CREATE TABLE IF NOT EXISTS "public"."support_ticket_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ticket_id" "uuid" NOT NULL,
    "author_profile_id" "uuid" NOT NULL,
    "author_role" "public"."user_role" NOT NULL,
    "body" "text" NOT NULL,
    "visibility" "text" DEFAULT 'requester'::"text" NOT NULL,
    "request_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "support_ticket_messages_body_not_blank" CHECK ((("length"(TRIM(BOTH FROM "body")) >= 1) AND ("length"(TRIM(BOTH FROM "body")) <= 4000))),
    CONSTRAINT "support_ticket_messages_visibility_valid" CHECK (("visibility" = ANY (ARRAY['requester'::"text", 'internal'::"text"])))
);


ALTER TABLE "public"."support_ticket_messages" OWNER TO "postgres";


COMMENT ON TABLE "public"."support_ticket_messages" IS 'Support thread only. Never use this table for participant-to-participant messaging.';



COMMENT ON COLUMN "public"."support_ticket_messages"."visibility" IS 'requester is visible to the ticket requester; internal is TES/Admin-only.';



CREATE OR REPLACE FUNCTION "public"."admin_add_support_ticket_note_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_body" "text") RETURNS "public"."support_ticket_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_body text;
  v_message public.support_ticket_messages%rowtype;
  v_existing public.support_ticket_messages%rowtype;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles where id = auth.uid() and role = 'admin'::public.user_role
  ) then
    raise exception 'authorized admin required' using errcode = '42501';
  end if;
  v_body := public.support_plain_text_v1(p_body, 1, 4000, 'note');
  if p_ticket_id is null or p_request_id is null then
    raise exception 'support note request is invalid' using errcode = '22023';
  end if;
  if not exists (select 1 from public.support_tickets where id = p_ticket_id) then
    raise exception 'support ticket not found' using errcode = 'P0002';
  end if;
  select * into v_existing from public.support_ticket_messages
  where ticket_id = p_ticket_id and author_profile_id = auth.uid() and request_id = p_request_id;
  if found then return v_existing; end if;

  insert into public.support_ticket_messages (ticket_id, author_profile_id, author_role, body, visibility, request_id)
  values (p_ticket_id, auth.uid(), 'admin'::public.user_role, v_body, 'internal', p_request_id)
  returning * into v_message;
  update public.support_tickets set last_activity_at = now() where id = p_ticket_id;
  perform public.record_admin_audit_event_v1(
    auth.uid(), 'admin', 'admin.support.manage', 'support.internal_note', 'support_ticket', p_ticket_id::text,
    '{}'::jsonb, jsonb_build_object('visibility', 'internal'), null, p_request_id::text, null, 'support_ticketing'
  );
  return v_message;
end;
$$;


ALTER FUNCTION "public"."admin_add_support_ticket_note_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assert_responsible_therapy_text_v1"("p_value" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_value ~* '(cura garantida|resultado garantido|diagn[oó]stico|tratamento m[eé]dico|transforma[cç][aã]o garantida)' then
    raise exception 'ADMIN_THERAPY_CATALOG_UNSAFE_COPY';
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_assert_responsible_therapy_text_v1"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assert_therapy_content_lengths_v1"("p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_benefit jsonb;
begin
  if char_length(coalesce(p_payload->>'shortDescription', '')) > 100 then
    raise exception 'ADMIN_THERAPY_CATALOG_SHORT_DESCRIPTION_TOO_LONG';
  end if;
  if char_length(coalesce(p_payload->>'description', '')) > 200 then
    raise exception 'ADMIN_THERAPY_CATALOG_DESCRIPTION_TOO_LONG';
  end if;
  if char_length(coalesce(p_payload#>>'{publicContent,introduction}', '')) > 160 then
    raise exception 'ADMIN_THERAPY_CATALOG_INTRODUCTION_TOO_LONG';
  end if;
  if char_length(coalesce(p_payload#>>'{publicContent,complementaryDescription}', '')) > 200 then
    raise exception 'ADMIN_THERAPY_CATALOG_COMPLEMENTARY_DESCRIPTION_TOO_LONG';
  end if;
  if char_length(coalesce(p_payload#>>'{publicContent,safetyNote}', '')) > 150 then
    raise exception 'ADMIN_THERAPY_CATALOG_SAFETY_NOTE_TOO_LONG';
  end if;

  for v_benefit in
    select value
    from jsonb_array_elements(coalesce(p_payload->'benefits', '[]'::jsonb)) as items(value)
  loop
    if char_length(coalesce(v_benefit->>'description', '')) > 100 then
      raise exception 'ADMIN_THERAPY_CATALOG_BENEFIT_DESCRIPTION_TOO_LONG';
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."admin_assert_therapy_content_lengths_v1"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_audit_json_object_v1"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_value is null then '{}'::jsonb
    when jsonb_typeof(p_value) = 'object' then p_value
    else jsonb_build_object('value', p_value)
  end;
$$;


ALTER FUNCTION "public"."admin_audit_json_object_v1"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_decide_therapy_catalog_request_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_catalog_request_id" "uuid", "p_status" "text", "p_decision" "text", "p_related_therapy_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor public.profiles;
  v_old public.therapy_catalog_requests;
  v_next public.therapy_catalog_requests;
begin
  v_actor := public.admin_get_actor_profile_v1(p_actor_user_id);

  if p_status not in ('under_review', 'needs_information', 'approved', 'merged', 'rejected') then
    raise exception 'ADMIN_THERAPY_CATALOG_INVALID_REQUEST_STATUS';
  end if;

  select * into v_old
  from public.therapy_catalog_requests
  where id = p_catalog_request_id
  for update;

  if v_old.id is null then
    raise exception 'ADMIN_THERAPY_CATALOG_REQUEST_NOT_FOUND';
  end if;

  update public.therapy_catalog_requests
  set
    status = p_status,
    decision = nullif(p_decision, ''),
    related_therapy_id = p_related_therapy_id,
    decided_by_profile_id = case
      when p_status in ('approved', 'merged', 'rejected') then v_actor.id
      else decided_by_profile_id
    end,
    decided_at = case
      when p_status in ('approved', 'merged', 'rejected') then now()
      else decided_at
    end,
    updated_at = now()
  where id = p_catalog_request_id
  returning * into v_next;

  insert into public.therapy_catalog_events (
    actor_profile_id,
    actor_role,
    entity_type,
    entity_id,
    event_type,
    previous_state,
    next_state,
    reason,
    request_id
  )
  values (
    v_actor.id,
    v_actor.role,
    'therapy_catalog_request',
    p_catalog_request_id,
    'therapy_request_' || p_status,
    to_jsonb(v_old),
    to_jsonb(v_next),
    p_decision,
    p_request_id
  );

  return jsonb_build_object(
    'contractVersion', 1,
    'requestId', p_catalog_request_id,
    'catalog', public.admin_list_therapy_catalog_v1(p_actor_user_id)
  );
end;
$$;


ALTER FUNCTION "public"."admin_decide_therapy_catalog_request_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_catalog_request_id" "uuid", "p_status" "text", "p_decision" "text", "p_related_therapy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_decide_therapy_catalog_request_v2"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_catalog_request_id" "uuid", "p_status" "text", "p_decision" "text", "p_related_therapy_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.therapy_catalog_requests;
  v_result jsonb;
begin
  select * into v_request
  from public.therapy_catalog_requests
  where id = p_catalog_request_id
  for update;

  if v_request.id is null then
    raise exception 'ADMIN_THERAPY_CATALOG_REQUEST_NOT_FOUND';
  end if;

  v_result := public.admin_decide_therapy_catalog_request_v1(
    p_actor_user_id,
    p_request_id,
    p_catalog_request_id,
    p_status,
    p_decision,
    p_related_therapy_id
  );

  insert into public.notifications (
    profile_id,
    kind,
    title,
    body,
    href
  )
  values (
    v_request.requester_profile_id,
    'therapy_catalog_request_updated',
    'Atualização da sua solicitação de terapia',
    case p_status
      when 'needs_information' then 'Nossa equipe precisa de mais informações para continuar a análise.'
      when 'approved' then 'Sua solicitação foi aprovada para a próxima etapa administrativa.'
      when 'merged' then 'Sua solicitação foi vinculada a uma terapia já existente.'
      when 'rejected' then 'A análise da sua solicitação foi concluída.'
      else 'Sua solicitação está em análise pela equipe da plataforma.'
    end,
    '/terapeuta/mensagens/solicitar-terapia?request=' || p_catalog_request_id::text
  );

  return v_result || jsonb_build_object(
    'requesterUserId', v_request.requester_profile_id,
    'requestStatus', p_status,
    'requestName', v_request.informed_name
  );
end;
$$;


ALTER FUNCTION "public"."admin_decide_therapy_catalog_request_v2"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_catalog_request_id" "uuid", "p_status" "text", "p_decision" "text", "p_related_therapy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_execute_operation_command_v1"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_action like 'professional.%' or p_action like 'verification.%' then
    return public.admin_execute_professional_lifecycle_command_v1(p_action,p_entity_id,p_reason,p_request_id,p_payload,p_correlation_id);
  end if;
  return public.admin_execute_operation_command_v1_internal(p_action,p_entity_id,p_reason,p_request_id,p_payload,p_correlation_id);
end; $$;


ALTER FUNCTION "public"."admin_execute_operation_command_v1"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_execute_operation_command_v1"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") IS 'Executes allowlisted admin operation commands and advances submitted verifications through in_review before an audited decision.';



CREATE OR REPLACE FUNCTION "public"."admin_execute_operation_command_v1_internal"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_audit_id uuid;
  v_entity_type text;
  v_next jsonb;
  v_permission text;
  v_previous jsonb;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_request_id text := nullif(btrim(coalesce(p_request_id, '')), '');
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if p_entity_id is null then
    raise exception 'admin command entity id required'
      using errcode = '22023';
  end if;

  if v_reason is null or length(v_reason) < 8 then
    raise exception 'admin command reason must have at least 8 characters'
      using errcode = '22023';
  end if;

  if v_request_id is null then
    raise exception 'admin command request_id required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  case p_action
    when 'professional.suspend' then
      v_entity_type := 'therapist_profile';
      v_permission := 'admin.professionals.suspend';

      select jsonb_build_object(
        'id', therapist_profiles.id,
        'status', therapist_profiles.status,
        'is_public', therapist_profiles.is_public,
        'is_accepting_bookings', therapist_profiles.is_accepting_bookings
      )
      into v_previous
      from public.therapist_profiles
      where therapist_profiles.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.therapist_profiles
      set
        status = 'suspended'::public.therapist_status,
        is_public = false,
        is_accepting_bookings = false,
        metadata = jsonb_set(
          jsonb_set(
            coalesce(metadata, '{}'::jsonb),
            '{adminSuspensionReason}',
            to_jsonb(v_reason),
            true
          ),
          '{adminSuspendedAt}',
          to_jsonb(now()),
          true
        ),
        updated_at = now()
      where id = p_entity_id;

      select jsonb_build_object(
        'id', therapist_profiles.id,
        'status', therapist_profiles.status,
        'is_public', therapist_profiles.is_public,
        'is_accepting_bookings', therapist_profiles.is_accepting_bookings
      )
      into v_next
      from public.therapist_profiles
      where therapist_profiles.id = p_entity_id;

    when 'professional.reactivate' then
      v_entity_type := 'therapist_profile';
      v_permission := 'admin.professionals.suspend';

      select jsonb_build_object(
        'id', therapist_profiles.id,
        'status', therapist_profiles.status,
        'is_public', therapist_profiles.is_public,
        'is_accepting_bookings', therapist_profiles.is_accepting_bookings
      )
      into v_previous
      from public.therapist_profiles
      where therapist_profiles.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.therapist_profiles
      set
        status = 'approved'::public.therapist_status,
        metadata = jsonb_set(
          coalesce(metadata, '{}'::jsonb),
          '{adminReactivatedAt}',
          to_jsonb(now()),
          true
        ),
        updated_at = now()
      where id = p_entity_id
        and status = 'suspended'::public.therapist_status;

      select jsonb_build_object(
        'id', therapist_profiles.id,
        'status', therapist_profiles.status,
        'is_public', therapist_profiles.is_public,
        'is_accepting_bookings', therapist_profiles.is_accepting_bookings
      )
      into v_next
      from public.therapist_profiles
      where therapist_profiles.id = p_entity_id;

    when 'verification.approve' then
      v_entity_type := 'therapist_verification';
      v_permission := 'admin.professionals.verify';

      select jsonb_build_object(
        'id', therapist_verifications.id,
        'status', therapist_verifications.status,
        'therapist_profile_id', therapist_verifications.therapist_profile_id
      )
      into v_previous
      from public.therapist_verifications
      where therapist_verifications.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.therapist_verifications
      set
        status = 'approved'::public.therapist_status,
        reviewed_by = v_actor_id,
        reviewed_at = now(),
        changes_requested = null,
        rejection_reason = null,
        updated_at = now()
      where id = p_entity_id;

      update public.therapist_profiles
      set status = 'approved'::public.therapist_status,
          updated_at = now()
      where id = (v_previous ->> 'therapist_profile_id')::uuid
        and status <> 'suspended'::public.therapist_status;

      select jsonb_build_object(
        'id', therapist_verifications.id,
        'status', therapist_verifications.status,
        'therapist_profile_id', therapist_verifications.therapist_profile_id
      )
      into v_next
      from public.therapist_verifications
      where therapist_verifications.id = p_entity_id;

    when 'verification.reject' then
      v_entity_type := 'therapist_verification';
      v_permission := 'admin.professionals.verify';

      select jsonb_build_object(
        'id', therapist_verifications.id,
        'status', therapist_verifications.status,
        'therapist_profile_id', therapist_verifications.therapist_profile_id
      )
      into v_previous
      from public.therapist_verifications
      where therapist_verifications.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.therapist_verifications
      set
        status = 'rejected'::public.therapist_status,
        reviewed_by = v_actor_id,
        reviewed_at = now(),
        rejection_reason = v_reason,
        updated_at = now()
      where id = p_entity_id;

      update public.therapist_profiles
      set status = 'rejected'::public.therapist_status,
          is_public = false,
          is_accepting_bookings = false,
          updated_at = now()
      where id = (v_previous ->> 'therapist_profile_id')::uuid
        and status <> 'suspended'::public.therapist_status;

      select jsonb_build_object(
        'id', therapist_verifications.id,
        'status', therapist_verifications.status,
        'therapist_profile_id', therapist_verifications.therapist_profile_id
      )
      into v_next
      from public.therapist_verifications
      where therapist_verifications.id = p_entity_id;

    when 'verification.request_changes' then
      v_entity_type := 'therapist_verification';
      v_permission := 'admin.professionals.verify';

      select jsonb_build_object(
        'id', therapist_verifications.id,
        'status', therapist_verifications.status,
        'therapist_profile_id', therapist_verifications.therapist_profile_id
      )
      into v_previous
      from public.therapist_verifications
      where therapist_verifications.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.therapist_verifications
      set
        status = 'changes_requested'::public.therapist_status,
        reviewed_by = v_actor_id,
        reviewed_at = now(),
        changes_requested = v_reason,
        updated_at = now()
      where id = p_entity_id;

      update public.therapist_profiles
      set status = 'changes_requested'::public.therapist_status,
          is_public = false,
          is_accepting_bookings = false,
          updated_at = now()
      where id = (v_previous ->> 'therapist_profile_id')::uuid
        and status <> 'suspended'::public.therapist_status;

      select jsonb_build_object(
        'id', therapist_verifications.id,
        'status', therapist_verifications.status,
        'therapist_profile_id', therapist_verifications.therapist_profile_id
      )
      into v_next
      from public.therapist_verifications
      where therapist_verifications.id = p_entity_id;

    when 'support.resolve' then
      v_entity_type := 'support_ticket';
      v_permission := 'admin.support.manage';

      select jsonb_build_object(
        'id', support_tickets.id,
        'status', support_tickets.status,
        'priority', support_tickets.priority,
        'urgency', support_tickets.urgency
      )
      into v_previous
      from public.support_tickets
      where support_tickets.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.support_tickets
      set
        status = 'resolved',
        resolution_summary = v_reason,
        reviewed_at = now(),
        updated_at = now()
      where id = p_entity_id;

      select jsonb_build_object(
        'id', support_tickets.id,
        'status', support_tickets.status,
        'priority', support_tickets.priority,
        'urgency', support_tickets.urgency
      )
      into v_next
      from public.support_tickets
      where support_tickets.id = p_entity_id;

    when 'support.reopen' then
      v_entity_type := 'support_ticket';
      v_permission := 'admin.support.manage';

      select jsonb_build_object(
        'id', support_tickets.id,
        'status', support_tickets.status,
        'priority', support_tickets.priority,
        'urgency', support_tickets.urgency
      )
      into v_previous
      from public.support_tickets
      where support_tickets.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.support_tickets
      set
        status = 'open',
        reviewed_at = null,
        updated_at = now()
      where id = p_entity_id;

      select jsonb_build_object(
        'id', support_tickets.id,
        'status', support_tickets.status,
        'priority', support_tickets.priority,
        'urgency', support_tickets.urgency
      )
      into v_next
      from public.support_tickets
      where support_tickets.id = p_entity_id;

    when 'review.hide' then
      v_entity_type := 'review';
      v_permission := 'admin.reviews.moderate';

      select jsonb_build_object(
        'id', reviews.id,
        'status', reviews.status,
        'published_at', reviews.published_at
      )
      into v_previous
      from public.reviews
      where reviews.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.reviews
      set
        status = 'hidden'::public.review_status,
        moderation_reason = v_reason,
        updated_at = now()
      where id = p_entity_id;

      select jsonb_build_object(
        'id', reviews.id,
        'status', reviews.status,
        'published_at', reviews.published_at
      )
      into v_next
      from public.reviews
      where reviews.id = p_entity_id;

    when 'review.restore' then
      v_entity_type := 'review';
      v_permission := 'admin.reviews.moderate';

      select jsonb_build_object(
        'id', reviews.id,
        'status', reviews.status,
        'published_at', reviews.published_at
      )
      into v_previous
      from public.reviews
      where reviews.id = p_entity_id
      for update;

      if v_previous is null then
        raise exception 'admin command target not found'
          using errcode = 'P0002';
      end if;

      update public.reviews
      set
        status = 'published'::public.review_status,
        published_at = coalesce(published_at, now()),
        updated_at = now()
      where id = p_entity_id;

      select jsonb_build_object(
        'id', reviews.id,
        'status', reviews.status,
        'published_at', reviews.published_at
      )
      into v_next
      from public.reviews
      where reviews.id = p_entity_id;

    else
      raise exception 'unsupported admin operation command: %', p_action
        using errcode = '22023';
  end case;

  v_audit_id := public.record_admin_audit_event_v1(
    v_actor_id,
    'admin',
    v_permission,
    p_action,
    v_entity_type,
    p_entity_id::text,
    coalesce(v_previous, '{}'::jsonb),
    coalesce(v_next, '{}'::jsonb),
    v_reason,
    v_request_id,
    p_correlation_id,
    'admin-operation-command'
  );

  return jsonb_build_object(
    'auditEventId', v_audit_id,
    'entityId', p_entity_id,
    'entityType', v_entity_type,
    'nextState', coalesce(v_next, '{}'::jsonb),
    'ok', true,
    'permission', v_permission,
    'previousState', coalesce(v_previous, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_execute_operation_command_v1_internal"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_execute_operation_command_v1_internal"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") IS 'Internal implementation for admin operation commands. Callable only through the guarded public wrapper.';



CREATE OR REPLACE FUNCTION "public"."admin_execute_operation_command_v2"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_verification public.therapist_verifications%rowtype;
begin
  if p_action in ('support.resolve', 'support.reopen') then
    if p_request_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'support management request is invalid' using errcode = '22023';
    end if;
    return public.admin_manage_support_ticket_v1(
      p_entity_id,
      p_request_id::uuid,
      case when p_action = 'support.resolve' then 'resolve' else 'reopen' end,
      null
    );
  end if;

  if p_action like 'professional.%' or p_action like 'verification.%' then
    if p_action = 'verification.pause_review' then
      select * into v_verification
      from public.therapist_verifications
      where id = p_entity_id
      for update;

      if found and v_verification.status = 'submitted'::public.therapist_status then
        update public.therapist_verifications
        set status = 'in_review'::public.therapist_status,
            reviewed_at = coalesce(reviewed_at, now()),
            updated_at = now()
        where id = p_entity_id;

        update public.therapist_profiles
        set status = 'in_review'::public.therapist_status,
            updated_at = now()
        where id = v_verification.therapist_profile_id
          and status <> 'suspended'::public.therapist_status;
      end if;
    end if;

    return public.admin_execute_professional_lifecycle_command_v1(
      p_action,
      p_entity_id,
      p_reason,
      p_request_id,
      p_payload,
      p_correlation_id
    );
  end if;

  return public.admin_execute_operation_command_v2_internal(
    p_action,
    p_entity_id,
    p_reason,
    p_request_id,
    p_payload,
    p_correlation_id
  );
end;
$_$;


ALTER FUNCTION "public"."admin_execute_operation_command_v2"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_execute_operation_command_v2"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") IS 'Extends guarded admin operation commands and advances submitted verifications through in_review before pausing for changes.';



CREATE OR REPLACE FUNCTION "public"."admin_execute_operation_command_v2_internal"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_audit_id uuid;
  v_next jsonb;
  v_previous jsonb;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_request_id text := nullif(btrim(coalesce(p_request_id, '')), '');
begin
  if p_action not in ('verification.pause_review', 'verification.reopen_review') then
    return public.admin_execute_operation_command_v1(
      p_action,
      p_entity_id,
      p_reason,
      p_request_id,
      p_payload,
      p_correlation_id
    );
  end if;

  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if p_entity_id is null then
    raise exception 'admin command entity id required'
      using errcode = '22023';
  end if;

  if v_reason is null or length(v_reason) < 8 then
    raise exception 'admin command reason must have at least 8 characters'
      using errcode = '22023';
  end if;

  if v_request_id is null then
    raise exception 'admin command request_id required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  select jsonb_build_object(
    'id', therapist_verifications.id,
    'status', therapist_verifications.status,
    'therapist_profile_id', therapist_verifications.therapist_profile_id
  )
  into v_previous
  from public.therapist_verifications
  where therapist_verifications.id = p_entity_id
  for update;

  if v_previous is null then
    raise exception 'admin command target not found'
      using errcode = 'P0002';
  end if;

  if p_action = 'verification.pause_review' then
    update public.therapist_verifications
    set
      status = 'changes_requested'::public.therapist_status,
      reviewed_by = v_actor_id,
      reviewed_at = now(),
      changes_requested = v_reason,
      updated_at = now()
    where id = p_entity_id;

    update public.therapist_profiles
    set
      status = 'changes_requested'::public.therapist_status,
      is_public = false,
      is_accepting_bookings = false,
      updated_at = now()
    where id = (v_previous ->> 'therapist_profile_id')::uuid
      and status <> 'suspended'::public.therapist_status;
  else
    update public.therapist_verifications
    set
      status = 'in_review'::public.therapist_status,
      reviewed_by = v_actor_id,
      reviewed_at = now(),
      updated_at = now()
    where id = p_entity_id
      and status in (
        'submitted'::public.therapist_status,
        'changes_requested'::public.therapist_status,
        'rejected'::public.therapist_status
      );

    update public.therapist_profiles
    set
      status = 'in_review'::public.therapist_status,
      updated_at = now()
    where id = (v_previous ->> 'therapist_profile_id')::uuid
      and status <> 'suspended'::public.therapist_status;
  end if;

  select jsonb_build_object(
    'id', therapist_verifications.id,
    'status', therapist_verifications.status,
    'therapist_profile_id', therapist_verifications.therapist_profile_id
  )
  into v_next
  from public.therapist_verifications
  where therapist_verifications.id = p_entity_id;

  v_audit_id := public.record_admin_audit_event_v1(
    v_actor_id,
    'admin',
    'admin.professionals.verify',
    p_action,
    'therapist_verification',
    p_entity_id::text,
    coalesce(v_previous, '{}'::jsonb),
    coalesce(v_next, '{}'::jsonb),
    v_reason,
    v_request_id,
    p_correlation_id,
    'admin-operation-command'
  );

  return jsonb_build_object(
    'auditEventId', v_audit_id,
    'entityId', p_entity_id,
    'entityType', 'therapist_verification',
    'nextState', coalesce(v_next, '{}'::jsonb),
    'ok', true,
    'permission', 'admin.professionals.verify',
    'previousState', coalesce(v_previous, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_execute_operation_command_v2_internal"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_execute_operation_command_v2_internal"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") IS 'Internal implementation for v2 admin operation commands. Callable only through the guarded public wrapper.';



CREATE OR REPLACE FUNCTION "public"."admin_execute_professional_lifecycle_command_v1"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_audit_id uuid;
  v_entity_type text;
  v_permission text;
  v_previous jsonb;
  v_next jsonb;
  v_replay record;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_request_id text := nullif(btrim(coalesce(p_request_id, '')), '');
  v_verification public.therapist_verifications%rowtype;
  v_profile public.therapist_profiles%rowtype;
  v_eligibility jsonb;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required' using errcode = '42501';
  end if;
  if p_entity_id is null then
    raise exception 'admin command entity id required' using errcode = '22023';
  end if;
  if v_reason is null or length(v_reason) < 8 then
    raise exception 'admin command reason must have at least 8 characters' using errcode = '22023';
  end if;
  if v_request_id is null then
    raise exception 'admin command request_id required' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = v_actor_id
      and role = 'admin'::public.user_role
      and auth_deleted_at is null
      and anonymized_at is null
  ) then
    raise exception 'admin permission required' using errcode = '42501';
  end if;

  if p_action in ('professional.suspend', 'professional.reactivate', 'professional.publish') then
    v_entity_type := 'therapist_profile';
    v_permission := case
      when p_action = 'professional.publish' then 'admin.professionals.verify'
      else 'admin.professionals.suspend'
    end;
  elsif p_action in (
    'verification.approve', 'verification.reject', 'verification.request_changes',
    'verification.pause_review', 'verification.reopen_review'
  ) then
    v_entity_type := 'therapist_verification';
    v_permission := 'admin.professionals.verify';
  else
    raise exception 'unsupported professional lifecycle command: %', p_action using errcode = '22023';
  end if;

  select id, entity_id, previous_state, next_state into v_replay
  from public.admin_audit_events
  where source = 'admin-operation-command'
    and request_id = v_request_id
    and action = p_action
    and entity_type = v_entity_type
  limit 1;

  if found then
    if v_replay.entity_id <> p_entity_id::text then
      raise exception 'admin command request_id reused for a different target' using errcode = '22023';
    end if;
    return jsonb_build_object(
      'ok', true, 'idempotentReplay', true, 'auditEventId', v_replay.id,
      'entityId', p_entity_id, 'entityType', v_entity_type,
      'previousState', v_replay.previous_state, 'nextState', v_replay.next_state,
      'permission', v_permission
    );
  end if;

  if v_entity_type = 'therapist_profile' then
    select * into v_profile from public.therapist_profiles where id = p_entity_id for update;
    if not found then raise exception 'admin command target not found' using errcode = 'P0002'; end if;

    v_previous := jsonb_build_object(
      'id', v_profile.id, 'status', v_profile.status,
      'public_status', v_profile.public_status, 'is_public', v_profile.is_public,
      'is_accepting_bookings', v_profile.is_accepting_bookings
    );

    if p_action = 'professional.suspend' then
      update public.therapist_profiles
      set status = 'suspended', public_status = 'suspended', is_public = false,
          is_accepting_bookings = false,
          metadata = jsonb_set(jsonb_set(coalesce(metadata, '{}'::jsonb), '{adminSuspensionReason}', to_jsonb(v_reason), true), '{adminSuspendedAt}', to_jsonb(now()), true),
          updated_at = now()
      where id = p_entity_id
      returning * into v_profile;
    elsif p_action = 'professional.reactivate' then
      if v_profile.status <> 'suspended' then
        raise exception 'only suspended professionals can be reactivated' using errcode = '22023';
      end if;
      update public.therapist_profiles
      set status = 'approved', public_status = 'unpublished', is_public = false,
          is_accepting_bookings = false,
          metadata = jsonb_set(coalesce(metadata, '{}'::jsonb), '{adminReactivatedAt}', to_jsonb(now()), true),
          updated_at = now()
      where id = p_entity_id
      returning * into v_profile;
    else
      if v_profile.status <> 'approved' or v_profile.public_status = 'suspended' then
        raise exception 'only approved non-suspended professionals can be published' using errcode = '22023';
      end if;

      v_eligibility := public.get_therapist_publication_eligibility_v1(v_profile.id);
      if exists (
        select 1
        from jsonb_array_elements_text(coalesce(v_eligibility -> 'blockers', '[]'::jsonb)) as blocker(code)
        where blocker.code not in ('profile_not_published', 'profile_not_public', 'not_accepting_bookings')
      ) then
        raise exception 'profile does not meet the publication criteria' using errcode = '22023';
      end if;

      update public.therapist_profiles
      set public_status = 'published', is_public = true, is_accepting_bookings = true,
          updated_at = now()
      where id = p_entity_id
      returning * into v_profile;
    end if;

    v_eligibility := public.get_therapist_publication_eligibility_v1(v_profile.id);
    v_next := jsonb_build_object(
      'id', v_profile.id, 'status', v_profile.status,
      'public_status', v_profile.public_status, 'is_public', v_profile.is_public,
      'is_accepting_bookings', v_profile.is_accepting_bookings,
      'publicationEligibility', v_eligibility
    );
  else
    select * into v_verification from public.therapist_verifications where id = p_entity_id for update;
    if not found then raise exception 'admin command target not found' using errcode = 'P0002'; end if;
    select * into v_profile from public.therapist_profiles where id = v_verification.therapist_profile_id for update;

    v_previous := jsonb_build_object(
      'id', v_verification.id, 'status', v_verification.status,
      'therapist_profile_id', v_verification.therapist_profile_id,
      'profile_status', v_profile.status,
      'publicationEligibility', public.get_therapist_publication_eligibility_v1(v_profile.id)
    );

    if p_action = 'verification.reopen_review' then
      if v_verification.status not in ('submitted', 'changes_requested', 'rejected') then
        raise exception 'verification cannot enter review from its current status' using errcode = '22023';
      end if;
      update public.therapist_verifications
      set status = 'in_review', reviewed_by = v_actor_id,
          reviewed_at = coalesce(reviewed_at, now()), updated_at = now()
      where id = p_entity_id returning * into v_verification;
      update public.therapist_profiles set status = 'in_review', updated_at = now()
      where id = v_profile.id and status <> 'suspended' returning * into v_profile;
    elsif p_action in ('verification.request_changes', 'verification.pause_review') then
      if v_verification.status <> 'in_review' then
        raise exception 'verification must be in review before requesting changes' using errcode = '22023';
      end if;
      update public.therapist_verifications
      set status = 'changes_requested', reviewed_by = v_actor_id, reviewed_at = now(),
          changes_requested = v_reason, updated_at = now()
      where id = p_entity_id returning * into v_verification;
      update public.therapist_profiles
      set status = 'changes_requested', public_status = 'unpublished', is_public = false,
          is_accepting_bookings = false, updated_at = now()
      where id = v_profile.id and status <> 'suspended' returning * into v_profile;
    elsif p_action = 'verification.approve' then
      if v_verification.status <> 'in_review' then
        raise exception 'verification must be in review before approval' using errcode = '22023';
      end if;
      update public.therapist_verifications
      set status = 'approved', reviewed_by = v_actor_id, reviewed_at = now(),
          changes_requested = null, rejection_reason = null, updated_at = now()
      where id = p_entity_id returning * into v_verification;
      update public.therapist_profiles set status = 'approved', updated_at = now()
      where id = v_profile.id and status <> 'suspended' returning * into v_profile;
    else
      if v_verification.status <> 'in_review' then
        raise exception 'verification must be in review before rejection' using errcode = '22023';
      end if;
      update public.therapist_verifications
      set status = 'rejected', reviewed_by = v_actor_id, reviewed_at = now(),
          rejection_reason = v_reason, updated_at = now()
      where id = p_entity_id returning * into v_verification;
      update public.therapist_profiles
      set status = 'rejected', public_status = 'unpublished', is_public = false,
          is_accepting_bookings = false, updated_at = now()
      where id = v_profile.id and status <> 'suspended' returning * into v_profile;
    end if;

    v_eligibility := public.get_therapist_publication_eligibility_v1(v_profile.id);
    v_next := jsonb_build_object(
      'id', v_verification.id, 'status', v_verification.status,
      'therapist_profile_id', v_verification.therapist_profile_id,
      'profile_status', v_profile.status, 'publicationEligibility', v_eligibility
    );
  end if;

  v_audit_id := public.record_admin_audit_event_v1(
    v_actor_id, 'admin', v_permission, p_action, v_entity_type, p_entity_id::text,
    v_previous, v_next, v_reason, v_request_id, p_correlation_id,
    'admin-operation-command'
  );

  return jsonb_build_object(
    'ok', true, 'idempotentReplay', false, 'auditEventId', v_audit_id,
    'entityId', p_entity_id, 'entityType', v_entity_type,
    'previousState', v_previous, 'nextState', v_next, 'permission', v_permission
  );
end;
$$;


ALTER FUNCTION "public"."admin_execute_professional_lifecycle_command_v1"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_execute_professional_lifecycle_command_v1"("p_action" "text", "p_entity_id" "uuid", "p_reason" "text", "p_request_id" "text", "p_payload" "jsonb", "p_correlation_id" "text") IS 'Audited professional lifecycle commands including conditional administrative publication. Publication never bypasses the authoritative eligibility prerequisites.';



CREATE OR REPLACE FUNCTION "public"."admin_filter_jsonb_read_model_rows_v1"("p_rows" "jsonb", "p_search" "text", "p_status" "text", "p_sort" "text", "p_page" integer, "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with source_rows as (
    select value as row_payload
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) as source(value)
  ),
  filtered_rows as (
    select row_payload
    from source_rows
    where (
        nullif(btrim(coalesce(p_search, '')), '') is null
        or lower(row_payload::text) like
          '%' || lower(nullif(btrim(coalesce(p_search, '')), '')) || '%'
      )
      and (
        nullif(btrim(coalesce(p_status, '')), '') is null
        or row_payload ->> 'status' = nullif(btrim(coalesce(p_status, '')), '')
        or row_payload ->> 'account_status' =
          nullif(btrim(coalesce(p_status, '')), '')
        or row_payload ->> 'financial_status' =
          nullif(btrim(coalesce(p_status, '')), '')
      )
  ),
  numbered_rows as (
    select
      row_payload,
      count(*) over ()::integer as total,
      row_number() over (
        order by
          case
            when coalesce(p_sort, 'recent') = 'name' then lower(coalesce(
              row_payload ->> 'public_name',
              row_payload ->> 'display_name',
              row_payload ->> 'therapist_name',
              row_payload ->> 'subject',
              row_payload ->> 'service_title',
              row_payload ->> 'plan_name',
              ''
            ))
          end asc nulls last,
          case
            when coalesce(p_sort, 'recent') = 'status' then lower(coalesce(
              row_payload ->> 'status',
              row_payload ->> 'account_status',
              row_payload ->> 'financial_status',
              ''
            ))
          end asc nulls last,
          case
            when coalesce(p_sort, 'recent') = 'amount' then
              nullif(row_payload ->> 'gross_amount_cents', '')::integer
          end desc nulls last,
          case
            when coalesce(p_sort, 'recent') = 'oldest' then coalesce(
              row_payload ->> 'created_at',
              row_payload ->> 'submitted_at',
              row_payload ->> 'starts_at',
              row_payload ->> 'updated_at',
              ''
            )
          end asc nulls last,
          coalesce(
            row_payload ->> 'updated_at',
            row_payload ->> 'created_at',
            row_payload ->> 'submitted_at',
            row_payload ->> 'starts_at',
            ''
          ) desc nulls last
      )::integer as row_number
    from filtered_rows
  ),
  page_rows as (
    select row_payload, row_number, total
    from numbered_rows
    where row_number > greatest((p_page - 1) * p_page_size, 0)
      and row_number <= greatest((p_page - 1) * p_page_size, 0) + p_page_size
  )
  select jsonb_build_object(
    'rows', coalesce(
      jsonb_agg(page_rows.row_payload order by page_rows.row_number),
      '[]'::jsonb
    ),
    'total', coalesce(max(page_rows.total), (select count(*)::integer from filtered_rows))
  )
  from page_rows;
$$;


ALTER FUNCTION "public"."admin_filter_jsonb_read_model_rows_v1"("p_rows" "jsonb", "p_search" "text", "p_status" "text", "p_sort" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "role" "public"."user_role" DEFAULT 'patient'::"public"."user_role" NOT NULL,
    "display_name" "text",
    "email" "text",
    "phone" "text",
    "avatar_url" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "email_confirmed_at" timestamp with time zone,
    "auth_deleted_at" timestamp with time zone,
    "anonymized_at" timestamp with time zone,
    "deletion_source" "text",
    "phone_country_code" "text",
    CONSTRAINT "profiles_phone_country_code_format" CHECK ((("phone_country_code" IS NULL) OR ("phone_country_code" ~ '^[1-9][0-9]{0,2}$'::"text")))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON COLUMN "public"."profiles"."email_confirmed_at" IS 'Transactional mirror of Supabase Auth email confirmation used by server-side auth flows and polling. Supabase Auth remains authoritative.';



COMMENT ON COLUMN "public"."profiles"."auth_deleted_at" IS 'Timestamp mirrored when the corresponding Supabase Auth user is deleted.';



COMMENT ON COLUMN "public"."profiles"."anonymized_at" IS 'Timestamp when direct profile PII was minimized after account deletion.';



COMMENT ON COLUMN "public"."profiles"."deletion_source" IS 'Deletion source for account removal workflows. Expected value for Authentication panel deletion: supabase_auth.';



CREATE OR REPLACE FUNCTION "public"."admin_get_actor_profile_v1"("p_actor_user_id" "uuid") RETURNS "public"."profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.profiles;
begin
  select *
  into v_profile
  from public.profiles
  where id = p_actor_user_id
    and role = 'admin';

  if v_profile.id is null then
    raise exception 'ADMIN_THERAPY_CATALOG_ADMIN_REQUIRED';
  end if;

  return v_profile;
end;
$$;


ALTER FUNCTION "public"."admin_get_actor_profile_v1"("p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_dashboard_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_metrics jsonb;
  v_events jsonb;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  select jsonb_build_object(
    'published-therapies', (
      select count(*)::integer
      from public.therapies
      where therapies.status::text in ('active', 'published')
        and therapies.is_public_visible is true
    ),
    'draft-therapies', (
      select count(*)::integer
      from public.therapies
      where therapies.status::text in ('draft', 'inactive')
        or therapies.is_public_visible is false
    ),
    'matching-visible-therapies', (
      select count(*)::integer
      from public.therapies
      join public.matching_therapy_settings
        on matching_therapy_settings.therapy_id = therapies.id
      where therapies.status::text in ('active', 'published')
        and therapies.is_public_visible is true
        and matching_therapy_settings.is_visible_in_matching is true
    ),
    'pending-therapy-requests', (
      select count(*)::integer
      from public.therapy_catalog_requests
      where therapy_catalog_requests.status in (
        'submitted',
        'under_review',
        'needs_information'
      )
    ),
    'active-therapists', (
      select count(*)::integer
      from public.therapist_profiles
      where therapist_profiles.status::text = 'approved'
    ),
    'pending-therapists', (
      select count(*)::integer
      from public.therapist_profiles
      where therapist_profiles.status::text in (
        'draft',
        'submitted',
        'in_review'
      )
    ),
    'active-patients', (
      select count(*)::integer
      from public.patient_profiles
    ),
    'future-sessions', (
      select count(*)::integer
      from public.bookings
      where bookings.starts_at >= now()
    ),
    'attention-sessions', (
      select count(*)::integer
      from public.bookings
      where bookings.status::text in (
        'pending_payment',
        'no_show_patient',
        'no_show_therapist',
        'refunded'
      )
    ),
    'open-support-tickets', (
      select count(*)::integer
      from public.support_tickets
      where support_tickets.status = 'open'
    ),
    'pending-session-payments', (
      select count(*)::integer
      from public.session_payments
      where session_payments.financial_status::text in (
        'pending',
        'processing'
      )
    ),
    'paid-session-payments', (
      select count(*)::integer
      from public.session_payments
      where session_payments.financial_status::text in (
        'paid',
        'partially_refunded'
      )
    ),
    'pending-refunds', (
      select count(*)::integer
      from public.session_refunds
      where session_refunds.status = 'pending'
    ),
    'open-disputes', (
      select count(*)::integer
      from public.session_disputes
      where session_disputes.closed_at is null
    ),
    'open-payout-batches', (
      select count(*)::integer
      from public.payout_batches
      where payout_batches.status::text in (
        'draft',
        'open',
        'processing',
        'partially_failed'
      )
    ),
    'active-subscriptions', (
      select count(*)::integer
      from public.therapist_subscriptions
      where therapist_subscriptions.status::text in ('trialing', 'active')
    ),
    'attention-subscriptions', (
      select count(*)::integer
      from public.therapist_subscriptions
      where therapist_subscriptions.status::text in (
        'past_due',
        'unpaid',
        'incomplete'
      )
    ),
    'failed-webhooks', (
      select count(*)::integer
      from public.stripe_webhook_events
      where stripe_webhook_events.processing_status::text = 'failed'
    ),
    'failed-zoom-webhooks', (
      select count(*)::integer
      from public.zoom_video_webhook_events
      where zoom_video_webhook_events.processing_status::text = 'failed'
    ),
    'failed-video-sessions', (
      select count(*)::integer
      from public.video_sessions
      where video_sessions.status::text = 'failed'
    ),
    'failed-emails', (
      select count(*)::integer
      from public.email_delivery_logs
      where email_delivery_logs.status::text = 'error'
    ),
    'restricted-connect-accounts', (
      select count(*)::integer
      from public.therapist_connect_accounts
      where therapist_connect_accounts.operational_status <> 'active'
    )
  )
  into v_metrics;

  select coalesce(jsonb_agg(event_payload order by created_at desc), '[]'::jsonb)
  into v_events
  from (
    select
      admin_audit_events.created_at,
      jsonb_build_object(
        'id', admin_audit_events.id,
        'actorRole', admin_audit_events.actor_role,
        'entityType', admin_audit_events.entity_type,
        'eventType', admin_audit_events.action,
        'reason', admin_audit_events.reason,
        'createdAt', admin_audit_events.created_at
      ) as event_payload
    from public.admin_audit_events
    order by admin_audit_events.created_at desc
    limit 6
  ) events;

  return jsonb_build_object(
    'generatedAt', now(),
    'metrics', v_metrics,
    'events', v_events
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_dashboard_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_dashboard_v1"() IS 'Sanitized admin-only dashboard read model. Returns aggregate operational, catalog, finance and integration counts plus safe audit event summaries.';



CREATE OR REPLACE FUNCTION "public"."admin_get_finance_detail_v1"("p_module" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payload jsonb;
  v_projection jsonb;
begin
  v_payload := public.private_admin_get_finance_detail_v1_v9_legacy(
    p_module,
    p_id
  );

  if p_module <> 'payments' or v_payload -> 'record' = 'null'::jsonb then
    return v_payload;
  end if;

  v_projection := coalesce(
    public.private_admin_session_payout_projection_v10(p_id),
    '{}'::jsonb
  );

  return jsonb_set(
    v_payload,
    '{record}',
    coalesce(v_payload -> 'record', '{}'::jsonb) || v_projection,
    true
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_finance_detail_v1"("p_module" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_finance_detail_v1"("p_module" "text", "p_id" "uuid") IS 'Admin finance detail with sanitized V10 bank, compensation and reconciliation projection.';



CREATE OR REPLACE FUNCTION "public"."admin_get_finance_module_v1"("p_module" "text", "p_limit" integer DEFAULT 12, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit, 12), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_metrics jsonb;
  v_rows jsonb;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  case p_module
    when 'payments' then
      select jsonb_build_object(
        'pending-session-payments', count(*) filter (
          where session_payments.financial_status in (
            'pending'::public.session_financial_status,
            'processing'::public.session_financial_status
          )
        )::integer,
        'paid-session-payments', count(*) filter (
          where session_payments.financial_status in (
            'paid'::public.session_financial_status,
            'partially_refunded'::public.session_financial_status
          )
        )::integer,
        'failed-session-payments', count(*) filter (
          where session_payments.financial_status in (
            'failed'::public.session_financial_status,
            'canceled'::public.session_financial_status
          )
        )::integer,
        'pending-refunds', (
          select count(*)::integer
          from public.session_refunds
          where session_refunds.status = 'pending'
        ),
        'open-disputes', (
          select count(*)::integer
          from public.session_disputes
          where session_disputes.closed_at is null
        ),
        'open-payout-batches', (
          select count(*)::integer
          from public.payout_batches
          where payout_batches.status in (
            'draft'::public.payout_batch_status,
            'open'::public.payout_batch_status,
            'processing'::public.payout_batch_status,
            'partially_failed'::public.payout_batch_status
          )
        ),
        'ledger-entries', (
          select count(*)::integer
          from public.financial_ledger_entries
        ),
        'stripe-transfers', (
          select count(*)::integer
          from public.stripe_transfers
        )
      )
      into v_metrics
      from public.session_payments;

      select coalesce(jsonb_agg(row_payload order by updated_at desc), '[]'::jsonb)
      into v_rows
      from (
        select
          session_payments.updated_at,
          jsonb_build_object(
            'id', session_payments.id,
            'booking_id', session_payments.booking_id,
            'therapist_profile_id', session_payments.therapist_profile_id,
            'therapist_name', therapist_profiles.public_name,
            'patient_profile_id', session_payments.patient_profile_id,
            'patient_name', patient_profiles.display_name,
            'service_title', bookings.service_title_snapshot,
            'starts_at', bookings.starts_at,
            'financial_status', session_payments.financial_status,
            'service_status', session_payments.service_status,
            'transfer_status', session_payments.transfer_status,
            'gross_amount_cents', session_payments.gross_amount_cents,
            'therapist_amount_cents', session_payments.therapist_amount_cents,
            'platform_gross_commission_cents',
              session_payments.platform_gross_commission_cents,
            'currency', session_payments.currency,
            'refund_pending', session_payments.refund_pending,
            'refund_count', coalesce(refund_summary.refund_count, 0),
            'refunded_amount_cents',
              coalesce(refund_summary.refunded_amount_cents, 0),
            'dispute_count', coalesce(dispute_summary.dispute_count, 0),
            'transfer_count', coalesce(transfer_summary.transfer_count, 0),
            'latest_transfer_status', transfer_summary.latest_transfer_status,
            'ledger_entry_count', coalesce(ledger_summary.ledger_entry_count, 0),
            'disputed_at', session_payments.disputed_at,
            'paid_at', session_payments.paid_at,
            'created_at', session_payments.created_at,
            'updated_at', session_payments.updated_at
          ) as row_payload
        from public.session_payments
        left join public.bookings
          on bookings.id = session_payments.booking_id
        left join public.therapist_profiles
          on therapist_profiles.id = session_payments.therapist_profile_id
        left join public.patient_profiles
          on patient_profiles.id = session_payments.patient_profile_id
        left join lateral (
          select
            count(*)::integer as refund_count,
            coalesce(sum(session_refunds.amount_cents), 0)::integer
              as refunded_amount_cents
          from public.session_refunds
          where session_refunds.session_payment_id = session_payments.id
        ) refund_summary on true
        left join lateral (
          select count(*)::integer as dispute_count
          from public.session_disputes
          where session_disputes.session_payment_id = session_payments.id
        ) dispute_summary on true
        left join lateral (
          select
            count(*)::integer as transfer_count,
            (
              array_agg(stripe_transfers.status order by stripe_transfers.created_at desc)
            )[1] as latest_transfer_status
          from public.stripe_transfers
          where stripe_transfers.session_payment_id = session_payments.id
        ) transfer_summary on true
        left join lateral (
          select count(*)::integer as ledger_entry_count
          from public.financial_ledger_entries
          where financial_ledger_entries.session_payment_id = session_payments.id
        ) ledger_summary on true
        order by session_payments.updated_at desc
        limit v_limit offset v_offset
      ) rows;

    when 'subscriptions' then
      select jsonb_build_object(
        'active-subscriptions', count(*) filter (
          where therapist_subscriptions.status in (
            'trialing'::public.billing_subscription_status,
            'active'::public.billing_subscription_status
          )
        )::integer,
        'attention-subscriptions', count(*) filter (
          where therapist_subscriptions.status in (
            'past_due'::public.billing_subscription_status,
            'unpaid'::public.billing_subscription_status,
            'incomplete'::public.billing_subscription_status
          )
        )::integer,
        'ending-subscriptions', count(*) filter (
          where therapist_subscriptions.cancel_at_period_end is true
        )::integer,
        'failed-invoices', (
          select count(*)::integer
          from public.billing_invoices
          where billing_invoices.status in ('open', 'uncollectible', 'void')
        ),
        'active-prices', (
          select count(*)::integer
          from public.billing_plan_prices
          where billing_plan_prices.is_active is true
        ),
        'stripe-customers', (
          select count(*)::integer
          from public.stripe_customers
          where stripe_customers.role = 'therapist'::public.user_role
        )
      )
      into v_metrics
      from public.therapist_subscriptions;

      select coalesce(jsonb_agg(row_payload order by updated_at desc), '[]'::jsonb)
      into v_rows
      from (
        select
          therapist_subscriptions.updated_at,
          jsonb_build_object(
            'id', therapist_subscriptions.id,
            'therapist_profile_id',
              therapist_subscriptions.therapist_profile_id,
            'therapist_name', therapist_profiles.public_name,
            'therapist_current_plan', therapist_profiles.plan,
            'plan_code', therapist_subscriptions.plan_code,
            'plan_name', billing_plans.name,
            'status', therapist_subscriptions.status,
            'current_period_start',
              therapist_subscriptions.current_period_start,
            'current_period_end', therapist_subscriptions.current_period_end,
            'cancel_at_period_end',
              therapist_subscriptions.cancel_at_period_end,
            'canceled_at', therapist_subscriptions.canceled_at,
            'ended_at', therapist_subscriptions.ended_at,
            'unit_amount_cents', billing_plan_prices.unit_amount_cents,
            'currency', billing_plan_prices.currency,
            'interval', billing_plan_prices.interval,
            'customer_linked', stripe_customers.id is not null,
            'customer_environment', stripe_customers.environment,
            'customer_livemode', stripe_customers.livemode,
            'invoice_count', coalesce(invoice_summary.invoice_count, 0),
            'latest_invoice_status',
              invoice_summary.latest_invoice_status,
            'event_count', coalesce(event_summary.event_count, 0),
            'created_at', therapist_subscriptions.created_at,
            'updated_at', therapist_subscriptions.updated_at
          ) as row_payload
        from public.therapist_subscriptions
        left join public.therapist_profiles
          on therapist_profiles.id =
            therapist_subscriptions.therapist_profile_id
        left join public.billing_plans
          on billing_plans.id = therapist_subscriptions.billing_plan_id
        left join public.billing_plan_prices
          on billing_plan_prices.id =
            therapist_subscriptions.billing_plan_price_id
        left join public.stripe_customers
          on stripe_customers.id = therapist_subscriptions.stripe_customer_id
        left join lateral (
          select
            count(*)::integer as invoice_count,
            (
              array_agg(billing_invoices.status order by billing_invoices.created_at desc)
            )[1] as latest_invoice_status
          from public.billing_invoices
          where billing_invoices.therapist_subscription_id =
            therapist_subscriptions.id
        ) invoice_summary on true
        left join lateral (
          select count(*)::integer as event_count
          from public.therapist_subscription_events
          where therapist_subscription_events.therapist_subscription_id =
            therapist_subscriptions.id
        ) event_summary on true
        order by therapist_subscriptions.updated_at desc
        limit v_limit offset v_offset
      ) rows;

    else
      raise exception 'unsupported admin finance module: %', p_module
        using errcode = '22023';
  end case;

  return jsonb_build_object(
    'generatedAt', now(),
    'metrics', coalesce(v_metrics, '{}'::jsonb),
    'module', p_module,
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_finance_module_v1"("p_module" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_finance_module_v1"("p_module" "text", "p_limit" integer, "p_offset" integer) IS 'Minimized admin finance list read model. Validates auth.uid() as admin and never returns Stripe external object ids, raw metadata, invoice URLs or webhook payloads.';



CREATE OR REPLACE FUNCTION "public"."admin_get_finance_module_v2"("p_module" "text", "p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_payload jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_open_v9 integer := 0;
  v_open_v10 integer := 0;
begin
  v_payload := public.private_admin_get_finance_module_v2_v9_legacy(
    p_module,
    p_query
  );

  if p_module <> 'payments' then
    return v_payload;
  end if;

  select coalesce(jsonb_agg(
    row_payload
      || coalesce(public.private_admin_session_payout_projection_v10(
        case
          when row_payload ->> 'id' ~
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then (row_payload ->> 'id')::uuid
          else null
        end
      ), '{}'::jsonb)
    order by ordinal
  ), '[]'::jsonb)
  into v_rows
  from jsonb_array_elements(coalesce(v_payload -> 'rows', '[]'::jsonb))
    with ordinality as rows(row_payload, ordinal);

  v_open_v9 := coalesce(
    (v_payload #>> '{metrics,open-payout-batches}')::integer,
    0
  );

  select count(*)::integer
  into v_open_v10
  from public.session_transfer_jobs job
  join public.session_payments payment
    on payment.id = job.session_payment_id
  left join public.stripe_transfers transfer
    on transfer.id = job.stripe_transfer_id
  where payment.payment_flow_version = 'v10'
    and job.status in (
      'queued', 'creating', 'pending_source', 'transferred',
      'reconciliation_required'
    )
    and not exists (
      select 1
      from public.stripe_payout_transfer_allocations allocation
      join public.stripe_payouts payout
        on payout.id = allocation.stripe_payout_id
      where allocation.stripe_transfer_id = transfer.id
        and allocation.allocation_origin = 'session_direct'
        and allocation.amount_cents = transfer.amount_cents
        and payout.status = 'paid'
        and payout.provider_reconciliation_status = 'completed'
        and payout.allocation_status = 'completed'
    );

  v_payload := jsonb_set(v_payload, '{rows}', v_rows, true);
  return jsonb_set(
    v_payload,
    '{metrics,open-payout-batches}',
    to_jsonb(v_open_v9 + v_open_v10),
    true
  );
end;
$_$;


ALTER FUNCTION "public"."admin_get_finance_module_v2"("p_module" "text", "p_query" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_finance_module_v2"("p_module" "text", "p_query" "jsonb") IS 'Paginated admin finance read model with sanitized V9/V10 payout states and no provider object identifiers.';



CREATE OR REPLACE FUNCTION "public"."admin_get_full_session_refund_followup_v10"("p_session_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_decision public.session_refund_decisions_v10%rowtype;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles where id = auth.uid() and role = 'admin'
      and auth_deleted_at is null and anonymized_at is null
  ) then raise exception 'ADMIN_REFUND_FORBIDDEN' using errcode = '42501'; end if;
  select * into v_decision from public.session_refund_decisions_v10
  where session_payment_id = p_session_payment_id;
  if not found then return jsonb_build_object('found', false); end if;
  return jsonb_build_object('found', true, 'requestId', v_decision.request_id,
    'reason', v_decision.reason);
end;
$$;


ALTER FUNCTION "public"."admin_get_full_session_refund_followup_v10"("p_session_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_full_session_refund_status_v11"("p_session_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_decision public.session_refund_decisions_v10%rowtype;
  v_job public.session_transfer_jobs%rowtype;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles where id = auth.uid() and role = 'admin'
      and auth_deleted_at is null and anonymized_at is null
  ) then raise exception 'ADMIN_REFUND_FORBIDDEN' using errcode = '42501'; end if;
  select * into v_payment from public.session_payments where id = p_session_payment_id;
  if not found then return jsonb_build_object('available', false, 'state', 'not_found'); end if;
  select * into v_decision from public.session_refund_decisions_v10
  where session_payment_id = p_session_payment_id;
  if found then return jsonb_build_object('available', false, 'state',
    case when v_payment.financial_status = 'refunded' then 'refunded' else 'in_review' end); end if;
  select * into v_job from public.session_transfer_jobs
  where session_payment_id = p_session_payment_id;
  return jsonb_build_object('available',
    v_payment.payment_flow_version = 'v10' and v_payment.financial_status = 'paid'
    and v_payment.stripe_charge_id is not null and v_payment.disputed_at is null
    and v_payment.admin_blocked_at is null and not v_payment.refund_pending
    and not exists (select 1 from public.session_refunds
      where session_payment_id = p_session_payment_id)
    and (v_job.id is null or (v_job.status in
      ('queued','pending_source','transferred','offset_only','reversed')
      and v_job.lease_owner is null
      and (v_job.prepared_at is null or v_job.status <> 'queued')
      and (v_job.status <> 'pending_source' or v_job.stripe_transfer_id is not null))),
    'state', case when v_payment.financial_status = 'refunded' then 'refunded'
      when v_payment.payment_flow_version <> 'v10' then 'other_flow'
      else 'unavailable' end);
end;
$$;


ALTER FUNCTION "public"."admin_get_full_session_refund_status_v11"("p_session_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_integration_health_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_signals jsonb;
  v_last jsonb;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  select jsonb_build_object(
    'failed-stripe-webhooks', (
      select count(*)::integer
      from public.stripe_webhook_events
      where stripe_webhook_events.processing_status::text = 'failed'
    ),
    'processing-stripe-webhooks', (
      select count(*)::integer
      from public.stripe_webhook_events
      where stripe_webhook_events.processing_status::text in (
        'received',
        'processing'
      )
    ),
    'attention-subscriptions', (
      select count(*)::integer
      from public.therapist_subscriptions
      where therapist_subscriptions.status::text in (
        'past_due',
        'unpaid',
        'incomplete'
      )
    ),
    'pending-session-payments', (
      select count(*)::integer
      from public.session_payments
      where session_payments.financial_status::text in (
        'pending',
        'processing'
      )
    ),
    'restricted-connect-accounts', (
      select count(*)::integer
      from public.therapist_connect_accounts
      where therapist_connect_accounts.operational_status <> 'active'
    ),
    'failed-zoom-webhooks', (
      select count(*)::integer
      from public.zoom_video_webhook_events
      where zoom_video_webhook_events.processing_status::text = 'failed'
    ),
    'processing-zoom-webhooks', (
      select count(*)::integer
      from public.zoom_video_webhook_events
      where zoom_video_webhook_events.processing_status::text in (
        'received',
        'processing'
      )
    ),
    'failed-video-sessions', (
      select count(*)::integer
      from public.video_sessions
      where video_sessions.status::text = 'failed'
    ),
    'failed-emails', (
      select count(*)::integer
      from public.email_delivery_logs
      where email_delivery_logs.status::text = 'error'
    )
  )
  into v_signals;

  select jsonb_build_object(
    'stripeWebhookAt', (
      select max(stripe_webhook_events.received_at)
      from public.stripe_webhook_events
    ),
    'zoomWebhookAt', (
      select max(zoom_video_webhook_events.created_at)
      from public.zoom_video_webhook_events
    ),
    'emailDeliveryAt', (
      select max(email_delivery_logs.created_at)
      from public.email_delivery_logs
    ),
    'connectSyncAt', (
      select max(therapist_connect_accounts.last_synced_at)
      from public.therapist_connect_accounts
    )
  )
  into v_last;

  return jsonb_build_object(
    'generatedAt', now(),
    'signals', v_signals,
    'last', v_last
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_integration_health_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_integration_health_v1"() IS 'Sanitized admin-only integration health read model. Returns aggregate Stripe, Connect, Zoom and email signals without secrets, payloads, URLs or provider object IDs.';



CREATE OR REPLACE FUNCTION "public"."admin_get_operation_detail_v1"("p_module" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_base jsonb;
  v_record jsonb;
  v_profile_id uuid;
  v_eligibility jsonb;
  v_verification_id uuid;
  v_verification_status text;
  v_protocol text;
begin
  v_base := public.admin_get_operation_detail_v1_internal(p_module, p_id);
  v_record := v_base -> 'record';
  if v_record is null or v_record = 'null'::jsonb then return v_base; end if;

  if p_module = 'support' then
    select protocol into v_protocol from public.support_tickets where id = p_id;
    return jsonb_set(v_base, '{record}', v_record || jsonb_build_object('protocol', v_protocol));
  end if;

  if p_module = 'professionals' then
    v_profile_id := (v_record ->> 'id')::uuid;
    select id, status::text into v_verification_id, v_verification_status
    from public.therapist_verifications
    where therapist_profile_id = v_profile_id
    order by submitted_at desc nulls last, created_at desc, id desc
    limit 1;
  elsif p_module = 'verifications' then
    v_profile_id := (v_record ->> 'therapist_profile_id')::uuid;
  else
    return v_base;
  end if;

  v_eligibility := public.get_therapist_publication_eligibility_v1(v_profile_id);
  v_record := v_record || jsonb_build_object(
    'latest_verification_id', v_verification_id,
    'verification_status', coalesce(v_verification_status, case when p_module = 'verifications' then v_record ->> 'status' else 'none' end),
    'publication_eligibility', v_eligibility,
    'publication_blockers', v_eligibility -> 'blockers'
  );
  return jsonb_set(v_base, '{record}', v_record);
end;
$$;


ALTER FUNCTION "public"."admin_get_operation_detail_v1"("p_module" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_operation_detail_v1_internal"("p_module" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_audit_entity_type text;
  v_record jsonb;
  v_audit_events jsonb;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if p_id is null then
    raise exception 'admin operation detail id required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  case p_module
    when 'professionals' then
      v_audit_entity_type := 'therapist_profile';

      select jsonb_build_object(
        'id', therapist_profiles.id,
        'user_id', therapist_profiles.user_id,
        'public_name', therapist_profiles.public_name,
        'slug', therapist_profiles.slug,
        'plan', therapist_profiles.plan,
        'status', therapist_profiles.status,
        'public_status', therapist_profiles.public_status,
        'is_public', therapist_profiles.is_public,
        'is_accepting_bookings', therapist_profiles.is_accepting_bookings,
        'accepts_online_sessions', therapist_profiles.accepts_online_sessions,
        'city', therapist_profiles.city,
        'state', therapist_profiles.state,
        'country', therapist_profiles.country,
        'languages', therapist_profiles.languages,
        'service_count', coalesce(service_counts.total, 0),
        'active_service_count', coalesce(service_counts.active_total, 0),
        'future_booking_count', coalesce(booking_counts.future_total, 0),
        'total_booking_count', coalesce(booking_counts.total, 0),
        'connect_status', therapist_connect_accounts.operational_status,
        'next_session_at', next_booking.starts_at,
        'created_at', therapist_profiles.created_at,
        'updated_at', therapist_profiles.updated_at
      )
      into v_record
      from public.therapist_profiles
      left join public.therapist_connect_accounts
        on therapist_connect_accounts.therapist_profile_id =
          therapist_profiles.id
      left join lateral (
        select
          count(*)::integer as total,
          count(*) filter (
            where therapist_services.status = 'active'::public.service_status
          )::integer as active_total
        from public.therapist_services
        where therapist_services.therapist_profile_id = therapist_profiles.id
          and therapist_services.archived_at is null
      ) service_counts on true
      left join lateral (
        select
          count(*)::integer as total,
          count(*) filter (where bookings.starts_at >= now())::integer
            as future_total
        from public.bookings
        where bookings.therapist_profile_id = therapist_profiles.id
      ) booking_counts on true
      left join lateral (
        select bookings.starts_at
        from public.bookings
        where bookings.therapist_profile_id = therapist_profiles.id
          and bookings.starts_at >= now()
          and bookings.status not in (
            'cancelled_by_patient'::public.booking_status,
            'cancelled_by_therapist'::public.booking_status,
            'refunded'::public.booking_status
          )
        order by bookings.starts_at asc
        limit 1
      ) next_booking on true
      where therapist_profiles.id = p_id;

    when 'patients' then
      v_audit_entity_type := 'patient_profile';

      select jsonb_build_object(
        'id', patient_profiles.id,
        'user_id', patient_profiles.user_id,
        'display_name', patient_profiles.display_name,
        'account_status', case
          when profiles.auth_deleted_at is not null then 'deleted'
          when profiles.anonymized_at is not null then 'anonymized'
          else 'active'
        end,
        'timezone', patient_profiles.timezone,
        'marketing_consent', patient_profiles.marketing_consent,
        'booking_count', coalesce(booking_counts.total, 0),
        'future_booking_count', coalesce(booking_counts.future_total, 0),
        'ticket_count', coalesce(ticket_counts.total, 0),
        'last_activity_at', greatest(
          patient_profiles.updated_at,
          coalesce(booking_counts.last_activity_at, patient_profiles.updated_at),
          coalesce(ticket_counts.last_activity_at, patient_profiles.updated_at)
        ),
        'created_at', patient_profiles.created_at,
        'updated_at', patient_profiles.updated_at
      )
      into v_record
      from public.patient_profiles
      left join public.profiles
        on profiles.id = patient_profiles.user_id
      left join lateral (
        select
          count(*)::integer as total,
          count(*) filter (where bookings.starts_at >= now())::integer
            as future_total,
          max(bookings.updated_at) as last_activity_at
        from public.bookings
        where bookings.patient_profile_id = patient_profiles.id
      ) booking_counts on true
      left join lateral (
        select
          count(*)::integer as total,
          max(support_tickets.updated_at) as last_activity_at
        from public.support_tickets
        where support_tickets.requester_profile_id = patient_profiles.user_id
      ) ticket_counts on true
      where patient_profiles.id = p_id;

    when 'sessions' then
      v_audit_entity_type := 'booking';

      select jsonb_build_object(
        'id', bookings.id,
        'status', bookings.status,
        'payment_status', bookings.payment_status,
        'starts_at', bookings.starts_at,
        'ends_at', bookings.ends_at,
        'timezone', bookings.timezone,
        'service_title_snapshot', bookings.service_title_snapshot,
        'service_duration_minutes_snapshot',
          bookings.service_duration_minutes_snapshot,
        'therapist_profile_id', bookings.therapist_profile_id,
        'therapist_name', therapist_profiles.public_name,
        'patient_profile_id', bookings.patient_profile_id,
        'patient_name', patient_profiles.display_name,
        'meeting_provider', bookings.meeting_provider,
        'cancelled_at', bookings.cancelled_at,
        'completed_at', bookings.completed_at,
        'created_at', bookings.created_at,
        'updated_at', bookings.updated_at,
        'video_session', video_session_detail.payload
      )
      into v_record
      from public.bookings
      left join public.therapist_profiles
        on therapist_profiles.id = bookings.therapist_profile_id
      left join public.patient_profiles
        on patient_profiles.id = bookings.patient_profile_id
      left join lateral (
        select jsonb_build_object(
          'provider', video_sessions.provider,
          'environment', video_sessions.environment,
          'status', video_sessions.status,
          'scheduled_starts_at', video_sessions.scheduled_starts_at,
          'scheduled_ends_at', video_sessions.scheduled_ends_at,
          'actual_started_at', video_sessions.actual_started_at,
          'actual_ended_at', video_sessions.actual_ended_at,
          'hard_ends_at', video_sessions.hard_ends_at,
          'therapist_token_issued_at', video_sessions.therapist_token_issued_at,
          'therapist_first_joined_at', video_sessions.therapist_first_joined_at,
          'therapist_last_joined_at', video_sessions.therapist_last_joined_at,
          'therapist_last_left_at', video_sessions.therapist_last_left_at,
          'therapist_present', video_sessions.therapist_present,
          'participant_count', video_sessions.participant_count,
          'last_participant_left_at', video_sessions.last_participant_left_at,
          'last_provider_event_at', video_sessions.last_provider_event_at,
          'termination_reason', video_sessions.termination_reason,
          'termination_requested_at', video_sessions.termination_requested_at,
          'termination_confirmed_at', video_sessions.termination_confirmed_at,
          'last_error_code', video_sessions.last_error_code,
          'last_synced_at', video_sessions.last_synced_at,
          'participations', coalesce(participation_rows.rows, '[]'::jsonb),
          'control_jobs', coalesce(job_rows.rows, '[]'::jsonb)
        ) as payload
        from public.video_sessions
        left join lateral (
          select coalesce(
            jsonb_agg(participation_payload order by event_at desc),
            '[]'::jsonb
          ) as rows
          from (
            select
              coalesce(
                video_session_participations.left_at,
                video_session_participations.joined_at,
                video_session_participations.created_at
              ) as event_at,
              jsonb_build_object(
                'participant_role', video_session_participations.participant_role,
                'event_type', video_session_participations.event_type,
                'joined_at', video_session_participations.joined_at,
                'left_at', video_session_participations.left_at,
                'duration_seconds', video_session_participations.duration_seconds,
                'created_at', video_session_participations.created_at
              ) as participation_payload
            from public.video_session_participations
            where video_session_participations.video_session_id = video_sessions.id
            order by coalesce(
              video_session_participations.left_at,
              video_session_participations.joined_at,
              video_session_participations.created_at
            ) desc
            limit 20
          ) sanitized_participations
        ) participation_rows on true
        left join lateral (
          select coalesce(
            jsonb_agg(job_payload order by created_at desc),
            '[]'::jsonb
          ) as rows
          from (
            select
              video_session_control_jobs.created_at,
              jsonb_build_object(
                'environment', video_session_control_jobs.environment,
                'operation', video_session_control_jobs.operation,
                'status', video_session_control_jobs.status,
                'attempts', video_session_control_jobs.attempts,
                'max_attempts', video_session_control_jobs.max_attempts,
                'next_run_at', video_session_control_jobs.next_run_at,
                'locked_until_at', video_session_control_jobs.locked_until_at,
                'last_error_code', video_session_control_jobs.last_error_code,
                'completed_at', video_session_control_jobs.completed_at,
                'created_at', video_session_control_jobs.created_at,
                'updated_at', video_session_control_jobs.updated_at
              ) as job_payload
            from public.video_session_control_jobs
            where video_session_control_jobs.video_session_id = video_sessions.id
            order by video_session_control_jobs.created_at desc
            limit 20
          ) sanitized_jobs
        ) job_rows on true
        where video_sessions.booking_id = bookings.id
      ) video_session_detail on true
      where bookings.id = p_id;

    when 'support' then
      v_audit_entity_type := 'support_ticket';

      select jsonb_build_object(
        'id', support_tickets.id,
        'subject', support_tickets.subject,
        'category', support_tickets.category,
        'status', support_tickets.status,
        'priority', support_tickets.priority,
        'urgency', support_tickets.urgency,
        'source', support_tickets.source,
        'booking_id', support_tickets.booking_id,
        'requester_profile_id', support_tickets.requester_profile_id,
        'requester_role', profiles.role,
        'requester_name', profiles.display_name,
        'created_at', support_tickets.created_at,
        'updated_at', support_tickets.updated_at
      )
      into v_record
      from public.support_tickets
      left join public.profiles
        on profiles.id = support_tickets.requester_profile_id
      where support_tickets.id = p_id;

    when 'reviews' then
      v_audit_entity_type := 'review';

      select jsonb_build_object(
        'id', reviews.id,
        'rating', reviews.rating,
        'status', reviews.status,
        'moderation_reason', reviews.moderation_reason,
        'published_at', reviews.published_at,
        'therapist_profile_id', reviews.therapist_profile_id,
        'therapist_name', therapist_profiles.public_name,
        'patient_profile_id', reviews.patient_profile_id,
        'booking_id', reviews.booking_id,
        'created_at', reviews.created_at,
        'updated_at', reviews.updated_at
      )
      into v_record
      from public.reviews
      left join public.therapist_profiles
        on therapist_profiles.id = reviews.therapist_profile_id
      where reviews.id = p_id;

    when 'verifications' then
      v_audit_entity_type := 'therapist_verification';

      select jsonb_build_object(
        'id', therapist_verifications.id,
        'therapist_profile_id', therapist_verifications.therapist_profile_id,
        'therapist_name', therapist_profiles.public_name,
        'status', therapist_verifications.status,
        'changes_requested_present',
          nullif(btrim(coalesce(therapist_verifications.changes_requested, '')), '')
            is not null,
        'rejection_reason_present',
          nullif(btrim(coalesce(therapist_verifications.rejection_reason, '')), '')
            is not null,
        'reviewed_by', therapist_verifications.reviewed_by,
        'reviewed_at', therapist_verifications.reviewed_at,
        'submitted_at', therapist_verifications.submitted_at,
        'created_at', therapist_verifications.created_at,
        'updated_at', therapist_verifications.updated_at
      )
      into v_record
      from public.therapist_verifications
      left join public.therapist_profiles
        on therapist_profiles.id =
          therapist_verifications.therapist_profile_id
      where therapist_verifications.id = p_id;

    else
      raise exception 'unsupported admin operation module: %', p_module
        using errcode = '22023';
  end case;

  if v_record is null then
    return jsonb_build_object(
      'auditEvents', '[]'::jsonb,
      'generatedAt', now(),
      'id', p_id,
      'module', p_module,
      'record', null
    );
  end if;

  select coalesce(jsonb_agg(event_payload order by created_at desc), '[]'::jsonb)
  into v_audit_events
  from (
    select
      admin_audit_events.created_at,
      jsonb_build_object(
        'id', admin_audit_events.id,
        'action', admin_audit_events.action,
        'actor_role', admin_audit_events.actor_role,
        'permission', admin_audit_events.permission,
        'reason', admin_audit_events.reason,
        'source', admin_audit_events.source,
        'created_at', admin_audit_events.created_at
      ) as event_payload
    from public.admin_audit_events
    where admin_audit_events.entity_type = v_audit_entity_type
      and admin_audit_events.entity_id = p_id::text
    order by admin_audit_events.created_at desc
    limit 8
  ) events;

  return jsonb_build_object(
    'auditEvents', coalesce(v_audit_events, '[]'::jsonb),
    'generatedAt', now(),
    'id', p_id,
    'module', p_module,
    'record', v_record
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_operation_detail_v1_internal"("p_module" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_operation_detail_v1_internal"("p_module" "text", "p_id" "uuid") IS 'Minimized admin operation detail read model. Validates auth.uid() as admin and returns safe operational DTOs plus sanitized audit event summaries, including Zoom lifecycle aggregates for session details.';



CREATE OR REPLACE FUNCTION "public"."admin_get_operation_module_v1"("p_module" "text", "p_limit" integer DEFAULT 12, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_base jsonb;
  v_rows jsonb;
  v_metrics jsonb;
begin
  v_base := public.admin_get_operation_module_v1_internal(p_module, p_limit, p_offset);

  if p_module = 'professionals' then
    select coalesce(jsonb_agg(
      r.row || jsonb_build_object(
        'latest_verification_id', v.id,
        'verification_status', coalesce(v.status::text, 'none'),
        'publication_eligibility', e.value,
        'publication_blockers', e.value -> 'blockers'
      ) order by r.ordinality
    ), '[]'::jsonb)
    into v_rows
    from jsonb_array_elements(v_base -> 'rows') with ordinality r(row, ordinality)
    left join lateral (
      select id, status from public.therapist_verifications
      where therapist_profile_id = (r.row ->> 'id')::uuid
      order by submitted_at desc nulls last, created_at desc, id desc
      limit 1
    ) v on true
    cross join lateral (
      select public.get_therapist_publication_eligibility_v1((r.row ->> 'id')::uuid) as value
    ) e;

    select (v_base -> 'metrics') || jsonb_build_object(
      'public-professionals', count(*) filter (where (public.get_therapist_publication_eligibility_v1(id) ->> 'eligible')::boolean)::integer,
      'approved-not-published', count(*) filter (where status = 'approved' and not (public.get_therapist_publication_eligibility_v1(id) ->> 'eligible')::boolean)::integer
    ) into v_metrics from public.therapist_profiles;

    return jsonb_set(jsonb_set(v_base, '{rows}', v_rows), '{metrics}', v_metrics);
  elsif p_module = 'verifications' then
    select coalesce(jsonb_agg(
      r.row || jsonb_build_object(
        'profile_status', p.status,
        'publication_eligibility', e.value,
        'publication_blockers', e.value -> 'blockers'
      ) order by r.ordinality
    ), '[]'::jsonb)
    into v_rows
    from jsonb_array_elements(v_base -> 'rows') with ordinality r(row, ordinality)
    join public.therapist_profiles p on p.id = (r.row ->> 'therapist_profile_id')::uuid
    cross join lateral (
      select public.get_therapist_publication_eligibility_v1(p.id) as value
    ) e;

    return jsonb_set(v_base, '{rows}', v_rows);
  end if;

  return v_base;
end;
$$;


ALTER FUNCTION "public"."admin_get_operation_module_v1"("p_module" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_operation_module_v1_internal"("p_module" "text", "p_limit" integer DEFAULT 12, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit, 12), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_metrics jsonb;
  v_rows jsonb;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  case p_module
    when 'professionals' then
      select jsonb_build_object(
        'total-professionals', count(*)::integer,
        'approved-professionals', count(*) filter (
          where therapist_profiles.status = 'approved'::public.therapist_status
        )::integer,
        'public-professionals', count(*) filter (
          where therapist_profiles.is_public is true
        )::integer,
        'booking-professionals', count(*) filter (
          where therapist_profiles.is_accepting_bookings is true
        )::integer
      )
      into v_metrics
      from public.therapist_profiles;

      select coalesce(jsonb_agg(row_payload order by updated_at desc), '[]'::jsonb)
      into v_rows
      from (
        select
          therapist_profiles.updated_at,
          jsonb_build_object(
            'id', therapist_profiles.id,
            'public_name', therapist_profiles.public_name,
            'slug', therapist_profiles.slug,
            'plan', therapist_profiles.plan,
            'status', therapist_profiles.status,
            'public_status', therapist_profiles.public_status,
            'is_public', therapist_profiles.is_public,
            'is_accepting_bookings', therapist_profiles.is_accepting_bookings,
            'service_count', coalesce(service_counts.total, 0),
            'connect_status', therapist_connect_accounts.operational_status,
            'next_session_at', next_booking.starts_at,
            'created_at', therapist_profiles.created_at,
            'updated_at', therapist_profiles.updated_at
          ) as row_payload
        from public.therapist_profiles
        left join lateral (
          select count(*)::integer as total
          from public.therapist_services
          where therapist_services.therapist_profile_id = therapist_profiles.id
            and therapist_services.archived_at is null
        ) service_counts on true
        left join public.therapist_connect_accounts
          on therapist_connect_accounts.therapist_profile_id =
            therapist_profiles.id
        left join lateral (
          select bookings.starts_at
          from public.bookings
          where bookings.therapist_profile_id = therapist_profiles.id
            and bookings.starts_at >= now()
            and bookings.status not in (
              'cancelled_by_patient'::public.booking_status,
              'cancelled_by_therapist'::public.booking_status,
              'refunded'::public.booking_status
            )
          order by bookings.starts_at asc
          limit 1
        ) next_booking on true
        order by therapist_profiles.updated_at desc
        limit v_limit offset v_offset
      ) rows;

    when 'patients' then
      select jsonb_build_object(
        'total-patients', count(*)::integer,
        'recent-patients', count(*) filter (
          where patient_profiles.created_at >= now() - interval '30 days'
        )::integer
      )
      into v_metrics
      from public.patient_profiles;

      select coalesce(jsonb_agg(row_payload order by created_at desc), '[]'::jsonb)
      into v_rows
      from (
        select
          patient_profiles.created_at,
          jsonb_build_object(
            'id', patient_profiles.id,
            'user_id', patient_profiles.user_id,
            'display_name', patient_profiles.display_name,
            'account_status', case
              when profiles.auth_deleted_at is not null then 'deleted'
              when profiles.anonymized_at is not null then 'anonymized'
              else 'active'
            end,
            'timezone', patient_profiles.timezone,
            'booking_count', coalesce(booking_counts.total, 0),
            'ticket_count', coalesce(ticket_counts.total, 0),
            'last_activity_at', greatest(
              patient_profiles.updated_at,
              coalesce(booking_counts.last_activity_at, patient_profiles.updated_at),
              coalesce(ticket_counts.last_activity_at, patient_profiles.updated_at)
            ),
            'created_at', patient_profiles.created_at,
            'updated_at', patient_profiles.updated_at
          ) as row_payload
        from public.patient_profiles
        left join public.profiles
          on profiles.id = patient_profiles.user_id
        left join lateral (
          select
            count(*)::integer as total,
            max(bookings.updated_at) as last_activity_at
          from public.bookings
          where bookings.patient_profile_id = patient_profiles.id
        ) booking_counts on true
        left join lateral (
          select
            count(*)::integer as total,
            max(support_tickets.updated_at) as last_activity_at
          from public.support_tickets
          where support_tickets.requester_profile_id =
            patient_profiles.user_id
        ) ticket_counts on true
        order by patient_profiles.created_at desc
        limit v_limit offset v_offset
      ) rows;

    when 'sessions' then
      select jsonb_build_object(
        'total-sessions', count(*)::integer,
        'future-sessions', count(*) filter (
          where bookings.starts_at >= now()
        )::integer,
        'attention-sessions', count(*) filter (
          where bookings.status in (
            'pending_payment'::public.booking_status,
            'no_show_patient'::public.booking_status,
            'no_show_therapist'::public.booking_status,
            'refunded'::public.booking_status
          )
        )::integer
      )
      into v_metrics
      from public.bookings;

      select coalesce(jsonb_agg(row_payload order by starts_at desc), '[]'::jsonb)
      into v_rows
      from (
        select
          bookings.starts_at,
          jsonb_build_object(
            'id', bookings.id,
            'status', bookings.status,
            'payment_status', bookings.payment_status,
            'starts_at', bookings.starts_at,
            'ends_at', bookings.ends_at,
            'timezone', bookings.timezone,
            'service_title_snapshot', bookings.service_title_snapshot,
            'service_duration_minutes_snapshot',
              bookings.service_duration_minutes_snapshot,
            'therapist_name', therapist_profiles.public_name,
            'patient_name', patient_profiles.display_name,
            'created_at', bookings.created_at,
            'updated_at', bookings.updated_at
          ) as row_payload
        from public.bookings
        left join public.therapist_profiles
          on therapist_profiles.id = bookings.therapist_profile_id
        left join public.patient_profiles
          on patient_profiles.id = bookings.patient_profile_id
        order by bookings.starts_at desc
        limit v_limit offset v_offset
      ) rows;

    when 'support' then
      select jsonb_build_object(
        'total-support', count(*)::integer,
        'open-support', count(*) filter (
          where support_tickets.status = 'open'
        )::integer,
        'urgent-support', count(*) filter (
          where support_tickets.urgency in ('high', 'critical')
        )::integer
      )
      into v_metrics
      from public.support_tickets;

      select coalesce(jsonb_agg(row_payload order by created_at desc), '[]'::jsonb)
      into v_rows
      from (
        select
          support_tickets.created_at,
          jsonb_build_object(
            'id', support_tickets.id,
            'subject', support_tickets.subject,
            'category', support_tickets.category,
            'status', support_tickets.status,
            'priority', support_tickets.priority,
            'urgency', support_tickets.urgency,
            'source', support_tickets.source,
            'requester_role', profiles.role,
            'requester_name', profiles.display_name,
            'created_at', support_tickets.created_at,
            'updated_at', support_tickets.updated_at
          ) as row_payload
        from public.support_tickets
        left join public.profiles
          on profiles.id = support_tickets.requester_profile_id
        order by support_tickets.created_at desc
        limit v_limit offset v_offset
      ) rows;

    when 'reviews' then
      select jsonb_build_object(
        'total-reviews', count(*)::integer,
        'published-reviews', count(*) filter (
          where reviews.status = 'published'::public.review_status
        )::integer,
        'pending-reviews', count(*) filter (
          where reviews.status in (
            'pending'::public.review_status,
            'reported'::public.review_status
          )
        )::integer
      )
      into v_metrics
      from public.reviews;

      select coalesce(jsonb_agg(row_payload order by created_at desc), '[]'::jsonb)
      into v_rows
      from (
        select
          reviews.created_at,
          jsonb_build_object(
            'id', reviews.id,
            'rating', reviews.rating,
            'status', reviews.status,
            'moderation_reason', reviews.moderation_reason,
            'published_at', reviews.published_at,
            'therapist_name', therapist_profiles.public_name,
            'booking_id', reviews.booking_id,
            'created_at', reviews.created_at,
            'updated_at', reviews.updated_at
          ) as row_payload
        from public.reviews
        left join public.therapist_profiles
          on therapist_profiles.id = reviews.therapist_profile_id
        order by reviews.created_at desc
        limit v_limit offset v_offset
      ) rows;

    when 'verifications' then
      select jsonb_build_object(
        'total-verifications', count(*)::integer,
        'pending-verifications', count(*) filter (
          where therapist_verifications.status in (
            'submitted'::public.therapist_status,
            'in_review'::public.therapist_status,
            'changes_requested'::public.therapist_status
          )
        )::integer
      )
      into v_metrics
      from public.therapist_verifications;

      select coalesce(jsonb_agg(row_payload order by submitted_at desc nulls last), '[]'::jsonb)
      into v_rows
      from (
        select
          therapist_verifications.submitted_at,
          jsonb_build_object(
            'id', therapist_verifications.id,
            'therapist_profile_id',
              therapist_verifications.therapist_profile_id,
            'therapist_name', therapist_profiles.public_name,
            'status', therapist_verifications.status,
            'submitted_at', therapist_verifications.submitted_at,
            'reviewed_at', therapist_verifications.reviewed_at,
            'created_at', therapist_verifications.created_at,
            'updated_at', therapist_verifications.updated_at
          ) as row_payload
        from public.therapist_verifications
        left join public.therapist_profiles
          on therapist_profiles.id =
            therapist_verifications.therapist_profile_id
        order by therapist_verifications.submitted_at desc nulls last,
          therapist_verifications.created_at desc
        limit v_limit offset v_offset
      ) rows;

    else
      raise exception 'unsupported admin operation module: %', p_module
        using errcode = '22023';
  end case;

  return jsonb_build_object(
    'generatedAt', now(),
    'metrics', coalesce(v_metrics, '{}'::jsonb),
    'module', p_module,
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_operation_module_v1_internal"("p_module" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_operation_module_v1_internal"("p_module" "text", "p_limit" integer, "p_offset" integer) IS 'Minimized admin operation read model. Validates auth.uid() as an admin profile before reading canonical tables and returning DTOs; does not accept actor id from clients.';



CREATE OR REPLACE FUNCTION "public"."admin_get_operation_module_v2"("p_module" "text", "p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_base jsonb;
  v_filtered jsonb;
  v_page integer := 1;
  v_page_size integer := 12;
  v_page_text text := coalesce(p_query ->> 'page', '');
  v_page_size_text text := coalesce(p_query ->> 'pageSize', '');
  v_search text := nullif(btrim(coalesce(p_query ->> 'search', '')), '');
  v_sort text := nullif(btrim(coalesce(p_query ->> 'sort', 'recent')), '');
  v_status text := nullif(btrim(coalesce(p_query ->> 'status', '')), '');
  v_total integer := 0;
begin
  if v_page_text ~ '^[0-9]+$' then
    v_page := greatest(v_page_text::integer, 1);
  end if;

  if v_page_size_text ~ '^[0-9]+$' then
    v_page_size := least(greatest(v_page_size_text::integer, 1), 50);
  end if;

  v_base := public.admin_get_operation_module_v1(p_module, 50, 0);

  v_filtered := public.admin_filter_jsonb_read_model_rows_v1(
    v_base -> 'rows',
    v_search,
    v_status,
    coalesce(v_sort, 'recent'),
    v_page,
    v_page_size
  );
  v_total := coalesce((v_filtered ->> 'total')::integer, 0);

  return jsonb_build_object(
    'filtersApplied', jsonb_build_object(
      'search', v_search,
      'sort', coalesce(v_sort, 'recent'),
      'status', v_status
    ),
    'generatedAt', coalesce(v_base -> 'generatedAt', to_jsonb(now())),
    'metrics', coalesce(v_base -> 'metrics', '{}'::jsonb),
    'module', p_module,
    'page', jsonb_build_object(
      'hasNext', (v_page * v_page_size) < v_total,
      'page', v_page,
      'pageSize', v_page_size,
      'total', v_total
    ),
    'rows', coalesce(v_filtered -> 'rows', '[]'::jsonb)
  );
end;
$_$;


ALTER FUNCTION "public"."admin_get_operation_module_v2"("p_module" "text", "p_query" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_operation_module_v2"("p_module" "text", "p_query" "jsonb") IS 'Paginated admin operation read model. Validates the authenticated admin through v1 and returns sanitized rows with filtersApplied and page metadata.';



CREATE OR REPLACE FUNCTION "public"."admin_get_session_feedback_v1"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_patient public.session_feedback;
  v_therapist public.session_feedback;
  v_patient_confirmation public.session_participant_confirmations;
  v_therapist_confirmation public.session_participant_confirmations;
  v_attendance jsonb;
  v_pending jsonb := '[]'::jsonb;
  v_is_divergent boolean := false;
  v_payment record;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles
    where profiles.id = auth.uid()
      and profiles.role = 'admin'::public.user_role
  ) then
    raise exception 'FEEDBACK_ADMIN_REQUIRED' using errcode = '42501';
  end if;

  select feedback.* into v_patient
  from public.session_feedback feedback
  where feedback.booking_id = p_booking_id
    and feedback.author_role = 'patient'::public.user_role
  limit 1;

  select feedback.* into v_therapist
  from public.session_feedback feedback
  where feedback.booking_id = p_booking_id
    and feedback.author_role = 'therapist'::public.user_role
  limit 1;

  select confirmation.* into v_patient_confirmation
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = 'patient'::public.user_role;

  select confirmation.* into v_therapist_confirmation
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = 'therapist'::public.user_role;

  v_attendance := public.session_attendance_state_v1(p_booking_id, now());

  if v_patient.id is null then
    v_pending := v_pending || jsonb_build_array('patient');
  end if;
  if v_therapist.id is null then
    v_pending := v_pending || jsonb_build_array('therapist');
  end if;

  if v_patient.id is not null and v_therapist.id is not null then
    v_is_divergent := v_patient.outcome is distinct from v_therapist.outcome
      or v_patient.rating is distinct from v_therapist.rating
      or v_patient.not_performed_reason is distinct from v_therapist.not_performed_reason;
  end if;

  select
    payment.transfer_status::text,
    payment.eligible_at,
    payment.service_status::text,
    payment.service_confirmed_at
  into v_payment
  from public.session_payments payment
  where payment.booking_id = p_booking_id;

  return jsonb_build_object(
    'attendance', v_attendance,
    'confirmation', jsonb_build_object(
      'patient', case when v_patient_confirmation.id is null then null else jsonb_build_object(
        'confirmedAt', v_patient_confirmation.confirmed_at,
        'dueAt', v_patient_confirmation.due_at,
        'outcome', v_patient_confirmation.outcome,
        'source', v_patient_confirmation.source
      ) end,
      'therapist', case when v_therapist_confirmation.id is null then null else jsonb_build_object(
        'confirmedAt', v_therapist_confirmation.confirmed_at,
        'dueAt', v_therapist_confirmation.due_at,
        'outcome', v_therapist_confirmation.outcome,
        'source', v_therapist_confirmation.source
      ) end
    ),
    'divergent', v_is_divergent,
    'financial', case when v_payment.transfer_status is null then null else jsonb_build_object(
      'eligibleAt', v_payment.eligible_at,
      'serviceConfirmedAt', v_payment.service_confirmed_at,
      'serviceStatus', v_payment.service_status,
      'transferStatus', v_payment.transfer_status
    ) end,
    'pendingRoles', v_pending,
    'patient', case when v_patient.id is null then null else public.session_feedback_payload(v_patient) end,
    'therapist', case when v_therapist.id is null then null else public.session_feedback_payload(v_therapist) end
  );
end;
$$;


