CREATE OR REPLACE FUNCTION "public"."admin_get_support_inbox_v1"("p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_page integer := greatest(1, least(10000, coalesce(nullif(p_query ->> 'page', '')::integer, 1)));
  v_page_size integer := greatest(1, least(50, coalesce(nullif(p_query ->> 'pageSize', '')::integer, 12)));
  v_search text := left(replace(btrim(coalesce(p_query ->> 'search', '')), '#', ''), 120);
  v_status text := nullif(btrim(coalesce(p_query ->> 'status', '')), '');
  v_priority text := nullif(btrim(coalesce(p_query ->> 'priority', '')), '');
  v_category text := nullif(btrim(coalesce(p_query ->> 'category', '')), '');
  v_persona text := nullif(btrim(coalesce(p_query ->> 'persona', '')), '');
  v_assignment text := nullif(btrim(coalesce(p_query ->> 'assignment', '')), '');
  v_total integer;
  v_attention integer;
  v_rows jsonb;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'::public.user_role
  ) then
    raise exception 'authorized admin required' using errcode = '42501';
  end if;
  if v_status is not null and v_status not in ('open', 'in_progress', 'waiting_requester', 'waiting_support', 'resolved') then
    raise exception 'support inbox status is invalid' using errcode = '22023';
  end if;
  if v_priority is not null and v_priority not in ('low', 'normal', 'high', 'urgent') then
    raise exception 'support inbox priority is invalid' using errcode = '22023';
  end if;
  if v_persona is not null and v_persona not in ('patient', 'therapist') then
    raise exception 'support inbox persona is invalid' using errcode = '22023';
  end if;
  if v_assignment is not null and v_assignment not in ('unassigned', 'me') then
    raise exception 'support inbox assignment is invalid' using errcode = '22023';
  end if;

  with filtered as (
    select tickets.id, tickets.protocol, tickets.subject, tickets.category,
      tickets.status, tickets.priority, tickets.booking_id, tickets.created_at,
      tickets.last_activity_at, requester.display_name as requester_name,
      requester.role::text as requester_role,
      assignee.display_name as assigned_admin_name, tickets.assigned_admin_id
    from public.support_tickets tickets
    left join public.profiles requester on requester.id = tickets.requester_profile_id
    left join public.profiles assignee on assignee.id = tickets.assigned_admin_id
    where (v_status is null or tickets.status = v_status)
      and (v_priority is null or tickets.priority = v_priority)
      and (v_category is null or tickets.category = v_category)
      and (v_persona is null or requester.role::text = v_persona)
      and (v_assignment is null
        or (v_assignment = 'unassigned' and tickets.assigned_admin_id is null)
        or (v_assignment = 'me' and tickets.assigned_admin_id = auth.uid()))
      and (v_search = '' or tickets.subject ilike '%' || v_search || '%'
        or tickets.protocol ilike v_search || '%'
        or coalesce(requester.display_name, '') ilike '%' || v_search || '%'
        or coalesce(requester.email, '') ilike '%' || v_search || '%')
  )
  select count(*)::integer into v_total from filtered;

  select count(*)::integer into v_attention
  from public.support_tickets where status = 'waiting_support';

  with filtered as (
    select tickets.id, tickets.protocol, tickets.subject, tickets.category,
      tickets.status, tickets.priority, tickets.booking_id, tickets.created_at,
      tickets.last_activity_at, requester.display_name as requester_name,
      requester.role::text as requester_role,
      assignee.display_name as assigned_admin_name, tickets.assigned_admin_id
    from public.support_tickets tickets
    left join public.profiles requester on requester.id = tickets.requester_profile_id
    left join public.profiles assignee on assignee.id = tickets.assigned_admin_id
    where (v_status is null or tickets.status = v_status)
      and (v_priority is null or tickets.priority = v_priority)
      and (v_category is null or tickets.category = v_category)
      and (v_persona is null or requester.role::text = v_persona)
      and (v_assignment is null
        or (v_assignment = 'unassigned' and tickets.assigned_admin_id is null)
        or (v_assignment = 'me' and tickets.assigned_admin_id = auth.uid()))
      and (v_search = '' or tickets.subject ilike '%' || v_search || '%'
        or tickets.protocol ilike v_search || '%'
        or coalesce(requester.display_name, '') ilike '%' || v_search || '%')
  ),
  ordered_rows as (
    select
      id,
      last_activity_at,
      created_at,
      jsonb_build_object(
        'id', id, 'protocol', protocol, 'subject', subject, 'category', category,
        'status', status, 'priority', priority, 'bookingId', booking_id,
        'createdAt', created_at, 'lastActivityAt', last_activity_at,
        'requesterName', requester_name, 'requesterRole', requester_role,
        'assignedAdminName', assigned_admin_name, 'assignedAdminId', assigned_admin_id
      ) as row_payload
    from filtered
    order by last_activity_at desc, created_at desc, id desc
    limit v_page_size offset ((v_page - 1) * v_page_size)
  )
  select coalesce(
    jsonb_agg(row_payload order by last_activity_at desc, created_at desc, id desc),
    '[]'::jsonb
  ) into v_rows
  from ordered_rows;

  return jsonb_build_object(
    'rows', v_rows, 'attentionCount', v_attention,
    'page', jsonb_build_object('page', v_page, 'pageSize', v_page_size, 'total', v_total, 'hasNext', v_total > v_page * v_page_size)
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_support_inbox_v1"("p_query" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_support_inbox_v1"("p_query" "jsonb") IS 'Admin-only support inbox with server-side filters, chronological recency ordering and pagination.';



CREATE OR REPLACE FUNCTION "public"."admin_get_support_ticket_management_v1"("p_ticket_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ticket jsonb;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles where id = auth.uid() and role = 'admin'::public.user_role
  ) then
    raise exception 'authorized admin required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'id', tickets.id,
    'status', tickets.status,
    'priority', tickets.priority,
    'assignedAdminId', tickets.assigned_admin_id,
    'assignedAdminName', assignee.display_name,
    'requesterEmail', requester.email,
    'booking', case when bookings.id is null then null else jsonb_build_object(
      'id', bookings.id,
      'startsAt', bookings.starts_at,
      'status', bookings.status,
      'paymentStatus', bookings.payment_status,
      'therapistName', therapist_profiles.public_name,
      'patientName', patient_profiles.display_name
    ) end
  ) into v_ticket
  from public.support_tickets tickets
  left join public.profiles assignee on assignee.id = tickets.assigned_admin_id
  left join public.profiles requester on requester.id = tickets.requester_profile_id
  left join public.bookings bookings on bookings.id = tickets.booking_id
  left join public.therapist_profiles therapist_profiles on therapist_profiles.id = bookings.therapist_profile_id
  left join public.patient_profiles patient_profiles on patient_profiles.id = bookings.patient_profile_id
  where tickets.id = p_ticket_id;

  if v_ticket is null then
    raise exception 'support ticket not found' using errcode = 'P0002';
  end if;
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."admin_get_support_ticket_management_v1"("p_ticket_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_support_ticket_thread_v1"("p_ticket_id" "uuid") RETURNS TABLE("id" "uuid", "author_role" "public"."user_role", "body" "text", "visibility" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles
    where profiles.id = auth.uid()
      and profiles.role = 'admin'::public.user_role
  ) then
    raise exception 'authorized admin required' using errcode = '42501';
  end if;

  if p_ticket_id is null or not exists (
    select 1 from public.support_tickets where support_tickets.id = p_ticket_id
  ) then
    raise exception 'support ticket not found' using errcode = 'P0002';
  end if;

  return query
  select
    support_ticket_messages.id,
    support_ticket_messages.author_role,
    support_ticket_messages.body,
    support_ticket_messages.visibility,
    support_ticket_messages.created_at
  from public.support_ticket_messages
  where support_ticket_messages.ticket_id = p_ticket_id
  order by support_ticket_messages.created_at asc, support_ticket_messages.id asc;
end;
$$;


ALTER FUNCTION "public"."admin_get_support_ticket_thread_v1"("p_ticket_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_support_ticket_thread_v1"("p_ticket_id" "uuid") IS 'Admin-only support thread read. It may include internal notes and must never be used by requester APIs.';



CREATE OR REPLACE FUNCTION "public"."admin_get_support_ticket_thread_v2"("p_ticket_id" "uuid") RETURNS TABLE("id" "uuid", "author_role" "public"."user_role", "body" "text", "visibility" "text", "created_at" timestamp with time zone, "attachments" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles
    where profiles.id = auth.uid() and profiles.role = 'admin'::public.user_role
  ) then
    raise exception 'authorized admin required' using errcode = '42501';
  end if;
  if p_ticket_id is null or not exists (
    select 1
    from public.support_tickets
    where public.support_tickets.id = p_ticket_id
  ) then
    raise exception 'support ticket not found' using errcode = 'P0002';
  end if;

  return query
  select
    messages.id,
    messages.author_role,
    messages.body,
    messages.visibility,
    messages.created_at,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', attachments.id,
          'fileName', attachments.original_name,
          'mimeType', attachments.mime_type,
          'sizeBytes', attachments.size_bytes
        ) order by attachments.created_at
      ) filter (where attachments.id is not null),
      '[]'::jsonb
    ) as attachments
  from public.support_ticket_messages messages
  left join public.support_ticket_message_attachments attachments
    on attachments.message_id = messages.id
  where messages.ticket_id = p_ticket_id
  group by messages.id, messages.author_role, messages.body,
    messages.visibility, messages.created_at
  order by messages.created_at asc, messages.id asc;
end;
$$;


ALTER FUNCTION "public"."admin_get_support_ticket_thread_v2"("p_ticket_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_therapist_profile_review_v1"("p_therapist_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_profile public.therapist_profiles%rowtype;
  v_content_id uuid;
  v_content jsonb;
  v_verification_status text;
  v_services jsonb;
  v_private_identity jsonb;
begin
  if v_actor_id is null or not exists (
    select 1 from public.profiles
    where id = v_actor_id
      and role = 'admin'::public.user_role
      and auth_deleted_at is null
      and anonymized_at is null
  ) then
    raise exception 'admin permission required' using errcode = '42501';
  end if;

  select * into v_profile
  from public.therapist_profiles
  where id = p_therapist_profile_id;

  if not found then
    raise exception 'profile review target not found' using errcode = 'P0002';
  end if;

  select content.id into v_content_id
  from public.therapist_profile_content_versions content
  where content.therapist_profile_id = v_profile.id
    and content.status = 'published'
  order by content.published_at desc nulls last,
    content.updated_at desc,
    content.created_at desc
  limit 1;

  if v_content_id is not null then
    v_content := public.therapist_profile_content_json_m1(v_content_id);
  end if;

  select status::text into v_verification_status
  from public.therapist_verifications
  where therapist_profile_id = v_profile.id
  order by submitted_at desc nulls last, created_at desc, id desc
  limit 1;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'title', services.title,
      'description', services.description,
      'durationMinutes', services.duration_minutes,
      'priceCents', services.price_cents,
      'currency', services.currency,
      'status', services.status,
      'therapyName', therapies.name
    ) order by services.position, services.created_at
  ), '[]'::jsonb)
  into v_services
  from public.therapist_services services
  left join public.therapies therapies on therapies.id = services.therapy_id
  where services.therapist_profile_id = v_profile.id
    and services.archived_at is null;

  select jsonb_build_object(
    'documentType', identity.document_type,
    'documentNumber', identity.document_number,
    'postalCode', identity.postal_code,
    'street', identity.street,
    'streetNumber', identity.street_number,
    'complement', identity.complement,
    'neighborhood', identity.neighborhood,
    'city', identity.city,
    'state', identity.state,
    'country', identity.country
  )
  into v_private_identity
  from public.therapist_private_identity identity
  where identity.therapist_profile_id = v_profile.id;

  return jsonb_build_object(
    'contentVersionId', v_content ->> 'contentVersionId',
    'profileStatus', v_profile.status,
    'publicStatus', v_profile.public_status,
    'verificationStatus', coalesce(v_verification_status, 'none'),
    'publishedAt', v_content ->> 'publishedAt',
    'fields', jsonb_strip_nulls(
      jsonb_build_object(
        'publicName', v_profile.public_name,
        'headline', v_profile.headline,
        'bio', v_profile.bio,
        'photoUrl', v_profile.photo_url,
        'city', v_profile.city,
        'state', v_profile.state,
        'country', v_profile.country
      ) || coalesce(v_content -> 'fields', '{}'::jsonb)
    ),
    'privateIdentity', v_private_identity,
    'services', v_services
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_therapist_profile_review_v1"("p_therapist_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_therapist_profile_review_v1"("p_therapist_profile_id" "uuid") IS 'Admin-only sanitized preview of the latest therapist profile submission, including public content, video link, services and private identity for validation.';



CREATE OR REPLACE FUNCTION "public"."admin_list_matching_v1"("p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.admin_get_actor_profile_v1(p_actor_user_id);

  return jsonb_build_object(
    'contractVersion', 1,
    'themes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', theme.id,
          'name', theme.name,
          'slug', theme.slug,
          'description', theme.description,
          'imageUrl', theme.image_url,
          'sortOrder', theme.sort_order,
          'isActive', theme.is_active,
          'therapyCount', coalesce(therapy_count.count, 0),
          'serviceCount', coalesce(service_count.count, 0),
          'createdAt', theme.created_at,
          'updatedAt', theme.updated_at,
          'interests', coalesce(interest_rows.items, '[]'::jsonb),
          'history', coalesce(event_rows.items, '[]'::jsonb)
        )
        order by theme.sort_order asc, theme.name asc
      )
      from public.matching_themes as theme
      left join lateral (
        select count(distinct therapy_id)::integer as count
        from public.therapy_matching_themes
        where theme_id = theme.id
      ) as therapy_count on true
      left join lateral (
        select count(distinct therapist_service_id)::integer as count
        from public.therapist_service_matching_themes
        where theme_id = theme.id
      ) as service_count on true
      left join lateral (
        select jsonb_agg(
          jsonb_build_object(
            'id', interest.id,
            'themeId', interest.theme_id,
            'name', interest.name,
            'slug', interest.slug,
            'sortOrder', interest.sort_order,
            'isActive', interest.is_active,
            'serviceCount', coalesce(interest_service_count.count, 0),
            'createdAt', interest.created_at,
            'updatedAt', interest.updated_at,
            'history', coalesce(interest_event_rows.items, '[]'::jsonb)
          )
          order by interest.sort_order asc, interest.name asc
        ) as items
        from public.matching_interests as interest
        left join lateral (
          select count(distinct therapist_service_id)::integer as count
          from public.therapist_service_matching_interests
          where interest_id = interest.id
        ) as interest_service_count on true
        left join lateral (
          select jsonb_agg(
            jsonb_build_object(
              'id', event.id,
              'eventType', event.event_type,
              'reason', event.reason,
              'createdAt', event.created_at,
              'actorProfileId', event.actor_profile_id
            )
            order by event.created_at desc
          ) as items
          from (
            select *
            from public.therapy_catalog_events
            where entity_type = 'matching_interest'
              and entity_id = interest.id
            order by created_at desc
            limit 8
          ) as event
        ) as interest_event_rows on true
        where interest.theme_id = theme.id
      ) as interest_rows on true
      left join lateral (
        select jsonb_agg(
          jsonb_build_object(
            'id', event.id,
            'eventType', event.event_type,
            'reason', event.reason,
            'createdAt', event.created_at,
            'actorProfileId', event.actor_profile_id
          )
          order by event.created_at desc
        ) as items
        from (
          select *
          from public.therapy_catalog_events
          where entity_type = 'matching_theme'
            and entity_id = theme.id
          order by created_at desc
          limit 8
        ) as event
      ) as event_rows on true
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_list_matching_v1"("p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_therapy_catalog_v1"("p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.admin_get_actor_profile_v1(p_actor_user_id);

  return jsonb_build_object(
    'contractVersion', 1,
    'matchingThemes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', theme.id,
          'name', theme.name,
          'slug', theme.slug,
          'imageUrl', theme.image_url,
          'sortOrder', theme.sort_order
        )
        order by theme.sort_order, theme.name
      )
      from public.matching_themes theme
      where theme.is_active
    ), '[]'::jsonb),
    'items', coalesce((
      select jsonb_agg(item order by item->>'name')
      from (
        select jsonb_build_object(
          'id', therapy.id,
          'name', therapy.name,
          'slug', therapy.slug,
          'status', therapy.status,
          'isPubliclyVisible', therapy.is_public_visible,
          'isAvailableForServices', therapy.is_available_for_services,
          'isVisibleInMatching', coalesce(settings.is_visible_in_matching, false),
          'matchingThemeIds', coalesce(theme_ids.items, '[]'::jsonb),
          'hasPublishedMatchWeights', exists (
            select 1
            from public.matching_weights weight
            join public.matching_versions version on version.id = weight.version_id
            where weight.therapy_id = therapy.id
              and weight.is_active
              and version.status = 'published'
          ),
          'isFeatured', therapy.is_featured,
          'publishedAt', therapy.published_at,
          'deprecatedAt', therapy.deprecated_at,
          'archivedAt', therapy.archived_at,
          'replacementTherapyId', therapy.replacement_therapy_id,
          'shortDescription', therapy.short_description,
          'description', therapy.description,
          'imageUrl', therapy.image_url,
          'aliases', therapy.search_aliases,
          'calendarColorKey', therapy.calendar_color_key,
          'publicContent', jsonb_build_object(
            'subtitle', content.subtitle,
            'introduction', content.introduction,
            'complementaryDescription', content.complementary_description,
            'safetyNote', coalesce(content.safety_note, therapy.safety_note),
            'seoTitle', content.seo_title,
            'seoDescription', content.seo_description,
            'heroImageUrl', content.hero_image_url,
            'approachLabel', content.approach_label,
            'approachIconKey', content.approach_icon_key,
            'visualThemeKey', content.visual_theme_key,
            'heroFocalPoint', content.hero_focal_point,
            'highlights', coalesce(highlights.items, '[]'::jsonb),
            'benefits', coalesce(benefits.items, '[]'::jsonb)
          ),
          'history', coalesce(events.items, '[]'::jsonb),
          'impact', public.admin_therapy_impact_v1(p_actor_user_id, therapy.id),
          'updatedAt', therapy.updated_at
        ) as item
        from public.therapies therapy
        left join public.matching_therapy_settings settings
          on settings.therapy_id = therapy.id
        left join public.therapy_public_content content
          on content.therapy_id = therapy.id
        left join lateral (
          select jsonb_agg(link.theme_id order by link.sort_order) as items
          from public.therapy_matching_themes link
          where link.therapy_id = therapy.id
        ) theme_ids on true
        left join lateral (
          select jsonb_agg(
            jsonb_build_object('title', highlight.title, 'iconKey', highlight.icon_key)
            order by highlight.sort_order
          ) as items
          from public.therapy_highlights highlight
          where highlight.therapy_id = therapy.id
        ) highlights on true
        left join lateral (
          select jsonb_agg(
            jsonb_build_object(
              'title', benefit.title,
              'description', benefit.description,
              'iconKey', benefit.icon_key
            )
            order by benefit.sort_order
          ) as items
          from public.therapy_benefits benefit
          where benefit.therapy_id = therapy.id
        ) benefits on true
        left join lateral (
          select jsonb_agg(
            jsonb_build_object(
              'id', event_row.id,
              'eventType', event_row.event_type,
              'reason', event_row.reason,
              'createdAt', event_row.created_at,
              'actorProfileId', event_row.actor_profile_id
            )
            order by event_row.created_at desc
          ) as items
          from (
            select *
            from public.therapy_catalog_events event
            where event.entity_type = 'therapy'
              and event.entity_id = therapy.id
            order by event.created_at desc
            limit 8
          ) event_row
        ) events on true
      ) rows
    ), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', request.id,
          'informedName', request.informed_name,
          'description', request.description,
          'justification', request.justification,
          'status', request.status,
          'relatedTherapyId', request.related_therapy_id,
          'decision', request.decision,
          'createdAt', request.created_at
        )
        order by request.created_at desc
      )
      from public.therapy_catalog_requests request
      where request.status in ('submitted', 'under_review', 'needs_information')
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_list_therapy_catalog_v1"("p_actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_list_therapy_catalog_v1"("p_actor_user_id" "uuid") IS 'Admin catalog contract with active Match themes and canonical therapy-theme links. Public Match projections are not used for administrative editing.';



CREATE OR REPLACE FUNCTION "public"."admin_manage_support_ticket_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_action" "text", "p_priority" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_ticket public.support_tickets%rowtype;
  v_previous jsonb;
  v_next jsonb;
  v_action text := nullif(btrim(coalesce(p_action, '')), '');
  v_priority text := nullif(btrim(coalesce(p_priority, '')), '');
  v_audit_id uuid;
begin
  if v_actor_id is null or not exists (
    select 1 from public.profiles where id = v_actor_id and role = 'admin'::public.user_role
  ) then
    raise exception 'authorized admin required' using errcode = '42501';
  end if;
  if p_ticket_id is null or p_request_id is null then
    raise exception 'support management request is invalid' using errcode = '22023';
  end if;
  if v_action not in ('assign_self', 'unassign', 'set_priority', 'start', 'resolve', 'reopen') then
    raise exception 'support management action is invalid' using errcode = '22023';
  end if;
  if v_action = 'set_priority' and v_priority not in ('low', 'normal', 'high', 'urgent') then
    raise exception 'support priority is invalid' using errcode = '22023';
  end if;

  select * into v_ticket
  from public.support_tickets
  where id = p_ticket_id
  for update;
  if not found then
    raise exception 'support ticket not found' using errcode = 'P0002';
  end if;

  v_previous := jsonb_build_object(
    'assignedAdminId', v_ticket.assigned_admin_id,
    'priority', v_ticket.priority,
    'status', v_ticket.status
  );

  if v_action = 'assign_self' then
    update public.support_tickets set assigned_admin_id = v_actor_id, last_activity_at = now()
    where id = p_ticket_id;
  elsif v_action = 'unassign' then
    update public.support_tickets set assigned_admin_id = null, last_activity_at = now()
    where id = p_ticket_id;
  elsif v_action = 'set_priority' then
    update public.support_tickets set priority = v_priority, last_activity_at = now()
    where id = p_ticket_id;
  elsif v_action = 'start' then
    if v_ticket.status not in ('open', 'waiting_support') then
      raise exception 'support ticket cannot enter in_progress from current status' using errcode = '22023';
    end if;
    update public.support_tickets set status = 'in_progress', last_activity_at = now()
    where id = p_ticket_id;
  elsif v_action = 'resolve' then
    if v_ticket.status = 'resolved' then
      raise exception 'support ticket is already resolved' using errcode = '22023';
    end if;
    update public.support_tickets set status = 'resolved', last_activity_at = now()
    where id = p_ticket_id;
  elsif v_action = 'reopen' then
    if v_ticket.status <> 'resolved' then
      raise exception 'only resolved tickets can be reopened' using errcode = '22023';
    end if;
    update public.support_tickets set status = 'open', last_activity_at = now()
    where id = p_ticket_id;
  end if;

  select jsonb_build_object(
    'assignedAdminId', tickets.assigned_admin_id,
    'priority', tickets.priority,
    'status', tickets.status
  ) into v_next
  from public.support_tickets tickets
  where id = p_ticket_id;

  v_audit_id := public.record_admin_audit_event_v1(
    v_actor_id,
    'admin',
    'admin.support.manage',
    'support.' || v_action,
    'support_ticket',
    p_ticket_id::text,
    v_previous,
    v_next,
    null,
    p_request_id::text,
    null,
    'admin-support-inbox'
  );

  return jsonb_build_object('ok', true, 'auditEventId', v_audit_id, 'ticket', v_next);
end;
$$;


ALTER FUNCTION "public"."admin_manage_support_ticket_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_action" "text", "p_priority" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_manage_support_ticket_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_action" "text", "p_priority" "text") IS 'Admin-only allowlisted support triage mutation with append-only audit event.';



