    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_event_type like 'matching_%' then 'admin.matching.manage'
    when p_event_type like 'therapy_matching_%' then 'admin.matching.manage'
    else 'admin.therapies.manage'
  end;
$$;


