CREATE OR REPLACE FUNCTION "public"."admin_resolve_session_confirmation_incident_v1"("p_booking_id" "uuid", "p_decision" "text", "p_reason" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_incident public.session_confirmation_incidents%rowtype;
  v_payment public.session_payments%rowtype;
begin
  if v_actor_id is null or not exists (
    select 1 from public.profiles
    where id = v_actor_id and role = 'admin'::public.user_role
  ) then
    raise exception 'SESSION_INCIDENT_ADMIN_REQUIRED' using errcode = '42501';
  end if;
  if p_booking_id is null or p_request_id is null
    or p_decision not in ('performed_confirmed', 'not_performed_confirmed')
    or length(btrim(coalesce(p_reason, ''))) < 5
    or length(btrim(coalesce(p_reason, ''))) > 1000 then
    raise exception 'SESSION_INCIDENT_VALIDATION_ERROR' using errcode = '22023';
  end if;

  select * into v_incident from public.session_confirmation_incidents
  where booking_id = p_booking_id for update;
  if not found then raise exception 'SESSION_INCIDENT_NOT_FOUND'; end if;
  if v_incident.resolution_request_id = p_request_id then
    return jsonb_build_object('idempotentReplay', true, 'status', v_incident.status);
  end if;
  if v_incident.status <> 'open' then
    raise exception 'SESSION_INCIDENT_ALREADY_RESOLVED';
  end if;

  select * into v_payment from public.session_payments
  where booking_id = p_booking_id for update;

  update public.session_confirmation_incidents
  set status = p_decision,
      resolution_reason = btrim(p_reason),
      resolved_by_user_id = v_actor_id,
      resolution_request_id = p_request_id,
      resolved_at = now(),
      updated_at = now()
  where id = v_incident.id;

  if p_decision = 'performed_confirmed' then
    update public.session_payments
    set internal_contested_at = null,
        transfer_blocked_reason = null,
        updated_at = now()
    where id = v_payment.id;

    perform public.confirm_session_service(
      p_booking_id,
      'admin'::public.session_confirmation_source,
      v_actor_id,
      null,
      jsonb_build_object(
        'confirmationModel', 'admin_incident_resolution',
        'incidentId', v_incident.id,
        'confirmedAt', now(),
        'reason', btrim(p_reason)
      )
    );
  else
    update public.session_payments
    set service_status = 'not_performed',
        transfer_status = case
          when transfer_status in ('batched', 'transfer_pending', 'transferred') then transfer_status
          else 'blocked'::public.session_transfer_status
        end,
        transfer_blocked_reason = 'not_performed_confirmed_by_admin',
        internal_contested_at = coalesce(internal_contested_at, now()),
        updated_at = now()
    where id = v_payment.id;
  end if;

  perform public.record_admin_audit_event_v1(
    v_actor_id,
    'admin',
    'admin.sessions.manage',
    'session_confirmation_incident.resolve',
    'session_confirmation_incident',
    v_incident.id::text,
    jsonb_build_object('status', v_incident.status),
    jsonb_build_object('status', p_decision),
    btrim(p_reason),
    p_request_id::text,
    null,
    'session_confirmation'
  );

  return jsonb_build_object('idempotentReplay', false, 'status', p_decision);
end;
$$;


ALTER FUNCTION "public"."admin_resolve_session_confirmation_incident_v1"("p_booking_id" "uuid", "p_decision" "text", "p_reason" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_support_ticket_message_exists_v1"("p_ticket_id" "uuid", "p_request_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and role = 'admin'::public.user_role
  ) then
    raise exception 'authorized admin required' using errcode = '42501';
  end if;

  if p_ticket_id is null or p_request_id is null or not exists (
    select 1
    from public.support_tickets
    where id = p_ticket_id
  ) then
    raise exception 'support ticket not found' using errcode = 'P0002';
  end if;

  return exists (
    select 1
    from public.support_ticket_messages
    where ticket_id = p_ticket_id
      and author_profile_id = auth.uid()
      and request_id = p_request_id
      and visibility = 'requester'
  );
end;
$$;


ALTER FUNCTION "public"."admin_support_ticket_message_exists_v1"("p_ticket_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_support_ticket_message_exists_v1"("p_ticket_id" "uuid", "p_request_id" "uuid") IS 'Returns whether the authenticated Admin already created this public support reply request. Does not expose thread data.';



CREATE OR REPLACE FUNCTION "public"."admin_therapy_impact_v1"("p_actor_user_id" "uuid", "p_therapy_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.admin_get_actor_profile_v1(p_actor_user_id);

  return (
    select jsonb_build_object(
      'therapyId', therapies.id,
      'slug', therapies.slug,
      'name', therapies.name,
      'status', therapies.status,
      'isPubliclyVisible', therapies.is_public_visible,
      'isAvailableForServices', therapies.is_available_for_services,
      'isVisibleInMatching', coalesce(matching_therapy_settings.is_visible_in_matching, false),
      'serviceCount', coalesce(service_counts.service_count, 0),
      'activeServiceCount', coalesce(service_counts.active_service_count, 0),
      'therapistCount', coalesce(service_counts.therapist_count, 0),
      'futureBookingCount', coalesce(booking_counts.future_booking_count, 0),
      'publicProfileCount', coalesce(profile_counts.public_profile_count, 0)
    )
    from public.therapies
    left join public.matching_therapy_settings
      on matching_therapy_settings.therapy_id = therapies.id
    left join lateral (
      select
        count(*)::integer as service_count,
        count(*) filter (
          where therapist_services.status = 'active'
            and therapist_services.is_bookable = true
        )::integer as active_service_count,
        count(distinct therapist_services.therapist_profile_id)::integer as therapist_count
      from public.therapist_services
      where therapist_services.therapy_id = therapies.id
    ) as service_counts on true
    left join lateral (
      select count(*)::integer as future_booking_count
      from public.bookings
      join public.therapist_services
        on therapist_services.id = bookings.service_id
      where therapist_services.therapy_id = therapies.id
        and bookings.starts_at >= now()
        and bookings.status in ('pending_payment', 'confirmed')
    ) as booking_counts on true
    left join lateral (
      select count(distinct therapist_profiles.id)::integer as public_profile_count
      from public.therapist_profiles
      join public.therapist_services
        on therapist_services.therapist_profile_id = therapist_profiles.id
      where therapist_services.therapy_id = therapies.id
        and therapist_profiles.status = 'approved'
        and therapist_profiles.is_public = true
        and therapist_services.status = 'active'
        and therapist_services.is_bookable = true
    ) as profile_counts on true
    where therapies.id = p_therapy_id
  );
end;
$$;


ALTER FUNCTION "public"."admin_therapy_impact_v1"("p_actor_user_id" "uuid", "p_therapy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_transition_matching_entity_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor public.profiles;
  v_old_state jsonb;
  v_next_state jsonb;
begin
  v_actor := public.admin_get_actor_profile_v1(p_actor_user_id);

  if p_request_id is null
    or p_entity_id is null
    or p_entity_type not in ('theme', 'interest')
    or p_action not in ('activate', 'deactivate')
    or length(btrim(coalesce(p_reason, ''))) < 4 then
    raise exception 'ADMIN_MATCHING_INVALID_PAYLOAD';
  end if;

  if p_entity_type = 'theme' then
    select to_jsonb(theme.*)
      into v_old_state
    from public.matching_themes as theme
    where theme.id = p_entity_id
    for update;

    if v_old_state is null then
      raise exception 'ADMIN_MATCHING_THEME_NOT_FOUND';
    end if;

    if p_action = 'deactivate' and exists (
      select 1
      from public.therapy_matching_themes as candidate
      join public.therapies
        on therapies.id = candidate.therapy_id
      left join public.matching_therapy_settings
        on matching_therapy_settings.therapy_id = therapies.id
      where candidate.theme_id = p_entity_id
        and therapies.status = 'published'
        and therapies.is_public_visible = true
        and coalesce(matching_therapy_settings.is_visible_in_matching, false) = true
        and (
          select count(*)::integer
          from public.therapy_matching_themes as sibling
          join public.matching_themes as sibling_theme
            on sibling_theme.id = sibling.theme_id
          where sibling.therapy_id = candidate.therapy_id
            and sibling.theme_id <> p_entity_id
            and sibling_theme.is_active = true
        ) = 0
    ) then
      raise exception 'ADMIN_MATCHING_THEME_DEACTIVATION_BLOCKED';
    end if;

    update public.matching_themes
    set
      is_active = p_action = 'activate',
      updated_at = now()
    where id = p_entity_id;

    select to_jsonb(theme.*)
      into v_next_state
    from public.matching_themes as theme
    where theme.id = p_entity_id;

    insert into public.therapy_catalog_events (
      actor_profile_id,
      actor_role,
      entity_type,
      entity_id,
      event_type,
      previous_state,
      next_state,
      reason,
      request_id
    )
    values (
      v_actor.id,
      v_actor.role,
      'matching_theme',
      p_entity_id,
      case when p_action = 'activate' then 'matching_theme_activated' else 'matching_theme_deactivated' end,
      v_old_state,
      v_next_state,
      p_reason,
      p_request_id
    );
  else
    select to_jsonb(interest.*)
      into v_old_state
    from public.matching_interests as interest
    where interest.id = p_entity_id
    for update;

    if v_old_state is null then
      raise exception 'ADMIN_MATCHING_INTEREST_NOT_FOUND';
    end if;

    update public.matching_interests
    set
      is_active = p_action = 'activate',
      updated_at = now()
    where id = p_entity_id;

    select to_jsonb(interest.*)
      into v_next_state
    from public.matching_interests as interest
    where interest.id = p_entity_id;

    insert into public.therapy_catalog_events (
      actor_profile_id,
      actor_role,
      entity_type,
      entity_id,
      event_type,
      previous_state,
      next_state,
      reason,
      request_id
    )
    values (
      v_actor.id,
      v_actor.role,
      'matching_interest',
      p_entity_id,
      case when p_action = 'activate' then 'matching_interest_activated' else 'matching_interest_deactivated' end,
      v_old_state,
      v_next_state,
      p_reason,
      p_request_id
    );
  end if;

  return public.admin_list_matching_v1(p_actor_user_id);
end;
$$;


ALTER FUNCTION "public"."admin_transition_matching_entity_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_transition_therapy_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_therapy_id" "uuid", "p_action" "text", "p_reason" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor public.profiles;
  v_old public.therapies;
  v_next public.therapies;
  v_impact jsonb;
begin
  v_actor := public.admin_get_actor_profile_v1(p_actor_user_id);

  select * into v_old
  from public.therapies
  where id = p_therapy_id
  for update;

  if v_old.id is null then
    raise exception 'ADMIN_THERAPY_CATALOG_NOT_FOUND';
  end if;

  if coalesce(trim(p_reason), '') = '' then
    raise exception 'ADMIN_THERAPY_CATALOG_REASON_REQUIRED';
  end if;

  v_impact := public.admin_therapy_impact_v1(p_actor_user_id, p_therapy_id);

  if p_action = 'review' then
    update public.therapies
    set status = 'in_review',
        updated_by_profile_id = v_actor.id,
        updated_at = now()
    where id = p_therapy_id;
  elsif p_action = 'publish' then
    perform public.admin_validate_therapy_publishable_v1(p_therapy_id);
    update public.therapies
    set status = 'published',
        published_at = now(),
        archived_at = null,
        updated_by_profile_id = v_actor.id,
        updated_at = now()
    where id = p_therapy_id;
  elsif p_action = 'unpublish' then
    update public.therapies
    set status = 'draft',
        published_at = null,
        updated_by_profile_id = v_actor.id,
        updated_at = now()
    where id = p_therapy_id;
  elsif p_action = 'deprecate' then
    update public.therapies
    set status = 'deprecated',
        is_available_for_services = false,
        replacement_therapy_id = nullif(p_payload->>'replacementTherapyId', '')::uuid,
        deprecated_at = now(),
        metadata = metadata || jsonb_build_object(
          'admin_message', nullif(p_payload->>'adminMessage', '')
        ),
        updated_by_profile_id = v_actor.id,
        updated_at = now()
    where id = p_therapy_id;
  elsif p_action = 'archive' then
    if (v_impact->>'activeServiceCount')::integer > 0
      or (v_impact->>'futureBookingCount')::integer > 0 then
      raise exception 'ADMIN_THERAPY_CATALOG_ARCHIVE_BLOCKED_BY_USAGE';
    end if;

    update public.therapies
    set status = 'archived',
        is_public_visible = false,
        is_available_for_services = false,
        archived_at = now(),
        updated_by_profile_id = v_actor.id,
        updated_at = now()
    where id = p_therapy_id;
  else
    raise exception 'ADMIN_THERAPY_CATALOG_INVALID_ACTION';
  end if;

  if p_action in ('deprecate', 'archive') then
    update public.matching_therapy_settings
    set is_visible_in_matching = false,
        updated_at = now()
    where therapy_id = p_therapy_id;
  end if;

  select * into v_next
  from public.therapies
  where id = p_therapy_id;

  insert into public.therapy_catalog_events (
    actor_profile_id,
    actor_role,
    entity_type,
    entity_id,
    event_type,
    previous_state,
    next_state,
    reason,
    request_id,
    metadata
  ) values (
    v_actor.id,
    v_actor.role,
    'therapy',
    p_therapy_id,
    'therapy_' || p_action,
    to_jsonb(v_old),
    to_jsonb(v_next),
    p_reason,
    p_request_id,
    jsonb_build_object('impactBefore', v_impact)
  );

  return jsonb_build_object(
    'contractVersion', 1,
    'therapyId', p_therapy_id,
    'impactBefore', v_impact,
    'catalog', public.admin_list_therapy_catalog_v1(p_actor_user_id)
  );
end;
$$;


ALTER FUNCTION "public"."admin_transition_therapy_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_therapy_id" "uuid", "p_action" "text", "p_reason" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_matching_interest_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor public.profiles;
  v_interest_id uuid;
  v_theme_id uuid := nullif(p_payload->>'themeId', '')::uuid;
  v_existing public.matching_interests%rowtype;
  v_old_state jsonb;
  v_next_state jsonb;
  v_name text := btrim(coalesce(p_payload->>'name', ''));
  v_slug text := btrim(coalesce(p_payload->>'slug', ''));
  v_sort_order integer := coalesce(nullif(p_payload->>'sortOrder', '')::integer, 0);
  v_reason text := btrim(coalesce(p_payload->>'reason', ''));
begin
  v_actor := public.admin_get_actor_profile_v1(p_actor_user_id);
  v_interest_id := nullif(p_payload->>'interestId', '')::uuid;

  if p_request_id is null
    or v_theme_id is null
    or length(v_name) < 2
    or v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
    or length(v_reason) < 4 then
    raise exception 'ADMIN_MATCHING_INVALID_PAYLOAD';
  end if;

  if not exists (
    select 1 from public.matching_themes
    where id = v_theme_id
      and is_active = true
  ) then
    raise exception 'ADMIN_MATCHING_THEME_NOT_FOUND';
  end if;

  if v_interest_id is not null then
    select * into v_existing
    from public.matching_interests
    where id = v_interest_id
    for update;

    if not found then
      raise exception 'ADMIN_MATCHING_INTEREST_NOT_FOUND';
    end if;

    if v_existing.theme_id <> v_theme_id then
      raise exception 'ADMIN_MATCHING_INTEREST_THEME_LOCKED';
    end if;

    if exists (
      select 1 from public.matching_interests
      where slug = v_slug
        and id <> v_interest_id
    ) then
      raise exception 'ADMIN_MATCHING_SLUG_CONFLICT';
    end if;

    v_old_state := to_jsonb(v_existing);

    update public.matching_interests
    set
      name = v_name,
      slug = v_slug,
      sort_order = v_sort_order,
      updated_at = now()
    where id = v_interest_id;
  else
    if exists (select 1 from public.matching_interests where slug = v_slug) then
      raise exception 'ADMIN_MATCHING_SLUG_CONFLICT';
    end if;

    insert into public.matching_interests (
      theme_id,
      name,
      slug,
      sort_order,
      is_active
    )
    values (
      v_theme_id,
      v_name,
      v_slug,
      v_sort_order,
      true
    )
    returning id into v_interest_id;

    v_old_state := null;
  end if;

  select to_jsonb(interest.*)
    into v_next_state
  from public.matching_interests as interest
  where interest.id = v_interest_id;

  insert into public.therapy_catalog_events (
    actor_profile_id,
    actor_role,
    entity_type,
    entity_id,
    event_type,
    previous_state,
    next_state,
    reason,
    request_id
  )
  values (
    v_actor.id,
    v_actor.role,
    'matching_interest',
    v_interest_id,
    case when v_old_state is null then 'matching_interest_created' else 'matching_interest_updated' end,
    v_old_state,
    v_next_state,
    v_reason,
    p_request_id
  );

  return public.admin_list_matching_v1(p_actor_user_id);
end;
$_$;


ALTER FUNCTION "public"."admin_upsert_matching_interest_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_matching_theme_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor public.profiles;
  v_theme_id uuid;
  v_existing public.matching_themes%rowtype;
  v_old_state jsonb;
  v_next_state jsonb;
  v_name text := btrim(coalesce(p_payload->>'name', ''));
  v_slug text := btrim(coalesce(p_payload->>'slug', ''));
  v_description text := btrim(coalesce(p_payload->>'description', ''));
  v_sort_order integer := coalesce(nullif(p_payload->>'sortOrder', '')::integer, 0);
  v_reason text := btrim(coalesce(p_payload->>'reason', ''));
begin
  v_actor := public.admin_get_actor_profile_v1(p_actor_user_id);
  v_theme_id := nullif(p_payload->>'themeId', '')::uuid;

  if p_request_id is null
    or length(v_name) < 2
    or v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
    or length(v_description) < 4
    or length(v_reason) < 4 then
    raise exception 'ADMIN_MATCHING_INVALID_PAYLOAD';
  end if;

  if v_theme_id is not null then
    select * into v_existing
    from public.matching_themes
    where id = v_theme_id
    for update;

    if not found then
      raise exception 'ADMIN_MATCHING_THEME_NOT_FOUND';
    end if;

    if exists (
      select 1 from public.matching_themes
      where slug = v_slug
        and id <> v_theme_id
    ) then
      raise exception 'ADMIN_MATCHING_SLUG_CONFLICT';
    end if;

    v_old_state := to_jsonb(v_existing);

    update public.matching_themes
    set
      name = v_name,
      slug = v_slug,
      description = v_description,
      image_url = nullif(p_payload->>'imageUrl', ''),
      sort_order = v_sort_order,
      updated_at = now()
    where id = v_theme_id;
  else
