      v_slug,
      v_description,
      nullif(p_payload->>'imageUrl', ''),
      v_sort_order,
      true
    )
    returning id into v_theme_id;

    v_old_state := null;
  end if;

  select to_jsonb(theme.*)
    into v_next_state
  from public.matching_themes as theme
  where theme.id = v_theme_id;

  insert into public.therapy_catalog_events (
    actor_profile_id,
    actor_role,
    entity_type,
    entity_id,
    event_type,
    previous_state,
    next_state,
    reason,
    request_id
  )
  values (
    v_actor.id,
    v_actor.role,
    'matching_theme',
    v_theme_id,
    case when v_old_state is null then 'matching_theme_created' else 'matching_theme_updated' end,
    v_old_state,
    v_next_state,
    v_reason,
    p_request_id
  );

  return public.admin_list_matching_v1(p_actor_user_id);
end;
$_$;


ALTER FUNCTION "public"."admin_upsert_matching_theme_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_therapy_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor public.profiles;
  v_therapy_id uuid;
  v_existing public.therapies;
  v_old_slug text;
  v_old_state jsonb;
  v_slug text;
  v_name text;
  v_short_description text;
  v_now timestamptz := now();
  v_next_state jsonb;
  v_theme_ids uuid[] := '{}'::uuid[];
  v_theme_input_count integer := 0;
  v_valid_theme_count integer := 0;
begin
  v_actor := public.admin_get_actor_profile_v1(p_actor_user_id);
  v_therapy_id := nullif(p_payload->>'therapyId', '')::uuid;
  v_name := trim(coalesce(p_payload->>'name', ''));
  v_slug := trim(coalesce(p_payload->>'slug', ''));
  v_short_description := trim(coalesce(p_payload->>'shortDescription', ''));

  if p_payload ? 'faqs' then
    raise exception 'ADMIN_THERAPY_CATALOG_FAQ_REMOVED';
  end if;

  if p_request_id is null
    or v_name = ''
    or v_slug = ''
    or v_short_description = ''
    or jsonb_typeof(p_payload->'themeIds') <> 'array' then
    raise exception 'ADMIN_THERAPY_CATALOG_INVALID_PAYLOAD';
  end if;

  with raw as (
    select trim(value) as id_text, ordinality
    from jsonb_array_elements_text(p_payload->'themeIds')
      with ordinality as item(value, ordinality)
  ), validated as (
    select id_text::uuid as id, ordinality
    from raw
    where id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  )
  select
    (select count(*) from raw),
    coalesce(array_agg(validated.id order by validated.ordinality), '{}'::uuid[]),
    count(distinct theme.id)::integer
  into v_theme_input_count, v_theme_ids, v_valid_theme_count
  from validated
  left join public.matching_themes theme
    on theme.id = validated.id
   and theme.is_active;

  if v_theme_input_count < 1 or v_theme_input_count > 3 then
    raise exception 'ADMIN_THERAPY_CATALOG_INVALID_THEME_LIMIT';
  end if;

  if cardinality(v_theme_ids) <> v_theme_input_count
    or v_valid_theme_count <> v_theme_input_count then
    raise exception 'ADMIN_THERAPY_CATALOG_INVALID_THEME';
  end if;

  perform public.admin_assert_therapy_content_lengths_v1(p_payload);

  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then
    raise exception 'ADMIN_THERAPY_CATALOG_INVALID_SLUG';
  end if;

  perform public.admin_assert_responsible_therapy_text_v1(
    concat_ws(
      ' ',
      v_name,
      v_short_description,
      p_payload->>'description',
      p_payload#>>'{publicContent,introduction}',
      p_payload#>>'{publicContent,complementaryDescription}',
      p_payload#>>'{publicContent,safetyNote}'
    )
  );

  if v_therapy_id is not null then
    select * into v_existing
    from public.therapies
    where id = v_therapy_id
    for update;

    if v_existing.id is null then
      raise exception 'ADMIN_THERAPY_CATALOG_NOT_FOUND';
    end if;

    v_old_slug := v_existing.slug;
    v_old_state := to_jsonb(v_existing);

    if exists (
      select 1
      from public.therapies
      where slug = v_slug and id <> v_therapy_id
    ) then
      raise exception 'ADMIN_THERAPY_CATALOG_SLUG_CONFLICT';
    end if;

    update public.therapies
    set
      name = v_name,
      slug = v_slug,
      short_description = v_short_description,
      description = nullif(p_payload->>'description', ''),
      image_url = nullif(p_payload->>'imageUrl', ''),
      search_aliases = coalesce(array(
        select trim(value)::text
        from jsonb_array_elements_text(coalesce(p_payload->'aliases', '[]'::jsonb)) value
        where trim(value) <> ''
      ), '{}'::text[]),
      is_public_visible = coalesce((p_payload->>'isPubliclyVisible')::boolean, is_public_visible),
      is_available_for_services = coalesce((p_payload->>'isAvailableForServices')::boolean, is_available_for_services),
      is_featured = coalesce((p_payload->>'isFeatured')::boolean, is_featured),
      calendar_color_key = coalesce(nullif(p_payload->>'calendarColorKey', ''), calendar_color_key),
      updated_by_profile_id = v_actor.id,
      updated_at = v_now
    where id = v_therapy_id;

    if v_old_slug <> v_slug then
      insert into public.therapy_slug_redirects (
        old_slug, current_slug, therapy_id, created_by_profile_id
      ) values (
        v_old_slug, v_slug, v_therapy_id, v_actor.id
      )
      on conflict (old_slug) do update set
        current_slug = excluded.current_slug,
        therapy_id = excluded.therapy_id,
        created_by_profile_id = excluded.created_by_profile_id;
    end if;
  else
    if exists (select 1 from public.therapies where slug = v_slug) then
      raise exception 'ADMIN_THERAPY_CATALOG_SLUG_CONFLICT';
    end if;

    insert into public.therapies (
      name,
      slug,
      short_description,
      description,
      status,
      is_public_visible,
      is_available_for_services,
      is_featured,
      image_url,
      search_aliases,
      calendar_color_key,
      created_by_profile_id,
      updated_by_profile_id
    ) values (
      v_name,
      v_slug,
      v_short_description,
      nullif(p_payload->>'description', ''),
      'draft',
      coalesce((p_payload->>'isPubliclyVisible')::boolean, false),
      coalesce((p_payload->>'isAvailableForServices')::boolean, false),
      coalesce((p_payload->>'isFeatured')::boolean, false),
      nullif(p_payload->>'imageUrl', ''),
      coalesce(array(
        select trim(value)::text
        from jsonb_array_elements_text(coalesce(p_payload->'aliases', '[]'::jsonb)) value
        where trim(value) <> ''
      ), '{}'::text[]),
      coalesce(nullif(p_payload->>'calendarColorKey', ''), 'neutral'),
      v_actor.id,
      v_actor.id
    )
    returning id into v_therapy_id;

    v_old_state := null;
  end if;

  insert into public.therapy_public_content (
    therapy_id,
    hero_image_url,
    subtitle,
    introduction,
    complementary_description,
    safety_note,
    seo_title,
    seo_description,
    approach_label,
    approach_icon_key,
    visual_theme_key,
    hero_focal_point
  ) values (
    v_therapy_id,
    nullif(p_payload#>>'{publicContent,heroImageUrl}', ''),
    nullif(p_payload#>>'{publicContent,subtitle}', ''),
    nullif(p_payload#>>'{publicContent,introduction}', ''),
    nullif(p_payload#>>'{publicContent,complementaryDescription}', ''),
    nullif(p_payload#>>'{publicContent,safetyNote}', ''),
    nullif(p_payload#>>'{publicContent,seoTitle}', ''),
    nullif(p_payload#>>'{publicContent,seoDescription}', ''),
    nullif(p_payload#>>'{publicContent,approachLabel}', ''),
    nullif(p_payload#>>'{publicContent,approachIconKey}', ''),
    coalesce(nullif(p_payload#>>'{publicContent,visualThemeKey}', ''), 'energy')::public.therapy_visual_theme_key,
    coalesce(nullif(p_payload#>>'{publicContent,heroFocalPoint}', ''), 'center')
  )
  on conflict (therapy_id) do update set
    hero_image_url = excluded.hero_image_url,
    subtitle = excluded.subtitle,
    introduction = excluded.introduction,
    complementary_description = excluded.complementary_description,
    safety_note = excluded.safety_note,
    seo_title = excluded.seo_title,
    seo_description = excluded.seo_description,
    approach_label = excluded.approach_label,
    approach_icon_key = excluded.approach_icon_key,
    visual_theme_key = excluded.visual_theme_key,
    hero_focal_point = excluded.hero_focal_point,
    updated_at = v_now;

  insert into public.matching_therapy_settings (therapy_id, is_visible_in_matching)
  values (
    v_therapy_id,
    coalesce((p_payload->>'isVisibleInMatching')::boolean, false)
  )
  on conflict (therapy_id) do update set
    is_visible_in_matching = excluded.is_visible_in_matching,
    updated_at = v_now;

  if p_payload ? 'highlights' then
    delete from public.therapy_highlights where therapy_id = v_therapy_id;
    insert into public.therapy_highlights (therapy_id, title, icon_key, sort_order)
    select
      v_therapy_id,
      trim(item->>'title'),
      coalesce(nullif(trim(item->>'iconKey'), ''), 'sparkles'),
      ordinality::integer
    from jsonb_array_elements(coalesce(p_payload->'highlights', '[]'::jsonb))
      with ordinality as items(item, ordinality)
    where trim(item->>'title') <> '';
  end if;

  if p_payload ? 'benefits' then
    delete from public.therapy_benefits where therapy_id = v_therapy_id;
    insert into public.therapy_benefits (therapy_id, title, description, icon_key, sort_order)
    select
      v_therapy_id,
      trim(item->>'title'),
      nullif(trim(item->>'description'), ''),
      coalesce(nullif(trim(item->>'iconKey'), ''), 'sparkles'),
      ordinality::integer
    from jsonb_array_elements(coalesce(p_payload->'benefits', '[]'::jsonb))
      with ordinality as items(item, ordinality)
    where trim(item->>'title') <> '';
  end if;

  select to_jsonb(therapy.*) into v_next_state
  from public.therapies therapy
  where therapy.id = v_therapy_id;

  insert into public.therapy_catalog_events (
    actor_profile_id,
    actor_role,
    entity_type,
    entity_id,
    event_type,
    previous_state,
    next_state,
    reason,
    request_id
  ) values (
    v_actor.id,
    v_actor.role,
    'therapy',
    v_therapy_id,
    case when v_old_state is null then 'therapy_draft_created' else 'therapy_edited' end,
    v_old_state,
    v_next_state,
    nullif(p_payload->>'reason', ''),
    p_request_id
  );

  return jsonb_build_object(
    'contractVersion', 1,
    'therapyId', v_therapy_id,
    'catalog', public.admin_replace_therapy_matching_themes_v1(
      p_actor_user_id,
      p_request_id,
      v_therapy_id,
      v_theme_ids,
      p_payload->>'reason'
    )
  );
end;
$_$;


ALTER FUNCTION "public"."admin_upsert_therapy_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_therapy_draft_with_matching_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return public.admin_upsert_therapy_draft_v1(
    p_actor_user_id,
    p_request_id,
    p_payload
  );
end;
$$;


ALTER FUNCTION "public"."admin_upsert_therapy_draft_with_matching_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_validate_therapy_publishable_v1"("p_therapy_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare v_row record;
begin
  select t.*, coalesce(c.hero_image_url,t.image_url) as effective_image_url, c.introduction,
    (select count(*) from public.therapy_highlights h where h.therapy_id=t.id) as highlight_count,
    (select count(*) from public.therapy_benefits b where b.therapy_id=t.id) as benefit_count
  into v_row from public.therapies t left join public.therapy_public_content c on c.therapy_id=t.id where t.id=p_therapy_id;
  if v_row.id is null then raise exception 'ADMIN_THERAPY_CATALOG_NOT_FOUND'; end if;
  if v_row.slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'ADMIN_THERAPY_CATALOG_INVALID_SLUG'; end if;
  if coalesce(v_row.short_description,'')='' or coalesce(v_row.introduction,v_row.description,'')='' or coalesce(v_row.effective_image_url,'')='' or v_row.highlight_count<1 or v_row.benefit_count<1 then raise exception 'ADMIN_THERAPY_CATALOG_INCOMPLETE_PUBLIC_CONTENT'; end if;
  perform public.ensure_therapy_has_matching_theme_for_publish_v1(p_therapy_id);
end; $_$;


ALTER FUNCTION "public"."admin_validate_therapy_publishable_v1"("p_therapy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_patient_booking_reschedule_v1"("p_booking_id" "uuid", "p_actor_profile_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_proposed_ends_at" timestamp with time zone, "p_proposed_timezone" "text", "p_reason" "text", "p_request_id" "text", "p_expected_booking_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_existing public.booking_reschedule_requests%rowtype;
  v_request public.booking_reschedule_requests%rowtype;
begin
  if length(trim(coalesce(p_request_id, ''))) not between 8 and 200 then
    raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode = '22023';
  end if;

  if p_proposed_starts_at is null
    or p_proposed_ends_at is null
    or p_proposed_starts_at >= p_proposed_ends_at
    or p_proposed_starts_at <= now()
  then
    raise exception 'INVALID_AVAILABILITY_RANGE' using errcode = '22023';
  end if;

  if not public.is_valid_timezone_v1(p_proposed_timezone) then
    raise exception 'INVALID_TIMEZONE' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-reschedule-request:' || trim(p_request_id),
      0
    )
  );

  select *
  into v_existing
  from public.booking_reschedule_requests
  where request_id = trim(p_request_id)
  for update;

  if found then
    if v_existing.booking_id <> p_booking_id
      or v_existing.requested_by_profile_id <> p_actor_profile_id
      or v_existing.proposed_starts_at <> p_proposed_starts_at
      or v_existing.proposed_ends_at <> p_proposed_ends_at
      or v_existing.proposed_timezone <> p_proposed_timezone
      or v_existing.status <> 'applied'
    then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;

    select * into v_booking
    from public.bookings
    where id = v_existing.booking_id;

    return pg_catalog.jsonb_build_object(
      'applied', true,
      'bookingId', v_booking.id,
      'bookingVersion', v_booking.version,
      'rescheduleRequestId', v_existing.id,
      'status', v_existing.status
    );
  end if;

  select booking.*
  into v_booking
  from public.bookings as booking
  join public.patient_profiles as patient
    on patient.id = booking.patient_profile_id
  where booking.id = p_booking_id
    and patient.user_id = p_actor_profile_id
  for update of booking;

  if not found then
    raise exception 'BOOKING_ACTOR_NOT_PATIENT' using errcode = '42501';
  end if;

  if v_booking.status <> 'confirmed' then
    raise exception 'BOOKING_CANNOT_BE_RESCHEDULED' using errcode = 'P0001';
  end if;

  if p_expected_booking_version is not null
    and p_expected_booking_version <> v_booking.version
  then
    raise exception 'BOOKING_VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  if p_proposed_timezone <> v_booking.timezone
    or p_proposed_ends_at <> p_proposed_starts_at
      + v_booking.service_duration_minutes_snapshot * interval '1 minute'
    or p_proposed_starts_at = v_booking.starts_at
  then
    raise exception 'INVALID_AVAILABILITY_RANGE' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.booking_reschedule_requests as pending
    where pending.booking_id = v_booking.id
      and pending.status = 'pending'
  ) then
    raise exception 'BOOKING_RESCHEDULE_ALREADY_PENDING' using errcode = 'P0001';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_booking.therapist_profile_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-schedule:' || v_booking.patient_profile_id::text,
      0
    )
  );
  perform public.expire_booking_holds_v1(now(), v_booking.therapist_profile_id);

  insert into public.booking_reschedule_requests (
    booking_id,
    requested_by_profile_id,
    original_starts_at,
    original_ends_at,
    original_timezone,
    proposed_starts_at,
    proposed_ends_at,
    proposed_timezone,
    reason,
    status,
    request_id,
    resolution_request_id,
    resolved_by_profile_id,
    booking_version_at_request,
    expires_at,
    resolved_at,
    applied_at
  ) values (
    v_booking.id,
    p_actor_profile_id,
    v_booking.starts_at,
    v_booking.ends_at,
    v_booking.timezone,
    p_proposed_starts_at,
    p_proposed_ends_at,
    p_proposed_timezone,
    nullif(left(trim(coalesce(p_reason, '')), 500), ''),
    'applied',
    trim(p_request_id),
    trim(p_request_id),
    p_actor_profile_id,
    v_booking.version,
    now(),
    now(),
    now()
  )
  returning * into v_request;

  perform pg_catalog.set_config(
    'tes.booking_actor_profile_id', p_actor_profile_id::text, true
  );
  perform pg_catalog.set_config(
    'tes.booking_reason', left(coalesce(v_request.reason, ''), 500), true
  );
  perform pg_catalog.set_config(
    'tes.booking_request_id', trim(p_request_id), true
  );
  perform pg_catalog.set_config(
    'tes.booking_source', 'reschedule_resolution', true
  );

  begin
    update public.bookings
    set starts_at = v_request.proposed_starts_at,
        ends_at = v_request.proposed_ends_at,
        timezone = v_request.proposed_timezone,
        updated_at = now()
    where id = v_booking.id
    returning * into v_booking;
  exception
    when exclusion_violation then
      raise exception 'BOOKING_CONFLICT' using errcode = 'P0001';
  end;

  perform public.sync_booking_video_session_from_agenda_v1(
    v_booking.id,
    'update',
    p_request_id
  );

  perform pg_catalog.set_config('tes.booking_actor_profile_id', '', true);
  perform pg_catalog.set_config('tes.booking_reason', '', true);
  perform pg_catalog.set_config('tes.booking_request_id', '', true);
  perform pg_catalog.set_config('tes.booking_source', '', true);

  insert into public.booking_events (
    booking_id,
    actor_profile_id,
    event_type,
    request_id,
    source,
    previous_status,
    next_status,
    payload
  ) values (
    v_booking.id,
    p_actor_profile_id,
    'booking_reschedule_resolved',
    trim(p_request_id),
    'agenda_patient_direct',
    v_booking.status,
    v_booking.status,
    pg_catalog.jsonb_build_object(
      'rescheduleRequestId', v_request.id,
      'resolution', 'accepted',
      'status', 'applied'
    )
  )
  on conflict do nothing;

  return pg_catalog.jsonb_build_object(
    'applied', true,
    'bookingId', v_booking.id,
    'bookingVersion', v_booking.version,
    'rescheduleRequestId', v_request.id,
    'status', v_request.status
  );
end;
$$;


ALTER FUNCTION "public"."apply_patient_booking_reschedule_v1"("p_booking_id" "uuid", "p_actor_profile_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_proposed_ends_at" timestamp with time zone, "p_proposed_timezone" "text", "p_reason" "text", "p_request_id" "text", "p_expected_booking_version" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_patient_booking_reschedule_v1"("p_booking_id" "uuid", "p_actor_profile_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_proposed_ends_at" timestamp with time zone, "p_proposed_timezone" "text", "p_reason" "text", "p_request_id" "text", "p_expected_booking_version" integer) IS 'Atomically applies a patient-initiated reschedule to the same confirmed booking after current authoritative availability, buffer, hold, and patient-conflict validation.';



CREATE OR REPLACE FUNCTION "public"."apply_session_payment_state_v1"("p_session_payment_id" "uuid", "p_financial_status" "public"."session_financial_status", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_payment_intent_id" "text" DEFAULT NULL::"text", "p_stripe_charge_id" "text" DEFAULT NULL::"text", "p_stripe_checkout_session_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_booking_status public.booking_status;
  v_applied boolean := false;
  v_now timestamptz := now();
begin
  select *
    into v_payment
  from public.session_payments
  where id = p_session_payment_id
  for update;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'payment_not_found');
  end if;

  if v_payment.stripe_event_created_at is not null
    and p_stripe_event_created_at < v_payment.stripe_event_created_at then
    return jsonb_build_object(
      'applied', false,
      'reason', 'stale_event',
      'financialStatus', v_payment.financial_status
    );
  end if;

  v_applied := case
    when p_financial_status = 'paid'
      then v_payment.financial_status in ('pending', 'processing', 'failed', 'canceled', 'paid')
    when p_financial_status = 'processing'
      then v_payment.financial_status in ('pending', 'processing')
    when p_financial_status in ('failed', 'canceled')
      then v_payment.financial_status in ('pending', 'processing', p_financial_status)
    else false
  end;

  if not v_applied then
    return jsonb_build_object(
      'applied', false,
      'reason', 'transition_blocked',
      'financialStatus', v_payment.financial_status
    );
  end if;

  update public.session_payments
  set financial_status = p_financial_status,
      stripe_event_id = p_stripe_event_id,
      stripe_event_created_at = p_stripe_event_created_at,
      stripe_payment_intent_id = coalesce(
        p_stripe_payment_intent_id,
        stripe_payment_intent_id
      ),
      stripe_charge_id = coalesce(p_stripe_charge_id, stripe_charge_id),
      stripe_checkout_session_id = coalesce(
        p_stripe_checkout_session_id,
        stripe_checkout_session_id
      ),
      paid_at = case
        when p_financial_status = 'paid' then coalesce(paid_at, p_stripe_event_created_at)
        else paid_at
      end,
      failed_at = case
        when p_financial_status = 'failed' then p_stripe_event_created_at
        when p_financial_status = 'paid' then null
        else failed_at
      end,
      canceled_at = case
        when p_financial_status = 'canceled' then p_stripe_event_created_at
        when p_financial_status = 'paid' then null
        else canceled_at
      end,
      updated_at = v_now
  where id = v_payment.id
  returning * into v_payment;

  select status
    into v_booking_status
  from public.bookings
  where id = v_payment.booking_id;

  if p_financial_status = 'paid' then
    update public.bookings
    set payment_status = 'paid',
        status = case
          when status in ('draft', 'pending_payment') then 'confirmed'
          else status
        end,
        updated_at = v_now
    where id = v_payment.booking_id;

    if v_booking_status in (
      'cancelled_by_patient',
      'cancelled_by_therapist',
      'refunded'
    ) then
      update public.session_payments
      set transfer_status = 'blocked',
          transfer_blocked_reason = 'paid_after_booking_closed',
          updated_at = v_now
      where id = v_payment.id;
    end if;

    update public.payments
    set status = 'paid',
        stripe_payment_intent_id = coalesce(
          p_stripe_payment_intent_id,
          stripe_payment_intent_id
        ),
        stripe_checkout_session_id = coalesce(
          p_stripe_checkout_session_id,
          stripe_checkout_session_id
        ),
        paid_at = coalesce(paid_at, p_stripe_event_created_at),
        updated_at = v_now
    where booking_id = v_payment.booking_id;

    insert into public.financial_ledger_entries (
      entry_type,
      direction,
      amount_cents,
      patient_profile_id,
      therapist_profile_id,
      booking_id,
      session_payment_id,
      stripe_event_id,
      source_table,
      source_id,
      occurred_at
    )
    select entry_type, direction, amount_cents,
      v_payment.patient_profile_id,
      v_payment.therapist_profile_id,
      v_payment.booking_id,
      v_payment.id,
      p_stripe_event_id,
      'session_payments',
      v_payment.id,
      p_stripe_event_created_at
    from (
      values
        (
          'session_gross_payment'::public.financial_ledger_entry_type,
          'credit'::public.financial_ledger_direction,
          v_payment.gross_amount_cents
        ),
        (
          'therapist_payable'::public.financial_ledger_entry_type,
          'credit'::public.financial_ledger_direction,
          v_payment.therapist_amount_cents
        ),
        (
          'platform_gross_commission'::public.financial_ledger_entry_type,
          'credit'::public.financial_ledger_direction,
          v_payment.platform_gross_commission_cents
        )
    ) as entries(entry_type, direction, amount_cents)
    where amount_cents > 0
    on conflict do nothing;

    perform public.refresh_session_transfer_eligibility(v_payment.id);
  elsif p_financial_status = 'processing' then
    update public.bookings
    set payment_status = 'pending',
        status = case when status = 'draft' then 'pending_payment' else status end,
        updated_at = v_now
    where id = v_payment.booking_id;

    update public.payments
    set status = 'pending',
        updated_at = v_now
    where booking_id = v_payment.booking_id
      and status <> 'paid';
  else
    update public.bookings
    set payment_status = case
          when p_financial_status = 'canceled' then 'cancelled'::public.payment_status
          else 'failed'::public.payment_status
        end,
        updated_at = v_now
    where id = v_payment.booking_id
      and payment_status <> 'paid';

    update public.payments
    set status = case
          when p_financial_status = 'canceled' then 'cancelled'::public.payment_status
          else 'failed'::public.payment_status
        end,
        updated_at = v_now
    where booking_id = v_payment.booking_id
      and status <> 'paid';
  end if;

  update public.session_payment_attempts
  set status = p_financial_status::text,
      stripe_payment_intent_id = coalesce(
        p_stripe_payment_intent_id,
        stripe_payment_intent_id
      ),
      updated_at = v_now
  where session_payment_id = v_payment.id
    and (
      p_stripe_checkout_session_id is null
      or stripe_checkout_session_id = p_stripe_checkout_session_id
    );

  return jsonb_build_object(
    'applied', true,
    'financialStatus', p_financial_status,
    'sessionPaymentId', v_payment.id
  );
end;
$$;


ALTER FUNCTION "public"."apply_session_payment_state_v1"("p_session_payment_id" "uuid", "p_financial_status" "public"."session_financial_status", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_stripe_checkout_session_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_session_payment_state_v1"("p_session_payment_id" "uuid", "p_financial_status" "public"."session_financial_status", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_stripe_checkout_session_id" "text") IS 'Aplica transicao financeira de sessao sem regressao por evento antigo e espelha projecoes legadas.';



CREATE OR REPLACE FUNCTION "public"."apply_stripe_payout_state_v1"("p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_provider_status" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_payout_batch_therapist_id" "uuid" DEFAULT NULL::"uuid", "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_message" "text" DEFAULT NULL::"text", "p_arrival_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payout public.stripe_payouts%rowtype;
  v_was_paid boolean;
  v_batch_status public.payout_batch_status;
  v_nonterminal_count integer;
begin
  if nullif(trim(p_stripe_payout_id), '') is null
    or nullif(trim(p_stripe_account_id), '') is null
    or p_provider_status not in ('pending', 'in_transit', 'paid', 'failed', 'canceled')
    or nullif(trim(p_stripe_event_id), '') is null
    or p_stripe_event_created_at is null
  then
    raise exception 'STRIPE_PAYOUT_EVENT_INVALID';
  end if;

  select payout.* into v_payout
  from public.stripe_payouts payout
  join public.therapist_connect_accounts account on account.id = payout.connect_account_id
  where account.stripe_account_id = p_stripe_account_id
    and (
      payout.stripe_payout_id = p_stripe_payout_id
      or (
        payout.stripe_payout_id is null
        and payout.payout_batch_therapist_id = p_payout_batch_therapist_id
      )
    )
  order by payout.created_at
  limit 1
  for update of payout;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'payout_not_found');
  end if;

  if v_payout.stripe_event_created_at is not null
    and p_stripe_event_created_at < v_payout.stripe_event_created_at
  then
    return jsonb_build_object('applied', false, 'reason', 'stale_event');
  end if;

  v_was_paid := v_payout.status = 'paid';

  update public.stripe_payouts
  set stripe_payout_id = coalesce(stripe_payout_id, p_stripe_payout_id),
      provider_status = p_provider_status,
      status = case p_provider_status
        when 'in_transit' then 'in_transit'::public.stripe_payout_status
        when 'paid' then 'paid'::public.stripe_payout_status
        when 'failed' then 'failed'::public.stripe_payout_status
        when 'canceled' then 'canceled'::public.stripe_payout_status
        else 'pending'::public.stripe_payout_status
      end,
      failure_code = left(nullif(regexp_replace(coalesce(p_failure_code, ''), '[\r\n]+', ' ', 'g'), ''), 120),
      failure_message = left(nullif(regexp_replace(coalesce(p_failure_message, ''), '[\r\n]+', ' ', 'g'), ''), 500),
      stripe_event_id = p_stripe_event_id,
      stripe_event_created_at = p_stripe_event_created_at,
      arrival_at = coalesce(p_arrival_at, arrival_at),
      paid_at = case when p_provider_status = 'paid' then coalesce(paid_at, p_stripe_event_created_at) else paid_at end,
      failed_at = case when p_provider_status = 'failed' then p_stripe_event_created_at else failed_at end,
      lease_owner = null, lease_expires_at = null, next_retry_at = null,
      updated_at = now()
  where id = v_payout.id
  returning * into v_payout;

  if p_provider_status = 'failed' then
    perform public.record_payout_operational_incident_v1(
      'payout:' || v_payout.id::text || ':provider_failed',
      case when v_was_paid then 'payout_failed_after_paid' else 'payout_failed' end,
      'critical', p_failure_code, p_failure_message, null,
      v_payout.payout_batch_id, null, null, v_payout.id,
      v_payout.therapist_profile_id,
      jsonb_build_object('failedAfterPaid', v_was_paid)
    );
  end if;

  select case
    when bool_and(coalesce(payout.status = 'paid', false)) then 'completed'::public.payout_batch_status
    when bool_or(coalesce(payout.status in ('failed', 'canceled', 'reconciliation_required'), false))
      then 'partially_failed'::public.payout_batch_status
    else 'processing'::public.payout_batch_status
  end into v_batch_status
  from public.payout_batch_therapists therapist_group
  left join public.stripe_payouts payout
    on payout.payout_batch_therapist_id = therapist_group.id
  where therapist_group.payout_batch_id = v_payout.payout_batch_id
    and therapist_group.total_amount_cents > 0;

  select count(*) into v_nonterminal_count
  from public.payout_batch_therapists therapist_group
  left join public.stripe_payouts payout
    on payout.payout_batch_therapist_id = therapist_group.id
  where therapist_group.payout_batch_id = v_payout.payout_batch_id
    and therapist_group.total_amount_cents > 0
    and coalesce(payout.status::text, 'missing') in (
      'missing', 'pending_balance', 'creating', 'pending', 'in_transit'
    );

  update public.payout_batches
  set status = v_batch_status,
      processed_at = case when v_batch_status = 'completed' then now() else null end,
      updated_at = now()
  where id = v_payout.payout_batch_id;

  update public.payout_scheduler_runs run
  set status = case
        when v_nonterminal_count = 0 and v_batch_status = 'completed'
          then 'completed'::public.payout_scheduler_run_status
        when v_nonterminal_count = 0 and v_batch_status = 'partially_failed'
          then 'completed_with_incidents'::public.payout_scheduler_run_status
        else run.status
      end,
      completed_at = case when v_nonterminal_count = 0 then now() else run.completed_at end,
      worker_id = case when v_nonterminal_count = 0 then null else run.worker_id end,
      lease_expires_at = case when v_nonterminal_count = 0 then null else run.lease_expires_at end,
      updated_at = now()
  where run.payout_batch_id = v_payout.payout_batch_id;

  return jsonb_build_object(
    'applied', true,
    'payoutId', v_payout.id,
    'status', v_payout.status,
    'failedAfterPaid', v_was_paid and p_provider_status = 'failed'
  );
end;
$$;


ALTER FUNCTION "public"."apply_stripe_payout_state_v1"("p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_provider_status" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_payout_batch_therapist_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_arrival_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_therapist_subscription_event_v1"("p_therapist_profile_id" "uuid", "p_stripe_subscription_id" "text", "p_plan_code" "public"."therapist_plan", "p_status" "public"."billing_subscription_status", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_customer_id" "uuid" DEFAULT NULL::"uuid", "p_billing_plan_id" "uuid" DEFAULT NULL::"uuid", "p_billing_plan_price_id" "uuid" DEFAULT NULL::"uuid", "p_stripe_checkout_session_id" "text" DEFAULT NULL::"text", "p_stripe_latest_invoice_id" "text" DEFAULT NULL::"text", "p_current_period_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_current_period_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cancel_at_period_end" boolean DEFAULT false, "p_canceled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ended_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_subscription public.therapist_subscriptions%rowtype;
  v_previous_plan public.therapist_plan;
  v_previous_status text;
  v_active_plan public.therapist_plan;
  v_applied boolean := false;
begin
  select *
    into v_subscription
  from public.therapist_subscriptions
  where stripe_subscription_id = p_stripe_subscription_id
  for update;

  v_previous_plan := v_subscription.plan_code;
  v_previous_status := v_subscription.status::text;

  if v_subscription.id is null then
    insert into public.therapist_subscriptions (
      therapist_profile_id,
      stripe_customer_id,
      billing_plan_id,
      billing_plan_price_id,
      plan_code,
      status,
      stripe_subscription_id,
      stripe_checkout_session_id,
      stripe_latest_invoice_id,
      current_period_start,
      current_period_end,
      cancel_at_period_end,
      canceled_at,
      ended_at,
      stripe_event_created_at,
      metadata
    ) values (
      p_therapist_profile_id,
      p_stripe_customer_id,
      p_billing_plan_id,
      p_billing_plan_price_id,
      p_plan_code,
      p_status,
      p_stripe_subscription_id,
      p_stripe_checkout_session_id,
      p_stripe_latest_invoice_id,
      p_current_period_start,
      p_current_period_end,
      p_cancel_at_period_end,
      p_canceled_at,
      p_ended_at,
      p_stripe_event_created_at,
      p_metadata
    )
    returning * into v_subscription;
    v_applied := true;
  elsif v_subscription.stripe_event_created_at is null
    or p_stripe_event_created_at >= v_subscription.stripe_event_created_at then
    update public.therapist_subscriptions
    set stripe_customer_id = coalesce(p_stripe_customer_id, stripe_customer_id),
        billing_plan_id = coalesce(p_billing_plan_id, billing_plan_id),
        billing_plan_price_id = coalesce(
          p_billing_plan_price_id,
          billing_plan_price_id
        ),
        plan_code = p_plan_code,
        status = p_status,
        stripe_checkout_session_id = coalesce(
          p_stripe_checkout_session_id,
          stripe_checkout_session_id
        ),
        stripe_latest_invoice_id = p_stripe_latest_invoice_id,
        current_period_start = p_current_period_start,
        current_period_end = p_current_period_end,
        cancel_at_period_end = p_cancel_at_period_end,
        canceled_at = p_canceled_at,
        ended_at = p_ended_at,
        stripe_event_created_at = p_stripe_event_created_at,
        metadata = p_metadata,
        updated_at = now()
    where id = v_subscription.id
    returning * into v_subscription;
    v_applied := true;
  end if;

  if v_applied then
    insert into public.therapist_subscription_events (
      therapist_subscription_id,
      therapist_profile_id,
      stripe_event_id,
      event_type,
      previous_plan,
      next_plan,
      previous_status,
      next_status,
      metadata
    ) values (
      v_subscription.id,
      p_therapist_profile_id,
      p_stripe_event_id,
      'stripe_subscription_sync',
      v_previous_plan,
      p_plan_code,
      v_previous_status,
      p_status::text,
      jsonb_build_object('stripeEventCreatedAt', p_stripe_event_created_at)
    )
    on conflict (stripe_event_id) where stripe_event_id is not null do nothing;
  end if;

  select plan_code
    into v_active_plan
  from public.therapist_subscriptions
  where therapist_profile_id = p_therapist_profile_id
    and status in ('active', 'trialing', 'past_due')
  order by
    case plan_code when 'premium_plus' then 2 when 'premium' then 1 else 0 end desc,
    stripe_event_created_at desc nulls last,
    updated_at desc
  limit 1;

  update public.therapist_profiles
  set plan = coalesce(v_active_plan, 'free'::public.therapist_plan),
      updated_at = now()
  where id = p_therapist_profile_id;

  return jsonb_build_object(
    'applied', v_applied,
    'plan', coalesce(v_active_plan, 'free'::public.therapist_plan),
    'subscriptionId', v_subscription.id
  );
end;
$$;


ALTER FUNCTION "public"."apply_therapist_subscription_event_v1"("p_therapist_profile_id" "uuid", "p_stripe_subscription_id" "text", "p_plan_code" "public"."therapist_plan", "p_status" "public"."billing_subscription_status", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_customer_id" "uuid", "p_billing_plan_id" "uuid", "p_billing_plan_price_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_latest_invoice_id" "text", "p_current_period_start" timestamp with time zone, "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean, "p_canceled_at" timestamp with time zone, "p_ended_at" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_therapist_subscription_event_v1"("p_therapist_profile_id" "uuid", "p_stripe_subscription_id" "text", "p_plan_code" "public"."therapist_plan", "p_status" "public"."billing_subscription_status", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_customer_id" "uuid", "p_billing_plan_id" "uuid", "p_billing_plan_price_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_latest_invoice_id" "text", "p_current_period_start" timestamp with time zone, "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean, "p_canceled_at" timestamp with time zone, "p_ended_at" timestamp with time zone, "p_metadata" "jsonb") IS 'Sincroniza assinatura e plano do terapeuta com protecao contra eventos Stripe fora de ordem.';



CREATE OR REPLACE FUNCTION "public"."apply_zoom_video_session_event_v1"("p_session_name" "text", "p_provider_session_id" "text", "p_event_type" "text", "p_event_at" timestamp with time zone, "p_provider_user_id" "text" DEFAULT NULL::"text", "p_provider_user_key" "text" DEFAULT NULL::"text", "p_duration_seconds" integer DEFAULT NULL::integer, "p_max_duration_minutes" integer DEFAULT NULL::integer, "p_after_ends_minutes" integer DEFAULT 30) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.apply_zoom_video_session_event_v1(
    p_session_name,
    p_provider_session_id,
    p_event_type,
    p_event_at,
    null,
    p_provider_user_id,
    p_provider_user_key,
    p_duration_seconds,
    p_max_duration_minutes,
    p_after_ends_minutes
  );
end;
$$;


ALTER FUNCTION "public"."apply_zoom_video_session_event_v1"("p_session_name" "text", "p_provider_session_id" "text", "p_event_type" "text", "p_event_at" timestamp with time zone, "p_provider_user_id" "text", "p_provider_user_key" "text", "p_duration_seconds" integer, "p_max_duration_minutes" integer, "p_after_ends_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_zoom_video_session_event_v1"("p_session_name" "text", "p_provider_session_id" "text", "p_event_type" "text", "p_event_at" timestamp with time zone, "p_provider_user_id" "text", "p_provider_user_key" "text", "p_duration_seconds" integer, "p_max_duration_minutes" integer, "p_after_ends_minutes" integer) IS 'Legacy internal Zoom Video SDK webhook event projection. Restricted to service_role.';



CREATE OR REPLACE FUNCTION "public"."apply_zoom_video_session_event_v1"("p_session_name" "text", "p_provider_session_id" "text", "p_event_type" "text", "p_event_at" timestamp with time zone, "p_environment" "text", "p_provider_user_id" "text", "p_provider_user_key" "text", "p_duration_seconds" integer, "p_max_duration_minutes" integer, "p_after_ends_minutes" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session public.video_sessions%rowtype;
  v_role public.video_session_participant_role :=
    'unknown'::public.video_session_participant_role;
  v_correlation text;
  v_event_at timestamptz := coalesce(p_event_at, now());
  v_hard_ends_at timestamptz;
  v_session_name text := nullif(btrim(coalesce(p_session_name, '')), '');
  v_provider_session_id text := nullif(btrim(coalesce(p_provider_session_id, '')), '');
  v_provider_user_id text := nullif(btrim(coalesce(p_provider_user_id, '')), '');
  v_provider_user_key text := nullif(btrim(coalesce(p_provider_user_key, '')), '');
  v_match_count integer := 0;
  v_closed_at timestamptz;
  v_provider_hash text;
begin
  if p_environment is not null
     and p_environment not in ('development', 'production') then
    raise exception 'invalid_zoom_video_environment'
      using errcode = '22023';
  end if;

  if v_session_name is null and v_provider_session_id is null then
    return;
  end if;

  with candidates as (
    select
      (
        case
          when v_session_name is not null
            and lower(vs.session_name) = lower(v_session_name)
            then 2
          else 0
        end
        +
        case
          when v_provider_session_id is not null
            and vs.provider_session_id = v_provider_session_id
            then 1
          else 0
        end
      ) as match_score
    from public.video_sessions vs
    where (p_environment is null or vs.environment = p_environment)
      and (
        (v_session_name is not null and lower(vs.session_name) = lower(v_session_name))
        or (
          v_provider_session_id is not null
          and vs.provider_session_id = v_provider_session_id
        )
      )
  )
  select count(*)
    into v_match_count
  from candidates
  where match_score = (select max(match_score) from candidates);

  if coalesce(v_match_count, 0) <> 1 then
    return;
  end if;

  select *
    into v_session
  from public.video_sessions vs
  where (p_environment is null or vs.environment = p_environment)
    and (
      (v_session_name is not null and lower(vs.session_name) = lower(v_session_name))
      or (
        v_provider_session_id is not null
        and vs.provider_session_id = v_provider_session_id
      )
    )
  order by
    (
      case
        when v_session_name is not null
          and lower(vs.session_name) = lower(v_session_name)
          then 2
        else 0
      end
      +
      case
        when v_provider_session_id is not null
          and vs.provider_session_id = v_provider_session_id
          then 1
        else 0
      end
    ) desc,
    vs.updated_at desc
  limit 1
  for update;

  if not found then
    return;
  end if;

  if v_provider_session_id is not null
     and v_session.provider_session_id is not null
     and v_session.provider_session_id <> v_provider_session_id then
    return;
  end if;

  -- Provider end closes an instance, not necessarily the TES encounter. Keep
  -- a watermark and opaque retired-instance identities in existing metadata.
  v_closed_at := (v_session.metadata ->> 'zoom_provider_closed_at')::timestamptz;
  v_provider_hash := case when v_provider_session_id is not null then
    encode(extensions.digest(v_provider_session_id, 'sha256'), 'hex') end;
  if v_session.status in ('ended', 'canceled')
     or v_session.termination_confirmed_at is not null then return; end if;
  if v_closed_at is not null and (
    v_event_at < v_closed_at or v_provider_session_id is null
    or coalesce(v_session.metadata -> 'zoom_closed_provider_hashes', '[]'::jsonb) ? v_provider_hash
  ) then return; end if;
  if p_event_type in ('session.started', 'session.user_joined', 'session.user_left')
     and (v_session.termination_requested_at is not null
       or v_event_at >= v_session.scheduled_ends_at
       or (v_session.hard_ends_at is not null and v_event_at >= v_session.hard_ends_at))
  then return; end if;

  if p_max_duration_minutes is not null then
    if p_max_duration_minutes < 1 or p_max_duration_minutes > 240 then
      raise exception 'invalid_zoom_video_session_max_duration_minutes'
        using errcode = '22023';
    end if;

    v_hard_ends_at := coalesce(v_session.actual_started_at, v_event_at)
      + make_interval(mins => p_max_duration_minutes);
  end if;

  if v_provider_user_key like 'tes-v1-t-%' then
    v_role := 'therapist'::public.video_session_participant_role;
  elsif v_provider_user_key like 'tes-v1-p-%' then
    v_role := 'patient'::public.video_session_participant_role;
  end if;

  if p_event_type = 'session.started' then
    update public.video_sessions
    set status = 'active',
        actual_started_at = coalesce(actual_started_at, v_event_at),
        hard_ends_at = coalesce(hard_ends_at, v_hard_ends_at),
        provider_session_id = coalesce(provider_session_id, v_provider_session_id),
        last_provider_event_at = greatest(
          coalesce(last_provider_event_at, '-infinity'::timestamptz),
          v_event_at
        ),
        last_synced_at = now(),
        updated_at = now()
    where id = v_session.id
      and status not in ('ended', 'canceled');
  elsif p_event_type = 'session.ended' then
    if v_session.status in ('ready', 'active')
       and v_session.termination_requested_at is null
       and v_session.termination_confirmed_at is null
       and v_event_at < v_session.scheduled_ends_at
       and (v_session.hard_ends_at is null or v_event_at < v_session.hard_ends_at) then
      update public.video_sessions
      set provider_session_id = null,
          metadata = metadata || jsonb_build_object(
            'zoom_provider_closed_at', v_event_at,
            'zoom_closed_provider_hashes',
              coalesce(metadata -> 'zoom_closed_provider_hashes', '[]'::jsonb)
              || case when v_provider_hash is null then '[]'::jsonb
                 else jsonb_build_array(v_provider_hash) end
          ),
          therapist_last_left_at = case
            when therapist_present then greatest(
              coalesce(therapist_last_left_at, '-infinity'::timestamptz),
              v_event_at
            )
            else therapist_last_left_at
          end,
          therapist_present = false,
          participant_count = 0,
          last_participant_left_at = greatest(
            coalesce(last_participant_left_at, '-infinity'::timestamptz),
            v_event_at
          ),
          last_provider_event_at = greatest(
            coalesce(last_provider_event_at, '-infinity'::timestamptz),
            v_event_at
          ),
          last_synced_at = now(),
          updated_at = now()
      where id = v_session.id
        and status in ('ready', 'active')
        and termination_requested_at is null
        and termination_confirmed_at is null;
    else
      update public.video_sessions
      set status = 'ended',
          actual_ended_at = coalesce(actual_ended_at, v_event_at),
          provider_session_id = coalesce(provider_session_id, v_provider_session_id),
          therapist_present = false,
          participant_count = 0,
          termination_reason = coalesce(termination_reason, 'provider_ended'),
          termination_confirmed_at = coalesce(termination_confirmed_at, v_event_at),
          last_provider_event_at = greatest(
            coalesce(last_provider_event_at, '-infinity'::timestamptz),
            v_event_at
          ),
          last_synced_at = now(),
          updated_at = now()
      where id = v_session.id
        and status <> 'canceled';
    end if;
  end if;

  if p_event_type in ('session.user_joined', 'session.user_left') then
    v_correlation := coalesce(
      v_provider_user_key,
      v_provider_user_id,
      encode(extensions.digest(v_session.id::text || p_event_type, 'sha256'::text), 'hex')
    );

    insert into public.video_session_participations (
      video_session_id,
      booking_id,
      participant_correlation_key,
      provider_user_id,
      provider_user_key,
      participant_role,
      event_type,
      joined_at,
      left_at,
      duration_seconds,
      metadata
    )
    select
      v_session.id,
      v_session.booking_id,
      v_correlation,
      v_provider_user_id,
      v_provider_user_key,
      v_role,
      p_event_type,
      case when p_event_type = 'session.user_joined' then v_event_at else null end,
      case when p_event_type = 'session.user_left' then v_event_at else null end,
      p_duration_seconds,
      jsonb_build_object('source', 'zoom_video_webhook', 'provider_hash', v_provider_hash)
    where not exists (
      select 1
      from public.video_session_participations existing
      where existing.video_session_id = v_session.id
        and existing.participant_correlation_key = v_correlation
        and existing.event_type = p_event_type
        and coalesce(existing.joined_at, existing.left_at) = v_event_at
    );

    update public.video_sessions
    set status = case
          when v_role = 'therapist'
            and p_event_type = 'session.user_joined'
            and public.video_sessions.status not in ('ended', 'canceled')
            then 'active'::public.video_session_status
          else public.video_sessions.status
        end,
        actual_started_at = case
          when v_role = 'therapist'
            and p_event_type = 'session.user_joined'
            and public.video_sessions.status not in ('ended', 'canceled')
            then coalesce(public.video_sessions.actual_started_at, v_event_at)
          else public.video_sessions.actual_started_at
        end,
        hard_ends_at = case
          when v_role = 'therapist'
            and p_event_type = 'session.user_joined'
            then coalesce(public.video_sessions.hard_ends_at, v_hard_ends_at)
          else public.video_sessions.hard_ends_at
        end,
        provider_session_id = coalesce(public.video_sessions.provider_session_id, v_provider_session_id),
        therapist_first_joined_at = aggregates.therapist_first_joined_at,
        therapist_last_joined_at = aggregates.therapist_last_joined_at,
        therapist_last_left_at = greatest(public.video_sessions.therapist_last_left_at, aggregates.therapist_last_left_at),
        therapist_present = aggregates.therapist_present,
        participant_count = aggregates.active_participant_count,
        last_participant_left_at = greatest(public.video_sessions.last_participant_left_at, aggregates.last_participant_left_at),
        last_provider_event_at = greatest(
          coalesce(public.video_sessions.last_provider_event_at, '-infinity'::timestamptz),
          v_event_at
        ),
        last_synced_at = now(),
        updated_at = now()
    from (
      with latest_events as (
        select distinct on (vsp.participant_correlation_key)
          vsp.participant_correlation_key,
          vsp.participant_role,
          vsp.event_type,
          coalesce(vsp.left_at, vsp.joined_at, vsp.created_at) as event_at
        from public.video_session_participations vsp
        where vsp.video_session_id = v_session.id
          and (v_closed_at is null or (
            coalesce(vsp.left_at, vsp.joined_at, vsp.created_at) >= v_closed_at
            and vsp.metadata ->> 'provider_hash' = v_provider_hash
          ))
        order by
          vsp.participant_correlation_key,
          coalesce(vsp.left_at, vsp.joined_at, vsp.created_at) desc,
          case when vsp.event_type = 'session.user_left' then 0 else 1 end
      )
      select
        coalesce(
          bool_or(
            latest_events.participant_role = 'therapist'::public.video_session_participant_role
            and latest_events.event_type = 'session.user_joined'
          ),
          false
        ) as therapist_present,
        count(*) filter (
          where latest_events.event_type = 'session.user_joined'
        )::integer as active_participant_count,
        (
          select min(vsp.joined_at)
          from public.video_session_participations vsp
          where vsp.video_session_id = v_session.id
            and vsp.participant_role = 'therapist'::public.video_session_participant_role
            and vsp.event_type = 'session.user_joined'
        ) as therapist_first_joined_at,
        (
          select max(vsp.joined_at)
          from public.video_session_participations vsp
          where vsp.video_session_id = v_session.id
            and vsp.participant_role = 'therapist'::public.video_session_participant_role
            and vsp.event_type = 'session.user_joined'
        ) as therapist_last_joined_at,
        (
          select max(vsp.left_at)
          from public.video_session_participations vsp
          where vsp.video_session_id = v_session.id
            and vsp.participant_role = 'therapist'::public.video_session_participant_role
            and vsp.event_type = 'session.user_left'
        ) as therapist_last_left_at,
        (
          select max(vsp.left_at)
          from public.video_session_participations vsp
          where vsp.video_session_id = v_session.id
            and vsp.event_type = 'session.user_left'
        ) as last_participant_left_at
      from latest_events
    ) as aggregates
    where public.video_sessions.id = v_session.id
      and public.video_sessions.status not in ('ended', 'canceled');
  end if;
end;
$$;


