CREATE OR REPLACE FUNCTION "public"."apply_zoom_video_webhook_transition_v1"("p_event_key" "text", "p_status" "public"."zoom_video_webhook_processing_status", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.zoom_video_webhook_events
  set processing_status = p_status,
      processed_at = case when p_status in ('processed', 'ignored') then now() else processed_at end,
      error_code = left(nullif(p_error_code, ''), 120),
      error_message = left(nullif(p_error_message, ''), 500),
      updated_at = now()
  where event_key = p_event_key;
end;
$$;


ALTER FUNCTION "public"."apply_zoom_video_webhook_transition_v1"("p_event_key" "text", "p_status" "public"."zoom_video_webhook_processing_status", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arm_email_outbox_test_fault_v1"("p_action_key" "text", "p_recipient_key" "text", "p_expires_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_expires_at <= now() or p_expires_at > now() + interval '15 minutes' then
    raise exception 'EMAIL_OUTBOX_TEST_FAULT_EXPIRY_INVALID';
  end if;
  delete from public.email_outbox_test_faults
  where action_key = p_action_key and recipient_key = p_recipient_key and consumed_at is null;
  insert into public.email_outbox_test_faults(action_key, recipient_key, expires_at)
  values (p_action_key, p_recipient_key, p_expires_at);
end; $$;


ALTER FUNCTION "public"."arm_email_outbox_test_fault_v1"("p_action_key" "text", "p_recipient_key" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_booking_session_reference_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.session_reference is not null then
    raise exception 'session_reference_is_system_generated' using errcode = '42501';
  end if;

  new.session_reference := public.next_booking_session_reference_v1(new.created_at);
  return new;
end;
$$;


ALTER FUNCTION "public"."assign_booking_session_reference_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_support_ticket_requester_attachments_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_message_id uuid;
begin
  if not exists (
    select 1 from public.support_tickets
    where id = p_ticket_id and requester_profile_id = auth.uid()
  ) then
    raise exception 'support ticket requester required' using errcode = '42501';
  end if;
  select id into v_message_id
  from public.support_ticket_messages
  where ticket_id = p_ticket_id
    and author_profile_id = auth.uid()
    and request_id = p_request_id
    and visibility = 'requester'
  order by created_at asc
  limit 1;
  if v_message_id is null then
    raise exception 'support ticket message not found' using errcode = 'P0002';
  end if;
  perform public.support_validate_ticket_attachments_v1(p_ticket_id, v_message_id, coalesce(p_attachments, '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."attach_support_ticket_requester_attachments_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_booking_change_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_profile_id uuid;
  v_reason text;
  v_request_id text;
  v_source text;
begin
  begin
    v_actor_profile_id := nullif(
      pg_catalog.current_setting('tes.booking_actor_profile_id', true),
      ''
    )::uuid;
  exception
    when invalid_text_representation then
      v_actor_profile_id := null;
  end;

  v_reason := nullif(
    pg_catalog.current_setting('tes.booking_reason', true),
    ''
  );
  v_request_id := nullif(
    pg_catalog.current_setting('tes.booking_request_id', true),
    ''
  );
  v_source := coalesce(
    nullif(
      pg_catalog.current_setting('tes.booking_source', true),
      ''
    ),
    case
      when tg_op = 'UPDATE'
        and new.payment_status is distinct from old.payment_status
        then 'payment_state'
      else 'database'
    end
  );

  if tg_op = 'INSERT' then
    insert into public.booking_events (
      booking_id,
      actor_profile_id,
      event_type,
      request_id,
      source,
      previous_status,
      next_status,
      payload
    ) values (
      new.id,
      v_actor_profile_id,
      'booking_created',
      v_request_id,
      left(v_source, 80),
      null,
      new.status,
      pg_catalog.jsonb_strip_nulls(
        pg_catalog.jsonb_build_object(
          'reason', left(v_reason, 500),
          'version', new.version
        )
      )
    )
    on conflict do nothing;

    return new;
  end if;

  if new.status <> old.status then
    insert into public.booking_events (
      booking_id,
      actor_profile_id,
      event_type,
      request_id,
      source,
      previous_status,
      next_status,
      payload
    ) values (
      new.id,
      v_actor_profile_id,
      'booking_status_changed',
      v_request_id,
      left(v_source, 80),
      old.status,
      new.status,
      pg_catalog.jsonb_strip_nulls(
        pg_catalog.jsonb_build_object(
          'reason', left(v_reason, 500),
          'version', new.version
        )
      )
    )
    on conflict do nothing;
  end if;

  if new.starts_at <> old.starts_at
    or new.ends_at <> old.ends_at
    or new.timezone <> old.timezone then
    insert into public.booking_events (
      booking_id,
      actor_profile_id,
      event_type,
      request_id,
      source,
      previous_status,
      next_status,
      payload
    ) values (
      new.id,
      v_actor_profile_id,
      'booking_rescheduled',
      v_request_id,
      left(v_source, 80),
      old.status,
      new.status,
      pg_catalog.jsonb_strip_nulls(
        pg_catalog.jsonb_build_object(
          'previousStartsAt', old.starts_at,
          'previousEndsAt', old.ends_at,
          'previousTimezone', old.timezone,
          'startsAt', new.starts_at,
          'endsAt', new.ends_at,
          'timezone', new.timezone,
          'reason', left(v_reason, 500),
          'version', new.version
        )
      )
    )
    on conflict do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."audit_booking_change_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authorize_therapist_zoom_manual_end_v1"("p_booking_id" "uuid", "p_therapist_profile_id" "uuid", "p_now" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session record;
  v_now timestamptz := coalesce(p_now, clock_timestamp());
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_booking_id::text, 0)
  );

  select
    booking.id as booking_id,
    booking.therapist_profile_id,
    booking.ends_at,
    booking.status as booking_status,
    payment.financial_status,
    video_session.id as video_session_id,
    video_session.status as video_session_status,
    video_session.provider_session_id,
    video_session.termination_confirmed_at,
    video_session.actual_ended_at,
    video_session.termination_reason,
    video_session.termination_requested_at
  into v_session
  from public.bookings booking
  left join public.session_payments payment
    on payment.booking_id = booking.id
  left join public.video_sessions video_session
    on video_session.booking_id = booking.id
  where booking.id = p_booking_id
  limit 1;

  if not found then
    raise exception 'ZOOM_BOOKING_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_session.therapist_profile_id is distinct from p_therapist_profile_id then
    raise exception 'ZOOM_FINAL_END_THERAPIST_REQUIRED'
      using errcode = '42501';
  end if;

  if v_session.termination_confirmed_at is not null
    or v_session.video_session_status in ('ended', 'canceled') then
    if v_session.actual_ended_at is null
      or v_session.actual_ended_at < v_session.ends_at - interval '5 minutes' then
      return jsonb_build_object(
        'alreadyEnded', true,
        'allowed', false,
        'reason', 'EARLY_PROVIDER_END',
        'serverNow', v_now
      );
    end if;

    return jsonb_build_object(
      'alreadyEnded', true,
      'allowed', true,
      'providerSessionId', null,
      'serverNow', v_now,
      'videoSessionId', v_session.video_session_id
    );
  end if;

  if v_now < v_session.ends_at - interval '5 minutes' then
    return jsonb_build_object(
      'alreadyEnded', false,
      'allowed', false,
      'availableAt', v_session.ends_at - interval '5 minutes',
      'reason', 'FINAL_END_TOO_EARLY',
      'serverNow', v_now
    );
  end if;

  if v_now >= v_session.ends_at then
    return jsonb_build_object(
      'alreadyEnded', false,
      'allowed', false,
      'reason', 'TOO_LATE',
      'serverNow', v_now
    );
  end if;

  if v_session.booking_status <> 'confirmed'::public.booking_status
    or v_session.financial_status is distinct from 'paid'::public.session_financial_status
    or v_session.video_session_status <> 'active'::public.video_session_status
    or v_session.video_session_id is null
    or v_session.provider_session_id is null then
    return jsonb_build_object(
      'alreadyEnded', false,
      'allowed', false,
      'reason', 'VIDEO_SESSION_NOT_READY',
      'serverNow', v_now
    );
  end if;

  if v_session.termination_reason = 'manual_end'
    and v_session.termination_requested_at is not null
    and v_session.termination_requested_at > v_now - interval '15 seconds' then
    return jsonb_build_object(
      'alreadyEnded', false,
      'allowed', false,
      'reason', 'FINAL_END_IN_PROGRESS',
      'serverNow', v_now
    );
  end if;

  update public.video_sessions
  set termination_reason = 'manual_end',
      termination_requested_at = v_now,
      updated_at = v_now
  where id = v_session.video_session_id
    and termination_confirmed_at is null;

  return jsonb_build_object(
    'alreadyEnded', false,
    'allowed', true,
    'providerSessionId', v_session.provider_session_id,
    'serverNow', v_now,
    'videoSessionId', v_session.video_session_id
  );
end;
$$;


ALTER FUNCTION "public"."authorize_therapist_zoom_manual_end_v1"("p_booking_id" "uuid", "p_therapist_profile_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."authorize_therapist_zoom_manual_end_v1"("p_booking_id" "uuid", "p_therapist_profile_id" "uuid", "p_now" timestamp with time zone) IS 'Authorizes an idempotent therapist-owned final Zoom termination only during the last five scheduled minutes.';



CREATE OR REPLACE FUNCTION "public"."auto_confirm_sessions"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.session_confirmation_scheduler_runs%rowtype;
  v_row record;
  v_hash text;
  v_inserted integer;
  v_patient_count integer := 0;
  v_therapist_count integer := 0;
  v_finalized integer := 0;
  v_result text;
begin
  insert into public.session_confirmation_scheduler_runs (scheduled_for, status)
  values (date_trunc('hour', p_now), 'running')
  on conflict (scheduled_for) do update
  set status = 'running',
      attempts = public.session_confirmation_scheduler_runs.attempts + 1,
      error_code = null,
      started_at = now(),
      finished_at = null,
      updated_at = now()
  returning * into v_run;

  begin
    for v_row in
      select
        payment.booking_id,
        payment.policy_version_id,
        booking.ends_at,
        deadline.participant_role,
        booking.ends_at + make_interval(days => deadline.deadline_days) as due_at
      from public.session_payments payment
      join public.bookings booking on booking.id = payment.booking_id
      join public.financial_policy_versions policy on policy.id = payment.policy_version_id
      cross join lateral (
        values
          ('patient'::public.user_role, policy.patient_auto_confirmation_days),
          ('therapist'::public.user_role, policy.therapist_auto_confirmation_days)
      ) as deadline(participant_role, deadline_days)
      where payment.financial_status in ('paid', 'partially_refunded')
        and payment.service_confirmed_at is null
        and booking.ends_at + make_interval(days => deadline.deadline_days) <= p_now
        and booking.status not in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded')
        and payment.refund_pending = false
        and payment.disputed_at is null
        and payment.internal_contested_at is null
        and payment.admin_blocked_at is null
        and not exists (
          select 1 from public.session_participant_confirmations confirmation
          where confirmation.booking_id = payment.booking_id
            and confirmation.participant_role = deadline.participant_role
        )
        and not exists (
          select 1 from public.session_confirmation_incidents incident
          where incident.booking_id = payment.booking_id and incident.status = 'open'
        )
        and not exists (
          select 1 from public.session_feedback feedback
          where feedback.booking_id = payment.booking_id
            and feedback.outcome = 'not_performed'
        )
      order by due_at, payment.booking_id, deadline.participant_role
    loop
      v_hash := encode(
        extensions.digest(
          concat_ws('|', v_row.booking_id::text, v_row.participant_role::text, 'completed', 'automatic'),
          'sha256'
        ),
        'hex'
      );

      insert into public.session_participant_confirmations (
        booking_id, participant_role, outcome, source, request_id,
        payload_hash, due_at, confirmed_at, policy_version_id
      ) values (
        v_row.booking_id, v_row.participant_role, 'completed', 'automatic',
        gen_random_uuid(), v_hash, v_row.due_at, v_row.due_at, v_row.policy_version_id
      )
      on conflict (booking_id, participant_role) do nothing;
      get diagnostics v_inserted = row_count;

      if v_inserted > 0 then
        if v_row.participant_role = 'patient'::public.user_role then
          v_patient_count := v_patient_count + 1;
        else
          v_therapist_count := v_therapist_count + 1;
        end if;
      end if;

      v_result := public.finalize_bilateral_session_confirmation_v1(v_row.booking_id, p_now);
      if v_result = 'confirmed' then v_finalized := v_finalized + 1; end if;
    end loop;

    update public.session_confirmation_scheduler_runs
    set status = 'completed',
        patient_confirmations = v_patient_count,
        therapist_confirmations = v_therapist_count,
        finalized_sessions = v_finalized,
        finished_at = now(),
        updated_at = now()
    where id = v_run.id;
  exception when others then
    update public.session_confirmation_scheduler_runs
    set status = 'failed',
        patient_confirmations = v_patient_count,
        therapist_confirmations = v_therapist_count,
        finalized_sessions = v_finalized,
        error_code = sqlstate,
        finished_at = now(),
        updated_at = now()
    where id = v_run.id;
    return -1;
  end;

  return v_patient_count + v_therapist_count;
end;
$$;


ALTER FUNCTION "public"."auto_confirm_sessions"("p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_confirm_sessions"("p_now" timestamp with time zone) IS 'Idempotently records role-specific automatic confirmations at 7/30-day deadlines without using Zoom attendance as a payment gate.';



CREATE OR REPLACE FUNCTION "public"."begin_session_charge_recovery_v10"("p_booking_id" "uuid", "p_patient_profile_id" "uuid", "p_schedule_id" "uuid", "p_stripe_payment_intent_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
  v_payment public.session_payments%rowtype;
  v_recovery public.session_charge_recoveries_v10%rowtype;
begin
  if p_booking_id is null or p_patient_profile_id is null or p_schedule_id is null
    or nullif(trim(p_stripe_payment_intent_id), '') is null then
    raise exception 'SESSION_CHARGE_RECOVERY_INVALID' using errcode = '22023';
  end if;
  select * into v_booking from public.bookings where id = p_booking_id for update;
  select * into v_schedule from public.session_payment_schedules
  where id = p_schedule_id for update;
  select * into v_payment from public.session_payments
  where id = v_schedule.session_payment_id;
  if v_booking.patient_profile_id <> p_patient_profile_id
    or v_booking.status <> 'confirmed'
    or v_booking.version <> v_schedule.expected_booking_version
    or v_booking.starts_at <= now()
    or v_schedule.booking_id <> p_booking_id
    or v_schedule.status <> 'requires_customer_action'
    or v_schedule.stripe_payment_intent_id <> trim(p_stripe_payment_intent_id)
    or v_payment.financial_status not in ('pending', 'processing')
  then
    raise exception 'SESSION_CHARGE_RECOVERY_NOT_ALLOWED' using errcode = '23514';
  end if;
  insert into public.session_charge_recoveries_v10 (
    schedule_id, booking_id, patient_profile_id, stripe_payment_intent_id
  ) values (
    p_schedule_id, p_booking_id, p_patient_profile_id, trim(p_stripe_payment_intent_id)
  ) on conflict (schedule_id) do update
    set opened_at = public.session_charge_recoveries_v10.opened_at
  returning * into v_recovery;
  if v_recovery.stripe_payment_intent_id <> trim(p_stripe_payment_intent_id)
    or v_recovery.patient_profile_id <> p_patient_profile_id
    or v_recovery.status <> 'open'
  then
    raise exception 'SESSION_CHARGE_RECOVERY_CONFLICT' using errcode = '23505';
  end if;
  return jsonb_build_object('allowed', true);
end;
$$;


ALTER FUNCTION "public"."begin_session_charge_recovery_v10"("p_booking_id" "uuid", "p_patient_profile_id" "uuid", "p_schedule_id" "uuid", "p_stripe_payment_intent_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_session_payment_retry_v10"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.session_payment_attempts%rowtype;
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
  v_preflight jsonb;
  v_updated integer := 0;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  select * into v_payment
  from public.session_payments
  where booking_id = p_booking_id
  for update;

  if v_booking.id is null
    or v_payment.id is null
    or v_payment.payment_flow_version <> 'v10'
  then
    return jsonb_build_object('allowed', false, 'reason', 'booking_not_retryable');
  end if;

  select attempt.* into v_attempt
  from public.session_payment_attempts as attempt
  where attempt.session_payment_id = v_payment.id
    and attempt.stripe_checkout_session_id = v_payment.stripe_checkout_session_id
  order by attempt.created_at desc
  limit 1
  for update;

  -- The first invocation may have reopened the booking before Stripe or the
  -- following database write failed. Repeating the same operation is safe only
  -- while the current attempt is terminal and no charge authority exists.
  if v_booking.status = 'pending_payment'
    and v_booking.payment_status = 'pending'
    and v_booking.starts_at > now()
    and v_payment.financial_status = 'pending'
    and v_payment.stripe_payment_intent_id is null
    and v_payment.stripe_charge_id is null
    and v_attempt.id is not null
    and v_attempt.attempt_kind in ('initial_hold', 'payment_retry')
    and v_attempt.status in ('expired', 'failed', 'canceled', 'slot_conflict')
    and v_attempt.slot_claimed_at is null
    and not exists (
      select 1 from public.session_payment_setups as setup
      where setup.session_payment_id = v_payment.id
        and setup.status = 'succeeded'
        and setup.superseded_at is null
    )
    and not exists (
      select 1 from public.session_payment_schedules as schedule
      where schedule.session_payment_id = v_payment.id
        and schedule.status not in ('canceled', 'superseded')
    )
    and not exists (
      select 1 from public.session_transfer_jobs as job
      where job.session_payment_id = v_payment.id
    )
    and not exists (
      select 1 from public.stripe_transfers as transfer
      where transfer.session_payment_id = v_payment.id
    )
  then
    return jsonb_build_object('allowed', true, 'reason', 'retry_already_started');
  end if;

  v_preflight := public.preflight_session_payment_retry_v1(p_booking_id);
  if coalesce((v_preflight ->> 'allowed')::boolean, false) is not true then
    return v_preflight;
  end if;

  perform pg_catalog.set_config('tes.booking_reason', 'v10_checkout_retry', true);
  perform pg_catalog.set_config('tes.booking_source', 'payment_retry_claim', true);

  begin
    update public.bookings
    set status = 'pending_payment',
        payment_status = 'pending',
        cancellation_reason = null,
        cancelled_at = null,
        updated_at = now()
    where id = p_booking_id
      and status = 'cancelled_by_payment';
    get diagnostics v_updated = row_count;
  exception
    when exclusion_violation then
      perform pg_catalog.set_config('tes.booking_reason', '', true);
      perform pg_catalog.set_config('tes.booking_source', '', true);
      return jsonb_build_object('allowed', false, 'reason', 'slot_conflict');
  end;

  perform pg_catalog.set_config('tes.booking_reason', '', true);
  perform pg_catalog.set_config('tes.booking_source', '', true);

  if v_updated <> 1 then
    return jsonb_build_object('allowed', false, 'reason', 'booking_not_retryable');
  end if;

  update public.session_payments
  set financial_status = 'pending',
      failed_at = null,
      canceled_at = null,
      transfer_blocked_reason = null,
      updated_at = now()
  where id = v_payment.id;

  return jsonb_build_object('allowed', true, 'reason', 'retry_started');
end;
$$;


ALTER FUNCTION "public"."begin_session_payment_retry_v10"("p_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_session_payment_retry_v10"("p_booking_id" "uuid") IS 'Atomically starts or safely resumes a V10 replacement Checkout after a terminal unpaid attempt.';



