    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    cardinality(p_values) = (
      select count(distinct value)
      from unnest(p_values) as item(value)
    ),
    false
  );
$$;


