CREATE OR REPLACE FUNCTION "public"."calculate_session_cancellation_policy"("p_booking_id" "uuid", "p_reason" "text" DEFAULT 'patient_cancellation'::"text", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("booking_id" "uuid", "session_payment_id" "uuid", "policy_version_id" "uuid", "decision" "text", "refund_amount_cents" integer, "retained_amount_cents" integer, "therapist_retained_cents" integer, "platform_retained_cents" integer, "requires_manual_review" boolean, "review_due_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
  v_policy public.financial_policy_versions%rowtype;
  v_retention_bps integer := 0;
  v_retained integer := 0;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id;

  if not found then
    raise exception 'booking_not_found';
  end if;

  select * into v_payment
  from public.session_payments
  where session_payments.booking_id = p_booking_id;

  select * into v_policy
  from public.financial_policy_versions
  where id = coalesce(v_payment.policy_version_id, (
    select id from public.financial_policy_versions where is_active limit 1
  ));

  if v_policy.id is null then
    raise exception 'financial_policy_not_found';
  end if;

  if v_payment.id is null or v_payment.financial_status not in ('paid', 'partially_refunded') then
    return query select
      v_booking.id,
      v_payment.id,
      v_policy.id,
      'unpaid_cancellation'::text,
      coalesce(v_payment.gross_amount_cents, 0),
      0,
      0,
      0,
      false,
      null::timestamptz;
    return;
  end if;

  if v_payment.transfer_status in ('batched', 'transferred')
    or v_payment.refund_pending
    or v_payment.financial_status in ('disputed', 'refunded')
    or v_payment.disputed_at is not null then
    return query select
      v_booking.id,
      v_payment.id,
      v_policy.id,
      'manual_review_required'::text,
      0,
      v_payment.gross_amount_cents,
      v_payment.therapist_amount_cents,
      v_payment.platform_gross_commission_cents,
      true,
      p_now + make_interval(days => v_policy.manual_review_response_days);
    return;
  end if;

  if p_reason = 'no_show' then
    v_retention_bps := v_policy.no_show_retention_bps;
  elsif v_booking.starts_at - p_now >= make_interval(hours => v_policy.free_cancellation_hours) then
    v_retention_bps := 0;
  else
    v_retention_bps := v_policy.late_cancellation_retention_bps;
  end if;

  v_retained := floor(v_payment.gross_amount_cents * v_retention_bps / 10000.0)::integer;

  return query select
    v_booking.id,
    v_payment.id,
    v_policy.id,
    case
      when p_reason = 'no_show' then 'no_show_retention'
      when v_retention_bps = 0 then 'free_cancellation_full_refund'
      else 'late_cancellation_partial_refund'
    end,
    greatest(v_payment.gross_amount_cents - v_retained, 0),
    v_retained,
    floor(v_retained * (10000 - v_policy.platform_commission_bps) / 10000.0)::integer,
    v_retained - floor(v_retained * (10000 - v_policy.platform_commission_bps) / 10000.0)::integer,
    false,
    null::timestamptz;
end;
$$;


ALTER FUNCTION "public"."calculate_session_cancellation_policy"("p_booking_id" "uuid", "p_reason" "text", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_session_payment_snapshot"("p_gross_amount_cents" integer, "p_platform_commission_bps" integer DEFAULT 1500) RETURNS TABLE("gross_amount_cents" integer, "platform_commission_bps" integer, "platform_gross_commission_cents" integer, "therapist_amount_cents" integer)
    LANGUAGE "sql" STABLE
    AS $$
  select
    p_gross_amount_cents,
    p_platform_commission_bps,
    p_gross_amount_cents - floor(
      p_gross_amount_cents * (10000 - p_platform_commission_bps) / 10000.0
    )::integer,
    floor(
      p_gross_amount_cents * (10000 - p_platform_commission_bps) / 10000.0
    )::integer
  where p_gross_amount_cents >= 0
    and p_platform_commission_bps between 0 and 10000;
$$;


ALTER FUNCTION "public"."calculate_session_payment_snapshot"("p_gross_amount_cents" integer, "p_platform_commission_bps" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."booking_holds" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "patient_profile_id" "uuid" NOT NULL,
    "therapist_profile_id" "uuid" NOT NULL,
    "service_id" "uuid" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "timezone" "text" NOT NULL,
    "status" "public"."booking_hold_status" DEFAULT 'active'::"public"."booking_hold_status" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "consume_idempotency_key" "text",
    "expires_at" timestamp with time zone NOT NULL,
    "consumed_booking_id" "uuid",
    "service_title_snapshot" "text" NOT NULL,
    "service_duration_minutes_snapshot" integer NOT NULL,
    "service_price_cents_snapshot" integer NOT NULL,
    "currency_snapshot" character(3) NOT NULL,
    "buffer_before_minutes_snapshot" integer NOT NULL,
    "buffer_after_minutes_snapshot" integer NOT NULL,
    "occupied_during" "tstzrange" NOT NULL,
    "snapshot_captured_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cancelled_at" timestamp with time zone,
    "consumed_at" timestamp with time zone,
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "booking_holds_idempotency_key_not_blank" CHECK ((("length"(TRIM(BOTH FROM "idempotency_key")) >= 8) AND ("length"(TRIM(BOTH FROM "idempotency_key")) <= 200))),
    CONSTRAINT "booking_holds_snapshot_values_valid" CHECK ((("length"(TRIM(BOTH FROM "service_title_snapshot")) > 0) AND ("service_duration_minutes_snapshot" > 0) AND ("service_price_cents_snapshot" >= 0) AND (("currency_snapshot")::"text" = "upper"(("currency_snapshot")::"text")) AND ("buffer_before_minutes_snapshot" >= 0) AND ("buffer_after_minutes_snapshot" >= 0) AND (NOT "isempty"("occupied_during")) AND "lower_inc"("occupied_during") AND (NOT "upper_inc"("occupied_during")) AND ("version" > 0))),
    CONSTRAINT "booking_holds_valid_expiry" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "booking_holds_valid_range" CHECK (("starts_at" < "ends_at"))
);


ALTER TABLE "public"."booking_holds" OWNER TO "postgres";


COMMENT ON TABLE "public"."booking_holds" IS 'Short-lived, idempotent slot reservations. Holds are not bookings and never represent payment.';



CREATE OR REPLACE FUNCTION "public"."cancel_booking_hold_v1"("p_hold_id" "uuid", "p_request_id" "text") RETURNS "public"."booking_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_hold public.booking_holds%rowtype;
begin
  if length(trim(coalesce(p_request_id, ''))) not between 8 and 200 then
    raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode = '22023';
  end if;

  select *
    into v_hold
  from public.booking_holds
  where id = p_hold_id
  for update;

  if not found then
    raise exception 'BOOKING_HOLD_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_hold.status = 'cancelled' then
    return v_hold;
  end if;

  if v_hold.status <> 'active' then
    raise exception 'INVALID_HOLD_STATE_TRANSITION' using errcode = 'P0001';
  end if;

  update public.booking_holds
  set status = 'cancelled',
      updated_at = now()
  where id = v_hold.id
  returning * into v_hold;

  return v_hold;
end;
$$;


ALTER FUNCTION "public"."cancel_booking_hold_v1"("p_hold_id" "uuid", "p_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_booking_reminder_jobs_v1"("p_booking_id" "uuid", "p_reason" "text" DEFAULT 'booking_not_eligible'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reason text := left(
    pg_catalog.regexp_replace(
      coalesce(nullif(pg_catalog.btrim(p_reason), ''), 'booking_not_eligible'),
      '[^a-zA-Z0-9_.-]+',
      '_',
      'g'
    ),
    120
  );
  v_cancelled integer := 0;
begin
  if p_booking_id is null then
    raise exception 'BOOKING_REMINDER_INVALID_CANCEL_REQUEST';
  end if;

  update public.email_outbox outbox
  set status = 'skipped'::public.email_outbox_status,
      last_error = 'booking_reminder_invalidated',
      next_attempt_at = null,
      locked_at = null,
      locked_by = null,
      processed_at = coalesce(processed_at, now())
  where outbox.id in (
    select job.outbox_id
    from public.booking_reminder_jobs job
    where job.booking_id = p_booking_id
      and job.outbox_id is not null
  )
    and outbox.status in ('pending', 'retry_pending');

  update public.booking_reminder_jobs
  set status = 'cancelled',
      last_error = v_reason,
      lease_owner = null,
      lease_expires_at = null
  where booking_id = p_booking_id
    and status in ('scheduled', 'processing', 'enqueued');

  get diagnostics v_cancelled = row_count;
  return v_cancelled;
end;
$$;


ALTER FUNCTION "public"."cancel_booking_reminder_jobs_v1"("p_booking_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_booking_reminder_jobs_v1"("p_booking_id" "uuid", "p_reason" "text") IS 'Invalidates pending patient reminder jobs and suppresses pending outbox rows after booking lifecycle changes.';



CREATE OR REPLACE FUNCTION "public"."cancel_reservation_checkout_attempt_v1"("p_booking_id" "uuid", "p_stripe_checkout_session_id" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.session_payment_attempts%rowtype;
  v_payment public.session_payments%rowtype;
begin
  select payment.* into v_payment
  from public.session_payments as payment
  where payment.booking_id = p_booking_id
    and payment.stripe_checkout_session_id = p_stripe_checkout_session_id
  for update;

  if not found then
    return jsonb_build_object('released', false, 'reason', 'superseded');
  end if;

  select * into v_attempt
  from public.session_payment_attempts
  where session_payment_id = v_payment.id
    and stripe_checkout_session_id = p_stripe_checkout_session_id
  for update;

  if not found or v_attempt.slot_claimed_at is not null then
    return jsonb_build_object('released', false, 'reason', 'not_releasable');
  end if;

  update public.session_payment_attempts
  set status = case when p_reason = 'reservation_expired' then 'expired' else 'canceled' end,
      terminal_reason = left(coalesce(nullif(trim(p_reason), ''), 'abandoned'), 120),
      updated_at = now()
  where id = v_attempt.id;

  if v_attempt.attempt_kind = 'initial_hold' then
    update public.session_payments
    set financial_status = 'canceled', canceled_at = coalesce(canceled_at, now()),
        updated_at = now()
    where id = v_payment.id and financial_status in ('pending', 'processing');
  end if;

  return jsonb_build_object('released', true, 'reason', p_reason);
end;
$$;


ALTER FUNCTION "public"."cancel_reservation_checkout_attempt_v1"("p_booking_id" "uuid", "p_stripe_checkout_session_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_therapist_block_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_block_id" "uuid", "p_scope" "text", "p_expected_schedule_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_block public.availability_exceptions%rowtype;
  v_cancelled_count integer;
  v_existing public.availability_exception_events%rowtype;
  v_result jsonb;
  v_settings public.therapist_schedule_settings%rowtype;
  v_therapist public.therapist_profiles%rowtype;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = p_actor_user_id
    and profile.role = 'therapist';

  if not found or v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_therapist.id::text, 0)
  );

  select event.*
    into v_existing
  from public.availability_exception_events as event
  where event.therapist_profile_id = v_therapist.id
    and event.request_id = p_request_id;

  if found then
    return v_existing.result || jsonb_build_object('idempotentReplay', true);
  end if;

  if p_scope not in ('occurrence', 'series') then
    raise exception 'invalid_block_scope' using errcode = '22023';
  end if;

  select exception.*
    into v_block
  from public.availability_exceptions as exception
  where exception.id = p_block_id
    and exception.therapist_profile_id = v_therapist.id
  for update;

  if not found then
    raise exception 'block_not_found' using errcode = 'P0002';
  end if;

  select settings.*
    into v_settings
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id
  for update;

  if v_settings.version <> p_expected_schedule_version then
    raise exception 'schedule_version_conflict' using errcode = 'P0001';
  end if;

  update public.availability_exceptions as exception
  set
    status = 'cancelled',
    version = exception.version + 1,
    cancelled_by_user_id = p_actor_user_id,
    cancelled_at = now()
  where exception.therapist_profile_id = v_therapist.id
    and exception.status = 'active'
    and (
      (p_scope = 'occurrence' and exception.id = v_block.id)
      or (
        p_scope = 'series'
        and v_block.series_id is not null
        and exception.series_id = v_block.series_id
      )
    );

  get diagnostics v_cancelled_count = row_count;

  update public.availability_exception_booking_impacts as impact
  set status = 'dismissed'
  where impact.status = 'pending'
    and exists (
      select 1
      from public.availability_exceptions as exception
      where exception.id = impact.exception_id
        and exception.therapist_profile_id = v_therapist.id
        and exception.status = 'cancelled'
        and (
          exception.id = v_block.id
          or (
            p_scope = 'series'
            and exception.series_id = v_block.series_id
          )
        )
    );

  if p_scope = 'series' and v_block.series_id is not null then
    update public.availability_exception_series
    set
      status = 'cancelled',
      version = version + 1,
      cancelled_by_user_id = p_actor_user_id,
      cancelled_at = now()
    where id = v_block.series_id;
  end if;

  update public.therapist_schedule_settings
  set version = version + 1
  where therapist_profile_id = v_therapist.id
  returning * into v_settings;

  v_result := jsonb_build_object(
    'cancelledCount', v_cancelled_count,
    'scheduleVersion', v_settings.version,
    'idempotentReplay', false
  );

  insert into public.availability_exception_events (
    therapist_profile_id,
    actor_user_id,
    series_id,
    exception_id,
    event_type,
    request_id,
    result
  )
  values (
    v_therapist.id,
    p_actor_user_id,
    v_block.series_id,
    v_block.id,
    case
      when p_scope = 'series' then 'block_series_cancelled'
      else 'block_cancelled'
    end,
    p_request_id,
    v_result
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."cancel_therapist_block_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_block_id" "uuid", "p_scope" "text", "p_expected_schedule_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_uncharged_session_v10"("p_booking_id" "uuid", "p_patient_user_id" "uuid", "p_request_id" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
  v_now timestamptz := now();
begin
  if p_booking_id is null or p_patient_user_id is null
    or length(trim(coalesce(p_request_id, ''))) not between 8 and 200
    or length(trim(coalesce(p_reason, ''))) not between 1 and 500
  then
    raise exception 'SESSION_PRECHARGE_CANCEL_V10_INVALID' using errcode = '22023';
  end if;

  -- Keep the same lock order as payment reconciliation. A worker that already
  -- claimed the schedule either commits first and is observed below, or waits
  -- until this transaction has atomically canceled the pristine schedule.
  select * into v_payment from public.session_payments
  where booking_id = p_booking_id for update;
  select booking.* into v_booking from public.bookings booking
  join public.patient_profiles patient on patient.id = booking.patient_profile_id
  where booking.id = p_booking_id and patient.user_id = p_patient_user_id
  for update of booking;
  if not found then
    raise exception 'SESSION_PRECHARGE_CANCEL_V10_FORBIDDEN' using errcode = '42501';
  end if;
  if v_payment.id is null or v_payment.payment_flow_version <> 'v10' then
    raise exception 'SESSION_PRECHARGE_CANCEL_V10_NOT_FOUND' using errcode = '23514';
  end if;

  select * into v_schedule from public.session_payment_schedules
  where session_payment_id = v_payment.id
  order by created_at desc limit 1 for update;

  if v_booking.status = 'cancelled_by_patient'
    and v_payment.financial_status = 'canceled'
    and v_schedule.status = 'canceled'
    and exists (
      select 1 from public.booking_events event
      where event.booking_id = v_booking.id
        and event.event_type = 'booking_status_changed'
        and event.request_id = trim(p_request_id)
        and event.next_status = 'cancelled_by_patient'
    )
  then
    return jsonb_build_object('bookingId', v_booking.id, 'canceled', true,
      'charged', false, 'applied', false);
  end if;

  -- This is the stale-modal guard. Once a claim, attempt, PaymentIntent,
  -- Charge or paid state exists, cancellation cannot retire the schedule.
  if v_payment.financial_status in (
      'processing', 'paid', 'partially_refunded', 'refunded', 'disputed'
    )
    or v_payment.stripe_payment_intent_id is not null
    or v_payment.stripe_charge_id is not null
    or v_payment.paid_at is not null
    or (
      v_schedule.id is not null
      and (
        v_schedule.status in (
          'claimed', 'processing', 'requires_customer_action',
          'retry_scheduled', 'paid'
        )
        or v_schedule.attempt_count <> 0
        or v_schedule.stripe_payment_intent_id is not null
        or v_schedule.stripe_charge_id is not null
        or v_schedule.lease_owner is not null
      )
    )
  then
    raise exception 'SESSION_PRECHARGE_CANCEL_V10_PAYMENT_CHANGED'
      using errcode = '23514';
  end if;

  if v_booking.status <> 'confirmed'
    or v_booking.starts_at <= v_now + interval '24 hours'
    or v_payment.financial_status <> 'pending'
    or v_schedule.id is null
    or v_schedule.status <> 'scheduled'
    or v_booking.version <> v_schedule.booking_version + 1
    or exists (select 1 from public.session_transfer_jobs job
      where job.session_payment_id = v_payment.id)
    or exists (select 1 from public.stripe_transfers transfer
      where transfer.session_payment_id = v_payment.id)
  then
    raise exception 'SESSION_PRECHARGE_CANCEL_V10_REQUIRES_SUPPORT'
      using errcode = '23514';
  end if;

  update public.session_payment_schedules
  set status = 'canceled', canceled_at = v_now,
      lease_owner = null, lease_expires_at = null, updated_at = v_now
  where id = v_schedule.id;

  update public.session_payment_setups
  set status = 'canceled', updated_at = v_now
  where id = v_schedule.session_payment_setup_id and status = 'succeeded';

  update public.session_promotion_reservations
  set status = 'released', released_at = v_now, updated_at = v_now
  where session_payment_id = v_payment.id and status = 'reserved';

  update public.session_payments
  set financial_status = 'canceled', transfer_status = 'not_eligible',
      canceled_at = v_now, updated_at = v_now
  where id = v_payment.id;

  perform public.transition_booking_status_v1(
    v_booking.id, 'cancelled_by_patient', p_patient_user_id,
    trim(p_reason), trim(p_request_id), v_booking.version,
    'request_session_cancellation'
  );
  update public.bookings
  set payment_status = 'cancelled', cancelled_at = v_now, updated_at = v_now
  where id = v_booking.id;

  return jsonb_build_object('bookingId', v_booking.id, 'canceled', true,
    'charged', false, 'applied', true);
end;
$$;


ALTER FUNCTION "public"."cancel_uncharged_session_v10"("p_booking_id" "uuid", "p_patient_user_id" "uuid", "p_request_id" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_uncharged_session_v10"("p_booking_id" "uuid", "p_patient_user_id" "uuid", "p_request_id" "text", "p_reason" "text") IS 'Cancels only a pristine V10 scheduled charge from freshly locked server state and rejects stale browser decisions after charge processing begins.';



CREATE OR REPLACE FUNCTION "public"."cancel_unstarted_initial_checkout_v1"("p_booking_id" "uuid", "p_hold_id" "uuid", "p_reason" "text" DEFAULT 'checkout_bootstrap_failed'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_hold public.booking_holds%rowtype;
  v_payment public.session_payments%rowtype;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  select * into v_hold
  from public.booking_holds
  where id = p_hold_id
  for update;

  if v_booking.id is null
    or v_hold.id is null
    or v_hold.consumed_booking_id is distinct from v_booking.id then
    return jsonb_build_object('released', false, 'reason', 'not_found');
  end if;

  if v_booking.status not in ('draft', 'pending_payment') then
    return jsonb_build_object('released', false, 'reason', v_booking.status);
  end if;

  select * into v_payment
  from public.session_payments
  where booking_id = v_booking.id
  for update;

  if v_payment.id is not null
    and (
      v_payment.stripe_checkout_session_id is not null
      or v_payment.financial_status not in ('pending', 'failed', 'canceled')
    ) then
    return jsonb_build_object('released', false, 'reason', 'checkout_persisted');
  end if;

  if v_payment.id is not null and v_payment.financial_status = 'pending' then
    update public.session_payments
    set financial_status = 'canceled',
        canceled_at = coalesce(canceled_at, now()),
        metadata = metadata || jsonb_build_object(
          'initial_checkout_terminal_reason',
          left(coalesce(nullif(trim(p_reason), ''), 'checkout_bootstrap_failed'), 120)
        ),
        updated_at = now()
    where id = v_payment.id;
  else
    perform pg_catalog.set_config('tes.booking_source', 'payment_state', true);
    update public.bookings
    set status = 'cancelled_by_payment',
        payment_status = 'failed',
        cancellation_reason = left(
          coalesce(nullif(trim(p_reason), ''), 'checkout_bootstrap_failed'),
          500
        ),
        cancelled_at = coalesce(cancelled_at, now()),
        last_transition_at = now(),
        version = version + 1,
        updated_at = now()
    where id = v_booking.id;
  end if;

  update public.session_payment_attempts
  set status = 'failed',
      terminal_reason = left(
        coalesce(nullif(trim(p_reason), ''), 'checkout_bootstrap_failed'),
        120
      ),
      updated_at = now()
  where session_payment_id = v_payment.id
    and status in ('created', 'checkout_created', 'waiting_payment');

  return jsonb_build_object('released', true, 'reason', p_reason);
end;
$$;


ALTER FUNCTION "public"."cancel_unstarted_initial_checkout_v1"("p_booking_id" "uuid", "p_hold_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_unstarted_initial_checkout_v1"("p_booking_id" "uuid", "p_hold_id" "uuid", "p_reason" "text") IS 'Releases only an unstarted initial checkout whose consumed hold never gained a persisted Stripe Checkout.';



CREATE OR REPLACE FUNCTION "public"."cancel_video_session_for_booking_v1"("p_booking_id" "uuid", "p_source" "text" DEFAULT 'system'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session_id uuid;
begin
  update public.video_sessions
  set status = case
        when status in ('active', 'ended') then status
        else 'canceled'::public.video_session_status
      end,
      metadata = metadata || jsonb_build_object(
        'cancelSource',
        left(coalesce(p_source, 'system'), 80)
      ),
      version = version + 1,
      updated_at = now()
  where booking_id = p_booking_id
  returning id into v_session_id;

  return v_session_id;
end;
$$;


ALTER FUNCTION "public"."cancel_video_session_for_booking_v1"("p_booking_id" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_availability_exception_history_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.availability_exceptions%rowtype;
begin
  if tg_op = 'DELETE' then
    v_row := old;
  else
    v_row := new;
  end if;

  insert into public.therapist_availability_history_coverage (
    therapist_profile_id,
    started_at
  ) values (v_row.therapist_profile_id, clock_timestamp())
  on conflict (therapist_profile_id) do nothing;

  insert into public.availability_exception_history (
    source_exception_id,
    therapist_profile_id,
    service_id,
    starts_at,
    ends_at,
    is_available,
    operation
  ) values (
    v_row.id,
    v_row.therapist_profile_id,
    v_row.service_id,
    v_row.starts_at,
    v_row.ends_at,
    v_row.is_available,
    lower(tg_op)
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."capture_availability_exception_history_v1"() OWNER TO "postgres";


