CREATE OR REPLACE FUNCTION "public"."claim_auth_action_token"("p_token_hash" "text", "p_purpose" "public"."auth_action_purpose", "p_claim_id" "uuid", "p_claim_lease_seconds" integer DEFAULT 120) RETURNS TABLE("id" "uuid", "user_id" "uuid", "recipient_email" "text", "recipient_role" "public"."user_role", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  update public.auth_action_tokens token
  set
    claimed_at = now(),
    claim_id = p_claim_id,
    claim_expires_at = now() + make_interval(secs => p_claim_lease_seconds)
  where token.token_hash = p_token_hash
    and token.purpose = p_purpose
    and token.expires_at > now()
    and token.consumed_at is null
    and token.revoked_at is null
    and (
      token.claimed_at is null
      or token.claim_expires_at is null
      or token.claim_expires_at < now()
      or token.claim_id = p_claim_id
    )
  returning
    token.id,
    token.user_id,
    token.recipient_email,
    token.recipient_role,
    token.expires_at;
end;
$$;


ALTER FUNCTION "public"."claim_auth_action_token"("p_token_hash" "text", "p_purpose" "public"."auth_action_purpose", "p_claim_id" "uuid", "p_claim_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_due_session_payment_schedules_v10"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_limit" integer DEFAULT 20, "p_lease_minutes" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_claims jsonb;
begin
  if p_now is null or p_worker_id is null
    or p_limit not between 1 and 100
    or p_lease_minutes not between 1 and 30
  then
    raise exception 'SESSION_PAYMENT_SCHEDULE_CLAIM_V10_INVALID' using errcode = '22023';
  end if;

  -- A worker that died after its fourth claim must not be retried forever.
  with exhausted as (
    select s.id
    from public.session_payment_schedules s
    where s.status in ('claimed', 'processing')
      and s.attempt_count >= 4
      and s.lease_expires_at <= p_now
    for update skip locked
  ), failed as (
    update public.session_payment_schedules s
    set status = 'failed', lease_owner = null, lease_expires_at = null,
        last_error_code = 'worker_lease_exhausted', last_failed_at = p_now,
        updated_at = p_now
    from exhausted where s.id = exhausted.id
    returning s.id
  )
  insert into public.session_charge_incidents_v10 (schedule_id, code)
  select id, 'worker_lease_exhausted' from failed
  on conflict (schedule_id) do update
    set code = excluded.code, status = 'open', resolved_at = null, updated_at = p_now;

  with candidates as (
    select s.id
    from public.session_payment_schedules s
    join public.session_payments p on p.id = s.session_payment_id
    join public.session_payment_setups setup on setup.id = s.session_payment_setup_id
    join public.bookings b on b.id = s.booking_id
    where s.status in ('scheduled', 'retry_scheduled', 'claimed', 'processing')
      and s.attempt_count < 4
      and coalesce(s.next_retry_at, s.due_at) <= p_now
      and (s.lease_expires_at is null or s.lease_expires_at <= p_now)
      and p.payment_flow_version = 'v10'
      and p.financial_status in ('pending', 'processing')
      and p.gross_amount_cents > 0
      and p.booking_id = s.booking_id
      and p.payment_due_at = s.due_at
      and setup.session_payment_id = p.id
      and setup.booking_id = b.id
      and setup.booking_version = s.booking_version
      and setup.stripe_environment = s.stripe_environment
      and setup.status = 'succeeded'
      and setup.superseded_at is null
      and setup.stripe_payment_method_id is not null
      -- Setup is bound to the pre-confirmation version. Confirming the
      -- booking is one operational transition and increments it exactly once.
      and b.version = s.expected_booking_version
      and b.status = 'confirmed'
      and b.starts_at > p_now
    order by coalesce(s.next_retry_at, s.due_at), s.id
    limit p_limit
    for update of s skip locked
  ), claimed as (
    update public.session_payment_schedules s
    set status = 'claimed', attempt_count = s.attempt_count + 1,
        lease_owner = p_worker_id,
        lease_expires_at = p_now + make_interval(mins => p_lease_minutes),
        claimed_at = p_now, updated_at = p_now
    from candidates where s.id = candidates.id
    returning s.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'scheduleId', s.id,
      'bookingId', s.booking_id,
      'bookingVersion', s.booking_version,
      'sessionPaymentId', s.session_payment_id,
      'setupId', setup.id,
      'stripeEnvironment', s.stripe_environment,
      'stripeCustomerId', setup.stripe_customer_id,
      'stripePaymentMethodId', setup.stripe_payment_method_id,
      'amountCents', p.gross_amount_cents,
      'currency', p.currency,
      'idempotencyKey', s.idempotency_key,
      'requestFingerprint', s.request_fingerprint,
      'attemptCount', s.attempt_count,
      'leaseExpiresAt', s.lease_expires_at
    ) order by s.due_at, s.id), '[]'::jsonb)
  into v_claims
  from claimed s
  join public.session_payment_setups setup on setup.id = s.session_payment_setup_id
  join public.session_payments p on p.id = s.session_payment_id;

  return jsonb_build_object('claims', v_claims, 'claimedAt', p_now);
end;
$$;


ALTER FUNCTION "public"."claim_due_session_payment_schedules_v10"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_limit" integer, "p_lease_minutes" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."email_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "action_key" "text" NOT NULL,
    "related_entity_type" "text" NOT NULL,
    "related_entity_id" "uuid" NOT NULL,
    "recipient_user_id" "uuid" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "public"."email_outbox_status" DEFAULT 'pending'::"public"."email_outbox_status" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"(),
    "last_error" "text",
    "locked_at" timestamp with time zone,
    "locked_by" "uuid",
    "processed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "domain_event_id" "uuid" NOT NULL,
    "recipient_key" "text" NOT NULL,
    "template_version" "text" DEFAULT 'v1'::"text" NOT NULL,
    "template_overrides" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "sender_profile_id" "uuid",
    "review_required" boolean DEFAULT false NOT NULL,
    "review_reason" "text",
    CONSTRAINT "email_outbox_attempts_check" CHECK ((("attempts" >= 0) AND ("attempts" <= 5))),
    CONSTRAINT "email_outbox_entity_check" CHECK (("related_entity_type" = ANY (ARRAY['auth_action_token'::"text", 'billing_invoice'::"text", 'booking'::"text", 'payout_operational_incident'::"text", 'session_payment'::"text", 'session_refund'::"text", 'stripe_payout'::"text", 'stripe_transfer'::"text", 'therapist_subscription'::"text", 'therapy_catalog_request'::"text", 'therapist_profile'::"text", 'therapist_verification'::"text"]))),
    CONSTRAINT "email_outbox_next_attempt_state_check" CHECK (((("status" = ANY (ARRAY['pending'::"public"."email_outbox_status", 'retry_pending'::"public"."email_outbox_status"])) AND ("next_attempt_at" IS NOT NULL)) OR (("status" = ANY (ARRAY['processing'::"public"."email_outbox_status", 'delivered'::"public"."email_outbox_status", 'skipped'::"public"."email_outbox_status", 'dead'::"public"."email_outbox_status"])) AND ("next_attempt_at" IS NULL)))),
    CONSTRAINT "email_outbox_payload_minimal" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "email_outbox_recipient_key_format" CHECK (("recipient_key" ~ '^[a-z][a-z0-9_-]*:[a-z0-9-]+$'::"text")),
    CONSTRAINT "email_outbox_template_overrides_object" CHECK (("jsonb_typeof"("template_overrides") = 'object'::"text"))
);


ALTER TABLE "public"."email_outbox" OWNER TO "postgres";


COMMENT ON TABLE "public"."email_outbox" IS 'Transactional e-mail outbox. Logical delivery is action + domain event + opaque recipient key; outbound delivery happens only after commit.';



CREATE OR REPLACE FUNCTION "public"."claim_email_outbox_v1"("p_worker_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS SETOF "public"."email_outbox"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_worker_id is null or p_limit < 1 or p_limit > 50 then
    raise exception 'EMAIL_OUTBOX_INVALID_CLAIM';
  end if;

  update public.email_outbox
  set
    status = 'dead',
    review_required = true,
    review_reason = 'delivery_outcome_unknown',
    last_error = 'delivery_outcome_unknown',
    next_attempt_at = null,
    processed_at = now(),
    locked_at = null,
    locked_by = null
  where status = 'processing'
    and locked_at < now() - interval '5 minutes';

  return query
  with candidates as (
    select id
    from public.email_outbox
    where status in ('pending', 'retry_pending')
      and next_attempt_at <= now()
    order by next_attempt_at, created_at
    limit p_limit
    for update skip locked
  )
  update public.email_outbox outbox
  set
    status = 'processing',
    attempts = outbox.attempts + 1,
    next_attempt_at = null,
    locked_at = now(),
    locked_by = p_worker_id
  from candidates
  where outbox.id = candidates.id
  returning outbox.*;
end;
$$;


ALTER FUNCTION "public"."claim_email_outbox_v1"("p_worker_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_financial_reconciliation_run_v1"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_lease_minutes" integer DEFAULT 45) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_scheduled_for timestamptz;
  v_run public.financial_reconciliation_runs%rowtype;
begin
  if p_now is null or p_worker_id is null or p_lease_minutes < 1 or p_lease_minutes > 55 then
    raise exception 'FINANCIAL_RECONCILIATION_CLAIM_INVALID';
  end if;

  v_scheduled_for := date_trunc('hour', p_now);

  insert into public.financial_reconciliation_runs (
    scheduled_for,
    worker_id,
    lease_expires_at
  ) values (
    v_scheduled_for,
    p_worker_id,
    p_now + make_interval(mins => p_lease_minutes)
  )
  on conflict (scheduled_for) do update
  set worker_id = excluded.worker_id,
      lease_expires_at = excluded.lease_expires_at,
      attempts = public.financial_reconciliation_runs.attempts + 1,
      status = 'running',
      last_error = null,
      completed_at = null,
      updated_at = now()
  where public.financial_reconciliation_runs.status = 'failed'
     or (
       public.financial_reconciliation_runs.status = 'running'
       and public.financial_reconciliation_runs.lease_expires_at <= p_now
     )
  returning * into v_run;

  if v_run.id is null then
    select * into v_run
    from public.financial_reconciliation_runs
    where scheduled_for = v_scheduled_for;

    return jsonb_build_object(
      'acquired', false,
      'runId', v_run.id,
      'status', v_run.status,
      'scheduledFor', v_run.scheduled_for
    );
  end if;

  return jsonb_build_object(
    'acquired', true,
    'runId', v_run.id,
    'status', v_run.status,
    'scheduledFor', v_run.scheduled_for
  );
end;
$$;


ALTER FUNCTION "public"."claim_financial_reconciliation_run_v1"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_lease_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_full_session_refund_v10_v2"("p_actor_user_id" "uuid", "p_session_payment_id" "uuid", "p_request_id" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_job public.session_transfer_jobs%rowtype;
  v_transfer public.stripe_transfers%rowtype;
  v_decision public.session_refund_decisions_v10%rowtype;
begin
  if p_actor_user_id is null or p_session_payment_id is null
    or length(btrim(coalesce(p_request_id, ''))) not between 8 and 128
    or length(btrim(coalesce(p_reason, ''))) not between 20 and 1000
    or not exists (select 1 from public.profiles where id = p_actor_user_id
      and role = 'admin' and auth_deleted_at is null and anonymized_at is null) then
    raise exception 'FULL_REFUND_REQUEST_INVALID' using errcode = '22023';
  end if;
  select * into v_payment from public.session_payments
  where id = p_session_payment_id for update;
  if not found or v_payment.payment_flow_version <> 'v10' then
    raise exception 'FULL_REFUND_PAYMENT_NOT_READY' using errcode = '23514';
  end if;
  select * into v_decision from public.session_refund_decisions_v10
  where session_payment_id = p_session_payment_id for update;
  if found then
    if v_decision.request_id <> btrim(p_request_id)
      or v_decision.reason <> btrim(p_reason) then
      raise exception 'FULL_REFUND_DECISION_ALREADY_EXISTS' using errcode = '23505';
    end if;
    return jsonb_build_object('decisionId', v_decision.id,
      'amountCents', v_decision.amount_cents, 'chargeId', v_decision.stripe_charge_id,
      'transferId', v_decision.stripe_transfer_id,
      'reversalState', v_decision.reversal_state,
      'refundState', v_decision.refund_state, 'existing', true);
  end if;
  if v_payment.financial_status <> 'paid' or v_payment.stripe_charge_id is null
    or v_payment.disputed_at is not null or v_payment.currency <> 'BRL'
    or v_payment.refund_pending or v_payment.admin_blocked_at is not null
    or exists (select 1 from public.session_refunds
      where session_payment_id = p_session_payment_id) then
    raise exception 'FULL_REFUND_REQUIRES_REVIEW' using errcode = '23514';
  end if;
  select * into v_job from public.session_transfer_jobs
  where session_payment_id = p_session_payment_id;
  if v_job.id is not null and (
    v_job.status in ('creating','reconciliation_required','failed','partially_reversed')
    or v_job.lease_owner is not null
    or (v_job.prepared_at is not null and v_job.status not in
      ('pending_source','transferred','offset_only','reversed'))
    or (v_job.status = 'pending_source' and v_job.stripe_transfer_id is null)
  ) then raise exception 'FULL_REFUND_TRANSFER_REQUIRES_REVIEW' using errcode = '23514'; end if;
  if v_job.stripe_transfer_id is not null then
    select * into v_transfer from public.stripe_transfers
    where id = v_job.stripe_transfer_id;
    if not found or v_transfer.stripe_transfer_id is null
      or v_transfer.transfer_origin <> 'session_direct'
      or v_transfer.session_payment_id <> v_payment.id
      or v_transfer.stripe_source_charge_id <> v_payment.stripe_charge_id
      or v_transfer.status not in ('transferred','reversed') then
      raise exception 'FULL_REFUND_TRANSFER_REQUIRES_REVIEW' using errcode = '23514';
    end if;
  end if;
  insert into public.session_refund_decisions_v10 (
    session_payment_id, actor_user_id, request_id, reason, amount_cents,
    therapist_exposure_cents, stripe_charge_id, stripe_transfer_id, reversal_state
  ) values (
    v_payment.id, p_actor_user_id, btrim(p_request_id), btrim(p_reason),
    v_payment.gross_amount_cents,
    case when v_job.prepared_at is not null then v_job.therapist_gross_amount_cents else 0 end,
    v_payment.stripe_charge_id, v_transfer.stripe_transfer_id,
    case when v_transfer.stripe_transfer_id is null or v_transfer.status = 'reversed'
      then 'not_needed' else 'not_attempted' end
  ) returning * into v_decision;
  update public.session_payments set refund_pending = true,
    admin_blocked_at = coalesce(admin_blocked_at, now()), updated_at = now()
  where id = v_payment.id;
  insert into public.admin_audit_events (
    actor_user_id, actor_role, permission, action, entity_type, entity_id,
    previous_state, next_state, reason, request_id, source
  ) values (
    p_actor_user_id, 'admin', 'admin.payments.refund', 'payment.full_refund_requested',
    'session_payment', v_payment.id::text,
    jsonb_build_object('financialStatus', v_payment.financial_status),
    jsonb_build_object('decisionId', v_decision.id, 'amountCents', v_decision.amount_cents),
    btrim(p_reason), btrim(p_request_id), 'admin'
  );
  return jsonb_build_object('decisionId', v_decision.id,
    'amountCents', v_decision.amount_cents, 'chargeId', v_decision.stripe_charge_id,
    'transferId', v_decision.stripe_transfer_id,
    'reversalState', v_decision.reversal_state,
    'refundState', v_decision.refund_state, 'existing', false);
end;
$$;


ALTER FUNCTION "public"."claim_full_session_refund_v10_v2"("p_actor_user_id" "uuid", "p_session_payment_id" "uuid", "p_request_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_full_session_refund_v10_v3"("p_actor_user_id" "uuid", "p_session_payment_id" "uuid", "p_request_id" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;
begin
  perform 1 from public.session_payments
  where id = p_session_payment_id for update;
  select actor_user_id into v_actor
  from public.session_refund_decisions_v10
  where session_payment_id = p_session_payment_id;
  if v_actor is not null and v_actor <> p_actor_user_id then
    raise exception 'FULL_REFUND_DECISION_ALREADY_EXISTS' using errcode = '23505';
  end if;
  return public.claim_full_session_refund_v10_v2(
    p_actor_user_id, p_session_payment_id, p_request_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."claim_full_session_refund_v10_v3"("p_actor_user_id" "uuid", "p_session_payment_id" "uuid", "p_request_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_payout_groups_v1"("p_payout_batch_id" "uuid", "p_worker_id" "uuid", "p_limit" integer DEFAULT 10, "p_lease_minutes" integer DEFAULT 5, "p_environment" "text" DEFAULT 'test'::"text") RETURNS TABLE("payout_id" "uuid", "payout_batch_therapist_id" "uuid", "therapist_profile_id" "uuid", "connect_account_id" "uuid", "stripe_account_id" "text", "amount_cents" integer, "idempotency_key" "text", "request_fingerprint" "text", "attempt_count" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    null::uuid,
    null::uuid,
    null::uuid,
    null::uuid,
    null::text,
    null::integer,
    null::text,
    null::text,
    null::integer
  where false;
$$;


ALTER FUNCTION "public"."claim_payout_groups_v1"("p_payout_batch_id" "uuid", "p_worker_id" "uuid", "p_limit" integer, "p_lease_minutes" integer, "p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_payout_transfer_items_v1"("p_payout_batch_id" "uuid", "p_worker_id" "uuid", "p_limit" integer DEFAULT 10, "p_lease_minutes" integer DEFAULT 5, "p_environment" "text" DEFAULT 'test'::"text") RETURNS TABLE("transfer_id" "uuid", "payout_batch_item_id" "uuid", "session_payment_id" "uuid", "booking_id" "uuid", "therapist_profile_id" "uuid", "connect_account_id" "uuid", "stripe_account_id" "text", "stripe_charge_id" "text", "amount_cents" integer, "idempotency_key" "text", "request_fingerprint" "text", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_payout_batch_id is null or p_worker_id is null
    or p_limit < 1 or p_limit > 50
    or p_lease_minutes < 1 or p_lease_minutes > 30
    or p_environment not in ('test', 'live')
  then
    raise exception 'PAYOUT_TRANSFER_CLAIM_INVALID';
  end if;

  return query
  with candidates as materialized (
    select item.id
    from public.payout_batch_items item
    where item.payout_batch_id = p_payout_batch_id
      and item.status in ('reserved', 'failed')
      and (
        not exists (
          select 1 from public.stripe_transfers existing
          where existing.payout_batch_item_id = item.id
        )
        or exists (
          select 1 from public.stripe_transfers retryable
          where retryable.payout_batch_item_id = item.id
            and retryable.status in ('failed', 'reconciliation_required')
            and retryable.next_retry_at <= now()
            and retryable.attempt_count < 4
            and (retryable.lease_expires_at is null or retryable.lease_expires_at <= now())
        )
      )
    order by item.created_at, item.id
    limit p_limit
    for update of item skip locked
  ), claimed_items as (
    update public.payout_batch_items item
    set status = 'transfer_pending', failure_code = null,
        failure_message = null, updated_at = now()
    from candidates
    where item.id = candidates.id
    returning item.*
  ), prepared as (
    insert into public.stripe_transfers (
      payout_batch_item_id, session_payment_id, therapist_profile_id,
      connect_account_id, idempotency_key, amount_cents, currency,
      status, stripe_source_charge_id, attempt_count, retry_cycle, lease_owner,
      lease_expires_at, request_fingerprint, last_attempt_at
    )
    select
      item.id, item.session_payment_id, item.therapist_profile_id,
      account.id,
      'tes:' || p_environment || ':transfer:' || item.id::text || ':cycle:0:attempt:1:v2',
      item.amount_cents, 'BRL', 'pending', payment.stripe_charge_id, 1, 0,
      p_worker_id, now() + make_interval(mins => p_lease_minutes),
      pg_catalog.encode(extensions.digest(
        pg_catalog.concat_ws('|', p_environment, item.id::text,
          item.amount_cents::text, 'BRL', account.stripe_account_id,
          payment.stripe_charge_id),
        'sha256'
      ), 'hex'),
      now()
    from claimed_items item
    join public.payout_batch_therapists therapist_group
      on therapist_group.id = item.payout_batch_therapist_id
      and therapist_group.payout_batch_id = item.payout_batch_id
      and therapist_group.therapist_profile_id = item.therapist_profile_id
    join public.session_payments payment
      on payment.id = item.session_payment_id
      and payment.booking_id = item.booking_id
      and payment.therapist_profile_id = item.therapist_profile_id
    join public.therapist_connect_accounts account
      on account.id = therapist_group.connect_account_id
      and account.therapist_profile_id = item.therapist_profile_id
    on conflict on constraint stripe_transfers_payout_batch_item_id_key do update
    set status = 'pending',
        idempotency_key = case
          when public.stripe_transfers.status = 'failed' then
            'tes:' || p_environment || ':transfer:' || excluded.payout_batch_item_id::text
              || ':cycle:' || public.stripe_transfers.retry_cycle::text
              || ':attempt:' || (public.stripe_transfers.attempt_count + 1)::text || ':v2'
          else public.stripe_transfers.idempotency_key
        end,
        attempt_count = public.stripe_transfers.attempt_count + 1,
        lease_owner = excluded.lease_owner,
        lease_expires_at = excluded.lease_expires_at,
        last_attempt_at = now(), failure_code = null, failure_message = null,
        updated_at = now()
    where public.stripe_transfers.attempt_count < 4
      and public.stripe_transfers.status in ('failed', 'reconciliation_required')
      and public.stripe_transfers.request_fingerprint = excluded.request_fingerprint
    returning public.stripe_transfers.*
  )
  select
    transfer.id, item.id, item.session_payment_id, item.booking_id,
    item.therapist_profile_id, account.id, account.stripe_account_id,
    payment.stripe_charge_id, item.amount_cents, transfer.idempotency_key,
    transfer.request_fingerprint, transfer.attempt_count
  from prepared transfer
  join public.payout_batch_items item on item.id = transfer.payout_batch_item_id
  join public.session_payments payment on payment.id = item.session_payment_id
  join public.therapist_connect_accounts account on account.id = transfer.connect_account_id;

  update public.session_payments payment
  set transfer_status = 'transfer_pending', updated_at = now()
  where exists (
    select 1 from public.payout_batch_items item
    join public.stripe_transfers transfer on transfer.payout_batch_item_id = item.id
    where item.session_payment_id = payment.id
      and transfer.lease_owner = p_worker_id and transfer.status = 'pending'
  );

  update public.payout_batches
  set status = 'processing', updated_at = now()
  where id = p_payout_batch_id and status in ('open', 'partially_failed');
end;
$$;


ALTER FUNCTION "public"."claim_payout_transfer_items_v1"("p_payout_batch_id" "uuid", "p_worker_id" "uuid", "p_limit" integer, "p_lease_minutes" integer, "p_environment" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_payout_transfer_items_v1"("p_payout_batch_id" "uuid", "p_worker_id" "uuid", "p_limit" integer, "p_lease_minutes" integer, "p_environment" "text") IS 'Claims immutable batch items; definitive provider rejections rotate the per-attempt idempotency key while ambiguous responses retain it for reconciliation.';



CREATE OR REPLACE FUNCTION "public"."claim_session_cancellation_decision_v1"("p_booking_id" "uuid", "p_session_payment_id" "uuid", "p_policy_version_id" "uuid", "p_requested_by_profile_id" "uuid", "p_requested_by_role" "text", "p_request_id" "uuid", "p_reason" "text", "p_decision" "text", "p_refund_amount_cents" integer, "p_retained_amount_cents" integer, "p_therapist_retained_cents" integer, "p_platform_retained_cents" integer, "p_requires_manual_review" boolean, "p_review_due_at" timestamp with time zone, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("id" "uuid", "booking_id" "uuid", "request_id" "uuid", "requested_by_profile_id" "uuid", "requested_by_role" "text", "session_payment_id" "uuid", "policy_version_id" "uuid", "reason" "text", "decision" "text", "refund_amount_cents" integer, "retained_amount_cents" integer, "therapist_retained_cents" integer, "platform_retained_cents" integer, "requires_manual_review" boolean, "review_due_at" timestamp with time zone, "created_new" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_existing public.session_cancellation_decisions%rowtype;
begin
  if p_requested_by_role not in ('admin', 'patient', 'therapist') then
    raise exception 'INVALID_CANCELLATION_ACTOR_ROLE' using errcode = '22023';
  end if;

  if p_reason is null
    or length(trim(p_reason)) = 0
    or p_decision is null
    or length(trim(p_decision)) = 0
    or p_refund_amount_cents < 0
    or p_retained_amount_cents < 0
    or p_therapist_retained_cents < 0
    or p_platform_retained_cents < 0
    or p_retained_amount_cents <> p_therapist_retained_cents + p_platform_retained_cents then
    raise exception 'INVALID_CANCELLATION_DECISION' using errcode = '22023';
  end if;

  select *
    into v_existing
  from public.session_cancellation_decisions as cancellation
  where cancellation.request_id = p_request_id
  for update;

  if found then
    if v_existing.booking_id <> p_booking_id
      or v_existing.requested_by_profile_id is distinct from p_requested_by_profile_id
      or v_existing.requested_by_role <> p_requested_by_role then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;

    return query
    select
      v_existing.id,
      v_existing.booking_id,
      v_existing.request_id,
      v_existing.requested_by_profile_id,
      v_existing.requested_by_role,
      v_existing.session_payment_id,
      v_existing.policy_version_id,
      v_existing.reason,
      v_existing.decision,
      v_existing.refund_amount_cents,
      v_existing.retained_amount_cents,
      v_existing.therapist_retained_cents,
      v_existing.platform_retained_cents,
      v_existing.requires_manual_review,
      v_existing.review_due_at,
      false;
    return;
  end if;

  select *
    into v_booking
  from public.bookings as booking
  where booking.id = p_booking_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND' using errcode = 'P0002';
  end if;

  select *
    into v_existing
  from public.session_cancellation_decisions as cancellation
  where cancellation.booking_id = p_booking_id
  order by cancellation.created_at desc, cancellation.id desc
  limit 1
  for update;

  if found then
    return query
    select
      v_existing.id,
      v_existing.booking_id,
      v_existing.request_id,
      v_existing.requested_by_profile_id,
      v_existing.requested_by_role,
      v_existing.session_payment_id,
      v_existing.policy_version_id,
      v_existing.reason,
      v_existing.decision,
      v_existing.refund_amount_cents,
      v_existing.retained_amount_cents,
      v_existing.therapist_retained_cents,
      v_existing.platform_retained_cents,
      v_existing.requires_manual_review,
      v_existing.review_due_at,
      false;
    return;
  end if;

  insert into public.session_cancellation_decisions (
    booking_id,
    session_payment_id,
    policy_version_id,
    requested_by_profile_id,
    requested_by_role,
    request_id,
    reason,
    decision,
    refund_amount_cents,
    retained_amount_cents,
    therapist_retained_cents,
    platform_retained_cents,
    requires_manual_review,
    review_due_at,
    metadata
  ) values (
    p_booking_id,
    p_session_payment_id,
    p_policy_version_id,
    p_requested_by_profile_id,
    p_requested_by_role,
    p_request_id,
    trim(p_reason),
    trim(p_decision),
    p_refund_amount_cents,
    p_retained_amount_cents,
    p_therapist_retained_cents,
    p_platform_retained_cents,
    p_requires_manual_review,
    p_review_due_at,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning * into v_existing;

  return query
  select
    v_existing.id,
    v_existing.booking_id,
    v_existing.request_id,
    v_existing.requested_by_profile_id,
    v_existing.requested_by_role,
    v_existing.session_payment_id,
    v_existing.policy_version_id,
    v_existing.reason,
    v_existing.decision,
    v_existing.refund_amount_cents,
    v_existing.retained_amount_cents,
    v_existing.therapist_retained_cents,
    v_existing.platform_retained_cents,
    v_existing.requires_manual_review,
    v_existing.review_due_at,
    true;
end;
$$;


ALTER FUNCTION "public"."claim_session_cancellation_decision_v1"("p_booking_id" "uuid", "p_session_payment_id" "uuid", "p_policy_version_id" "uuid", "p_requested_by_profile_id" "uuid", "p_requested_by_role" "text", "p_request_id" "uuid", "p_reason" "text", "p_decision" "text", "p_refund_amount_cents" integer, "p_retained_amount_cents" integer, "p_therapist_retained_cents" integer, "p_platform_retained_cents" integer, "p_requires_manual_review" boolean, "p_review_due_at" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_session_cancellation_decision_v1"("p_booking_id" "uuid", "p_session_payment_id" "uuid", "p_policy_version_id" "uuid", "p_requested_by_profile_id" "uuid", "p_requested_by_role" "text", "p_request_id" "uuid", "p_reason" "text", "p_decision" "text", "p_refund_amount_cents" integer, "p_retained_amount_cents" integer, "p_therapist_retained_cents" integer, "p_platform_retained_cents" integer, "p_requires_manual_review" boolean, "p_review_due_at" timestamp with time zone, "p_metadata" "jsonb") IS 'Atomically claims one cancellation decision per booking and replays the original financial command for retries.';



CREATE OR REPLACE FUNCTION "public"."claim_session_payment_authorization_v1"("p_session_payment_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text", "p_event_created_at" timestamp with time zone, "p_request_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.session_payment_attempts%rowtype;
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
begin
  select * into v_payment
  from public.session_payments
  where id = p_session_payment_id
  for update;

  if not found then
    return jsonb_build_object('claimed', false, 'reason', 'payment_not_found');
  end if;

  if v_payment.stripe_checkout_session_id is distinct from
    p_stripe_checkout_session_id then
    return jsonb_build_object('claimed', false, 'reason', 'superseded');
  end if;

  select * into v_attempt
  from public.session_payment_attempts
  where session_payment_id = v_payment.id
    and stripe_checkout_session_id = p_stripe_checkout_session_id
  for update;

  if not found or v_attempt.attempt_kind = 'legacy' then
    return jsonb_build_object('claimed', false, 'reason', 'attempt_not_found');
  end if;

  if v_attempt.slot_claimed_at is not null then
    return jsonb_build_object('claimed', true, 'reason', 'already_claimed');
  end if;

  if v_attempt.status in ('expired', 'slot_conflict', 'failed', 'canceled') then
    return jsonb_build_object(
      'claimed', false,
      'reason', coalesce(v_attempt.terminal_reason, v_attempt.status)
    );
  end if;

  if v_attempt.attempt_kind = 'initial_hold'
    and (
      v_attempt.reservation_expires_at is null
      or p_event_created_at > v_attempt.reservation_expires_at
      or now() > v_attempt.reservation_expires_at
    ) then
    update public.session_payment_attempts
    set status = 'expired', terminal_reason = 'reservation_expired',
        updated_at = now()
    where id = v_attempt.id;

    update public.session_payments
    set financial_status = 'canceled', canceled_at = coalesce(canceled_at, now()),
        updated_at = now()
    where id = v_payment.id and financial_status in ('pending', 'processing');

    return jsonb_build_object('claimed', false, 'reason', 'expired');
  end if;

  select * into v_booking
  from public.bookings
  where id = v_payment.booking_id
  for update;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_booking.therapist_profile_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-schedule:' || v_booking.patient_profile_id::text,
      0
    )
  );
  perform public.expire_booking_holds_v1(now(), v_booking.therapist_profile_id);

  if public.patient_has_schedule_conflict_v1(
    v_booking.patient_profile_id,
    v_booking.starts_at,
    v_booking.ends_at,
    v_booking.id
  ) then
    update public.session_payment_attempts
    set status = 'slot_conflict',
        terminal_reason = 'patient_schedule_conflict',
        authorization_received_at = coalesce(
          authorization_received_at,
          p_event_created_at
        ),
        stripe_payment_intent_id = coalesce(
          p_stripe_payment_intent_id,
          stripe_payment_intent_id
        ),
        updated_at = now()
    where id = v_attempt.id;

    return jsonb_build_object(
      'claimed', false,
      'reason', 'patient_schedule_conflict'
    );
  end if;

  if v_attempt.attempt_kind = 'payment_retry' then
    if v_booking.status <> 'cancelled_by_payment'
      or v_payment.financial_status not in ('failed', 'canceled') then
      return jsonb_build_object('claimed', false, 'reason', 'booking_not_retryable');
    end if;

    begin
      perform pg_catalog.set_config('tes.booking_reason', 'payment_retry_authorized', true);
      perform pg_catalog.set_config('tes.booking_source', 'payment_retry_claim', true);
      perform pg_catalog.set_config('tes.booking_request_id', left(p_request_id, 200), true);

      update public.bookings
      set status = 'pending_payment', cancellation_reason = null,
          cancelled_at = null, payment_status = 'pending', updated_at = now()
      where id = v_booking.id;
    exception
      when exclusion_violation or raise_exception then
        perform pg_catalog.set_config('tes.booking_reason', '', true);
        perform pg_catalog.set_config('tes.booking_source', '', true);
        perform pg_catalog.set_config('tes.booking_request_id', '', true);
        update public.session_payment_attempts
        set status = 'slot_conflict', terminal_reason = 'slot_conflict',
            authorization_received_at = coalesce(
              authorization_received_at,
              p_event_created_at
            ),
            stripe_payment_intent_id = coalesce(
              p_stripe_payment_intent_id,
              stripe_payment_intent_id
            ),
            updated_at = now()
        where id = v_attempt.id;
        return jsonb_build_object('claimed', false, 'reason', 'slot_conflict');
    end;
  elsif v_booking.status not in ('draft', 'pending_payment') then
    return jsonb_build_object('claimed', false, 'reason', 'booking_not_payable');
  end if;

  perform pg_catalog.set_config('tes.booking_reason', '', true);
  perform pg_catalog.set_config('tes.booking_source', '', true);
  perform pg_catalog.set_config('tes.booking_request_id', '', true);

  update public.session_payments
  set financial_status = 'processing',
      stripe_payment_intent_id = coalesce(
        p_stripe_payment_intent_id,
        stripe_payment_intent_id
      ),
      failed_at = null, canceled_at = null, updated_at = now()
  where id = v_payment.id;

  update public.session_payment_attempts
  set status = 'capture_pending',
      authorization_received_at = coalesce(
        authorization_received_at,
        p_event_created_at
      ),
      slot_claimed_at = coalesce(slot_claimed_at, now()),
      stripe_payment_intent_id = coalesce(
        p_stripe_payment_intent_id,
        stripe_payment_intent_id
      ),
      updated_at = now()
  where id = v_attempt.id;

  return jsonb_build_object('claimed', true, 'reason', 'claimed');
end;
$$;


ALTER FUNCTION "public"."claim_session_payment_authorization_v1"("p_session_payment_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text", "p_event_created_at" timestamp with time zone, "p_request_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_session_payment_authorization_v1"("p_session_payment_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text", "p_event_created_at" timestamp with time zone, "p_request_id" "text") IS 'Claims therapist then patient locks before manual Stripe capture; payment retry can reopen cancelled_by_payment only through this RPC.';



CREATE OR REPLACE FUNCTION "public"."claim_session_transfer_jobs_v10"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_limit" integer DEFAULT 20, "p_lease_minutes" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_claims jsonb;
begin
  if p_now is null or p_worker_id is null
    or p_limit not between 1 and 100
    or p_lease_minutes not between 1 and 30 then
    raise exception 'SESSION_TRANSFER_JOB_CLAIM_V10_INVALID' using errcode = '22023';
  end if;

  with candidates as (
    select job.id
    from public.session_transfer_jobs job
    join public.session_payments payment on payment.id = job.session_payment_id
    where payment.payment_flow_version = 'v10'
      and payment.financial_status = 'paid'
      and not payment.refund_pending
      and job.status in ('queued', 'creating', 'reconciliation_required')
      and job.attempt_count < 8
      and coalesce(job.next_retry_at, job.created_at) <= p_now
      and (job.lease_expires_at is null or job.lease_expires_at <= p_now)
    order by coalesce(job.next_retry_at, job.created_at), job.id
    limit p_limit
    for update of job skip locked
  ), claimed as (
    update public.session_transfer_jobs job
    set status = 'creating', attempt_count = job.attempt_count + 1,
        lease_owner = p_worker_id,
        lease_expires_at = p_now + make_interval(mins => p_lease_minutes),
        updated_at = p_now
    from candidates where candidates.id = job.id
    returning job.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'jobId', claimed.id,
    'sessionPaymentId', claimed.session_payment_id,
    'stripeEnvironment', claimed.stripe_environment,
    'attemptCount', claimed.attempt_count,
    'bookingId', claimed.booking_id,
    'therapistProfileId', payment.therapist_profile_id,
    'paymentIntentId', payment.stripe_payment_intent_id,
    'grossAmountCents', payment.gross_amount_cents,
    'stripeAccountId', account.stripe_account_id,
    'sourceChargeId', claimed.stripe_source_charge_id
  ) order by claimed.created_at, claimed.id), '[]'::jsonb)
  into v_claims
  from claimed
  join public.session_payments payment on payment.id = claimed.session_payment_id
  join public.therapist_connect_accounts account on account.id = claimed.connect_account_id;
  return jsonb_build_object('claims', v_claims, 'claimedAt', p_now);
end;
$$;


ALTER FUNCTION "public"."claim_session_transfer_jobs_v10"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_limit" integer, "p_lease_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_weekly_payout_scheduler_run_v1"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_lease_minutes" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_local timestamp;
  v_business_date date;
  v_cutoff_at timestamptz;
  v_window_open boolean;
  v_run public.payout_scheduler_runs%rowtype;
  v_batch_id uuid;
begin
  if p_now is null or p_worker_id is null or p_lease_minutes < 1 or p_lease_minutes > 30 then
    raise exception 'PAYOUT_SCHEDULER_CLAIM_INVALID';
  end if;

  v_local := p_now at time zone 'America/Sao_Paulo';
  v_business_date := v_local::date;
  v_window_open := extract(dow from v_local)::integer = 2
    and v_local::time >= time '02:00'
    and v_local::time < time '04:00';

  select * into v_run
  from public.payout_scheduler_runs
  where status = 'running'
  order by business_date asc
  limit 1
  for update skip locked;

  if v_run.id is not null and v_run.next_retry_at is not null and v_run.next_retry_at > p_now then
    return jsonb_build_object(
      'acquired', false,
      'reason', 'backoff_active',
      'runId', v_run.id,
      'batchId', v_run.payout_batch_id,
      'retryAt', v_run.next_retry_at
    );
  end if;

  if v_run.id is not null
    and v_run.worker_id is distinct from p_worker_id
    and v_run.lease_expires_at is not null
    and v_run.lease_expires_at > p_now
  then
    return jsonb_build_object('acquired', false, 'reason', 'already_claimed');
  end if;

  if v_run.id is null and not v_window_open then
    return jsonb_build_object('acquired', false, 'reason', 'outside_start_window');
  end if;

  if v_run.id is null then
    v_cutoff_at := make_timestamptz(
      extract(year from v_business_date)::integer,
      extract(month from v_business_date)::integer,
      extract(day from v_business_date)::integer,
      2, 0, 0, 'America/Sao_Paulo'
    );
    perform pg_advisory_xact_lock(hashtextextended('tes-weekly-payout:' || v_business_date::text, 0));

    insert into public.payout_scheduler_runs (
      business_date, reference_period_start, reference_period_end,
      cutoff_at, status, worker_id, lease_expires_at, attempts
    ) values (
      v_business_date, v_business_date - 7, v_business_date - 1,
      v_cutoff_at, 'running', p_worker_id,
      p_now + make_interval(mins => p_lease_minutes), 1
    )
    on conflict (business_date) do update
    set worker_id = excluded.worker_id,
        lease_expires_at = excluded.lease_expires_at,
        attempts = public.payout_scheduler_runs.attempts + 1,
        updated_at = now()
    where public.payout_scheduler_runs.status = 'running'
      and (public.payout_scheduler_runs.next_retry_at is null or public.payout_scheduler_runs.next_retry_at <= p_now)
      and (
        public.payout_scheduler_runs.lease_expires_at is null
        or public.payout_scheduler_runs.lease_expires_at <= p_now
        or public.payout_scheduler_runs.worker_id = p_worker_id
      )
    returning * into v_run;

    if v_run.id is null then
      return jsonb_build_object('acquired', false, 'reason', 'already_claimed');
    end if;
  else
    update public.payout_scheduler_runs
    set worker_id = p_worker_id,
        lease_expires_at = p_now + make_interval(mins => p_lease_minutes),
        attempts = attempts + 1,
        updated_at = now()
    where id = v_run.id
    returning * into v_run;
  end if;

  if v_run.payout_batch_id is null then
    v_batch_id := public.create_weekly_payout_batch_v2(
      v_run.reference_period_start,
      v_run.reference_period_end,
      v_run.cutoff_at,
      null
    );
    if v_batch_id is not null then
      update public.payout_scheduler_runs
      set payout_batch_id = v_batch_id, updated_at = now()
      where id = v_run.id
      returning * into v_run;
    end if;
  end if;

  return jsonb_build_object(
    'acquired', true,
    'runId', v_run.id,
    'batchId', v_run.payout_batch_id,
    'businessDate', v_run.business_date,
    'cutoffAt', v_run.cutoff_at,
    'windowOpen', v_window_open,
    'reason', case when v_run.payout_batch_id is null then 'no_eligible_payments' else null end
  );
end;
$$;


ALTER FUNCTION "public"."claim_weekly_payout_scheduler_run_v1"("p_now" timestamp with time zone, "p_worker_id" "uuid", "p_lease_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_unpaid_session_payment_v10"("p_schedule_id" "uuid", "p_booking_id" "uuid", "p_observed_stripe_status" "text", "p_now" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
  v_booking public.bookings%rowtype;
  v_patient_user_id uuid;
  v_therapist_user_id uuid;
  v_event_id text;
begin
  if p_schedule_id is null or p_booking_id is null or p_now is null
    or p_observed_stripe_status not in (
      'not_created', 'canceled', 'requires_action', 'requires_payment_method'
    ) then
    raise exception 'SESSION_PAYMENT_CLOSURE_V10_INVALID' using errcode = '22023';
  end if;

  -- Same lock order as payment reconciliation: payment, schedule, booking.
  select payment.* into v_payment
  from public.session_payments payment
  join public.session_payment_schedules schedule
    on schedule.session_payment_id = payment.id
  where schedule.id = p_schedule_id
  for update of payment;
  select * into v_schedule from public.session_payment_schedules
  where id = p_schedule_id for update;
  select * into v_booking from public.bookings
  where id = p_booking_id for update;

  if v_schedule.status = 'canceled'
    and v_booking.status = 'cancelled_by_payment'
    and v_payment.financial_status in ('failed', 'canceled')
  then
    return jsonb_build_object('closed', true, 'applied', false, 'bookingId', v_booking.id);
  end if;

  if not found or v_payment.id is null or v_schedule.id is null
    or v_payment.payment_flow_version <> 'v10'
    or v_schedule.booking_id <> v_booking.id
    or v_schedule.booking_id <> p_booking_id
    or v_schedule.session_payment_id <> v_payment.id
    or v_booking.status <> 'confirmed'
    or v_booking.version <> v_schedule.expected_booking_version
    or v_booking.starts_at > p_now
    or v_payment.financial_status not in ('pending', 'processing')
    or v_schedule.status not in (
      'scheduled', 'requires_customer_action', 'retry_scheduled', 'failed'
    )
    or (p_observed_stripe_status = 'not_created' and (
      v_schedule.status <> 'scheduled'
      or v_schedule.stripe_payment_intent_id is not null
    ))
    or (p_observed_stripe_status <> 'not_created'
      and v_schedule.stripe_payment_intent_id is null)
  then
    raise exception 'SESSION_PAYMENT_CLOSURE_V10_NOT_ALLOWED' using errcode = '23514';
  end if;

  v_event_id := 'scheduler:v10:unpaid-at-start:' || v_schedule.id::text;
  perform public.apply_session_payment_state_v1(
    v_payment.id,
    case when p_observed_stripe_status = 'canceled'
      then 'canceled'::public.session_financial_status
      else 'failed'::public.session_financial_status end,
    v_event_id,
    p_now,
    v_schedule.stripe_payment_intent_id,
    null,
    null
  );

  update public.session_payment_schedules set
    status = 'canceled', lease_owner = null, lease_expires_at = null,
    next_retry_at = null, last_error_code = 'payment_not_completed_before_session',
    last_failed_at = p_now, updated_at = p_now
  where id = v_schedule.id;

  perform pg_catalog.set_config('tes.booking_reason', 'payment_not_completed_before_session', true);
  perform pg_catalog.set_config('tes.booking_source', 'payment_state', true);
  perform pg_catalog.set_config('tes.booking_request_id', v_event_id, true);
  update public.bookings set
    status = 'cancelled_by_payment',
    payment_status = case when p_observed_stripe_status = 'canceled'
      then 'cancelled'::public.payment_status else 'failed'::public.payment_status end,
    cancellation_reason = 'payment_not_completed_before_session',
    cancelled_at = coalesce(cancelled_at, p_now), updated_at = p_now
  where id = v_booking.id;
  perform pg_catalog.set_config('tes.booking_reason', '', true);
  perform pg_catalog.set_config('tes.booking_source', '', true);
  perform pg_catalog.set_config('tes.booking_request_id', '', true);

  update public.session_charge_recoveries_v10 set status = 'canceled'
  where schedule_id = v_schedule.id and status = 'open';
  update public.session_charge_incidents_v10 set
    status = 'resolved', resolved_at = p_now, updated_at = p_now
  where schedule_id = v_schedule.id and status = 'open';

  select patient.user_id, therapist.user_id
  into v_patient_user_id, v_therapist_user_id
  from public.patient_profiles patient, public.therapist_profiles therapist
  where patient.id = v_booking.patient_profile_id
    and therapist.id = v_booking.therapist_profile_id;
  insert into public.notifications(profile_id, kind, title, body, href, event_key)
  values
    (v_patient_user_id, 'session_payment_incomplete_patient',
      'Pagamento não concluído',
      'O pagamento não foi confirmado a tempo e o encontro foi cancelado.',
      '/app/encontros/' || v_booking.id::text,
      'session-payment-closure:' || v_schedule.id::text || ':patient'),
    (v_therapist_user_id, 'session_payment_incomplete_therapist',
      'Sessão cancelada',
      'O pagamento não foi confirmado e o horário foi liberado.',
      '/terapeuta/sessoes/' || v_booking.id::text,
      'session-payment-closure:' || v_schedule.id::text || ':therapist')
  on conflict (profile_id, event_key) where event_key is not null do nothing;

  return jsonb_build_object('closed', true, 'applied', true, 'bookingId', v_booking.id);
end;
$$;


ALTER FUNCTION "public"."close_unpaid_session_payment_v10"("p_schedule_id" "uuid", "p_booking_id" "uuid", "p_observed_stripe_status" "text", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_direct_transfer_from_paid_payout_v10"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'paid'
    and new.provider_reconciliation_status = 'completed'
    and new.allocation_status = 'completed' then
    update public.session_transfer_jobs job
    set status = 'transferred', updated_at = now()
    from public.stripe_payout_transfer_allocations allocation
    join public.stripe_transfers transfer on transfer.id = allocation.stripe_transfer_id
    where allocation.stripe_payout_id = new.id
      and allocation.allocation_origin = 'session_direct'
      and transfer.transfer_origin = 'session_direct'
      and job.stripe_transfer_id = transfer.id
      and job.status = 'pending_source';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."complete_direct_transfer_from_paid_payout_v10"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_email_outbox_v1"("p_outbox_id" "uuid", "p_worker_id" "uuid", "p_outcome" "public"."email_outbox_status", "p_last_error" "text" DEFAULT NULL::"text", "p_review_required" boolean DEFAULT false, "p_review_reason" "text" DEFAULT NULL::"text") RETURNS "public"."email_outbox"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.email_outbox;
begin
  if p_outcome not in ('delivered', 'skipped', 'retry_pending', 'dead') then
    raise exception 'EMAIL_OUTBOX_INVALID_OUTCOME';
  end if;

  update public.email_outbox
  set
    status = case
      when p_outcome = 'retry_pending' and attempts >= 5 then 'dead'::public.email_outbox_status
      else p_outcome
    end,
    next_attempt_at = case
      when p_outcome = 'retry_pending' and attempts < 5 then
        now() + make_interval(secs => least(3600, 30 * power(2, attempts - 1)::integer))
      else null
    end,
    last_error = nullif(regexp_replace(coalesce(p_last_error, ''), '[\r\n]+', ' ', 'g'), '')::text,
    review_required = p_review_required or (p_outcome = 'retry_pending' and attempts >= 5),
    review_reason = case
      when p_review_required then nullif(regexp_replace(coalesce(p_review_reason, ''), '[\r\n]+', ' ', 'g'), '')::text
      when p_outcome = 'retry_pending' and attempts >= 5 then 'retry_limit_exhausted'
      else null
    end,
    locked_at = null,
    locked_by = null,
    processed_at = case
      when p_outcome in ('delivered', 'skipped', 'dead') or attempts >= 5 then now()
      else null
    end
  where id = p_outbox_id
    and status = 'processing'
    and locked_by = p_worker_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'EMAIL_OUTBOX_CLAIM_LOST';
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."complete_email_outbox_v1"("p_outbox_id" "uuid", "p_worker_id" "uuid", "p_outcome" "public"."email_outbox_status", "p_last_error" "text", "p_review_required" boolean, "p_review_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payout_transfer_v1"("p_transfer_id" "uuid", "p_worker_id" "uuid", "p_stripe_transfer_id" "text", "p_transferred_at" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfer public.stripe_transfers%rowtype;
  v_item public.payout_batch_items%rowtype;
  v_payment public.session_payments%rowtype;
begin
  select * into v_transfer
  from public.stripe_transfers
  where id = p_transfer_id
  for update;

  if not found then raise exception 'PAYOUT_TRANSFER_NOT_FOUND'; end if;
  if v_transfer.status = 'transferred' then return true; end if;
  if v_transfer.lease_owner <> p_worker_id or v_transfer.lease_expires_at < now() then
    raise exception 'PAYOUT_TRANSFER_CLAIM_LOST';
  end if;
  if nullif(trim(p_stripe_transfer_id), '') is null then
    raise exception 'PAYOUT_TRANSFER_PROVIDER_ID_INVALID';
  end if;

  select * into v_item from public.payout_batch_items
  where id = v_transfer.payout_batch_item_id for update;
  select * into v_payment from public.session_payments
  where id = v_transfer.session_payment_id for update;

  update public.stripe_transfers
  set stripe_transfer_id = p_stripe_transfer_id,
      status = 'transferred', transferred_at = p_transferred_at,
      lease_owner = null, lease_expires_at = null, next_retry_at = null,
      failure_code = null, failure_message = null, updated_at = now()
  where id = v_transfer.id;

  update public.payout_batch_items
  set status = 'transferred', failure_code = null, failure_message = null,
      updated_at = now()
  where id = v_item.id;

  update public.session_payments
  set transfer_status = 'transferred', transfer_blocked_reason = null,
      updated_at = now()
  where id = v_payment.id;

  insert into public.financial_ledger_entries (
    entry_type, direction, currency, amount_cents, therapist_profile_id,
    booking_id, session_payment_id, payout_batch_id, stripe_transfer_id,
    source_table, source_id, occurred_at
  ) values (
    'transfer', 'debit', v_transfer.currency, v_transfer.amount_cents,
    v_transfer.therapist_profile_id, v_item.booking_id,
    v_transfer.session_payment_id, v_item.payout_batch_id, v_transfer.id,
    'stripe_transfers', v_transfer.id, p_transferred_at
  ) on conflict do nothing;

  return true;
end;
$$;


ALTER FUNCTION "public"."complete_payout_transfer_v1"("p_transfer_id" "uuid", "p_worker_id" "uuid", "p_stripe_transfer_id" "text", "p_transferred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payout_transfer_v2"("p_transfer_id" "uuid", "p_worker_id" "uuid", "p_stripe_transfer_id" "text", "p_stripe_destination_payment_id" "text", "p_stripe_connected_balance_transaction_id" "text" DEFAULT NULL::"text", "p_connected_balance_available_on" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_transferred_at" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if nullif(trim(p_stripe_destination_payment_id), '') is null then
    raise exception 'PAYOUT_TRANSFER_DESTINATION_PAYMENT_REQUIRED';
  end if;

  perform public.complete_payout_transfer_v1(
    p_transfer_id, p_worker_id, p_stripe_transfer_id, p_transferred_at
  );

  update public.stripe_transfers
  set stripe_destination_payment_id = coalesce(
        stripe_destination_payment_id, p_stripe_destination_payment_id
      ),
      stripe_connected_balance_transaction_id = coalesce(
        stripe_connected_balance_transaction_id,
        nullif(trim(p_stripe_connected_balance_transaction_id), '')
      ),
      connected_balance_available_on = coalesce(
        connected_balance_available_on, p_connected_balance_available_on
      ),
      updated_at = now()
  where id = p_transfer_id
    and stripe_transfer_id = p_stripe_transfer_id
    and (
      stripe_destination_payment_id is null
      or stripe_destination_payment_id = p_stripe_destination_payment_id
    );

  if not found then
    raise exception 'PAYOUT_TRANSFER_DESTINATION_PAYMENT_MISMATCH';
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."complete_payout_transfer_v2"("p_transfer_id" "uuid", "p_worker_id" "uuid", "p_stripe_transfer_id" "text", "p_stripe_destination_payment_id" "text", "p_stripe_connected_balance_transaction_id" "text", "p_connected_balance_available_on" timestamp with time zone, "p_transferred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_session_payment_setup_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_stripe_checkout_session_id" "text", "p_stripe_customer_id" "text", "p_stripe_setup_intent_id" "text", "p_stripe_payment_method_id" "text", "p_consent_version" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_customer public.stripe_customers%rowtype;
  v_payment public.session_payments%rowtype;
  v_schedule jsonb;
  v_schedule_key text;
  v_setup jsonb;
  v_setup_id uuid;
  v_fingerprint text;
begin
  if p_session_payment_id is null
    or p_booking_version is null or p_booking_version <= 0
    or p_stripe_environment not in ('test', 'live')
    or nullif(trim(p_stripe_checkout_session_id), '') is null
    or nullif(trim(p_stripe_customer_id), '') is null
    or nullif(trim(p_stripe_setup_intent_id), '') is null
    or nullif(trim(p_stripe_payment_method_id), '') is null
    or nullif(trim(p_consent_version), '') is null
    or nullif(trim(p_stripe_event_id), '') is null
    or p_stripe_event_created_at is null
  then
    raise exception 'SESSION_PAYMENT_SETUP_COMPLETION_V10_INVALID'
      using errcode = '22023';
  end if;

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.id = p_session_payment_id
  for update;

  if not found
    or v_payment.payment_flow_version <> 'v10'
    or v_payment.financial_status <> 'pending'
    or v_payment.stripe_checkout_session_id <> trim(p_stripe_checkout_session_id)
  then
    raise exception 'SESSION_PAYMENT_SETUP_COMPLETION_V10_CONFLICT'
      using errcode = '23514';
  end if;

  select customer.*
  into v_customer
  from public.stripe_customers as customer
  where customer.id = v_payment.stripe_customer_id;

  if not found
    or v_customer.stripe_customer_id <> trim(p_stripe_customer_id)
    or v_customer.environment <> p_stripe_environment
  then
    raise exception 'SESSION_PAYMENT_SETUP_CUSTOMER_V10_CONFLICT'
      using errcode = '23514';
  end if;

  select booking.*
  into v_booking
  from public.bookings as booking
  where booking.id = v_payment.booking_id
  for update;

  if not found or v_booking.legal_acceptance_recorded_at is null
  then
    raise exception 'SESSION_PAYMENT_SETUP_CONSENT_V10_MISSING'
      using errcode = '23514';
  end if;

  select setup.id
  into v_setup_id
  from public.session_payment_setups as setup
  where setup.session_payment_id = v_payment.id
    and setup.booking_version = p_booking_version
    and setup.stripe_environment = p_stripe_environment
    and setup.stripe_customer_id = trim(p_stripe_customer_id)
    and setup.stripe_setup_intent_id = trim(p_stripe_setup_intent_id)
    and setup.stripe_payment_method_id = trim(p_stripe_payment_method_id)
    and setup.consent_version = trim(p_consent_version)
    and setup.status = 'succeeded'
    and setup.superseded_at is null;

  if found and exists (
    select 1
    from public.session_payment_schedules as schedule
    where schedule.session_payment_id = v_payment.id
      and schedule.session_payment_setup_id = v_setup_id
      and schedule.status in ('scheduled', 'claimed', 'processing', 'retry_scheduled')
  ) and v_booking.status = 'confirmed' then
    return jsonb_build_object(
      'bookingId', v_booking.id,
      'bookingVersion', p_booking_version,
      'scheduleId', (
        select schedule.id
        from public.session_payment_schedules as schedule
        where schedule.session_payment_id = v_payment.id
          and schedule.session_payment_setup_id = v_setup_id
        limit 1
      ),
      'setupId', v_setup_id,
      'status', 'scheduled'
    );
  end if;

  if v_booking.version <> p_booking_version then
    raise exception 'SESSION_PAYMENT_BOOKING_VERSION_MISMATCH'
      using errcode = '23514';
  end if;

  v_setup := public.register_session_payment_setup_v10(
    v_payment.id,
    p_booking_version,
    p_stripe_environment,
    trim(p_stripe_customer_id),
    trim(p_stripe_setup_intent_id),
    trim(p_stripe_payment_method_id),
    'succeeded',
    trim(p_consent_version),
    v_booking.legal_acceptance_recorded_at,
    null
  );
  v_setup_id := (v_setup ->> 'setupId')::uuid;
  v_schedule_key := 'tes:v10:session-charge:' || v_payment.id::text
    || ':booking-version:' || p_booking_version::text;
  v_fingerprint := encode(
    extensions.digest(
      concat_ws(
        ':',
        p_stripe_environment,
        v_payment.id::text,
        v_setup_id::text,
        trim(p_stripe_payment_method_id),
        v_payment.payment_due_at::text,
        v_payment.gross_amount_cents::text,
        v_payment.currency::text
      ),
      'sha256'
    ),
    'hex'
  );

  v_schedule := public.schedule_session_payment_v10(
    v_payment.id,
    v_setup_id,
    v_payment.payment_due_at,
    v_schedule_key,
    v_fingerprint
  );

  update public.bookings
  set status = case
        when status in ('draft', 'pending_payment') then 'confirmed'
        else status
      end,
      payment_status = 'pending',
      updated_at = now()
  where id = v_booking.id
    and status not in (
      'cancelled_by_patient', 'cancelled_by_therapist',
      'cancelled_by_payment', 'refunded'
    );

  if not found then
    raise exception 'SESSION_PAYMENT_SETUP_BOOKING_CLOSED'
      using errcode = '23514';
  end if;

  update public.session_payment_attempts
  set status = 'setup_succeeded',
      stripe_setup_intent_id = trim(p_stripe_setup_intent_id),
      updated_at = now()
  where session_payment_id = v_payment.id
    and stripe_checkout_session_id = trim(p_stripe_checkout_session_id);

  update public.session_promotion_reservations
  set status = 'consumed',
      consumed_at = coalesce(consumed_at, p_stripe_event_created_at),
      updated_at = now()
  where session_payment_id = v_payment.id
    and booking_version = p_booking_version
    and status = 'reserved';

  return jsonb_build_object(
    'bookingId', v_booking.id,
    'bookingVersion', p_booking_version,
    'scheduleId', v_schedule ->> 'scheduleId',
    'setupId', v_setup_id,
    'status', 'scheduled'
  );
end;
$$;


ALTER FUNCTION "public"."complete_session_payment_setup_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_stripe_checkout_session_id" "text", "p_stripe_customer_id" "text", "p_stripe_setup_intent_id" "text", "p_stripe_payment_method_id" "text", "p_consent_version" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_session_payment_setup_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_stripe_checkout_session_id" "text", "p_stripe_customer_id" "text", "p_stripe_setup_intent_id" "text", "p_stripe_payment_method_id" "text", "p_consent_version" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) IS 'Binds the successful off-session SetupIntent and PaymentMethod to one booking version and schedules its T-24 charge.';



CREATE OR REPLACE FUNCTION "public"."complete_session_transfer_job_v10"("p_job_id" "uuid", "p_worker_id" "uuid", "p_stripe_transfer_id" "text", "p_destination_payment_id" "text" DEFAULT NULL::"text", "p_connected_balance_transaction_id" "text" DEFAULT NULL::"text", "p_connected_balance_available_on" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_transferred_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.session_transfer_jobs%rowtype;
  v_transfer public.stripe_transfers%rowtype;
begin
  if nullif(trim(p_stripe_transfer_id), '') is null or p_transferred_at is null then
    raise exception 'SESSION_TRANSFER_PROVIDER_ID_INVALID' using errcode = '22023';
  end if;
  select * into v_job from public.session_transfer_jobs where id = p_job_id for update;
  if not found or v_job.stripe_transfer_id is null or v_job.prepared_at is null then
    raise exception 'SESSION_TRANSFER_JOB_NOT_PREPARED' using errcode = '23514';
  end if;
  select * into v_transfer from public.stripe_transfers
  where id = v_job.stripe_transfer_id for update;
  if v_transfer.stripe_transfer_id = p_stripe_transfer_id
    and v_transfer.status = 'transferred' then
    return jsonb_build_object('completed', true, 'duplicate', true);
  end if;
  if v_job.status <> 'creating'
    or v_job.lease_owner is distinct from p_worker_id
    or v_job.lease_expires_at <= now()
    or (v_transfer.stripe_transfer_id is not null
      and v_transfer.stripe_transfer_id <> p_stripe_transfer_id) then
    raise exception 'SESSION_TRANSFER_JOB_LEASE_OR_PROVIDER_MISMATCH'
      using errcode = '23514';
  end if;

  update public.stripe_transfers
  set stripe_transfer_id = p_stripe_transfer_id,
      stripe_destination_payment_id = nullif(trim(p_destination_payment_id), ''),
      stripe_connected_balance_transaction_id = nullif(trim(p_connected_balance_transaction_id), ''),
      connected_balance_available_on = p_connected_balance_available_on,
      transferred_at = p_transferred_at, status = 'transferred',
      failure_code = null, failure_message = null,
      updated_at = now()
  where id = v_transfer.id;

  update public.session_transfer_jobs
  set status = case when p_connected_balance_available_on is null
                      or p_connected_balance_available_on > now()
                    then 'pending_source' else 'transferred' end,
      succeeded_at = p_transferred_at, lease_owner = null,
      lease_expires_at = null, next_retry_at = null,
      last_error_code = null, updated_at = now()
  where id = v_job.id;

  update public.session_payments
  set transfer_status = 'transferred', transfer_blocked_reason = null,
      updated_at = now() where id = v_job.session_payment_id;

  insert into public.financial_ledger_entries (
    entry_type, direction, currency, amount_cents, therapist_profile_id,
    booking_id, session_payment_id, stripe_transfer_id,
    financial_policy_version_id, transfer_origin,
    source_table, source_id, occurred_at
  ) select
    'transfer', 'debit', 'BRL', v_transfer.amount_cents,
    v_transfer.therapist_profile_id, v_job.booking_id,
    v_job.session_payment_id, v_transfer.id,
    v_job.policy_version_id, 'session_direct',
    'stripe_transfers', v_transfer.id, p_transferred_at
  on conflict do nothing;
  return jsonb_build_object('completed', true, 'duplicate', false);
end;
$$;


ALTER FUNCTION "public"."complete_session_transfer_job_v10"("p_job_id" "uuid", "p_worker_id" "uuid", "p_stripe_transfer_id" "text", "p_destination_payment_id" "text", "p_connected_balance_transaction_id" "text", "p_connected_balance_available_on" timestamp with time zone, "p_transferred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_stripe_payout_creation_v1"("p_payout_id" "uuid", "p_worker_id" "uuid", "p_stripe_payout_id" "text", "p_provider_status" "text", "p_source_type" "text" DEFAULT NULL::"text", "p_arrival_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payout public.stripe_payouts%rowtype;
begin
  select * into v_payout from public.stripe_payouts
  where id = p_payout_id for update;
  if not found then raise exception 'STRIPE_PAYOUT_NOT_FOUND'; end if;
  if v_payout.stripe_payout_id is not null then return true; end if;
  if v_payout.lease_owner <> p_worker_id or v_payout.lease_expires_at < now() then
    raise exception 'STRIPE_PAYOUT_CLAIM_LOST';
  end if;
  if nullif(trim(p_stripe_payout_id), '') is null
    or p_provider_status not in ('pending', 'in_transit', 'paid', 'failed', 'canceled')
  then
    raise exception 'STRIPE_PAYOUT_PROVIDER_STATE_INVALID';
  end if;

  update public.stripe_payouts
  set stripe_payout_id = p_stripe_payout_id,
      provider_status = p_provider_status,
      source_type = p_source_type,
      status = case p_provider_status
        when 'in_transit' then 'in_transit'::public.stripe_payout_status
        else 'pending'::public.stripe_payout_status
      end,
      arrival_at = p_arrival_at,
      lease_owner = null, lease_expires_at = null, next_retry_at = null,
      updated_at = now()
  where id = v_payout.id;

  return true;
end;
$$;


ALTER FUNCTION "public"."complete_stripe_payout_creation_v1"("p_payout_id" "uuid", "p_worker_id" "uuid", "p_stripe_payout_id" "text", "p_provider_status" "text", "p_source_type" "text", "p_arrival_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_video_session_control_job_v1"("p_job_id" "uuid", "p_success" boolean, "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text", "p_retry_after_seconds" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job_exists boolean;
begin
  select exists (
    select 1
    from public.video_session_control_jobs
    where id = p_job_id
  )
  into v_job_exists;

  if not v_job_exists then
    raise exception 'video_session_control_job_not_found' using errcode = 'P0002';
  end if;

  if p_success then
    update public.video_session_control_jobs
    set status = 'done',
        completed_at = now(),
        locked_until_at = null,
        last_error_code = null,
        last_error_message = null,
        updated_at = now()
    where id = p_job_id;
    return;
  end if;

  update public.video_session_control_jobs
  set status = case
        when attempts >= max_attempts then 'dead_letter'::public.video_session_control_job_status
        else 'retry'::public.video_session_control_job_status
      end,
      next_run_at = now() + make_interval(
        secs => greatest(
          15,
          least(coalesce(p_retry_after_seconds, 30 * attempts), 900)
        )
      ),
      locked_until_at = null,
      last_error_code = left(nullif(p_error_code, ''), 120),
      last_error_message = left(nullif(p_error_message, ''), 500),
      updated_at = now()
  where id = p_job_id;
end;
$$;


ALTER FUNCTION "public"."complete_video_session_control_job_v1"("p_job_id" "uuid", "p_success" boolean, "p_error_code" "text", "p_error_message" "text", "p_retry_after_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_session_payment_and_enqueue_transfer_v10"("p_session_payment_id" "uuid", "p_stripe_environment" "text", "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_paid_at" timestamp with time zone, "p_stripe_event_id" "text" DEFAULT NULL::"text", "p_stripe_event_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_applied jsonb;
  v_fingerprint text;
  v_idempotency_key text;
  v_job public.session_transfer_jobs%rowtype;
  v_payment public.session_payments%rowtype;
begin
  if p_session_payment_id is null
    or p_stripe_environment not in ('test', 'live')
    or nullif(trim(p_stripe_payment_intent_id), '') is null
    or nullif(trim(p_stripe_charge_id), '') is null
    or p_paid_at is null
    or nullif(trim(p_stripe_event_id), '') is null
    or p_stripe_event_created_at is null
  then
    raise exception 'SESSION_PAYMENT_CONFIRMATION_V10_INVALID'
      using errcode = '22023';
  end if;

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.id = p_session_payment_id
  for update;

  if not found or v_payment.payment_flow_version <> 'v10' then
    raise exception 'SESSION_PAYMENT_V10_NOT_FOUND'
      using errcode = 'P0002';
  end if;

  if v_payment.financial_status = 'paid' and (
    v_payment.stripe_payment_intent_id is distinct from trim(p_stripe_payment_intent_id)
    or v_payment.stripe_charge_id is distinct from trim(p_stripe_charge_id)
  ) then
    raise exception 'SESSION_PAYMENT_CONFIRMATION_V10_IDEMPOTENCY_CONFLICT'
      using errcode = '23505';
  end if;

  if v_payment.financial_status not in ('pending', 'processing', 'paid') then
    raise exception 'SESSION_PAYMENT_V10_NOT_CONFIRMABLE'
      using errcode = '23514';
  end if;

  v_applied := public.apply_session_payment_state_v1(
    v_payment.id,
    'paid',
    trim(p_stripe_event_id),
    p_stripe_event_created_at,
    trim(p_stripe_payment_intent_id),
    trim(p_stripe_charge_id),
    v_payment.stripe_checkout_session_id
  );

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.id = p_session_payment_id;

  if v_payment.financial_status <> 'paid'
    or v_payment.stripe_payment_intent_id <> trim(p_stripe_payment_intent_id)
    or v_payment.stripe_charge_id <> trim(p_stripe_charge_id)
  then
    raise exception 'SESSION_PAYMENT_CONFIRMATION_V10_NOT_APPLIED'
      using errcode = '23514';
  end if;

  update public.session_payment_schedules
  set status = 'paid',
      stripe_payment_intent_id = trim(p_stripe_payment_intent_id),
      stripe_charge_id = trim(p_stripe_charge_id),
      succeeded_at = coalesce(succeeded_at, p_paid_at),
      lease_owner = null,
      lease_expires_at = null,
      next_retry_at = null,
      last_error_code = null,
      updated_at = now()
  where session_payment_id = v_payment.id
    and status <> 'paid';

  if v_payment.therapist_amount_cents = 0 then
    update public.session_payments
    set transfer_status = 'not_eligible', updated_at = now()
    where id = v_payment.id;

    return jsonb_build_object(
      'sessionPaymentId', v_payment.id,
      'financialStatus', 'paid',
      'transferJobId', null,
      'transferStatus', 'not_eligible'
    );
  end if;

  update public.session_payments
  set transfer_status = 'transfer_pending',
      transfer_blocked_reason = null,
      eligible_at = null,
      updated_at = now()
  where id = v_payment.id;

  v_idempotency_key := 'tes:v10:session-transfer:' || v_payment.id::text;
  v_fingerprint := encode(
    extensions.digest(
      concat_ws(
        ':',
        p_stripe_environment,
        v_payment.id::text,
        trim(p_stripe_charge_id),
        v_payment.connect_account_id_snapshot::text,
        v_payment.therapist_amount_cents::text,
        v_payment.currency::text
      ),
      'sha256'
    ),
    'hex'
  );

  insert into public.session_transfer_jobs (
    session_payment_id,
    booking_id,
    policy_version_id,
    connect_account_id,
    stripe_environment,
    stripe_source_charge_id,
    therapist_gross_amount_cents,
    debt_offset_amount_cents,
    transfer_amount_cents,
    idempotency_key,
    request_fingerprint
  )
  values (
    v_payment.id,
    v_payment.booking_id,
    v_payment.policy_version_id,
    v_payment.connect_account_id_snapshot,
    p_stripe_environment,
    trim(p_stripe_charge_id),
    v_payment.therapist_amount_cents,
    0,
    v_payment.therapist_amount_cents,
    v_idempotency_key,
    v_fingerprint
  )
  on conflict (session_payment_id) do update
  set updated_at = public.session_transfer_jobs.updated_at
  returning * into v_job;

  if v_job.stripe_source_charge_id <> trim(p_stripe_charge_id)
    or v_job.connect_account_id <> v_payment.connect_account_id_snapshot
    or v_job.transfer_amount_cents <> v_payment.therapist_amount_cents
    or v_job.request_fingerprint <> v_fingerprint
  then
    raise exception 'SESSION_TRANSFER_JOB_V10_IDEMPOTENCY_CONFLICT'
      using errcode = '23505';
  end if;

  return jsonb_build_object(
    'sessionPaymentId', v_payment.id,
    'financialStatus', 'paid',
    'transferJobId', v_job.id,
    'transferStatus', 'transfer_pending'
  );
end;
$$;


ALTER FUNCTION "public"."confirm_session_payment_and_enqueue_transfer_v10"("p_session_payment_id" "uuid", "p_stripe_environment" "text", "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_paid_at" timestamp with time zone, "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_session_payment_and_enqueue_transfer_v10"("p_session_payment_id" "uuid", "p_stripe_environment" "text", "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_paid_at" timestamp with time zone, "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) IS 'Atomically records a confirmed V10 card payment and creates its direct Transfer outbox job. Session attendance is not a financial gate.';



CREATE OR REPLACE FUNCTION "public"."confirm_session_service"("p_booking_id" "uuid", "p_source" "public"."session_confirmation_source", "p_confirmed_by_profile_id" "uuid" DEFAULT NULL::"uuid", "p_review_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_policy uuid;
  v_confirmation_id uuid;
  v_new_service_status public.session_service_status;
  v_confirmed_at timestamptz;
begin
  select * into v_payment
  from public.session_payments
  where booking_id = p_booking_id
  for update;

  if not found then raise exception 'session_payment_not_found'; end if;
  if v_payment.financial_status not in ('paid', 'partially_refunded') then
    raise exception 'payment_not_confirmed';
  end if;
  if v_payment.financial_status in ('refunded', 'disputed')
    or v_payment.admin_blocked_at is not null
    or v_payment.internal_contested_at is not null then
    raise exception 'session_blocked';
  end if;

  v_policy := v_payment.policy_version_id;
  v_confirmed_at := coalesce(
    nullif(p_metadata ->> 'confirmedAt', '')::timestamptz,
    now()
  );
  v_new_service_status := case p_source
    when 'bilateral' then 'confirmed_bilateral'::public.session_service_status
    when 'admin' then 'confirmed_bilateral'::public.session_service_status
    when 'patient_review' then 'confirmed_by_patient_review'::public.session_service_status
    when 'therapist_manual' then 'confirmed_by_therapist'::public.session_service_status
    when 'automatic' then 'auto_confirmed'::public.session_service_status
    else 'confirmed_bilateral'::public.session_service_status
  end;

  insert into public.session_service_confirmations (
    booking_id, session_payment_id, source, previous_service_status,
    confirmed_by_profile_id, review_id, policy_version_id, confirmed_at, metadata
  ) values (
    p_booking_id, v_payment.id, p_source, v_payment.service_status,
    p_confirmed_by_profile_id, p_review_id, v_policy, v_confirmed_at,
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (booking_id, source) do update
  set metadata = public.session_service_confirmations.metadata || excluded.metadata
  returning id into v_confirmation_id;

  update public.session_payments
  set service_status = v_new_service_status,
      service_confirmed_at = coalesce(service_confirmed_at, v_confirmed_at),
      service_confirmation_source = p_source,
      transfer_blocked_reason = null,
      updated_at = now()
  where id = v_payment.id;

  update public.bookings
  set status = 'completed',
      completed_at = coalesce(completed_at, v_confirmed_at),
      updated_at = now()
  where id = p_booking_id
    and status not in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded');

  perform public.refresh_session_transfer_eligibility(v_payment.id, now());
  return v_confirmation_id;
end;
$$;


ALTER FUNCTION "public"."confirm_session_service"("p_booking_id" "uuid", "p_source" "public"."session_confirmation_source", "p_confirmed_by_profile_id" "uuid", "p_review_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_zero_total_session_payment_v10"("p_session_payment_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
begin
  if p_session_payment_id is null
    or nullif(trim(p_stripe_checkout_session_id), '') is null
    or nullif(trim(p_stripe_event_id), '') is null
    or p_stripe_event_created_at is null
  then
    raise exception 'SESSION_PAYMENT_ZERO_TOTAL_V10_INVALID'
      using errcode = '22023';
  end if;

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.id = p_session_payment_id
  for update;

  if not found
    or v_payment.payment_flow_version <> 'v10'
    or v_payment.gross_amount_cents <> 0
    or v_payment.therapist_amount_cents <> 0
    or v_payment.stripe_checkout_session_id <> trim(p_stripe_checkout_session_id)
  then
    raise exception 'SESSION_PAYMENT_ZERO_TOTAL_V10_CONFLICT'
      using errcode = '23514';
  end if;

  perform public.apply_session_payment_state_v1(
    v_payment.id,
    'paid',
    trim(p_stripe_event_id),
    p_stripe_event_created_at,
    null,
    null,
    trim(p_stripe_checkout_session_id)
  );

  update public.session_payments
  set transfer_status = 'not_eligible', updated_at = now()
  where id = v_payment.id;

  update public.session_promotion_reservations
  set status = 'consumed',
      consumed_at = coalesce(consumed_at, p_stripe_event_created_at),
      updated_at = now()
  where session_payment_id = v_payment.id
    and status = 'reserved';

  return jsonb_build_object(
    'sessionPaymentId', v_payment.id,
    'financialStatus', 'paid',
    'transferJobId', null,
    'transferStatus', 'not_eligible'
  );
end;
$$;


ALTER FUNCTION "public"."confirm_zero_total_session_payment_v10"("p_session_payment_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_zero_total_session_payment_v10"("p_session_payment_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone) IS 'Confirms a signed no-payment-required V10 Checkout without creating a card setup or Transfer obligation.';



CREATE OR REPLACE FUNCTION "public"."consume_auth_action_token"("p_token_id" "uuid", "p_claim_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_updated integer;
begin
  update public.auth_action_tokens
  set consumed_at = now()
  where id = p_token_id
    and claim_id = p_claim_id
    and consumed_at is null
    and revoked_at is null
    and expires_at > now();

  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;


ALTER FUNCTION "public"."consume_auth_action_token"("p_token_id" "uuid", "p_claim_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bookings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "patient_profile_id" "uuid" NOT NULL,
    "therapist_profile_id" "uuid" NOT NULL,
    "service_id" "uuid" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "timezone" "text" DEFAULT 'America/Sao_Paulo'::"text" NOT NULL,
    "status" "public"."booking_status" DEFAULT 'draft'::"public"."booking_status" NOT NULL,
    "payment_status" "public"."payment_status" DEFAULT 'not_started'::"public"."payment_status" NOT NULL,
    "meeting_provider" "text",
    "meeting_url" "text",
    "cancellation_reason" "text",
    "cancelled_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_title_snapshot" "text" NOT NULL,
    "service_duration_minutes_snapshot" integer NOT NULL,
    "service_price_cents_snapshot" integer NOT NULL,
    "currency_snapshot" character(3) NOT NULL,
    "buffer_before_minutes_snapshot" integer NOT NULL,
    "buffer_after_minutes_snapshot" integer NOT NULL,
    "occupied_during" "tstzrange" NOT NULL,
    "snapshot_captured_at" timestamp with time zone NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "last_transition_at" timestamp with time zone,
    "legal_terms_version_id" "uuid",
    "legal_privacy_version_id" "uuid",
    "legal_cancellation_policy_version_id" "uuid",
    "legal_acceptance_recorded_at" timestamp with time zone,
    "session_reference" "text" NOT NULL,
    CONSTRAINT "bookings_session_reference_format_check" CHECK (("session_reference" ~ '^[0-9]{2}[JFMAIULGSOND][0-9]{6}$'::"text")),
    CONSTRAINT "bookings_snapshot_values_valid" CHECK ((("length"(TRIM(BOTH FROM "service_title_snapshot")) > 0) AND ("service_duration_minutes_snapshot" > 0) AND ("service_price_cents_snapshot" >= 0) AND (("currency_snapshot")::"text" = "upper"(("currency_snapshot")::"text")) AND ("buffer_before_minutes_snapshot" >= 0) AND ("buffer_after_minutes_snapshot" >= 0) AND (NOT "isempty"("occupied_during")) AND "lower_inc"("occupied_during") AND (NOT "upper_inc"("occupied_during")) AND ("version" > 0))),
    CONSTRAINT "bookings_valid_range" CHECK (("starts_at" < "ends_at"))
);


ALTER TABLE "public"."bookings" OWNER TO "postgres";


COMMENT ON COLUMN "public"."bookings"."meeting_url" IS 'Campo legado sem uso no Video SDK. Nao gravar token, session name, URL ou segredo.';



COMMENT ON COLUMN "public"."bookings"."service_price_cents_snapshot" IS 'Service list price captured at reservation time. The charged amount remains canonical in session_payments.';



COMMENT ON COLUMN "public"."bookings"."session_reference" IS 'Immutable human-readable operational reference. UUID remains the canonical authorization key.';



CREATE OR REPLACE FUNCTION "public"."consume_booking_hold_v1"("p_hold_id" "uuid", "p_idempotency_key" "text") RETURNS "public"."bookings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_booking_id uuid := gen_random_uuid();
  v_hold public.booking_holds%rowtype;
begin
  if length(trim(coalesce(p_idempotency_key, ''))) not between 8 and 200 then
    raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode = '22023';
  end if;

  select *
    into v_hold
  from public.booking_holds
  where id = p_hold_id
  for update;

  if not found then
    raise exception 'BOOKING_HOLD_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_hold.status = 'consumed' then
    if v_hold.consume_idempotency_key <> trim(p_idempotency_key)
      or v_hold.consumed_booking_id is null then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;

    select *
      into v_booking
    from public.bookings
    where id = v_hold.consumed_booking_id;

    return v_booking;
  end if;

  if v_hold.status <> 'active' or v_hold.expires_at <= now() then
    if v_hold.status = 'active' then
      update public.booking_holds
      set status = 'expired',
          updated_at = now()
      where id = v_hold.id;
    end if;

    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;

  if not exists (
    select 1
    from public.therapist_services as service
    join public.therapist_profiles as therapist
      on therapist.id = service.therapist_profile_id
    where service.id = v_hold.service_id
      and service.status = 'active'
      and therapist.status = 'approved'
      and therapist.is_accepting_bookings
  ) then
    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_hold.therapist_profile_id::text, 0)
  );

  update public.booking_holds
  set status = 'consumed',
      consume_idempotency_key = trim(p_idempotency_key),
      updated_at = now()
  where id = v_hold.id
  returning * into v_hold;

  perform pg_catalog.set_config(
    'tes.booking_request_id',
    trim(p_idempotency_key),
    true
  );
  perform pg_catalog.set_config(
    'tes.booking_source',
    'hold_conversion',
    true
  );

  begin
    insert into public.bookings (
      id,
      patient_profile_id,
      therapist_profile_id,
      service_id,
      starts_at,
      ends_at,
      timezone,
      status,
      payment_status,
      service_title_snapshot,
      service_duration_minutes_snapshot,
      service_price_cents_snapshot,
      currency_snapshot,
      buffer_before_minutes_snapshot,
      buffer_after_minutes_snapshot,
      snapshot_captured_at
    ) values (
      v_booking_id,
      v_hold.patient_profile_id,
      v_hold.therapist_profile_id,
      v_hold.service_id,
      v_hold.starts_at,
      v_hold.ends_at,
      v_hold.timezone,
      'draft',
      'not_started',
      v_hold.service_title_snapshot,
      v_hold.service_duration_minutes_snapshot,
      v_hold.service_price_cents_snapshot,
      v_hold.currency_snapshot,
      v_hold.buffer_before_minutes_snapshot,
      v_hold.buffer_after_minutes_snapshot,
      v_hold.snapshot_captured_at
    )
    returning * into v_booking;
  exception
    when exclusion_violation then
      raise exception 'BOOKING_CONFLICT' using errcode = 'P0001';
  end;

  update public.booking_holds
  set consumed_booking_id = v_booking.id,
      updated_at = now()
  where id = v_hold.id;

  perform pg_catalog.set_config('tes.booking_request_id', '', true);
  perform pg_catalog.set_config('tes.booking_source', '', true);

  return v_booking;
end;
$$;


ALTER FUNCTION "public"."consume_booking_hold_v1"("p_hold_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consume_booking_hold_v1"("p_hold_id" "uuid", "p_idempotency_key" "text") IS 'Atomically consumes an active hold into one draft booking. Payment creation remains a separate F0 workflow.';



CREATE OR REPLACE FUNCTION "public"."consume_email_outbox_test_fault_v1"("p_action_key" "text", "p_recipient_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  select id into v_id
  from public.email_outbox_test_faults
  where action_key = p_action_key and recipient_key = p_recipient_key
    and consumed_at is null and expires_at > now()
  order by created_at
  limit 1
  for update skip locked;
  if v_id is null then return false; end if;
  update public.email_outbox_test_faults set consumed_at = now() where id = v_id;
  return true;
end; $$;


ALTER FUNCTION "public"."consume_email_outbox_test_fault_v1"("p_action_key" "text", "p_recipient_key" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."support_tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "requester_profile_id" "uuid",
    "booking_id" "uuid",
    "category" "text" NOT NULL,
    "subject" "text" NOT NULL,
    "description" "text",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolution_summary" "text",
    "reviewed_at" timestamp with time zone,
    "request_id" "uuid",
    "correlation_id" "uuid",
    "diagnostic_context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source" "text" DEFAULT 'message_center'::"text" NOT NULL,
    "urgency" "text" DEFAULT 'normal'::"text" NOT NULL,
    "last_activity_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "assigned_admin_id" "uuid",
    "protocol" "text" NOT NULL,
    CONSTRAINT "support_tickets_protocol_format" CHECK (("protocol" ~ '^[0-9]{9}[A-Z]$'::"text")),
    CONSTRAINT "support_tickets_source_valid" CHECK (("source" = ANY (ARRAY['message_center'::"text", 'encounter_detail'::"text", 'waiting_room'::"text", 'public_help'::"text"]))),
    CONSTRAINT "support_tickets_urgency_valid" CHECK (("urgency" = ANY (ARRAY['normal'::"text", 'high'::"text", 'critical'::"text"])))
);


ALTER TABLE "public"."support_tickets" OWNER TO "postgres";


COMMENT ON COLUMN "public"."support_tickets"."assigned_admin_id" IS 'Operational ownership for Admin Support Inbox. Never exposed to requester DTOs.';



COMMENT ON COLUMN "public"."support_tickets"."protocol" IS 'Immutable public-facing support protocol: nine digits plus a category suffix. Not an authorization secret.';



CREATE OR REPLACE FUNCTION "public"."create_support_ticket_v1"("p_request_id" "uuid", "p_category" "text", "p_subject" "text", "p_description" "text", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'message_center'::"text") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_role public.user_role;
  v_category text;
  v_subject text;
  v_description text;
  v_ticket public.support_tickets%rowtype;
  v_existing public.support_tickets%rowtype;
begin
  v_actor_role := public.support_current_requester_role_v1();
  v_category := lower(public.support_plain_text_v1(p_category, 1, 80, 'category'));
  v_subject := public.support_plain_text_v1(p_subject, 3, 120, 'subject');
  v_description := public.support_plain_text_v1(p_description, 1, 4000, 'description');

  if p_request_id is null then
    raise exception 'support request id is required' using errcode = '22023';
  end if;

  if v_category not in (
    'agenda_sessoes',
    'zoom_acesso',
    'pagamentos',
    'financeiro_repasses',
    'plano_assinatura',
    'perfil_verificacao',
    'conta_acesso',
    'outro'
  ) then
    raise exception 'support category is invalid' using errcode = '22023';
  end if;

  if p_source not in ('message_center', 'encounter_detail', 'waiting_room', 'public_help') then
    raise exception 'support source is invalid' using errcode = '22023';
  end if;

  select *
    into v_existing
  from public.support_tickets
  where requester_profile_id = auth.uid()
    and request_id = p_request_id;

  if found then
    return v_existing;
  end if;

  if p_booking_id is not null and not exists (
    select 1
    from public.bookings
    left join public.patient_profiles
      on patient_profiles.id = bookings.patient_profile_id
    left join public.therapist_profiles
      on therapist_profiles.id = bookings.therapist_profile_id
    where bookings.id = p_booking_id
      and (
        patient_profiles.user_id = auth.uid()
        or therapist_profiles.user_id = auth.uid()
      )
  ) then
    raise exception 'support booking is not authorized' using errcode = '42501';
  end if;

  if (
    select count(*)
    from public.support_tickets
    where requester_profile_id = auth.uid()
      and created_at >= now() - interval '1 hour'
  ) >= 12 then
    raise exception 'support ticket rate limit reached' using errcode = 'P0001';
  end if;

  insert into public.support_tickets (
    requester_profile_id,
    booking_id,
    category,
    subject,
    description,
    status,
    priority,
    urgency,
    request_id,
    correlation_id,
    diagnostic_context,
    source,
    last_activity_at,
    resolved_at
  )
  values (
    auth.uid(),
    p_booking_id,
    v_category,
    v_subject,
    v_description,
    'open',
    'normal',
    'normal',
    p_request_id,
    gen_random_uuid(),
    jsonb_build_object('source', p_source, 'contract_version', 'support_ticket_v2'),
    p_source,
    now(),
    null
  )
  returning * into v_ticket;

  insert into public.support_ticket_messages (
    ticket_id,
    author_profile_id,
    author_role,
    body,
    visibility,
    request_id
  )
  values (
    v_ticket.id,
    auth.uid(),
    v_actor_role,
    v_description,
    'requester',
    p_request_id
  );

  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."create_support_ticket_v1"("p_request_id" "uuid", "p_category" "text", "p_subject" "text", "p_description" "text", "p_booking_id" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_support_ticket_with_attachments_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_category" "text", "p_subject" "text", "p_description" "text", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'message_center'::"text", "p_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_role public.user_role;
  v_category text;
  v_subject text;
  v_description text;
  v_ticket public.support_tickets%rowtype;
  v_existing public.support_tickets%rowtype;
  v_message_id uuid;
begin
  v_actor_role := public.support_current_requester_role_v1();
  v_category := lower(public.support_plain_text_v1(p_category, 1, 80, 'category'));
  v_subject := public.support_plain_text_v1(p_subject, 3, 120, 'subject');
  v_description := public.support_plain_text_v1(p_description, 1, 4000, 'description');

  if p_ticket_id is null or p_request_id is null then
    raise exception 'support request id is required' using errcode = '22023';
  end if;
  if v_category not in ('agenda_sessoes', 'zoom_acesso', 'pagamentos', 'financeiro_repasses', 'plano_assinatura', 'perfil_verificacao', 'conta_acesso', 'outro') then
    raise exception 'support category is invalid' using errcode = '22023';
  end if;
  if p_source not in ('message_center', 'encounter_detail', 'waiting_room', 'public_help') then
    raise exception 'support source is invalid' using errcode = '22023';
  end if;

  select * into v_existing
  from public.support_tickets
  where requester_profile_id = auth.uid() and request_id = p_request_id;
  if found then return v_existing; end if;

  if p_booking_id is not null and not exists (
    select 1
    from public.bookings
    left join public.patient_profiles on patient_profiles.id = bookings.patient_profile_id
    left join public.therapist_profiles on therapist_profiles.id = bookings.therapist_profile_id
    where bookings.id = p_booking_id
      and (patient_profiles.user_id = auth.uid() or therapist_profiles.user_id = auth.uid())
  ) then
    raise exception 'support booking is not authorized' using errcode = '42501';
  end if;

  if (select count(*) from public.support_tickets where requester_profile_id = auth.uid() and created_at >= now() - interval '1 hour') >= 12 then
    raise exception 'support ticket rate limit reached' using errcode = 'P0001';
  end if;

  insert into public.support_tickets (
    id, requester_profile_id, booking_id, category, subject, description, status,
    priority, urgency, request_id, correlation_id, diagnostic_context, source,
    last_activity_at, resolved_at
  )
  values (
    p_ticket_id, auth.uid(), p_booking_id, v_category, v_subject, v_description,
    'open', 'normal', 'normal', p_request_id, gen_random_uuid(),
    jsonb_build_object('source', p_source, 'contract_version', 'support_ticket_v2'),
    p_source, now(), null
  )
  returning * into v_ticket;

  insert into public.support_ticket_messages (
    ticket_id, author_profile_id, author_role, body, visibility, request_id
  )
  values (v_ticket.id, auth.uid(), v_actor_role, v_description, 'requester', p_request_id)
  returning id into v_message_id;

  perform public.support_validate_ticket_attachments_v1(v_ticket.id, v_message_id, coalesce(p_attachments, '[]'::jsonb));
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."create_support_ticket_with_attachments_v1"("p_ticket_id" "uuid", "p_request_id" "uuid", "p_category" "text", "p_subject" "text", "p_description" "text", "p_booking_id" "uuid", "p_source" "text", "p_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_therapist_block_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_timezone" "text", "p_starts_on" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_all_day" boolean, "p_recurrence_frequency" "text", "p_recurrence_ends_on" "date", "p_service_id" "uuid", "p_reason_code" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_end_at timestamptz;
  v_existing public.availability_exception_events%rowtype;
  v_frequency text := coalesce(p_recurrence_frequency, 'none');
  v_impacted_count integer := 0;
  v_occurrence_count integer := 0;
  v_occurrence_date date;
  v_series public.availability_exception_series%rowtype;
  v_settings public.therapist_schedule_settings%rowtype;
  v_start_at timestamptz;
  v_step interval;
  v_therapist public.therapist_profiles%rowtype;
  v_result jsonb;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = p_actor_user_id
    and profile.role = 'therapist';

  if not found or v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_therapist.id::text, 0)
  );

  select event.*
    into v_existing
  from public.availability_exception_events as event
  where event.therapist_profile_id = v_therapist.id
    and event.request_id = p_request_id;

  if found then
    return v_existing.result || jsonb_build_object('idempotentReplay', true);
  end if;

  if not public.is_valid_timezone_v1(p_timezone) then
    raise exception 'invalid_block_timezone' using errcode = '22023';
  end if;

  if p_starts_on is null
    or p_recurrence_ends_on is null
    or p_recurrence_ends_on < p_starts_on
    or p_recurrence_ends_on > p_starts_on + 366
    or v_frequency not in ('none', 'daily', 'weekly')
    or (v_frequency = 'none' and p_recurrence_ends_on <> p_starts_on)
    or (
      not coalesce(p_all_day, false)
      and (
        p_start_time is null
        or p_end_time is null
        or p_start_time >= p_end_time
      )
    )
    or p_reason_code not in (
      'personal',
      'vacation',
      'administrative',
      'training',
      'health',
      'other'
    )
    or length(trim(coalesce(p_reason, ''))) > 240 then
    raise exception 'invalid_block_payload' using errcode = '22023';
  end if;

  if p_service_id is not null
    and not exists (
      select 1
      from public.therapist_services as service
      where service.id = p_service_id
        and service.therapist_profile_id = v_therapist.id
    ) then
    raise exception 'block_service_forbidden' using errcode = '42501';
  end if;

  select settings.*
    into v_settings
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id
  for update;

  insert into public.availability_exception_series (
    therapist_profile_id,
    service_id,
    timezone,
    starts_on,
    start_time,
    end_time,
    all_day,
    recurrence_frequency,
    recurrence_ends_on,
    reason_code,
    reason,
    created_by_user_id
  )
  values (
    v_therapist.id,
    p_service_id,
    p_timezone,
    p_starts_on,
    case when p_all_day then null else p_start_time end,
    case when p_all_day then null else p_end_time end,
    coalesce(p_all_day, false),
    v_frequency,
    p_recurrence_ends_on,
    p_reason_code,
    nullif(trim(coalesce(p_reason, '')), ''),
    p_actor_user_id
  )
  returning * into v_series;

  v_step := case
    when v_frequency = 'daily' then interval '1 day'
    when v_frequency = 'weekly' then interval '7 days'
    else interval '1 day'
  end;

  for v_occurrence_date in
    select generated_at::date
    from pg_catalog.generate_series(
      p_starts_on::timestamp,
      p_recurrence_ends_on::timestamp,
      v_step
    ) as generated_at
    limit 90
  loop
    v_occurrence_count := v_occurrence_count + 1;

    if p_all_day then
      v_start_at := v_occurrence_date::timestamp at time zone p_timezone;
      v_end_at := (v_occurrence_date + 1)::timestamp at time zone p_timezone;
    else
      v_start_at := (
        v_occurrence_date::timestamp + p_start_time
      ) at time zone p_timezone;
      v_end_at := (
        v_occurrence_date::timestamp + p_end_time
      ) at time zone p_timezone;
    end if;

    with inserted_exception as (
      insert into public.availability_exceptions (
        therapist_profile_id,
        service_id,
        starts_at,
        ends_at,
        is_available,
        reason,
        series_id,
        occurrence_date,
        timezone,
        all_day,
        reason_code,
        status,
        created_by_user_id
      )
      values (
        v_therapist.id,
        p_service_id,
        v_start_at,
        v_end_at,
        false,
        nullif(trim(coalesce(p_reason, '')), ''),
        v_series.id,
        v_occurrence_date,
        p_timezone,
        coalesce(p_all_day, false),
        p_reason_code,
        'active',
        p_actor_user_id
      )
      returning id, starts_at, ends_at
    ),
    inserted_impacts as (
      insert into public.availability_exception_booking_impacts (
        exception_id,
        booking_id,
        therapist_profile_id
      )
      select
        exception.id,
        booking.id,
        v_therapist.id
      from inserted_exception as exception
      join public.bookings as booking
        on booking.therapist_profile_id = v_therapist.id
       and booking.status in ('draft', 'pending_payment', 'confirmed')
       and booking.starts_at < exception.ends_at
       and booking.ends_at > exception.starts_at
       and (
         p_service_id is null
         or booking.service_id = p_service_id
       )
      on conflict (exception_id, booking_id) do nothing
      returning id
    )
    select count(*) into v_impacted_count
    from inserted_impacts;

    v_impacted_count := (
      select count(*)
      from public.availability_exception_booking_impacts as impact
      join public.availability_exceptions as exception
        on exception.id = impact.exception_id
      where exception.series_id = v_series.id
    );
  end loop;

  if v_frequency = 'daily'
    and (p_recurrence_ends_on - p_starts_on + 1) > 90 then
    raise exception 'block_recurrence_too_long' using errcode = '22023';
  end if;

  update public.therapist_schedule_settings
  set version = version + 1
  where therapist_profile_id = v_therapist.id
  returning * into v_settings;

  v_result := jsonb_build_object(
    'seriesId', v_series.id,
    'scheduleVersion', v_settings.version,
    'occurrenceCount', v_occurrence_count,
    'impactedBookingCount', v_impacted_count,
    'idempotentReplay', false
  );

  insert into public.availability_exception_events (
    therapist_profile_id,
    actor_user_id,
    series_id,
    event_type,
    request_id,
    result
  )
  values (
    v_therapist.id,
    p_actor_user_id,
    v_series.id,
    'block_created',
    p_request_id,
    v_result
  );

  if v_impacted_count > 0 then
    insert into public.notifications (
      profile_id,
      kind,
      title,
      body,
      href
    )
    values (
      p_actor_user_id,
      'schedule_block_impact',
      'Bloqueio com sessões impactadas',
      format(
        '%s sessão(ões) existente(s) precisam da sua revisão.',
        v_impacted_count
      ),
      '/terapeuta/agenda?aba=bloqueios'
    );
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_therapist_block_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_timezone" "text", "p_starts_on" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_all_day" boolean, "p_recurrence_frequency" "text", "p_recurrence_ends_on" "date", "p_service_id" "uuid", "p_reason_code" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_therapist_block_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_timezone" "text", "p_starts_on" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_all_day" boolean, "p_recurrence_frequency" "text", "p_recurrence_ends_on" "date", "p_service_id" "uuid", "p_reason_code" "text", "p_reason" "text") IS 'A4 service-role command that materializes timezone-safe block occurrences and records booking impacts without changing bookings.';



CREATE OR REPLACE FUNCTION "public"."create_therapist_block_v2"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_timezone" "text", "p_starts_on" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_all_day" boolean, "p_recurrence_frequency" "text", "p_recurrence_ends_on" "date", "p_service_id" "uuid", "p_reason_code" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_series_id uuid;
  v_paid_impacts jsonb := '[]'::jsonb;
begin
  v_result := public.create_therapist_block_v1(
    p_actor_user_id,
    p_request_id,
    p_timezone,
    p_starts_on,
    p_start_time,
    p_end_time,
    p_all_day,
    p_recurrence_frequency,
    p_recurrence_ends_on,
    p_service_id,
    p_reason_code,
    p_reason
  );

  v_series_id := nullif(v_result ->> 'seriesId', '')::uuid;

  if v_series_id is not null then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'bookingId', booking.id,
          'endsAt', booking.ends_at,
          'patientName', patient.display_name,
          'serviceTitle', coalesce(
            booking.service_title_snapshot,
            booking_service.title,
            'Sessão'
          ),
          'startsAt', booking.starts_at,
          'timezone', exception.timezone
        )
        order by booking.starts_at, booking.id
      ),
      '[]'::jsonb
    )
    into v_paid_impacts
    from public.availability_exceptions as exception
    join public.bookings as booking
      on booking.therapist_profile_id = exception.therapist_profile_id
     and booking.starts_at < exception.ends_at
     and booking.ends_at > exception.starts_at
     and booking.status = 'confirmed'
     and (
       p_service_id is null
       or booking.service_id = p_service_id
     )
    join public.patient_profiles as patient
      on patient.id = booking.patient_profile_id
    left join public.therapist_services as booking_service
      on booking_service.id = booking.service_id
    where exception.series_id = v_series_id
      and exists (
        select 1
        from public.session_payments as payment
        where payment.booking_id = booking.id
          and payment.financial_status = 'paid'
      );
  end if;

  return v_result || jsonb_build_object(
    'paidImpactedBookings', v_paid_impacts
  );
end;
$$;


ALTER FUNCTION "public"."create_therapist_block_v2"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_timezone" "text", "p_starts_on" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_all_day" boolean, "p_recurrence_frequency" "text", "p_recurrence_ends_on" "date", "p_service_id" "uuid", "p_reason_code" "text", "p_reason" "text") OWNER TO "postgres";


