CREATE OR REPLACE FUNCTION "public"."create_therapist_service_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_therapy public.therapies%rowtype;
  v_service public.therapist_services%rowtype;
  v_payload_hash text := encode(extensions.digest(p_payload::text, 'sha256'), 'hex');
  v_response jsonb;
  v_title text := btrim(coalesce(p_payload ->> 'title', ''));
  v_description text := nullif(btrim(coalesce(p_payload ->> 'description', '')), '');
  v_delivery_format text := coalesce(p_payload ->> 'deliveryFormat', 'online');
  v_currency text := upper(coalesce(p_payload ->> 'currency', 'BRL'));
  v_duration integer := nullif(p_payload ->> 'durationMinutes', '')::integer;
  v_price integer := nullif(p_payload ->> 'priceCents', '')::integer;
  v_therapy_id uuid := nullif(p_payload ->> 'therapyId', '')::uuid;
  v_position integer;
begin
  v_therapist := public.get_therapist_for_service_actor_v1(p_actor_user_id);
  v_response := public.get_therapist_service_request_replay_v1(
    v_therapist.id,
    p_request_id,
    'create',
    v_payload_hash
  );

  if v_response is not null then
    return v_response;
  end if;

  v_therapy := public.validate_platform_therapy_for_service_v1(v_therapy_id);

  if v_title = '' or length(v_title) > 120 then
    raise exception 'THERAPIST_SERVICE_INVALID_TITLE' using errcode = 'P0001';
  end if;

  if v_description is not null and length(v_description) > 800 then
    raise exception 'THERAPIST_SERVICE_INVALID_DESCRIPTION' using errcode = 'P0001';
  end if;

  if v_duration is null or v_duration not between 15 and 240 then
    raise exception 'THERAPIST_SERVICE_INVALID_DURATION' using errcode = 'P0001';
  end if;

  if v_price is null or v_price not between 1000 and 2000000 then
    raise exception 'THERAPIST_SERVICE_INVALID_PRICE' using errcode = 'P0001';
  end if;

  if v_currency <> 'BRL' then
    raise exception 'THERAPIST_SERVICE_INVALID_CURRENCY' using errcode = 'P0001';
  end if;

  if v_delivery_format not in ('online', 'in_person', 'hybrid') then
    raise exception 'THERAPIST_SERVICE_INVALID_FORMAT' using errcode = 'P0001';
  end if;

  perform public.ensure_therapist_service_limit_v1(
    v_therapist.id,
    v_therapist.plan
  );
  perform public.ensure_no_duplicate_therapist_service_v1(
    v_therapist.id,
    v_therapy.id
  );

  select coalesce(max(position), 0) + 10
    into v_position
  from public.therapist_services
  where therapist_profile_id = v_therapist.id;

  insert into public.therapist_services (
    therapist_profile_id,
    therapy_id,
    title,
    description,
    duration_minutes,
    price_cents,
    currency,
    status,
    online_only,
    delivery_format,
    is_bookable,
    position
  )
  values (
    v_therapist.id,
    v_therapy.id,
    v_title,
    v_description,
    v_duration,
    v_price,
    v_currency,
    'draft',
    v_delivery_format = 'online',
    v_delivery_format,
    false,
    v_position
  )
  returning * into v_service;

  insert into public.therapist_service_booking_settings (
    service_id,
    buffer_before_minutes,
    buffer_after_minutes,
    min_notice_minutes,
    max_days_ahead,
    interval_minutes
  )
  values (v_service.id, 0, 0, 120, 90, 30)
  on conflict (service_id) do nothing;

  insert into public.therapist_service_events (
    therapist_profile_id,
    service_id,
    actor_user_id,
    event_type,
    request_id,
    next_status,
    resulting_version,
    metadata
  )
  values (
    v_therapist.id,
    v_service.id,
    p_actor_user_id,
    'service_created',
    p_request_id,
    v_service.status,
    v_service.version,
    jsonb_build_object('therapyId', v_service.therapy_id)
  );

  v_response := jsonb_build_object(
    'contractVersion', 1,
    'idempotentReplay', false,
    'service', public.service_row_to_private_json_v1(v_service.id)
  );

  return public.store_therapist_service_request_v1(
    v_therapist.id,
    p_request_id,
    'create',
    v_payload_hash,
    v_service.id,
    v_response
  );
end;
$$;


ALTER FUNCTION "public"."create_therapist_service_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_therapist_service_with_matching_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_service_id uuid;
  v_theme_ids uuid[];
  v_interest_ids uuid[];
begin
  v_result := public.create_therapist_service_v1(
    p_actor_user_id,
    p_request_id,
    p_payload
  );
  v_service_id := (v_result#>>'{service,serviceId}')::uuid;

  select coalesce(array_agg(value::uuid order by ordinality), '{}'::uuid[])
    into v_theme_ids
  from jsonb_array_elements_text(coalesce(p_payload->'themeIds', '[]'::jsonb))
    with ordinality as items(value, ordinality);

  select coalesce(array_agg(value::uuid order by ordinality), '{}'::uuid[])
    into v_interest_ids
  from jsonb_array_elements_text(coalesce(p_payload->'interestIds', '[]'::jsonb))
    with ordinality as items(value, ordinality);

  perform public.replace_therapist_service_matching_v1(
    p_actor_user_id,
    v_service_id,
    v_theme_ids,
    v_interest_ids,
    p_request_id
  );

  return jsonb_set(
    v_result,
    '{service}',
    public.service_row_to_private_json_v1(v_service_id),
    true
  );
end;
$$;


ALTER FUNCTION "public"."create_therapist_service_with_matching_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_weekly_payout_batch"("p_reference_period_start" "date", "p_reference_period_end" "date", "p_cutoff_at" timestamp with time zone DEFAULT "now"(), "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_batch_id uuid;
begin
  if p_reference_period_start is null
    or p_reference_period_end is null
    or p_reference_period_start > p_reference_period_end
    or p_cutoff_at is null
  then
    raise exception 'PAYOUT_BATCH_PERIOD_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'tes-payout-batch:' || p_reference_period_start::text || ':' || p_reference_period_end::text,
      0
    )
  );

  select id into v_batch_id
  from public.payout_batches
  where reference_period_start = p_reference_period_start
    and reference_period_end = p_reference_period_end
    and status <> 'canceled'
  order by created_at asc
  limit 1
  for update;

  if v_batch_id is null then
    insert into public.payout_batches (
      reference_period_start,
      reference_period_end,
      cutoff_at,
      status,
      created_by
    )
    values (
      p_reference_period_start,
      p_reference_period_end,
      p_cutoff_at,
      'open',
      p_created_by
    )
    returning id into v_batch_id;
  end if;

  insert into public.payout_batch_therapists (
    payout_batch_id,
    therapist_profile_id,
    connect_account_id,
    item_count,
    total_amount_cents
  )
  select
    v_batch_id,
    payment.therapist_profile_id,
    account.id,
    count(*)::integer,
    sum(payment.therapist_amount_cents)::integer
  from public.private_weekly_payout_session_payments_v1 as payment
  join public.therapist_connect_accounts as account
    on account.therapist_profile_id = payment.therapist_profile_id
   and account.is_current
   and account.operational_status = 'ready'
   and account.stripe_transfers_status = 'active'
   and account.payouts_enabled
   and account.payout_status = 'enabled'
   and account.payout_schedule_interval = 'daily'
  where payment.transfer_status = 'eligible'
    and payment.eligible_at <= p_cutoff_at
    and payment.therapist_amount_cents > 0
    and payment.stripe_charge_id is not null
    and payment.stripe_balance_transaction_id is not null
    and not exists (
      select 1
      from public.payout_batch_items as existing
      where existing.session_payment_id = payment.id
        and existing.status in ('reserved', 'transfer_pending', 'transferred')
    )
  group by payment.therapist_profile_id, account.id
  on conflict (payout_batch_id, therapist_profile_id, connect_account_id) do nothing;

  insert into public.payout_batch_items (
    payout_batch_id,
    payout_batch_therapist_id,
    session_payment_id,
    booking_id,
    therapist_profile_id,
    amount_cents
  )
  select
    v_batch_id,
    therapist_group.id,
    payment.id,
    payment.booking_id,
    payment.therapist_profile_id,
    payment.therapist_amount_cents
  from public.private_weekly_payout_session_payments_v1 as payment
  join public.payout_batch_therapists as therapist_group
    on therapist_group.payout_batch_id = v_batch_id
   and therapist_group.therapist_profile_id = payment.therapist_profile_id
  join public.therapist_connect_accounts as account
    on account.id = therapist_group.connect_account_id
   and account.is_current
   and account.operational_status = 'ready'
   and account.stripe_transfers_status = 'active'
   and account.payouts_enabled
   and account.payout_status = 'enabled'
   and account.payout_schedule_interval = 'daily'
  where payment.transfer_status = 'eligible'
    and payment.eligible_at <= p_cutoff_at
    and payment.therapist_amount_cents > 0
    and payment.stripe_charge_id is not null
    and payment.stripe_balance_transaction_id is not null
    and not exists (
      select 1
      from public.payout_batch_items as existing
      where existing.session_payment_id = payment.id
        and existing.status in ('reserved', 'transfer_pending', 'transferred')
    );

  update public.session_payments as payment
  set transfer_status = 'batched',
      updated_at = now()
  where payment.payment_flow_version = 'v9'
    and exists (
      select 1
      from public.payout_batch_items as item
      where item.payout_batch_id = v_batch_id
        and item.session_payment_id = payment.id
        and item.status = 'reserved'
    )
    and payment.transfer_status = 'eligible';

  update public.payout_batch_therapists as therapist_group
  set item_count = stats.item_count,
      total_amount_cents = stats.total_amount_cents,
      updated_at = now()
  from (
    select
      item.payout_batch_therapist_id,
      count(*)::integer as item_count,
      sum(item.amount_cents)::integer as total_amount_cents
    from public.payout_batch_items as item
    where item.payout_batch_id = v_batch_id
      and item.status <> 'removed'
    group by item.payout_batch_therapist_id
  ) as stats
  where therapist_group.id = stats.payout_batch_therapist_id;

  delete from public.payout_batch_therapists as therapist_group
  where therapist_group.payout_batch_id = v_batch_id
    and not exists (
      select 1
      from public.payout_batch_items as item
      where item.payout_batch_therapist_id = therapist_group.id
        and item.status <> 'removed'
    );

  update public.payout_batches as batch
  set item_count = stats.item_count,
      therapist_count = stats.therapist_count,
      gross_amount_cents = stats.gross_amount_cents,
      therapist_amount_cents = stats.therapist_amount_cents,
      platform_gross_commission_cents = stats.platform_amount_cents,
      status = case
        when stats.item_count = 0 then 'completed'::public.payout_batch_status
        else 'open'::public.payout_batch_status
      end,
      processed_at = case when stats.item_count = 0 then now() else null end,
      updated_at = now()
  from (
    select
      count(item.id)::integer as item_count,
      count(distinct item.therapist_profile_id)::integer as therapist_count,
      coalesce(sum(payment.gross_amount_cents), 0)::integer as gross_amount_cents,
      coalesce(sum(item.amount_cents), 0)::integer as therapist_amount_cents,
      coalesce(sum(payment.platform_gross_commission_cents), 0)::integer as platform_amount_cents
    from public.payout_batch_items as item
    join public.session_payments as payment
      on payment.id = item.session_payment_id
    where item.payout_batch_id = v_batch_id
      and item.status <> 'removed'
  ) as stats
  where batch.id = v_batch_id;

  return v_batch_id;
end;
$$;


ALTER FUNCTION "public"."create_weekly_payout_batch"("p_reference_period_start" "date", "p_reference_period_end" "date", "p_cutoff_at" timestamp with time zone, "p_created_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_weekly_payout_batch"("p_reference_period_start" "date", "p_reference_period_end" "date", "p_cutoff_at" timestamp with time zone, "p_created_by" "uuid") IS 'Legacy V9 weekly payout batch constructor. V10 direct Transfer payments are excluded by view and trigger.';



CREATE OR REPLACE FUNCTION "public"."create_weekly_payout_batch_v2"("p_reference_period_start" "date", "p_reference_period_end" "date", "p_cutoff_at" timestamp with time zone DEFAULT "now"(), "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment_id uuid;
begin
  if p_reference_period_start is null
    or p_reference_period_end is null
    or p_reference_period_start > p_reference_period_end
    or p_cutoff_at is null
  then
    raise exception 'PAYOUT_BATCH_PERIOD_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'tes-payout-batch:' || p_reference_period_start::text || ':' || p_reference_period_end::text,
      0
    )
  );

  for v_payment_id in
    select payment.id
    from public.private_weekly_payout_session_payments_v1 as payment
    where payment.financial_status in ('paid', 'partially_refunded')
      and payment.transfer_status in (
        'waiting_confirmation',
        'waiting_safety_period',
        'waiting_settlement',
        'eligible'
      )
      and not exists (
        select 1
        from public.payout_batch_items as item
        where item.session_payment_id = payment.id
          and item.status in ('reserved', 'transfer_pending', 'transferred')
      )
    order by payment.id
    for update
  loop
    perform public.refresh_session_transfer_eligibility(v_payment_id, p_cutoff_at);
  end loop;

  if not exists (
    select 1
    from public.private_weekly_payout_session_payments_v1 as payment
    join public.therapist_connect_accounts as account
      on account.therapist_profile_id = payment.therapist_profile_id
     and account.is_current
     and account.operational_status = 'ready'
     and account.stripe_transfers_status = 'active'
     and account.payouts_enabled
     and account.payout_status = 'enabled'
     and account.payout_schedule_interval = 'daily'
    where payment.transfer_status = 'eligible'
      and payment.eligible_at <= p_cutoff_at
      and payment.stripe_balance_status = 'available'
      and payment.stripe_balance_available_on <= p_cutoff_at
      and payment.stripe_balance_checked_at >= p_cutoff_at - interval '2 hours'
      and payment.therapist_amount_cents > 0
      and payment.stripe_charge_id is not null
      and payment.stripe_balance_transaction_id is not null
      and not exists (
        select 1
        from public.payout_batch_items as item
        where item.session_payment_id = payment.id
          and item.status in ('reserved', 'transfer_pending', 'transferred')
      )
  ) then
    return null;
  end if;

  return public.create_weekly_payout_batch(
    p_reference_period_start,
    p_reference_period_end,
    p_cutoff_at,
    p_created_by
  );
end;
$$;


ALTER FUNCTION "public"."create_weekly_payout_batch_v2"("p_reference_period_start" "date", "p_reference_period_end" "date", "p_cutoff_at" timestamp with time zone, "p_created_by" "uuid") OWNER TO "postgres";


