CREATE OR REPLACE FUNCTION "public"."default_session_payment_schedule_booking_version_v10"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking_status public.booking_status;
  v_booking_version bigint;
begin
  if new.expected_booking_version is not null then
    return new;
  end if;

  select booking.status, booking.version
  into v_booking_status, v_booking_version
  from public.bookings as booking
  where booking.id = new.booking_id;

  if not found then
    raise exception 'SESSION_PAYMENT_SCHEDULE_V10_BOOKING_NOT_FOUND'
      using errcode = 'P0002';
  end if;

  new.expected_booking_version := case
    when v_booking_status = 'confirmed' then v_booking_version
    else v_booking_version + 1
  end;
  return new;
end;
$$;


ALTER FUNCTION "public"."default_session_payment_schedule_booking_version_v10"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."defer_stripe_payout_v1"("p_payout_id" "uuid", "p_worker_id" "uuid", "p_disposition" "text", "p_error_code" "text", "p_error_message" "text", "p_retry_after" interval DEFAULT '00:15:00'::interval) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payout public.stripe_payouts%rowtype;
  v_terminal boolean;
  v_status public.stripe_payout_status;
begin
  if p_disposition not in ('pending_balance', 'transient', 'reconciliation_required', 'blocked') then
    raise exception 'STRIPE_PAYOUT_DISPOSITION_INVALID';
  end if;
  select * into v_payout from public.stripe_payouts
  where id = p_payout_id for update;
  if not found then raise exception 'STRIPE_PAYOUT_NOT_FOUND'; end if;
  if v_payout.status = 'paid' then return 'paid'; end if;
  if v_payout.lease_owner <> p_worker_id then raise exception 'STRIPE_PAYOUT_CLAIM_LOST'; end if;

  -- Balance availability is eventual and is not a provider failure. It must
  -- never consume the finite retry budget or become terminal by itself.
  v_terminal := p_disposition = 'blocked'
    or (p_disposition <> 'pending_balance' and v_payout.attempt_count >= 4);
  v_status := case
    when p_disposition = 'pending_balance' then 'pending_balance'::public.stripe_payout_status
    when p_disposition = 'reconciliation_required' then 'reconciliation_required'::public.stripe_payout_status
    else 'failed'::public.stripe_payout_status
  end;

  update public.stripe_payouts
  set status = v_status,
      failure_code = left(coalesce(p_error_code, 'provider_error'), 120),
      failure_message = left(regexp_replace(coalesce(p_error_message, 'Falha no repasse bancario.'), '[\r\n]+', ' ', 'g'), 500),
      next_retry_at = case when v_terminal then null else now() + greatest(p_retry_after, interval '1 minute') end,
      lease_owner = null, lease_expires_at = null,
      failed_at = case when v_terminal then now() else failed_at end,
      updated_at = now()
  where id = v_payout.id;

  if v_terminal or p_disposition = 'reconciliation_required' then
    perform public.record_payout_operational_incident_v1(
      'payout:' || v_payout.id::text || ':' || v_status::text,
      case when p_disposition = 'blocked' then 'payout_blocked'
        when p_disposition = 'reconciliation_required' then 'payout_reconciliation_required'
        else 'payout_failed' end,
      case when v_terminal then 'critical' else 'warning' end,
      p_error_code, p_error_message, null, v_payout.payout_batch_id,
      null, null, v_payout.id, v_payout.therapist_profile_id
    );
  end if;

  return case when v_terminal then 'terminal' else v_status::text end;
end;
$$;


ALTER FUNCTION "public"."defer_stripe_payout_v1"("p_payout_id" "uuid", "p_worker_id" "uuid", "p_disposition" "text", "p_error_code" "text", "p_error_message" "text", "p_retry_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_payout_allocation_origin_v10"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_origin text;
begin
  select transfer_origin into v_origin from public.stripe_transfers
  where id = new.stripe_transfer_id;
  if v_origin is null then
    raise exception 'PAYOUT_ALLOCATION_TRANSFER_NOT_FOUND' using errcode = '23514';
  end if;
  new.allocation_origin := v_origin;
  if v_origin = 'session_direct' then
    new.payout_batch_id := null;
    new.payout_batch_therapist_id := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."derive_payout_allocation_origin_v10"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discard_therapist_profile_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_payload_hash text := encode(extensions.digest(p_expected_version::text, 'sha256'), 'hex');
  v_replay jsonb;
  v_response jsonb;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);
  v_replay := public.therapist_profile_request_replay_m1(v_profile.id, p_request_id, 'discard_draft', v_payload_hash);
  if v_replay is not null then
    return v_replay;
  end if;

  if p_expected_version <> v_profile.profile_version then
    raise exception 'VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  delete from public.therapist_profile_content_versions
  where therapist_profile_id = v_profile.id
    and status = 'draft';

  insert into public.therapist_profile_events (
    therapist_profile_id,
    actor_user_id,
    event_type,
    request_id,
    previous_public_status,
    next_public_status,
    previous_version,
    next_version
  )
  values (
    v_profile.id,
    p_actor_user_id,
    'profile_draft_discarded',
    p_request_id,
    v_profile.public_status,
    v_profile.public_status,
    v_profile.profile_version,
    v_profile.profile_version
  );

  v_response := jsonb_build_object(
    'contractVersion', 1,
    'idempotentReplay', false,
    'editor', public.get_private_therapist_profile_editor_v1(p_actor_user_id)
  );

  return public.therapist_profile_store_request_m1(
    v_profile.id,
    p_request_id,
    'discard_draft',
    v_payload_hash,
    v_response
  );
end;
$$;


ALTER FUNCTION "public"."discard_therapist_profile_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."discard_therapist_profile_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) IS 'SERVICE_ROLE_ONLY therapist profile draft discard command. Browser calls must go through therapist-profile-command.';



CREATE OR REPLACE FUNCTION "public"."dismiss_therapist_aura_recommendation_v1"("p_recommendation_id" "uuid", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist_id uuid;
  v_recommendation public.aura_recommendations%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if p_recommendation_id is null or p_request_id is null then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  select therapist.id
    into v_therapist_id
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist'
    and therapist.plan = 'premium_plus'::public.therapist_plan
    and therapist.status not in ('suspended', 'rejected');

  if v_therapist_id is null then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select *
    into v_recommendation
  from public.aura_recommendations
  where id = p_recommendation_id
    and therapist_profile_id = v_therapist_id
  for update;

  if not found then
    raise exception 'RECOMMENDATION_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_recommendation.status <> 'dismissed' then
    update public.aura_recommendations
    set
      status = 'dismissed',
      is_active = false,
      dismissed_at = now(),
      context = context || jsonb_build_object(
        'dismissRequestId',
        p_request_id
      ),
      updated_at = now()
    where id = p_recommendation_id;
  end if;

  return jsonb_build_object(
    'status', 'dismissed',
    'recommendationId', p_recommendation_id
  );
end;
$$;


ALTER FUNCTION "public"."dismiss_therapist_aura_recommendation_v1"("p_recommendation_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dismiss_therapist_aura_recommendation_v1"("p_recommendation_id" "uuid", "p_request_id" "uuid") IS 'Idempotent therapist-owned dismiss command for deterministic Aura recommendations.';



CREATE OR REPLACE FUNCTION "public"."dismiss_therapist_aura_signal_v1"("p_recommendation_key" "text", "p_rule_key" "text", "p_rule_version" integer, "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist_id uuid;
begin
  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if p_recommendation_key is null
    or length(trim(p_recommendation_key)) < 8
    or length(p_recommendation_key) > 160
    or p_rule_key is null
    or length(trim(p_rule_key)) < 8
    or length(p_rule_key) > 120
    or p_rule_version is null
    or p_rule_version < 1
    or p_period_start is null
    or p_period_end is null
    or p_period_start >= p_period_end
    or p_request_id is null
  then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  select therapist.id
    into v_therapist_id
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist'
    and therapist.plan = 'premium_plus'::public.therapist_plan
    and therapist.status not in ('suspended', 'rejected');

  if v_therapist_id is null then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  insert into public.aura_recommendation_dismissals (
    therapist_profile_id,
    recommendation_key,
    rule_key,
    rule_version,
    period_start,
    period_end,
    request_id
  )
  values (
    v_therapist_id,
    p_recommendation_key,
    p_rule_key,
    p_rule_version,
    p_period_start,
    p_period_end,
    p_request_id
  )
  on conflict (therapist_profile_id, recommendation_key) do update
  set
    request_id = public.aura_recommendation_dismissals.request_id,
    dismissed_at = public.aura_recommendation_dismissals.dismissed_at;

  return jsonb_build_object(
    'status', 'dismissed',
    'recommendationKey', p_recommendation_key
  );
end;
$$;


ALTER FUNCTION "public"."dismiss_therapist_aura_signal_v1"("p_recommendation_key" "text", "p_rule_key" "text", "p_rule_version" integer, "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dismiss_therapist_aura_signal_v1"("p_recommendation_key" "text", "p_rule_key" "text", "p_rule_version" integer, "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_request_id" "uuid") IS 'Idempotent dismiss command for live deterministic Aura rule output.';



CREATE OR REPLACE FUNCTION "public"."dismiss_therapist_aura_signal_v2"("p_recommendation_key" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist_id uuid;
  v_timezone text;
  v_local_end date;
  v_period_days integer;
  v_expected_start timestamptz;
  v_expected_end timestamptz;
  v_canonical_start text;
  v_canonical_end text;
  v_rule_key text;
  v_candidate text;
  v_rule_version integer := 1;
  v_recommendation_id uuid;
  v_payload jsonb;
  v_eligible boolean := false;
  v_existing public.aura_recommendation_dismissals%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if p_recommendation_key is null
    or length(trim(p_recommendation_key)) < 8
    or length(p_recommendation_key) > 220
    or p_period_start is null
    or p_period_end is null
    or p_period_start >= p_period_end
    or p_request_id is null
  then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  select therapist.id
    into v_therapist_id
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist'
    and therapist.plan = 'premium_plus'::public.therapist_plan
    and therapist.status not in ('suspended', 'rejected');

  if v_therapist_id is null then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist_id;

  v_timezone := coalesce(v_timezone, 'America/Sao_Paulo');
  v_local_end := (now() at time zone v_timezone)::date;

  if p_period_start = (v_local_end - 30)::timestamp at time zone v_timezone
    and p_period_end = v_local_end::timestamp at time zone v_timezone
  then
    v_period_days := 30;
  elsif p_period_start = (v_local_end - 90)::timestamp at time zone v_timezone
    and p_period_end = v_local_end::timestamp at time zone v_timezone
  then
    v_period_days := 90;
  else
    raise exception 'PERIOD_NOT_CURRENT' using errcode = '22023';
  end if;

  v_expected_start := p_period_start;
  v_expected_end := p_period_end;
  v_canonical_start := to_char(
    v_expected_start at time zone 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );
  v_canonical_end := to_char(
    v_expected_end at time zone 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  );

  if p_recommendation_key like 'persisted:%' then
    begin
      v_recommendation_id := substring(
        p_recommendation_key from char_length('persisted:') + 1
      )::uuid;
    exception when others then
      raise exception 'RECOMMENDATION_NOT_FOUND' using errcode = 'P0002';
    end;

    select recommendation.source_rule_key, recommendation.rule_version
      into v_rule_key, v_rule_version
    from public.aura_recommendations as recommendation
    where recommendation.id = v_recommendation_id
      and recommendation.therapist_profile_id = v_therapist_id
      and recommendation.source_rule_key in (
        'aura.booking_readiness.no_future_slots.v1',
        'aura.reviews.pending_reply.v1',
        'aura.sessions.cancellation_increased.v1',
        'aura.sessions.no_show_increased.v1',
        'aura.continuity.return_rate_decreased.v1'
      )
      and recommendation.rule_version = 1
      and recommendation.status in ('active', 'dismissed')
      and recommendation.is_active is true
      and recommendation.plan_required = 'premium_plus'::public.therapist_plan
      and coalesce(recommendation.expires_at, now() + interval '1 second') > now()
      and coalesce(recommendation.context->>'source', '') not in ('demo_seed', 'seed')
      and coalesce(recommendation.evidence->>'source', '') not in ('demo_seed', 'seed')
      and recommendation.patient_profile_id is null
      and recommendation.booking_id is null
      and recommendation.generated_at >= v_expected_start
      and recommendation.generated_at < v_expected_end;

    if not found then
      raise exception 'RECOMMENDATION_NOT_FOUND' using errcode = 'P0002';
    end if;
  else
    foreach v_candidate in array array[
      'aura.booking_readiness.no_future_slots.v1',
      'aura.reviews.pending_reply.v1',
      'aura.sessions.cancellation_increased.v1',
      'aura.sessions.no_show_increased.v1',
      'aura.continuity.return_rate_decreased.v1'
    ]
    loop
      if p_recommendation_key = v_candidate || ':' || v_canonical_start || ':' || v_canonical_end then
        v_rule_key := v_candidate;
      end if;
    end loop;

    if v_rule_key is null then
      raise exception 'RECOMMENDATION_NOT_FOUND' using errcode = 'P0002';
    end if;

    v_payload := public.get_therapist_aura_signals_v2(v_period_days);
    v_eligible := case v_rule_key
      when 'aura.booking_readiness.no_future_slots.v1' then
        (v_payload #>> '{signals,bookingReadiness,status}') = 'ready'
        and (v_payload #>> '{signals,bookingReadiness,publicBookableServices}')::integer > 0
        and (v_payload #>> '{signals,bookingReadiness,servicesWithFutureAvailability}')::integer = 0
      when 'aura.reviews.pending_reply.v1' then
        (v_payload #>> '{signals,reviews,status}') = 'ready'
        and (v_payload #>> '{signals,reviews,pendingReplyCount}')::integer > 0
      when 'aura.sessions.cancellation_increased.v1' then
        (v_payload #>> '{signals,sessions,cancellationRate,status}') = 'ready'
        and (v_payload #>> '{signals,sessions,cancellationRate,direction}') = 'up'
        and nullif(v_payload #>> '{signals,sessions,cancellationRate,value}', '')::numeric
          is distinct from nullif(v_payload #>> '{signals,sessions,cancellationRate,previousValue}', '')::numeric
      when 'aura.sessions.no_show_increased.v1' then
        (v_payload #>> '{signals,sessions,noShowRate,status}') = 'ready'
        and (v_payload #>> '{signals,sessions,noShowRate,direction}') = 'up'
        and nullif(v_payload #>> '{signals,sessions,noShowRate,value}', '')::numeric
          is distinct from nullif(v_payload #>> '{signals,sessions,noShowRate,previousValue}', '')::numeric
      when 'aura.continuity.return_rate_decreased.v1' then
        (v_payload #>> '{signals,continuity,returnRate,status}') = 'ready'
        and (v_payload #>> '{signals,continuity,returnRate,direction}') = 'down'
        and nullif(v_payload #>> '{signals,continuity,returnRate,value}', '')::numeric
          is distinct from nullif(v_payload #>> '{signals,continuity,returnRate,previousValue}', '')::numeric
      else false
    end;

    if not coalesce(v_eligible, false) then
      raise exception 'RECOMMENDATION_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  select *
    into v_existing
  from public.aura_recommendation_dismissals as dismissal
  where dismissal.therapist_profile_id = v_therapist_id
    and dismissal.recommendation_key = p_recommendation_key;

  if found then
    if v_existing.period_start <> v_expected_start
      or v_existing.period_end <> v_expected_end
    then
      raise exception 'RECOMMENDATION_NOT_FOUND' using errcode = 'P0002';
    end if;

    return jsonb_build_object(
      'status', 'dismissed',
      'recommendationKey', p_recommendation_key,
      'ruleKey', v_existing.rule_key,
      'ruleVersion', v_existing.rule_version,
      'periodStart', v_existing.period_start,
      'periodEnd', v_existing.period_end
    );
  end if;

  insert into public.aura_recommendation_dismissals (
    therapist_profile_id,
    recommendation_key,
    rule_key,
    rule_version,
    period_start,
    period_end,
    request_id
  )
  values (
    v_therapist_id,
    p_recommendation_key,
    v_rule_key,
    v_rule_version,
    v_expected_start,
    v_expected_end,
    p_request_id
  )
  on conflict (therapist_profile_id, recommendation_key) do nothing;

  return jsonb_build_object(
    'status', 'dismissed',
    'recommendationKey', p_recommendation_key,
    'ruleKey', v_rule_key,
    'ruleVersion', v_rule_version,
    'periodStart', v_expected_start,
    'periodEnd', v_expected_end
  );
end;
$$;


ALTER FUNCTION "public"."dismiss_therapist_aura_signal_v2"("p_recommendation_key" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dismiss_therapist_aura_signal_v2"("p_recommendation_key" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_request_id" "uuid") IS 'Server-proven Aura dismiss command. The browser supplies only an opaque key and current period; the function proves tenant ownership, registered rule/version, temporal eligibility and current rule output.';



CREATE OR REPLACE FUNCTION "public"."dispatch_email_outbox_recovery_v1"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_url text; v_secret text;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'email_outbox_dispatch_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'email_outbox_dispatch_secret';
  if v_url is null or v_secret is null then
    raise exception 'EMAIL_OUTBOX_RECOVERY_CONFIGURATION_MISSING';
  end if;
  perform net.http_post(
    url := v_url,
    headers := jsonb_build_object('content-type', 'application/json', 'x-email-outbox-dispatch-secret', v_secret),
    body := jsonb_build_object('limit', 25)
  );
end; $$;


ALTER FUNCTION "public"."dispatch_email_outbox_recovery_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_expired_booking_reschedule_event_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status public.booking_status;
begin
  if old.status <> 'pending' or new.status <> 'expired' then
    return new;
  end if;

  select status into v_status
  from public.bookings
  where id = new.booking_id;

  insert into public.booking_events (
    booking_id, actor_profile_id, event_type, request_id, source,
    previous_status, next_status, payload
  ) values (
    new.booking_id, new.resolved_by_profile_id, 'booking_reschedule_resolved',
    'reschedule-expired:' || new.id::text,
    'agenda_a2_expiry', v_status, v_status,
    pg_catalog.jsonb_build_object(
      'rescheduleRequestId', new.id,
      'resolution', 'expired',
      'status', 'expired'
    )
  ) on conflict do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."emit_expired_booking_reschedule_event_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_booking_hold_lifecycle_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.patient_profile_id <> old.patient_profile_id
    or new.therapist_profile_id <> old.therapist_profile_id
    or new.service_id <> old.service_id
    or new.starts_at <> old.starts_at
    or new.ends_at <> old.ends_at
    or new.timezone <> old.timezone
    or new.idempotency_key <> old.idempotency_key
    or new.expires_at <> old.expires_at
    or new.service_title_snapshot <> old.service_title_snapshot
    or new.service_duration_minutes_snapshot <> old.service_duration_minutes_snapshot
    or new.service_price_cents_snapshot <> old.service_price_cents_snapshot
    or new.currency_snapshot <> old.currency_snapshot
    or new.buffer_before_minutes_snapshot <> old.buffer_before_minutes_snapshot
    or new.buffer_after_minutes_snapshot <> old.buffer_after_minutes_snapshot
    or new.occupied_during <> old.occupied_during
    or new.snapshot_captured_at <> old.snapshot_captured_at then
    raise exception 'BOOKING_HOLD_IMMUTABLE' using errcode = '23514';
  end if;

  if new.status <> old.status and not (
    old.status = 'active'
    and new.status in ('cancelled', 'consumed', 'expired')
  ) then
    raise exception 'INVALID_HOLD_STATE_TRANSITION' using errcode = 'P0001';
  end if;

  if new.status = 'cancelled' and old.status <> 'cancelled' then
    new.cancelled_at := coalesce(new.cancelled_at, now());
  end if;

  if new.status = 'consumed' and old.status <> 'consumed' then
    new.consumed_at := coalesce(new.consumed_at, now());
  end if;

  new.version := case
    when new.status <> old.status
      or new.consumed_booking_id is distinct from old.consumed_booking_id
      then old.version + 1
    else old.version
  end;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_booking_hold_lifecycle_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_booking_lifecycle_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operational_change boolean;
begin
  if new.patient_profile_id <> old.patient_profile_id
    or new.therapist_profile_id <> old.therapist_profile_id
    or new.service_id <> old.service_id then
    raise exception 'BOOKING_PARTICIPANTS_IMMUTABLE' using errcode = '23514';
  end if;

  if new.service_title_snapshot <> old.service_title_snapshot
    or new.service_duration_minutes_snapshot <> old.service_duration_minutes_snapshot
    or new.service_price_cents_snapshot <> old.service_price_cents_snapshot
    or new.currency_snapshot <> old.currency_snapshot
    or new.buffer_before_minutes_snapshot <> old.buffer_before_minutes_snapshot
    or new.buffer_after_minutes_snapshot <> old.buffer_after_minutes_snapshot
    or new.snapshot_captured_at <> old.snapshot_captured_at then
    raise exception 'BOOKING_SNAPSHOT_IMMUTABLE' using errcode = '23514';
  end if;

  if new.status <> old.status
    and not public.is_booking_status_transition_allowed_v1(
      old.status,
      new.status
    ) then
    raise exception 'INVALID_STATE_TRANSITION' using errcode = 'P0001';
  end if;

  v_operational_change :=
    new.status <> old.status
    or new.starts_at <> old.starts_at
    or new.ends_at <> old.ends_at
    or new.timezone <> old.timezone;

  if new.starts_at <> old.starts_at or new.ends_at <> old.ends_at then
    new.occupied_during := pg_catalog.tstzrange(
      new.starts_at
        - new.buffer_before_minutes_snapshot * interval '1 minute',
      new.ends_at
        + new.buffer_after_minutes_snapshot * interval '1 minute',
      '[)'
    );
  elsif new.occupied_during <> old.occupied_during then
    raise exception 'BOOKING_OCCUPIED_RANGE_IMMUTABLE'
      using errcode = '23514';
  end if;

  new.version := case
    when v_operational_change then old.version + 1
    else old.version
  end;

  if new.status <> old.status then
    new.last_transition_at := now();
  else
    new.last_transition_at := old.last_transition_at;
  end if;

  if new.status in ('cancelled_by_patient', 'cancelled_by_therapist')
    and old.status <> new.status then
    new.cancelled_at := coalesce(new.cancelled_at, now());
  end if;

  if new.status = 'completed' and old.status <> 'completed' then
    new.completed_at := coalesce(new.completed_at, now());
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_booking_lifecycle_v1"() OWNER TO "postgres";


