CREATE OR REPLACE FUNCTION "public"."enforce_reschedule_proposal_requester_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status <> 'pending' then
    return new;
  end if;

  if not exists (
    select 1
    from public.bookings as booking
    join public.therapist_profiles as therapist
      on therapist.id = booking.therapist_profile_id
    where booking.id = new.booking_id
      and therapist.user_id = new.requested_by_profile_id
  ) then
    raise exception 'BOOKING_PROPOSAL_REQUIRES_THERAPIST'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


