COMMENT ON FUNCTION "public"."enforce_therapist_verification_transition_v1"() IS 'Enforces submitted, in-review and decision sequencing for therapist verification records.';



CREATE OR REPLACE FUNCTION "public"."enqueue_booking_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_patient_user_id uuid;
  v_therapist_user_id uuid;
  v_requester_user_id uuid;
  v_patient_action_key text;
  v_therapist_action_key text;
  v_status text;
  v_is_future_v10_reservation boolean := false;
begin
  if new.event_type = 'booking_created' and new.next_status::text = 'confirmed' then
    perform public.schedule_booking_reminder_jobs_v1(new.booking_id);
    return new;
  end if;

  select patient.user_id, therapist.user_id
  into v_patient_user_id, v_therapist_user_id
  from public.bookings booking
  join public.patient_profiles patient on patient.id = booking.patient_profile_id
  join public.therapist_profiles therapist on therapist.id = booking.therapist_profile_id
  where booking.id = new.booking_id;

  if new.event_type like 'booking_reschedule_%' then
    select requested_by_profile_id into v_requester_user_id
    from public.booking_reschedule_requests
    where id = (new.payload ->> 'rescheduleRequestId')::uuid;
  end if;

  if new.event_type = 'booking_status_changed'
    and new.next_status::text = 'confirmed'
  then
    perform public.schedule_booking_reminder_jobs_v1(new.booking_id);

    select exists (
      select 1
      from public.session_payments payment
      join public.session_payment_schedules schedule
        on schedule.session_payment_id = payment.id
      where payment.booking_id = new.booking_id
        and payment.payment_flow_version = 'v10'
        and payment.financial_status in ('pending', 'processing')
        and schedule.status in (
          'scheduled', 'claimed', 'processing',
          'requires_customer_action', 'retry_scheduled'
        )
    ) into v_is_future_v10_reservation;

    if v_is_future_v10_reservation then
      v_patient_action_key := 'booking_reserved_patient';
      v_therapist_action_key := 'booking_reserved_therapist';
    else
      v_patient_action_key := 'booking_confirmed_patient';
      v_therapist_action_key := 'booking_confirmed_therapist';
    end if;
  elsif new.event_type = 'booking_status_changed'
    and new.next_status::text in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded')
  then
    perform public.cancel_booking_reminder_jobs_v1(new.booking_id, 'booking_status_changed');
    v_patient_action_key := 'booking_cancelled_patient';
    v_therapist_action_key := 'booking_cancelled_therapist';
  elsif new.event_type = 'booking_reschedule_requested' then
    if v_requester_user_id = v_patient_user_id then
      v_therapist_action_key := 'booking_reschedule_requested_therapist';
    else
      v_patient_action_key := 'booking_reschedule_requested_patient';
    end if;
  elsif new.event_type = 'booking_reschedule_resolved' then
    v_status := new.payload ->> 'status';
    if v_status = 'applied' then
      perform public.cancel_booking_reminder_jobs_v1(new.booking_id, 'booking_rescheduled');
      perform public.schedule_booking_reminder_jobs_v1(new.booking_id);
      v_patient_action_key := 'booking_rescheduled_patient';
      v_therapist_action_key := 'booking_rescheduled_therapist';
    elsif v_status = 'rejected' then
      if v_requester_user_id = v_patient_user_id then
        v_patient_action_key := 'booking_reschedule_rejected_patient';
      else
        v_therapist_action_key := 'booking_reschedule_rejected_therapist';
      end if;
    elsif v_status = 'cancelled' then
      if v_requester_user_id = v_patient_user_id then
        v_therapist_action_key := 'booking_reschedule_withdrawn_therapist';
      else
        v_patient_action_key := 'booking_reschedule_withdrawn_patient';
      end if;
    elsif v_status = 'expired' then
      v_patient_action_key := 'booking_reschedule_expired_patient';
      v_therapist_action_key := 'booking_reschedule_expired_therapist';
    else
      return new;
    end if;
  else
    return new;
  end if;

  if v_patient_action_key is not null and v_patient_user_id is not null then
    perform public.enqueue_transactional_email_v1(
      v_patient_action_key, new.id, 'booking', new.booking_id,
      v_patient_user_id, 'profile:' || v_patient_user_id::text, '{}'::jsonb
    );
  end if;

  if v_therapist_action_key is not null and v_therapist_user_id is not null then
    perform public.enqueue_transactional_email_v1(
      v_therapist_action_key, new.id, 'booking', new.booking_id,
      v_therapist_user_id, 'profile:' || v_therapist_user_id::text, '{}'::jsonb
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_booking_email_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_booking_email_v1"() IS 'Enfileira reserva, confirmação e demais comunicações do encontro a partir de eventos persistidos, sem dados clínicos ou financeiros no payload.';



CREATE OR REPLACE FUNCTION "public"."enqueue_due_video_session_control_jobs_v1"("p_environment" "text", "p_limit" integer DEFAULT 50, "p_therapist_absence_grace_seconds" integer DEFAULT 120) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer := 0;
  v_session record;
begin
  if p_environment not in ('development', 'production') then
    raise exception 'invalid_zoom_video_environment' using errcode = '22023';
  end if;

  -- Compatibility-only input. Therapist reconnect grace remains unrelated to
  -- the no-show rule and never authorizes a terminal transition.
  if p_therapist_absence_grace_seconds is not null then
    null;
  end if;

  -- A queued timeout from a previous booking version, or one invalidated by a
  -- just-recorded patient arrival, must not be retried later.
  update public.video_session_control_jobs job
  set status = 'done'::public.video_session_control_job_status,
      completed_at = coalesce(job.completed_at, now()),
      locked_until_at = null,
      last_error_code = null,
      last_error_message = null,
      metadata = job.metadata || jsonb_build_object(
        'supersededBy', 'patient_arrival_or_booking_change',
        'supersededAt', now()
      ),
      updated_at = now()
  from public.bookings booking
  where job.booking_id = booking.id
    and job.operation = 'end_patient_no_show'::public.video_session_control_operation
    and job.status in (
      'queued'::public.video_session_control_job_status,
      'retry'::public.video_session_control_job_status
    )
    and (
      job.metadata ->> 'bookingVersion' is distinct from booking.version::text
      or job.metadata ->> 'scheduledStartsAt' is distinct from booking.starts_at::text
      or exists (
        select 1
        from public.booking_events event
        where event.booking_id = booking.id
          and event.event_type = 'zoom_waiting_room_entered'
          and event.payload ->> 'bookingVersion' = booking.version::text
          and event.payload ->> 'scheduledStartsAt' = booking.starts_at::text
      )
      or exists (
        select 1
        from public.video_session_participations participation
        join public.video_sessions session on session.id = participation.video_session_id
        where session.booking_id = booking.id
          and participation.participant_role = 'patient'::public.video_session_participant_role
          and participation.event_type = 'session.user_joined'
      )
    );

  for v_session in
    select session.id, booking.version, booking.starts_at
    from public.video_sessions session
    join public.bookings booking on booking.id = session.booking_id
    where session.environment = p_environment
      and session.status = 'active'
      and session.termination_confirmed_at is null
      and booking.status = 'confirmed'::public.booking_status
      and booking.meeting_provider in ('zoom', 'zoom_video_sdk')
      and exists (
        select 1
        from public.session_payments payment
        where payment.booking_id = booking.id
          and payment.financial_status = 'paid'::public.session_financial_status
      )
      and session.scheduled_starts_at = booking.starts_at
      and session.scheduled_ends_at = booking.ends_at
      and booking.starts_at + interval '10 minutes' < now()
      and booking.ends_at > now()
      and not exists (
        select 1
        from public.booking_events event
        where event.booking_id = booking.id
          and event.event_type = 'zoom_waiting_room_entered'
          and event.payload ->> 'bookingVersion' = booking.version::text
          and event.payload ->> 'scheduledStartsAt' = booking.starts_at::text
      )
      and not exists (
        select 1
        from public.video_session_participations participation
        where participation.video_session_id = session.id
          and participation.participant_role = 'patient'::public.video_session_participant_role
          and participation.event_type = 'session.user_joined'
      )
    order by booking.starts_at
    limit greatest(1, least(coalesce(p_limit, 50), 100))
  loop
    perform public.enqueue_video_session_control_job_v1(
      v_session.id,
      'end_patient_no_show',
      'patient-no-show:' || v_session.id::text || ':v' || v_session.version::text ||
        ':' || floor(extract(epoch from v_session.starts_at) * 1000)::bigint::text,
      now(),
      jsonb_build_object(
        'bookingVersion', v_session.version,
        'scheduledStartsAt', v_session.starts_at::text,
        'source', 'maintenance_due_scan'
      )
    );
    v_count := v_count + 1;
  end loop;

  for v_session in
    select id
    from public.video_sessions
    where environment = p_environment
      and status = 'active'
      and scheduled_ends_at <= now()
      and termination_confirmed_at is null
    order by scheduled_ends_at
    limit greatest(1, least(coalesce(p_limit, 50), 100))
  loop
    perform public.enqueue_video_session_control_job_v1(
      v_session.id, 'end_scheduled', 'scheduled-end:' || v_session.id::text,
      now(), jsonb_build_object('source', 'maintenance_due_scan')
    );
    v_count := v_count + 1;
  end loop;

  for v_session in
    select id
    from public.video_sessions
    where environment = p_environment
      and status = 'active'
      and scheduled_ends_at > now()
      and hard_ends_at is not null
      and hard_ends_at <= now()
      and termination_confirmed_at is null
    order by hard_ends_at
    limit greatest(1, least(coalesce(p_limit, 50), 100))
  loop
    perform public.enqueue_video_session_control_job_v1(
      v_session.id, 'end_hard_timeout', 'hard-timeout:' || v_session.id::text,
      now(), jsonb_build_object('source', 'maintenance_due_scan')
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."enqueue_due_video_session_control_jobs_v1"("p_environment" "text", "p_limit" integer, "p_therapist_absence_grace_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_due_video_session_control_jobs_v1"("p_environment" "text", "p_limit" integer, "p_therapist_absence_grace_seconds" integer) IS 'Queues patient-no-show only after T+10 without a current-version waiting-room arrival or trusted patient join; therapist absence remains reentrant.';



CREATE OR REPLACE FUNCTION "public"."enqueue_session_payment_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action_key text;
  v_booking_status public.booking_status;
  v_domain_event_id uuid;
  v_patient_user_id uuid;
  v_therapist_user_id uuid;
begin
  if new.financial_status is not distinct from old.financial_status then
    return new;
  end if;

  v_action_key := case new.financial_status::text
    when 'paid' then 'session_payment_approved'
    when 'failed' then 'session_payment_declined'
    when 'processing' then 'session_payment_pending'
    else null
  end;

  if v_action_key is null then
    return new;
  end if;

  if new.stripe_event_id is not null then
    select event.id into v_domain_event_id
    from public.stripe_webhook_events event
    where event.stripe_event_id = new.stripe_event_id
      and event.processing_status in ('processing', 'processed')
    limit 1;
  end if;

  -- A scheduled charge may be confirmed by the worker before its webhook is
  -- delivered. The immutable schedule is the local event identity in that path.
  if v_domain_event_id is null and new.payment_flow_version = 'v10' then
    select schedule.id into v_domain_event_id
    from public.session_payment_schedules schedule
    where schedule.session_payment_id = new.id
    order by schedule.created_at desc, schedule.id desc
    limit 1;
  end if;

  if v_domain_event_id is null then
    return new;
  end if;

  select booking.status, patient.user_id, therapist.user_id
  into v_booking_status, v_patient_user_id, v_therapist_user_id
  from public.bookings booking
  join public.patient_profiles patient on patient.id = booking.patient_profile_id
  join public.therapist_profiles therapist on therapist.id = booking.therapist_profile_id
  where booking.id = new.booking_id;

  if v_patient_user_id is not null then
    perform public.enqueue_transactional_email_v1(
      v_action_key,
      v_domain_event_id,
      'session_payment',
      new.id,
      v_patient_user_id,
      'profile:' || v_patient_user_id::text,
      '{}'::jsonb
    );
  end if;

  -- In the scheduled V10 path the operational booking was already confirmed
  -- when the card was saved. Payment success therefore has no second booking
  -- status transition from which to notify both participants.
  if new.payment_flow_version = 'v10'
    and new.financial_status = 'paid'
    and v_booking_status = 'confirmed'
  then
    if v_patient_user_id is not null then
      perform public.enqueue_transactional_email_v1(
        'booking_confirmed_patient',
        v_domain_event_id,
        'booking',
        new.booking_id,
        v_patient_user_id,
        'profile:' || v_patient_user_id::text,
        '{}'::jsonb
      );
    end if;

    if v_therapist_user_id is not null then
      perform public.enqueue_transactional_email_v1(
        'booking_confirmed_therapist',
        v_domain_event_id,
        'booking',
        new.booking_id,
        v_therapist_user_id,
        'profile:' || v_therapist_user_id::text,
        '{}'::jsonb
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_session_payment_email_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_session_payment_email_v1"() IS 'Enfileira comunicações financeiras e confirmações V10 a partir do estado persistido, usando identidade local idempotente quando o worker antecede o webhook.';



CREATE OR REPLACE FUNCTION "public"."enqueue_session_refund_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_recipient_user_id uuid;
begin
  if new.status <> 'succeeded' or new.stripe_refund_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from public.stripe_webhook_events event
    where event.object_id = new.stripe_refund_id
      and event.event_type in ('refund.created', 'refund.updated')
      and event.processing_status in ('processing', 'processed')
  ) then
    return new;
  end if;

  select patient.user_id into v_recipient_user_id
  from public.session_payments payment
  join public.patient_profiles patient on patient.id = payment.patient_profile_id
  where payment.id = new.session_payment_id;

  if v_recipient_user_id is not null then
    perform public.enqueue_transactional_email_v1(
      'session_refund_approved',
      new.id,
      'session_refund',
      new.id,
      v_recipient_user_id,
      'profile:' || v_recipient_user_id::text,
      '{}'::jsonb
    );
  end if;

  return new;
end;
$$;


