CREATE OR REPLACE FUNCTION "public"."enqueue_therapist_profile_lifecycle_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action_key text;
begin
  if old.status is not distinct from new.status then
    return new;
  end if;

  v_action_key := case
    when new.status = 'suspended'::public.therapist_status
      then 'therapist_profile_suspended'
    when old.status = 'suspended'::public.therapist_status
      and new.status = 'approved'::public.therapist_status
      then 'therapist_profile_reactivated'
    else null
  end;

  if v_action_key is not null then
    perform public.enqueue_transactional_email_v1(
      v_action_key,
      gen_random_uuid(),
      'therapist_profile',
      new.id,
      new.user_id,
      'profile:' || new.user_id::text,
      '{}'::jsonb
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_therapist_profile_lifecycle_email_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_therapist_profile_lifecycle_email_v1"() IS 'Enfileira suspensão ou reativação somente após mudança persistida de status do perfil.';



CREATE OR REPLACE FUNCTION "public"."enqueue_therapist_subscription_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action_key text;
  v_recipient_user_id uuid;
begin
  if new.event_type <> 'stripe_subscription_sync'
    or new.stripe_event_id is null
    or new.therapist_subscription_id is null
    or new.therapist_profile_id is null
    or not exists (
      select 1
      from public.stripe_webhook_events event
      where event.stripe_event_id = new.stripe_event_id
        and event.event_type in (
          'customer.subscription.created',
          'customer.subscription.updated',
          'customer.subscription.deleted'
        )
        and event.processing_status in ('processing', 'processed')
    )
  then
    return new;
  end if;

  v_action_key := case
    when new.next_status in ('active', 'trialing')
      and coalesce(new.previous_status, '') not in ('active', 'trialing')
      then 'therapist_subscription_created'
    when new.next_status = 'canceled'
      and new.previous_status is distinct from 'canceled'
      then 'therapist_subscription_cancelled'
    when new.previous_plan is not null
      and new.previous_plan is distinct from new.next_plan
      and new.next_status in ('active', 'trialing')
      then 'therapist_subscription_plan_changed'
    else null
  end;

  if v_action_key is null then
    return new;
  end if;

  select therapist.user_id into v_recipient_user_id
  from public.therapist_profiles therapist
  where therapist.id = new.therapist_profile_id;

  if v_recipient_user_id is not null then
    perform public.enqueue_transactional_email_v1(
      v_action_key,
      new.id,
      'therapist_subscription',
      new.therapist_subscription_id,
      v_recipient_user_id,
      'profile:' || v_recipient_user_id::text,
      '{}'::jsonb
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_therapist_subscription_email_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_therapist_subscription_email_v1"() IS 'Enfileira assinatura criada, cancelada ou plano alterado somente por evento Stripe reservado e estado sincronizado. Cancelamento agendado nao envia.';



CREATE OR REPLACE FUNCTION "public"."enqueue_therapist_subscription_renewal_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_recipient_user_id uuid;
begin
  if new.status <> 'paid'
    or new.billing_reason <> 'subscription_cycle'
    or new.therapist_subscription_id is null
    or new.therapist_profile_id is null
    or not exists (
      select 1
      from public.stripe_webhook_events event
      where event.object_id = new.stripe_invoice_id
        and event.event_type = 'invoice.paid'
        and event.processing_status in ('processing', 'processed')
    )
  then
    return new;
  end if;

  select therapist.user_id into v_recipient_user_id
  from public.therapist_profiles therapist
  where therapist.id = new.therapist_profile_id;

  if v_recipient_user_id is not null then
    perform public.enqueue_transactional_email_v1(
      'therapist_subscription_renewed',
      new.id,
      'billing_invoice',
      new.id,
      v_recipient_user_id,
      'profile:' || v_recipient_user_id::text,
      '{}'::jsonb
    );
  end if;

  return new;
end;
$$;


