COMMENT ON FUNCTION "public"."enqueue_therapist_subscription_renewal_email_v1"() IS 'Enfileira renovacao somente por invoice.paid de subscription_cycle persistida. A cobranca inicial nao recebe e-mail de renovacao.';



CREATE OR REPLACE FUNCTION "public"."enqueue_therapist_verification_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action_key text;
  v_recipient_user_id uuid;
begin
  v_action_key := case
    when tg_op = 'INSERT' and new.status = 'submitted'::public.therapist_status
      then 'therapist_profile_submitted_for_review'
    when tg_op = 'UPDATE' and old.status is distinct from new.status
      and new.status = 'submitted'::public.therapist_status
      then 'therapist_profile_submitted_for_review'
    when tg_op = 'UPDATE' and old.status is distinct from new.status
      and new.status = 'changes_requested'::public.therapist_status
      then 'therapist_documents_requested'
    when tg_op = 'UPDATE' and old.status is distinct from new.status
      and new.status = 'approved'::public.therapist_status
      then 'therapist_profile_approved'
    when tg_op = 'UPDATE' and old.status is distinct from new.status
      and new.status = 'rejected'::public.therapist_status
      then 'therapist_profile_rejected'
    else null
  end;

  if v_action_key is null then
    return new;
  end if;

  select therapist.user_id into v_recipient_user_id
  from public.therapist_profiles therapist
  where therapist.id = new.therapist_profile_id;

  if v_recipient_user_id is not null then
    perform public.enqueue_transactional_email_v1(
      v_action_key,
      gen_random_uuid(),
      'therapist_verification',
      new.id,
      v_recipient_user_id,
      'profile:' || v_recipient_user_id::text,
      '{}'::jsonb
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_therapist_verification_email_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_therapist_verification_email_v1"() IS 'Enfileira e-mail somente após uma transição persistida da verificação. Motivos e documentos não entram no payload.';



CREATE OR REPLACE FUNCTION "public"."enqueue_therapy_catalog_email_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_action_key text;
begin
  if new.entity_type <> 'therapy_catalog_request' then return new; end if;
  v_action_key := case
    when new.event_type in ('therapy_request_submitted', 'therapy_request_resubmitted') then 'therapy_catalog_request_submitted'
    when new.event_type in ('therapy_request_under_review', 'therapy_request_needs_information', 'therapy_request_approved', 'therapy_request_merged', 'therapy_request_rejected') then 'therapy_catalog_request_updated'
    else null end;
  if v_action_key is null then return new; end if;
  insert into public.email_outbox(action_key, related_entity_type, related_entity_id, recipient_user_id, idempotency_key, payload)
  select v_action_key, 'therapy_catalog_request', new.entity_id, request.requester_profile_id, new.id::text,
    jsonb_build_object('catalog_event_id', new.id)
  from public.therapy_catalog_requests request where request.id = new.entity_id
  on conflict (action_key, idempotency_key) do nothing;
  return new;
end; $$;


ALTER FUNCTION "public"."enqueue_therapy_catalog_email_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_therapy_catalog_email_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action_key text;
  v_recipient_id uuid;
begin
  if new.entity_type <> 'therapy_catalog_request' then
    return new;
  end if;

  v_action_key := case
    when new.event_type in ('therapy_request_submitted', 'therapy_request_resubmitted')
      then 'therapy_catalog_request_submitted'
    when new.event_type in (
      'therapy_request_under_review',
      'therapy_request_needs_information',
      'therapy_request_approved',
      'therapy_request_merged',
      'therapy_request_rejected'
    ) then 'therapy_catalog_request_updated'
    else null
  end;
  if v_action_key is null then
    return new;
  end if;

  select requester_profile_id into v_recipient_id
  from public.therapy_catalog_requests
  where id = new.entity_id;

  if v_recipient_id is not null then
    perform public.enqueue_transactional_email_v1(
      v_action_key,
      new.id,
      'therapy_catalog_request',
      new.entity_id,
      v_recipient_id,
      'profile:' || v_recipient_id::text,
      jsonb_build_object('catalog_event_id', new.id)
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_therapy_catalog_email_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_transactional_email_v1"("p_action_key" "text", "p_domain_event_id" "uuid", "p_related_entity_type" "text", "p_related_entity_id" "uuid", "p_recipient_user_id" "uuid", "p_recipient_key" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_enabled boolean;
  v_automatic boolean;
  v_id uuid;
  v_overrides jsonb;
  v_sender_profile_id uuid;
  v_template_version text;
begin
  if p_action_key is null or p_domain_event_id is null
    or p_related_entity_id is null or p_recipient_user_id is null
    or p_recipient_key <> 'profile:' || p_recipient_user_id::text
    or pg_catalog.jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) <> 'object'
  then raise exception 'EMAIL_OUTBOX_INVALID_ENQUEUE'; end if;

  if p_related_entity_type not in (
    'auth_action_token', 'billing_invoice', 'booking',
    'payout_operational_incident', 'session_payment', 'session_refund',
    'stripe_payout', 'stripe_transfer', 'therapist_subscription',
    'therapy_catalog_request', 'therapist_profile', 'therapist_verification'
  ) then raise exception 'EMAIL_OUTBOX_INVALID_ENTITY'; end if;

  select definition.active and coalesce(setting.enabled, true),
    coalesce(setting.automatic_dispatch_enabled, true),
    definition.default_template_version,
    coalesce(setting.sender_profile_id, default_sender.id),
    pg_catalog.jsonb_build_object(
      'subject_override', setting.subject_override,
      'preheader_override', setting.preheader_override,
      'text_override', setting.text_override,
      'html_override', setting.html_override
    )
  into v_enabled, v_automatic, v_template_version, v_sender_profile_id, v_overrides
  from public.email_action_definitions definition
  left join public.email_action_settings setting on setting.action_key = definition.action_key
  left join lateral (
    select sender.id from public.email_sender_profiles sender
    where sender.active and sender.is_default order by sender.created_at limit 1
  ) default_sender on true
  where definition.action_key = p_action_key;

  if coalesce(v_enabled, false) is false or coalesce(v_automatic, false) is false then
    return null;
  end if;

  insert into public.email_outbox (
    action_key, domain_event_id, related_entity_type, related_entity_id,
    recipient_user_id, recipient_key, idempotency_key, payload,
    template_version, template_overrides, sender_profile_id
  ) values (
    p_action_key, p_domain_event_id, p_related_entity_type, p_related_entity_id,
    p_recipient_user_id, p_recipient_key, p_domain_event_id::text,
    coalesce(p_payload, '{}'::jsonb), coalesce(v_template_version, 'v1'),
    coalesce(v_overrides, '{}'::jsonb), v_sender_profile_id
  ) on conflict (action_key, domain_event_id, recipient_key) do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_id from public.email_outbox
    where action_key = p_action_key and domain_event_id = p_domain_event_id
      and recipient_key = p_recipient_key;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."enqueue_transactional_email_v1"("p_action_key" "text", "p_domain_event_id" "uuid", "p_related_entity_type" "text", "p_related_entity_id" "uuid", "p_recipient_user_id" "uuid", "p_recipient_key" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_transactional_email_v1"("p_action_key" "text", "p_domain_event_id" "uuid", "p_related_entity_type" "text", "p_related_entity_id" "uuid", "p_recipient_user_id" "uuid", "p_recipient_key" "text", "p_payload" "jsonb") IS 'Enfileira entrega automática com snapshot no mesmo commit do evento autoritativo. Não aceita destinatário ou action key do browser.';



CREATE OR REPLACE FUNCTION "public"."enqueue_video_session_control_job_v1"("p_video_session_id" "uuid", "p_operation" "public"."video_session_control_operation", "p_idempotency_key" "text", "p_next_run_at" timestamp with time zone DEFAULT "now"(), "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session public.video_sessions%rowtype;
  v_job_id uuid;
begin
  select *
    into v_session
  from public.video_sessions
  where id = p_video_session_id;

  if not found then
    raise exception 'video_session_not_found' using errcode = 'P0002';
  end if;

  insert into public.video_session_control_jobs (
    video_session_id,
    booking_id,
    environment,
    operation,
    idempotency_key,
    next_run_at,
    metadata
  )
  values (
    v_session.id,
    v_session.booking_id,
    v_session.environment,
    p_operation,
    left(p_idempotency_key, 160),
    coalesce(p_next_run_at, now()),
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (environment, idempotency_key) do update
  set next_run_at = least(public.video_session_control_jobs.next_run_at, excluded.next_run_at),
      metadata = public.video_session_control_jobs.metadata || excluded.metadata,
      updated_at = now()
  where public.video_session_control_jobs.status in ('queued', 'retry', 'processing')
  returning id into v_job_id;

  return v_job_id;
end;
$$;


ALTER FUNCTION "public"."enqueue_video_session_control_job_v1"("p_video_session_id" "uuid", "p_operation" "public"."video_session_control_operation", "p_idempotency_key" "text", "p_next_run_at" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_no_duplicate_therapist_service_v1"("p_therapist_profile_id" "uuid", "p_therapy_id" "uuid", "p_excluding_service_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (
    select 1
    from public.therapist_services as service
    where service.therapist_profile_id = p_therapist_profile_id
      and service.therapy_id = p_therapy_id
      and service.status <> 'archived'
      and (
        p_excluding_service_id is null
        or service.id <> p_excluding_service_id
      )
  ) then
    raise exception 'THERAPIST_SERVICE_DUPLICATE_THERAPY' using errcode = 'P0001';
  end if;
end;
$$;


