CREATE OR REPLACE FUNCTION "public"."ensure_therapy_matching_theme_limit_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_count integer;
begin
  if tg_op = 'DELETE' then
    return old;
  end if;

  if exists (
    select 1
    from public.matching_themes
    where id = new.theme_id
      and is_active = false
  ) then
    raise exception 'INACTIVE_ENTITY';
  end if;

  select count(*)::integer
    into v_count
  from public.therapy_matching_themes
  where therapy_id = new.therapy_id;

  if v_count > 3 then
    raise exception 'LIMIT_EXCEEDED';
  end if;

  return new;
end;
$$;


