CREATE OR REPLACE FUNCTION "public"."expire_due_initial_checkout_attempts_v1"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 100) RETURNS TABLE("checkout_session_id" "text", "session_payment_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.session_payment_attempts%rowtype;
begin
  for v_attempt in
    select attempt.*
    from public.session_payment_attempts as attempt
    join public.session_payments as payment
      on payment.id = attempt.session_payment_id
     and payment.stripe_checkout_session_id = attempt.stripe_checkout_session_id
    where attempt.attempt_kind = 'initial_hold'
      and attempt.reservation_expires_at <= p_now
      and attempt.slot_claimed_at is null
      and attempt.status in ('checkout_created', 'waiting_payment', 'processing')
    order by attempt.reservation_expires_at
    for update of attempt skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  loop
    update public.session_payment_attempts
    set status = 'expired', terminal_reason = 'reservation_expired',
        updated_at = p_now
    where id = v_attempt.id;

    update public.session_payments
    set financial_status = 'canceled', canceled_at = coalesce(canceled_at, p_now),
        updated_at = p_now
    where id = v_attempt.session_payment_id
      and financial_status in ('pending', 'processing');

    checkout_session_id := v_attempt.stripe_checkout_session_id;
    session_payment_id := v_attempt.session_payment_id;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."expire_due_initial_checkout_attempts_v1"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_due_initial_checkout_orphans_v1"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 100) RETURNS TABLE("booking_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate record;
  v_result jsonb;
begin
  for v_candidate in
    select hold.id as hold_id, booking.id as booking_id
    from public.booking_holds as hold
    join public.bookings as booking
      on booking.id = hold.consumed_booking_id
    left join public.session_payments as payment
      on payment.booking_id = booking.id
    where hold.status = 'consumed'
      and hold.expires_at <= p_now
      and booking.status in ('draft', 'pending_payment')
      and (
        payment.id is null
        or (
          payment.stripe_checkout_session_id is null
          and payment.financial_status in ('pending', 'failed', 'canceled')
        )
      )
    order by hold.expires_at, hold.id
    for update of hold, booking skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  loop
    v_result := public.cancel_unstarted_initial_checkout_v1(
      v_candidate.booking_id,
      v_candidate.hold_id,
      'reservation_expired_before_checkout'
    );
    if coalesce((v_result ->> 'released')::boolean, false) then
      booking_id := v_candidate.booking_id;
      return next;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."expire_due_initial_checkout_orphans_v1"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."expire_due_initial_checkout_orphans_v1"("p_now" timestamp with time zone, "p_limit" integer) IS 'Recovers expired consumed holds whose booking bootstrap stopped before a Stripe Checkout was persisted.';



CREATE OR REPLACE FUNCTION "public"."fail_payout_transfer_v1"("p_transfer_id" "uuid", "p_worker_id" "uuid", "p_disposition" "text", "p_error_code" "text", "p_error_message" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfer public.stripe_transfers%rowtype;
  v_item public.payout_batch_items%rowtype;
  v_next_retry timestamptz;
  v_terminal boolean;
  v_status text;
  v_disposition text;
begin
  if p_disposition not in ('transient', 'blocked', 'reconciliation_required') then
    raise exception 'PAYOUT_TRANSFER_DISPOSITION_INVALID';
  end if;

  v_disposition := case
    when p_disposition = 'blocked'
      and p_error_code in ('balance_insufficient', 'insufficient_funds')
      then 'transient'
    else p_disposition
  end;

  select * into v_transfer
  from public.stripe_transfers
  where id = p_transfer_id
  for update;
  if not found then raise exception 'PAYOUT_TRANSFER_NOT_FOUND'; end if;
  if v_transfer.status = 'transferred' then return 'transferred'; end if;
  if v_transfer.lease_owner <> p_worker_id then raise exception 'PAYOUT_TRANSFER_CLAIM_LOST'; end if;

  select * into v_item
  from public.payout_batch_items
  where id = v_transfer.payout_batch_item_id
  for update;

  v_terminal := v_disposition = 'blocked' or v_transfer.attempt_count >= 4;
  v_next_retry := case v_transfer.attempt_count
    when 1 then now() + interval '15 minutes'
    when 2 then now() + interval '30 minutes'
    when 3 then now() + interval '60 minutes'
    else null
  end;
  v_status := case
    when v_disposition = 'reconciliation_required' then 'reconciliation_required'
    else 'failed'
  end;

  update public.stripe_transfers
  set status = v_status,
      failure_code = left(coalesce(p_error_code, 'provider_error'), 120),
      failure_message = left(regexp_replace(coalesce(p_error_message, 'Falha no repasse.'), '[\r\n]+', ' ', 'g'), 500),
      next_retry_at = case when v_terminal then null else v_next_retry end,
      lease_owner = null,
      lease_expires_at = null,
      updated_at = now()
  where id = v_transfer.id;

  update public.payout_batch_items
  set status = case when v_disposition = 'blocked'
        then 'blocked'::public.payout_batch_item_status
        else 'failed'::public.payout_batch_item_status end,
      failure_code = left(coalesce(p_error_code, 'provider_error'), 120),
      failure_message = left(regexp_replace(coalesce(p_error_message, 'Falha no repasse.'), '[\r\n]+', ' ', 'g'), 500),
      updated_at = now()
  where id = v_item.id;

  update public.session_payments
  set transfer_status = case
        when v_disposition = 'blocked' then 'blocked'::public.session_transfer_status
        when v_terminal then 'failed'::public.session_transfer_status
        else 'transfer_pending'::public.session_transfer_status
      end,
      transfer_blocked_reason = left(coalesce(p_error_code, 'provider_error'), 120),
      updated_at = now()
  where id = v_transfer.session_payment_id;

  if v_terminal or v_disposition = 'reconciliation_required' then
    perform public.record_payout_operational_incident_v1(
      'transfer:' || v_transfer.id::text || ':' || v_status,
      case when v_disposition = 'blocked' then 'transfer_blocked'
        when v_disposition = 'reconciliation_required' then 'transfer_reconciliation_required'
        else 'transfer_failed' end,
      case when v_terminal then 'critical' else 'warning' end,
      p_error_code, p_error_message, null, v_item.payout_batch_id,
      v_item.id, v_transfer.id, null, v_transfer.therapist_profile_id
    );
  end if;

  return case when v_terminal then 'terminal' else v_status end;
end;
$$;


ALTER FUNCTION "public"."fail_payout_transfer_v1"("p_transfer_id" "uuid", "p_worker_id" "uuid", "p_disposition" "text", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fail_payout_transfer_v1"("p_transfer_id" "uuid", "p_worker_id" "uuid", "p_disposition" "text", "p_error_code" "text", "p_error_message" "text") IS 'Records an owned Transfer failure with bounded 15, 30 and 60 minute retry backoff; the fourth failure is terminal.';



CREATE OR REPLACE FUNCTION "public"."fail_session_payment_schedule_attempt_v10"("p_schedule_id" "uuid", "p_worker_id" "uuid", "p_error_code" "text", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_schedule public.session_payment_schedules%rowtype;
  v_failed boolean;
  v_retry_at timestamptz;
begin
  if p_schedule_id is null or p_worker_id is null or p_now is null
    or p_error_code not in ('stripe_transient', 'stripe_timeout', 'worker_error', 'stripe_state_unknown')
  then
    raise exception 'SESSION_PAYMENT_SCHEDULE_FAILURE_V10_INVALID' using errcode = '22023';
  end if;
  select * into v_schedule from public.session_payment_schedules
  where id = p_schedule_id for update;
  if not found or v_schedule.lease_owner is distinct from p_worker_id
    or v_schedule.lease_expires_at <= p_now
    or v_schedule.status not in ('claimed', 'processing')
  then
    raise exception 'SESSION_PAYMENT_SCHEDULE_LEASE_V10_INVALID' using errcode = '23514';
  end if;

  v_failed := v_schedule.attempt_count >= 4;
  v_retry_at := case when v_failed then null
    else p_now + make_interval(mins => least(15 * (2 ^ (v_schedule.attempt_count - 1))::integer, 60)) end;
  update public.session_payment_schedules
  set status = case when v_failed then 'failed' else 'retry_scheduled' end,
      next_retry_at = v_retry_at,
      last_error_code = p_error_code,
      last_failed_at = p_now,
      lease_owner = null, lease_expires_at = null, updated_at = p_now
  where id = p_schedule_id;

  if v_failed then
    insert into public.session_charge_incidents_v10 (schedule_id, code)
    values (p_schedule_id, p_error_code)
    on conflict (schedule_id) do update
      set code = excluded.code, status = 'open', resolved_at = null, updated_at = p_now;
  end if;
  return jsonb_build_object('status', case when v_failed then 'failed' else 'retry_scheduled' end,
    'nextRetryAt', v_retry_at, 'attemptCount', v_schedule.attempt_count);
end;
$$;


ALTER FUNCTION "public"."fail_session_payment_schedule_attempt_v10"("p_schedule_id" "uuid", "p_worker_id" "uuid", "p_error_code" "text", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_session_transfer_job_v10"("p_job_id" "uuid", "p_worker_id" "uuid", "p_error_code" "text", "p_ambiguous" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.session_transfer_jobs%rowtype;
  v_terminal boolean;
  v_payment public.session_payments%rowtype;
begin
  select * into v_job from public.session_transfer_jobs where id = p_job_id for update;
  if not found or v_job.status <> 'creating'
    or v_job.lease_owner is distinct from p_worker_id then
    raise exception 'SESSION_TRANSFER_JOB_LEASE_LOST' using errcode = '23514';
  end if;
  -- An unknown provider outcome is never converted into a definitive failure.
  -- After eight claims it remains visible for manual reconciliation, but is
  -- no longer automatically retried by the claim RPC.
  v_terminal := not coalesce(p_ambiguous, true);
  update public.session_transfer_jobs
  set status = case when v_terminal then 'failed' else 'reconciliation_required' end,
      last_error_code = left(coalesce(nullif(trim(p_error_code), ''), 'provider_unknown'), 80),
      last_failed_at = now(),
      next_retry_at = case when v_terminal or v_job.attempt_count >= 8 then null
        else now() + make_interval(mins => least(60, 5 * power(2, least(v_job.attempt_count - 1, 4))::integer)) end,
      lease_owner = null, lease_expires_at = null, updated_at = now()
  where id = v_job.id;
  if v_job.stripe_transfer_id is not null then
    update public.stripe_transfers
    set status = case when v_terminal then 'failed' else 'reconciliation_required' end,
        failure_code = left(coalesce(nullif(trim(p_error_code), ''), 'provider_unknown'), 80),
        updated_at = now()
    where id = v_job.stripe_transfer_id;
  end if;
  if v_terminal then
    update public.session_payments set transfer_status = 'failed',
      updated_at = now() where id = v_job.session_payment_id;
  end if;
  if v_terminal or v_job.attempt_count >= 8 then
    select * into v_payment from public.session_payments
    where id = v_job.session_payment_id;
    perform public.record_payout_operational_incident_v1(
      'session-transfer-v10:' || v_job.id::text,
      'session_direct_transfer_attention', 'critical',
      left(coalesce(nullif(trim(p_error_code), ''), 'provider_unknown'), 80),
      'O Transfer da sessao requer verificacao operacional.',
      null, null, null, v_job.stripe_transfer_id, null,
      v_payment.therapist_profile_id,
      jsonb_build_object('sessionPaymentId', v_job.session_payment_id)
    );
  end if;
  return jsonb_build_object('status', case when v_terminal then 'failed' else 'reconciliation_required' end);
end;
$$;


ALTER FUNCTION "public"."fail_session_transfer_job_v10"("p_job_id" "uuid", "p_worker_id" "uuid", "p_error_code" "text", "p_ambiguous" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_bilateral_session_confirmation_v1"("p_booking_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_patient public.session_participant_confirmations;
  v_therapist public.session_participant_confirmations;
  v_confirmed_at timestamptz;
begin
  select payment.* into v_payment
  from public.session_payments payment
  where payment.booking_id = p_booking_id
  for update;

  if not found then return 'payment_missing'; end if;
  if v_payment.financial_status not in ('paid', 'partially_refunded')
    or v_payment.refund_pending
    or v_payment.disputed_at is not null
    or v_payment.internal_contested_at is not null
    or v_payment.admin_blocked_at is not null then
    return 'payment_blocked';
  end if;
  if exists (
    select 1 from public.session_confirmation_incidents incident
    where incident.booking_id = p_booking_id and incident.status = 'open'
  ) then
    return 'incident_open';
  end if;

  select confirmation.* into v_patient
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = 'patient'::public.user_role;
  select confirmation.* into v_therapist
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = 'therapist'::public.user_role;

  if v_patient.id is null or v_therapist.id is null then return 'waiting_confirmation'; end if;
  if v_patient.outcome <> 'completed' or v_therapist.outcome <> 'completed' then
    return 'not_performed';
  end if;

  v_confirmed_at := greatest(v_patient.confirmed_at, v_therapist.confirmed_at);
  perform public.confirm_session_service(
    p_booking_id,
    'bilateral'::public.session_confirmation_source,
    null,
    null,
    jsonb_build_object(
      'confirmationModel', 'bilateral_role_deadlines',
      'patientSource', v_patient.source,
      'patientConfirmedAt', v_patient.confirmed_at,
      'therapistSource', v_therapist.source,
      'therapistConfirmedAt', v_therapist.confirmed_at,
      'confirmedAt', v_confirmed_at,
      'finalizedAt', p_now
    )
  );
  return 'confirmed';
end;
$$;


ALTER FUNCTION "public"."finalize_bilateral_session_confirmation_v1"("p_booking_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_bilateral_session_confirmation_v1"("p_booking_id" "uuid", "p_now" timestamp with time zone) IS 'Finalizes service confirmation only after both participants joined and both participant confirmations are completed.';



CREATE OR REPLACE FUNCTION "public"."finalize_financial_reconciliation_run_v1"("p_run_id" "uuid", "p_worker_id" "uuid", "p_status" "text", "p_source_charges_reconciled" integer DEFAULT 0, "p_settlements_reconciled" integer DEFAULT 0, "p_transfers_reconciled" integer DEFAULT 0, "p_payouts_reconciled" integer DEFAULT 0, "p_last_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_run_id is null or p_worker_id is null or p_status not in ('completed', 'failed') then
    raise exception 'FINANCIAL_RECONCILIATION_FINALIZE_INVALID';
  end if;

  update public.financial_reconciliation_runs
  set status = p_status,
      source_charges_reconciled = greatest(coalesce(p_source_charges_reconciled, 0), 0),
      settlements_reconciled = greatest(coalesce(p_settlements_reconciled, 0), 0),
      transfers_reconciled = greatest(coalesce(p_transfers_reconciled, 0), 0),
      payouts_reconciled = greatest(coalesce(p_payouts_reconciled, 0), 0),
      last_error = nullif(left(coalesce(p_last_error, ''), 1000), ''),
      completed_at = now(),
      lease_expires_at = now(),
      updated_at = now()
  where id = p_run_id
    and worker_id = p_worker_id
    and status = 'running';

  if not found then
    raise exception 'FINANCIAL_RECONCILIATION_RUN_CLAIM_LOST';
  end if;
end;
$$;


ALTER FUNCTION "public"."finalize_financial_reconciliation_run_v1"("p_run_id" "uuid", "p_worker_id" "uuid", "p_status" "text", "p_source_charges_reconciled" integer, "p_settlements_reconciled" integer, "p_transfers_reconciled" integer, "p_payouts_reconciled" integer, "p_last_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_payout_scheduler_run_v1"("p_scheduler_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.payout_scheduler_runs%rowtype;
  v_open_incidents integer;
  v_transfer_pending integer;
  v_transfer_failed integer;
  v_status public.payout_scheduler_run_status;
begin
  select * into v_run
  from public.payout_scheduler_runs
  where id = p_scheduler_run_id
  for update;
  if not found then raise exception 'PAYOUT_SCHEDULER_RUN_NOT_FOUND'; end if;

  select count(*) into v_open_incidents
  from public.payout_operational_incidents incident
  where incident.status = 'open'
    and (
      incident.payout_scheduler_run_id = v_run.id
      or incident.payout_batch_id = v_run.payout_batch_id
    );

  select
    count(*) filter (where item.status in ('reserved', 'transfer_pending')),
    count(*) filter (where item.status in ('failed', 'blocked'))
  into v_transfer_pending, v_transfer_failed
  from public.payout_batch_items item
  where item.payout_batch_id = v_run.payout_batch_id
    and item.status <> 'removed';

  if v_transfer_pending > 0 then
    update public.payout_batches
    set status = case when v_open_incidents > 0
      then 'partially_failed'::public.payout_batch_status
      else 'processing'::public.payout_batch_status end,
      updated_at = now()
    where id = v_run.payout_batch_id;
    return jsonb_build_object(
      'completed', false,
      'transferPending', v_transfer_pending,
      'awaitingAutomaticPayout', false
    );
  end if;

  v_status := case when v_open_incidents > 0 or v_transfer_failed > 0
    then 'completed_with_incidents'::public.payout_scheduler_run_status
    else 'completed'::public.payout_scheduler_run_status
  end;

  update public.payout_scheduler_runs
  set status = v_status,
      completed_at = coalesce(completed_at, now()),
      worker_id = null,
      lease_expires_at = null,
      updated_at = now()
  where id = v_run.id;

  perform public.refresh_automatic_payout_batch_states_v1();

  return jsonb_build_object(
    'completed', true,
    'status', v_status,
    'transferFailures', v_transfer_failed,
    'awaitingAutomaticPayout', v_transfer_failed = 0
  );
end;
$$;


ALTER FUNCTION "public"."finalize_payout_scheduler_run_v1"("p_scheduler_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_therapist_free_public_slug_v1"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate text;
  v_attempt integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('therapist-free-public-slug', 0));

  while v_attempt < 100 loop
    v_attempt := v_attempt + 1;
    v_candidate := (1000000 + floor(random() * 9000000)::integer)::text;
    if not exists (select 1 from public.therapist_profiles where slug = v_candidate or free_public_slug = v_candidate)
      and not exists (select 1 from public.therapist_profile_slug_history where old_slug = v_candidate)
    then
      return v_candidate;
    end if;
  end loop;

  raise exception 'FREE_PUBLIC_SLUG_EXHAUSTED' using errcode = 'P0001';
end;
$$;


ALTER FUNCTION "public"."generate_therapist_free_public_slug_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_payout_operations_v1"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (
    select 1 from public.profiles profile
    where profile.id = auth.uid() and profile.role = 'admin'
      and profile.auth_deleted_at is null and profile.anonymized_at is null
  ) then
    raise exception 'ADMIN_REQUIRED' using errcode = '42501';
  end if;
  if p_limit < 1 or p_limit > 200 then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'contractVersion', 2,
    'runs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', run.id,
        'businessDate', run.business_date,
        'cutoffAt', run.cutoff_at,
        'status', run.status,
        'attempts', run.attempts,
        'startedAt', run.started_at,
        'completedAt', run.completed_at,
        'windowAlertedAt', run.window_alerted_at
      ) order by run.business_date desc)
      from (select * from public.payout_scheduler_runs order by business_date desc limit p_limit) run
    ), '[]'::jsonb),
    'payouts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', payout.id,
        'therapistProfileId', payout.therapist_profile_id,
        'amountCents', payout.amount_cents,
        'currency', payout.currency,
        'automatic', payout.automatic,
        'status', payout.status,
        'providerReconciliationStatus', payout.provider_reconciliation_status,
        'allocationStatus', payout.allocation_status,
        'unmatchedTransactionCount', payout.unmatched_transaction_count,
        'arrivalAt', payout.arrival_at,
        'paidAt', payout.paid_at,
        'failedAt', payout.failed_at,
        'createdAt', payout.created_at
      ) order by payout.created_at desc)
      from (select * from public.stripe_payouts order by created_at desc limit p_limit) payout
    ), '[]'::jsonb),
    'incidents', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', incident.id,
        'type', incident.incident_type,
        'severity', incident.severity,
        'status', incident.status,
        'errorCode', incident.error_code,
        'occurrenceCount', incident.occurrence_count,
        'firstOccurredAt', incident.first_occurred_at,
        'lastOccurredAt', incident.last_occurred_at,
        'therapistProfileId', incident.therapist_profile_id
      ) order by incident.last_occurred_at desc)
      from (select * from public.payout_operational_incidents order by last_occurred_at desc limit p_limit) incident
    ), '[]'::jsonb),
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_admin_payout_operations_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_payout_operations_v1"("p_limit" integer) IS 'Contract v2: sanitized weekly runs, automatic Payout reconciliation and incidents.';



CREATE OR REPLACE FUNCTION "public"."get_booking_reschedule_availability_v1"("p_booking_id" "uuid", "p_actor_profile_id" "uuid", "p_scope" "text" DEFAULT 'next'::"text", "p_anchor" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_horizon_ends_at timestamptz;
  v_horizon_days integer;
  v_range_end timestamptz;
  v_range_start timestamptz;
  v_therapy_name text;
begin
  if p_scope not in ('next', 'month', 'day')
    or p_limit not between 1 and 1000
    or (p_scope in ('month', 'day') and p_anchor is null)
  then
    raise exception 'INVALID_RESCHEDULE_RANGE' using errcode = '22023';
  end if;

  if not public.is_booking_participant_profile_v1(
    p_booking_id,
    p_actor_profile_id
  ) then
    raise exception 'BOOKING_ACTOR_FORBIDDEN' using errcode = '42501';
  end if;

  select booking.*
  into v_booking
  from public.bookings as booking
  where booking.id = p_booking_id
    and booking.status = 'confirmed';

  if not found then
    raise exception 'BOOKING_CANNOT_BE_RESCHEDULED' using errcode = 'P0001';
  end if;

  select therapy.name into v_therapy_name
  from public.therapist_services as service
  join public.therapies as therapy on therapy.id = service.therapy_id
  where service.id = v_booking.service_id;

  if not found then
    raise exception 'BOOKING_CANNOT_BE_RESCHEDULED' using errcode = 'P0001';
  end if;

  select coalesce(
    (select settings.max_days_ahead
      from public.therapist_service_booking_settings as settings
      where settings.service_id = v_booking.service_id),
    90
  ) into v_horizon_days;

  v_horizon_ends_at := now() + v_horizon_days * interval '1 day';

  if p_scope = 'day' then
    v_range_start := greatest(
      now(),
      p_anchor::timestamp at time zone v_booking.timezone
    );
    v_range_end := least(
      (p_anchor + 1)::timestamp at time zone v_booking.timezone,
      v_horizon_ends_at
    );
  elsif p_scope = 'month' then
    v_range_start := greatest(
      now(),
      date_trunc('month', p_anchor)::timestamp at time zone v_booking.timezone
    );
    v_range_end := least(
      (date_trunc('month', p_anchor) + interval '1 month')::timestamp
        at time zone v_booking.timezone,
      v_horizon_ends_at
    );
  else
    v_range_start := now();
    v_range_end := v_horizon_ends_at;
  end if;

  return pg_catalog.jsonb_build_object(
    'contractVersion', 1,
    'booking', pg_catalog.jsonb_build_object(
      'id', v_booking.id,
      'version', v_booking.version,
      'startsAt', v_booking.starts_at
    ),
    'service', pg_catalog.jsonb_build_object(
      'id', v_booking.service_id,
      'title', v_booking.service_title_snapshot,
      'therapyName', v_therapy_name,
      'durationMinutes', v_booking.service_duration_minutes_snapshot,
      'priceCents', v_booking.service_price_cents_snapshot,
      'currency', v_booking.currency_snapshot
    ),
    'timezone', v_booking.timezone,
    'horizonEndsAt', v_horizon_ends_at,
    'scope', p_scope,
    'range', pg_catalog.jsonb_build_object(
      'start', v_range_start,
      'end', v_range_end,
      'endExclusive', true
    ),
    'slots', case
      when v_range_start >= v_range_end then '[]'::jsonb
      else (
        with candidate_slots as materialized (
          select
            candidate.starts_at,
            candidate.ends_at,
            candidate.occupied_during
          from public.list_booking_reschedule_candidates_v1(
            v_booking.id,
            v_range_start,
            v_range_end,
            now(),
            5000
          ) as candidate
          where candidate.starts_at is distinct from v_booking.starts_at
        ),
        therapist_blockers as materialized (
          select conflict.occupied_during
          from public.bookings as conflict
          where conflict.therapist_profile_id = v_booking.therapist_profile_id
            and conflict.id <> v_booking.id
            and conflict.status in ('draft', 'pending_payment', 'confirmed')
            and conflict.occupied_during && pg_catalog.tstzrange(
              v_range_start,
              v_range_end,
              '[)'
            )
        ),
        live_holds as materialized (
          select hold.occupied_during
          from public.booking_holds as hold
          where hold.therapist_profile_id = v_booking.therapist_profile_id
            and hold.status = 'active'
            and hold.expires_at > now()
            and hold.occupied_during && pg_catalog.tstzrange(
              v_range_start,
              v_range_end,
              '[)'
            )
        ),
        patient_blockers as materialized (
          select pg_catalog.tstzrange(
            blocker.starts_at,
            blocker.ends_at,
            '[)'
          ) as occupied_during
          from public.get_patient_schedule_blocking_bookings_v1(
            v_booking.patient_profile_id,
            v_range_start,
            v_range_end,
            v_booking.id
          ) as blocker
        ),
        available as (
          select candidate.starts_at, candidate.ends_at
          from candidate_slots as candidate
          where not exists (
              select 1
              from therapist_blockers as conflict
              where conflict.occupied_during && candidate.occupied_during
            )
            and not exists (
              select 1
              from live_holds as hold
              where hold.occupied_during && candidate.occupied_during
            )
            and not exists (
              select 1
              from patient_blockers as blocker
              where blocker.occupied_during && pg_catalog.tstzrange(
                candidate.starts_at,
                candidate.ends_at,
                '[)'
              )
            )
          order by candidate.starts_at
          limit p_limit
        )
        select coalesce(
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'startsAt', available.starts_at,
              'endsAt', available.ends_at
            ) order by available.starts_at
          ),
          '[]'::jsonb
        )
        from available
      )
    end
  );
end;
$$;


ALTER FUNCTION "public"."get_booking_reschedule_availability_v1"("p_booking_id" "uuid", "p_actor_profile_id" "uuid", "p_scope" "text", "p_anchor" "date", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_booking_reschedule_availability_v1"("p_booking_id" "uuid", "p_actor_profile_id" "uuid", "p_scope" "text", "p_anchor" "date", "p_limit" integer) IS 'Participant-authorized booking availability with immutable service snapshots and set-based current schedule, hold, therapist and patient conflict filtering.';



CREATE OR REPLACE FUNCTION "public"."get_my_patient_schedule_blocking_intervals_v1"("p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone) RETURNS TABLE("starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_patient_profile_id uuid;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  if p_range_start is null
    or p_range_end is null
    or p_range_start >= p_range_end
    or p_range_end - p_range_start > interval '120 days' then
    raise exception 'INVALID_PATIENT_SCHEDULE_RANGE' using errcode = '22023';
  end if;

  select patient.id
    into v_patient_profile_id
  from public.patient_profiles as patient
  where patient.user_id = auth.uid();

  if v_patient_profile_id is null then
    raise exception 'PATIENT_PROFILE_REQUIRED' using errcode = '42501';
  end if;

  return query
  select blocker.starts_at, blocker.ends_at
  from public.get_patient_schedule_blocking_bookings_v1(
    v_patient_profile_id,
    p_range_start,
    p_range_end,
    null
  ) as blocker
  order by blocker.starts_at, blocker.ends_at;
end;
$$;


ALTER FUNCTION "public"."get_my_patient_schedule_blocking_intervals_v1"("p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_patient_schedule_blocking_intervals_v1"("p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone) IS 'Returns only the authenticated patient own blocking intervals for reservation UI prevention.';



CREATE OR REPLACE FUNCTION "public"."get_patient_reservation_attempt_status_v1"("p_booking_id" "uuid", "p_stripe_checkout_session_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.session_payment_attempts%rowtype;
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
begin
  select booking.* into v_booking
  from public.bookings as booking
  join public.patient_profiles as patient
    on patient.id = booking.patient_profile_id
  where booking.id = p_booking_id
    and patient.user_id = auth.uid();

  if not found then
    return jsonb_build_object('status', 'failed');
  end if;

  select * into v_payment
  from public.session_payments
  where booking_id = v_booking.id;

  select * into v_attempt
  from public.session_payment_attempts
  where session_payment_id = v_payment.id
    and stripe_checkout_session_id = coalesce(
      p_stripe_checkout_session_id,
      v_payment.stripe_checkout_session_id
    )
  order by created_at desc
  limit 1;

  if p_stripe_checkout_session_id is not null and not found then
    return jsonb_build_object('status', 'failed');
  end if;

  if v_payment.payment_flow_version = 'v10' then
    select schedule.*
    into v_schedule
    from public.session_payment_schedules as schedule
    where schedule.session_payment_id = v_payment.id
    order by schedule.created_at desc
    limit 1;
  end if;

  return jsonb_build_object(
    'status', case
      when v_payment.financial_status = 'paid' and v_booking.status = 'confirmed'
        then 'confirmed'
      when v_payment.payment_flow_version = 'v10'
        and v_booking.status = 'confirmed'
        and v_payment.financial_status = 'pending'
        and v_attempt.status = 'setup_succeeded'
        and v_schedule.status in ('scheduled', 'claimed', 'processing', 'retry_scheduled')
        then 'scheduled'
      when v_attempt.status = 'slot_conflict'
        or (v_attempt.status in ('failed', 'canceled', 'expired')
          and v_attempt.terminal_reason in ('patient_schedule_conflict', 'slot_conflict'))
        then 'slot_conflict'
      when v_attempt.status = 'expired'
        or (v_attempt.status in ('failed', 'canceled')
          and v_attempt.terminal_reason = 'reservation_expired')
        then 'expired'
      when v_attempt.status in ('failed', 'canceled') then 'failed'
      when v_attempt.status = 'capture_pending'
        or v_attempt.status = 'paid'
        or v_payment.financial_status in ('processing', 'paid') then 'authorizing'
      when v_attempt.status in ('checkout_created', 'waiting_payment', 'processing')
        then 'waiting_payment'
      when v_payment.financial_status in ('failed', 'canceled') then 'failed'
      else 'waiting_payment'
    end,
    'bookingId', v_booking.id,
    'conflictKind', case
      when v_attempt.status in ('slot_conflict', 'failed', 'canceled', 'expired')
        and v_attempt.terminal_reason = 'patient_schedule_conflict'
        then 'patient_schedule'
      when v_attempt.status = 'slot_conflict'
        or (v_attempt.status in ('failed', 'canceled', 'expired')
          and v_attempt.terminal_reason = 'slot_conflict')
        then 'therapist_slot'
      else null
    end
  );
end;
$$;


ALTER FUNCTION "public"."get_patient_reservation_attempt_status_v1"("p_booking_id" "uuid", "p_stripe_checkout_session_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_patient_reservation_retry_context_v1"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
begin
  select jsonb_build_object(
    'bookingId', booking.id,
    'serviceId', booking.service_id,
    'serviceLabel', booking.service_title_snapshot,
    'durationMinutes', booking.service_duration_minutes_snapshot,
    'priceCents', booking.service_price_cents_snapshot,
    'startsAt', booking.starts_at,
    'timezone', booking.timezone,
    'bookingStatus', booking.status,
    'financialStatus', payment.financial_status,
    'canRetry', (
      (
        booking.status = 'cancelled_by_payment'
        and payment.financial_status in ('failed', 'canceled')
      )
      or (
        booking.status = 'pending_payment'
        and booking.payment_status = 'pending'
        and booking.starts_at > now()
        and payment.payment_flow_version = 'v10'
        and payment.financial_status = 'pending'
        and payment.stripe_payment_intent_id is null
        and payment.stripe_charge_id is null
        and attempt.id is not null
        and attempt.attempt_kind in ('initial_hold', 'payment_retry')
        and attempt.status in ('expired', 'failed', 'canceled', 'slot_conflict')
        and attempt.slot_claimed_at is null
        and not exists (
          select 1 from public.session_payment_setups as setup
          where setup.session_payment_id = payment.id
            and setup.status = 'succeeded'
            and setup.superseded_at is null
        )
        and not exists (
          select 1 from public.session_payment_schedules as schedule
          where schedule.session_payment_id = payment.id
            and schedule.status not in ('canceled', 'superseded')
        )
        and not exists (
          select 1 from public.session_transfer_jobs as job
          where job.session_payment_id = payment.id
        )
        and not exists (
          select 1 from public.stripe_transfers as transfer
          where transfer.session_payment_id = payment.id
        )
      )
    ),
    'therapist', jsonb_build_object(
      'slug', therapist.slug,
      'name', therapist.public_name,
      'headline', coalesce(therapist.headline, 'Profissional TES'),
      'avatarUrl', therapist.photo_url,
      'isVerified', therapist.status = 'approved'
    )
  ) into v_result
  from public.bookings as booking
  join public.patient_profiles as patient
    on patient.id = booking.patient_profile_id
  join public.therapist_profiles as therapist
    on therapist.id = booking.therapist_profile_id
  join public.session_payments as payment
    on payment.booking_id = booking.id
  left join lateral (
    select current_attempt.*
    from public.session_payment_attempts as current_attempt
    where current_attempt.session_payment_id = payment.id
      and current_attempt.stripe_checkout_session_id = payment.stripe_checkout_session_id
    order by current_attempt.created_at desc
    limit 1
  ) as attempt on true
  where booking.id = p_booking_id
    and patient.user_id = auth.uid();

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_patient_reservation_retry_context_v1"("p_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_patient_reservation_retry_context_v1"("p_booking_id" "uuid") IS 'Returns the authenticated retry snapshot with a server-derived retry eligibility flag.';



CREATE OR REPLACE FUNCTION "public"."get_patient_schedule_blocking_bookings_v1"("p_patient_profile_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_exclude_booking_id" "uuid") RETURNS TABLE("booking_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select distinct
    booking.id,
    booking.starts_at,
    booking.ends_at
  from public.bookings as booking
  left join public.session_payments as payment
    on payment.booking_id = booking.id
  left join public.session_payment_attempts as attempt
    on attempt.session_payment_id = payment.id
   and attempt.stripe_checkout_session_id = payment.stripe_checkout_session_id
  where booking.patient_profile_id = p_patient_profile_id
    and booking.id is distinct from p_exclude_booking_id
    and booking.starts_at < p_range_end
    and booking.ends_at > p_range_start
    and (
      booking.status in ('confirmed', 'completed')
      or (
        booking.status in ('draft', 'pending_payment')
        and payment.financial_status = 'paid'
      )
      or (
        booking.status in ('draft', 'pending_payment')
        and payment.financial_status = 'processing'
        and attempt.status = 'capture_pending'
        and attempt.slot_claimed_at is not null
      )
    );
$$;


ALTER FUNCTION "public"."get_patient_schedule_blocking_bookings_v1"("p_patient_profile_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_exclude_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_patient_schedule_blocking_bookings_v1"("p_patient_profile_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_exclude_booking_id" "uuid") IS 'Canonical patient schedule blockers: confirmed/completed, paid awaiting projection, or the current claimed manual authorization.';



CREATE OR REPLACE FUNCTION "public"."get_patient_session_charge_status_v10"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
begin
  if p_booking_id is null or auth.uid() is null then
    raise exception 'SESSION_CHARGE_ACCESS_DENIED' using errcode = '42501';
  end if;
  select b.* into v_booking from public.bookings b
  join public.patient_profiles patient on patient.id = b.patient_profile_id
  where b.id = p_booking_id and patient.user_id = auth.uid();
  if not found then
    raise exception 'SESSION_CHARGE_ACCESS_DENIED' using errcode = '42501';
  end if;
  select * into v_schedule from public.session_payment_schedules
  where booking_id = p_booking_id order by created_at desc limit 1;
  if not found then return jsonb_build_object('flow', 'other'); end if;
  return jsonb_build_object(
    'flow', 'v10',
    'status', v_schedule.status,
    'dueAt', v_schedule.due_at,
    'recoveryAvailable', v_schedule.status = 'requires_customer_action'
      and v_booking.status = 'confirmed'
      and v_booking.version = v_schedule.expected_booking_version
      and v_booking.starts_at > now()
      and v_schedule.stripe_payment_intent_id is not null
  );
end;
$$;


ALTER FUNCTION "public"."get_patient_session_charge_status_v10"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_patient_session_feedback_queue_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with legacy as (
    select public.private_patient_session_feedback_queue_v1_v9_legacy() payload
  ), items as (
    select item.value payload
    from legacy
    cross join lateral jsonb_array_elements(legacy.payload) item
  )
  select coalesce(jsonb_agg(
    case when payment.payment_flow_version = 'v10' then
      items.payload || jsonb_build_object(
        'confirmationState', case
          when payment.internal_contested_at is not null
            or payment.admin_blocked_at is not null
            or exists (
              select 1 from public.session_confirmation_incidents incident
              where incident.booking_id = payment.booking_id
                and incident.status = 'open'
            ) then 'blocked_for_review'
          when items.payload -> 'actorConfirmation' = 'null'::jsonb
            and items.payload -> 'counterpartConfirmation' = 'null'::jsonb
            then 'awaiting_both'
          when items.payload -> 'actorConfirmation' = 'null'::jsonb
            then 'awaiting_patient'
          when items.payload -> 'counterpartConfirmation' = 'null'::jsonb
            then 'awaiting_therapist'
          else 'completed'
        end,
        'eligibleAt', null,
        'nextBatchAt', null
      )
    else items.payload end
    order by (items.payload ->> 'endsAt')::timestamptz desc
  ), '[]'::jsonb)
  from items
  join public.session_payments payment
    on payment.booking_id = (items.payload ->> 'bookingId')::uuid;
$$;


ALTER FUNCTION "public"."get_patient_session_feedback_queue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_patient_therapist_review_v1"("p_therapist_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_patient_id uuid;
  v_review public.reviews;
  v_eligible boolean;
begin
  if v_actor_id is null then
    raise exception 'PATIENT_REVIEW_AUTH_REQUIRED' using errcode = '42501';
  end if;
  select patient.id into v_patient_id
  from public.patient_profiles patient where patient.user_id = v_actor_id;
  if v_patient_id is null then
    raise exception 'PATIENT_REVIEW_PATIENT_REQUIRED' using errcode = '42501';
  end if;

  select exists (
    select 1
    from public.bookings booking
    join public.session_participant_confirmations confirmation
      on confirmation.booking_id = booking.id
      and confirmation.participant_role = 'patient'::public.user_role
      and confirmation.outcome = 'completed'
    where booking.patient_profile_id = v_patient_id
      and booking.therapist_profile_id = p_therapist_profile_id
  ) into v_eligible;

  select review.* into v_review
  from public.reviews review
  where review.patient_profile_id = v_patient_id
    and review.therapist_profile_id = p_therapist_profile_id
    and review.superseded_at is null;

  return jsonb_build_object(
    'eligible', v_eligible,
    'review', public.patient_review_payload_v1(v_review),
    'therapistProfileId', p_therapist_profile_id
  );
end;
$$;


ALTER FUNCTION "public"."get_patient_therapist_review_v1"("p_therapist_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payout_transfer_liquidity_requirement_v1"("p_payout_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item_count integer;
  v_amount_cents integer;
begin
  if p_payout_batch_id is null then
    raise exception 'PAYOUT_LIQUIDITY_REQUIREMENT_INVALID';
  end if;

  if not exists (
    select 1 from public.payout_batches where id = p_payout_batch_id
  ) then
    raise exception 'PAYOUT_BATCH_NOT_FOUND';
  end if;

  select count(*)::integer, coalesce(sum(item.amount_cents), 0)::integer
  into v_item_count, v_amount_cents
  from public.payout_batch_items item
  left join public.stripe_transfers transfer
    on transfer.payout_batch_item_id = item.id
  where item.payout_batch_id = p_payout_batch_id
    and item.status in ('reserved', 'failed', 'transfer_pending')
    and (transfer.id is null or transfer.status <> 'transferred');

  return jsonb_build_object(
    'itemCount', v_item_count,
    'amountCents', v_amount_cents
  );
end;
$$;


ALTER FUNCTION "public"."get_payout_transfer_liquidity_requirement_v1"("p_payout_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_payout_transfer_liquidity_requirement_v1"("p_payout_batch_id" "uuid") IS 'Returns the complete unresolved batch liability for a fail-before-claim Stripe platform balance check. It does not reserve or mutate funds.';



