CREATE OR REPLACE FUNCTION "public"."get_private_therapist_bank_payouts_v1"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
begin
  if p_limit < 1 or p_limit > 100 then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;
  v_therapist := public.get_private_therapist_financial_actor_v1();

  return jsonb_build_object(
    'contractVersion', 2,
    'therapistProfileId', v_therapist.id,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'payoutBatchId', therapist_group.payout_batch_id,
        'payoutBatchTherapistId', therapist_group.id,
        'amountCents', therapist_group.total_amount_cents,
        'currency', 'BRL',
        'transferStage', case
          when stats.transfer_attention_count > 0 then 'attention'
          when stats.transfer_pending_count = 0 then 'transferred'
          else 'processing'
        end,
        'bankPayoutStatus', case
          when stats.payout_attention_count > 0 then 'attention'
          when stats.transfer_count > 0
            and stats.paid_transfer_count = stats.transfer_count then 'paid'
          when stats.paid_transfer_count > 0 then 'partially_paid'
          when stats.transfer_pending_count = 0 then 'awaiting_automatic_payout'
          else 'not_available'
        end,
        'payoutCount', stats.payout_count,
        'payoutCreatedAt', stats.payout_created_at,
        'expectedArrivalAt', stats.expected_arrival_at,
        'paidAt', stats.paid_at,
        'failedAt', stats.failed_at,
        'requiresReconciliation', stats.transfer_attention_count > 0
          or stats.payout_attention_count > 0
      ) order by therapist_group.created_at desc)
      from (
        select * from public.payout_batch_therapists group_row
        where group_row.therapist_profile_id = v_therapist.id
        order by group_row.created_at desc
        limit p_limit
      ) therapist_group
      cross join lateral (
        select
          count(distinct transfer.id)::integer as transfer_count,
          count(distinct transfer.id) filter (
            where item.status <> 'transferred'
              or transfer.status is null
              or transfer.status <> 'transferred'
          )::integer as transfer_pending_count,
          count(distinct transfer.id) filter (
            where item.status in ('failed', 'blocked')
              or transfer.status in ('failed', 'reconciliation_required', 'reversed')
          )::integer as transfer_attention_count,
          count(distinct transfer.id) filter (
            where payout.status = 'paid'
              and payout.provider_reconciliation_status = 'completed'
              and payout.allocation_status = 'completed'
          )::integer as paid_transfer_count,
          count(distinct payout.id)::integer as payout_count,
          count(distinct payout.id) filter (
            where payout.status in ('failed', 'canceled', 'reconciliation_required')
              or payout.allocation_status = 'partial'
          )::integer as payout_attention_count,
          min(payout.created_at) as payout_created_at,
          max(payout.arrival_at) as expected_arrival_at,
          max(payout.paid_at) as paid_at,
          max(payout.failed_at) as failed_at
        from public.payout_batch_items item
        left join public.stripe_transfers transfer
          on transfer.payout_batch_item_id = item.id
        left join public.stripe_payout_transfer_allocations allocation
          on allocation.stripe_transfer_id = transfer.id
        left join public.stripe_payouts payout
          on payout.id = allocation.stripe_payout_id
        where item.payout_batch_therapist_id = therapist_group.id
          and item.status <> 'removed'
      ) stats
    ), '[]'::jsonb),
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_private_therapist_bank_payouts_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_private_therapist_bank_payouts_v1"("p_limit" integer) IS 'Contract v2: weekly Transfer progress and many-to-many automatic bank Payout coverage without provider identifiers.';



CREATE OR REPLACE FUNCTION "public"."get_private_therapist_connect_account_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_account public.therapist_connect_accounts%rowtype;
  v_previous_account_closed boolean := false;
  v_currently_due jsonb := '[]'::jsonb;
  v_eventually_due jsonb := '[]'::jsonb;
  v_pending_verification jsonb := '[]'::jsonb;
begin
  v_therapist := public.get_private_therapist_financial_actor_v1();

  select * into v_account
  from public.therapist_connect_accounts as account
  where account.therapist_profile_id = v_therapist.id
    and account.is_current;

  if not found then
    select exists(
      select 1
      from public.therapist_connect_accounts historical
      where historical.therapist_profile_id = v_therapist.id
        and not historical.is_current
        and historical.disabled_reason = 'account_closed'
    ) into v_previous_account_closed;

    return jsonb_build_object(
      'contractVersion', 1,
      'therapistProfileId', v_therapist.id,
      'accountExists', false,
      'previousAccountClosed', v_previous_account_closed,
      'maskedAccountId', null,
      'onboardingStatus', 'not_started',
      'detailsSubmitted', false,
      'payoutsEnabled', false,
      'chargesEnabled', false,
      'transferCapabilityStatus', 'inactive',
      'currentlyDue', '[]'::jsonb,
      'eventuallyDue', '[]'::jsonb,
      'pendingVerification', '[]'::jsonb,
      'disabledReason', null,
      'maskedBankAccountSummary', null,
      'lastSyncedAt', null,
      'generatedAt', now()
    );
  end if;

  if jsonb_typeof(v_account.pending_requirements) = 'object' then
    v_currently_due := coalesce(v_account.pending_requirements -> 'currentlyDue', v_account.pending_requirements -> 'currently_due', '[]'::jsonb);
    v_eventually_due := coalesce(v_account.pending_requirements -> 'eventuallyDue', v_account.pending_requirements -> 'eventually_due', '[]'::jsonb);
    v_pending_verification := coalesce(v_account.pending_requirements -> 'pendingVerification', v_account.pending_requirements -> 'pending_verification', '[]'::jsonb);
  elsif jsonb_typeof(v_account.pending_requirements) = 'array' then
    v_currently_due := v_account.pending_requirements;
  end if;

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', v_therapist.id,
    'accountExists', true,
    'previousAccountClosed', false,
    'maskedAccountId', left(v_account.stripe_account_id, 7) || '...' || right(v_account.stripe_account_id, 4),
    'onboardingStatus', v_account.onboarding_status,
    'detailsSubmitted', v_account.details_submitted,
    'payoutsEnabled', v_account.payouts_enabled,
    'chargesEnabled', v_account.charges_enabled,
    'transferCapabilityStatus', v_account.stripe_transfers_status,
    'currentlyDue', v_currently_due,
    'eventuallyDue', v_eventually_due,
    'pendingVerification', v_pending_verification,
    'disabledReason', v_account.disabled_reason,
    'maskedBankAccountSummary', null,
    'lastSyncedAt', v_account.last_synced_at,
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_private_therapist_connect_account_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_private_therapist_connect_account_v1"() IS 'Private Stripe Connect account state for the therapist shell. Returns masked identifiers only and no bank-account form data.';



CREATE TABLE IF NOT EXISTS "public"."therapist_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "plan" "public"."therapist_plan" DEFAULT 'free'::"public"."therapist_plan" NOT NULL,
    "status" "public"."therapist_status" DEFAULT 'draft'::"public"."therapist_status" NOT NULL,
    "slug" "text" NOT NULL,
    "public_name" "text" NOT NULL,
    "legal_name" "text",
    "headline" "text",
    "bio" "text",
    "photo_url" "text",
    "city" "text",
    "state" "text",
    "country" "text" DEFAULT 'BR'::"text",
    "languages" "text"[] DEFAULT ARRAY['pt-BR'::"text"] NOT NULL,
    "is_public" boolean DEFAULT false NOT NULL,
    "is_accepting_bookings" boolean DEFAULT false NOT NULL,
    "accepts_online_sessions" boolean DEFAULT true NOT NULL,
    "visibility_flags" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "public_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "profile_version" bigint DEFAULT 1 NOT NULL,
    "last_published_at" timestamp with time zone,
    "unpublished_at" timestamp with time zone,
    "public_profile_theme" "text" DEFAULT 'serene'::"text" NOT NULL,
    "free_public_slug" "text" NOT NULL,
    CONSTRAINT "therapist_profiles_accepts_online_sessions_check" CHECK (("accepts_online_sessions" IS TRUE)),
    CONSTRAINT "therapist_profiles_free_public_slug_format_check" CHECK ((("free_public_slug" IS NULL) OR ("free_public_slug" ~ '^[1-9][0-9]{6}$'::"text"))),
    CONSTRAINT "therapist_profiles_public_profile_theme_check" CHECK (("public_profile_theme" = ANY (ARRAY['ancestral'::"text", 'aurora'::"text", 'botanico'::"text", 'celestial'::"text", 'cristalino'::"text", 'energia'::"text", 'essencial_editorial'::"text", 'essential'::"text", 'frequencia'::"text", 'geometria'::"text", 'lunar'::"text", 'natural'::"text", 'oraculo'::"text", 'profundo'::"text", 'sagrado'::"text", 'sereno_horizonte'::"text", 'serene'::"text", 'vinculos'::"text", 'warm'::"text"]))),
    CONSTRAINT "therapist_profiles_public_status_check" CHECK (("public_status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'unpublished'::"text", 'suspended'::"text", 'archived'::"text"])))
);


