CREATE OR REPLACE FUNCTION "public"."get_private_therapist_financial_metrics_v1"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_period record;
  v_period_days integer;
  v_previous_period_start date;
  v_previous_period_end date;
  v_previous_starts_at timestamptz;
  v_today date;
  v_gross_paid_cents integer := 0;
  v_previous_gross_paid_cents integer := 0;
  v_therapist_net_cents integer := 0;
  v_previous_therapist_net_cents integer := 0;
  v_paid_session_count integer := 0;
  v_previous_paid_session_count integer := 0;
  v_gross_average_ticket_cents integer;
  v_net_average_ticket_cents integer;
  v_previous_net_average_ticket_cents integer;
  v_completed_count integer := 0;
  v_cancelled_count integer := 0;
  v_rescheduled_count integer := 0;
  v_eligible_scheduled_count integer := 0;
  v_cancellation_rate numeric;
  v_reschedule_rate numeric;
  v_eligible_patients integer := 0;
  v_returning_patients integer := 0;
  v_return_rate numeric;
  v_revenue_by_therapy jsonb := '[]'::jsonb;
  v_financial_evolution jsonb := '[]'::jsonb;
begin
  v_therapist := public.get_private_therapist_financial_actor_v1();

  if v_therapist.plan = 'free' then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select *
    into v_period
  from public.normalize_private_therapist_finance_period_v1(
    p_period_start,
    p_period_end,
    p_timezone
  );

  v_period_days := (v_period.period_end - v_period.period_start) + 1;
  v_previous_period_end := v_period.period_start - 1;
  v_previous_period_start := v_previous_period_end - (v_period_days - 1);
  v_previous_starts_at := v_previous_period_start::timestamp at time zone v_period.timezone;
  v_today := (now() at time zone v_period.timezone)::date;

  with paid_rows as (
    select
      case
        when coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
          then 'current'
        else 'previous'
      end as period_key,
      payment.id,
      payment.gross_amount_cents,
      payment.platform_gross_commission_cents,
      public.private_therapist_finance_refunded_cents_v1(payment.id)
        as refunded_cents
    from public.session_payments as payment
    where payment.therapist_profile_id = v_therapist.id
      and payment.financial_status in (
        'paid',
        'partially_refunded',
        'refunded',
        'disputed'
      )
      and coalesce(payment.paid_at, payment.created_at) >= v_previous_starts_at
      and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at
  )
  select
    coalesce(sum(gross_amount_cents) filter (where period_key = 'current'), 0)::integer,
    coalesce(sum(gross_amount_cents) filter (where period_key = 'previous'), 0)::integer,
    coalesce(sum(
      gross_amount_cents - platform_gross_commission_cents - refunded_cents
    ) filter (where period_key = 'current'), 0)::integer,
    coalesce(sum(
      gross_amount_cents - platform_gross_commission_cents - refunded_cents
    ) filter (where period_key = 'previous'), 0)::integer,
    count(*) filter (where period_key = 'current')::integer,
    count(*) filter (where period_key = 'previous')::integer
    into
      v_gross_paid_cents,
      v_previous_gross_paid_cents,
      v_therapist_net_cents,
      v_previous_therapist_net_cents,
      v_paid_session_count,
      v_previous_paid_session_count
  from paid_rows;

  v_gross_average_ticket_cents := case
    when v_paid_session_count = 0 then null
    else round(v_gross_paid_cents::numeric / v_paid_session_count)::integer
  end;
  v_net_average_ticket_cents := case
    when v_paid_session_count = 0 then null
    else round(v_therapist_net_cents::numeric / v_paid_session_count)::integer
  end;
  v_previous_net_average_ticket_cents := case
    when v_previous_paid_session_count = 0 then null
    else round(v_previous_therapist_net_cents::numeric / v_previous_paid_session_count)::integer
  end;

  select
    count(distinct booking.id) filter (
      where booking.status = 'completed'
        or payment.service_status in (
          'confirmed_by_patient_review',
          'confirmed_by_therapist',
          'auto_confirmed'
        )
        or payment.service_confirmed_at is not null
    )::integer,
    count(distinct booking.id) filter (
      where booking.status in (
        'cancelled_by_patient',
        'cancelled_by_therapist',
        'refunded'
      )
    )::integer,
    count(distinct booking.id) filter (
      where booking.status in (
        'confirmed',
        'completed',
        'cancelled_by_patient',
        'cancelled_by_therapist',
        'no_show_patient',
        'no_show_therapist',
        'refunded'
      )
    )::integer
    into v_completed_count, v_cancelled_count, v_eligible_scheduled_count
  from public.bookings as booking
  left join public.session_payments as payment
    on payment.booking_id = booking.id
  where booking.therapist_profile_id = v_therapist.id
    and booking.starts_at >= v_period.starts_at
    and booking.starts_at < v_period.ends_at;

  select count(distinct request.booking_id)::integer
    into v_rescheduled_count
  from public.booking_reschedule_requests as request
  join public.bookings as booking
    on booking.id = request.booking_id
  where booking.therapist_profile_id = v_therapist.id
    and request.status = 'applied'
    and request.applied_at >= v_period.starts_at
    and request.applied_at < v_period.ends_at;

  v_cancellation_rate := case
    when v_eligible_scheduled_count = 0 then null
    else round(v_cancelled_count::numeric * 100 / v_eligible_scheduled_count, 1)
  end;
  v_reschedule_rate := case
    when v_eligible_scheduled_count = 0 then null
    else round(v_rescheduled_count::numeric * 100 / v_eligible_scheduled_count, 1)
  end;

  with first_completed as (
    select
      booking.patient_profile_id,
      min(booking.starts_at) as first_completed_at
    from public.bookings as booking
    left join public.session_payments as payment
      on payment.booking_id = booking.id
    where booking.therapist_profile_id = v_therapist.id
      and booking.starts_at >= v_period.starts_at
      and booking.starts_at < v_period.ends_at
      and (
        booking.status = 'completed'
        or payment.service_status in (
          'confirmed_by_patient_review',
          'confirmed_by_therapist',
          'auto_confirmed'
        )
        or payment.service_confirmed_at is not null
      )
    group by booking.patient_profile_id
  ),
  eligible as (
    select *
    from first_completed
    where first_completed_at + interval '90 days' <= v_period.ends_at
  ),
  returned as (
    select distinct eligible.patient_profile_id
    from eligible
    join public.session_payments as payment
      on payment.therapist_profile_id = v_therapist.id
      and payment.patient_profile_id = eligible.patient_profile_id
      and payment.financial_status in (
        'paid',
        'partially_refunded',
        'refunded',
        'disputed'
      )
      and coalesce(payment.paid_at, payment.created_at) > eligible.first_completed_at
      and coalesce(payment.paid_at, payment.created_at)
        <= eligible.first_completed_at + interval '90 days'
  )
  select
    (select count(*)::integer from eligible),
    (select count(*)::integer from returned)
    into v_eligible_patients, v_returning_patients;

  v_return_rate := case
    when v_eligible_patients < 10 then null
    else round(v_returning_patients::numeric * 100 / v_eligible_patients, 1)
  end;

  with paid_rows as (
    select
      therapy.id as therapy_id,
      coalesce(therapy.name, booking.service_title_snapshot) as therapy_name_snapshot,
      payment.id,
      payment.gross_amount_cents,
      payment.platform_gross_commission_cents,
      public.private_therapist_finance_refunded_cents_v1(payment.id)
        as refunded_cents
    from public.session_payments as payment
    join public.bookings as booking
      on booking.id = payment.booking_id
    join public.therapist_services as service
      on service.id = payment.service_id
    left join public.therapies as therapy
      on therapy.id = service.therapy_id
    where payment.therapist_profile_id = v_therapist.id
      and payment.financial_status in (
        'paid',
        'partially_refunded',
        'refunded',
        'disputed'
      )
      and coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
      and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at
  ),
  grouped as (
    select
      therapy_id,
      max(therapy_name_snapshot) as therapy_name_snapshot,
      count(*)::integer as paid_session_count,
      sum(gross_amount_cents)::integer as gross_amount_cents,
      sum(gross_amount_cents - platform_gross_commission_cents - refunded_cents)::integer
        as therapist_net_amount_cents
    from paid_rows
    group by therapy_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'therapyId', therapy_id,
        'therapyNameSnapshot', therapy_name_snapshot,
        'paidSessionCount', paid_session_count,
        'grossAmountCents', gross_amount_cents,
        'therapistNetAmountCents', therapist_net_amount_cents,
        'averageTicketCents', case
          when paid_session_count = 0 then null
          else round(gross_amount_cents::numeric / paid_session_count)::integer
        end
      )
      order by therapist_net_amount_cents desc, therapy_name_snapshot
    ),
    '[]'::jsonb
  )
    into v_revenue_by_therapy
  from (
    select *
    from grouped
    order by therapist_net_amount_cents desc, therapy_name_snapshot
    limit 6
  ) as limited;

  with buckets as (
    select
      bucket_start::date as period_start,
      least(
        (bucket_start::date + 6),
        v_period.period_end
      )::date as period_end
    from generate_series(
      v_period.period_start,
      v_period.period_end,
      interval '7 days'
    ) as bucket(bucket_start)
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'periodStart', bucket.period_start,
        'periodEnd', bucket.period_end,
        'grossAmountCents', coalesce((
          select sum(payment.gross_amount_cents)::integer
          from public.session_payments as payment
          where payment.therapist_profile_id = v_therapist.id
            and payment.financial_status in (
              'paid',
              'partially_refunded',
              'refunded',
              'disputed'
            )
            and (coalesce(payment.paid_at, payment.created_at) at time zone v_period.timezone)::date
              between bucket.period_start and bucket.period_end
        ), 0),
        'therapistNetAmountCents', coalesce((
          select sum(
            payment.gross_amount_cents
            - payment.platform_gross_commission_cents
            - public.private_therapist_finance_refunded_cents_v1(payment.id)
          )::integer
          from public.session_payments as payment
          where payment.therapist_profile_id = v_therapist.id
            and payment.financial_status in (
              'paid',
              'partially_refunded',
              'refunded',
              'disputed'
            )
            and (coalesce(payment.paid_at, payment.created_at) at time zone v_period.timezone)::date
              between bucket.period_start and bucket.period_end
        ), 0),
        'previousPeriodNetAmountCents', (
          select coalesce(sum(
            payment.gross_amount_cents
            - payment.platform_gross_commission_cents
            - public.private_therapist_finance_refunded_cents_v1(payment.id)
          ), 0)::integer
          from public.session_payments as payment
          where payment.therapist_profile_id = v_therapist.id
            and payment.financial_status in (
              'paid',
              'partially_refunded',
              'refunded',
              'disputed'
            )
            and (coalesce(payment.paid_at, payment.created_at) at time zone v_period.timezone)::date
              between (
                v_previous_period_start + (bucket.period_start - v_period.period_start)
              )
              and least(
                v_previous_period_start + (bucket.period_end - v_period.period_start),
                v_previous_period_end
              )
        )
      )
      order by bucket.period_start
    ),
    '[]'::jsonb
  )
    into v_financial_evolution
  from buckets as bucket;

  return jsonb_build_object(
    'contractVersion', 1,
    'metricDefinitionVersion', 1,
    'therapistProfileId', v_therapist.id,
    'plan', v_therapist.plan,
    'period', jsonb_build_object(
      'start', v_period.period_start,
      'end', v_period.period_end,
      'previousStart', v_previous_period_start,
      'previousEnd', v_previous_period_end,
      'timezone', v_period.timezone,
      'generatedAt', now(),
      'isPartial', v_period.period_end = v_today
    ),
    'revenue', jsonb_build_object(
      'grossPaidCents', v_gross_paid_cents,
      'therapistNetCents', v_therapist_net_cents,
      'paidSessionCount', v_paid_session_count,
      'grossAverageTicketCents', v_gross_average_ticket_cents,
      'netAverageTicketCents', v_net_average_ticket_cents,
      'comparison', jsonb_build_object(
        'grossPaid', public.private_therapist_finance_metric_comparison_v1(
          v_gross_paid_cents,
          v_previous_gross_paid_cents,
          v_paid_session_count > 0,
          v_previous_paid_session_count > 0
        ),
        'therapistNet', public.private_therapist_finance_metric_comparison_v1(
          v_therapist_net_cents,
          v_previous_therapist_net_cents,
          v_paid_session_count > 0,
          v_previous_paid_session_count > 0
        ),
        'paidSessions', public.private_therapist_finance_metric_comparison_v1(
          v_paid_session_count,
          v_previous_paid_session_count,
          v_paid_session_count > 0,
          v_previous_paid_session_count > 0
        ),
        'averageTicket', public.private_therapist_finance_metric_comparison_v1(
          coalesce(v_net_average_ticket_cents, 0),
          v_previous_net_average_ticket_cents,
          v_paid_session_count > 0,
          v_previous_paid_session_count > 0
        )
      )
    ),
    'sessions', jsonb_build_object(
      'completedCount', v_completed_count,
      'cancelledCount', v_cancelled_count,
      'rescheduledCount', v_rescheduled_count,
      'eligibleScheduledCount', v_eligible_scheduled_count,
      'cancellationRate', v_cancellation_rate,
      'rescheduleRate', v_reschedule_rate
    ),
    'retention', jsonb_build_object(
      'observationWindowDays', 90,
      'minimumEligiblePatients', 10,
      'eligiblePatients', v_eligible_patients,
      'returningPatients', v_returning_patients,
      'returnRate', v_return_rate,
      'status', case
        when v_eligible_patients < 10 then 'insufficient_data'
        else 'available'
      end
    ),
    'revenueByTherapy', v_revenue_by_therapy,
    'financialEvolution', v_financial_evolution
  );
end;
$$;


ALTER FUNCTION "public"."get_private_therapist_financial_metrics_v1"("p_period_start" "date", "p_period_end" "date", "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_private_therapist_financial_metrics_v1"("p_period_start" "date", "p_period_end" "date", "p_timezone" "text") IS 'Private F2 financial metrics read model for Premium and Premium Plus therapists. Uses session_payments as financial authority, derives therapist from auth.uid(), and returns deterministic aggregates only.';



CREATE OR REPLACE FUNCTION "public"."get_private_therapist_financial_opportunities_v1"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_dashboard jsonb;
begin
  v_dashboard := public.get_private_therapist_advanced_financial_dashboard_v1(
    p_period_start,
    p_period_end,
    p_timezone
  );

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', v_dashboard ->> 'therapistProfileId',
    'period', v_dashboard -> 'period',
    'opportunities', v_dashboard -> 'opportunities',
    'insights', v_dashboard -> 'insights'
  );
end;
$$;


ALTER FUNCTION "public"."get_private_therapist_financial_opportunities_v1"("p_period_start" "date", "p_period_end" "date", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_therapist_financial_overview_v1"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_period record;
  v_gross_paid_cents integer := 0;
  v_tes_commission_cents integer := 0;
  v_refunded_to_customers_cents integer := 0;
  v_therapist_net_cents integer := 0;
  v_waiting_confirmation_cents integer := 0;
  v_waiting_safety_period_cents integer := 0;
  v_eligible_for_payout_cents integer := 0;
  v_payout_processing_cents integer := 0;
  v_transferred_cents integer := 0;
  v_blocked_cents integer := 0;
  v_disputed_cents integer := 0;
begin
  v_therapist := public.get_private_therapist_financial_actor_v1();

  select *
    into v_period
  from public.normalize_private_therapist_finance_period_v1(
    p_period_start,
    p_period_end,
    p_timezone
  );

  select
    coalesce(sum(payment.gross_amount_cents), 0)::integer,
    coalesce(sum(payment.platform_gross_commission_cents), 0)::integer
    into v_gross_paid_cents, v_tes_commission_cents
  from public.session_payments as payment
  where payment.therapist_profile_id = v_therapist.id
    and payment.financial_status in (
      'paid',
      'partially_refunded',
      'refunded',
      'disputed'
    )
    and coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
    and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at;

  select coalesce(sum(refund.amount_cents), 0)::integer
    into v_refunded_to_customers_cents
  from public.session_refunds as refund
  join public.session_payments as payment
    on payment.id = refund.session_payment_id
  where payment.therapist_profile_id = v_therapist.id
    and refund.status = 'succeeded'
    and coalesce(refund.processed_at, refund.created_at) >= v_period.starts_at
    and coalesce(refund.processed_at, refund.created_at) < v_period.ends_at;

  v_therapist_net_cents :=
    v_gross_paid_cents
    - v_tes_commission_cents
    - v_refunded_to_customers_cents;

  select
    coalesce(sum(payment.therapist_amount_cents) filter (
      where payment.transfer_status = 'waiting_confirmation'
    ), 0)::integer,
    coalesce(sum(payment.therapist_amount_cents) filter (
      where payment.transfer_status = 'waiting_safety_period'
    ), 0)::integer,
    coalesce(sum(payment.therapist_amount_cents) filter (
      where payment.transfer_status = 'eligible'
    ), 0)::integer,
    coalesce(sum(payment.therapist_amount_cents) filter (
      where payment.transfer_status in ('batched', 'transfer_pending')
    ), 0)::integer,
    coalesce(sum(payment.therapist_amount_cents) filter (
      where payment.transfer_status = 'blocked'
    ), 0)::integer,
    coalesce(sum(payment.gross_amount_cents) filter (
      where payment.financial_status = 'disputed'
        or payment.disputed_at is not null
    ), 0)::integer
    into
      v_waiting_confirmation_cents,
      v_waiting_safety_period_cents,
      v_eligible_for_payout_cents,
      v_payout_processing_cents,
      v_blocked_cents,
      v_disputed_cents
  from public.session_payments as payment
  where payment.therapist_profile_id = v_therapist.id
    and coalesce(payment.eligible_at, payment.paid_at, payment.created_at)
      >= v_period.starts_at
    and coalesce(payment.eligible_at, payment.paid_at, payment.created_at)
      < v_period.ends_at;

  select coalesce(sum(transfer.amount_cents), 0)::integer
    into v_transferred_cents
  from public.stripe_transfers as transfer
  where transfer.therapist_profile_id = v_therapist.id
    and transfer.status = 'transferred'
    and coalesce(transfer.transferred_at, transfer.created_at) >= v_period.starts_at
    and coalesce(transfer.transferred_at, transfer.created_at) < v_period.ends_at;

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', v_therapist.id,
    'plan', v_therapist.plan,
    'grossPaidCents', v_gross_paid_cents,
    'tesCommissionCents', v_tes_commission_cents,
    'refundedToCustomersCents', v_refunded_to_customers_cents,
    'therapistNetCents', v_therapist_net_cents,
    'waitingConfirmationCents', v_waiting_confirmation_cents,
    'waitingSafetyPeriodCents', v_waiting_safety_period_cents,
    'eligibleForPayoutCents', v_eligible_for_payout_cents,
    'payoutProcessingCents', v_payout_processing_cents,
    'transferredCents', v_transferred_cents,
    'blockedCents', v_blocked_cents,
    'disputedCents', v_disputed_cents,
    'periodStart', v_period.period_start,
    'periodEnd', v_period.period_end,
    'timezone', v_period.timezone,
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_private_therapist_financial_overview_v1"("p_period_start" "date", "p_period_end" "date", "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_private_therapist_financial_overview_v1"("p_period_start" "date", "p_period_end" "date", "p_timezone" "text") IS 'Private therapist financial overview read model. Uses session_payments as the canonical financial source and derives the therapist from auth.uid().';



CREATE OR REPLACE FUNCTION "public"."get_private_therapist_financial_overview_v2"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_base jsonb;
  v_therapist public.therapist_profiles%rowtype;
  v_period record;
  v_received integer := 0;
  v_processing integer := 0;
  v_waiting_settlement integer := 0;
begin
  v_therapist := public.get_private_therapist_financial_actor_v1();
  select * into v_period from public.normalize_private_therapist_finance_period_v1(
    p_period_start, p_period_end, p_timezone
  );
  v_base := public.get_private_therapist_financial_overview_v1(
    p_period_start, p_period_end, p_timezone
  );

  select coalesce(sum(transfer.amount_cents), 0)::integer into v_received
  from public.stripe_transfers transfer
  join public.stripe_payout_transfer_allocations allocation on allocation.stripe_transfer_id = transfer.id
  join public.stripe_payouts payout on payout.id = allocation.stripe_payout_id
  where transfer.therapist_profile_id = v_therapist.id
    and transfer.status = 'transferred'
    and payout.status = 'paid'
    and payout.provider_reconciliation_status = 'completed'
    and payout.allocation_status = 'completed'
    and allocation.amount_cents = transfer.amount_cents
    and coalesce(payout.paid_at, payout.updated_at) >= v_period.starts_at
    and coalesce(payout.paid_at, payout.updated_at) < v_period.ends_at;

  select
    coalesce(sum(payment.therapist_amount_cents) filter (
      where public.private_therapist_receipt_status_v2(payment.id) in (
        'receivable', 'waiting_confirmation', 'waiting_safety_period',
        'waiting_settlement', 'eligible', 'payout_processing', 'bank_pending'
      )
    ), 0)::integer,
    coalesce(sum(payment.therapist_amount_cents) filter (
      where payment.transfer_status = 'waiting_settlement'
    ), 0)::integer
  into v_processing, v_waiting_settlement
  from public.session_payments payment
  join public.bookings booking on booking.id = payment.booking_id
  where payment.therapist_profile_id = v_therapist.id
    and booking.starts_at >= v_period.starts_at
    and booking.starts_at < v_period.ends_at;

  return v_base || jsonb_build_object(
    'contractVersion', 2,
    'receivedCents', v_received,
    'processingCents', v_processing,
    'waitingSettlementCents', v_waiting_settlement
  );
end;
$$;


ALTER FUNCTION "public"."get_private_therapist_financial_overview_v2"("p_period_start" "date", "p_period_end" "date", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_therapist_payouts_v1"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_period record;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := least(greatest(coalesce(p_page_size, 20), 1), 100);
  v_offset integer;
  v_total_count integer := 0;
  v_items jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  if p_status is not null and p_status not in (
    'waiting_confirmation', 'waiting_safety_period', 'eligible', 'batched',
    'transfer_pending', 'transferred', 'blocked', 'failed', 'reversed'
  ) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  v_therapist := public.get_private_therapist_financial_actor_v1();
  v_offset := (v_page - 1) * v_page_size;
  select * into v_period
  from public.normalize_private_therapist_finance_period_v1(
    p_period_start, p_period_end, p_timezone
  );

  with batch_rows as (
    select
      batch.id as payout_batch_id,
      batch.reference_period_start as period_start,
      batch.reference_period_end as period_end,
      batch.cutoff_at as expected_transfer_at,
      max(transfer.transferred_at) as transferred_at,
      max(transfer.updated_at) as reconciliation_updated_at,
      max(transfer.stripe_transfer_id) as stripe_transfer_id,
      max(transfer.stripe_source_charge_id) as stripe_source_charge_id,
      coalesce(sum(payment.gross_amount_cents), 0)::integer as gross_amount_cents,
      coalesce(sum(payment.platform_gross_commission_cents), 0)::integer as tes_commission_cents,
      coalesce(sum(public.private_therapist_finance_refunded_cents_v1(payment.id)), 0)::integer as refunded_amount_cents,
      coalesce(sum(item.amount_cents), 0)::integer as therapist_net_amount_cents,
      count(distinct item.session_payment_id)::integer as session_count,
      case
        when bool_or(transfer.status = 'reversed' or payment.transfer_status = 'reversed') then 'reversed'
        when bool_or(transfer.status = 'failed' or item.status = 'failed' or payment.transfer_status = 'failed') then 'failed'
        when bool_or(item.status = 'blocked' or payment.transfer_status = 'blocked') then 'blocked'
        when bool_and(item.status = 'transferred') or batch.status = 'completed' then 'transferred'
        when bool_or(item.status = 'transfer_pending' or transfer.status = 'pending') or batch.status = 'processing' then 'transfer_pending'
        else 'batched'
      end as transfer_status,
      case
        when bool_or(transfer.status = 'failed' or item.status = 'failed' or payment.transfer_status = 'failed') then 'failed'
        when bool_or(transfer.status = 'reversed' or payment.transfer_status = 'reversed') then 'reversed'
        when bool_and(transfer.stripe_transfer_id is not null and transfer.stripe_source_charge_id is not null and item.status = 'transferred') then 'matched'
        when bool_or(item.status in ('reserved', 'transfer_pending') or payment.transfer_status in ('batched', 'transfer_pending')) then 'pending'
        else 'needs_reconciliation'
      end as reconciliation_status,
      max(item.failure_code) filter (where item.status = 'blocked' or payment.transfer_status = 'blocked') as blocked_reason,
      max(item.failure_code) filter (where item.status = 'failed' or transfer.status = 'failed' or payment.transfer_status = 'failed') as failed_reason
    from public.payout_batch_items item
    join public.payout_batches batch on batch.id = item.payout_batch_id
    join public.session_payments payment on payment.id = item.session_payment_id
    left join public.stripe_transfers transfer on transfer.payout_batch_item_id = item.id
    where item.therapist_profile_id = v_therapist.id
      and batch.reference_period_start >= v_period.period_start
      and batch.reference_period_start <= v_period.period_end
      and item.status <> 'removed'
    group by batch.id, batch.reference_period_start, batch.reference_period_end, batch.cutoff_at, batch.status
  ), filtered as (
    select * from batch_rows where p_status is null or transfer_status = p_status
  ), counted as (
    select count(*)::integer as count from filtered
  ), paged as (
    select * from filtered order by period_start desc, payout_batch_id desc limit v_page_size offset v_offset
  )
  select counted.count, coalesce(jsonb_agg(jsonb_build_object(
    'payoutBatchId', paged.payout_batch_id, 'periodStart', paged.period_start,
    'periodEnd', paged.period_end, 'grossAmountCents', paged.gross_amount_cents,
    'tesCommissionCents', paged.tes_commission_cents, 'refundedAmountCents', paged.refunded_amount_cents,
    'therapistNetAmountCents', paged.therapist_net_amount_cents, 'transferStatus', paged.transfer_status,
    'expectedTransferAt', paged.expected_transfer_at, 'transferredAt', paged.transferred_at,
    'blockedReason', paged.blocked_reason, 'failedReason', paged.failed_reason,
    'sessionCount', paged.session_count, 'stripeTransferId', paged.stripe_transfer_id,
    'stripeSourceChargeId', paged.stripe_source_charge_id, 'reconciliationStatus', paged.reconciliation_status,
    'reconciliationUpdatedAt', paged.reconciliation_updated_at
  ) order by paged.period_start desc, paged.payout_batch_id desc) filter (where paged.payout_batch_id is not null), '[]'::jsonb)
  into v_total_count, v_items
  from counted left join paged on true group by counted.count;

  select jsonb_build_object(
    'eligibleForPayoutCents', coalesce(sum(payment.therapist_amount_cents) filter (where payment.transfer_status = 'eligible'), 0)::integer,
    'waitingConfirmationCents', coalesce(sum(payment.therapist_amount_cents) filter (where payment.transfer_status = 'waiting_confirmation'), 0)::integer,
    'waitingSafetyPeriodCents', coalesce(sum(payment.therapist_amount_cents) filter (where payment.transfer_status = 'waiting_safety_period'), 0)::integer,
    'payoutProcessingCents', coalesce(sum(payment.therapist_amount_cents) filter (where payment.transfer_status in ('batched', 'transfer_pending')), 0)::integer,
    'blockedCents', coalesce(sum(payment.therapist_amount_cents) filter (where payment.transfer_status = 'blocked'), 0)::integer,
    'blockedReasonCodes', coalesce((select jsonb_agg(distinct case
      when blocked.transfer_blocked_reason = 'connect_not_ready' then 'account'
      when blocked.transfer_blocked_reason in ('refund', 'manual_refund_review') then 'refund'
      when blocked.transfer_blocked_reason in ('disputed', 'blocked_or_contested', 'participant_reported_not_performed') then 'review'
      else 'other' end)
      from public.session_payments blocked
      where blocked.therapist_profile_id = v_therapist.id
        and blocked.transfer_status = 'blocked'
        and coalesce(blocked.eligible_at, blocked.paid_at, blocked.created_at) >= v_period.starts_at
        and coalesce(blocked.eligible_at, blocked.paid_at, blocked.created_at) < v_period.ends_at), '[]'::jsonb),
    'nextBatchAt', case when exists (
      select 1 from public.session_payments eligible
      join public.therapist_connect_accounts account
        on account.therapist_profile_id = eligible.therapist_profile_id
       and account.is_current = true
       and account.stripe_transfers_status = 'active'
       and account.payouts_enabled = true
       and account.payout_status = 'enabled'
       and account.payout_schedule_interval = 'daily'
       and account.operational_status = 'ready'
      where eligible.therapist_profile_id = v_therapist.id
        and eligible.transfer_status = 'eligible'
        and eligible.therapist_amount_cents > 0
    ) then public.next_weekly_payout_cutoff_v1(now(), now()) else null end
  ) into v_summary
  from public.session_payments payment
  where payment.therapist_profile_id = v_therapist.id
    and coalesce(payment.eligible_at, payment.paid_at, payment.created_at) >= v_period.starts_at
    and coalesce(payment.eligible_at, payment.paid_at, payment.created_at) < v_period.ends_at;

  return jsonb_build_object(
    'contractVersion', 1, 'therapistProfileId', v_therapist.id, 'items', v_items,
    'pagination', jsonb_build_object('page', v_page, 'pageSize', v_page_size, 'totalCount', v_total_count,
      'totalPages', case when v_total_count = 0 then 0 else ceil(v_total_count::numeric / v_page_size)::integer end,
      'hasNextPage', v_offset + v_page_size < v_total_count),
    'filters', jsonb_build_object('status', p_status, 'periodStart', v_period.period_start,
      'periodEnd', v_period.period_end, 'timezone', v_period.timezone),
    'summary', v_summary, 'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_private_therapist_payouts_v1"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_private_therapist_payouts_v1"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") IS 'Read model privado de repasses do terapeuta, incluindo status de conciliacao de transferencias Connect.';



CREATE OR REPLACE FUNCTION "public"."get_private_therapist_payouts_v2"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payload jsonb;
  v_summary jsonb;
  v_therapist public.therapist_profiles%rowtype;
  v_processing_cents integer := 0;
begin
  -- This call retains authorization, filter validation, deterministic
  -- pagination and the complete unified history contract.
  v_payload := public.private_therapist_payouts_v2_v10_gross_processing_legacy(
    p_period_start,
    p_period_end,
    p_status,
    p_page,
    p_page_size,
    p_timezone
  );
  v_therapist := public.get_private_therapist_financial_actor_v1();

  select coalesce(sum(
    case
      when payment.payment_flow_version = 'v10'
        then coalesce(job.transfer_amount_cents, payment.therapist_amount_cents)
      else payment.therapist_amount_cents
    end
  ), 0)::integer
  into v_processing_cents
  from public.session_payments payment
  left join public.session_transfer_jobs job
    on job.session_payment_id = payment.id
  where payment.therapist_profile_id = v_therapist.id
    and public.private_therapist_receipt_status_v2(payment.id) in (
      'waiting_confirmation',
      'waiting_safety_period',
      'waiting_settlement',
      'eligible',
      'payout_processing',
      'bank_pending'
    );

  v_summary := coalesce(v_payload -> 'summary', '{}'::jsonb)
    || jsonb_build_object('payoutProcessingCents', v_processing_cents);

  return jsonb_set(v_payload, '{summary}', v_summary, true);
end;
$$;


