COMMENT ON FUNCTION "public"."get_public_therapist_next_slot_v1"("p_therapist_profile_id" "uuid") IS 'Returns the first currently bookable slot across every eligible online service for a public therapist.';



CREATE OR REPLACE FUNCTION "public"."get_public_therapy_theme_names_v1"("p_therapy_id" "uuid") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    array_agg(distinct themes.name order by themes.name),
    '{}'::text[]
  )
  from public.therapies as therapies
  join public.therapy_theme_weights as weights
    on weights.therapy_id = therapies.id
  join public.therapy_themes as themes
    on themes.id = coalesce(weights.theme_id, weights.subtheme_id)
  where therapies.id = p_therapy_id
    and therapies.status = 'published'::public.therapy_status
    and therapies.is_public_visible = true
    and therapies.archived_at is null
    and weights.is_active = true
    and themes.is_active = true;
$$;


ALTER FUNCTION "public"."get_public_therapy_theme_names_v1"("p_therapy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_therapy_therapists_v1"("p_therapy_slug" "text", "p_theme_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_interest_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_limit" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapy_id uuid;
  v_relevant_theme_ids uuid[];
  v_relevant_interest_ids uuid[];
begin
  select therapy.id into v_therapy_id
  from public.therapies therapy
  where therapy.slug = p_therapy_slug
    and therapy.status = 'published'
    and therapy.is_public_visible
    and public.therapy_has_active_matching_theme_v1(therapy.id);

  if v_therapy_id is null then
    raise exception 'NOT_FOUND';
  end if;

  select coalesce(array_agg(distinct link.theme_id), '{}'::uuid[])
    into v_relevant_theme_ids
  from public.therapy_matching_themes link
  join public.matching_themes theme
    on theme.id = link.theme_id
   and theme.is_active
  where link.therapy_id = v_therapy_id
    and link.theme_id = any(coalesce(p_theme_ids, '{}'::uuid[]));

  select coalesce(array_agg(distinct interest.id), '{}'::uuid[])
    into v_relevant_interest_ids
  from public.matching_interests interest
  where interest.id = any(coalesce(p_interest_ids, '{}'::uuid[]))
    and interest.theme_id = any(v_relevant_theme_ids)
    and interest.is_active;

  return coalesce((
    with eligible_services as (
      select
        profile.id as therapist_profile_id,
        profile.slug,
        profile.public_name,
        profile.headline as therapist_headline,
        profile.photo_url,
        profile.plan,
        service.id as service_id,
        service.title as service_title,
        service.description as service_description,
        service.position,
        service.price_cents,
        coalesce(tags.items, array[therapy.name]) as tags,
        coalesce(interest_matches.matching_interest_count, 0)::integer as matching_interest_count,
        coalesce(theme_matches.matching_service_theme_count, 0)::integer as matching_service_theme_count,
        review_summary.average_rating,
        coalesce(review_summary.review_count, 0)::integer as review_count,
        coalesce(session_summary.completed_session_count, 0)::integer as completed_session_count,
        next_slot.next_slot_at
      from public.therapist_services service
      join public.therapist_profiles profile
        on profile.id = service.therapist_profile_id
      join public.therapies therapy
        on therapy.id = service.therapy_id
      left join lateral (
        select array_agg(tag.value order by tag.value) as items
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(profile.metadata->'care_tags') = 'array'
              then profile.metadata->'care_tags'
            else '[]'::jsonb
          end
        ) tag(value)
      ) tags on true
      left join lateral (
        select count(distinct service_interest.interest_id)::integer as matching_interest_count
        from public.therapist_service_matching_interests service_interest
        where service_interest.therapist_service_id = service.id
          and service_interest.interest_id = any(v_relevant_interest_ids)
      ) interest_matches on true
      left join lateral (
        select count(distinct service_theme.theme_id)::integer as matching_service_theme_count
        from public.therapist_service_matching_themes service_theme
        where service_theme.therapist_service_id = service.id
          and service_theme.theme_id = any(v_relevant_theme_ids)
      ) theme_matches on true
      left join lateral (
        select
          round(avg(review.rating)::numeric, 1) as average_rating,
          count(*)::integer as review_count
        from public.public_therapist_profile_reviews_v_internal review
        where review.therapist_slug = profile.slug
      ) review_summary on true
      left join lateral (
        select count(*)::integer as completed_session_count
        from public.bookings booking
        where booking.therapist_profile_id = profile.id
          and booking.status = 'completed'
          and booking.payment_status = 'paid'
      ) session_summary on true
      left join lateral (
        select min((slot.value->>'startsAt')::timestamptz) as next_slot_at
        from jsonb_array_elements(
          coalesce(
            public.get_service_available_slots_v1(
              service.id,
              now(),
              now() + interval '31 days',
              1
            )->'slots',
            '[]'::jsonb
          )
        ) slot(value)
      ) next_slot on true
      where service.therapy_id = v_therapy_id
        and service.archived_at is null
        and service.status = 'active'
        and service.is_bookable
        and service.online_only
        and therapy.status = 'published'
        and therapy.is_public_visible
        and public.therapy_has_active_matching_theme_v1(therapy.id)
        and public.is_public_service_booking_eligible_v1(service.id)
        and public.is_therapist_publication_eligible_v1(profile.id)
    ), selected_service as (
      select
        eligible_services.*,
        row_number() over (
          partition by therapist_profile_id
          order by
            matching_interest_count desc,
            matching_service_theme_count desc,
            position asc nulls last,
            price_cents,
            service_title,
            service_id
        ) as service_rank
      from eligible_services
    ), ranked as (
      select *
      from selected_service
      where service_rank = 1
      order by
        case when cardinality(v_relevant_interest_ids) > 0 then matching_interest_count else 0 end desc,
        matching_service_theme_count desc,
        case when cardinality(v_relevant_theme_ids) > 0 then
          case plan when 'premium_plus' then 2 when 'premium' then 1 else 0 end
        else 0 end desc,
        next_slot_at asc nulls last,
        average_rating desc nulls last,
        review_count desc,
        slug
      limit least(greatest(coalesce(p_limit, 6), 1), 24)
    )
    select jsonb_agg(
      jsonb_build_object(
        'slug', slug,
        'public_name', public_name,
        'photo_url', photo_url,
        'therapist_headline', therapist_headline,
        'service_description', service_description,
        'tags', tags,
        'average_rating', average_rating,
        'review_count', review_count,
        'completed_session_count', completed_session_count,
        'next_slot_at', next_slot_at,
        'service_id', service_id,
        'matching_interest_count', matching_interest_count,
        'matching_service_theme_count', matching_service_theme_count
      )
      order by
        case when cardinality(v_relevant_interest_ids) > 0 then matching_interest_count else 0 end desc,
        matching_service_theme_count desc,
        case when cardinality(v_relevant_theme_ids) > 0 then
          case plan when 'premium_plus' then 2 when 'premium' then 1 else 0 end
        else 0 end desc,
        next_slot_at asc nulls last,
        average_rating desc nulls last,
        review_count desc,
        slug
    )
    from ranked
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_public_therapy_therapists_v1"("p_therapy_slug" "text", "p_theme_ids" "uuid"[], "p_interest_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_service_available_day_slots_v1"("p_service_id" "uuid", "p_day" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
begin
  if p_day is null or not public.is_public_service_booking_eligible_v1(p_service_id) then
    return null;
  end if;

  select schedule.timezone
    into v_timezone
  from public.therapist_services as service
  join public.therapist_schedule_settings as schedule
    on schedule.therapist_profile_id = service.therapist_profile_id
  where service.id = p_service_id;

  return public.get_service_available_slots_v1(
    p_service_id,
    p_day::timestamp at time zone v_timezone,
    (p_day + interval '1 day')::timestamp at time zone v_timezone,
    500
  );
end;
$$;


ALTER FUNCTION "public"."get_service_available_day_slots_v1"("p_service_id" "uuid", "p_day" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_service_available_day_slots_v1"("p_service_id" "uuid", "p_day" "date") IS 'Public day-detail availability. Returns the authoritative slots for one local calendar day.';



CREATE OR REPLACE FUNCTION "public"."get_service_available_days_v1"("p_service_id" "uuid", "p_month" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_horizon_ends_at timestamptz;
  v_month date;
  v_month_end timestamptz;
  v_month_start timestamptz;
  v_range_end timestamptz;
  v_range_start timestamptz;
  v_timezone text;
begin
  if not public.is_public_service_booking_eligible_v1(p_service_id) then
    return null;
  end if;

  select
    schedule.timezone,
    now() + coalesce(settings.max_days_ahead, 90) * interval '1 day'
  into v_timezone, v_horizon_ends_at
  from public.therapist_services as service
  join public.therapist_schedule_settings as schedule
    on schedule.therapist_profile_id = service.therapist_profile_id
  left join public.therapist_service_booking_settings as settings
    on settings.service_id = service.id
  where service.id = p_service_id;

  v_month := date_trunc(
    'month',
    coalesce(p_month, now() at time zone v_timezone)::date
  )::date;
  v_month_start := v_month::timestamp at time zone v_timezone;
  v_month_end := (v_month + interval '1 month')::timestamp at time zone v_timezone;
  v_range_start := greatest(v_month_start, now());
  v_range_end := least(v_month_end, v_horizon_ends_at);

  return jsonb_build_object(
    'contractVersion', 1,
    'timezone', v_timezone,
    'horizonEndsAt', v_horizon_ends_at,
    'month', to_char(v_month, 'YYYY-MM'),
    'days', case
      when v_range_start >= v_range_end then '[]'::jsonb
      else (
        select coalesce(
          jsonb_agg(
            jsonb_build_object(
              'date',
              to_char(local_day.day::date, 'YYYY-MM-DD')
            )
            order by local_day.day
          ),
          '[]'::jsonb
        )
        from generate_series(
          (v_range_start at time zone v_timezone)::date,
          ((v_range_end - interval '1 microsecond') at time zone v_timezone)::date,
          interval '1 day'
        ) as local_day(day)
        where jsonb_array_length(
          coalesce(
            public.get_service_available_slots_v1(
              p_service_id,
              local_day.day::timestamp at time zone v_timezone,
              (local_day.day + interval '1 day')::timestamp at time zone v_timezone,
              500
            ) -> 'slots',
            '[]'::jsonb
          )
        ) > 0
      )
    end
  );
end;
$$;


ALTER FUNCTION "public"."get_service_available_days_v1"("p_service_id" "uuid", "p_month" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_service_available_days_v1"("p_service_id" "uuid", "p_month" "date") IS 'Public calendar-month availability. Returns only local dates that have at least one currently free authoritative slot, plus timezone and horizonEndsAt.';



CREATE OR REPLACE FUNCTION "public"."get_service_available_slots_v1"("p_service_id" "uuid", "p_range_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_range_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_horizon_ends_at timestamptz;
  v_result jsonb;
begin
  if not public.is_public_service_booking_eligible_v1(p_service_id) then
    return null;
  end if;

  select now() + coalesce(settings.max_days_ahead, 90) * interval '1 day'
    into v_horizon_ends_at
  from public.therapist_services as service
  left join public.therapist_service_booking_settings as settings
    on settings.service_id = service.id
  where service.id = p_service_id;

  v_result := public.get_service_available_slots_v1_internal(
    p_service_id,
    p_range_start,
    p_range_end,
    p_limit
  );

  if v_result is null then
    return null;
  end if;

  return jsonb_set(
    v_result,
    '{horizonEndsAt}',
    to_jsonb(v_horizon_ends_at),
    true
  );
end;
$$;


ALTER FUNCTION "public"."get_service_available_slots_v1"("p_service_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_service_available_slots_v1_internal"("p_service_id" "uuid", "p_range_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_range_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_now timestamptz := now();
  v_range_end timestamptz := coalesce(
    p_range_end,
    now() + interval '30 days'
  );
  v_range_start timestamptz := coalesce(p_range_start, now());
  v_service record;
begin
  if v_range_start >= v_range_end
    or v_range_end - v_range_start > interval '31 days'
    or p_limit not between 1 and 500
  then
    raise exception 'invalid_slot_range' using errcode = '22023';
  end if;

  select
    service.id,
    service.duration_minutes,
    service.title,
    therapy.calendar_color_key,
    therapy.id as therapy_id,
    therapy.name as therapy_name,
    schedule_settings.timezone,
    service.therapist_profile_id
  into v_service
  from public.therapist_services as service
  join public.therapies as therapy
    on therapy.id = service.therapy_id
  join public.therapist_profiles as therapist
    on therapist.id = service.therapist_profile_id
  join public.therapist_schedule_settings as schedule_settings
    on schedule_settings.therapist_profile_id = therapist.id
  where service.id = p_service_id
    and service.status = 'active'
    and therapy.status = 'published'
    and therapist.status = 'approved'
    and therapist.is_public
    and therapist.is_accepting_bookings;

  if not found then
    return null;
  end if;

  return jsonb_build_object(
    'contractVersion', 1,
    'service', jsonb_build_object(
      'id', v_service.id,
      'title', v_service.title,
      'durationMinutes', v_service.duration_minutes,
      'therapyId', v_service.therapy_id,
      'therapyName', v_service.therapy_name,
      'colorKey', v_service.calendar_color_key
    ),
    'timezone', v_service.timezone,
    'range', jsonb_build_object(
      'start', v_range_start,
      'end', v_range_end,
      'endExclusive', true
    ),
    'slots', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'startsAt', candidate.starts_at,
            'endsAt', candidate.ends_at
          )
          order by candidate.starts_at
        ),
        '[]'::jsonb
      )
      from public.list_service_schedule_candidates_v1(
        p_service_id,
        v_range_start,
        v_range_end,
        v_now,
        p_limit
      ) as candidate
      where not exists (
        select 1
        from public.bookings as booking
        where booking.therapist_profile_id =
          v_service.therapist_profile_id
          and booking.status in ('draft', 'pending_payment', 'confirmed')
          and booking.occupied_during && candidate.occupied_during
      )
      and not exists (
        select 1
        from public.booking_holds as hold
        where hold.therapist_profile_id =
          v_service.therapist_profile_id
          and hold.status = 'active'
          and hold.expires_at > v_now
          and hold.occupied_during && candidate.occupied_during
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_service_available_slots_v1_internal"("p_service_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_service_available_slots_v1_internal"("p_service_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_limit" integer) IS 'A5 public safe slot endpoint. Composes schedule rules, active exceptions, service settings, bookings and live holds without exposing participant data.';



CREATE OR REPLACE FUNCTION "public"."get_session_feedback_v1"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role public.user_role;
  v_feedback public.session_feedback;
  v_attendance jsonb;
  v_payment_status text;
  v_status text;
  v_reason text;
begin
  if v_actor_id is null then
    raise exception 'FEEDBACK_AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  if p_booking_id is null then
    raise exception 'FEEDBACK_BOOKING_REQUIRED' using errcode = '22023';
  end if;

  select case
    when patient_profiles.user_id = v_actor_id then 'patient'::public.user_role
    when therapist_profiles.user_id = v_actor_id then 'therapist'::public.user_role
    else null
  end
  into v_actor_role
  from public.bookings
  left join public.patient_profiles
    on patient_profiles.id = bookings.patient_profile_id
  left join public.therapist_profiles
    on therapist_profiles.id = bookings.therapist_profile_id
  where bookings.id = p_booking_id;

  if v_actor_role is null then
    raise exception 'FEEDBACK_PARTICIPANT_REQUIRED' using errcode = '42501';
  end if;

  select payment.financial_status::text
  into v_payment_status
  from public.session_payments payment
  where payment.booking_id = p_booking_id;

  v_attendance := public.session_attendance_state_v1(p_booking_id, now());

  select feedback.*
  into v_feedback
  from public.session_feedback feedback
  where feedback.booking_id = p_booking_id
    and feedback.author_role = v_actor_role
  limit 1;

  if v_feedback.id is not null then
    v_status := 'submitted';
    v_reason := 'submitted';
  elsif v_payment_status is distinct from 'paid'
    and v_payment_status is distinct from 'partially_refunded' then
    v_status := 'unavailable';
    v_reason := 'payment_pending';
  elsif coalesce((v_attendance ->> 'sessionClosed')::boolean, false) = false
    and coalesce((v_attendance ->> 'bothJoined')::boolean, false) = false then
    v_status := case
      when now() < coalesce((v_attendance ->> 'sessionStartedAt')::timestamptz, now())
        then 'before_session'
      else 'waiting_for_participants'
    end;
    v_reason := 'both_participants_required';
  elsif coalesce((v_attendance ->> 'sessionClosed')::boolean, false) = false then
    v_status := 'attendance_pending';
    v_reason := 'session_not_closed';
  elsif coalesce((v_attendance ->> 'bothJoined')::boolean, false) = false then
    v_status := 'incident_only';
    v_reason := 'attendance_incomplete';
  else
    v_status := 'eligible';
    v_reason := 'both_participants_joined';
  end if;

  return jsonb_build_object(
    'attendance', v_attendance,
    'confirmation', public.session_feedback_confirmation_payload(p_booking_id, v_actor_role),
    'feedback', case
      when v_feedback.id is null then null
      else public.session_feedback_payload(v_feedback)
    end,
    'reason', v_reason,
    'status', v_status
  );
end;
$$;


ALTER FUNCTION "public"."get_session_feedback_v1"("p_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_session_feedback_v1"("p_booking_id" "uuid") IS 'Returns only the authenticated participant feedback for a booking; identity is derived from auth.uid().';



CREATE OR REPLACE FUNCTION "public"."get_session_feedback_v2"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payload jsonb;
  v_payment public.session_payments%rowtype;
  v_state text;
begin
  -- The legacy reader authorizes the actor before any V10 projection runs.
  v_payload := public.private_session_feedback_v2_v9_legacy(p_booking_id);

  select payment.* into v_payment
  from public.session_payments payment
  where payment.booking_id = p_booking_id;

  if v_payment.payment_flow_version <> 'v10' then
    return v_payload;
  end if;

  v_state := case
    when v_payment.internal_contested_at is not null
      or v_payment.admin_blocked_at is not null
      or exists (
        select 1 from public.session_confirmation_incidents incident
        where incident.booking_id = p_booking_id and incident.status = 'open'
      ) then 'blocked_for_review'
    when v_payload -> 'actorConfirmation' = 'null'::jsonb
      and v_payload -> 'counterpartConfirmation' = 'null'::jsonb
      then 'awaiting_both'
    when v_payload -> 'actorConfirmation' = 'null'::jsonb
      then case when v_payload ->> 'actorRole' = 'patient'
        then 'awaiting_patient' else 'awaiting_therapist' end
    when v_payload -> 'counterpartConfirmation' = 'null'::jsonb
      then case when v_payload ->> 'actorRole' = 'patient'
        then 'awaiting_therapist' else 'awaiting_patient' end
    else 'completed'
  end;

  v_payload := jsonb_set(v_payload, '{confirmationState}', to_jsonb(v_state), true);
  return jsonb_set(v_payload, '{financial,nextBatchAt}', 'null'::jsonb, true);
end;
$$;


ALTER FUNCTION "public"."get_session_feedback_v2"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_therapist_agenda_v1"("p_range_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_range_end" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_range_start timestamptz := coalesce(
    p_range_start,
    now() - interval '7 days'
  );
  v_range_end timestamptz := coalesce(
    p_range_end,
    now() + interval '35 days'
  );
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = (select auth.uid())
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  if v_range_start >= v_range_end then
    raise exception 'invalid_agenda_range' using errcode = '22023';
  end if;

  if v_range_end - v_range_start > interval '93 days' then
    raise exception 'agenda_range_too_large' using errcode = '22023';
  end if;

  v_timezone := coalesce(
    nullif(v_therapist.metadata ->> 'timezone', ''),
    'America/Sao_Paulo'
  );

  return jsonb_build_object(
    'version', 1,
    'therapistProfileId', v_therapist.id,
    'timezone', v_timezone,
    'range', jsonb_build_object(
      'start', v_range_start,
      'end', v_range_end,
      'endExclusive', true
    ),
    'summary', jsonb_build_object(
      'bookings', (
        select count(*)
        from public.therapist_session_read_model_v1 as session_row
        where session_row."_therapistProfileId" = v_therapist.id
          and session_row."startsAt" < v_range_end
          and session_row."endsAt" > v_range_start
      ),
      'activeHolds', (
        select count(*)
        from public.booking_holds as hold
        where hold.therapist_profile_id = v_therapist.id
          and hold.status = 'active'
          and hold.expires_at > now()
          and hold.starts_at < v_range_end
          and hold.ends_at > v_range_start
      ),
      'pendingReschedules', (
        select count(*)
        from public.booking_reschedule_requests as request
        join public.bookings as booking
          on booking.id = request.booking_id
        where booking.therapist_profile_id = v_therapist.id
          and request.status = 'pending'
      )
    ),
    'bookings', (
      select coalesce(
        jsonb_agg(
          (
            to_jsonb(session_row)
            - '_therapistProfileId'
            - '_videoSessionReady'
          ) || jsonb_build_object(
            'zoomAccess',
            public.build_video_session_access_state_v1(
              session_row."bookingStatus",
              session_row."financialStatus",
              session_row."startsAt",
              session_row."endsAt",
              session_row."videoSessionStatus",
              session_row."_videoSessionReady",
              now()
            )
          )
          order by session_row."startsAt", session_row."bookingId"
        ),
        '[]'::jsonb
      )
      from public.therapist_session_read_model_v1 as session_row
      where session_row."_therapistProfileId" = v_therapist.id
        and session_row."startsAt" < v_range_end
        and session_row."endsAt" > v_range_start
    ),
    'holds', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', hold.id,
            'serviceId', hold.service_id,
            'serviceTitle', hold.service_title_snapshot,
            'startsAt', hold.starts_at,
            'endsAt', hold.ends_at,
            'timezone', hold.timezone,
            'status', hold.status,
            'expiresAt', hold.expires_at
          )
          order by hold.starts_at
        ),
        '[]'::jsonb
      )
      from public.booking_holds as hold
      where hold.therapist_profile_id = v_therapist.id
        and hold.status = 'active'
        and hold.expires_at > now()
        and hold.starts_at < v_range_end
        and hold.ends_at > v_range_start
    ),
    'availability', jsonb_build_object(
      'rules', (
        select coalesce(
          jsonb_agg(
            jsonb_build_object(
              'id', rule.id,
              'serviceId', rule.service_id,
              'dayOfWeek', rule.day_of_week,
              'startTime', rule.start_time,
              'endTime', rule.end_time,
              'timezone', rule.timezone,
              'isActive', rule.is_active
            )
            order by rule.day_of_week, rule.start_time
          ),
          '[]'::jsonb
        )
        from public.availability_rules as rule
        where rule.therapist_profile_id = v_therapist.id
      ),
      'exceptions', (
        select coalesce(
          jsonb_agg(
            jsonb_build_object(
              'id', exception.id,
              'serviceId', exception.service_id,
              'startsAt', exception.starts_at,
              'endsAt', exception.ends_at,
              'isAvailable', exception.is_available
            )
            order by exception.starts_at
          ),
          '[]'::jsonb
        )
        from public.availability_exceptions as exception
        where exception.therapist_profile_id = v_therapist.id
          and exception.starts_at < v_range_end
          and exception.ends_at > v_range_start
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_agenda_v1"("p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_agenda_v1"("p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone) IS 'Timezone-aware Agenda read model over a semi-open instant range [start,end), including bookings, active holds, rules and exceptions.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_aura_signals_v1"("p_period_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_current_local_end date;
  v_current_local_start date;
  v_previous_local_start date;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_previous_start timestamptz;
  v_next_start timestamptz;
  v_next_end timestamptz;
  v_current_completed bigint := 0;
  v_previous_completed bigint := 0;
  v_current_cancelled bigint := 0;
  v_previous_cancelled bigint := 0;
  v_current_no_shows bigint := 0;
  v_previous_no_shows bigint := 0;
  v_current_presence_sample bigint := 0;
  v_previous_presence_sample bigint := 0;
  v_current_people bigint := 0;
  v_previous_people bigint := 0;
  v_current_returned bigint := 0;
  v_previous_returned bigint := 0;
  v_pending_reviews bigint := 0;
  v_public_bookable_services bigint := 0;
  v_services_with_slots bigint := 0;
  v_active_recommendations jsonb := '[]'::jsonb;
  v_dismissals jsonb := '[]'::jsonb;
begin
  if p_period_days not in (30, 90) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select therapist.*
    into v_therapist
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = '42501';
  end if;

  if v_therapist.plan <> 'premium_plus'::public.therapist_plan then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  v_timezone := coalesce(v_timezone, 'America/Sao_Paulo');

  v_current_local_end := (now() at time zone v_timezone)::date;
  v_current_local_start := v_current_local_end - p_period_days;
  v_previous_local_start := v_current_local_start - p_period_days;
  v_current_start := v_current_local_start::timestamp at time zone v_timezone;
  v_current_end := v_current_local_end::timestamp at time zone v_timezone;
  v_previous_start := v_previous_local_start::timestamp at time zone v_timezone;
  v_next_start := now();
  v_next_end := now() + interval '14 days';

  select
    count(*) filter (
      where booking.starts_at >= v_current_start
        and booking.status = 'completed'
    ),
    count(*) filter (
      where booking.starts_at < v_current_start
        and booking.status = 'completed'
    ),
    count(*) filter (
      where booking.starts_at >= v_current_start
        and booking.status in (
          'cancelled_by_patient',
          'cancelled_by_therapist'
        )
    ),
    count(*) filter (
      where booking.starts_at < v_current_start
        and booking.status in (
          'cancelled_by_patient',
          'cancelled_by_therapist'
        )
    ),
    count(*) filter (
      where booking.starts_at >= v_current_start
        and booking.status in ('no_show_patient', 'no_show_therapist')
    ),
    count(*) filter (
      where booking.starts_at < v_current_start
        and booking.status in ('no_show_patient', 'no_show_therapist')
    )
    into
      v_current_completed,
      v_previous_completed,
      v_current_cancelled,
      v_previous_cancelled,
      v_current_no_shows,
      v_previous_no_shows
  from public.bookings as booking
  where booking.therapist_profile_id = v_therapist.id
    and booking.starts_at >= v_previous_start
    and booking.starts_at < v_current_end;

  v_current_presence_sample := v_current_completed + v_current_no_shows;
  v_previous_presence_sample := v_previous_completed + v_previous_no_shows;

  with completed as (
    select booking.patient_profile_id, booking.starts_at
    from public.bookings as booking
    where booking.therapist_profile_id = v_therapist.id
      and booking.status = 'completed'
      and booking.starts_at < v_current_end
  )
  select
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_current_start
    ),
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_previous_start
        and completed.starts_at < v_current_start
    ),
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_current_start
        and exists (
          select 1
          from completed as earlier
          where earlier.patient_profile_id = completed.patient_profile_id
            and earlier.starts_at < v_current_start
        )
    ),
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_previous_start
        and completed.starts_at < v_current_start
        and exists (
          select 1
          from completed as earlier
          where earlier.patient_profile_id = completed.patient_profile_id
            and earlier.starts_at < v_previous_start
        )
    )
    into
      v_current_people,
      v_previous_people,
      v_current_returned,
      v_previous_returned
  from completed;

  select count(*)
    into v_pending_reviews
  from public.reviews as review
  where review.therapist_profile_id = v_therapist.id
    and review.status = 'published'
    and review.published_at is not null
    and not exists (
      select 1
      from public.review_replies as reply
      where reply.review_id = review.id
        and reply.therapist_profile_id = v_therapist.id
        and reply.status = 'published'
        and reply.published_at is not null
    );

  with public_services as (
    select service.id
    from public.therapist_services as service
    join public.therapies as therapy
      on therapy.id = service.therapy_id
    where service.therapist_profile_id = v_therapist.id
      and service.status = 'active'
      and service.is_bookable is true
      and service.online_only is true
      and service.delivery_format = 'online'
      and therapy.status = 'published'
      and v_therapist.status = 'approved'
      and v_therapist.is_public is true
      and v_therapist.is_accepting_bookings is true
  ),
  slot_checks as (
    select
      service.id,
      jsonb_array_length(
        coalesce(
          public.get_service_available_slots_v1(
            service.id,
            v_next_start,
            v_next_end,
            1
          )->'slots',
          '[]'::jsonb
        )
      ) as slot_count
    from public_services as service
  )
  select
    (select count(*) from public_services),
    (select count(*) from slot_checks where slot_count > 0)
    into v_public_bookable_services, v_services_with_slots;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', recommendation.id,
        'ruleKey', recommendation.source_rule_key,
        'ruleVersion', recommendation.rule_version,
        'title', recommendation.title,
        'body', recommendation.body,
        'priority', recommendation.priority,
        'actionRouteKey', recommendation.action_route_key,
        'evidence', recommendation.evidence,
        'generatedAt', recommendation.generated_at,
        'expiresAt', recommendation.expires_at
      )
      order by recommendation.priority desc, recommendation.generated_at desc
    ),
    '[]'::jsonb
  )
    into v_active_recommendations
  from public.aura_recommendations as recommendation
  where recommendation.therapist_profile_id = v_therapist.id
    and recommendation.status = 'active'
    and recommendation.is_active is true
    and recommendation.plan_required = 'premium_plus'::public.therapist_plan
    and coalesce(recommendation.expires_at, now() + interval '1 second') > now()
    and coalesce(recommendation.context->>'source', '') <> 'demo_seed'
    and recommendation.patient_profile_id is null
    and recommendation.booking_id is null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'recommendationKey', dismissal.recommendation_key,
        'ruleKey', dismissal.rule_key,
        'ruleVersion', dismissal.rule_version,
        'periodStart', dismissal.period_start,
        'periodEnd', dismissal.period_end,
        'dismissedAt', dismissal.dismissed_at
      )
      order by dismissal.dismissed_at desc
    ),
    '[]'::jsonb
  )
    into v_dismissals
  from public.aura_recommendation_dismissals as dismissal
  where dismissal.therapist_profile_id = v_therapist.id
    and dismissal.period_start = v_current_start
    and dismissal.period_end = v_current_end;

  return jsonb_build_object(
    'contractVersion', 1,
    'ruleRegistryVersion', 1,
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'plan', v_therapist.plan
    ),
    'meta', jsonb_build_object(
      'timezone', v_timezone,
      'periodDays', p_period_days,
      'periodStart', v_current_start,
      'periodEnd', v_current_end,
      'previousPeriodStart', v_previous_start,
      'previousPeriodEnd', v_current_start,
      'computedAt', now(),
      'freshThrough', v_current_end
    ),
    'signals', jsonb_build_object(
      'bookingReadiness', jsonb_build_object(
        'status', case
          when v_public_bookable_services = 0 then 'empty'
          else 'ready'
        end,
        'windowDays', 14,
        'publicBookableServices', v_public_bookable_services,
        'servicesWithFutureAvailability', v_services_with_slots
      ),
      'reviews', jsonb_build_object(
        'status', case
          when v_pending_reviews = 0 then 'empty'
          else 'ready'
        end,
        'pendingReplyCount', v_pending_reviews
      ),
      'sessions', jsonb_build_object(
        'cancellationRate', public.therapist_metric_rate_v1(
          v_current_cancelled,
          v_current_completed + v_current_no_shows + v_current_cancelled,
          v_previous_cancelled,
          v_previous_completed + v_previous_no_shows + v_previous_cancelled,
          'therapist_metrics.sessions_cancelled',
          10
        ),
        'noShowRate', public.therapist_metric_rate_v1(
          v_current_no_shows,
          v_current_presence_sample,
          v_previous_no_shows,
          v_previous_presence_sample,
          'therapist_metrics.operational_presence',
          10
        )
      ),
      'continuity', jsonb_build_object(
        'returnRate', public.therapist_metric_rate_v1(
          v_current_returned,
          v_current_people,
          v_previous_returned,
          v_previous_people,
          'therapist_metrics.return_rate',
          10
        )
      )
    ),
    'recommendations', v_active_recommendations,
    'dismissals', v_dismissals
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_aura_signals_v1"("p_period_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_aura_signals_v1"("p_period_days" integer) IS 'Private deterministic Aura read model. Uses auth.uid(), Premium Plus only, aggregate signals, no patient ids, no free text and no demo recommendations.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_aura_signals_v2"("p_period_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_payload jsonb;
  v_therapist_id uuid;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_pending_reviews bigint := 0;
  v_recommendations jsonb := '[]'::jsonb;
begin
  if p_period_days not in (30, 90) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  v_payload := public.get_therapist_aura_signals_v1(p_period_days);
  v_period_start := (v_payload #>> '{meta,periodStart}')::timestamptz;
  v_period_end := (v_payload #>> '{meta,periodEnd}')::timestamptz;

  select therapist.id
    into v_therapist_id
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if v_therapist_id is null then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  select count(*)
    into v_pending_reviews
  from public.reviews as review
  where review.therapist_profile_id = v_therapist_id
    and review.status = 'published'
    and review.published_at >= v_period_start
    and review.published_at < v_period_end
    and not exists (
      select 1
      from public.review_replies as reply
      where reply.review_id = review.id
        and reply.therapist_profile_id = v_therapist_id
        and reply.status = 'published'
        and reply.published_at is not null
    );

  select coalesce(
    jsonb_agg(
      recommendation
      order by
        (recommendation->>'priority')::integer desc,
        recommendation->>'generatedAt' desc
    ),
    '[]'::jsonb
  )
    into v_recommendations
  from jsonb_array_elements(
    coalesce(v_payload->'recommendations', '[]'::jsonb)
  ) as item(recommendation)
  where recommendation->>'ruleKey' in (
      'aura.booking_readiness.no_future_slots.v1',
      'aura.reviews.pending_reply.v1',
      'aura.sessions.cancellation_increased.v1',
      'aura.sessions.no_show_increased.v1',
      'aura.continuity.return_rate_decreased.v1'
    )
    and (recommendation->>'ruleVersion')::integer = 1
    and (recommendation->>'generatedAt')::timestamptz >= v_period_start
    and (recommendation->>'generatedAt')::timestamptz < v_period_end;

  v_payload := jsonb_set(
    v_payload,
    '{signals,reviews}',
    jsonb_build_object(
      'status', case when v_pending_reviews = 0 then 'empty' else 'ready' end,
      'pendingReplyCount', v_pending_reviews,
      'windowDays', p_period_days
    ),
    true
  );

  return jsonb_set(v_payload, '{recommendations}', v_recommendations, true);
end;
$$;


ALTER FUNCTION "public"."get_therapist_aura_signals_v2"("p_period_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_aura_signals_v2"("p_period_days" integer) IS 'Private deterministic Aura read model v2. Persisted recommendations must be generated inside the selected completed period, pending reviews use that same period, and only registered rule versions are returned.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_blocks_v1"("p_range_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_range_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_status" "text" DEFAULT 'active'::"text", "p_reason_code" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_cursor_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_range_end timestamptz := coalesce(p_range_end, now() + interval '1 year');
  v_range_start timestamptz := coalesce(p_range_start, now() - interval '90 days');
  v_settings public.therapist_schedule_settings%rowtype;
  v_therapist public.therapist_profiles%rowtype;
begin
  if v_range_start >= v_range_end then
    raise exception 'invalid_block_range' using errcode = '22023';
  end if;

  if p_status not in ('active', 'cancelled', 'all') then
    raise exception 'invalid_block_filter' using errcode = '22023';
  end if;

  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = (select auth.uid())
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  select settings.*
    into v_settings
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', v_therapist.id,
    'scheduleVersion', v_settings.version,
    'timezone', v_settings.timezone,
    'summary', jsonb_build_object(
      'activeBlocks', (
        select count(*)
        from public.availability_exceptions as exception
        where exception.therapist_profile_id = v_therapist.id
          and exception.status = 'active'
          and not exception.is_available
          and exception.starts_at < v_range_end
          and exception.ends_at > v_range_start
      ),
      'recurringSeries', (
        select count(*)
        from public.availability_exception_series as series
        where series.therapist_profile_id = v_therapist.id
          and series.status = 'active'
          and series.recurrence_frequency <> 'none'
      ),
      'pendingImpacts', (
        select count(*)
        from public.availability_exception_booking_impacts as impact
        where impact.therapist_profile_id = v_therapist.id
          and impact.status = 'pending'
      )
    ),
    'blocks', (
      select coalesce(
        jsonb_agg(block_row.payload order by block_row.starts_at, block_row.id),
        '[]'::jsonb
      )
      from (
        select
          exception.id,
          exception.starts_at,
          jsonb_build_object(
            'id', exception.id,
            'seriesId', exception.series_id,
            'serviceId', exception.service_id,
            'serviceTitle', service.title,
            'startsAt', exception.starts_at,
            'endsAt', exception.ends_at,
            'timezone', exception.timezone,
            'allDay', exception.all_day,
            'reasonCode', exception.reason_code,
            'reason', exception.reason,
            'status', exception.status,
            'version', exception.version,
            'recurrenceFrequency',
              coalesce(series.recurrence_frequency, 'none'),
            'recurrenceEndsOn', series.recurrence_ends_on,
            'createdAt', exception.created_at,
            'impactedBookings', (
              select coalesce(
                jsonb_agg(
                  jsonb_build_object(
                    'impactId', impact.id,
                    'bookingId', booking.id,
                    'startsAt', booking.starts_at,
                    'serviceTitle',
                      coalesce(booking.service_title_snapshot, booking_service.title),
                    'patientName', patient.display_name,
                    'status', impact.status,
                    'resolution', impact.resolution
                  )
                  order by booking.starts_at
                ),
                '[]'::jsonb
              )
              from public.availability_exception_booking_impacts as impact
              join public.bookings as booking on booking.id = impact.booking_id
              join public.patient_profiles as patient
                on patient.id = booking.patient_profile_id
              join public.therapist_services as booking_service
                on booking_service.id = booking.service_id
              where impact.exception_id = exception.id
            )
          ) as payload
        from public.availability_exceptions as exception
        left join public.availability_exception_series as series
          on series.id = exception.series_id
        left join public.therapist_services as service
          on service.id = exception.service_id
        where exception.therapist_profile_id = v_therapist.id
          and not exception.is_available
          and exception.starts_at < v_range_end
          and exception.ends_at > v_range_start
          and (p_status = 'all' or exception.status = p_status)
          and (
            p_reason_code is null
            or exception.reason_code = p_reason_code
          )
          and (
            nullif(trim(coalesce(p_search, '')), '') is null
            or coalesce(exception.reason, '') ilike
              '%' || trim(p_search) || '%'
            or coalesce(service.title, '') ilike
              '%' || trim(p_search) || '%'
          )
          and (
            p_cursor_starts_at is null
            or (exception.starts_at, exception.id) > (
              p_cursor_starts_at,
              coalesce(p_cursor_id, '00000000-0000-0000-0000-000000000000')
            )
          )
        order by exception.starts_at, exception.id
        limit v_limit
      ) as block_row
    ),
    'nextCursor', (
      select case
        when count(*) = v_limit then jsonb_build_object(
          'startsAt', max(page.starts_at),
          'id', (
            select page_last.id
            from (
              select exception.id, exception.starts_at
              from public.availability_exceptions as exception
              where exception.therapist_profile_id = v_therapist.id
                and not exception.is_available
                and exception.starts_at < v_range_end
                and exception.ends_at > v_range_start
                and (p_status = 'all' or exception.status = p_status)
                and (
                  p_reason_code is null
                  or exception.reason_code = p_reason_code
                )
                and (
                  p_cursor_starts_at is null
                  or (exception.starts_at, exception.id) > (
                    p_cursor_starts_at,
                    coalesce(
                      p_cursor_id,
                      '00000000-0000-0000-0000-000000000000'
                    )
                  )
                )
              order by exception.starts_at, exception.id
              limit v_limit
            ) as page_last
            order by page_last.starts_at desc, page_last.id desc
            limit 1
          )
        )
        else null
      end
      from (
        select exception.starts_at
        from public.availability_exceptions as exception
        where exception.therapist_profile_id = v_therapist.id
          and not exception.is_available
          and exception.starts_at < v_range_end
          and exception.ends_at > v_range_start
          and (p_status = 'all' or exception.status = p_status)
          and (
            p_reason_code is null
            or exception.reason_code = p_reason_code
          )
          and (
            p_cursor_starts_at is null
            or (exception.starts_at, exception.id) > (
              p_cursor_starts_at,
              coalesce(p_cursor_id, '00000000-0000-0000-0000-000000000000')
            )
          )
        order by exception.starts_at, exception.id
        limit v_limit
      ) as page
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_blocks_v1"("p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_status" "text", "p_reason_code" "text", "p_search" "text", "p_limit" integer, "p_cursor_starts_at" timestamp with time zone, "p_cursor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_blocks_v1"("p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_status" "text", "p_reason_code" "text", "p_search" "text", "p_limit" integer, "p_cursor_starts_at" timestamp with time zone, "p_cursor_id" "uuid") IS 'A4 authenticated therapist block read model. Identity derives from auth.uid().';



CREATE OR REPLACE FUNCTION "public"."get_therapist_calendar_v1"("p_anchor_date" "date" DEFAULT NULL::"date", "p_view" "text" DEFAULT 'week'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_anchor date;
  v_local_end date;
  v_local_start date;
  v_now timestamptz := now();
  v_range_end timestamptz;
  v_range_start timestamptz;
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
begin
  select therapist.*
  into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = (select auth.uid())
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  if p_view not in ('day', 'week', 'month') then
    raise exception 'invalid_calendar_view' using errcode = '22023';
  end if;

  select schedule_settings.timezone
  into v_timezone
  from public.therapist_schedule_settings as schedule_settings
  where schedule_settings.therapist_profile_id = v_therapist.id;

  if not found then
    raise exception 'schedule_settings_not_found' using errcode = 'P0002';
  end if;

  v_anchor := coalesce(p_anchor_date, (v_now at time zone v_timezone)::date);

  if p_view = 'day' then
    v_local_start := v_anchor;
    v_local_end := v_anchor + 1;
  elsif p_view = 'week' then
    v_local_start := v_anchor
      - (extract(isodow from v_anchor)::integer - 1);
    v_local_end := v_local_start + 7;
  else
    v_local_start := date_trunc('month', v_anchor)::date;
    v_local_start := v_local_start
      - (extract(isodow from v_local_start)::integer - 1);
    v_local_end := v_local_start + 42;
  end if;

  v_range_start := v_local_start::timestamp at time zone v_timezone;
  v_range_end := v_local_end::timestamp at time zone v_timezone;

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', v_therapist.id,
    'timezone', v_timezone,
    'view', p_view,
    'anchorDate', v_anchor,
    'range', jsonb_build_object(
      'localStart', v_local_start,
      'localEndExclusive', v_local_end,
      'start', v_range_start,
      'end', v_range_end,
      'endExclusive', true
    ),
    'summary', jsonb_build_object(
      'bookings', (
        select count(*)
        from public.bookings as booking
        where booking.therapist_profile_id = v_therapist.id
          and booking.starts_at < v_range_end
          and booking.ends_at > v_range_start
      ),
      'activeHolds', (
        select count(*)
        from public.booking_holds as hold
        where hold.therapist_profile_id = v_therapist.id
          and hold.status = 'active'
          and hold.expires_at > v_now
          and hold.starts_at < v_range_end
          and hold.ends_at > v_range_start
      ),
      'pendingAttention', (
        select count(*)
        from public.booking_reschedule_requests as request
        join public.bookings as booking
          on booking.id = request.booking_id
        where booking.therapist_profile_id = v_therapist.id
          and request.status = 'pending'
      )
    ),
    'services', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', service.id,
            'title', service.title,
            'therapyId', therapy.id,
            'therapyName', therapy.name,
            'colorKey', therapy.calendar_color_key,
            'durationMinutes', service.duration_minutes
          )
          order by service.title, service.id
        ),
        '[]'::jsonb
      )
      from public.therapist_services as service
      join public.therapies as therapy
        on therapy.id = service.therapy_id
      where service.therapist_profile_id = v_therapist.id
        and service.status <> 'archived'
    ),
    'bookings', (
      select coalesce(
        jsonb_agg(
          (
            to_jsonb(session_row)
            - '_therapistProfileId'
            - '_videoSessionReady'
          ) || jsonb_build_object(
            'therapyId', therapy.id,
            'therapyName', therapy.name,
            'colorKey', therapy.calendar_color_key,
            'zoomAccess',
            public.build_video_session_access_state_v1(
              session_row."bookingStatus",
              session_row."financialStatus",
              session_row."startsAt",
              session_row."endsAt",
              session_row."videoSessionStatus",
              session_row."_videoSessionReady",
              v_now
            )
          )
          order by session_row."startsAt", session_row."bookingId"
        ),
        '[]'::jsonb
      )
      from public.therapist_session_read_model_v1 as session_row
      join public.bookings as booking
        on booking.id = session_row."bookingId"
      join public.therapist_services as service
        on service.id = booking.service_id
      join public.therapies as therapy
        on therapy.id = service.therapy_id
      where session_row."_therapistProfileId" = v_therapist.id
        and session_row."startsAt" < v_range_end
        and session_row."endsAt" > v_range_start
    ),
    'holds', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', hold.id,
            'serviceId', hold.service_id,
            'serviceTitle', hold.service_title_snapshot,
            'startsAt', hold.starts_at,
            'endsAt', hold.ends_at,
            'expiresAt', hold.expires_at,
            'colorKey', therapy.calendar_color_key
          )
          order by hold.starts_at, hold.id
        ),
        '[]'::jsonb
      )
      from public.booking_holds as hold
      join public.therapist_services as service
        on service.id = hold.service_id
      join public.therapies as therapy
        on therapy.id = service.therapy_id
      where hold.therapist_profile_id = v_therapist.id
        and hold.status = 'active'
        and hold.expires_at > v_now
        and hold.starts_at < v_range_end
        and hold.ends_at > v_range_start
    ),
    'blocks', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', exception.id,
            'serviceId', exception.service_id,
            'startsAt', exception.starts_at,
            'endsAt', exception.ends_at,
            'allDay', exception.all_day,
            'reason', exception.reason,
            'reasonCode', exception.reason_code
          )
          order by exception.starts_at, exception.id
        ),
        '[]'::jsonb
      )
      from public.availability_exceptions as exception
      where exception.therapist_profile_id = v_therapist.id
        and not exception.is_available
        and exception.status = 'active'
        and exception.starts_at < v_range_end
        and exception.ends_at > v_range_start
    ),
    'attentionItems', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', request.id,
            'starts_at', booking.starts_at,
            'kind', 'reschedule',
            'title', patient_profile.display_name,
            'description', 'Pediu reagendamento',
            'booking_id', booking.id
          )
          order by booking.starts_at, request.id
        ),
        '[]'::jsonb
      )
      from public.booking_reschedule_requests as request
      join public.bookings as booking
        on booking.id = request.booking_id
      join public.patient_profiles as patient_profile
        on patient_profile.id = booking.patient_profile_id
      where booking.therapist_profile_id = v_therapist.id
        and request.status = 'pending'
    ),
    'demand', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'dayOfWeek', demand.day_of_week,
            'hourBlock', demand.hour_block,
            'count', demand.booking_count
          )
          order by demand.hour_block, demand.day_of_week
        ),
        '[]'::jsonb
      )
      from (
        select
          extract(
            dow from booking.starts_at at time zone v_timezone
          )::integer as day_of_week,
          (
            floor(
              extract(
                hour from booking.starts_at at time zone v_timezone
              ) / 2
            ) * 2
          )::integer as hour_block,
          count(*)::integer as booking_count
        from public.bookings as booking
        where booking.therapist_profile_id = v_therapist.id
          and booking.starts_at >= v_now - interval '90 days'
          and booking.starts_at < v_now
          and booking.status in (
            'completed',
            'no_show_patient',
            'no_show_therapist'
          )
        group by day_of_week, hour_block
      ) as demand
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_calendar_v1"("p_anchor_date" "date", "p_view" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_calendar_v1"("p_anchor_date" "date", "p_view" "text") IS 'Private therapist calendar. Its operational rail exposes only pending reschedule requests; confirmed paid sessions are selected client-side from bookings.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_dashboard_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.profiles%rowtype;
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_today date;
  v_month_start date;
  v_previous_month_start date;
  v_week_start date;
  v_profile_completeness integer;
  v_completed integer;
  v_no_shows integer;
begin
  select *
  into v_profile
  from public.profiles
  where id = (select auth.uid())
    and role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  select *
  into v_therapist
  from public.therapist_profiles
  where user_id = (select auth.uid())
    and plan = 'premium_plus'
    and status = 'approved';

  if not found then
    raise exception 'premium_plus_access_required' using errcode = '42501';
  end if;

  v_timezone := coalesce(
    nullif(v_therapist.metadata ->> 'timezone', ''),
    'America/Sao_Paulo'
  );
  v_today := (now() at time zone v_timezone)::date;
  v_month_start := date_trunc('month', v_today::timestamp)::date;
  v_previous_month_start := (v_month_start - interval '1 month')::date;
  v_week_start := date_trunc('week', v_today::timestamp)::date;

  v_profile_completeness := (
    (
      (v_therapist.photo_url is not null)::integer
      + (v_therapist.headline is not null)::integer
      + (v_therapist.bio is not null)::integer
      + (v_therapist.city is not null)::integer
      + exists (
          select 1
          from public.therapist_services
          where therapist_profile_id = v_therapist.id
            and status = 'active'
        )::integer
    ) * 20
  );

  select
    count(*) filter (where status = 'completed'),
    count(*) filter (where status in ('no_show_patient', 'no_show_therapist'))
  into v_completed, v_no_shows
  from public.bookings
  where therapist_profile_id = v_therapist.id
    and (starts_at at time zone v_timezone)::date between v_week_start and v_week_start + 6;

  return jsonb_build_object(
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'name', v_therapist.public_name,
      'avatarUrl', coalesce(v_therapist.photo_url, v_profile.avatar_url),
      'plan', v_therapist.plan,
      'profileCompleteness', v_profile_completeness
    ),
    'today', jsonb_build_object(
      'sessionsToday', (
        select count(*)
        from public.bookings
        where therapist_profile_id = v_therapist.id
          and status in ('confirmed', 'completed')
          and (starts_at at time zone v_timezone)::date = v_today
      ),
      'newConnections', (
        select count(*)
        from public.therapist_patient_relationships
        where therapist_profile_id = v_therapist.id
          and (started_at at time zone v_timezone)::date = v_today
          and source_booking_id is not null
      ),
      'pendingReviewReplies', (
        select count(*)
        from public.reviews
        where therapist_profile_id = v_therapist.id
          and status = 'published'
          and not exists (
            select 1
            from public.review_replies
            where review_replies.review_id = reviews.id
              and review_replies.status = 'published'
          )
      ),
      'reservedMinutesToday', (
        select coalesce(sum(extract(epoch from (ends_at - starts_at)) / 60), 0)::integer
        from public.bookings
        where therapist_profile_id = v_therapist.id
          and status in ('confirmed', 'completed')
          and (starts_at at time zone v_timezone)::date = v_today
      ),
      'pendingPayments', (
        select count(*)
        from public.bookings
        where therapist_profile_id = v_therapist.id
          and status = 'pending_payment'
      ),
      'rescheduleRequests', (
        select count(*)
        from public.booking_reschedule_requests
        join public.bookings on bookings.id = booking_reschedule_requests.booking_id
        where bookings.therapist_profile_id = v_therapist.id
          and booking_reschedule_requests.status = 'pending'
      )
    ),
    'week', jsonb_build_object(
      'rangeLabel',
        to_char(v_week_start, 'DD/MM') || ' – ' || to_char(v_week_start + 6, 'DD/MM'),
      'attendanceRate',
        case
          when v_completed + v_no_shows = 0 then 0
          else round((v_completed::numeric / (v_completed + v_no_shows)) * 100)::integer
        end,
      'days', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'date', day_value::date,
          'label', upper(to_char(day_value, 'Dy')),
          'scheduled', scheduled,
          'completed', completed,
          'cancelled', cancelled
        ) order by day_value), '[]'::jsonb)
        from (
          select
            day_value,
            count(bookings.id) filter (
              where bookings.status in ('confirmed', 'completed', 'no_show_patient', 'no_show_therapist')
            ) as scheduled,
            count(bookings.id) filter (where bookings.status = 'completed') as completed,
            count(bookings.id) filter (
              where bookings.status in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded')
            ) as cancelled
          from generate_series(v_week_start, v_week_start + 6, interval '1 day') day_value
          left join public.bookings
            on bookings.therapist_profile_id = v_therapist.id
            and (bookings.starts_at at time zone v_timezone)::date = day_value::date
          group by day_value
        ) weekly
      )
    ),
    'upcomingSessions', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'bookingId', upcoming.id,
        'startsAt', upcoming.starts_at,
        'patientName', upcoming.display_name,
        'patientAvatarUrl', upcoming.avatar_url,
        'serviceTitle', upcoming.title
      ) order by upcoming.starts_at), '[]'::jsonb)
      from (
        select
          bookings.id,
          bookings.starts_at,
          patient_profiles.display_name,
          patient_profiles.avatar_url,
          therapist_services.title
        from public.bookings
        join public.patient_profiles
          on patient_profiles.id = bookings.patient_profile_id
        join public.therapist_services
          on therapist_services.id = bookings.service_id
        where bookings.therapist_profile_id = v_therapist.id
          and bookings.status = 'confirmed'
          and bookings.starts_at >= now()
        order by bookings.starts_at
        limit 4
      ) upcoming
    ),
    'kpis', jsonb_build_object(
      'monthlySessions', public.dashboard_kpi_json(
        (
          select count(*)
          from public.bookings
          where therapist_profile_id = v_therapist.id
            and (starts_at at time zone v_timezone)::date >= v_month_start
            and status not in ('draft', 'pending_payment', 'cancelled_by_patient', 'cancelled_by_therapist', 'refunded')
        ),
        (
          select count(*)
          from public.bookings
          where therapist_profile_id = v_therapist.id
            and (starts_at at time zone v_timezone)::date >= v_previous_month_start
            and (starts_at at time zone v_timezone)::date < v_month_start
            and status not in ('draft', 'pending_payment', 'cancelled_by_patient', 'cancelled_by_therapist', 'refunded')
        )
      ),
      'activePatients', public.dashboard_kpi_json(
        (
          select count(*)
          from public.therapist_patient_relationships
          where therapist_profile_id = v_therapist.id
            and status = 'active'
        ),
        (
          select count(*)
          from public.therapist_patient_relationships
          where therapist_profile_id = v_therapist.id
            and started_at < v_month_start
            and (ended_at is null or ended_at >= v_month_start)
        )
      ),
      'monthlyNetRevenueCents', public.dashboard_kpi_json(
        (
          select coalesce(sum(therapist_amount_cents), 0)
          from public.payments
          where therapist_profile_id = v_therapist.id
            and status = 'paid'
            and (paid_at at time zone v_timezone)::date >= v_month_start
        ),
        (
          select coalesce(sum(therapist_amount_cents), 0)
          from public.payments
          where therapist_profile_id = v_therapist.id
            and status = 'paid'
            and (paid_at at time zone v_timezone)::date >= v_previous_month_start
            and (paid_at at time zone v_timezone)::date < v_month_start
        )
      ),
      'profileViews', public.dashboard_kpi_json(
        (
          select coalesce(sum(profile_views), 0)
          from public.therapist_profile_daily_analytics
          where therapist_profile_id = v_therapist.id
            and metric_date >= v_month_start
        ),
        (
          select coalesce(sum(profile_views), 0)
          from public.therapist_profile_daily_analytics
          where therapist_profile_id = v_therapist.id
            and metric_date >= v_previous_month_start
            and metric_date < v_month_start
        )
      )
    ),
    'attentionItems', (
      select coalesce(jsonb_agg(item), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'id', 'pending-payments',
          'count', (
            select count(*)
            from public.bookings
            where therapist_profile_id = v_therapist.id
              and status = 'pending_payment'
          ),
          'label', 'Pagamentos pendentes',
          'href', '/plus/sessoes',
          'tone', 'warning'
        ) as item
        where exists (
          select 1 from public.bookings
          where therapist_profile_id = v_therapist.id
            and status = 'pending_payment'
        )
        union all
        select jsonb_build_object(
          'id', 'reschedule-requests',
          'count', (
            select count(*)
            from public.booking_reschedule_requests
            join public.bookings on bookings.id = booking_reschedule_requests.booking_id
            where bookings.therapist_profile_id = v_therapist.id
              and booking_reschedule_requests.status = 'pending'
          ),
          'label', 'Pedidos de reagendamento',
          'href', '/plus/agenda',
          'tone', 'warning'
        ) as item
        where exists (
          select 1
          from public.booking_reschedule_requests
          join public.bookings on bookings.id = booking_reschedule_requests.booking_id
          where bookings.therapist_profile_id = v_therapist.id
            and booking_reschedule_requests.status = 'pending'
        )
        union all
        select jsonb_build_object(
          'id', 'profile-completeness',
          'label', 'Perfil ' || v_profile_completeness || '% concluído',
          'href', '/plus/perfil',
          'tone', 'info'
        ) as item
        where v_profile_completeness < 100
      ) attention
    ),
    'history', jsonb_build_object(
      'completedSessions', (
        select count(*)
        from public.bookings
        where therapist_profile_id = v_therapist.id
          and status = 'completed'
      ),
      'activePatients', (
        select count(*)
        from public.therapist_patient_relationships
        where therapist_profile_id = v_therapist.id
          and status = 'active'
      ),
      'averageRating', (
        select round(avg(rating), 1)
        from public.reviews
        where therapist_profile_id = v_therapist.id
          and status = 'published'
      )
    ),
    'recentReviews', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', recent.id,
        'patientName', recent.display_name,
        'patientInitial', left(recent.display_name, 1),
        'rating', recent.rating,
        'comment', recent.comment,
        'publishedAt', recent.published_at
      ) order by recent.published_at desc), '[]'::jsonb)
      from (
        select
          reviews.id,
          patient_profiles.display_name,
          reviews.rating,
          coalesce(reviews.comment, '') as comment,
          reviews.published_at
        from public.reviews
        join public.patient_profiles
          on patient_profiles.id = reviews.patient_profile_id
        where reviews.therapist_profile_id = v_therapist.id
          and reviews.status = 'published'
        order by reviews.published_at desc
        limit 3
      ) recent
    ),
    'unreadMessagesCount', (
      select count(*)
      from public.messages
      join public.conversations on conversations.id = messages.conversation_id
      where conversations.therapist_profile_id = v_therapist.id
        and messages.sender_profile_id <> (select auth.uid())
        and messages.read_at is null
    ),
    'unreadNotificationsCount', (
      select count(*)
      from public.notifications
      where profile_id = (select auth.uid())
        and read_at is null
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_dashboard_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_dashboard_v1"() IS 'Premium Plus therapist dashboard read model. Resolves auth.uid(), uses RLS and returns aggregate/private-safe data.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_for_service_actor_v1"("p_actor_user_id" "uuid") RETURNS "public"."therapist_profiles"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = p_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  return v_therapist;
end;
$$;


ALTER FUNCTION "public"."get_therapist_for_service_actor_v1"("p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_therapist_interest_metrics_v1"("p_period_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_current_local_end date;
  v_current_local_start date;
  v_previous_local_start date;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_previous_start timestamptz;
  v_current_people bigint := 0;
  v_previous_people bigint := 0;
  v_current_sessions bigint := 0;
  v_previous_sessions bigint := 0;
  v_current_returned bigint := 0;
  v_previous_returned bigint := 0;
  v_current_favorites bigint := 0;
  v_previous_favorites bigint := 0;
  v_segment_total bigint := 0;
  v_segment_small_groups bigint := 0;
  v_segment_items jsonb := '[]'::jsonb;
  v_cohort_observed bigint := 0;
  v_cohort_items jsonb := '[]'::jsonb;
begin
  if p_period_days not in (30, 60, 90, 120) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select therapist.*
    into v_therapist
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = '42501';
  end if;

  if v_therapist.plan not in (
    'premium'::public.therapist_plan,
    'premium_plus'::public.therapist_plan
  ) then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  if v_timezone is null then
    raise exception 'UNAVAILABLE' using errcode = 'P0001';
  end if;

  v_current_local_end := (now() at time zone v_timezone)::date;
  v_current_local_start := v_current_local_end - p_period_days;
  v_previous_local_start := v_current_local_start - p_period_days;
  v_current_start := v_current_local_start::timestamp at time zone v_timezone;
  v_current_end := v_current_local_end::timestamp at time zone v_timezone;
  v_previous_start := v_previous_local_start::timestamp at time zone v_timezone;

  if v_therapist.plan = 'premium'::public.therapist_plan then
    return jsonb_build_object(
      'contractVersion', 1,
      'metricDefinitionVersion', 1,
      'therapist', jsonb_build_object(
        'profileId', v_therapist.id,
        'plan', v_therapist.plan
      ),
      'meta', jsonb_build_object(
        'timezone', v_timezone,
        'periodDays', p_period_days,
        'periodStart', v_current_start,
        'periodEnd', v_current_end,
        'previousPeriodStart', v_previous_start,
        'previousPeriodEnd', v_current_start,
        'computedAt', now(),
        'freshThrough', v_current_end
      ),
      'access', jsonb_build_object(
        'status', 'capability_locked',
        'requiredPlan', 'premium_plus'
      )
    );
  end if;

  with completed as (
    select booking.patient_profile_id, booking.starts_at
    from public.bookings as booking
    where booking.therapist_profile_id = v_therapist.id
      and booking.status = 'completed'
      and booking.starts_at < v_current_end
  )
  select
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_current_start
    ),
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_previous_start
        and completed.starts_at < v_current_start
    ),
    count(*) filter (where completed.starts_at >= v_current_start),
    count(*) filter (
      where completed.starts_at >= v_previous_start
        and completed.starts_at < v_current_start
    ),
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_current_start
        and exists (
          select 1
          from completed as earlier
          where earlier.patient_profile_id = completed.patient_profile_id
            and earlier.starts_at < v_current_start
        )
    ),
    count(distinct completed.patient_profile_id) filter (
      where completed.starts_at >= v_previous_start
        and completed.starts_at < v_current_start
        and exists (
          select 1
          from completed as earlier
          where earlier.patient_profile_id = completed.patient_profile_id
            and earlier.starts_at < v_previous_start
        )
    )
    into
      v_current_people,
      v_previous_people,
      v_current_sessions,
      v_previous_sessions,
      v_current_returned,
      v_previous_returned
  from completed;

  select
    coalesce(sum(aggregate.favorites_added) filter (
      where aggregate.metric_date >= v_current_local_start
    ), 0),
    coalesce(sum(aggregate.favorites_added) filter (
      where aggregate.metric_date < v_current_local_start
    ), 0)
    into v_current_favorites, v_previous_favorites
  from public.therapist_metric_daily_aggregates as aggregate
  where aggregate.therapist_profile_id = v_therapist.id
    and aggregate.definition_version = 1
    and aggregate.metric_date >= v_previous_local_start
    and aggregate.metric_date < v_current_local_end;

  with booking_summary as (
    select
      booking.patient_profile_id,
      min(booking.starts_at) as first_completed_at,
      max(booking.starts_at) as last_completed_at,
      count(*)::bigint as completed_count
    from public.bookings as booking
    where booking.therapist_profile_id = v_therapist.id
      and booking.status = 'completed'
      and booking.starts_at < v_current_end
    group by booking.patient_profile_id
  ),
  patient_universe as (
    select
      coalesce(
        relationship.patient_profile_id,
        booking_summary.patient_profile_id
      ) as patient_profile_id,
      relationship.status as relationship_status,
      booking_summary.first_completed_at,
      booking_summary.last_completed_at,
      coalesce(booking_summary.completed_count, 0) as completed_count
    from public.therapist_patient_relationships as relationship
    full join booking_summary
      on booking_summary.patient_profile_id = relationship.patient_profile_id
      and relationship.therapist_profile_id = v_therapist.id
    where relationship.therapist_profile_id = v_therapist.id
      or relationship.therapist_profile_id is null
  ),
  segmented as (
    select case
      when relationship_status = 'paused' then 'paused'
      when relationship_status = 'closed'
        or last_completed_at < v_current_end - interval '90 days'
        then 'inactive'
      when first_completed_at >= v_current_end - interval '30 days'
        and completed_count = 1
        then 'new'
      when completed_count >= 2
        and last_completed_at >= v_current_end - interval '90 days'
        then 'recurring'
      else 'active'
    end as segment
    from patient_universe
  ),
  segment_counts as (
    select segment, count(*)::bigint as segment_count
    from segmented
    group by segment
  ),
  segment_counts_with_total as (
    select
      segment,
      segment_count,
      sum(segment_count) over () as total_count
    from segment_counts
  )
  select
    coalesce(sum(segment_count), 0),
    count(*) filter (
      where segment_count between 1 and 9
    ),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'key', segment,
          'value', segment_count,
          'percentage', round(
            segment_count::numeric
              * 100 / nullif(total_count, 0),
            1
          )
        )
        order by case segment
          when 'active' then 1
          when 'recurring' then 2
          when 'new' then 3
          when 'inactive' then 4
          else 5
        end
      ),
      '[]'::jsonb
    )
    into v_segment_total, v_segment_small_groups, v_segment_items
  from segment_counts_with_total;

  with completed as (
    select
      booking.patient_profile_id,
      date_trunc(
        'month',
        booking.starts_at at time zone v_timezone
      )::date as session_month
    from public.bookings as booking
    where booking.therapist_profile_id = v_therapist.id
      and booking.status = 'completed'
      and booking.starts_at < (
        date_trunc(
          'month',
          v_current_local_end::timestamp
        )::date::timestamp at time zone v_timezone
      )
  ),
  cohort_members as (
    select
      patient_profile_id,
      min(session_month) as cohort_month
    from completed
    group by patient_profile_id
  ),
  cohort_sizes as (
    select cohort_month, count(*)::bigint as cohort_size
    from cohort_members
    where cohort_month >= (
      date_trunc('month', v_current_local_end::timestamp)::date
        - interval '6 months'
    )::date
    group by cohort_month
  ),
  eligible_cohorts as (
    select *
    from cohort_sizes
    where cohort_size >= 10
  ),
  cohort_retention_points as (
    select
      eligible.cohort_month,
      eligible.cohort_size,
      offsets.month_offset,
      round(
        count(distinct completed.patient_profile_id)::numeric
          * 100 / eligible.cohort_size,
        1
      ) as percentage
    from eligible_cohorts as eligible
    cross join generate_series(0, 5) as offsets(month_offset)
    left join cohort_members as member
      on member.cohort_month = eligible.cohort_month
    left join completed
      on completed.patient_profile_id = member.patient_profile_id
      and completed.session_month = (
        eligible.cohort_month
          + make_interval(months => offsets.month_offset)
      )::date
    where (
      eligible.cohort_month
        + make_interval(months => offsets.month_offset)
    )::date < date_trunc(
      'month',
      v_current_local_end::timestamp
    )::date
    group by
      eligible.cohort_month,
      eligible.cohort_size,
      offsets.month_offset
  ),
  cohort_rows as (
    select
      point.cohort_month,
      point.cohort_size,
      jsonb_agg(
        jsonb_build_object(
          'monthOffset', point.month_offset,
          'percentage', point.percentage
        )
        order by point.month_offset
      ) as retention
    from cohort_retention_points as point
    group by point.cohort_month, point.cohort_size
  )
  select
    coalesce(max(cohort_size), 0),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'cohortMonth', cohort_month,
          'cohortSize', cohort_size,
          'retention', retention
        )
        order by cohort_month
      ),
      '[]'::jsonb
    )
    into v_cohort_observed, v_cohort_items
  from cohort_rows;

  return jsonb_build_object(
    'contractVersion', 1,
    'metricDefinitionVersion', 1,
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'plan', v_therapist.plan
    ),
    'meta', jsonb_build_object(
      'timezone', v_timezone,
      'periodDays', p_period_days,
      'periodStart', v_current_start,
      'periodEnd', v_current_end,
      'previousPeriodStart', v_previous_start,
      'previousPeriodEnd', v_current_start,
      'computedAt', now(),
      'freshThrough', v_current_end
    ),
    'access', jsonb_build_object(
      'status', 'ready',
      'requiredPlan', 'premium_plus'
    ),
    'summary', jsonb_build_object(
      'peopleReturned', public.therapist_metric_sampled_counter_by_sample_v1(
        v_current_returned,
        v_previous_returned,
        v_current_people,
        'therapist_metrics.people_returned',
        'people',
        10
      ),
      'returnRate', public.therapist_metric_rate_v1(
        v_current_returned,
        v_current_people,
        v_previous_returned,
        v_previous_people,
        'therapist_metrics.return_rate',
        10
      ),
      'sessionsPerPerson', public.therapist_metric_sampled_counter_by_sample_v1(
        round(
          v_current_sessions::numeric / nullif(v_current_people, 0),
          1
        ),
        round(
          v_previous_sessions::numeric / nullif(v_previous_people, 0),
          1
        ),
        v_current_people,
        'therapist_metrics.sessions_per_person',
        'ratio',
        10
      ),
      'profileFavorites', jsonb_build_object(
        'activity', jsonb_build_object(
          'status', case
            when v_current_favorites = 0 then 'empty'
            else 'ready'
          end,
          'unit', 'favorites',
          'value', v_current_favorites
        ),
        'comparison', public.therapist_metric_sampled_counter_v1(
          v_current_favorites,
          v_previous_favorites,
          'therapist_metrics.profile_favorites',
          'favorites',
          10
        )
      )
    ),
    'segments', jsonb_build_object(
      'status', case
        when v_segment_total = 0 then 'empty'
        when v_segment_total < 10 or v_segment_small_groups > 0
          then 'insufficient_sample'
        else 'ready'
      end,
      'minimumSample', 10,
      'observedSample', v_segment_total,
      'items', case
        when v_segment_total < 10 or v_segment_small_groups > 0
          then '[]'::jsonb
        else v_segment_items
      end,
      'definitionVersion', 1
    ),
    'baseEvolution', jsonb_build_object(
      'status', case
        when v_current_sessions = 0 then 'empty'
        when v_current_sessions < 10 then 'insufficient_sample'
        else 'ready'
      end,
      'minimumSample', 10,
      'observedSample', v_current_sessions,
      'items', case
        when v_current_sessions < 10 then '[]'::jsonb
        else (
          with first_sessions as (
            select
              booking.patient_profile_id,
              min(booking.starts_at) as first_completed_at
            from public.bookings as booking
            where booking.therapist_profile_id = v_therapist.id
              and booking.status = 'completed'
              and booking.starts_at < v_current_end
            group by booking.patient_profile_id
          )
          select jsonb_agg(
            jsonb_build_object(
              'date', point.bucket_start::date,
              'totalPeople', (
                select count(*)
                from first_sessions
                where first_completed_at < least(
                  point.bucket_start + interval '7 days',
                  v_current_end
                )
              ),
              'newPeople', (
                select count(*)
                from first_sessions
                where first_completed_at >= point.bucket_start
                  and first_completed_at < least(
                    point.bucket_start + interval '7 days',
                    v_current_end
                  )
              )
            )
            order by point.bucket_start
          )
          from generate_series(
            v_current_start,
            v_current_end - interval '1 day',
            interval '7 days'
          ) as point(bucket_start)
        )
      end
    ),
    'cohorts', jsonb_build_object(
      'status', case
        when v_cohort_observed = 0 then 'insufficient_sample'
        else 'ready'
      end,
      'minimumSample', 10,
      'observedSample', v_cohort_observed,
      'items', v_cohort_items
    ),
    'therapyReturn', (
      with current_people as (
        select
          service.therapy_id,
          therapy.name as therapy_name,
          booking.patient_profile_id
        from public.bookings as booking
        join public.therapist_services as service
          on service.id = booking.service_id
        join public.therapies as therapy
          on therapy.id = service.therapy_id
        where booking.therapist_profile_id = v_therapist.id
          and booking.status = 'completed'
          and booking.starts_at >= v_current_start
          and booking.starts_at < v_current_end
        group by service.therapy_id, therapy.name, booking.patient_profile_id
      ),
      therapy_people as (
        select
          current_people.therapy_id,
          current_people.therapy_name,
          current_people.patient_profile_id,
          exists (
            select 1
            from public.bookings as earlier
            join public.therapist_services as earlier_service
              on earlier_service.id = earlier.service_id
            where earlier.therapist_profile_id = v_therapist.id
              and earlier.patient_profile_id =
                current_people.patient_profile_id
              and earlier_service.therapy_id = current_people.therapy_id
              and earlier.status = 'completed'
              and earlier.starts_at < v_current_start
          ) as returned
        from current_people
      ),
      therapy_counts as (
        select
          therapy_id,
          therapy_name,
          count(*)::bigint as people,
          count(*) filter (where returned)::bigint as returned_people
        from therapy_people
        group by therapy_id, therapy_name
      )
      select jsonb_build_object(
        'status', case
          when coalesce(sum(people), 0) = 0 then 'empty'
          when not exists (
            select 1 from therapy_counts where people >= 10
          ) then 'insufficient_sample'
          else 'ready'
        end,
        'minimumSample', 10,
        'observedSample', coalesce(max(people), 0),
        'items', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'therapyId', therapy_id,
              'therapyName', therapy_name,
              'people', people,
              'returnedPeople', returned_people,
              'returnRate', round(
                returned_people::numeric * 100 / people,
                1
              )
            )
            order by
              returned_people::numeric / people desc,
              therapy_name
          )
          from therapy_counts
          where people >= 10
        ), '[]'::jsonb)
      )
      from therapy_counts
    ),
    'favoriteConversion', jsonb_build_object(
      'status', 'unavailable',
      'reason', 'favorite_conversion_linkage_not_available'
    ),
    'sentiment', jsonb_build_object(
      'status', 'unavailable',
      'reason', 'sentiment_schema_and_consent_not_implemented'
    ),
    'availabilityGap', jsonb_build_object(
      'status', 'unavailable',
      'reason', 'availability_gap_event_not_implemented'
    ),
    'journeyThemes', jsonb_build_object(
      'status', 'unavailable',
      'reason', 'free_text_analysis_prohibited'
    ),
    'exitReasons', jsonb_build_object(
      'status', 'unavailable',
      'reason', 'relationship_exit_taxonomy_not_versioned'
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_interest_metrics_v1"("p_period_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_interest_metrics_v1"("p_period_days" integer) IS 'MTR-5 private continuity read model for Premium Plus. Profile-favorite activity is aggregate-only and available from the first completed local day; comparisons, cohorts and segments retain sample locks of ten and the response contains no patient identifiers or free text.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_metrics_dashboard_v2"("p_period_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_overview jsonb;
  v_sessions jsonb;
  v_interest jsonb;
  v_profile_id uuid;
  v_timezone text;
begin
  if p_period_days not in (30, 60, 90, 120) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  v_overview := public.get_therapist_metrics_overview_v1(p_period_days);
  v_sessions := public.get_therapist_session_metrics_v1(p_period_days);
  v_interest := public.get_therapist_interest_metrics_v1(p_period_days);
  v_profile_id := (v_overview #>> '{therapist,profileId}')::uuid;
  v_timezone := v_overview #>> '{meta,timezone}';

  return jsonb_build_object(
    'contractVersion', 2,
    'metricDefinitionVersion', 2,
    'therapist', v_overview -> 'therapist',
    'meta', v_overview -> 'meta',
    'overview', v_overview,
    'sessions', v_sessions,
    'interest', v_interest,
    'occupancy', public.get_therapist_occupancy_metrics_v2(
      v_profile_id,
      v_timezone,
      p_period_days
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_metrics_dashboard_v2"("p_period_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_metrics_dashboard_v2"("p_period_days" integer) IS 'Authenticated aggregate dashboard for therapist metrics. Preserves v1 contracts and adds occupancy only after complete immutable schedule history coverage.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_metrics_foundation_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_current_local_end date;
  v_current_local_start date;
  v_previous_local_start date;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_previous_start timestamptz;
  v_current_people bigint := 0;
  v_previous_people bigint := 0;
  v_current_sessions bigint := 0;
  v_previous_sessions bigint := 0;
  v_current_minutes bigint := 0;
  v_previous_minutes bigint := 0;
begin
  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select therapist.*
    into v_therapist
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = '42501';
  end if;

  if v_therapist.plan not in (
    'premium'::public.therapist_plan,
    'premium_plus'::public.therapist_plan
  ) then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  if v_timezone is null then
    raise exception 'UNAVAILABLE' using errcode = 'P0001';
  end if;

  v_current_local_end := (now() at time zone v_timezone)::date;
  v_current_local_start := v_current_local_end - 30;
  v_previous_local_start := v_current_local_start - 30;
  v_current_start := v_current_local_start::timestamp at time zone v_timezone;
  v_current_end := v_current_local_end::timestamp at time zone v_timezone;
  v_previous_start := v_previous_local_start::timestamp at time zone v_timezone;

  select
    count(distinct booking.patient_profile_id) filter (
      where booking.starts_at >= v_current_start
        and booking.starts_at < v_current_end
    ),
    count(distinct booking.patient_profile_id) filter (
      where booking.starts_at >= v_previous_start
        and booking.starts_at < v_current_start
    ),
    count(*) filter (
      where booking.starts_at >= v_current_start
        and booking.starts_at < v_current_end
    ),
    count(*) filter (
      where booking.starts_at >= v_previous_start
        and booking.starts_at < v_current_start
    ),
    coalesce(sum(booking.service_duration_minutes_snapshot) filter (
      where booking.starts_at >= v_current_start
        and booking.starts_at < v_current_end
    ), 0),
    coalesce(sum(booking.service_duration_minutes_snapshot) filter (
      where booking.starts_at >= v_previous_start
        and booking.starts_at < v_current_start
    ), 0)
    into
      v_current_people,
      v_previous_people,
      v_current_sessions,
      v_previous_sessions,
      v_current_minutes,
      v_previous_minutes
  from public.bookings as booking
  where booking.therapist_profile_id = v_therapist.id
    and booking.status = 'completed'
    and booking.starts_at >= v_previous_start
    and booking.starts_at < v_current_end;

  return jsonb_build_object(
    'contractVersion', 1,
    'metricDefinitionVersion', 1,
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'plan', v_therapist.plan
    ),
    'meta', jsonb_build_object(
      'timezone', v_timezone,
      'periodDays', 30,
      'periodStart', v_current_start,
      'periodEnd', v_current_end,
      'previousPeriodStart', v_previous_start,
      'previousPeriodEnd', v_current_start,
      'computedAt', now(),
      'freshThrough', v_current_end
    ),
    'counters', jsonb_build_object(
      'peopleServed', public.therapist_metric_counter_v1(
        v_current_people,
        v_previous_people,
        'therapist_metrics.people_served',
        'people'
      ),
      'sessionsCompleted', public.therapist_metric_counter_v1(
        v_current_sessions,
        v_previous_sessions,
        'therapist_metrics.sessions_completed',
        'sessions'
      ),
      'serviceMinutes', public.therapist_metric_counter_v1(
        v_current_minutes,
        v_previous_minutes,
        'therapist_metrics.service_minutes',
        'minutes'
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_metrics_foundation_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_metrics_foundation_v1"() IS 'Authenticated MTR-0.1 read model: three no-lock counters for the last 30 complete local days and the preceding comparison period.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_metrics_overview_v1"("p_period_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_current_local_end date;
  v_current_local_start date;
  v_previous_local_start date;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_previous_start timestamptz;
  v_current_people bigint := 0;
  v_previous_people bigint := 0;
  v_current_sessions bigint := 0;
  v_previous_sessions bigint := 0;
  v_current_minutes bigint := 0;
  v_previous_minutes bigint := 0;
  v_current_search bigint := 0;
  v_previous_search bigint := 0;
  v_current_profile bigint := 0;
  v_previous_profile bigint := 0;
  v_current_booking_start bigint := 0;
  v_previous_booking_start bigint := 0;
  v_current_favorites bigint := 0;
  v_previous_favorites bigint := 0;
  v_current_search_sessions bigint := 0;
  v_previous_search_sessions bigint := 0;
  v_current_profile_sessions bigint := 0;
  v_previous_profile_sessions bigint := 0;
  v_current_search_to_profile bigint := 0;
  v_previous_search_to_profile bigint := 0;
  v_current_profile_to_booking bigint := 0;
  v_previous_profile_to_booking bigint := 0;
  v_telemetry_enabled boolean := false;
  v_first_browser_event_at timestamptz;
  v_browser_fresh_through timestamptz;
  v_discovery_status text;
  v_completed_sample bigint := 0;
begin
  if p_period_days not in (30, 60, 90, 120) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select therapist.*
    into v_therapist
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = '42501';
  end if;

  if v_therapist.plan not in (
    'premium'::public.therapist_plan,
    'premium_plus'::public.therapist_plan
  ) then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  if v_timezone is null then
    raise exception 'UNAVAILABLE' using errcode = 'P0001';
  end if;

  v_current_local_end := (now() at time zone v_timezone)::date;
  v_current_local_start := v_current_local_end - p_period_days;
  v_previous_local_start := v_current_local_start - p_period_days;
  v_current_start := v_current_local_start::timestamp at time zone v_timezone;
  v_current_end := v_current_local_end::timestamp at time zone v_timezone;
  v_previous_start := v_previous_local_start::timestamp at time zone v_timezone;

  select
    count(distinct booking.patient_profile_id) filter (
      where booking.starts_at >= v_current_start
    ),
    count(distinct booking.patient_profile_id) filter (
      where booking.starts_at < v_current_start
    ),
    count(*) filter (
      where booking.starts_at >= v_current_start
    ),
    count(*) filter (
      where booking.starts_at < v_current_start
    ),
    coalesce(sum(booking.service_duration_minutes_snapshot) filter (
      where booking.starts_at >= v_current_start
    ), 0),
    coalesce(sum(booking.service_duration_minutes_snapshot) filter (
      where booking.starts_at < v_current_start
    ), 0)
    into
      v_current_people,
      v_previous_people,
      v_current_sessions,
      v_previous_sessions,
      v_current_minutes,
      v_previous_minutes
  from public.bookings as booking
  where booking.therapist_profile_id = v_therapist.id
    and booking.status = 'completed'
    and booking.starts_at >= v_previous_start
    and booking.starts_at < v_current_end;

  v_completed_sample := v_current_sessions;

  select
    coalesce(sum(aggregate.search_impressions) filter (
      where aggregate.metric_date >= v_current_local_start
    ), 0),
    coalesce(sum(aggregate.search_impressions) filter (
      where aggregate.metric_date < v_current_local_start
    ), 0),
    coalesce(sum(aggregate.profile_views) filter (
      where aggregate.metric_date >= v_current_local_start
    ), 0),
    coalesce(sum(aggregate.profile_views) filter (
      where aggregate.metric_date < v_current_local_start
    ), 0),
    coalesce(sum(aggregate.booking_flow_starts) filter (
      where aggregate.metric_date >= v_current_local_start
    ), 0),
    coalesce(sum(aggregate.booking_flow_starts) filter (
      where aggregate.metric_date < v_current_local_start
    ), 0),
    coalesce(sum(aggregate.favorites_added) filter (
      where aggregate.metric_date >= v_current_local_start
    ), 0),
    coalesce(sum(aggregate.favorites_added) filter (
      where aggregate.metric_date < v_current_local_start
    ), 0),
    max(aggregate.fresh_through)
    into
      v_current_search,
      v_previous_search,
      v_current_profile,
      v_previous_profile,
      v_current_booking_start,
      v_previous_booking_start,
      v_current_favorites,
      v_previous_favorites,
      v_browser_fresh_through
  from public.therapist_metric_daily_aggregates as aggregate
  where aggregate.therapist_profile_id = v_therapist.id
    and aggregate.definition_version = 1
    and aggregate.metric_date >= v_previous_local_start
    and aggregate.metric_date < v_current_local_end;

  select config.public_telemetry_enabled
    into v_telemetry_enabled
  from public.therapist_metrics_runtime_config as config
  where config.singleton = true;

  select min(metric_event.occurred_at)
    into v_first_browser_event_at
  from public.therapist_metric_events as metric_event
  where metric_event.therapist_profile_id = v_therapist.id
    and metric_event.event_source = 'browser';

  with period_events as (
    select
      metric_event.event_type,
      metric_event.session_key_hash,
      metric_event.occurred_at
    from public.therapist_metric_events as metric_event
    where metric_event.therapist_profile_id = v_therapist.id
      and metric_event.event_source = 'browser'
      and metric_event.occurred_at >= v_previous_start
      and metric_event.occurred_at < v_current_end
  )
  select
    count(distinct session_key_hash) filter (
      where event_type = 'search_impression'
        and occurred_at >= v_current_start
    ),
    count(distinct session_key_hash) filter (
      where event_type = 'search_impression'
        and occurred_at < v_current_start
    ),
    count(distinct session_key_hash) filter (
      where event_type = 'profile_view'
        and occurred_at >= v_current_start
    ),
    count(distinct session_key_hash) filter (
      where event_type = 'profile_view'
        and occurred_at < v_current_start
    )
    into
      v_current_search_sessions,
      v_previous_search_sessions,
      v_current_profile_sessions,
      v_previous_profile_sessions
  from period_events;

  select
    count(distinct profile_event.session_key_hash) filter (
      where profile_event.occurred_at >= v_current_start
    ),
    count(distinct profile_event.session_key_hash) filter (
      where profile_event.occurred_at < v_current_start
    )
    into v_current_search_to_profile, v_previous_search_to_profile
  from public.therapist_metric_events as profile_event
  where profile_event.therapist_profile_id = v_therapist.id
    and profile_event.event_type = 'profile_view'
    and profile_event.event_source = 'browser'
    and profile_event.occurred_at >= v_previous_start
    and profile_event.occurred_at < v_current_end
    and exists (
      select 1
      from public.therapist_metric_events as search_event
      where search_event.therapist_profile_id = v_therapist.id
        and search_event.event_type = 'search_impression'
        and search_event.event_source = 'browser'
        and search_event.session_key_hash = profile_event.session_key_hash
        and search_event.occurred_at <= profile_event.occurred_at
    );

  select
    count(distinct booking_event.session_key_hash) filter (
      where booking_event.occurred_at >= v_current_start
    ),
    count(distinct booking_event.session_key_hash) filter (
      where booking_event.occurred_at < v_current_start
    )
    into v_current_profile_to_booking, v_previous_profile_to_booking
  from public.therapist_metric_events as booking_event
  where booking_event.therapist_profile_id = v_therapist.id
    and booking_event.event_type = 'booking_flow_started'
    and booking_event.event_source = 'browser'
    and booking_event.occurred_at >= v_previous_start
    and booking_event.occurred_at < v_current_end
    and exists (
      select 1
      from public.therapist_metric_events as profile_event
      where profile_event.therapist_profile_id = v_therapist.id
        and profile_event.event_type = 'profile_view'
        and profile_event.event_source = 'browser'
        and profile_event.session_key_hash = booking_event.session_key_hash
        and profile_event.occurred_at <= booking_event.occurred_at
    );

  v_discovery_status := case
    when not coalesce(v_telemetry_enabled, false) then 'unavailable'
    when v_first_browser_event_at is null then 'processing'
    when (
      v_current_search
      + v_current_profile
      + v_current_booking_start
    ) = 0 then 'empty'
    else 'ready'
  end;

  return jsonb_build_object(
    'contractVersion', 1,
    'metricDefinitionVersion', 1,
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'plan', v_therapist.plan
    ),
    'meta', jsonb_build_object(
      'timezone', v_timezone,
      'periodDays', p_period_days,
      'periodStart', v_current_start,
      'periodEnd', v_current_end,
      'previousPeriodStart', v_previous_start,
      'previousPeriodEnd', v_current_start,
      'computedAt', now(),
      'freshThrough', v_current_end
    ),
    'counters', jsonb_build_object(
      'peopleServed', public.therapist_metric_counter_v1(
        v_current_people,
        v_previous_people,
        'therapist_metrics.people_served',
        'people'
      ),
      'sessionsCompleted', public.therapist_metric_counter_v1(
        v_current_sessions,
        v_previous_sessions,
        'therapist_metrics.sessions_completed',
        'sessions'
      ),
      'serviceMinutes', public.therapist_metric_counter_v1(
        v_current_minutes,
        v_previous_minutes,
        'therapist_metrics.service_minutes',
        'minutes'
      )
    ),
    'activity', jsonb_build_object(
      'status', case
        when v_current_sessions = 0 then 'empty'
        else 'ready'
      end,
      'freshThrough', v_current_end,
      'points', (
        select coalesce(
          jsonb_agg(
            jsonb_build_object(
              'date', day.metric_date::date,
              'sessionsCompleted', coalesce(bookings.completed_count, 0)
            )
            order by day.metric_date
          ),
          '[]'::jsonb
        )
        from generate_series(
          v_current_local_start,
          v_current_local_end - 1,
          interval '1 day'
        ) as day(metric_date)
        left join (
          select
            (booking.starts_at at time zone v_timezone)::date as metric_date,
            count(*)::integer as completed_count
          from public.bookings as booking
          where booking.therapist_profile_id = v_therapist.id
            and booking.status = 'completed'
            and booking.starts_at >= v_current_start
            and booking.starts_at < v_current_end
          group by (booking.starts_at at time zone v_timezone)::date
        ) as bookings
          on bookings.metric_date = day.metric_date::date
      )
    ),
    'discovery', jsonb_build_object(
      'status', v_discovery_status,
      'reason', case
        when v_discovery_status = 'unavailable'
          then 'privacy_activation_pending'
        else null
      end,
      'freshThrough', v_browser_fresh_through,
      'stages', jsonb_build_object(
        'searchImpressions', public.therapist_metric_counter_v1(
          v_current_search,
          v_previous_search,
          'therapist_metrics.search_impressions',
          'events'
        ),
        'profileViews', public.therapist_metric_counter_v1(
          v_current_profile,
          v_previous_profile,
          'therapist_metrics.profile_views',
          'events'
        ),
        'bookingFlowStarts', public.therapist_metric_counter_v1(
          v_current_booking_start,
          v_previous_booking_start,
          'therapist_metrics.booking_flow_starts',
          'events'
        )
      ),
      'funnel', jsonb_build_object(
        'searchToProfile', public.therapist_metric_rate_v1(
          v_current_search_to_profile,
          v_current_search_sessions,
          v_previous_search_to_profile,
          v_previous_search_sessions,
          'therapist_metrics.search_to_profile',
          10
        ),
        'profileToBooking', public.therapist_metric_rate_v1(
          v_current_profile_to_booking,
          v_current_profile_sessions,
          v_previous_profile_to_booking,
          v_previous_profile_sessions,
          'therapist_metrics.profile_to_booking',
          10
        )
      )
    ),
    'profileFavorites', public.therapist_metric_sampled_counter_v1(
      v_current_favorites,
      v_previous_favorites,
      'therapist_metrics.profile_favorites',
      'favorites',
      10
    ),
    'therapyRanking', jsonb_build_object(
      'status', case
        when v_completed_sample = 0 then 'empty'
        when v_completed_sample < 10 then 'insufficient_sample'
        else 'ready'
      end,
      'minimumSample', 10,
      'observedSample', v_completed_sample,
      'items', case
        when v_completed_sample < 10 then '[]'::jsonb
        else (
          with current_counts as (
            select
              therapy.id,
              therapy.name,
              count(*)::bigint as current_count
            from public.bookings as booking
            join public.therapist_services as service
              on service.id = booking.service_id
            join public.therapies as therapy
              on therapy.id = service.therapy_id
            where booking.therapist_profile_id = v_therapist.id
              and booking.status = 'completed'
              and booking.starts_at >= v_current_start
              and booking.starts_at < v_current_end
            group by therapy.id, therapy.name
          ),
          previous_counts as (
            select
              therapy.id,
              count(*)::bigint as previous_count
            from public.bookings as booking
            join public.therapist_services as service
              on service.id = booking.service_id
            join public.therapies as therapy
              on therapy.id = service.therapy_id
            where booking.therapist_profile_id = v_therapist.id
              and booking.status = 'completed'
              and booking.starts_at >= v_previous_start
              and booking.starts_at < v_current_start
            group by therapy.id
          )
          select coalesce(
            jsonb_agg(
              jsonb_build_object(
                'therapyId', current_counts.id,
                'therapyName', current_counts.name,
                'counter', public.therapist_metric_counter_v1(
                  current_counts.current_count,
                  coalesce(previous_counts.previous_count, 0),
                  'therapist_metrics.therapy_bookings',
                  'sessions'
                )
              )
              order by
                current_counts.current_count desc,
                current_counts.name
            ),
            '[]'::jsonb
          )
          from current_counts
          left join previous_counts
            on previous_counts.id = current_counts.id
        )
      end
    ),
    'occupancy', jsonb_build_object(
      'status', 'unavailable',
      'reason', 'historical_availability_not_versioned'
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_metrics_overview_v1"("p_period_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_metrics_overview_v1"("p_period_days" integer) IS 'MTR-2 private overview read model. Uses complete local days, own-history comparisons, versioned states and no patient identifiers.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_metrics_today_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_local_date date;
  v_favorites_added bigint := 0;
  v_fresh_through timestamptz;
begin
  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select therapist.*
    into v_therapist
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = '42501';
  end if;

  if v_therapist.plan <> 'premium_plus'::public.therapist_plan then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  if v_timezone is null then
    raise exception 'UNAVAILABLE' using errcode = 'P0001';
  end if;

  v_local_date := (now() at time zone v_timezone)::date;

  select
    coalesce(sum(aggregate.favorites_added), 0),
    max(aggregate.fresh_through)
    into v_favorites_added, v_fresh_through
  from public.therapist_metric_daily_aggregates as aggregate
  where aggregate.therapist_profile_id = v_therapist.id
    and aggregate.metric_date = v_local_date
    and aggregate.definition_version = 1;

  return jsonb_build_object(
    'contractVersion', 1,
    'metricDefinitionVersion', 1,
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'plan', v_therapist.plan
    ),
    'meta', jsonb_build_object(
      'timezone', v_timezone,
      'localDate', v_local_date,
      'computedAt', now(),
      'freshThrough', v_fresh_through
    ),
    'profileFavoritesAdded', jsonb_build_object(
      'status', case
        when v_favorites_added = 0 then 'empty'
        else 'ready'
      end,
      'unit', 'favorites',
      'value', v_favorites_added
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_metrics_today_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_metrics_today_v1"() IS 'Authenticated current-local-day metrics projection. It complements, and never changes, complete-day historical comparisons.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_occupancy_metrics_v2"("p_therapist_profile_id" "uuid", "p_timezone" "text", "p_period_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_local_end date;
  v_local_start date;
  v_previous_local_start date;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_previous_start timestamptz;
  v_coverage_start timestamptz;
  v_coverage_days integer := 0;
  v_current_offered bigint := 0;
  v_current_occupied bigint := 0;
  v_previous_offered bigint := 0;
  v_previous_occupied bigint := 0;
  v_series jsonb := '[]'::jsonb;
  v_heatmap jsonb := '[]'::jsonb;
begin
  if p_period_days not in (30, 60, 90, 120) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  select coverage.started_at
    into v_coverage_start
  from public.therapist_availability_history_coverage as coverage
  where coverage.therapist_profile_id = p_therapist_profile_id;

  v_local_end := (now() at time zone p_timezone)::date;
  v_local_start := v_local_end - p_period_days;
  v_previous_local_start := v_local_start - p_period_days;
  v_current_start := v_local_start::timestamp at time zone p_timezone;
  v_current_end := v_local_end::timestamp at time zone p_timezone;
  v_previous_start := v_previous_local_start::timestamp at time zone p_timezone;

  if v_coverage_start is not null then
    v_coverage_days := greatest(
      0,
      v_local_end - (v_coverage_start at time zone p_timezone)::date
    );
  end if;

  if v_coverage_start is null or v_coverage_start > v_current_start then
    return jsonb_build_object(
      'status', 'forming',
      'reason', 'history_in_formation',
      'coverageStart', case
        when v_coverage_start is null then null
        else (v_coverage_start at time zone p_timezone)::date
      end,
      'coverageDays', least(v_coverage_days, p_period_days),
      'requiredCoverageDays', p_period_days
    );
  end if;

  with buckets as (
    select bucket.starts_at,
      bucket.starts_at + interval '15 minutes' as ends_at,
      (bucket.starts_at at time zone p_timezone)::date as local_date,
      extract(dow from bucket.starts_at at time zone p_timezone)::integer as day_of_week,
      extract(hour from bucket.starts_at at time zone p_timezone)::integer as hour_bucket_start
    from generate_series(
      greatest(v_previous_start, v_coverage_start),
      v_current_end - interval '15 minutes',
      interval '15 minutes'
    ) as bucket(starts_at)
  ), evaluated as (
    select bucket.*,
      exists (
        select 1
        from (
          select distinct on (history.source_rule_id)
            history.operation,
            history.day_of_week,
            history.start_time,
            history.end_time,
            history.timezone,
            history.is_active
          from public.availability_rule_history as history
          where history.therapist_profile_id = p_therapist_profile_id
            and history.recorded_at <= bucket.starts_at
          order by history.source_rule_id, history.recorded_at desc, history.id desc
        ) as current_rule
        where current_rule.operation <> 'delete'
          and current_rule.is_active
          and current_rule.day_of_week = extract(dow from bucket.starts_at at time zone current_rule.timezone)::integer
          and (bucket.starts_at at time zone current_rule.timezone)::time >= current_rule.start_time
          and (bucket.ends_at at time zone current_rule.timezone)::time <= current_rule.end_time
      )
      and not exists (
        select 1
        from (
          select distinct on (history.source_exception_id)
            history.operation,
            history.starts_at,
            history.ends_at,
            history.is_available
          from public.availability_exception_history as history
          where history.therapist_profile_id = p_therapist_profile_id
            and history.recorded_at <= bucket.starts_at
          order by history.source_exception_id, history.recorded_at desc, history.id desc
        ) as current_exception
        where current_exception.operation <> 'delete'
          and not current_exception.is_available
          and current_exception.starts_at < bucket.ends_at
          and current_exception.ends_at > bucket.starts_at
      ) as offered,
      exists (
        select 1
        from public.bookings as booking
        where booking.therapist_profile_id = p_therapist_profile_id
          and booking.status in ('confirmed', 'completed', 'no_show_patient', 'no_show_therapist')
          and booking.starts_at < bucket.ends_at
          and booking.ends_at > bucket.starts_at
      ) as booked
    from buckets as bucket
  ), daily as (
    select local_date,
      count(*) filter (where offered) * 15 as offered_minutes,
      count(*) filter (where offered and booked) * 15 as occupied_minutes
    from evaluated
    where starts_at >= v_current_start
    group by local_date
  ), hourly as (
    select day_of_week, hour_bucket_start,
      count(*) filter (where offered) * 15 as offered_minutes,
      count(*) filter (where offered and booked) * 15 as occupied_minutes
    from evaluated
    where starts_at >= v_current_start
    group by day_of_week, hour_bucket_start
  )
  select
    coalesce(sum(case when evaluated.starts_at >= v_current_start and offered then 15 else 0 end), 0),
    coalesce(sum(case when evaluated.starts_at >= v_current_start and offered and booked then 15 else 0 end), 0),
    coalesce(sum(case when evaluated.starts_at < v_current_start and offered then 15 else 0 end), 0),
    coalesce(sum(case when evaluated.starts_at < v_current_start and offered and booked then 15 else 0 end), 0),
    (select coalesce(jsonb_agg(jsonb_build_object(
      'date', daily.local_date,
      'offeredMinutes', daily.offered_minutes,
      'occupiedMinutes', daily.occupied_minutes,
      'percentage', case when daily.offered_minutes = 0 then null else round(daily.occupied_minutes::numeric * 100 / daily.offered_minutes, 1) end
    ) order by daily.local_date), '[]'::jsonb) from daily),
    (select coalesce(jsonb_agg(jsonb_build_object(
      'dayOfWeek', hourly.day_of_week,
      'hourBucketStart', hourly.hour_bucket_start,
      'offeredMinutes', hourly.offered_minutes,
      'occupiedMinutes', hourly.occupied_minutes,
      'percentage', case when hourly.offered_minutes = 0 then null else round(hourly.occupied_minutes::numeric * 100 / hourly.offered_minutes, 1) end
    ) order by hourly.hour_bucket_start, hourly.day_of_week), '[]'::jsonb) from hourly)
    into v_current_offered, v_current_occupied, v_previous_offered,
      v_previous_occupied, v_series, v_heatmap
  from evaluated;

  return jsonb_build_object(
    'status', case when v_current_offered = 0 then 'empty' else 'ready' end,
    'coverageStart', (v_coverage_start at time zone p_timezone)::date,
    'coverageDays', least(v_coverage_days, p_period_days),
    'requiredCoverageDays', p_period_days,
    'current', jsonb_build_object(
      'offeredMinutes', v_current_offered,
      'occupiedMinutes', v_current_occupied,
      'percentage', case when v_current_offered = 0 then null else round(v_current_occupied::numeric * 100 / v_current_offered, 1) end
    ),
    'previous', jsonb_build_object(
      'offeredMinutes', v_previous_offered,
      'occupiedMinutes', v_previous_occupied,
      'percentage', case when v_previous_offered = 0 then null else round(v_previous_occupied::numeric * 100 / v_previous_offered, 1) end
    ),
    'series', v_series,
    'heatmap', v_heatmap
  );
end;
$$;


