CREATE OR REPLACE FUNCTION "public"."get_therapist_profile_actor_m1"("p_actor_user_id" "uuid") RETURNS "public"."therapist_profiles"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
begin
  select *
    into v_therapist
  from public.therapist_profiles
  where user_id = p_actor_user_id;

  if v_therapist.id is null then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0001';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = 'P0001';
  end if;

  return v_therapist;
end;
$$;


