CREATE OR REPLACE FUNCTION "public"."get_therapist_publication_eligibility_v1"("p_therapist_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with profile as (
    select *
    from public.therapist_profiles
    where id = p_therapist_profile_id
  ), services as (
    select
      count(*) filter (
        where service.status = 'active'
          and service.is_bookable
          and service.online_only
      )::integer as online_bookable,
      count(*) filter (
        where service.status = 'active'
          and service.is_bookable
          and service.online_only
          and therapy.status = 'published'
          and therapy.is_public_visible
      )::integer as published_therapy,
      count(*) filter (
        where service.status = 'active'
          and service.is_bookable
          and service.online_only
          and therapy.status = 'published'
          and therapy.is_public_visible
          and public.therapy_has_active_matching_theme_v1(therapy.id)
      )::integer as eligible
    from public.therapist_services service
    join public.therapies therapy on therapy.id = service.therapy_id
    where service.therapist_profile_id = p_therapist_profile_id
      and service.archived_at is null
  )
  select jsonb_build_object(
    'eligible', coalesce(
      profile.status = 'approved'::public.therapist_status
      and profile.is_public
      and profile.is_accepting_bookings
      and profile.accepts_online_sessions
      and coalesce(services.eligible, 0) > 0
      and public.is_therapist_receiving_account_ready_v1(profile.id),
      false
    ),
    'blockers', coalesce((
      select jsonb_agg(code order by position)
      from unnest(array[
        case when profile.id is null then 'profile_not_found' end,
        case when profile.id is not null and profile.status <> 'approved'::public.therapist_status then 'profile_not_approved' end,
        case when profile.id is not null and not profile.is_public then 'profile_not_public' end,
        case when profile.id is not null and not profile.is_accepting_bookings then 'not_accepting_bookings' end,
        case when profile.id is not null and not profile.accepts_online_sessions then 'online_sessions_disabled' end,
        case when profile.id is not null and coalesce(services.online_bookable, 0) = 0 then 'no_active_bookable_online_service' end,
        case when profile.id is not null and coalesce(services.online_bookable, 0) > 0 and coalesce(services.published_therapy, 0) = 0 then 'therapy_not_public' end,
        case when profile.id is not null and coalesce(services.published_therapy, 0) > 0 and coalesce(services.eligible, 0) = 0 then 'therapy_without_active_theme' end,
        case when profile.id is not null and not public.is_therapist_receiving_account_ready_v1(profile.id) then 'receiving_account_not_ready' end
      ]) with ordinality as blockers(code, position)
      where code is not null
    ), '[]'::jsonb),
    'eligibleServiceCount', coalesce(services.eligible, 0)
  )
  from profile
  full join services on true
$$;


ALTER FUNCTION "public"."get_therapist_publication_eligibility_v1"("p_therapist_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_therapist_reviews_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_reviews jsonb;
  v_distribution jsonb;
  v_private_feedback jsonb;
  v_pending jsonb;
  v_total integer;
  v_distinct_patients integer;
  v_average numeric;
  v_responded integer;
  v_positive integer;
begin
  v_profile := public.resolve_current_therapist_for_reviews_v1();
  if v_profile.plan not in ('premium', 'premium_plus') then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = 'P0001';
  end if;

  select count(*)::integer,
    count(distinct review.patient_profile_id)::integer,
    round(avg(review.rating), 1),
    count(*) filter (where reply.id is not null)::integer,
    count(*) filter (where review.rating >= 4)::integer
  into v_total, v_distinct_patients, v_average, v_responded, v_positive
  from public.reviews review
  left join public.review_replies reply
    on reply.review_id = review.id and reply.status = 'published'
  where review.therapist_profile_id = v_profile.id
    and review.status = 'published'
    and review.superseded_at is null;

  with ratings as (select generate_series(5, 1, -1) rating), counts as (
    select review.rating, count(*)::integer total
    from public.reviews review
    where review.therapist_profile_id = v_profile.id
      and review.status = 'published' and review.superseded_at is null
    group by review.rating
  )
  select jsonb_agg(jsonb_build_object(
    'rating', ratings.rating, 'count', coalesce(counts.total, 0)
  ) order by ratings.rating desc)
  into v_distribution from ratings left join counts using (rating);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', review.id,
    'patientName', coalesce(patient.display_name, 'Paciente TES'),
    'patientInitials', public.therapist_reviews_initials_v1(patient.display_name),
    'rating', review.rating,
    'comment', coalesce(review.comment, ''),
    'publishedAt', review.published_at,
    'publishedLabel', public.therapist_reviews_date_label_v1(review.published_at),
    'serviceTitle', service.title,
    'therapyName', therapy.name,
    'responseStatus', case when reply.id is null then 'pending' else 'responded' end,
    'reply', case when reply.id is null then null else jsonb_build_object(
      'id', reply.id, 'body', reply.body, 'status', reply.status,
      'publishedAt', reply.published_at
    ) end
  ) order by review.published_at desc nulls last, review.updated_at desc), '[]'::jsonb)
  into v_reviews
  from public.reviews review
  join public.patient_profiles patient on patient.id = review.patient_profile_id
  left join public.bookings booking on booking.id = review.booking_id
  left join public.therapist_services service on service.id = booking.service_id
  left join public.therapies therapy on therapy.id = service.therapy_id
  left join public.review_replies reply
    on reply.review_id = review.id and reply.status = 'published'
  where review.therapist_profile_id = v_profile.id
    and review.status = 'published' and review.superseded_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', feedback.id,
    'bookingId', feedback.booking_id,
    'authorRole', feedback.author_role,
    'comment', feedback.comment,
    'createdAt', feedback.created_at,
    'notPerformedReason', feedback.not_performed_reason,
    'outcome', feedback.outcome,
    'rating', feedback.rating,
    'patientName', patient.display_name,
    'serviceTitle', service.title,
    'startsAt', booking.starts_at
  ) order by feedback.created_at desc), '[]'::jsonb)
  into v_private_feedback
  from public.session_feedback feedback
  join public.bookings booking on booking.id = feedback.booking_id
  join public.patient_profiles patient on patient.id = booking.patient_profile_id
  left join public.therapist_services service on service.id = booking.service_id
  where booking.therapist_profile_id = v_profile.id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'bookingId', pending.booking_id,
    'sessionReference', booking.session_reference,
    'patientName', pending.patient_name,
    'serviceTitle', pending.service_title,
    'startsAt', pending.starts_at,
    'endsAt', pending.ends_at,
    'timezone', booking.timezone,
    'dueAt', pending.due_at,
    'remainingSeconds', pending.remaining_seconds
  ) order by pending.ends_at desc, pending.booking_id desc), '[]'::jsonb)
  into v_pending
  from public.therapist_pending_confirmation_rows_v1(v_profile.id) as pending
  join public.bookings as booking
    on booking.id = pending.booking_id;

  return jsonb_build_object(
    'therapist', jsonb_build_object(
      'profileId', v_profile.id, 'publicName', v_profile.public_name,
      'plan', v_profile.plan, 'publicSlug', v_profile.slug
    ),
    'metrics', jsonb_build_object(
      'averageRating', v_average,
      'totalReviews', coalesce(v_total, 0),
      'distinctPatients', coalesce(v_distinct_patients, 0),
      'respondedReviews', coalesce(v_responded, 0),
      'pendingReplies', greatest(coalesce(v_total, 0) - coalesce(v_responded, 0), 0),
      'positiveReviews', coalesce(v_positive, 0),
      'positivePercent', round(100 * coalesce(v_positive, 0)::numeric / nullif(v_total, 0), 0),
      'trends', jsonb_build_object(
        'averageRatingDelta', null, 'totalReviewsDelta', null,
        'respondedReviewsDelta', null, 'positivePercentDelta', null
      )
    ),
    'distribution', coalesce(v_distribution, '[]'::jsonb),
    'reviews', v_reviews,
    'privateFeedback', v_private_feedback,
    'pendingConfirmations', v_pending,
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_reviews_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_reviews_v1"() IS 'Private therapist reviews read model. Resolves auth.uid(), includes only paid/completed published reviews and published replies.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_schedule_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_settings public.therapist_schedule_settings%rowtype;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = (select auth.uid())
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  select schedule_settings.*
    into v_settings
  from public.therapist_schedule_settings as schedule_settings
  where schedule_settings.therapist_profile_id = v_therapist.id;

  if not found then
    raise exception 'schedule_settings_not_found' using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', v_therapist.id,
    'scheduleVersion', v_settings.version,
    'timezone', v_settings.timezone,
    'updatedAt', v_settings.updated_at,
    'summary', jsonb_build_object(
      'configuredDays', (
        select count(distinct rule.day_of_week)
        from public.availability_rules as rule
        join public.therapist_services as service
          on service.id = rule.service_id
         and service.therapist_profile_id = v_therapist.id
         and service.status <> 'archived'
        where rule.therapist_profile_id = v_therapist.id
          and rule.is_active
      ),
      'weeklyAvailableMinutes', (
        with merged_day_windows as (
          select
            rule.day_of_week,
            range_agg(
              pg_catalog.int4range(
                floor(extract(epoch from rule.start_time) / 60)::integer,
                floor(extract(epoch from rule.end_time) / 60)::integer,
                '[)'
              )
            ) as windows
          from public.availability_rules as rule
          join public.therapist_services as service
            on service.id = rule.service_id
           and service.therapist_profile_id = v_therapist.id
           and service.status <> 'archived'
          where rule.therapist_profile_id = v_therapist.id
            and rule.is_active
          group by rule.day_of_week
        )
        select coalesce(
          sum(
            upper(window_segment.range_value)
            - lower(window_segment.range_value)
          ),
          0
        )::integer
        from merged_day_windows as merged
        cross join lateral unnest(merged.windows)
          as window_segment(range_value)
      )
    ),
    'rules', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', rule.id,
            'serviceId', rule.service_id,
            'dayOfWeek', rule.day_of_week,
            'startTime', rule.start_time,
            'endTime', rule.end_time,
            'isActive', rule.is_active
          )
          order by
            rule.day_of_week,
            rule.service_id,
            rule.start_time,
            rule.id
        ),
        '[]'::jsonb
      )
      from public.availability_rules as rule
      where rule.therapist_profile_id = v_therapist.id
    ),
    'services', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', service.id,
            'title', service.title,
            'status', service.status,
            'durationMinutes', service.duration_minutes,
            'settings', jsonb_build_object(
              'bufferBeforeMinutes',
                coalesce(booking_settings.buffer_before_minutes, 0),
              'bufferAfterMinutes',
                coalesce(booking_settings.buffer_after_minutes, 0),
              'minimumNoticeMinutes',
                coalesce(booking_settings.min_notice_minutes, 120),
              'bookingHorizonDays',
                coalesce(booking_settings.max_days_ahead, 30),
              'slotStepMinutes',
                coalesce(booking_settings.interval_minutes, 30)
            ),
            'weeklyAvailableMinutes', (
              select coalesce(
                sum(
                  extract(
                    epoch from (service_rule.end_time - service_rule.start_time)
                  ) / 60
                ),
                0
              )::integer
              from public.availability_rules as service_rule
              where service_rule.therapist_profile_id = v_therapist.id
                and service_rule.is_active
                and service_rule.service_id = service.id
            )
          )
          order by service.created_at, service.id
        ),
        '[]'::jsonb
      )
      from public.therapist_services as service
      left join public.therapist_service_booking_settings as booking_settings
        on booking_settings.service_id = service.id
      where service.therapist_profile_id = v_therapist.id
        and service.status <> 'archived'
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_schedule_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_schedule_v1"() IS 'A3 versioned therapist schedule read model derived from auth.uid().';



CREATE OR REPLACE FUNCTION "public"."get_therapist_service_request_replay_v1"("p_therapist_profile_id" "uuid", "p_request_id" "uuid", "p_operation" "text", "p_payload_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_existing public.therapist_service_mutation_requests%rowtype;
begin
  select *
    into v_existing
  from public.therapist_service_mutation_requests
  where therapist_profile_id = p_therapist_profile_id
    and request_id = p_request_id
  for update;

  if not found then
    return null;
  end if;

  if v_existing.operation <> p_operation
    or v_existing.payload_hash <> p_payload_hash then
    raise exception 'THERAPIST_SERVICE_IDEMPOTENCY_CONFLICT'
      using errcode = 'P0001';
  end if;

  return jsonb_set(v_existing.response, '{idempotentReplay}', 'true'::jsonb, true);
end;
$$;


ALTER FUNCTION "public"."get_therapist_service_request_replay_v1"("p_therapist_profile_id" "uuid", "p_request_id" "uuid", "p_operation" "text", "p_payload_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_therapist_session_detail_v1"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_session public.therapist_session_read_model_v1%rowtype;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = (select auth.uid())
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  select *
    into v_session
  from public.therapist_session_read_model_v1
  where "bookingId" = p_booking_id
    and "_therapistProfileId" = v_therapist.id;

  if not found then
    return null;
  end if;

  return (
    to_jsonb(v_session)
    - '_therapistProfileId'
    - '_videoSessionReady'
  ) || jsonb_build_object(
    'version', 1,
    'therapistProfileId', v_therapist.id,
    'zoomAccess',
    public.build_video_session_access_state_v1(
      v_session."bookingStatus",
      v_session."financialStatus",
      v_session."startsAt",
      v_session."endsAt",
      v_session."videoSessionStatus",
      v_session."_videoSessionReady",
      now()
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_session_detail_v1"("p_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_session_detail_v1"("p_booking_id" "uuid") IS 'Private-safe therapist session detail. Returns null for missing or non-owned bookings and never exposes Zoom host credentials.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_session_evolution_comparison_v1"("p_period_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_current_local_end date;
  v_current_local_start date;
  v_previous_local_start date;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_previous_start timestamptz;
  v_current_completed bigint := 0;
  v_previous_completed bigint := 0;
begin
  if p_period_days not in (30, 60, 90, 120) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select therapist.*
    into v_therapist
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = '42501';
  end if;

  if v_therapist.plan not in (
    'premium'::public.therapist_plan,
    'premium_plus'::public.therapist_plan
  ) then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  if v_timezone is null then
    raise exception 'UNAVAILABLE' using errcode = 'P0001';
  end if;

  v_current_local_end := (now() at time zone v_timezone)::date;
  v_current_local_start := v_current_local_end - p_period_days;
  v_previous_local_start := v_current_local_start - p_period_days;
  v_current_start := v_current_local_start::timestamp at time zone v_timezone;
  v_current_end := v_current_local_end::timestamp at time zone v_timezone;
  v_previous_start := v_previous_local_start::timestamp at time zone v_timezone;

  select
    count(*) filter (where booking.starts_at >= v_current_start),
    count(*) filter (where booking.starts_at < v_current_start)
    into v_current_completed, v_previous_completed
  from public.bookings as booking
  where booking.therapist_profile_id = v_therapist.id
    and booking.status = 'completed'
    and booking.starts_at >= v_previous_start
    and booking.starts_at < v_current_end;

  return jsonb_build_object(
    'contractVersion', 1,
    'metricDefinitionVersion', 1,
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'plan', v_therapist.plan
    ),
    'meta', jsonb_build_object(
      'timezone', v_timezone,
      'periodDays', p_period_days,
      'periodStart', v_current_start,
      'periodEnd', v_current_end,
      'previousPeriodStart', v_previous_start,
      'previousPeriodEnd', v_current_start,
      'computedAt', now(),
      'freshThrough', v_current_end
    ),
    'status', case
      when v_current_completed = 0 and v_previous_completed = 0 then 'empty'
      else 'ready'
    end,
    'points', (
      with completed_by_day as (
        select
          (booking.starts_at at time zone v_timezone)::date as metric_date,
          count(*)::integer as completed_count
        from public.bookings as booking
        where booking.therapist_profile_id = v_therapist.id
          and booking.status = 'completed'
          and booking.starts_at >= v_previous_start
          and booking.starts_at < v_current_end
        group by (booking.starts_at at time zone v_timezone)::date
      )
      select jsonb_agg(
        jsonb_build_object(
          'index', day_offset.value,
          'currentDate', v_current_local_start + day_offset.value,
          'previousDate', v_previous_local_start + day_offset.value,
          'current', coalesce(current_day.completed_count, 0),
          'previous', coalesce(previous_day.completed_count, 0)
        )
        order by day_offset.value
      )
      from generate_series(0, p_period_days - 1) as day_offset(value)
      left join completed_by_day as current_day
        on current_day.metric_date = v_current_local_start + day_offset.value
      left join completed_by_day as previous_day
        on previous_day.metric_date = v_previous_local_start + day_offset.value
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_session_evolution_comparison_v1"("p_period_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_session_evolution_comparison_v1"("p_period_days" integer) IS 'Returns aligned aggregate completed-session series for the selected complete period and its immediately preceding period. Uses auth.uid(), contains no patient identifiers and supports 30, 60, 90 and 120 complete days.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_session_metrics_v1"("p_period_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_current_local_end date;
  v_current_local_start date;
  v_previous_local_start date;
  v_current_start timestamptz;
  v_current_end timestamptz;
  v_previous_start timestamptz;
  v_current_completed bigint := 0;
  v_previous_completed bigint := 0;
  v_current_cancelled bigint := 0;
  v_previous_cancelled bigint := 0;
  v_current_no_shows bigint := 0;
  v_previous_no_shows bigint := 0;
  v_current_reschedules bigint := 0;
  v_previous_reschedules bigint := 0;
  v_current_average_minutes bigint := 0;
  v_previous_average_minutes bigint := 0;
  v_current_presence_sample bigint := 0;
  v_previous_presence_sample bigint := 0;
  v_current_outcome_sample bigint := 0;
begin
  if p_period_days not in (30, 60, 90, 120) then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  if v_actor_user_id is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select therapist.*
    into v_therapist
  from public.therapist_profiles as therapist
  join public.profiles as profile
    on profile.id = therapist.user_id
  where therapist.user_id = v_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'PROFILE_LOCKED' using errcode = '42501';
  end if;

  if v_therapist.plan not in (
    'premium'::public.therapist_plan,
    'premium_plus'::public.therapist_plan
  ) then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = v_therapist.id;

  if v_timezone is null then
    raise exception 'UNAVAILABLE' using errcode = 'P0001';
  end if;

  v_current_local_end := (now() at time zone v_timezone)::date;
  v_current_local_start := v_current_local_end - p_period_days;
  v_previous_local_start := v_current_local_start - p_period_days;
  v_current_start := v_current_local_start::timestamp at time zone v_timezone;
  v_current_end := v_current_local_end::timestamp at time zone v_timezone;
  v_previous_start := v_previous_local_start::timestamp at time zone v_timezone;

  select
    count(*) filter (
      where booking.starts_at >= v_current_start
        and booking.status = 'completed'
    ),
    count(*) filter (
      where booking.starts_at < v_current_start
        and booking.status = 'completed'
    ),
    count(*) filter (
      where booking.starts_at >= v_current_start
        and booking.status in (
          'cancelled_by_patient',
          'cancelled_by_therapist'
        )
    ),
    count(*) filter (
      where booking.starts_at < v_current_start
        and booking.status in (
          'cancelled_by_patient',
          'cancelled_by_therapist'
        )
    ),
    count(*) filter (
      where booking.starts_at >= v_current_start
        and booking.status in ('no_show_patient', 'no_show_therapist')
    ),
    count(*) filter (
      where booking.starts_at < v_current_start
        and booking.status in ('no_show_patient', 'no_show_therapist')
    ),
    coalesce(round(avg(booking.service_duration_minutes_snapshot) filter (
      where booking.starts_at >= v_current_start
        and booking.status = 'completed'
    )), 0),
    coalesce(round(avg(booking.service_duration_minutes_snapshot) filter (
      where booking.starts_at < v_current_start
        and booking.status = 'completed'
    )), 0)
    into
      v_current_completed,
      v_previous_completed,
      v_current_cancelled,
      v_previous_cancelled,
      v_current_no_shows,
      v_previous_no_shows,
      v_current_average_minutes,
      v_previous_average_minutes
  from public.bookings as booking
  where booking.therapist_profile_id = v_therapist.id
    and booking.starts_at >= v_previous_start
    and booking.starts_at < v_current_end;

  select
    count(*) filter (
      where request.applied_at >= v_current_start
    ),
    count(*) filter (
      where request.applied_at < v_current_start
    )
    into v_current_reschedules, v_previous_reschedules
  from public.booking_reschedule_requests as request
  join public.bookings as booking
    on booking.id = request.booking_id
  where booking.therapist_profile_id = v_therapist.id
    and request.status = 'applied'
    and request.applied_at >= v_previous_start
    and request.applied_at < v_current_end;

  v_current_presence_sample := v_current_completed + v_current_no_shows;
  v_previous_presence_sample := v_previous_completed + v_previous_no_shows;
  v_current_outcome_sample :=
    v_current_completed + v_current_no_shows + v_current_cancelled;

  return jsonb_build_object(
    'contractVersion', 1,
    'metricDefinitionVersion', 1,
    'therapist', jsonb_build_object(
      'profileId', v_therapist.id,
      'plan', v_therapist.plan
    ),
    'meta', jsonb_build_object(
      'timezone', v_timezone,
      'periodDays', p_period_days,
      'periodStart', v_current_start,
      'periodEnd', v_current_end,
      'previousPeriodStart', v_previous_start,
      'previousPeriodEnd', v_current_start,
      'computedAt', now(),
      'freshThrough', v_current_end
    ),
    'summary', jsonb_build_object(
      'sessionsCompleted', public.therapist_metric_counter_v1(
        v_current_completed,
        v_previous_completed,
        'therapist_metrics.sessions_completed',
        'sessions'
      ),
      'operationalPresence', public.therapist_metric_rate_v1(
        v_current_completed,
        v_current_presence_sample,
        v_previous_completed,
        v_previous_presence_sample,
        'therapist_metrics.operational_presence',
        10
      ),
      'sessionsCancelled', public.therapist_metric_counter_v1(
        v_current_cancelled,
        v_previous_cancelled,
        'therapist_metrics.sessions_cancelled',
        'sessions'
      ),
      'sessionsRescheduled', public.therapist_metric_counter_v1(
        v_current_reschedules,
        v_previous_reschedules,
        'therapist_metrics.sessions_rescheduled',
        'sessions'
      ),
      'reservedDurationAverage', public.therapist_metric_counter_v1(
        v_current_average_minutes,
        v_previous_average_minutes,
        'therapist_metrics.reserved_duration_average',
        'minutes'
      )
    ),
    'outcomeDistribution', jsonb_build_object(
      'status', case
        when v_current_outcome_sample = 0 then 'empty'
        when v_current_outcome_sample < 10 then 'insufficient_sample'
        else 'ready'
      end,
      'minimumSample', 10,
      'observedSample', v_current_outcome_sample,
      'items', case
        when v_current_outcome_sample < 10 then '[]'::jsonb
        else (
          with outcome_keys(key, label, sort_order) as (
            values
              ('completed', 'Compareceram', 1),
              ('no_show_patient', 'Ausência da pessoa atendida', 2),
              ('no_show_therapist', 'Ausência do terapeuta', 3),
              ('cancelled_by_patient', 'Canceladas pela pessoa atendida', 4),
              ('cancelled_by_therapist', 'Canceladas pelo terapeuta', 5)
          ),
          outcome_counts as (
            select booking.status::text as key, count(*)::bigint as value
            from public.bookings as booking
            where booking.therapist_profile_id = v_therapist.id
              and booking.starts_at >= v_current_start
              and booking.starts_at < v_current_end
              and booking.status in (
                'completed',
                'no_show_patient',
                'no_show_therapist',
                'cancelled_by_patient',
                'cancelled_by_therapist'
              )
            group by booking.status
          )
          select jsonb_agg(
            jsonb_build_object(
              'key', outcome_keys.key,
              'label', outcome_keys.label,
              'value', coalesce(outcome_counts.value, 0),
              'percentage', round(
                coalesce(outcome_counts.value, 0)::numeric
                  * 100 / v_current_outcome_sample,
                1
              )
            )
            order by outcome_keys.sort_order
          )
          from outcome_keys
          left join outcome_counts using (key)
        )
      end
    ),
    'evolution', jsonb_build_object(
      'status', case
        when v_current_outcome_sample = 0 and v_current_reschedules = 0
          then 'empty'
        else 'ready'
      end,
      'points', (
        select coalesce(
          jsonb_agg(
            jsonb_build_object(
              'date', day.metric_date::date,
              'sessionsCompleted', coalesce(outcomes.completed_count, 0),
              'sessionsCancelled', coalesce(outcomes.cancelled_count, 0),
              'noShows', coalesce(outcomes.no_show_count, 0),
              'sessionsRescheduled', coalesce(reschedules.rescheduled_count, 0)
            )
            order by day.metric_date
          ),
          '[]'::jsonb
        )
        from generate_series(
          v_current_local_start,
          v_current_local_end - 1,
          interval '1 day'
        ) as day(metric_date)
        left join (
          select
            (booking.starts_at at time zone v_timezone)::date as metric_date,
            count(*) filter (
              where booking.status = 'completed'
            )::integer as completed_count,
            count(*) filter (
              where booking.status in (
                'cancelled_by_patient',
                'cancelled_by_therapist'
              )
            )::integer as cancelled_count,
            count(*) filter (
              where booking.status in (
                'no_show_patient',
                'no_show_therapist'
              )
            )::integer as no_show_count
          from public.bookings as booking
          where booking.therapist_profile_id = v_therapist.id
            and booking.starts_at >= v_current_start
            and booking.starts_at < v_current_end
          group by (booking.starts_at at time zone v_timezone)::date
        ) as outcomes
          on outcomes.metric_date = day.metric_date::date
        left join (
          select
            (request.applied_at at time zone v_timezone)::date as metric_date,
            count(*)::integer as rescheduled_count
          from public.booking_reschedule_requests as request
          join public.bookings as booking
            on booking.id = request.booking_id
          where booking.therapist_profile_id = v_therapist.id
            and request.status = 'applied'
            and request.applied_at >= v_current_start
            and request.applied_at < v_current_end
          group by (request.applied_at at time zone v_timezone)::date
        ) as reschedules
          on reschedules.metric_date = day.metric_date::date
      )
    ),
    'heatmap', jsonb_build_object(
      'status', case
        when v_current_completed = 0 then 'empty'
        when v_current_completed < 10 then 'insufficient_sample'
        else 'ready'
      end,
      'minimumSample', 10,
      'observedSample', v_current_completed,
      'items', case
        when v_current_completed < 10 then '[]'::jsonb
        else (
          select coalesce(
            jsonb_agg(
              jsonb_build_object(
                'dayOfWeek', heat.day_of_week,
                'hourBucketStart', heat.hour_bucket_start,
                'sessions', heat.sessions
              )
              order by heat.day_of_week, heat.hour_bucket_start
            ),
            '[]'::jsonb
          )
          from (
            select
              extract(
                isodow from booking.starts_at at time zone v_timezone
              )::integer as day_of_week,
              (
                floor(
                  extract(hour from booking.starts_at at time zone v_timezone)
                    / 2
                ) * 2
              )::integer as hour_bucket_start,
              count(*)::integer as sessions
            from public.bookings as booking
            where booking.therapist_profile_id = v_therapist.id
              and booking.status = 'completed'
              and booking.starts_at >= v_current_start
              and booking.starts_at < v_current_end
            group by 1, 2
          ) as heat
        )
      end
    ),
    'presenceByDay', (
      with presence as (
        select
          extract(
            isodow from booking.starts_at at time zone v_timezone
          )::integer as day_of_week,
          count(*) filter (
            where booking.status = 'completed'
          )::bigint as completed_count,
          count(*)::bigint as sample
        from public.bookings as booking
        where booking.therapist_profile_id = v_therapist.id
          and booking.status in (
            'completed',
            'no_show_patient',
            'no_show_therapist'
          )
          and booking.starts_at >= v_current_start
          and booking.starts_at < v_current_end
        group by 1
      )
      select jsonb_build_object(
        'status', case
          when v_current_presence_sample = 0 then 'empty'
          when not exists (select 1 from presence where sample >= 10)
            then 'insufficient_sample'
          else 'ready'
        end,
        'minimumSample', 10,
        'observedSample', v_current_presence_sample,
        'items', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'dayOfWeek', day_of_week,
              'percentage', round(
                completed_count::numeric * 100 / sample,
                1
              ),
              'sample', sample
            )
            order by completed_count::numeric / sample desc, day_of_week
          )
          from presence
          where sample >= 10
        ), '[]'::jsonb)
      )
    ),
    'presenceByHour', (
      with presence as (
        select
          (
            floor(
              extract(hour from booking.starts_at at time zone v_timezone) / 2
            ) * 2
          )::integer as hour_bucket_start,
          count(*) filter (
            where booking.status = 'completed'
          )::bigint as completed_count,
          count(*)::bigint as sample
        from public.bookings as booking
        where booking.therapist_profile_id = v_therapist.id
          and booking.status in (
            'completed',
            'no_show_patient',
            'no_show_therapist'
          )
          and booking.starts_at >= v_current_start
          and booking.starts_at < v_current_end
        group by 1
      )
      select jsonb_build_object(
        'status', case
          when v_current_presence_sample = 0 then 'empty'
          when not exists (select 1 from presence where sample >= 10)
            then 'insufficient_sample'
          else 'ready'
        end,
        'minimumSample', 10,
        'observedSample', v_current_presence_sample,
        'items', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'hourBucketStart', hour_bucket_start,
              'percentage', round(
                completed_count::numeric * 100 / sample,
                1
              ),
              'sample', sample
            )
            order by completed_count::numeric / sample desc, hour_bucket_start
          )
          from presence
          where sample >= 10
        ), '[]'::jsonb)
      )
    ),
    'therapyDistribution', jsonb_build_object(
      'status', case
        when v_current_completed = 0 then 'empty'
        when v_current_completed < 10 then 'insufficient_sample'
        else 'ready'
      end,
      'minimumSample', 10,
      'observedSample', v_current_completed,
      'items', case
        when v_current_completed < 10 then '[]'::jsonb
        else (
          select coalesce(
            jsonb_agg(
              jsonb_build_object(
                'therapyId', therapy_count.therapy_id,
                'therapyName', therapy_count.therapy_name,
                'sessions', therapy_count.sessions,
                'percentage', round(
                  therapy_count.sessions::numeric
                    * 100 / v_current_completed,
                  1
                )
              )
              order by therapy_count.sessions desc, therapy_count.therapy_name
            ),
            '[]'::jsonb
          )
          from (
            select
              service.therapy_id,
              therapy.name as therapy_name,
              count(*)::integer as sessions
            from public.bookings as booking
            join public.therapist_services as service
              on service.id = booking.service_id
            join public.therapies as therapy
              on therapy.id = service.therapy_id
            where booking.therapist_profile_id = v_therapist.id
              and booking.status = 'completed'
              and booking.starts_at >= v_current_start
              and booking.starts_at < v_current_end
            group by service.therapy_id, therapy.name
          ) as therapy_count
        )
      end
    ),
    'cancellationReasons', jsonb_build_object(
      'status', 'unavailable',
      'reason', 'cancellation_taxonomy_not_versioned'
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_session_metrics_v1"("p_period_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_session_metrics_v1"("p_period_days" integer) IS 'MTR-4 private session read model. Uses booking outcomes, immutable duration snapshots and applied reschedules; returns no patient identity or cancellation free text.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_sessions_v1"("p_limit" integer DEFAULT 20, "p_cursor_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_booking_id" "uuid" DEFAULT NULL::"uuid", "p_period_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_period_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_booking_status" "public"."booking_status" DEFAULT NULL::"public"."booking_status", "p_financial_status" "public"."session_financial_status" DEFAULT NULL::"public"."session_financial_status", "p_patient_profile_id" "uuid" DEFAULT NULL::"uuid", "p_service_id" "uuid" DEFAULT NULL::"uuid", "p_modality" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_timezone text;
  v_items jsonb;
  v_has_more boolean;
  v_next_cursor jsonb;
  v_summary jsonb;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = (select auth.uid())
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  if p_limit < 1 or p_limit > 100 then
    raise exception 'invalid_sessions_page_size' using errcode = '22023';
  end if;

  if (p_cursor_starts_at is null) <> (p_cursor_booking_id is null) then
    raise exception 'invalid_sessions_cursor' using errcode = '22023';
  end if;

  if p_period_start is not null
    and p_period_end is not null
    and p_period_start >= p_period_end
  then
    raise exception 'invalid_sessions_period' using errcode = '22023';
  end if;

  if p_modality is not null and p_modality <> 'online' then
    raise exception 'invalid_sessions_modality' using errcode = '22023';
  end if;

  v_timezone := coalesce(
    nullif(v_therapist.metadata ->> 'timezone', ''),
    'America/Sao_Paulo'
  );

  with scoped as (
    select session_row.*
    from public.therapist_session_read_model_v1 as session_row
    where session_row."_therapistProfileId" = v_therapist.id
      and (
        p_period_start is null
        or session_row."endsAt" > p_period_start
      )
      and (
        p_period_end is null
        or session_row."startsAt" < p_period_end
      )
      and (
        p_booking_status is null
        or session_row."bookingStatus" = p_booking_status
      )
      and (
        p_financial_status is null
        or session_row."financialStatus" = p_financial_status
      )
      and (
        p_patient_profile_id is null
        or session_row."patientProfileId" = p_patient_profile_id
      )
      and (
        p_service_id is null
        or session_row."serviceId" = p_service_id
      )
      and (
        p_modality is null
        or session_row.modality = 'online'
      )
  ), counts as (
    select
      count(*)::integer as total,
      count(*) filter (
        where "bookingStatus" = 'completed'::public.booking_status
          or "fulfillmentStatus" in (
            'confirmed_by_patient_review'::public.session_service_status,
            'confirmed_by_therapist'::public.session_service_status,
            'auto_confirmed'::public.session_service_status
          )
      )::integer as completed,
      count(*) filter (
        where "bookingStatus" = any (array[
          'cancelled_by_patient'::public.booking_status,
          'cancelled_by_therapist'::public.booking_status,
          'no_show_patient'::public.booking_status,
          'no_show_therapist'::public.booking_status,
          'cancelled_by_payment'::public.booking_status,
          'refunded'::public.booking_status
        ])
      )::integer as cancelled,
      count(*) filter (
        where "bookingStatus" = 'pending_payment'::public.booking_status
          or "financialStatus" is null
          or "financialStatus" = any (array[
            'pending'::public.session_financial_status,
            'processing'::public.session_financial_status,
            'failed'::public.session_financial_status,
            'disputed'::public.session_financial_status
          ])
          or "rescheduleStatus" = 'pending'
          or coalesce("cancellationRequiresReview", false)
      )::integer as pending,
      count(*) filter (
        where "bookingStatus" = 'confirmed'::public.booking_status
      )::integer as confirmed
    from scoped
  )
  select jsonb_build_object(
    'total', total,
    'completed', completed,
    'cancelled', cancelled,
    'pending', pending,
    'attendanceRate', case
      when confirmed > 0 then round(
        (completed::numeric / greatest(confirmed, completed)::numeric) * 100
      )::integer
      else null
    end
  )
  into v_summary
  from counts;

  with candidates as (
    select session_row.*
    from public.therapist_session_read_model_v1 as session_row
    where session_row."_therapistProfileId" = v_therapist.id
      and (
        p_cursor_starts_at is null
        or (
          session_row."startsAt",
          session_row."bookingId"
        ) < (
          p_cursor_starts_at,
          p_cursor_booking_id
        )
      )
      and (
        p_period_start is null
        or session_row."endsAt" > p_period_start
      )
      and (
        p_period_end is null
        or session_row."startsAt" < p_period_end
      )
      and (
        p_booking_status is null
        or session_row."bookingStatus" = p_booking_status
      )
      and (
        p_financial_status is null
        or session_row."financialStatus" = p_financial_status
      )
      and (
        p_patient_profile_id is null
        or session_row."patientProfileId" = p_patient_profile_id
      )
      and (
        p_service_id is null
        or session_row."serviceId" = p_service_id
      )
      and (
        p_modality is null
        or session_row.modality = 'online'
      )
    order by session_row."startsAt" desc, session_row."bookingId" desc
    limit p_limit + 1
  ),
  page as (
    select *
    from candidates
    order by "startsAt" desc, "bookingId" desc
    limit p_limit
  ),
  payload as (
    select
      page."startsAt",
      page."bookingId",
      (
        to_jsonb(page)
        - '_therapistProfileId'
        - '_videoSessionReady'
      ) || jsonb_build_object(
        'zoomAccess',
        public.build_video_session_access_state_v1(
          page."bookingStatus",
          page."financialStatus",
          page."startsAt",
          page."endsAt",
          page."videoSessionStatus",
          page."_videoSessionReady",
          now()
        )
      ) as item
    from page
  )
  select
    coalesce(
      jsonb_agg(item order by "startsAt" desc, "bookingId" desc),
      '[]'::jsonb
    ),
    (select count(*) > p_limit from candidates),
    (
      select jsonb_build_object(
        'startsAt', "startsAt",
        'bookingId', "bookingId"
      )
      from payload
      order by "startsAt" asc, "bookingId" asc
      limit 1
    )
  into v_items, v_has_more, v_next_cursor
  from payload;

  return jsonb_build_object(
    'version', 1,
    'therapistProfileId', v_therapist.id,
    'timezone', v_timezone,
    'items', v_items,
    'summary', v_summary,
    'page', jsonb_build_object(
      'limit', p_limit,
      'hasMore', coalesce(v_has_more, false),
      'nextCursor', case
        when coalesce(v_has_more, false) then v_next_cursor
        else null
      end
    ),
    'filters', jsonb_build_object(
      'periodStart', p_period_start,
      'periodEnd', p_period_end,
      'bookingStatus', p_booking_status,
      'financialStatus', p_financial_status,
      'patientProfileId', p_patient_profile_id,
      'serviceId', p_service_id,
      'modality', p_modality
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_sessions_v1"("p_limit" integer, "p_cursor_starts_at" timestamp with time zone, "p_cursor_booking_id" "uuid", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_booking_status" "public"."booking_status", "p_financial_status" "public"."session_financial_status", "p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_modality" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_sessions_v1"("p_limit" integer, "p_cursor_starts_at" timestamp with time zone, "p_cursor_booking_id" "uuid", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_booking_status" "public"."booking_status", "p_financial_status" "public"."session_financial_status", "p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_modality" "text") IS 'Therapist-scoped sessions read model with a server-side period summary for operational cards.';



CREATE OR REPLACE FUNCTION "public"."get_therapist_shell_counters_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = (select auth.uid())
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'version', 1,
    'therapistProfileId', v_therapist.id,
    'unreadMessages', (
      select count(*)
      from public.messages as message
      join public.conversations as conversation
        on conversation.id = message.conversation_id
      where conversation.therapist_profile_id = v_therapist.id
        and message.sender_profile_id <> (select auth.uid())
        and message.read_at is null
    ),
    'unreadNotifications', (
      select count(*)
      from public.notifications as notification
      where notification.profile_id = (select auth.uid())
        and notification.read_at is null
    ),
    'pendingRescheduleRequests', (
      select count(*)
      from public.booking_reschedule_requests as request
      join public.bookings as booking
        on booking.id = request.booking_id
      where booking.therapist_profile_id = v_therapist.id
        and request.status = 'pending'
    ),
    'pendingPayments', (
      select count(*)
      from public.bookings as booking
      left join public.session_payments as payment
        on payment.booking_id = booking.id
      where booking.therapist_profile_id = v_therapist.id
        and (
          payment.financial_status in ('pending', 'processing')
          or (
            payment.id is null
            and booking.status = 'pending_payment'
          )
        )
    ),
    'pendingReviewReplies', (
      select count(*)
      from public.reviews as review
      where review.therapist_profile_id = v_therapist.id
        and review.status = 'published'
        and not exists (
          select 1
          from public.review_replies as reply
          where reply.review_id = review.id
            and reply.status = 'published'
        )
    ),
    'impactedBookings', 0
  );
end;
$$;


ALTER FUNCTION "public"."get_therapist_shell_counters_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_therapist_shell_counters_v1"() IS 'Small plan-independent shell counter read model for every authorized therapist.';



CREATE OR REPLACE FUNCTION "public"."guard_payment_owned_booking_status_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_source text := coalesce(
    pg_catalog.current_setting('tes.booking_source', true),
    ''
  );
begin
  if new.status in ('cancelled_by_payment', 'refunded')
    and new.status is distinct from old.status
    and v_source <> 'payment_state' then
    raise exception 'PAYMENT_WORKFLOW_REQUIRED' using errcode = 'P0001';
  end if;

  if old.status = 'cancelled_by_payment'
    and new.status = 'pending_payment'
    and v_source <> 'payment_retry_claim' then
    raise exception 'PAYMENT_RETRY_CLAIM_REQUIRED' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_payment_owned_booking_status_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_payment_owned_booking_status_v1"() IS 'Restricts payment-owned booking states to trusted payment workflows.';



CREATE OR REPLACE FUNCTION "public"."guard_v10_payment_from_weekly_batch_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (
    select 1
    from public.session_payments as payment
    where payment.id = new.session_payment_id
      and payment.payment_flow_version = 'v10'
  ) then
    raise exception 'V10_DIRECT_TRANSFER_CANNOT_ENTER_WEEKLY_BATCH'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_v10_payment_from_weekly_batch_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_legacy_payment_projection"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_policy_id uuid;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  select *
    into v_booking
  from public.bookings
  where id = new.booking_id;

  select id
    into v_policy_id
  from public.financial_policy_versions
  where version = 'tes-legacy-import-v1';

  insert into public.session_payments (
    booking_id,
    patient_profile_id,
    therapist_profile_id,
    service_id,
    policy_version_id,
    stripe_checkout_session_id,
    stripe_payment_intent_id,
    gross_amount_cents,
    platform_commission_bps,
    platform_gross_commission_cents,
    therapist_amount_cents,
    currency,
    financial_status,
    transfer_status,
    transfer_blocked_reason,
    paid_at,
    failed_at,
    metadata,
    created_at,
    updated_at
  ) values (
    new.booking_id,
    new.patient_profile_id,
    new.therapist_profile_id,
    v_booking.service_id,
    v_policy_id,
    new.stripe_checkout_session_id,
    new.stripe_payment_intent_id,
    new.amount_cents,
    case
      when new.amount_cents > 0
        then floor(new.platform_fee_cents * 10000.0 / new.amount_cents)::integer
      else 0
    end,
    new.platform_fee_cents,
    new.therapist_amount_cents,
    new.currency,
    case new.status
      when 'not_started' then 'pending'::public.session_financial_status
      when 'pending' then 'processing'::public.session_financial_status
      when 'paid' then 'paid'::public.session_financial_status
      when 'failed' then 'failed'::public.session_financial_status
      when 'cancelled' then 'canceled'::public.session_financial_status
      when 'refunded' then 'refunded'::public.session_financial_status
      when 'partially_refunded' then 'partially_refunded'::public.session_financial_status
    end,
    case
      when new.status = 'paid' and new.stripe_payment_intent_id is not null
        then 'blocked'::public.session_transfer_status
      else 'not_eligible'::public.session_transfer_status
    end,
    case
      when new.status = 'paid' and new.stripe_payment_intent_id is not null
        then 'source_charge_reconciliation_required'
      else null
    end,
    new.paid_at,
    case when new.status = 'failed' then new.updated_at else null end,
    jsonb_build_object(
      'source', 'legacy_payments_projection_import',
      'legacyPaymentId', new.id
    ),
    new.created_at,
    new.updated_at
  )
  on conflict (booking_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."import_legacy_payment_projection"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_therapist_metric_daily_v1"("p_therapist_profile_id" "uuid", "p_metric_date" "date", "p_event_type" "text", "p_fresh_through" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.therapist_metric_daily_aggregates (
    therapist_profile_id,
    metric_date,
    definition_version,
    search_impressions,
    profile_views,
    booking_flow_starts,
    favorites_added,
    fresh_through
  )
  values (
    p_therapist_profile_id,
    p_metric_date,
    1,
    case when p_event_type = 'search_impression' then 1 else 0 end,
    case when p_event_type = 'profile_view' then 1 else 0 end,
    case when p_event_type = 'booking_flow_started' then 1 else 0 end,
    case when p_event_type = 'favorite_therapist_added' then 1 else 0 end,
    p_fresh_through
  )
  on conflict (
    therapist_profile_id,
    metric_date,
    definition_version
  )
  do update set
    search_impressions =
      public.therapist_metric_daily_aggregates.search_impressions
      + excluded.search_impressions,
    profile_views =
      public.therapist_metric_daily_aggregates.profile_views
      + excluded.profile_views,
    booking_flow_starts =
      public.therapist_metric_daily_aggregates.booking_flow_starts
      + excluded.booking_flow_starts,
    favorites_added =
      public.therapist_metric_daily_aggregates.favorites_added
      + excluded.favorites_added,
    fresh_through = greatest(
      public.therapist_metric_daily_aggregates.fresh_through,
      excluded.fresh_through
    ),
    updated_at = now();

  insert into public.therapist_profile_daily_analytics (
    therapist_profile_id,
    metric_date,
    profile_views,
    search_impressions,
    favorites_added
  )
  values (
    p_therapist_profile_id,
    p_metric_date,
    case when p_event_type = 'profile_view' then 1 else 0 end,
    case when p_event_type = 'search_impression' then 1 else 0 end,
    case when p_event_type = 'favorite_therapist_added' then 1 else 0 end
  )
  on conflict (therapist_profile_id, metric_date)
  do update set
    profile_views =
      public.therapist_profile_daily_analytics.profile_views
      + excluded.profile_views,
    search_impressions =
      public.therapist_profile_daily_analytics.search_impressions
      + excluded.search_impressions,
    favorites_added =
      public.therapist_profile_daily_analytics.favorites_added
      + excluded.favorites_added,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."increment_therapist_metric_daily_v1"("p_therapist_profile_id" "uuid", "p_metric_date" "date", "p_event_type" "text", "p_fresh_through" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_therapist_service_version_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if row(
    new.therapy_id,
    new.title,
    new.description,
    new.duration_minutes,
    new.price_cents,
    new.currency,
    new.status,
    new.online_only,
    new.delivery_format,
    new.is_bookable,
    new.position,
    new.archived_at
  ) is distinct from row(
    old.therapy_id,
    old.title,
    old.description,
    old.duration_minutes,
    old.price_cents,
    old.currency,
    old.status,
    old.online_only,
    old.delivery_format,
    old.is_bookable,
    old.position,
    old.archived_at
  ) then
    new.version = old.version + 1;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."increment_therapist_service_version_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_therapist_schedule_settings_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.therapist_schedule_settings (
    therapist_profile_id,
    timezone
  )
  values (new.id, 'America/Sao_Paulo')
  on conflict (therapist_profile_id) do nothing;

  update public.therapist_profiles
  set metadata = jsonb_set(
    coalesce(metadata, '{}'::jsonb),
    '{timezone}',
    '"America/Sao_Paulo"'::jsonb,
    true
  )
  where id = new.id
    and metadata ->> 'timezone' is distinct from 'America/Sao_Paulo';

  return new;
end;
$$;


ALTER FUNCTION "public"."initialize_therapist_schedule_settings_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_booking_reschedule_request_v1"("p_reschedule_request_id" "uuid", "p_actor_profile_id" "uuid", "p_request_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_request public.booking_reschedule_requests%rowtype;
begin
  if length(trim(coalesce(p_request_id, ''))) not between 8 and 200 then
    raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode = '22023';
  end if;

  select * into v_request
  from public.booking_reschedule_requests
  where id = p_reschedule_request_id
  for update;

  if not found then
    raise exception 'BOOKING_RESCHEDULE_NOT_FOUND' using errcode = 'P0002';
  end if;

  select * into v_booking from public.bookings where id = v_request.booking_id;

  if not public.is_booking_participant_profile_v1(
    v_request.booking_id,
    p_actor_profile_id
  ) then
    raise exception 'BOOKING_ACTOR_FORBIDDEN' using errcode = '42501';
  end if;

  if v_request.status = 'pending' then
    update public.booking_reschedule_requests
    set status = 'expired',
        resolved_by_profile_id = p_actor_profile_id,
        resolution_request_id = trim(p_request_id),
        resolved_at = now(),
        updated_at = now()
    where id = v_request.id
    returning * into v_request;

  end if;

  return pg_catalog.jsonb_build_object(
    'applied', false,
    'bookingId', v_booking.id,
    'bookingVersion', v_booking.version,
    'rescheduleRequestId', v_request.id,
    'status', v_request.status
  );
end;
$$;


ALTER FUNCTION "public"."invalidate_booking_reschedule_request_v1"("p_reschedule_request_id" "uuid", "p_actor_profile_id" "uuid", "p_request_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."invalidate_booking_reschedule_request_v1"("p_reschedule_request_id" "uuid", "p_actor_profile_id" "uuid", "p_request_id" "text") IS 'Closes a pending proposal whose slot became unavailable without moving or releasing the original booking.';



CREATE OR REPLACE FUNCTION "public"."is_booking_participant_profile_v1"("p_booking_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.bookings as booking
    join public.patient_profiles as patient
      on patient.id = booking.patient_profile_id
    join public.therapist_profiles as therapist
      on therapist.id = booking.therapist_profile_id
    where booking.id = p_booking_id
      and p_profile_id in (patient.user_id, therapist.user_id)
  );
$$;


ALTER FUNCTION "public"."is_booking_participant_profile_v1"("p_booking_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_booking_status_transition_allowed_v1"("p_current" "public"."booking_status", "p_next" "public"."booking_status") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_current
    when 'draft' then p_next in (
      'pending_payment', 'cancelled_by_patient', 'cancelled_by_payment'
    )
    when 'pending_payment' then p_next in (
      'confirmed', 'cancelled_by_patient', 'cancelled_by_payment', 'refunded'
    )
    when 'confirmed' then p_next in (
      'completed', 'cancelled_by_patient', 'cancelled_by_therapist',
      'cancelled_by_payment', 'no_show_patient', 'no_show_therapist', 'refunded'
    )
    when 'completed' then p_next = 'refunded'
    when 'cancelled_by_patient' then p_next = 'refunded'
    when 'cancelled_by_therapist' then p_next = 'refunded'
    when 'no_show_patient' then p_next = 'refunded'
    when 'no_show_therapist' then p_next = 'refunded'
    when 'cancelled_by_payment' then p_next = 'pending_payment'
    when 'refunded' then false
    else false
  end;
$$;


