CREATE OR REPLACE FUNCTION "public"."list_booking_reschedule_candidates_v1"("p_booking_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_reference_at" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 5000) RETURNS TABLE("starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "timezone" "text", "occupied_during" "tstzrange")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_horizon_days integer;
  v_min_notice integer;
  v_step integer;
begin
  if p_range_start is null
    or p_range_end is null
    or p_range_start >= p_range_end
    or p_range_end - p_range_start > interval '92 days'
    or p_limit not between 1 and 5000
  then
    raise exception 'INVALID_RESCHEDULE_RANGE' using errcode = '22023';
  end if;

  select booking.*
  into v_booking
  from public.bookings as booking
  where booking.id = p_booking_id
    and booking.status = 'confirmed'
    and exists (
      select 1 from public.therapist_profiles as therapist
      where therapist.id = booking.therapist_profile_id
        and therapist.status = 'approved'
    )
    and exists (
      select 1 from public.therapist_schedule_settings as schedule
      where schedule.therapist_profile_id = booking.therapist_profile_id
    );

  if not found then
    return;
  end if;

  select
    coalesce((select settings.min_notice_minutes from public.therapist_service_booking_settings as settings where settings.service_id = v_booking.service_id), 120),
    coalesce((select settings.max_days_ahead from public.therapist_service_booking_settings as settings where settings.service_id = v_booking.service_id), 90),
    coalesce((select settings.interval_minutes from public.therapist_service_booking_settings as settings where settings.service_id = v_booking.service_id), 30)
  into v_min_notice, v_horizon_days, v_step;

  return query
  with local_days as (
    select generated.local_day::date as local_day
    from pg_catalog.generate_series(
      (p_range_start at time zone v_booking.timezone)::date - 1,
      (p_range_end at time zone v_booking.timezone)::date + 1,
      interval '1 day'
    ) as generated(local_day)
  ),
  rule_windows as (
    select
      local_day.local_day + rule.start_time as local_start,
      local_day.local_day + rule.end_time as local_end
    from local_days as local_day
    join public.availability_rules as rule
      on rule.therapist_profile_id = v_booking.therapist_profile_id
     and rule.service_id = v_booking.service_id
     and rule.is_active
     and rule.day_of_week = extract(dow from local_day.local_day)::integer
  ),
  available_exception_windows as (
    select
      exception.starts_at at time zone v_booking.timezone as local_start,
      exception.ends_at at time zone v_booking.timezone as local_end
    from public.availability_exceptions as exception
    where exception.therapist_profile_id = v_booking.therapist_profile_id
      and exception.is_available
      and coalesce(exception.status, 'active') = 'active'
      and (exception.service_id is null or exception.service_id = v_booking.service_id)
      and exception.starts_at < p_range_end
      and exception.ends_at > p_range_start
  ),
  source_windows as (
    select local_start, local_end from rule_windows
    union
    select local_start, local_end from available_exception_windows
  ),
  local_candidates as (
    select generated.local_starts_at::timestamp as local_starts_at
    from source_windows as source_window
    cross join lateral pg_catalog.generate_series(
      source_window.local_start,
      source_window.local_end
        - v_booking.service_duration_minutes_snapshot * interval '1 minute',
      v_step * interval '1 minute'
    ) as generated(local_starts_at)
    where source_window.local_start <= source_window.local_end
      - v_booking.service_duration_minutes_snapshot * interval '1 minute'
  ),
  utc_candidates as (
    select distinct
      candidate.local_starts_at at time zone v_booking.timezone as starts_at,
      (candidate.local_starts_at at time zone v_booking.timezone)
        + v_booking.service_duration_minutes_snapshot * interval '1 minute' as ends_at,
      candidate.local_starts_at
    from local_candidates as candidate
  )
  select
    candidate.starts_at,
    candidate.ends_at,
    v_booking.timezone,
    pg_catalog.tstzrange(
      candidate.starts_at
        - v_booking.buffer_before_minutes_snapshot * interval '1 minute',
      candidate.ends_at
        + v_booking.buffer_after_minutes_snapshot * interval '1 minute',
      '[)'
    )
  from utc_candidates as candidate
  where candidate.starts_at >= p_range_start
    and candidate.ends_at <= p_range_end
    and candidate.starts_at >= p_reference_at + v_min_notice * interval '1 minute'
    and candidate.starts_at < p_reference_at + v_horizon_days * interval '1 day'
    and (candidate.starts_at at time zone v_booking.timezone) = candidate.local_starts_at
    and not exists (
      select 1
      from public.availability_exceptions as exception
      where exception.therapist_profile_id = v_booking.therapist_profile_id
        and not exception.is_available
        and coalesce(exception.status, 'active') = 'active'
        and (exception.service_id is null or exception.service_id = v_booking.service_id)
        and pg_catalog.tstzrange(exception.starts_at, exception.ends_at, '[)')
          && pg_catalog.tstzrange(candidate.starts_at, candidate.ends_at, '[)')
    )
  order by candidate.starts_at
  limit p_limit;
end;
$$;


ALTER FUNCTION "public"."list_booking_reschedule_candidates_v1"("p_booking_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_reference_at" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_due_session_payment_closures_v10"("p_now" timestamp with time zone, "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_items jsonb;
begin
  if p_now is null or p_limit not between 1 and 100 then
    raise exception 'SESSION_PAYMENT_CLOSURE_LIST_V10_INVALID' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'scheduleId', schedule.id,
    'scheduleStatus', schedule.status,
    'bookingId', booking.id,
    'bookingVersion', schedule.booking_version,
    'sessionPaymentId', payment.id,
    'stripeEnvironment', schedule.stripe_environment,
    'stripePaymentIntentId', schedule.stripe_payment_intent_id,
    'stripeCustomerId', setup.stripe_customer_id,
    'stripePaymentMethodId', setup.stripe_payment_method_id,
    'amountCents', payment.gross_amount_cents,
    'currency', payment.currency,
    'idempotencyKey', schedule.idempotency_key
  ) order by booking.starts_at, schedule.id), '[]'::jsonb)
  into v_items
  from (
    select s.id
    from public.session_payment_schedules s
    join public.bookings b on b.id = s.booking_id
    join public.session_payments p on p.id = s.session_payment_id
    where b.status = 'confirmed'
      and b.starts_at <= p_now
      and p.payment_flow_version = 'v10'
      and p.financial_status in ('pending', 'processing')
      and s.status in (
        'scheduled', 'claimed', 'processing', 'requires_customer_action',
        'retry_scheduled', 'failed'
      )
    order by b.starts_at, s.id
    limit p_limit
  ) candidate
  join public.session_payment_schedules schedule on schedule.id = candidate.id
  join public.bookings booking on booking.id = schedule.booking_id
  join public.session_payments payment on payment.id = schedule.session_payment_id
  join public.session_payment_setups setup on setup.id = schedule.session_payment_setup_id;
  return jsonb_build_object('items', v_items, 'observedAt', p_now);
end;
$$;


ALTER FUNCTION "public"."list_due_session_payment_closures_v10"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_private_therapist_services_v1"("p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
begin
  v_therapist := public.get_therapist_for_service_actor_v1(p_actor_user_id);

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', v_therapist.id,
    'plan', v_therapist.plan,
    'serviceLimit', public.therapist_service_limit_for_plan_v1(v_therapist.plan),
    'items', (
      select coalesce(
        jsonb_agg(
          public.service_row_to_private_json_v1(service.service_id)
          order by service.position, service.created_at, service.service_id
        ),
        '[]'::jsonb
      )
      from public.therapist_private_services_v1 as service
      where service.therapist_profile_id = v_therapist.id
    )
  );
end;
$$;


ALTER FUNCTION "public"."list_private_therapist_services_v1"("p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_recoverable_session_captures_v1"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 50) RETURNS TABLE("session_payment_id" "uuid", "stripe_payment_intent_id" "text", "slot_claimed_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    attempt.session_payment_id,
    attempt.stripe_payment_intent_id,
    attempt.slot_claimed_at
  from public.session_payment_attempts as attempt
  join public.session_payments as payment
    on payment.id = attempt.session_payment_id
   and payment.stripe_checkout_session_id = attempt.stripe_checkout_session_id
  where attempt.status = 'capture_pending'
    and attempt.slot_claimed_at is not null
    and attempt.slot_claimed_at <= p_now - interval '30 seconds'
    and attempt.stripe_payment_intent_id is not null
    and payment.financial_status = 'processing'
  order by attempt.slot_claimed_at
  limit greatest(1, least(coalesce(p_limit, 50), 100));
$$;


ALTER FUNCTION "public"."list_recoverable_session_captures_v1"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_recoverable_session_captures_v1"("p_now" timestamp with time zone, "p_limit" integer) IS 'Returns bounded current capture_pending attempts for Stripe reconciliation; service_role only.';



CREATE OR REPLACE FUNCTION "public"."list_service_schedule_candidates_v1"("p_service_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_reference_at" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 500) RETURNS TABLE("starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "timezone" "text", "occupied_during" "tstzrange")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_buffer_after integer;
  v_buffer_before integer;
  v_duration integer;
  v_horizon_days integer;
  v_min_notice integer;
  v_step integer;
  v_therapist_profile_id uuid;
  v_timezone text;
begin
  if p_range_start is null
    or p_range_end is null
    or p_range_start >= p_range_end
    or p_range_end - p_range_start > interval '62 days'
    or p_limit not between 1 and 1000
  then
    raise exception 'invalid_slot_range' using errcode = '22023';
  end if;

  select
    service.therapist_profile_id,
    service.duration_minutes,
    schedule_settings.timezone,
    coalesce(booking_settings.buffer_before_minutes, 0),
    coalesce(booking_settings.buffer_after_minutes, 0),
    coalesce(booking_settings.min_notice_minutes, 120),
    coalesce(booking_settings.max_days_ahead, 90),
    coalesce(booking_settings.interval_minutes, 30)
  into
    v_therapist_profile_id,
    v_duration,
    v_timezone,
    v_buffer_before,
    v_buffer_after,
    v_min_notice,
    v_horizon_days,
    v_step
  from public.therapist_services as service
  join public.therapist_profiles as therapist
    on therapist.id = service.therapist_profile_id
  join public.therapist_schedule_settings as schedule_settings
    on schedule_settings.therapist_profile_id = service.therapist_profile_id
  left join public.therapist_service_booking_settings as booking_settings
    on booking_settings.service_id = service.id
  where service.id = p_service_id
    and service.status = 'active'
    and therapist.status = 'approved'
    and therapist.is_accepting_bookings;

  if not found then
    return;
  end if;

  return query
  with local_days as (
    select generated.local_day::date as local_day
    from pg_catalog.generate_series(
      (p_range_start at time zone v_timezone)::date - 1,
      (p_range_end at time zone v_timezone)::date + 1,
      interval '1 day'
    ) as generated(local_day)
  ),
  rule_windows as (
    select
      local_day.local_day + rule.start_time as local_start,
      local_day.local_day + rule.end_time as local_end
    from local_days as local_day
    join public.availability_rules as rule
      on rule.therapist_profile_id = v_therapist_profile_id
      and rule.is_active
      and rule.day_of_week =
        extract(dow from local_day.local_day)::integer
      and rule.service_id = p_service_id
  ),
  available_exception_windows as (
    select
      exception.starts_at at time zone v_timezone as local_start,
      exception.ends_at at time zone v_timezone as local_end
    from public.availability_exceptions as exception
    where exception.therapist_profile_id = v_therapist_profile_id
      and exception.is_available
      and coalesce(exception.status, 'active') = 'active'
      and (exception.service_id is null or exception.service_id = p_service_id)
      and exception.starts_at < p_range_end
      and exception.ends_at > p_range_start
  ),
  source_windows as (
    select local_start, local_end from rule_windows
    union
    select local_start, local_end from available_exception_windows
  ),
  local_candidates as (
    select generated.local_starts_at::timestamp as local_starts_at
    from source_windows as source_window
    cross join lateral pg_catalog.generate_series(
      source_window.local_start,
      source_window.local_end
        - v_duration * interval '1 minute',
      v_step * interval '1 minute'
    ) as generated(local_starts_at)
    where source_window.local_start
      <= source_window.local_end
        - v_duration * interval '1 minute'
  ),
  utc_candidates as (
    select distinct
      local_candidate.local_starts_at at time zone v_timezone as starts_at,
      (
        local_candidate.local_starts_at at time zone v_timezone
      ) + v_duration * interval '1 minute' as ends_at,
      local_candidate.local_starts_at
    from local_candidates as local_candidate
  )
  select
    candidate.starts_at,
    candidate.ends_at,
    v_timezone,
    pg_catalog.tstzrange(
      candidate.starts_at - v_buffer_before * interval '1 minute',
      candidate.ends_at + v_buffer_after * interval '1 minute',
      '[)'
    )
  from utc_candidates as candidate
  where candidate.starts_at >= p_range_start
    and candidate.ends_at <= p_range_end
    and candidate.starts_at
      >= p_reference_at + v_min_notice * interval '1 minute'
    and candidate.starts_at
      < p_reference_at + v_horizon_days * interval '1 day'
    and (candidate.starts_at at time zone v_timezone)
      = candidate.local_starts_at
    and not exists (
      select 1
      from public.availability_exceptions as exception
      where exception.therapist_profile_id = v_therapist_profile_id
        and not exception.is_available
        and coalesce(exception.status, 'active') = 'active'
        and (
          exception.service_id is null
          or exception.service_id = p_service_id
        )
        and pg_catalog.tstzrange(
          exception.starts_at,
          exception.ends_at,
          '[)'
        ) && pg_catalog.tstzrange(candidate.starts_at, candidate.ends_at, '[)')
    )
  order by candidate.starts_at
  limit p_limit;
end;
$$;


ALTER FUNCTION "public"."list_service_schedule_candidates_v1"("p_service_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_reference_at" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_service_schedule_candidates_v1"("p_service_id" "uuid", "p_range_start" timestamp with time zone, "p_range_end" timestamp with time zone, "p_reference_at" timestamp with time zone, "p_limit" integer) IS 'Authoritative service-scoped candidate generator. Session starts are anchored to each availability window; buffers expand therapist-global occupancy and the after buffer must fit before the window end.';



