CREATE OR REPLACE FUNCTION "public"."mark_payout_window_incomplete_v1"("p_run_id" "uuid", "p_now" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.payout_scheduler_runs%rowtype;
begin
  select * into v_run from public.payout_scheduler_runs
  where id = p_run_id for update;
  if not found or v_run.status <> 'running' then return false; end if;
  if (p_now at time zone 'America/Sao_Paulo')::time < time '04:00'
    or v_run.window_alerted_at is not null
  then return false; end if;
  update public.payout_scheduler_runs
  set window_alerted_at = p_now, updated_at = now()
  where id = v_run.id;
  perform public.record_payout_operational_incident_v1(
    'scheduler:' || v_run.id::text || ':window_incomplete',
    'batch_incomplete_after_window', 'warning',
    'processing_window_closed', 'Lote ainda em processamento apos a janela inicial.',
    v_run.id, v_run.payout_batch_id
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."mark_payout_window_incomplete_v1"("p_run_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_structured_participant_messages_read_v1"("p_conversation_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_updated integer := 0;
begin
  if auth.uid() is null then
    raise exception 'authenticated participant required' using errcode = '42501';
  end if;

  if p_conversation_id is null or not exists (
    select 1
    from public.conversations conversations
    left join public.patient_profiles patients
      on patients.id = conversations.patient_profile_id
    left join public.therapist_profiles therapists
      on therapists.id = conversations.therapist_profile_id
    where conversations.id = p_conversation_id
      and (patients.user_id = auth.uid() or therapists.user_id = auth.uid())
  ) then
    raise exception 'conversation participant required' using errcode = '42501';
  end if;

  update public.messages
  set read_at = now()
  where conversation_id = p_conversation_id
    and sender_profile_id <> auth.uid()
    and read_at is null;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


