COMMENT ON FUNCTION "public"."mark_structured_participant_messages_read_v1"("p_conversation_id" "uuid") IS 'Marks only received structured messages in an authenticated conversation as read.';



CREATE OR REPLACE FUNCTION "public"."mark_video_session_termination_confirmed_v1"("p_video_session_id" "uuid", "p_reason" "text" DEFAULT 'provider_ended'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_reason text;
begin
  if p_reason not in ('scheduled_end', 'hard_timeout', 'manual_end', 'provider_ended', 'patient_no_show') then
    return;
  end if;

  select case
      when termination_reason = 'manual_end' and termination_requested_at is not null then 'manual_end'
      when termination_reason = 'patient_no_show' and termination_requested_at is not null then 'patient_no_show'
      when hard_ends_at is not null and hard_ends_at <= now() then 'hard_timeout'
      when scheduled_ends_at <= now() then 'scheduled_end'
      else null
    end
  into v_reason
  from public.video_sessions
  where id = p_video_session_id and status <> 'canceled'
    and termination_confirmed_at is null
  for update;

  if v_reason is null then return; end if;

  update public.video_sessions
  set status = 'ended', actual_ended_at = coalesce(actual_ended_at, now()),
      therapist_present = false, participant_count = 0,
      termination_reason = v_reason,
      termination_requested_at = coalesce(termination_requested_at, now()),
      termination_confirmed_at = coalesce(termination_confirmed_at, now()),
      last_maintenance_at = now(), last_synced_at = now(), updated_at = now()
  where id = p_video_session_id and status <> 'canceled'
    and termination_confirmed_at is null;
end;
$$;


ALTER FUNCTION "public"."mark_video_session_termination_confirmed_v1"("p_video_session_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_video_session_termination_confirmed_v1"("p_video_session_id" "uuid", "p_reason" "text") IS 'Confirms logical termination only after an authorized terminal reason, including verified patient no-show.';



CREATE OR REPLACE FUNCTION "public"."mark_video_session_termination_requested_v1"("p_video_session_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_reason = 'scheduled_end' then
    update public.video_sessions set termination_reason = 'scheduled_end',
      termination_requested_at = coalesce(termination_requested_at, now()),
      last_maintenance_at = now(), updated_at = now()
    where id = p_video_session_id and scheduled_ends_at <= now()
      and termination_confirmed_at is null;
  elsif p_reason = 'hard_timeout' then
    update public.video_sessions set termination_reason = 'hard_timeout',
      termination_requested_at = coalesce(termination_requested_at, now()),
      last_maintenance_at = now(), updated_at = now()
    where id = p_video_session_id and hard_ends_at is not null
      and hard_ends_at <= now() and termination_confirmed_at is null;
  elsif p_reason = 'patient_no_show' then
    update public.video_sessions session
    set termination_reason = 'patient_no_show',
        termination_requested_at = coalesce(session.termination_requested_at, now()),
        last_maintenance_at = now(), updated_at = now()
    from public.bookings booking
    where session.id = p_video_session_id
      and booking.id = session.booking_id
      and session.status = 'active'
      and session.scheduled_starts_at = booking.starts_at
      and session.scheduled_ends_at = booking.ends_at
      and booking.status = 'confirmed'::public.booking_status
      and booking.starts_at + interval '10 minutes' < now()
      and booking.ends_at > now()
      and session.termination_confirmed_at is null
      and not exists (
        select 1 from public.booking_events event
        where event.booking_id = booking.id
          and event.event_type = 'zoom_waiting_room_entered'
          and event.payload ->> 'bookingVersion' = booking.version::text
          and event.payload ->> 'scheduledStartsAt' = booking.starts_at::text
      )
      and not exists (
        select 1 from public.video_session_participations participation
        where participation.video_session_id = session.id
          and participation.participant_role = 'patient'::public.video_session_participant_role
          and participation.event_type = 'session.user_joined'
      );
  elsif p_reason = 'manual_end' then
    update public.video_sessions set last_maintenance_at = now(), updated_at = now()
    where id = p_video_session_id and termination_reason = 'manual_end'
      and termination_requested_at is not null and termination_confirmed_at is null;
  elsif p_reason = 'provider_ended' then
    update public.video_sessions
    set termination_reason = case when hard_ends_at is not null and hard_ends_at <= now()
          then 'hard_timeout' else 'scheduled_end' end,
        termination_requested_at = coalesce(termination_requested_at, now()),
        last_maintenance_at = now(), updated_at = now()
    where id = p_video_session_id
      and (scheduled_ends_at <= now() or (hard_ends_at is not null and hard_ends_at <= now()))
      and termination_confirmed_at is null;
  end if;
end;
$$;


ALTER FUNCTION "public"."mark_video_session_termination_requested_v1"("p_video_session_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_video_session_termination_requested_v1"("p_video_session_id" "uuid", "p_reason" "text") IS 'Creates termination fences only for authorized manual, scheduled, hard-timeout, or verified patient-no-show termination.';



CREATE OR REPLACE FUNCTION "public"."mirror_therapy_catalog_event_to_admin_audit_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.actor_role <> 'admin' or new.actor_profile_id is null then
    return new;
  end if;

  perform public.record_admin_audit_event_v1(
    new.actor_profile_id,
    new.actor_role::text,
    public.admin_permission_for_therapy_catalog_event_v1(new.event_type),
    new.event_type,
    new.entity_type,
    new.entity_id::text,
    public.admin_audit_json_object_v1(new.previous_state),
    public.admin_audit_json_object_v1(new.next_state),
    new.reason,
    new.request_id::text,
    new.correlation_id::text,
    'therapy_catalog_events'
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."mirror_therapy_catalog_event_to_admin_audit_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mirror_therapy_catalog_event_to_admin_audit_v1"() IS 'Internal trigger that mirrors admin Therapy Catalog / Match domain events into admin_audit_events. Does not expose secrets or raw request payloads.';



CREATE OR REPLACE FUNCTION "public"."next_booking_session_reference_v1"("p_created_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_local_created_at timestamp;
  v_month smallint;
  v_sequence integer;
  v_year smallint;
begin
  if p_created_at is null then
    raise exception 'session_reference_created_at_required' using errcode = '22004';
  end if;

  v_local_created_at := p_created_at at time zone 'America/Sao_Paulo';
  v_year := mod(extract(year from v_local_created_at)::integer, 100)::smallint;
  v_month := extract(month from v_local_created_at)::smallint;

  insert into public.booking_session_reference_counters as counter (
    reference_year,
    reference_month,
    last_sequence
  )
  values (v_year, v_month, 1)
  on conflict (reference_year, reference_month) do update
    set last_sequence = counter.last_sequence + 1
    where counter.last_sequence < 999999
  returning last_sequence into v_sequence;

  if not found then
    raise exception 'session_reference_capacity_exhausted' using errcode = 'P0001';
  end if;

  return lpad(v_year::text, 2, '0')
    || public.booking_session_reference_month_code_v1(p_created_at)
    || lpad(v_sequence::text, 6, '0');
end;
$$;


ALTER FUNCTION "public"."next_booking_session_reference_v1"("p_created_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_weekly_payout_cutoff_v1"("p_eligible_at" timestamp with time zone, "p_now" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_weekday integer;
  v_time time;
  v_timezone text;
  v_reference timestamptz;
  v_local_date date;
  v_days_ahead integer;
  v_candidate timestamptz;
begin
  if p_eligible_at is null then return null; end if;

  select policy.weekly_batch_weekday, policy.weekly_batch_time, policy.timezone
  into v_weekday, v_time, v_timezone
  from public.financial_policy_versions policy
  where policy.is_active
  order by policy.effective_from desc
  limit 1;

  v_weekday := coalesce(v_weekday, 2);
  v_time := coalesce(v_time, time '10:00');
  v_timezone := coalesce(v_timezone, 'America/Sao_Paulo');
  v_reference := greatest(p_eligible_at, p_now);
  v_local_date := (v_reference at time zone v_timezone)::date;
  v_days_ahead := (v_weekday - extract(dow from v_local_date)::integer + 7) % 7;
  v_candidate := (v_local_date + v_days_ahead + v_time) at time zone v_timezone;

  if v_candidate < v_reference then
    v_candidate := v_candidate + interval '7 days';
  end if;
  return v_candidate;
end;
$$;


ALTER FUNCTION "public"."next_weekly_payout_cutoff_v1"("p_eligible_at" timestamp with time zone, "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_private_therapist_finance_period_v1"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT NULL::"text") RETURNS TABLE("period_start" "date", "period_end" "date", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "timezone" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_period_start date;
  v_period_end date;
begin
  select name
    into v_timezone
  from pg_catalog.pg_timezone_names
  where name = coalesce(nullif(p_timezone, ''), 'America/Sao_Paulo')
  limit 1;

  if v_timezone is null then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  v_period_end := coalesce(p_period_end, (now() at time zone v_timezone)::date);
  v_period_start := coalesce(p_period_start, v_period_end - 30);

  if v_period_start > v_period_end
    or v_period_end - v_period_start > 366 then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  period_start := v_period_start;
  period_end := v_period_end;
  starts_at := v_period_start::timestamp at time zone v_timezone;
  ends_at := (v_period_end + 1)::timestamp at time zone v_timezone;
  timezone := v_timezone;
  return next;
end;
$$;


ALTER FUNCTION "public"."normalize_private_therapist_finance_period_v1"("p_period_start" "date", "p_period_end" "date", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_therapist_public_slug_v1"("p_slug" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select trim(both '-' from regexp_replace(
    regexp_replace(
      lower(public.unaccent(btrim(coalesce(p_slug, '')))),
      '[^a-z0-9]+', '-', 'g'
    ),
    '-+', '-', 'g'
  ))
$$;


ALTER FUNCTION "public"."normalize_therapist_public_slug_v1"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_booking_lifecycle_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_patient_user_id uuid;
  v_requester_user_id uuid;
  v_therapist_user_id uuid;
  v_status text;
begin
  if not (
    (new.event_type = 'booking_status_changed'
      and new.next_status::text in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded'))
    or new.event_type in ('booking_reschedule_requested', 'booking_reschedule_resolved')
  ) then
    return new;
  end if;

  select patient.user_id, therapist.user_id
  into v_patient_user_id, v_therapist_user_id
  from public.bookings as booking
  join public.patient_profiles as patient on patient.id = booking.patient_profile_id
  join public.therapist_profiles as therapist on therapist.id = booking.therapist_profile_id
  where booking.id = new.booking_id;

  if new.event_type like 'booking_reschedule_%' then
    select requested_by_profile_id into v_requester_user_id
    from public.booking_reschedule_requests
    where id = (new.payload ->> 'rescheduleRequestId')::uuid;
  end if;

  if new.event_type = 'booking_status_changed' then
    insert into public.notifications (profile_id, kind, title, body, href, event_key)
    values
      (v_patient_user_id, 'booking_cancelled_patient', 'Seu encontro foi cancelado',
        'O cancelamento foi concluído. Consulte os detalhes atualizados.',
        '/app/encontros/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':patient'),
      (v_therapist_user_id, 'booking_cancelled_therapist', 'Sessão cancelada',
        'O cancelamento foi concluído e sua agenda foi atualizada.',
        '/terapeuta/sessoes/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':therapist')
    on conflict (profile_id, event_key) where event_key is not null do nothing;
    return new;
  end if;

  v_status := coalesce(new.payload ->> 'status', 'pending');

  if new.event_type = 'booking_reschedule_requested' then
    if v_requester_user_id = v_patient_user_id then
      insert into public.notifications (profile_id, kind, title, body, href, event_key)
      values (v_therapist_user_id, 'booking_reschedule_requested_therapist',
        'Nova proposta de reagendamento',
        'Uma pessoa propôs outro horário para a sessão. Revise a solicitação.',
        '/terapeuta/sessoes/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':therapist')
      on conflict (profile_id, event_key) where event_key is not null do nothing;
    else
      insert into public.notifications (profile_id, kind, title, body, href, event_key)
      values (v_patient_user_id, 'booking_reschedule_requested_patient',
        'Nova proposta de reagendamento',
        'Sua terapeuta propôs outro horário para o encontro. Revise a solicitação.',
        '/app/encontros/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':patient')
      on conflict (profile_id, event_key) where event_key is not null do nothing;
    end if;
  elsif v_status = 'applied' then
    insert into public.notifications (profile_id, kind, title, body, href, event_key)
    values
      (v_patient_user_id, 'booking_rescheduled_patient', 'Encontro reagendado',
        'O novo horário foi confirmado. Consulte os detalhes atualizados.',
        '/app/encontros/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':patient'),
      (v_therapist_user_id, 'booking_rescheduled_therapist', 'Sessão reagendada',
        'O novo horário foi confirmado e sua agenda foi atualizada.',
        '/terapeuta/sessoes/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':therapist')
    on conflict (profile_id, event_key) where event_key is not null do nothing;
  elsif v_status = 'rejected' then
    insert into public.notifications (profile_id, kind, title, body, href, event_key)
    values (
      v_requester_user_id,
      case when v_requester_user_id = v_patient_user_id
        then 'booking_reschedule_rejected_patient'
        else 'booking_reschedule_rejected_therapist' end,
      'Proposta de reagendamento recusada',
      'A proposta não foi aceita. O horário original permanece confirmado.',
      case when v_requester_user_id = v_patient_user_id
        then '/app/encontros/' || new.booking_id::text
        else '/terapeuta/sessoes/' || new.booking_id::text end,
      'booking-event:' || new.id::text || ':' || v_requester_user_id::text
    ) on conflict (profile_id, event_key) where event_key is not null do nothing;
  elsif v_status = 'cancelled' then
    insert into public.notifications (profile_id, kind, title, body, href, event_key)
    values (
      case when v_requester_user_id = v_patient_user_id
        then v_therapist_user_id else v_patient_user_id end,
      case when v_requester_user_id = v_patient_user_id
        then 'booking_reschedule_withdrawn_therapist'
        else 'booking_reschedule_withdrawn_patient' end,
      'Proposta de reagendamento retirada',
      'A proposta foi retirada. O horário original permanece confirmado.',
      case when v_requester_user_id = v_patient_user_id
        then '/terapeuta/sessoes/' || new.booking_id::text
        else '/app/encontros/' || new.booking_id::text end,
      'booking-event:' || new.id::text || ':counterparty'
    ) on conflict (profile_id, event_key) where event_key is not null do nothing;
  elsif v_status = 'expired' then
    insert into public.notifications (profile_id, kind, title, body, href, event_key)
    values
      (v_patient_user_id, 'booking_reschedule_expired_patient',
        'Proposta de reagendamento encerrada',
        'A proposta expirou ou o horário deixou de estar disponível. O horário original permanece confirmado.',
        '/app/encontros/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':patient'),
      (v_therapist_user_id, 'booking_reschedule_expired_therapist',
        'Proposta de reagendamento encerrada',
        'A proposta expirou ou o horário deixou de estar disponível. O horário original permanece confirmado.',
        '/terapeuta/sessoes/' || new.booking_id::text,
        'booking-event:' || new.id::text || ':therapist')
    on conflict (profile_id, event_key) where event_key is not null do nothing;
  end if;

  return new;
end;
$$;


