CREATE OR REPLACE FUNCTION "public"."preflight_session_payment_retry_v1"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    return jsonb_build_object('allowed', false, 'reason', 'booking_not_found');
  end if;

  select * into v_payment
  from public.session_payments
  where booking_id = v_booking.id
  for update;

  if v_booking.status <> 'cancelled_by_payment'
    or v_payment.financial_status not in ('failed', 'canceled') then
    return jsonb_build_object('allowed', false, 'reason', 'booking_not_retryable');
  end if;

  if v_booking.starts_at <= now() then
    return jsonb_build_object('allowed', false, 'reason', 'booking_started');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_booking.therapist_profile_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-schedule:' || v_booking.patient_profile_id::text,
      0
    )
  );

  perform public.expire_booking_holds_v1(now(), v_booking.therapist_profile_id);

  if exists (
    select 1 from public.bookings as conflict
    where conflict.therapist_profile_id = v_booking.therapist_profile_id
      and conflict.id <> v_booking.id
      and conflict.status in ('draft', 'pending_payment', 'confirmed')
      and conflict.occupied_during && v_booking.occupied_during
  ) or exists (
    select 1 from public.booking_holds as hold
    where hold.therapist_profile_id = v_booking.therapist_profile_id
      and hold.status = 'active'
      and hold.expires_at > now()
      and hold.occupied_during && v_booking.occupied_during
  ) then
    return jsonb_build_object('allowed', false, 'reason', 'slot_conflict');
  end if;

  if public.patient_has_schedule_conflict_v1(
    v_booking.patient_profile_id,
    v_booking.starts_at,
    v_booking.ends_at,
    v_booking.id
  ) then
    return jsonb_build_object(
      'allowed', false,
      'reason', 'patient_schedule_conflict'
    );
  end if;

  return jsonb_build_object('allowed', true, 'reason', 'available');
end;
$$;


ALTER FUNCTION "public"."preflight_session_payment_retry_v1"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_booking_hold_snapshot_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_service public.therapist_services%rowtype;
  v_buffer_before integer;
  v_buffer_after integer;
begin
  select *
    into v_service
  from public.therapist_services
  where id = new.service_id;

  if not found then
    raise exception 'SERVICE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_service.therapist_profile_id <> new.therapist_profile_id then
    raise exception 'SERVICE_THERAPIST_MISMATCH' using errcode = '23514';
  end if;

  select
    coalesce(settings.buffer_before_minutes, 0),
    coalesce(settings.buffer_after_minutes, 0)
  into v_buffer_before, v_buffer_after
  from (select 1) as anchor
  left join public.therapist_service_booking_settings as settings
    on settings.service_id = v_service.id;

  new.service_title_snapshot := coalesce(
    nullif(trim(new.service_title_snapshot), ''),
    v_service.title
  );
  new.service_duration_minutes_snapshot := coalesce(
    new.service_duration_minutes_snapshot,
    v_service.duration_minutes
  );
  new.service_price_cents_snapshot := coalesce(
    new.service_price_cents_snapshot,
    v_service.price_cents
  );
  new.currency_snapshot := upper(
    coalesce(new.currency_snapshot, v_service.currency)
  );
  new.buffer_before_minutes_snapshot := coalesce(
    new.buffer_before_minutes_snapshot,
    v_buffer_before
  );
  new.buffer_after_minutes_snapshot := coalesce(
    new.buffer_after_minutes_snapshot,
    v_buffer_after
  );
  new.occupied_during := pg_catalog.tstzrange(
    new.starts_at
      - new.buffer_before_minutes_snapshot * interval '1 minute',
    new.ends_at
      + new.buffer_after_minutes_snapshot * interval '1 minute',
    '[)'
  );
  new.snapshot_captured_at := coalesce(new.snapshot_captured_at, now());
  new.version := coalesce(new.version, 1);

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_booking_hold_snapshot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_booking_reschedule_request_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
begin
  select *
    into v_booking
  from public.bookings
  where id = new.booking_id;

  if not found then
    raise exception 'BOOKING_NOT_FOUND' using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.patient_profiles as patient
    join public.therapist_profiles as therapist
      on therapist.id = v_booking.therapist_profile_id
    where patient.id = v_booking.patient_profile_id
      and new.requested_by_profile_id in (
        patient.user_id,
        therapist.user_id
      )
  ) then
    raise exception 'BOOKING_ACTOR_FORBIDDEN' using errcode = '42501';
  end if;

  new.original_starts_at := coalesce(
    new.original_starts_at,
    v_booking.starts_at
  );
  new.original_ends_at := coalesce(
    new.original_ends_at,
    v_booking.ends_at
  );
  new.original_timezone := coalesce(
    nullif(trim(new.original_timezone), ''),
    v_booking.timezone
  );
  new.proposed_timezone := coalesce(
    nullif(trim(new.proposed_timezone), ''),
    v_booking.timezone
  );
  new.booking_version_at_request := coalesce(
    new.booking_version_at_request,
    v_booking.version
  );
  new.expires_at := coalesce(
    new.expires_at,
    now() + interval '48 hours'
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_booking_reschedule_request_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_booking_snapshot_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_service public.therapist_services%rowtype;
  v_buffer_before integer;
  v_buffer_after integer;
begin
  select *
    into v_service
  from public.therapist_services
  where id = new.service_id;

  if not found then
    raise exception 'SERVICE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_service.therapist_profile_id <> new.therapist_profile_id then
    raise exception 'SERVICE_THERAPIST_MISMATCH' using errcode = '23514';
  end if;

  select
    coalesce(settings.buffer_before_minutes, 0),
    coalesce(settings.buffer_after_minutes, 0)
  into v_buffer_before, v_buffer_after
  from (select 1) as anchor
  left join public.therapist_service_booking_settings as settings
    on settings.service_id = v_service.id;

  new.service_title_snapshot := coalesce(
    nullif(trim(new.service_title_snapshot), ''),
    v_service.title
  );
  new.service_duration_minutes_snapshot := coalesce(
    new.service_duration_minutes_snapshot,
    v_service.duration_minutes
  );
  new.service_price_cents_snapshot := coalesce(
    new.service_price_cents_snapshot,
    v_service.price_cents
  );
  new.currency_snapshot := upper(
    coalesce(new.currency_snapshot, v_service.currency)
  );
  new.buffer_before_minutes_snapshot := coalesce(
    new.buffer_before_minutes_snapshot,
    v_buffer_before
  );
  new.buffer_after_minutes_snapshot := coalesce(
    new.buffer_after_minutes_snapshot,
    v_buffer_after
  );
  new.occupied_during := pg_catalog.tstzrange(
    new.starts_at
      - new.buffer_before_minutes_snapshot * interval '1 minute',
    new.ends_at
      + new.buffer_after_minutes_snapshot * interval '1 minute',
    '[)'
  );
  new.snapshot_captured_at := coalesce(new.snapshot_captured_at, now());
  new.version := coalesce(new.version, 1);

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_booking_snapshot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_profile_for_auth_user_delete_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.profiles
     set auth_deleted_at = coalesce(auth_deleted_at, now()),
         anonymized_at = coalesce(anonymized_at, now()),
         deletion_source = 'supabase_auth',
         display_name = 'Usuário removido',
         email = null,
         phone = null,
         avatar_url = null,
         email_confirmed_at = null,
         updated_at = now()
   where id = old.id;

  return old;
end;
$$;


