CREATE OR REPLACE FUNCTION "public"."prepare_session_payment_v10"("p_booking_id" "uuid", "p_stripe_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_account public.therapist_connect_accounts%rowtype;
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
  v_policy public.financial_policy_versions%rowtype;
  v_snapshot record;
  v_due_at timestamptz;
begin
  if p_booking_id is null or p_stripe_customer_id is null then
    raise exception 'SESSION_PAYMENT_V10_PREPARE_INVALID'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('tes:v10:session-payment:' || p_booking_id::text, 0)
  );

  select booking.*
  into v_booking
  from public.bookings as booking
  where booking.id = p_booking_id
  for update;

  if not found
    or v_booking.status not in ('draft', 'pending_payment')
    or v_booking.service_price_cents_snapshot <= 0
    or v_booking.currency_snapshot <> 'BRL'
  then
    raise exception 'SESSION_PAYMENT_V10_BOOKING_NOT_PREPARABLE'
      using errcode = '23514';
  end if;

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.booking_id = v_booking.id
  for update;

  if found then
    if v_payment.payment_flow_version <> 'v10'
      or v_payment.stripe_customer_id is distinct from p_stripe_customer_id
    then
      raise exception 'SESSION_PAYMENT_V10_EXISTING_FLOW_CONFLICT'
        using errcode = '23505';
    end if;

    return jsonb_build_object(
      'bookingVersion', v_booking.version,
      'connectAccountId', v_payment.connect_account_id_snapshot,
      'paymentDueAt', v_payment.payment_due_at,
      'paymentFlowVersion', v_payment.payment_flow_version,
      'sessionPaymentId', v_payment.id,
      'stripeCheckoutSessionId', v_payment.stripe_checkout_session_id,
      'stripeConnectAccountId', v_payment.stripe_connect_account_id_snapshot
    );
  end if;

  select policy.*
  into v_policy
  from public.financial_policy_versions as policy
  where policy.policy_key = 'tes-payments-v10-setup-t24-immediate-transfer';

  if not found or v_policy.platform_commission_bps <> 1500 then
    raise exception 'SESSION_PAYMENT_V10_POLICY_NOT_READY'
      using errcode = '23514';
  end if;

  select account.*
  into v_account
  from public.therapist_connect_accounts as account
  where account.therapist_profile_id = v_booking.therapist_profile_id
    and account.is_current
    and account.closed_at is null
    and account.operational_status = 'ready'
    and account.stripe_transfers_status = 'active'
    and account.payouts_enabled
    and account.payout_status = 'enabled'
    and account.payout_schedule_interval = 'daily'
  order by account.updated_at desc, account.id
  limit 1
  for update;

  if not found then
    raise exception 'SESSION_PAYMENT_CONNECT_ACCOUNT_NOT_READY'
      using errcode = '23514';
  end if;

  select *
  into v_snapshot
  from public.calculate_session_payment_snapshot(
    v_booking.service_price_cents_snapshot,
    v_policy.platform_commission_bps
  );

  v_due_at := v_booking.starts_at - interval '24 hours';

  insert into public.session_payments (
    booking_id,
    patient_profile_id,
    therapist_profile_id,
    service_id,
    policy_version_id,
    gross_amount_cents,
    platform_commission_bps,
    platform_gross_commission_cents,
    therapist_amount_cents,
    currency,
    stripe_customer_id,
    payment_flow_version,
    connect_account_id_snapshot,
    stripe_connect_account_id_snapshot,
    payment_due_at,
    metadata
  )
  values (
    v_booking.id,
    v_booking.patient_profile_id,
    v_booking.therapist_profile_id,
    v_booking.service_id,
    v_policy.id,
    v_snapshot.gross_amount_cents,
    v_snapshot.platform_commission_bps,
    v_snapshot.platform_gross_commission_cents,
    v_snapshot.therapist_amount_cents,
    'BRL',
    p_stripe_customer_id,
    'v10',
    v_account.id,
    v_account.stripe_account_id,
    v_due_at,
    jsonb_build_object(
      'stripe_checkout', jsonb_build_object(
        'original_amount_cents', v_booking.service_price_cents_snapshot,
        'charged_amount_cents', v_booking.service_price_cents_snapshot,
        'discount_amount_cents', 0
      )
    )
  )
  returning * into v_payment;

  -- The legacy payment projection trigger moves a draft booking to
  -- pending_payment when the payment is inserted, which advances the booking
  -- version. Return the version that is actually persisted after that trigger
  -- instead of the stale row captured before the insert.
  select booking.*
  into v_booking
  from public.bookings as booking
  where booking.id = p_booking_id;

  return jsonb_build_object(
    'bookingVersion', v_booking.version,
    'connectAccountId', v_payment.connect_account_id_snapshot,
    'paymentDueAt', v_payment.payment_due_at,
    'paymentFlowVersion', v_payment.payment_flow_version,
    'sessionPaymentId', v_payment.id,
    'stripeCheckoutSessionId', v_payment.stripe_checkout_session_id,
    'stripeConnectAccountId', v_payment.stripe_connect_account_id_snapshot
  );
end;
$$;


ALTER FUNCTION "public"."prepare_session_payment_v10"("p_booking_id" "uuid", "p_stripe_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prepare_session_payment_v10"("p_booking_id" "uuid", "p_stripe_customer_id" "uuid") IS 'Creates one immutable V10 payment/account/due-date snapshot per booking; service_role only.';



CREATE OR REPLACE FUNCTION "public"."prepare_session_transfer_job_v10"("p_job_id" "uuid", "p_worker_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.session_transfer_jobs%rowtype;
  v_payment public.session_payments%rowtype;
  v_account public.therapist_connect_accounts%rowtype;
  v_transfer public.stripe_transfers%rowtype;
  v_debt public.therapist_financial_debts%rowtype;
  v_remaining integer;
  v_amount integer;
  v_offset integer := 0;
  v_net integer;
  v_ledger_id uuid;
  v_allocation_id uuid;
begin
  if p_job_id is null or p_worker_id is null then
    raise exception 'SESSION_TRANSFER_JOB_PREPARE_V10_INVALID' using errcode = '22023';
  end if;

  select * into v_job from public.session_transfer_jobs
  where id = p_job_id for update;
  if not found or v_job.status <> 'creating'
    or v_job.lease_owner is distinct from p_worker_id
    or v_job.lease_expires_at <= now() then
    raise exception 'SESSION_TRANSFER_JOB_LEASE_LOST' using errcode = '23514';
  end if;

  select * into v_payment from public.session_payments
  where id = v_job.session_payment_id for update;
  select * into v_account from public.therapist_connect_accounts
  where id = v_job.connect_account_id for update;
  if v_payment.payment_flow_version <> 'v10'
    or v_payment.financial_status <> 'paid'
    or v_payment.refund_pending
    or v_payment.disputed_at is not null
    or v_payment.admin_blocked_at is not null
    or v_payment.stripe_charge_id is distinct from v_job.stripe_source_charge_id
    or v_payment.connect_account_id_snapshot is distinct from v_job.connect_account_id
    or v_account.id is null
    or v_account.therapist_profile_id <> v_payment.therapist_profile_id
    or v_account.operational_status <> 'ready'
    or v_account.stripe_transfers_status <> 'active'
    or v_account.closed_at is not null then
    raise exception 'SESSION_TRANSFER_JOB_BINDING_NOT_READY' using errcode = '23514';
  end if;

  -- A prepared job owns its debt allocations permanently. Reclaims only
  -- reuse that frozen net amount and the same Stripe idempotency key.
  if v_job.prepared_at is not null then
    if v_job.stripe_transfer_id is not null then
      select * into v_transfer from public.stripe_transfers
      where id = v_job.stripe_transfer_id for update;
    end if;
    return jsonb_build_object(
      'jobId', v_job.id, 'transferId', v_job.stripe_transfer_id,
      'bookingId', v_job.booking_id,
      'sessionPaymentId', v_job.session_payment_id,
      'therapistProfileId', v_payment.therapist_profile_id,
      'paymentIntentId', v_payment.stripe_payment_intent_id,
      'grossAmountCents', v_payment.gross_amount_cents,
      'stripeAccountId', v_account.stripe_account_id,
      'sourceChargeId', v_job.stripe_source_charge_id,
      'amountCents', v_job.transfer_amount_cents,
      'debtOffsetCents', v_job.debt_offset_amount_cents,
      'idempotencyKey', v_job.idempotency_key,
      'stripeTransferId', v_transfer.stripe_transfer_id
    );
  end if;

  -- One therapist's debt offset decisions must be serialized across jobs.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_payment.therapist_profile_id::text, 91410)
  );
  v_remaining := v_job.therapist_gross_amount_cents;
  for v_debt in
    select * from public.therapist_financial_debts
    where therapist_profile_id = v_payment.therapist_profile_id
      and status = 'open' and open_amount_cents > 0
    order by opened_at, id for update
  loop
    exit when v_remaining = 0;
    v_amount := least(v_remaining, v_debt.open_amount_cents);
    v_allocation_id := gen_random_uuid();
    update public.therapist_financial_debts
    set open_amount_cents = open_amount_cents - v_amount,
        recovered_amount_cents = recovered_amount_cents + v_amount,
        status = case when open_amount_cents = v_amount then 'settled' else 'open' end,
        closed_at = case when open_amount_cents = v_amount then now() else null end,
        updated_at = now()
    where id = v_debt.id;

    insert into public.financial_ledger_entries (
      entry_type, direction, currency, amount_cents,
      therapist_profile_id, booking_id, session_payment_id,
      financial_policy_version_id, transfer_origin,
      therapist_financial_debt_id, source_table, source_id, occurred_at
    ) values (
      'therapist_debt_offset', 'debit', 'BRL', v_amount,
      v_payment.therapist_profile_id, v_job.booking_id, v_job.session_payment_id,
      v_job.policy_version_id, 'session_direct',
      v_debt.id, 'therapist_financial_debt_allocations', v_allocation_id, now()
    ) returning id into v_ledger_id;

    insert into public.therapist_financial_debt_allocations (
      id, therapist_financial_debt_id, session_transfer_job_id,
      financial_ledger_entry_id, amount_cents, idempotency_key
    ) values (
      v_allocation_id, v_debt.id, v_job.id, v_ledger_id, v_amount,
      'tes:v10:debt-offset:' || v_job.id::text || ':' || v_debt.id::text
    );
    insert into public.therapist_financial_debt_events (
      therapist_financial_debt_id, event_type, direction, amount_cents,
      idempotency_key, financial_ledger_entry_id
    ) values (
      v_debt.id, 'transfer_offset', 'decrease', v_amount,
      'tes:v10:debt-event:' || v_job.id::text || ':' || v_debt.id::text,
      v_ledger_id
    );
    v_remaining := v_remaining - v_amount;
    v_offset := v_offset + v_amount;
  end loop;

  v_net := v_job.therapist_gross_amount_cents - v_offset;
  if v_net > 0 then
    insert into public.stripe_transfers (
      session_payment_id, therapist_profile_id, connect_account_id,
      idempotency_key, request_fingerprint, amount_cents, currency,
      status, stripe_source_charge_id, transfer_origin,
      therapist_gross_amount_cents, debt_offset_amount_cents
    ) values (
      v_job.session_payment_id, v_payment.therapist_profile_id,
      v_job.connect_account_id, v_job.idempotency_key,
      v_job.request_fingerprint, v_net, 'BRL', 'pending',
      v_job.stripe_source_charge_id, 'session_direct',
      v_job.therapist_gross_amount_cents, v_offset
    ) returning * into v_transfer;
  end if;

  update public.session_transfer_jobs
  set debt_offset_amount_cents = v_offset,
      transfer_amount_cents = v_net,
      stripe_transfer_id = v_transfer.id,
      prepared_at = now(),
      status = case when v_net = 0 then 'offset_only' else 'creating' end,
      succeeded_at = case when v_net = 0 then now() else null end,
      lease_owner = case when v_net = 0 then null else lease_owner end,
      lease_expires_at = case when v_net = 0 then null else lease_expires_at end,
      updated_at = now()
  where id = v_job.id;

  if v_net = 0 then
    update public.session_payments set transfer_status = 'transferred',
      updated_at = now() where id = v_job.session_payment_id;
  end if;

  return jsonb_build_object(
    'jobId', v_job.id, 'transferId', v_transfer.id,
    'bookingId', v_job.booking_id,
    'sessionPaymentId', v_job.session_payment_id,
    'therapistProfileId', v_payment.therapist_profile_id,
    'paymentIntentId', v_payment.stripe_payment_intent_id,
    'grossAmountCents', v_payment.gross_amount_cents,
    'stripeAccountId', v_account.stripe_account_id,
    'sourceChargeId', v_job.stripe_source_charge_id,
    'amountCents', v_net, 'debtOffsetCents', v_offset,
    'idempotencyKey', v_job.idempotency_key,
    'stripeTransferId', null
  );
end;
$$;


ALTER FUNCTION "public"."prepare_session_transfer_job_v10"("p_job_id" "uuid", "p_worker_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_therapist_public_identity_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.free_public_slug is null then
    new.free_public_slug := public.generate_therapist_free_public_slug_v1();
  end if;

  if new.plan = 'free' then
    new.slug := new.free_public_slug;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_therapist_public_identity_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preserve_reservation_attempt_state_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.attempt_kind = 'legacy' then return new; end if;

  -- Financial cancellation acknowledges the rejected authorization; it must not
  -- erase the scheduling decision. A real paid result still takes precedence.
  if old.status in ('slot_conflict', 'expired')
    and new.status in ('canceled', 'failed', 'processing', 'expired') then
    new.status := old.status;
    new.terminal_reason := old.terminal_reason;
  elsif old.status = 'capture_pending'
    and old.slot_claimed_at is not null
    and new.status = 'processing' then
    new.status := 'capture_pending';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."preserve_reservation_attempt_state_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preserve_reservation_attempt_state_v1"() IS 'Preserves reservation conflict/expiry and claimed authorization semantics across generic financial projections; paid evidence remains authoritative.';



CREATE OR REPLACE FUNCTION "public"."prevent_accepted_therapist_private_document_replacement_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.document_kind not in ('identity_document', 'address_proof') then
    return new;
  end if;

  if exists (
    select 1
    from public.therapist_private_documents existing_document
    where existing_document.therapist_profile_id = new.therapist_profile_id
      and existing_document.document_kind = new.document_kind
      and existing_document.status = 'accepted'
  ) then
    raise exception 'DOCUMENT_ALREADY_ACCEPTED' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_accepted_therapist_private_document_replacement_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prevent_accepted_therapist_private_document_replacement_v1"() IS 'Blocks replacement of an accepted required private document until an authorized Admin requests a new submission.';



CREATE OR REPLACE FUNCTION "public"."prevent_admin_audit_event_mutation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    raise exception 'admin audit events are append-only'
      using errcode = '23514';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'admin audit events cannot be deleted'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_admin_audit_event_mutation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_legal_acceptance_mutation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE'
    and (
      new.profile_id is distinct from old.profile_id
      or new.actor_role is distinct from old.actor_role
      or new.document_version_id is distinct from old.document_version_id
      or new.document_key is distinct from old.document_key
      or new.document_version is distinct from old.document_version
      or new.content_hash is distinct from old.content_hash
      or new.context is distinct from old.context
      or new.booking_id is distinct from old.booking_id
      or new.request_id is distinct from old.request_id
      or new.evidence is distinct from old.evidence
      or new.accepted_at is distinct from old.accepted_at
    )
  then
    raise exception 'legal acceptances are immutable'
      using errcode = '23514';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'legal acceptances cannot be deleted'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_legal_acceptance_mutation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_operational_theme_deactivation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.is_active and not new.is_active and exists (
    select 1
    from public.therapy_matching_themes candidate
    join public.therapies therapy on therapy.id = candidate.therapy_id
    left join public.matching_therapy_settings settings
      on settings.therapy_id = therapy.id
    where candidate.theme_id = old.id
      and (
        (
          therapy.status = 'published'
          and (
            therapy.is_public_visible
            or therapy.is_available_for_services
            or coalesce(settings.is_visible_in_matching, false)
          )
        )
        or exists (
          select 1
          from public.therapist_services service
          where service.therapy_id = therapy.id
            and service.status = 'active'
            and service.archived_at is null
        )
      )
      and not exists (
        select 1
        from public.therapy_matching_themes sibling
        join public.matching_themes sibling_theme
          on sibling_theme.id = sibling.theme_id
         and sibling_theme.is_active
        where sibling.therapy_id = candidate.therapy_id
          and sibling.theme_id <> old.id
      )
  ) then
    raise exception 'ADMIN_MATCHING_THEME_DEACTIVATION_BLOCKED';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_operational_theme_deactivation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_published_legal_document_mutation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE'
    and old.status = 'published'
    and (
      new.document_key is distinct from old.document_key
      or new.title is distinct from old.title
      or new.audience is distinct from old.audience
      or new.version is distinct from old.version
      or new.content_hash is distinct from old.content_hash
      or new.canonical_path is distinct from old.canonical_path
      or new.language is distinct from old.language
      or new.approved_at is distinct from old.approved_at
      or new.approved_by is distinct from old.approved_by
      or new.effective_at is distinct from old.effective_at
      or new.published_at is distinct from old.published_at
      or new.requires_new_acceptance is distinct from old.requires_new_acceptance
      or new.change_summary is distinct from old.change_summary
      or new.source_reference is distinct from old.source_reference
    )
  then
    raise exception 'published legal document versions are immutable'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_published_legal_document_mutation_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_structured_participant_message_v2"("p_conversation_id" "uuid", "p_template_key" "text", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_parameters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return public.resolve_structured_participant_message_v2(
    p_conversation_id,
    p_template_key,
    p_booking_id,
    p_parameters
  );
end;
$$;


ALTER FUNCTION "public"."preview_structured_participant_message_v2"("p_conversation_id" "uuid", "p_template_key" "text", "p_booking_id" "uuid", "p_parameters" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_structured_participant_message_v2"("p_conversation_id" "uuid", "p_template_key" "text", "p_booking_id" "uuid", "p_parameters" "jsonb") IS 'V2 preview boundary: returns only server-resolved participant content and allowlisted recipient CTA without persisting a message.';



CREATE OR REPLACE FUNCTION "public"."private_admin_get_finance_detail_v1_v9_legacy"("p_module" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_events jsonb := '[]'::jsonb;
  v_record jsonb;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if p_id is null then
    raise exception 'admin finance detail id required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  case p_module
    when 'payments' then
      select jsonb_build_object(
        'id', session_payments.id,
        'booking_id', session_payments.booking_id,
        'therapist_profile_id', session_payments.therapist_profile_id,
        'therapist_name', therapist_profiles.public_name,
        'patient_profile_id', session_payments.patient_profile_id,
        'patient_name', patient_profiles.display_name,
        'service_id', session_payments.service_id,
        'service_title', bookings.service_title_snapshot,
        'starts_at', bookings.starts_at,
        'ends_at', bookings.ends_at,
        'financial_status', session_payments.financial_status,
        'service_status', session_payments.service_status,
        'transfer_status', session_payments.transfer_status,
        'service_confirmed_at', session_payments.service_confirmed_at,
        'service_confirmation_source',
          session_payments.service_confirmation_source,
        'eligible_at', session_payments.eligible_at,
        'transfer_blocked_reason',
          session_payments.transfer_blocked_reason,
        'refund_pending', session_payments.refund_pending,
        'disputed_at', session_payments.disputed_at,
        'internal_contested_at', session_payments.internal_contested_at,
        'admin_blocked_at', session_payments.admin_blocked_at,
        'paid_at', session_payments.paid_at,
        'failed_at', session_payments.failed_at,
        'canceled_at', session_payments.canceled_at,
        'gross_amount_cents', session_payments.gross_amount_cents,
        'therapist_amount_cents', session_payments.therapist_amount_cents,
        'platform_gross_commission_cents',
          session_payments.platform_gross_commission_cents,
        'stripe_fee_amount_cents',
          session_payments.stripe_fee_amount_cents,
        'stripe_net_amount_cents',
          session_payments.stripe_net_amount_cents,
        'currency', session_payments.currency,
        'has_checkout_session',
          session_payments.stripe_checkout_session_id is not null,
        'has_payment_intent',
          session_payments.stripe_payment_intent_id is not null,
        'has_charge', session_payments.stripe_charge_id is not null,
        'has_balance_transaction',
          session_payments.stripe_balance_transaction_id is not null,
        'stripe_event_created_at',
          session_payments.stripe_event_created_at,
        'metadata_present',
          coalesce(session_payments.metadata, '{}'::jsonb) <> '{}'::jsonb,
        'attempt_count', coalesce(attempt_summary.attempt_count, 0),
        'latest_attempt_status',
          attempt_summary.latest_attempt_status,
        'refund_count', coalesce(refund_summary.refund_count, 0),
        'refunded_amount_cents',
          coalesce(refund_summary.refunded_amount_cents, 0),
        'dispute_count', coalesce(dispute_summary.dispute_count, 0),
        'transfer_count', coalesce(transfer_summary.transfer_count, 0),
        'ledger_entry_count', coalesce(ledger_summary.ledger_entry_count, 0),
        'created_at', session_payments.created_at,
        'updated_at', session_payments.updated_at
      )
      into v_record
      from public.session_payments
      left join public.bookings
        on bookings.id = session_payments.booking_id
      left join public.therapist_profiles
        on therapist_profiles.id = session_payments.therapist_profile_id
      left join public.patient_profiles
        on patient_profiles.id = session_payments.patient_profile_id
      left join lateral (
        select
          count(*)::integer as attempt_count,
          (
            array_agg(session_payment_attempts.status order by session_payment_attempts.created_at desc)
          )[1] as latest_attempt_status
        from public.session_payment_attempts
        where session_payment_attempts.session_payment_id =
          session_payments.id
      ) attempt_summary on true
      left join lateral (
        select
          count(*)::integer as refund_count,
          coalesce(sum(session_refunds.amount_cents), 0)::integer
            as refunded_amount_cents
        from public.session_refunds
        where session_refunds.session_payment_id = session_payments.id
      ) refund_summary on true
      left join lateral (
        select count(*)::integer as dispute_count
        from public.session_disputes
        where session_disputes.session_payment_id = session_payments.id
      ) dispute_summary on true
      left join lateral (
        select count(*)::integer as transfer_count
        from public.stripe_transfers
        where stripe_transfers.session_payment_id = session_payments.id
      ) transfer_summary on true
      left join lateral (
        select count(*)::integer as ledger_entry_count
        from public.financial_ledger_entries
        where financial_ledger_entries.session_payment_id = session_payments.id
      ) ledger_summary on true
      where session_payments.id = p_id;

      select coalesce(jsonb_agg(event_payload order by occurred_at desc), '[]'::jsonb)
      into v_events
      from (
        select
          financial_ledger_entries.occurred_at,
          jsonb_build_object(
            'id', financial_ledger_entries.id,
            'kind', 'ledger_entry',
            'entry_type', financial_ledger_entries.entry_type,
            'direction', financial_ledger_entries.direction,
            'amount_cents', financial_ledger_entries.amount_cents,
            'currency', financial_ledger_entries.currency,
            'source_table', financial_ledger_entries.source_table,
            'occurred_at', financial_ledger_entries.occurred_at,
            'recorded_at', financial_ledger_entries.recorded_at
          ) as event_payload
        from public.financial_ledger_entries
        where financial_ledger_entries.session_payment_id = p_id
        order by financial_ledger_entries.occurred_at desc
        limit 12
      ) events;

    when 'subscriptions' then
      select jsonb_build_object(
        'id', therapist_subscriptions.id,
        'therapist_profile_id',
          therapist_subscriptions.therapist_profile_id,
        'therapist_name', therapist_profiles.public_name,
        'therapist_current_plan', therapist_profiles.plan,
        'plan_code', therapist_subscriptions.plan_code,
        'plan_name', billing_plans.name,
        'status', therapist_subscriptions.status,
        'current_period_start',
          therapist_subscriptions.current_period_start,
        'current_period_end', therapist_subscriptions.current_period_end,
        'cancel_at_period_end',
          therapist_subscriptions.cancel_at_period_end,
        'canceled_at', therapist_subscriptions.canceled_at,
        'ended_at', therapist_subscriptions.ended_at,
        'unit_amount_cents', billing_plan_prices.unit_amount_cents,
        'currency', billing_plan_prices.currency,
        'interval', billing_plan_prices.interval,
        'customer_linked', stripe_customers.id is not null,
        'customer_environment', stripe_customers.environment,
        'customer_livemode', stripe_customers.livemode,
        'customer_email_present',
          nullif(btrim(coalesce(stripe_customers.email, '')), '') is not null,
        'has_subscription_reference',
          therapist_subscriptions.stripe_subscription_id is not null,
        'has_checkout_session',
          therapist_subscriptions.stripe_checkout_session_id is not null,
        'has_latest_invoice_reference',
          therapist_subscriptions.stripe_latest_invoice_id is not null,
        'stripe_event_created_at',
          therapist_subscriptions.stripe_event_created_at,
        'metadata_present',
          coalesce(therapist_subscriptions.metadata, '{}'::jsonb) <> '{}'::jsonb,
        'invoice_count', coalesce(invoice_summary.invoice_count, 0),
        'open_invoice_count', coalesce(invoice_summary.open_invoice_count, 0),
        'paid_invoice_count', coalesce(invoice_summary.paid_invoice_count, 0),
        'event_count', coalesce(event_summary.event_count, 0),
        'created_at', therapist_subscriptions.created_at,
        'updated_at', therapist_subscriptions.updated_at
      )
      into v_record
      from public.therapist_subscriptions
      left join public.therapist_profiles
        on therapist_profiles.id =
          therapist_subscriptions.therapist_profile_id
      left join public.billing_plans
        on billing_plans.id = therapist_subscriptions.billing_plan_id
      left join public.billing_plan_prices
        on billing_plan_prices.id =
          therapist_subscriptions.billing_plan_price_id
      left join public.stripe_customers
        on stripe_customers.id = therapist_subscriptions.stripe_customer_id
      left join lateral (
        select
          count(*)::integer as invoice_count,
          count(*) filter (where billing_invoices.status = 'open')::integer
            as open_invoice_count,
          count(*) filter (where billing_invoices.status = 'paid')::integer
            as paid_invoice_count
        from public.billing_invoices
        where billing_invoices.therapist_subscription_id =
          therapist_subscriptions.id
      ) invoice_summary on true
      left join lateral (
        select count(*)::integer as event_count
        from public.therapist_subscription_events
        where therapist_subscription_events.therapist_subscription_id =
          therapist_subscriptions.id
      ) event_summary on true
      where therapist_subscriptions.id = p_id;

      select coalesce(jsonb_agg(event_payload order by created_at desc), '[]'::jsonb)
      into v_events
      from (
        select
          billing_invoices.created_at,
          jsonb_build_object(
            'id', billing_invoices.id,
            'kind', 'invoice',
            'status', billing_invoices.status,
            'amount_due_cents', billing_invoices.amount_due_cents,
            'amount_paid_cents', billing_invoices.amount_paid_cents,
            'currency', billing_invoices.currency,
            'paid_at', billing_invoices.paid_at,
            'due_at', billing_invoices.due_at,
            'created_at', billing_invoices.created_at
          ) as event_payload
        from public.billing_invoices
        where billing_invoices.therapist_subscription_id = p_id
        union all
        select
          therapist_subscription_events.created_at,
          jsonb_build_object(
            'id', therapist_subscription_events.id,
            'kind', 'subscription_event',
            'event_type', therapist_subscription_events.event_type,
            'previous_plan', therapist_subscription_events.previous_plan,
            'next_plan', therapist_subscription_events.next_plan,
            'previous_status', therapist_subscription_events.previous_status,
            'next_status', therapist_subscription_events.next_status,
            'stripe_event_present',
              therapist_subscription_events.stripe_event_id is not null,
            'created_at', therapist_subscription_events.created_at
          ) as event_payload
        from public.therapist_subscription_events
        where therapist_subscription_events.therapist_subscription_id = p_id
        order by created_at desc
        limit 12
      ) events;

    else
      raise exception 'unsupported admin finance module: %', p_module
        using errcode = '22023';
  end case;

  if v_record is null then
    return jsonb_build_object(
      'events', '[]'::jsonb,
      'generatedAt', now(),
      'id', p_id,
      'module', p_module,
      'record', null
    );
  end if;

  return jsonb_build_object(
    'events', coalesce(v_events, '[]'::jsonb),
    'generatedAt', now(),
    'id', p_id,
    'module', p_module,
    'record', v_record
  );
end;
$$;


ALTER FUNCTION "public"."private_admin_get_finance_detail_v1_v9_legacy"("p_module" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_admin_get_finance_detail_v1_v9_legacy"("p_module" "text", "p_id" "uuid") IS 'Minimized admin finance detail read model for payments and subscriptions. Read-only by design; financial mutations require a separate audited command boundary.';



CREATE OR REPLACE FUNCTION "public"."private_admin_get_finance_module_v2_v9_legacy"("p_module" "text", "p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor_id uuid := auth.uid();
  v_base jsonb;
  v_filtered jsonb;
  v_metrics jsonb := '{}'::jsonb;
  v_page integer := 1;
  v_page_size integer := 12;
  v_page_text text := coalesce(p_query ->> 'page', '');
  v_page_size_text text := coalesce(p_query ->> 'pageSize', '');
  v_rows jsonb := '[]'::jsonb;
  v_search text := nullif(btrim(coalesce(p_query ->> 'search', '')), '');
  v_sort text := nullif(btrim(coalesce(p_query ->> 'sort', 'recent')), '');
  v_status text := nullif(btrim(coalesce(p_query ->> 'status', '')), '');
  v_total integer := 0;
begin
  if v_actor_id is null then
    raise exception 'admin authentication required'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = v_actor_id
      and profiles.role = 'admin'::public.user_role
      and profiles.auth_deleted_at is null
      and profiles.anonymized_at is null
  ) then
    raise exception 'admin permission required'
      using errcode = '42501';
  end if;

  if v_page_text ~ '^[0-9]+$' then
    v_page := greatest(v_page_text::integer, 1);
  end if;

  if v_page_size_text ~ '^[0-9]+$' then
    v_page_size := least(greatest(v_page_size_text::integer, 1), 50);
  end if;

  if p_module in ('payments', 'subscriptions') then
    v_base := public.admin_get_finance_module_v1(p_module, 50, 0);
    v_metrics := coalesce(v_base -> 'metrics', '{}'::jsonb);
    v_rows := coalesce(v_base -> 'rows', '[]'::jsonb);
  elsif p_module = 'reports' then
    v_metrics := jsonb_build_object(
      'report-professionals', (
        select count(*)::integer from public.therapist_profiles
      ),
      'report-patients', (
        select count(*)::integer from public.patient_profiles
      ),
      'report-sessions', (
        select count(*)::integer from public.bookings
      ),
      'report-payments', (
        select count(*)::integer from public.session_payments
      ),
      'report-subscriptions', (
        select count(*)::integer from public.therapist_subscriptions
      ),
      'report-stripe-failures', (
        select count(*)::integer
        from public.stripe_webhook_events
        where processing_status::text = 'failed'
      )
    );
    v_rows := jsonb_build_array(
      jsonb_build_object(
        'description', 'Status, publicação, plano e prontidão operacional.',
        'export_status', 'Pendente de comando auditado',
        'id', 'professionals',
        'privacy', 'Mínimo necessário',
        'scope', 'Admin read-only',
        'source', 'therapist_profiles',
        'status', 'planned',
        'title', 'Relatório de profissionais',
        'updated_at', now()
      ),
      jsonb_build_object(
        'description', 'Base de clientes com mínimo operacional, sem conteúdo clínico.',
        'export_status', 'Pendente de comando auditado',
        'id', 'patients',
        'privacy', 'Mínimo necessário',
        'scope', 'Admin read-only',
        'source', 'patient_profiles',
        'status', 'planned',
        'title', 'Relatório de clientes',
        'updated_at', now()
      ),
      jsonb_build_object(
        'description', 'Reservas, estados, janelas e conciliação operacional.',
        'export_status', 'Pendente de comando auditado',
        'id', 'sessions',
        'privacy', 'Mínimo necessário',
        'scope', 'Admin read-only',
        'source', 'bookings',
        'status', 'planned',
        'title', 'Relatório de sessões',
        'updated_at', now()
      ),
      jsonb_build_object(
        'description', 'Pagamentos, refunds, disputes, ledger e repasses.',
        'export_status', 'Pendente de comando auditado',
        'id', 'payments',
        'privacy', 'Mínimo necessário',
        'scope', 'Admin read-only',
        'source', 'session_payments',
        'status', 'planned',
        'title', 'Relatório financeiro',
        'updated_at', now()
      ),
      jsonb_build_object(
        'description', 'Billing de terapeutas, planos e estados de cobrança.',
        'export_status', 'Pendente de comando auditado',
        'id', 'subscriptions',
        'privacy', 'Mínimo necessário',
        'scope', 'Admin read-only',
        'source', 'therapist_subscriptions',
        'status', 'planned',
        'title', 'Relatório de assinaturas',
        'updated_at', now()
      )
    );
  else
    raise exception 'unsupported admin finance module: %', p_module
      using errcode = '22023';
  end if;

  v_filtered := public.admin_filter_jsonb_read_model_rows_v1(
    v_rows,
    v_search,
    v_status,
    coalesce(v_sort, 'recent'),
    v_page,
    v_page_size
  );
  v_total := coalesce((v_filtered ->> 'total')::integer, 0);

  return jsonb_build_object(
    'filtersApplied', jsonb_build_object(
      'search', v_search,
      'sort', coalesce(v_sort, 'recent'),
      'status', v_status
    ),
    'generatedAt', now(),
    'metrics', v_metrics,
    'module', p_module,
    'page', jsonb_build_object(
      'hasNext', (v_page * v_page_size) < v_total,
      'page', v_page,
      'pageSize', v_page_size,
      'total', v_total
    ),
    'rows', coalesce(v_filtered -> 'rows', '[]'::jsonb)
  );
end;
$_$;


ALTER FUNCTION "public"."private_admin_get_finance_module_v2_v9_legacy"("p_module" "text", "p_query" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_admin_get_finance_module_v2_v9_legacy"("p_module" "text", "p_query" "jsonb") IS 'Paginated admin finance read model. Keeps Stripe/Billing/ledger data read-only and returns sanitized rows with filtersApplied and page metadata.';



CREATE OR REPLACE FUNCTION "public"."private_admin_session_payout_projection_v10"("p_session_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'payout_display_status', case
      when coalesce(open_debt.open_amount_cents, 0) > 0
        then 'compensation_pending'
      when job.status = 'reversed' or transfer.status = 'reversed'
        then 'reversed'
      when payment.financial_status = 'refunded'
        and transfer.status = 'transferred'
        then 'needs_review'
      when payment.financial_status = 'refunded'
        then 'refunded'
      when job.status = 'offset_only'
        then 'compensated'
      when job.status in ('partially_reversed', 'failed')
        or transfer.status = 'failed'
        then 'failed'
      when job.status = 'reconciliation_required'
        or transfer.status = 'reconciliation_required'
        then 'needs_review'
      when paid_payout.id is not null
        then 'paid'
      when job.status in ('pending_source', 'transferred')
        or transfer.status = 'transferred'
        then 'bank_pending'
      when job.status in ('queued', 'creating')
        or transfer.status in ('pending', 'creating')
        then 'processing'
      else 'processing'
    end,
    'debt_offset_amount_cents', coalesce(
      nullif(job.debt_offset_amount_cents, 0),
      nullif(transfer.debt_offset_amount_cents, 0)
    ),
    'transfer_effective_amount_cents', coalesce(
      job.transfer_amount_cents,
      transfer.amount_cents
    ),
    'bank_paid_at', paid_payout.paid_at
  ))
  from public.session_payments payment
  left join public.session_transfer_jobs job
    on job.session_payment_id = payment.id
  left join lateral (
    select candidate.*
    from public.stripe_transfers candidate
    where candidate.session_payment_id = payment.id
    order by
      (candidate.id = job.stripe_transfer_id) desc,
      coalesce(candidate.transferred_at, candidate.created_at) desc,
      candidate.id desc
    limit 1
  ) transfer on true
  left join lateral (
    select coalesce(sum(debt.open_amount_cents), 0)::integer
      as open_amount_cents
    from public.therapist_financial_debts debt
    where debt.session_payment_id = payment.id
      and debt.status = 'open'
      and debt.open_amount_cents > 0
  ) open_debt on true
  left join lateral (
    select payout.id, payout.paid_at
    from public.stripe_payout_transfer_allocations allocation
    join public.stripe_payouts payout
      on payout.id = allocation.stripe_payout_id
    where allocation.stripe_transfer_id = transfer.id
      and allocation.amount_cents = transfer.amount_cents
      and payout.status = 'paid'
      and payout.provider_reconciliation_status = 'completed'
      and payout.allocation_status = 'completed'
    order by payout.paid_at desc nulls last, payout.id desc
    limit 1
  ) paid_payout on true
  where payment.id = p_session_payment_id
    and (job.id is not null or transfer.id is not null);
$$;


ALTER FUNCTION "public"."private_admin_session_payout_projection_v10"("p_session_payment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_admin_session_payout_projection_v10"("p_session_payment_id" "uuid") IS 'Private fail-closed V9/V10 payout projection used by the administrative finance read model.';



CREATE OR REPLACE FUNCTION "public"."private_patient_session_feedback_queue_v1_v9_legacy"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with legacy as (
    select public.private_patient_session_feedback_queue_v1_with_safety_legacy() payload
  ), items as (
    select item.value payload
    from legacy
    cross join lateral jsonb_array_elements(legacy.payload) item
  )
  select coalesce(jsonb_agg(
    items.payload || jsonb_build_object(
      'confirmationState', case
        when items.payload ->> 'confirmationState' in ('safety_period', 'next_batch')
          and payment.transfer_status in ('waiting_safety_period', 'waiting_settlement')
          then 'processing_payment'
        when payment.transfer_status = 'transferred' then 'completed'
        when items.payload ->> 'confirmationState' in ('safety_period', 'next_batch')
          then 'next_batch'
        else items.payload ->> 'confirmationState'
      end,
      'eligibleAt', payment.eligible_at,
      'nextBatchAt', case
        when payment.transfer_status = 'eligible'
          then public.next_weekly_payout_cutoff_v1(payment.eligible_at, now())
        else null
      end
    ) order by (items.payload ->> 'endsAt')::timestamptz desc
  ), '[]'::jsonb)
  from items
  join public.session_payments payment
    on payment.booking_id = (items.payload ->> 'bookingId')::uuid;
$$;


ALTER FUNCTION "public"."private_patient_session_feedback_queue_v1_v9_legacy"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_patient_session_feedback_queue_v1_v9_legacy"() IS 'Ended paid patient encounters awaiting feedback, with settlement-only transfer state.';



CREATE OR REPLACE FUNCTION "public"."private_patient_session_feedback_queue_v1_with_safety_legacy"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_patient_profile_id uuid;
begin
  if v_actor_id is null then
    raise exception 'FEEDBACK_AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select patient.id into v_patient_profile_id
  from public.patient_profiles patient
  where patient.user_id = v_actor_id;
  if v_patient_profile_id is null then
    raise exception 'FEEDBACK_PATIENT_REQUIRED' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'bookingId', booking.id,
      'startsAt', booking.starts_at,
      'endsAt', booking.ends_at,
      'timezone', booking.timezone,
      'serviceLabel', service.title,
      'therapyLabel', therapy.name,
      'therapist', jsonb_build_object(
        'id', therapist.id,
        'name', therapist.public_name,
        'avatarUrl', therapist.photo_url
      ),
      'actorConfirmation', public.session_confirmation_payload_v2(patient_confirmation),
      'counterpartConfirmation', public.session_confirmation_payload_v2(therapist_confirmation),
      'confirmationState', case
        when incident.status = 'open' or payment.internal_contested_at is not null
          or payment.admin_blocked_at is not null then 'blocked_for_review'
        when payment.transfer_status = 'transferred' then 'completed'
        when payment.service_confirmed_at is not null and payment.eligible_at > now() then 'safety_period'
        when payment.service_confirmed_at is not null then 'next_batch'
        when patient_confirmation.id is null and therapist_confirmation.id is null then 'awaiting_both'
        when patient_confirmation.id is null then 'awaiting_patient'
        when therapist_confirmation.id is null then 'awaiting_therapist'
        else 'blocked_for_review'
      end,
      'eligibleAt', payment.eligible_at,
      'nextBatchAt', public.next_weekly_payout_cutoff_v1(payment.eligible_at, now()),
      'serviceConfirmedAt', payment.service_confirmed_at
    ) order by booking.ends_at desc)
    from public.bookings booking
    join public.session_payments payment on payment.booking_id = booking.id
    join public.therapist_profiles therapist on therapist.id = booking.therapist_profile_id
    join public.therapist_services service on service.id = booking.service_id
    join public.therapies therapy on therapy.id = service.therapy_id
    left join public.session_participant_confirmations patient_confirmation
      on patient_confirmation.booking_id = booking.id
      and patient_confirmation.participant_role = 'patient'::public.user_role
    left join public.session_participant_confirmations therapist_confirmation
      on therapist_confirmation.booking_id = booking.id
      and therapist_confirmation.participant_role = 'therapist'::public.user_role
    left join public.session_confirmation_incidents incident
      on incident.booking_id = booking.id and incident.status = 'open'
    where booking.patient_profile_id = v_patient_profile_id
      and booking.ends_at <= now()
      and booking.status not in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded')
      and payment.financial_status in ('paid', 'partially_refunded')
      and not exists (
        select 1 from public.session_feedback feedback
        where feedback.booking_id = booking.id
          and feedback.author_role = 'patient'::public.user_role
      )
  ), '[]'::jsonb);
end;
$$;


