COMMENT ON FUNCTION "public"."private_patient_session_feedback_queue_v1_with_safety_legacy"() IS 'All ended paid patient encounters that still lack the patient private feedback response.';



CREATE OR REPLACE FUNCTION "public"."private_refresh_session_transfer_eligibility_v9_legacy"("p_session_payment_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "public"."session_transfer_status"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_connect_ready boolean;
  v_has_active_batch boolean;
  v_eligible_at timestamptz;
  v_status public.session_transfer_status;
  v_reason text;
begin
  select * into v_payment
  from public.session_payments
  where id = p_session_payment_id
  for update;

  if not found then
    raise exception 'session_payment_not_found';
  end if;

  select exists (
    select 1
    from public.therapist_connect_accounts account
    where account.therapist_profile_id = v_payment.therapist_profile_id
      and account.is_current = true
      and account.stripe_transfers_status = 'active'
      and account.payouts_enabled = true
      and account.payout_status = 'enabled'
      and account.payout_schedule_interval = 'daily'
      and account.operational_status = 'ready'
  ) into v_connect_ready;

  select exists (
    select 1
    from public.payout_batch_items
    where session_payment_id = p_session_payment_id
      and status in ('reserved', 'transfer_pending', 'transferred')
  ) into v_has_active_batch;

  if v_payment.transfer_status = 'transferred' then
    v_status := 'transferred';
    v_reason := 'already_transferred';
  elsif v_has_active_batch then
    v_status := 'batched';
    v_reason := 'already_batched';
  elsif v_payment.financial_status = 'disputed' or v_payment.disputed_at is not null then
    v_status := 'blocked';
    v_reason := 'disputed';
  elsif v_payment.admin_blocked_at is not null or v_payment.internal_contested_at is not null then
    v_status := 'blocked';
    v_reason := coalesce(v_payment.transfer_blocked_reason, 'blocked_or_contested');
  elsif v_payment.refund_pending or v_payment.financial_status = 'refunded' then
    v_status := 'blocked';
    v_reason := 'refund';
  elsif v_payment.financial_status not in ('paid', 'partially_refunded') then
    v_status := 'not_eligible';
    v_reason := 'payment_not_confirmed';
  elsif (
      v_payment.service_status not in (
        'confirmed_bilateral',
        'confirmed_by_patient_review',
        'confirmed_by_therapist',
        'auto_confirmed'
      )
      and not (
        v_payment.service_status = 'canceled'
        and public.is_fully_retained_cancellation_payment_v1(v_payment.id)
      )
    ) or v_payment.service_confirmed_at is null
      or v_payment.service_confirmed_at > p_now then
    v_status := 'waiting_confirmation';
    v_reason := 'service_not_confirmed';
  elsif not v_connect_ready then
    v_status := 'blocked';
    v_reason := 'connect_not_ready';
  elsif v_payment.therapist_amount_cents <= 0 then
    v_status := 'not_eligible';
    v_reason := 'non_positive_transfer_amount';
  else
    v_eligible_at := v_payment.service_confirmed_at;
    if v_payment.stripe_charge_id is null
      or v_payment.stripe_balance_transaction_id is null
      or v_payment.stripe_balance_status is distinct from 'available'
      or v_payment.stripe_balance_available_on is null
      or v_payment.stripe_balance_available_on > p_now
      or v_payment.stripe_balance_checked_at is null
      or v_payment.stripe_balance_checked_at < p_now - interval '2 hours' then
      v_status := 'waiting_settlement';
      v_reason := 'stripe_settlement_pending';
    else
      v_status := 'eligible';
      v_reason := 'eligible';
    end if;
  end if;

  update public.session_payments
  set transfer_status = v_status,
      eligible_at = case
        when v_status in ('waiting_settlement', 'eligible') then v_eligible_at
        when v_status in ('batched', 'transfer_pending', 'transferred') then eligible_at
        else null
      end,
      transfer_blocked_reason = v_reason,
      updated_at = now()
  where id = p_session_payment_id;

  return v_status;
end;
$$;


ALTER FUNCTION "public"."private_refresh_session_transfer_eligibility_v9_legacy"("p_session_payment_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_refresh_session_transfer_eligibility_v9_legacy"("p_session_payment_id" "uuid", "p_now" timestamp with time zone) IS 'Recalcula a elegibilidade do Transfer sem alterar confirmacao, presenca ou acesso Zoom; exige liquidacao Stripe recente e usa search_path endurecido.';



CREATE OR REPLACE FUNCTION "public"."private_session_feedback_v2_v9_legacy"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payload jsonb;
  v_transfer_status text;
begin
  v_payload := public.private_session_feedback_v2_with_safety_legacy(p_booking_id);

  select payment.transfer_status::text into v_transfer_status
  from public.session_payments payment
  where payment.booking_id = p_booking_id;

  if v_payload ->> 'confirmationState' in ('safety_period', 'next_batch') then
    v_payload := jsonb_set(
      v_payload,
      '{confirmationState}',
      to_jsonb(case
        when v_transfer_status in ('waiting_safety_period', 'waiting_settlement') then 'processing_payment'
        when v_transfer_status = 'transferred' then 'completed'
        else 'next_batch'
      end::text),
      true
    );
  end if;

  v_payload := jsonb_set(v_payload, '{policy,transferSafetyHours}', '0'::jsonb, true);
  v_payload := jsonb_set(
    v_payload,
    '{financial,nextBatchAt}',
    case
      when v_transfer_status = 'eligible' then coalesce(v_payload #> '{financial,nextBatchAt}', 'null'::jsonb)
      else 'null'::jsonb
    end,
    true
  );

  return v_payload;
end;
$$;


ALTER FUNCTION "public"."private_session_feedback_v2_v9_legacy"("p_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_session_feedback_v2_v9_legacy"("p_booking_id" "uuid") IS 'Participant-scoped feedback and confirmation state. Stripe settlement replaces the retired transfer safety period.';



CREATE OR REPLACE FUNCTION "public"."private_session_feedback_v2_with_safety_legacy"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role public.user_role;
  v_booking record;
  v_feedback public.session_feedback;
  v_patient public.session_participant_confirmations;
  v_therapist public.session_participant_confirmations;
  v_attendance jsonb;
  v_status text;
  v_reason text;
  v_confirmation_state text;
  v_next_batch_at timestamptz;
  v_incident_status text;
begin
  if v_actor_id is null then
    raise exception 'FEEDBACK_AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  if p_booking_id is null then
    raise exception 'FEEDBACK_BOOKING_REQUIRED' using errcode = '22023';
  end if;

  select
    booking.starts_at,
    booking.ends_at,
    booking.status::text as booking_status,
    payment.financial_status::text as financial_status,
    payment.service_status::text as service_status,
    payment.service_confirmed_at,
    payment.eligible_at,
    payment.transfer_status::text as transfer_status,
    payment.transfer_blocked_reason,
    payment.admin_blocked_at,
    payment.internal_contested_at,
    policy.patient_auto_confirmation_days,
    policy.therapist_auto_confirmation_days,
    case
      when patient.user_id = v_actor_id then 'patient'::public.user_role
      when therapist.user_id = v_actor_id then 'therapist'::public.user_role
      else null
    end as actor_role
  into v_booking
  from public.bookings booking
  join public.session_payments payment on payment.booking_id = booking.id
  join public.financial_policy_versions policy on policy.id = payment.policy_version_id
  join public.patient_profiles patient on patient.id = booking.patient_profile_id
  join public.therapist_profiles therapist on therapist.id = booking.therapist_profile_id
  where booking.id = p_booking_id;

  v_actor_role := v_booking.actor_role;
  if v_actor_role is null then
    raise exception 'FEEDBACK_PARTICIPANT_REQUIRED' using errcode = '42501';
  end if;

  select feedback.* into v_feedback
  from public.session_feedback feedback
  where feedback.booking_id = p_booking_id
    and feedback.author_role = v_actor_role;
  select confirmation.* into v_patient
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = 'patient'::public.user_role;
  select confirmation.* into v_therapist
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = 'therapist'::public.user_role;
  select incident.status into v_incident_status
  from public.session_confirmation_incidents incident
  where incident.booking_id = p_booking_id;

  v_attendance := public.session_attendance_state_v1(p_booking_id, now());

  if v_feedback.id is not null then
    v_status := 'submitted';
    v_reason := 'submitted';
  elsif v_booking.financial_status not in ('paid', 'partially_refunded') then
    v_status := 'unavailable';
    v_reason := 'payment_pending';
  elsif now() < v_booking.ends_at then
    v_status := 'before_session';
    v_reason := 'session_not_ended';
  elsif v_booking.booking_status in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded') then
    v_status := 'unavailable';
    v_reason := 'session_cancelled';
  else
    v_status := 'eligible';
    v_reason := 'post_session_available';
  end if;

  if v_incident_status = 'open'
    or v_booking.internal_contested_at is not null
    or v_booking.admin_blocked_at is not null then
    v_confirmation_state := 'blocked_for_review';
  elsif v_booking.transfer_status = 'transferred' then
    v_confirmation_state := 'completed';
  elsif v_booking.service_confirmed_at is not null
    and v_booking.eligible_at is not null
    and now() < v_booking.eligible_at then
    v_confirmation_state := 'safety_period';
  elsif v_booking.service_confirmed_at is not null then
    v_confirmation_state := 'next_batch';
  elsif v_patient.id is null and v_therapist.id is null then
    v_confirmation_state := 'awaiting_both';
  elsif v_patient.id is null then
    v_confirmation_state := 'awaiting_patient';
  elsif v_therapist.id is null then
    v_confirmation_state := 'awaiting_therapist';
  else
    v_confirmation_state := 'blocked_for_review';
  end if;

  v_next_batch_at := public.next_weekly_payout_cutoff_v1(v_booking.eligible_at, now());

  return jsonb_build_object(
    'actorRole', v_actor_role,
    'attendance', v_attendance,
    'confirmation', case when v_actor_role = 'patient'::public.user_role
      then public.session_confirmation_payload_v2(v_patient)
      else public.session_confirmation_payload_v2(v_therapist) end,
    'actorConfirmation', case when v_actor_role = 'patient'::public.user_role
      then public.session_confirmation_payload_v2(v_patient)
      else public.session_confirmation_payload_v2(v_therapist) end,
    'counterpartConfirmation', case when v_actor_role = 'patient'::public.user_role
      then public.session_confirmation_payload_v2(v_therapist)
      else public.session_confirmation_payload_v2(v_patient) end,
    'patientConfirmation', public.session_confirmation_payload_v2(v_patient),
    'therapistConfirmation', public.session_confirmation_payload_v2(v_therapist),
    'confirmationState', v_confirmation_state,
    'feedback', case when v_feedback.id is null then null
      else public.session_feedback_payload(v_feedback) end,
    'financial', jsonb_build_object(
      'eligibleAt', v_booking.eligible_at,
      'nextBatchAt', v_next_batch_at,
      'serviceConfirmedAt', v_booking.service_confirmed_at,
      'serviceStatus', v_booking.service_status,
      'transferBlockedReason', v_booking.transfer_blocked_reason,
      'transferStatus', v_booking.transfer_status
    ),
    'policy', jsonb_build_object(
      'patientAutoConfirmationDays', v_booking.patient_auto_confirmation_days,
      'therapistAutoConfirmationDays', v_booking.therapist_auto_confirmation_days,
      'transferSafetyHours', 24
    ),
    'reason', v_reason,
    'status', v_status
  );
end;
$$;


ALTER FUNCTION "public"."private_session_feedback_v2_with_safety_legacy"("p_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_session_feedback_v2_with_safety_legacy"("p_booking_id" "uuid") IS 'Participant-scoped private feedback plus bilateral confirmation, role deadlines, safety period and next-batch state.';



CREATE OR REPLACE FUNCTION "public"."private_therapist_agenda_capacity_v1"("p_therapist_profile_id" "uuid", "p_range_start" "date", "p_range_end" "date", "p_timezone" "text") RETURNS TABLE("scheduled_minutes" integer, "exception_minutes" integer, "committed_minutes" integer, "available_minutes" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_window tstzrange;
  v_scheduled tstzmultirange := '{}'::tstzmultirange;
  v_after_exceptions tstzmultirange := '{}'::tstzmultirange;
  v_available tstzmultirange := '{}'::tstzmultirange;
  v_booked tstzmultirange := '{}'::tstzmultirange;
  v_service_scheduled tstzmultirange;
  v_service_blocked tstzmultirange;
  v_service record;
  v_scheduled_minutes integer := 0;
  v_after_exception_minutes integer := 0;
  v_available_minutes integer := 0;
begin
  if p_therapist_profile_id is null
    or p_range_start is null
    or p_range_end is null
    or p_range_start > p_range_end
    or p_range_end - p_range_start > 62
    or not public.is_valid_timezone_v1(p_timezone)
  then
    raise exception 'invalid_agenda_capacity_range' using errcode = '22023';
  end if;

  v_window := pg_catalog.tstzrange(
    p_range_start::timestamp at time zone p_timezone,
    (p_range_end + 1)::timestamp at time zone p_timezone,
    '[)'
  );

  for v_service in
    select service.id
    from public.therapist_services as service
    join public.therapies as therapy
      on therapy.id = service.therapy_id
    where service.therapist_profile_id = p_therapist_profile_id
      and service.status = 'active'
      and service.is_bookable = true
      and service.delivery_format = 'online'
      and service.online_only = true
      and therapy.status in ('published', 'active')
      and therapy.is_available_for_services = true
  loop
    with days as (
      select day_value::date as day_value
      from pg_catalog.generate_series(
        p_range_start,
        p_range_end,
        interval '1 day'
      ) as generated(day_value)
    ),
    source_windows as (
      select pg_catalog.tstzrange(
        (days.day_value + rule.start_time) at time zone p_timezone,
        (days.day_value + rule.end_time) at time zone p_timezone,
        '[)'
      ) as range_value
      from days
      join public.availability_rules as rule
        on rule.therapist_profile_id = p_therapist_profile_id
       and rule.service_id = v_service.id
       and rule.is_active
       and rule.day_of_week = extract(dow from days.day_value)::integer

      union all

      select pg_catalog.tstzrange(
        exception.starts_at,
        exception.ends_at,
        '[)'
      ) as range_value
      from public.availability_exceptions as exception
      where exception.therapist_profile_id = p_therapist_profile_id
        and exception.is_available
        and coalesce(exception.status, 'active') = 'active'
        and (exception.service_id is null or exception.service_id = v_service.id)
        and exception.starts_at < upper(v_window)
        and exception.ends_at > lower(v_window)
    )
    select coalesce(
      range_agg(source.range_value * v_window),
      '{}'::tstzmultirange
    )
      into v_service_scheduled
    from source_windows as source
    where source.range_value && v_window;

    select coalesce(
      range_agg(
        pg_catalog.tstzrange(
          exception.starts_at,
          exception.ends_at,
          '[)'
        ) * v_window
      ),
      '{}'::tstzmultirange
    )
      into v_service_blocked
    from public.availability_exceptions as exception
    where exception.therapist_profile_id = p_therapist_profile_id
      and not exception.is_available
      and coalesce(exception.status, 'active') = 'active'
      and (exception.service_id is null or exception.service_id = v_service.id)
      and exception.starts_at < upper(v_window)
      and exception.ends_at > lower(v_window);

    v_scheduled := v_scheduled + v_service_scheduled;
    v_after_exceptions :=
      v_after_exceptions + (v_service_scheduled - v_service_blocked);
  end loop;

  select coalesce(
    range_agg(booking.occupied_during * v_window),
    '{}'::tstzmultirange
  )
    into v_booked
  from public.bookings as booking
  where booking.therapist_profile_id = p_therapist_profile_id
    and booking.status in ('confirmed', 'completed')
    and booking.occupied_during && v_window
    and exists (
      select 1
      from public.session_payments as payment
      where payment.booking_id = booking.id
        and payment.therapist_profile_id = p_therapist_profile_id
        and payment.financial_status in ('paid', 'partially_refunded')
    );

  v_available := v_after_exceptions - v_booked;

  select coalesce(sum(
    extract(
      epoch from (upper(segment.range_value) - lower(segment.range_value))
    ) / 60
  ), 0)::integer
    into v_scheduled_minutes
  from unnest(v_scheduled) as segment(range_value);

  select coalesce(sum(
    extract(
      epoch from (upper(segment.range_value) - lower(segment.range_value))
    ) / 60
  ), 0)::integer
    into v_after_exception_minutes
  from unnest(v_after_exceptions) as segment(range_value);

  select coalesce(sum(
    extract(
      epoch from (upper(segment.range_value) - lower(segment.range_value))
    ) / 60
  ), 0)::integer
    into v_available_minutes
  from unnest(v_available) as segment(range_value);

  return query
  select
    v_scheduled_minutes,
    greatest(v_scheduled_minutes - v_after_exception_minutes, 0),
    greatest(v_after_exception_minutes - v_available_minutes, 0),
    v_available_minutes;
end;
$$;


ALTER FUNCTION "public"."private_therapist_agenda_capacity_v1"("p_therapist_profile_id" "uuid", "p_range_start" "date", "p_range_end" "date", "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_therapist_agenda_capacity_v1"("p_therapist_profile_id" "uuid", "p_range_start" "date", "p_range_end" "date", "p_timezone" "text") IS 'Internal F3 capacity projection. Merges service availability, applies scoped exceptions, and subtracts therapist-global booking occupancy including immutable buffer snapshots.';



CREATE OR REPLACE FUNCTION "public"."private_therapist_finance_advanced_comparison_v1"("p_current" integer, "p_previous" integer) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'currentValue', p_current,
    'previousValue', case when p_previous is null then null else p_previous end,
    'absoluteDelta', case when p_previous is null then null else p_current - p_previous end,
    'percentageDelta', case
      when p_previous is null then null
      when p_previous = 0 then null
      else round((p_current - p_previous)::numeric * 100 / p_previous, 1)
    end,
    'comparisonStatus', case
      when p_previous is null then 'no_previous_data'
      when p_previous = 0 then 'division_by_zero'
      else 'available'
    end
  );
$$;


ALTER FUNCTION "public"."private_therapist_finance_advanced_comparison_v1"("p_current" integer, "p_previous" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_therapist_finance_advanced_dashboard_payload_v1"("p_therapist_profile_id" "uuid", "p_plan" "public"."therapist_plan", "p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_period record;
  v_period_days integer;
  v_previous_period_start date;
  v_previous_period_end date;
  v_today date;
  v_now timestamptz := now();
  v_forecast_month_start date;
  v_forecast_month_end date;
  v_forecast_window_start date;
  v_forecast_window_end date;
  v_realized_net_cents integer := 0;
  v_contracted_future_net_cents integer := 0;
  v_contracted_month_net_cents integer := 0;
  v_active_service_count integer := 0;
  v_min_service_price_cents integer := 0;
  v_max_service_price_cents integer := 0;
  v_expected_service_price_cents integer := 0;
  v_primary_duration_minutes integer := 60;
  v_scheduled_minutes integer := 0;
  v_committed_minutes integer := 0;
  v_available_minutes integer := 0;
  v_estimated_bookable_slots integer := 0;
  v_conservative_potential_cents integer := 0;
  v_expected_potential_cents integer := 0;
  v_maximum_potential_cents integer := 0;
  v_agenda_confidence text := 'low';
  v_forecast_confidence text := 'low';
  v_paid_history_count integer := 0;
  v_cancelled_count integer := 0;
  v_eligible_patients_90 integer := 0;
  v_returning_patients_90 integer := 0;
  v_patients_without_return integer := 0;
  v_return_rate_90 numeric;
  v_median_days_to_return numeric;
  v_retention_cohorts jsonb := '[]'::jsonb;
  v_revenue_by_therapy jsonb := '[]'::jsonb;
  v_evolution jsonb := '[]'::jsonb;
  v_opportunities jsonb := '[]'::jsonb;
  v_insights jsonb := '[]'::jsonb;
  v_benchmark jsonb;
  v_benchmark_therapists integer := 0;
  v_benchmark_sessions integer := 0;
  v_benchmark_average_ticket_median numeric;
  v_benchmark_return_rate_median numeric;
  v_benchmark_occupancy_median numeric;
  v_therapist_average_ticket integer;
  v_therapist_occupancy_rate numeric;
begin
  if p_plan <> 'premium_plus' then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = '42501';
  end if;

  select *
    into v_period
  from public.normalize_private_therapist_finance_period_v1(
    p_period_start,
    p_period_end,
    p_timezone
  );

  v_period_days := (v_period.period_end - v_period.period_start) + 1;
  v_previous_period_end := v_period.period_start - 1;
  v_previous_period_start := v_previous_period_end - (v_period_days - 1);
  v_today := (v_now at time zone v_period.timezone)::date;
  v_forecast_month_start :=
    date_trunc('month', v_period.period_end::timestamp)::date;
  v_forecast_month_end :=
    (date_trunc('month', v_period.period_end::timestamp) + interval '1 month - 1 day')::date;
  v_forecast_window_start := greatest(v_today, v_forecast_month_start);

  v_forecast_window_end := v_forecast_month_end;

  select
    count(*)::integer,
    coalesce(min(service.price_cents), 0)::integer,
    coalesce(max(service.price_cents), 0)::integer,
    coalesce(round(avg(service.price_cents)), 0)::integer,
    coalesce(round(avg(service.duration_minutes)), 60)::integer
    into
      v_active_service_count,
      v_min_service_price_cents,
      v_max_service_price_cents,
      v_expected_service_price_cents,
      v_primary_duration_minutes
  from public.therapist_services as service
  join public.therapies as therapy
    on therapy.id = service.therapy_id
  where service.therapist_profile_id = p_therapist_profile_id
    and service.status = 'active'
    and service.is_bookable = true
    and service.delivery_format = 'online'
    and service.online_only = true
    and therapy.status in ('published', 'active')
    and therapy.is_available_for_services = true;

  select count(*)::integer
    into v_paid_history_count
  from public.session_payments as payment
  where payment.therapist_profile_id = p_therapist_profile_id
    and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
    and coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
    and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at;

  select coalesce(
    round(sum(payment.gross_amount_cents)::numeric / nullif(count(*), 0)),
    v_expected_service_price_cents
  )::integer
    into v_expected_service_price_cents
  from public.session_payments as payment
  where payment.therapist_profile_id = p_therapist_profile_id
    and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
    and coalesce(payment.paid_at, payment.created_at) >= (v_period.starts_at - interval '90 days')
    and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at;

  if v_active_service_count > 0 then
    v_expected_service_price_cents :=
      least(
        greatest(
          coalesce(v_expected_service_price_cents, 0),
          coalesce(v_min_service_price_cents, 0)
        ),
        coalesce(v_max_service_price_cents, 0)
      );
  else
    v_expected_service_price_cents := 0;
  end if;

  if v_forecast_window_start <= v_forecast_window_end then
    select
      capacity.scheduled_minutes,
      capacity.committed_minutes,
      capacity.available_minutes
      into
        v_scheduled_minutes,
        v_committed_minutes,
        v_available_minutes
    from public.private_therapist_agenda_capacity_v1(
      p_therapist_profile_id,
      v_forecast_window_start,
      v_forecast_window_end,
      v_period.timezone
    ) as capacity;
  end if;
  v_primary_duration_minutes := greatest(v_primary_duration_minutes, 15);
  v_estimated_bookable_slots :=
    floor(v_available_minutes::numeric / v_primary_duration_minutes)::integer;
  v_conservative_potential_cents :=
    v_estimated_bookable_slots * coalesce(v_min_service_price_cents, 0);
  v_expected_potential_cents :=
    v_estimated_bookable_slots * coalesce(v_expected_service_price_cents, 0);
  v_maximum_potential_cents :=
    v_estimated_bookable_slots * coalesce(v_max_service_price_cents, 0);

  v_agenda_confidence := case
    when v_active_service_count = 0 or v_scheduled_minutes = 0 then 'low'
    when v_paid_history_count >= 10 then 'high'
    when v_paid_history_count >= 5 then 'medium'
    else 'low'
  end;
  v_forecast_confidence := case
    when v_agenda_confidence = 'high' and v_paid_history_count >= 10 then 'high'
    when v_active_service_count > 0 and v_scheduled_minutes > 0 then 'medium'
    else 'low'
  end;

  select coalesce(sum(public.private_therapist_finance_net_cents_v1(payment)), 0)::integer
    into v_realized_net_cents
  from public.session_payments as payment
  join public.bookings as booking
    on booking.id = payment.booking_id
  where payment.therapist_profile_id = p_therapist_profile_id
    and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
    and booking.status not in (
      'cancelled_by_patient',
      'cancelled_by_therapist',
      'refunded'
    )
    and coalesce(payment.paid_at, payment.created_at) >=
      (v_forecast_month_start::timestamp at time zone v_period.timezone)
    and coalesce(payment.paid_at, payment.created_at) < least(
      v_now,
      (v_forecast_month_end + 1)::timestamp at time zone v_period.timezone
    );

  select coalesce(sum(public.private_therapist_finance_net_cents_v1(payment)), 0)::integer
    into v_contracted_future_net_cents
  from public.session_payments as payment
  join public.bookings as booking
    on booking.id = payment.booking_id
  where payment.therapist_profile_id = p_therapist_profile_id
    and payment.financial_status in ('paid', 'partially_refunded')
    and booking.status in ('confirmed', 'completed')
    and booking.starts_at >= v_now
    and booking.starts_at <
      ((v_forecast_month_end + 1)::timestamp at time zone v_period.timezone);

  v_contracted_month_net_cents :=
    v_realized_net_cents + v_contracted_future_net_cents;

  select count(distinct booking.id)::integer
    into v_cancelled_count
  from public.bookings as booking
  where booking.therapist_profile_id = p_therapist_profile_id
    and booking.status in ('cancelled_by_patient', 'cancelled_by_therapist', 'refunded')
    and booking.starts_at >= v_period.starts_at
    and booking.starts_at < v_period.ends_at;

  with first_completed as (
    select
      booking.patient_profile_id,
      min(booking.starts_at) as first_completed_at
    from public.bookings as booking
    left join public.session_payments as payment
      on payment.booking_id = booking.id
    where booking.therapist_profile_id = p_therapist_profile_id
      and (
        booking.status = 'completed'
        or payment.service_status in (
          'confirmed_by_patient_review',
          'confirmed_by_therapist',
          'auto_confirmed'
        )
        or payment.service_confirmed_at is not null
      )
    group by booking.patient_profile_id
  ),
  eligible as (
    select *
    from first_completed
    where first_completed_at >= v_period.starts_at
      and first_completed_at < v_period.ends_at
      and first_completed_at + interval '90 days' <= v_now
  ),
  returns as (
    select
      eligible.patient_profile_id,
      min(coalesce(payment.paid_at, payment.created_at)) as returned_at
    from eligible
    join public.session_payments as payment
      on payment.therapist_profile_id = p_therapist_profile_id
     and payment.patient_profile_id = eligible.patient_profile_id
     and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
     and coalesce(payment.paid_at, payment.created_at) > eligible.first_completed_at
     and coalesce(payment.paid_at, payment.created_at)
       <= eligible.first_completed_at + interval '90 days'
    group by eligible.patient_profile_id
  )
  select
    (select count(*)::integer from eligible),
    (select count(*)::integer from returns),
    (select count(*)::integer from eligible left join returns using (patient_profile_id) where returns.patient_profile_id is null),
    (select percentile_cont(0.5) within group (
      order by extract(epoch from (returned_at - first_completed_at)) / 86400
    ) from eligible join returns using (patient_profile_id))
    into
      v_eligible_patients_90,
      v_returning_patients_90,
      v_patients_without_return,
      v_median_days_to_return;

  v_return_rate_90 := case
    when v_eligible_patients_90 < 10 then null
    else round(v_returning_patients_90::numeric * 100 / v_eligible_patients_90, 1)
  end;

  with first_completed as (
    select
      booking.patient_profile_id,
      date_trunc('month', min(booking.starts_at) at time zone v_period.timezone)::date
        as cohort_month,
      min(booking.starts_at) as first_completed_at
    from public.bookings as booking
    left join public.session_payments as payment
      on payment.booking_id = booking.id
    where booking.therapist_profile_id = p_therapist_profile_id
      and (
        booking.status = 'completed'
        or payment.service_status in (
          'confirmed_by_patient_review',
          'confirmed_by_therapist',
          'auto_confirmed'
        )
        or payment.service_confirmed_at is not null
      )
    group by booking.patient_profile_id
  ),
  cohort_rows as (
    select
      first_completed.patient_profile_id,
      first_completed.cohort_month,
      first_completed.first_completed_at,
      first_completed.first_completed_at + interval '90 days' <= v_now as is_eligible,
      exists (
        select 1
        from public.session_payments as payment
        where payment.therapist_profile_id = p_therapist_profile_id
          and payment.patient_profile_id = first_completed.patient_profile_id
          and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
          and coalesce(payment.paid_at, payment.created_at) > first_completed.first_completed_at
          and coalesce(payment.paid_at, payment.created_at)
            <= first_completed.first_completed_at + interval '90 days'
      ) as has_returned
    from first_completed
    where first_completed.cohort_month between
      date_trunc('month', v_period.starts_at at time zone v_period.timezone)::date
      and date_trunc('month', v_period.ends_at at time zone v_period.timezone)::date
  ),
  grouped as (
    select
      cohort_month,
      count(*)::integer as new_patients,
      count(*) filter (where is_eligible and has_returned)::integer as returning_patients,
      count(*) filter (where is_eligible and not has_returned)::integer as without_return_patients,
      count(*) filter (where not is_eligible)::integer as censored_patients
    from cohort_rows
    group by cohort_month
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'cohortMonth', cohort_month,
        'newPatients', new_patients,
        'returningPatients', returning_patients,
        'withoutReturnPatients', without_return_patients,
        'censoredPatients', censored_patients,
        'returnRate', case
          when new_patients - censored_patients <= 0 then null
          else round(returning_patients::numeric * 100 / (new_patients - censored_patients), 1)
        end
      )
      order by cohort_month
    ),
    '[]'::jsonb
  )
    into v_retention_cohorts
  from grouped;

  with current_paid as (
    select
      service.therapy_id,
      coalesce(therapy.name, booking.service_title_snapshot) as therapy_name_snapshot,
      payment.id,
      payment.gross_amount_cents,
      public.private_therapist_finance_net_cents_v1(payment) as net_cents
    from public.session_payments as payment
    join public.bookings as booking
      on booking.id = payment.booking_id
    join public.therapist_services as service
      on service.id = payment.service_id
    left join public.therapies as therapy
      on therapy.id = service.therapy_id
    where payment.therapist_profile_id = p_therapist_profile_id
      and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
      and coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
      and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at
  ),
  previous_paid as (
    select
      service.therapy_id,
      public.private_therapist_finance_net_cents_v1(payment) as net_cents
    from public.session_payments as payment
    join public.therapist_services as service
      on service.id = payment.service_id
    where payment.therapist_profile_id = p_therapist_profile_id
      and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
      and coalesce(payment.paid_at, payment.created_at) >=
        (v_previous_period_start::timestamp at time zone v_period.timezone)
      and coalesce(payment.paid_at, payment.created_at) <
        ((v_previous_period_end + 1)::timestamp at time zone v_period.timezone)
  ),
  current_grouped as (
    select
      therapy_id,
      max(therapy_name_snapshot) as therapy_name_snapshot,
      count(*)::integer as paid_session_count,
      sum(gross_amount_cents)::integer as gross_amount_cents,
      sum(net_cents)::integer as therapist_net_amount_cents
    from current_paid
    group by therapy_id
  ),
  previous_grouped as (
    select therapy_id, sum(net_cents)::integer as previous_net_cents
    from previous_paid
    group by therapy_id
  ),
  total_current as (
    select greatest(coalesce(sum(therapist_net_amount_cents), 0), 0)::numeric as total_net
    from current_grouped
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'therapyId', current_grouped.therapy_id,
        'therapyNameSnapshot', current_grouped.therapy_name_snapshot,
        'paidSessionCount', current_grouped.paid_session_count,
        'grossAmountCents', current_grouped.gross_amount_cents,
        'therapistNetAmountCents', current_grouped.therapist_net_amount_cents,
        'averageTicketCents', case
          when current_grouped.paid_session_count = 0 then null
          else round(current_grouped.gross_amount_cents::numeric / current_grouped.paid_session_count)::integer
        end,
        'revenueSharePercent', case
          when total_current.total_net <= 0 then null
          else round(current_grouped.therapist_net_amount_cents::numeric * 100 / total_current.total_net, 1)
        end,
        'trend', public.private_therapist_finance_advanced_comparison_v1(
          current_grouped.therapist_net_amount_cents,
          coalesce(previous_grouped.previous_net_cents, 0)
        )
      )
      order by current_grouped.therapist_net_amount_cents desc,
        current_grouped.therapy_name_snapshot
    ),
    '[]'::jsonb
  )
    into v_revenue_by_therapy
  from (
    select *
    from current_grouped
    order by therapist_net_amount_cents desc, therapy_name_snapshot
    limit 8
  ) as current_grouped
  cross join total_current
  left join previous_grouped
    on previous_grouped.therapy_id is not distinct from current_grouped.therapy_id;

  with buckets as (
    select
      bucket_start::date as period_start,
      least((bucket_start::date + 6), v_period.period_end)::date as period_end
    from generate_series(
      v_period.period_start,
      v_period.period_end,
      interval '7 days'
    ) as bucket(bucket_start)
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'periodStart', bucket.period_start,
        'periodEnd', bucket.period_end,
        'realizedNetCents', coalesce((
          select sum(public.private_therapist_finance_net_cents_v1(payment))::integer
          from public.session_payments as payment
          where payment.therapist_profile_id = p_therapist_profile_id
            and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
            and (coalesce(payment.paid_at, payment.created_at) at time zone v_period.timezone)::date
              between bucket.period_start and bucket.period_end
        ), 0),
        'contractedNetCents', coalesce((
          select sum(public.private_therapist_finance_net_cents_v1(payment))::integer
          from public.session_payments as payment
          join public.bookings as booking
            on booking.id = payment.booking_id
          where payment.therapist_profile_id = p_therapist_profile_id
            and payment.financial_status in ('paid', 'partially_refunded')
            and booking.status in ('confirmed', 'completed')
            and booking.starts_at >= v_now
            and (booking.starts_at at time zone v_period.timezone)::date
              between bucket.period_start and bucket.period_end
        ), 0),
        'projectedNetCents', case
          when bucket.period_end < v_today then null
          else round(
            coalesce((
              select sum(public.private_therapist_finance_net_cents_v1(payment))::integer
              from public.session_payments as payment
              where payment.therapist_profile_id = p_therapist_profile_id
                and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
                and (coalesce(payment.paid_at, payment.created_at) at time zone v_period.timezone)::date
                  between bucket.period_start and bucket.period_end
            ), 0)
            + case
              when v_forecast_window_start > v_forecast_window_end then 0
              else v_expected_potential_cents::numeric
                / greatest((v_forecast_window_end - v_forecast_window_start + 1), 1)
                * greatest(
                  least(bucket.period_end, v_forecast_window_end)
                  - greatest(bucket.period_start, v_forecast_window_start)
                  + 1,
                  0
                )
            end
          )::integer
        end,
        'previousPeriodNetCents', (
          select coalesce(sum(public.private_therapist_finance_net_cents_v1(payment)), 0)::integer
          from public.session_payments as payment
          where payment.therapist_profile_id = p_therapist_profile_id
            and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
            and (coalesce(payment.paid_at, payment.created_at) at time zone v_period.timezone)::date
              between (
                v_previous_period_start + (bucket.period_start - v_period.period_start)
              )
              and least(
                v_previous_period_start + (bucket.period_end - v_period.period_start),
                v_previous_period_end
              )
        )
      )
      order by bucket.period_start
    ),
    '[]'::jsonb
  )
    into v_evolution
  from buckets as bucket;

  v_therapist_average_ticket := case
    when v_paid_history_count = 0 then null
    else round((
      select coalesce(sum(payment.gross_amount_cents), 0)::numeric
      from public.session_payments as payment
      where payment.therapist_profile_id = p_therapist_profile_id
        and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
        and coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
        and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at
    ) / v_paid_history_count)::integer
  end;

  v_therapist_occupancy_rate := case
    when v_scheduled_minutes <= 0 then null
    else round(v_committed_minutes::numeric * 100 / v_scheduled_minutes, 1)
  end;

  with therapist_stats as (
    select
      payment.therapist_profile_id,
      count(*)::integer as paid_sessions,
      round(avg(payment.gross_amount_cents))::integer as average_ticket_cents
    from public.session_payments as payment
    join public.therapist_profiles as therapist
      on therapist.id = payment.therapist_profile_id
    where therapist.status = 'approved'
      and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
      and coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
      and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at
    group by payment.therapist_profile_id
  )
  select
    count(*)::integer,
    coalesce(sum(paid_sessions), 0)::integer,
    percentile_cont(0.5) within group (order by average_ticket_cents)
    into
      v_benchmark_therapists,
      v_benchmark_sessions,
      v_benchmark_average_ticket_median
  from therapist_stats;

  if v_benchmark_therapists < 20 or v_benchmark_sessions < 100 then
    v_benchmark := jsonb_build_object(
      'status', 'insufficient_sample',
      'cohortDescription', null,
      'sampleSize', null,
      'minimumTherapists', 20,
      'minimumSessions', 100,
      'methodologyVersion', 'tes-financial-benchmark-v1',
      'metrics', jsonb_build_object(
        'averageTicketCents', jsonb_build_object(
          'therapistValue', v_therapist_average_ticket,
          'cohortMedian', null,
          'percentile', null
        ),
        'returnRate', jsonb_build_object(
          'therapistValue', v_return_rate_90,
          'cohortMedian', null,
          'percentile', null
        ),
        'occupancyRate', jsonb_build_object(
          'therapistValue', v_therapist_occupancy_rate,
          'cohortMedian', null,
          'percentile', null
        )
      )
    );
  else
    with therapist_stats as (
      select
        payment.therapist_profile_id,
        count(*)::integer as paid_sessions,
        round(avg(payment.gross_amount_cents))::integer as average_ticket_cents
      from public.session_payments as payment
      join public.therapist_profiles as therapist
        on therapist.id = payment.therapist_profile_id
      where therapist.status = 'approved'
        and payment.financial_status in ('paid', 'partially_refunded', 'refunded')
        and coalesce(payment.paid_at, payment.created_at) >= v_period.starts_at
        and coalesce(payment.paid_at, payment.created_at) < v_period.ends_at
      group by payment.therapist_profile_id
    )
    select jsonb_build_object(
      'status', 'available',
      'cohortDescription', 'Terapeutas ativos comparáveis no período selecionado.',
      'sampleSize', v_benchmark_therapists,
      'minimumTherapists', 20,
      'minimumSessions', 100,
      'methodologyVersion', 'tes-financial-benchmark-v1',
      'metrics', jsonb_build_object(
        'averageTicketCents', jsonb_build_object(
          'therapistValue', v_therapist_average_ticket,
          'cohortMedian', round(v_benchmark_average_ticket_median)::integer,
          'percentile', (
            select round(count(*) filter (
              where average_ticket_cents <= coalesce(v_therapist_average_ticket, 0)
            )::numeric * 100 / greatest(count(*), 1), 1)
            from therapist_stats
          )
        ),
        'returnRate', jsonb_build_object(
          'therapistValue', v_return_rate_90,
          'cohortMedian', v_benchmark_return_rate_median,
          'percentile', null
        ),
        'occupancyRate', jsonb_build_object(
          'therapistValue', v_therapist_occupancy_rate,
          'cohortMedian', v_benchmark_occupancy_median,
          'percentile', null
        )
      )
    )
      into v_benchmark;
  end if;

  if v_expected_potential_cents > 0 then
    v_opportunities := v_opportunities || jsonb_build_array(
      jsonb_build_object(
        'code', 'agenda_open_potential',
        'title', 'Potencial disponível da agenda',
        'description', 'Há horários online disponíveis que podem receber novas reservas sem alterar sua política financeira.',
        'estimatedImpactCents', case
          when v_agenda_confidence in ('medium', 'high') then v_expected_potential_cents
          else null
        end,
        'confidence', v_agenda_confidence,
        'evidence', jsonb_build_array(
          jsonb_build_object(
            'metric', 'availableMinutes',
            'value', v_available_minutes,
            'periodStart', v_forecast_window_start,
            'periodEnd', v_forecast_window_end
          ),
          jsonb_build_object(
            'metric', 'estimatedBookableSlots',
            'value', v_estimated_bookable_slots,
            'periodStart', v_forecast_window_start,
            'periodEnd', v_forecast_window_end
          )
        ),
        'action', 'open_agenda',
        'generatedAt', v_now,
        'methodologyVersion', 'tes-financial-opportunities-v1'
      )
    );
  end if;

  if v_patients_without_return > 0 then
    v_opportunities := v_opportunities || jsonb_build_array(
      jsonb_build_object(
        'code', 'patients_without_return',
        'title', 'Pacientes sem retorno na janela observada',
        'description', 'Existe uma base elegível de pacientes que ainda não teve nova sessão paga dentro da janela de retorno.',
        'estimatedImpactCents', null,
        'confidence', case when v_eligible_patients_90 >= 10 then 'medium' else 'low' end,
        'evidence', jsonb_build_array(
          jsonb_build_object(
            'metric', 'patientsWithoutReturn',
            'value', v_patients_without_return,
            'periodStart', v_period.period_start,
            'periodEnd', v_period.period_end
          )
        ),
        'action', 'view_patients_without_return',
        'generatedAt', v_now,
        'methodologyVersion', 'tes-financial-opportunities-v1'
      )
    );
  end if;

  if v_cancelled_count > 0 then
    v_opportunities := v_opportunities || jsonb_build_array(
      jsonb_build_object(
        'code', 'review_cancellations',
        'title', 'Cancelamentos para revisar',
        'description', 'Cancelamentos no período podem indicar horários que precisam de acompanhamento operacional.',
        'estimatedImpactCents', null,
        'confidence', 'medium',
        'evidence', jsonb_build_array(
          jsonb_build_object(
            'metric', 'cancelledSessions',
            'value', v_cancelled_count,
            'periodStart', v_period.period_start,
            'periodEnd', v_period.period_end
          )
        ),
        'action', 'review_cancellations',
        'generatedAt', v_now,
        'methodologyVersion', 'tes-financial-opportunities-v1'
      )
    );
  end if;

  if jsonb_array_length(v_opportunities) = 0 then
    v_opportunities := jsonb_build_array(
      jsonb_build_object(
        'code', 'no_actionable_opportunity',
        'title', 'Sem oportunidade financeira confiável neste período',
        'description', 'Os dados atuais não sustentam uma recomendação financeira acionável. Continue acompanhando conforme novas sessões forem confirmadas.',
        'estimatedImpactCents', null,
        'confidence', 'low',
        'evidence', '[]'::jsonb,
        'action', 'none',
        'generatedAt', v_now,
        'methodologyVersion', 'tes-financial-opportunities-v1'
      )
    );
  end if;

  v_insights := (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'code', opportunity ->> 'code',
        'title', opportunity ->> 'title',
        'explanation', opportunity ->> 'description',
        'evidence', opportunity -> 'evidence',
        'action', opportunity ->> 'action',
        'generatedAt', opportunity ->> 'generatedAt',
        'methodologyVersion', 'tes-financial-opportunities-v1'
      )
    ), '[]'::jsonb)
    from jsonb_array_elements(v_opportunities) as item(opportunity)
  );

  return jsonb_build_object(
    'contractVersion', 1,
    'therapistProfileId', p_therapist_profile_id,
    'plan', p_plan,
    'period', jsonb_build_object(
      'start', v_period.period_start,
      'end', v_period.period_end,
      'previousStart', v_previous_period_start,
      'previousEnd', v_previous_period_end,
      'timezone', v_period.timezone,
      'generatedAt', v_now,
      'isPartial', v_period.period_end = v_today,
      'forecastMonthStart', v_forecast_month_start,
      'forecastMonthEnd', v_forecast_month_end
    ),
    'forecast', jsonb_build_object(
      'status', 'available',
      'reason', null,
      'realizedNetCents', v_realized_net_cents,
      'contractedFutureNetCents', v_contracted_future_net_cents,
      'estimatedOpenAgendaPotentialCents', v_expected_potential_cents,
      'contractedMonthNetCents', v_contracted_month_net_cents,
      'totalEstimatedPotentialCents',
        v_contracted_month_net_cents + v_expected_potential_cents,
      'confidence', v_forecast_confidence,
      'methodologyVersion', 'tes-financial-forecast-v1'
    ),
    'agendaPotential', jsonb_build_object(
      'status', case
        when v_active_service_count = 0 then 'unavailable'
        when v_scheduled_minutes = 0 then 'insufficient_data'
        else 'available'
      end,
      'reason', case
        when v_active_service_count = 0 then 'no_active_services'
        when v_scheduled_minutes = 0 then 'no_availability_rules'
        else null
      end,
      'windowStart', v_forecast_window_start,
      'windowEnd', v_forecast_window_end,
      'availableMinutes', v_available_minutes,
      'capacityMinutes', v_scheduled_minutes,
      'committedMinutes', v_committed_minutes,
      'estimatedBookableSlots', v_estimated_bookable_slots,
      'conservativePotentialCents', v_conservative_potential_cents,
      'expectedPotentialCents', v_expected_potential_cents,
      'maximumPotentialCents', v_maximum_potential_cents,
      'occupancyRate', v_therapist_occupancy_rate,
      'methodologyVersion', 'tes-agenda-potential-v1',
      'confidence', v_agenda_confidence
    ),
    'opportunities', jsonb_build_object(
      'status', case
        when jsonb_array_length(v_opportunities) = 0 then 'unavailable'
        else 'available'
      end,
      'primary', v_opportunities -> 0,
      'items', v_opportunities,
      'methodologyVersion', 'tes-financial-opportunities-v1'
    ),
    'retention', jsonb_build_object(
      'status', case
        when v_eligible_patients_90 < 10 then 'insufficient_data'
        else 'available'
      end,
      'observationWindowsDays', jsonb_build_array(30, 60, 90),
      'primaryWindowDays', 90,
      'minimumEligiblePatients', 10,
      'eligiblePatients', v_eligible_patients_90,
      'returningPatients', v_returning_patients_90,
      'withoutReturnPatients', v_patients_without_return,
      'returnRate', v_return_rate_90,
      'medianDaysToReturn', case
        when v_median_days_to_return is null then null
        else round(v_median_days_to_return, 1)
      end,
      'cohorts', v_retention_cohorts,
      'methodologyVersion', 'tes-retention-v1'
    ),
    'benchmark', v_benchmark,
    'revenueByTherapy', v_revenue_by_therapy,
    'financialEvolution', v_evolution,
    'insights', jsonb_build_object(
      'status', 'available',
      'items', v_insights,
      'methodologyVersion', 'tes-financial-opportunities-v1'
    ),
    'methodologies', jsonb_build_array(
      jsonb_build_object(
        'version', 'tes-financial-forecast-v1',
        'description', 'Separa realizado líquido, receita contratada futura e potencial estimado da agenda sem misturar valores garantidos e estimados.'
      ),
      jsonb_build_object(
        'version', 'tes-agenda-potential-v1',
        'description', 'Deduplica janelas de disponibilidade, subtrai bloqueios e reservas pagas, usa duração média dos serviços ativos e preço médio histórico quando disponível.'
      ),
      jsonb_build_object(
        'version', 'tes-retention-v1',
        'description', 'Usa primeira sessão concluída, retorno pago em até 90 dias e censura janelas incompletas.'
      ),
      jsonb_build_object(
        'version', 'tes-financial-benchmark-v1',
        'description', 'Suprime benchmark quando há menos de 20 terapeutas elegíveis ou menos de 100 sessões agregadas.'
      ),
      jsonb_build_object(
        'version', 'tes-financial-opportunities-v1',
        'description', 'Gera oportunidades determinísticas a partir de agenda, retorno e cancelamentos sem IA generativa.'
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."private_therapist_finance_advanced_dashboard_payload_v1"("p_therapist_profile_id" "uuid", "p_plan" "public"."therapist_plan", "p_period_start" "date", "p_period_end" "date", "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_therapist_finance_advanced_dashboard_payload_v1"("p_therapist_profile_id" "uuid", "p_plan" "public"."therapist_plan", "p_period_start" "date", "p_period_end" "date", "p_timezone" "text") IS 'Private F3 advanced dashboard payload. Revenue already realized and sessions already paid for the month remain visible independently from agenda-potential availability; estimated potential stays separate from guaranteed revenue.';



CREATE OR REPLACE FUNCTION "public"."private_therapist_finance_metric_comparison_v1"("p_current_value" numeric, "p_previous_value" numeric, "p_current_has_data" boolean, "p_previous_has_data" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_current numeric := coalesce(p_current_value, 0);
  v_previous numeric := p_previous_value;
begin
  if not coalesce(p_current_has_data, false) then
    return jsonb_build_object(
      'currentValue', v_current,
      'previousValue', case when p_previous_has_data then v_previous else null end,
      'absoluteDelta', null,
      'percentageDelta', null,
      'comparisonStatus', 'insufficient_data'
    );
  end if;

  if not coalesce(p_previous_has_data, false) then
    return jsonb_build_object(
      'currentValue', v_current,
      'previousValue', null,
      'absoluteDelta', null,
      'percentageDelta', null,
      'comparisonStatus', 'no_previous_data'
    );
  end if;

  if coalesce(v_previous, 0) = 0 then
    return jsonb_build_object(
      'currentValue', v_current,
      'previousValue', coalesce(v_previous, 0),
      'absoluteDelta', v_current - coalesce(v_previous, 0),
      'percentageDelta', null,
      'comparisonStatus', 'division_by_zero'
    );
  end if;

  return jsonb_build_object(
    'currentValue', v_current,
    'previousValue', v_previous,
    'absoluteDelta', v_current - v_previous,
    'percentageDelta', round(((v_current - v_previous) * 100 / v_previous), 1),
    'comparisonStatus', 'available'
  );
end;
$$;


ALTER FUNCTION "public"."private_therapist_finance_metric_comparison_v1"("p_current_value" numeric, "p_previous_value" numeric, "p_current_has_data" boolean, "p_previous_has_data" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."session_payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "patient_profile_id" "uuid" NOT NULL,
    "therapist_profile_id" "uuid" NOT NULL,
    "service_id" "uuid" NOT NULL,
    "policy_version_id" "uuid" NOT NULL,
    "stripe_customer_id" "uuid",
    "stripe_checkout_session_id" "text",
    "stripe_payment_intent_id" "text",
    "stripe_charge_id" "text",
    "stripe_balance_transaction_id" "text",
    "gross_amount_cents" integer NOT NULL,
    "platform_commission_bps" integer NOT NULL,
    "platform_gross_commission_cents" integer NOT NULL,
    "therapist_amount_cents" integer NOT NULL,
    "stripe_fee_amount_cents" integer,
    "stripe_net_amount_cents" integer,
    "currency" character(3) DEFAULT 'BRL'::"bpchar" NOT NULL,
    "financial_status" "public"."session_financial_status" DEFAULT 'pending'::"public"."session_financial_status" NOT NULL,
    "service_status" "public"."session_service_status" DEFAULT 'scheduled'::"public"."session_service_status" NOT NULL,
    "transfer_status" "public"."session_transfer_status" DEFAULT 'not_eligible'::"public"."session_transfer_status" NOT NULL,
    "service_confirmed_at" timestamp with time zone,
    "service_confirmation_source" "public"."session_confirmation_source",
    "eligible_at" timestamp with time zone,
    "transfer_blocked_reason" "text",
    "refund_pending" boolean DEFAULT false NOT NULL,
    "disputed_at" timestamp with time zone,
    "internal_contested_at" timestamp with time zone,
    "admin_blocked_at" timestamp with time zone,
    "paid_at" timestamp with time zone,
    "failed_at" timestamp with time zone,
    "canceled_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "stripe_event_id" "text",
    "stripe_event_created_at" timestamp with time zone,
    "stripe_balance_status" "text",
    "stripe_balance_available_on" timestamp with time zone,
    "stripe_balance_checked_at" timestamp with time zone,
    "payment_flow_version" "text" DEFAULT 'v9'::"text" NOT NULL,
    "connect_account_id_snapshot" "uuid",
    "stripe_connect_account_id_snapshot" "text",
    "payment_due_at" timestamp with time zone,
    CONSTRAINT "session_payments_amounts_non_negative" CHECK ((("gross_amount_cents" >= 0) AND (("platform_commission_bps" >= 0) AND ("platform_commission_bps" <= 10000)) AND ("platform_gross_commission_cents" >= 0) AND ("therapist_amount_cents" >= 0))),
    CONSTRAINT "session_payments_amounts_reconcile" CHECK (("gross_amount_cents" = ("platform_gross_commission_cents" + "therapist_amount_cents"))),
    CONSTRAINT "session_payments_currency_brl" CHECK (("currency" = 'BRL'::"bpchar")),
    CONSTRAINT "session_payments_flow_version_check" CHECK (("payment_flow_version" = ANY (ARRAY['v9'::"text", 'v10'::"text"]))),
    CONSTRAINT "session_payments_stripe_balance_status_check" CHECK ((("stripe_balance_status" IS NULL) OR ("stripe_balance_status" = ANY (ARRAY['pending'::"text", 'available'::"text"])))),
    CONSTRAINT "session_payments_v10_snapshot_check" CHECK ((("payment_flow_version" = 'v9'::"text") OR (("connect_account_id_snapshot" IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM "stripe_connect_account_id_snapshot"), ''::"text") IS NOT NULL) AND ("payment_due_at" IS NOT NULL))))
);


ALTER TABLE "public"."session_payments" OWNER TO "postgres";


COMMENT ON TABLE "public"."session_payments" IS 'Fonte financeira canônica para cobranças de sessão TES. Valores são snapshots em centavos.';



COMMENT ON COLUMN "public"."session_payments"."stripe_balance_status" IS 'Last verified status of the source Charge Balance Transaction. Only available may authorize weekly Transfer eligibility.';



COMMENT ON COLUMN "public"."session_payments"."stripe_balance_available_on" IS 'Provider availability instant from the source Charge Balance Transaction.';



COMMENT ON COLUMN "public"."session_payments"."stripe_balance_checked_at" IS 'Instant when the source Charge Balance Transaction snapshot was verified against Stripe.';



COMMENT ON COLUMN "public"."session_payments"."payment_flow_version" IS 'Immutable policy family. V9 remains weekly-batch; V10 uses T-24 charge and direct Transfer.';



CREATE OR REPLACE FUNCTION "public"."private_therapist_finance_net_cents_v1"("p_payment" "public"."session_payments") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (
    p_payment.gross_amount_cents
    - p_payment.platform_gross_commission_cents
    - public.private_therapist_finance_refunded_cents_v1(p_payment.id)
  )::integer;
$$;


ALTER FUNCTION "public"."private_therapist_finance_net_cents_v1"("p_payment" "public"."session_payments") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_therapist_finance_refunded_cents_v1"("p_session_payment_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(sum(refund.amount_cents), 0)::integer
  from public.session_refunds as refund
  where refund.session_payment_id = p_session_payment_id
    and refund.status = 'succeeded';
$$;


ALTER FUNCTION "public"."private_therapist_finance_refunded_cents_v1"("p_session_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_therapist_payouts_v2_legacy_blocked_card"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_therapist public.therapist_profiles%rowtype; v_period record;
  v_page integer:=greatest(coalesce(p_page,1),1); v_page_size integer:=least(greatest(coalesce(p_page_size,20),1),500); v_offset integer;
  v_total_count integer:=0; v_items jsonb:='[]'::jsonb; v_summary jsonb:='{}'::jsonb;
begin
  if p_status is not null and p_status not in ('waiting_confirmation','waiting_safety_period','waiting_settlement','eligible','batched','transfer_pending','bank_pending','paid','blocked','failed','reversed') then raise exception 'VALIDATION_ERROR' using errcode='22023'; end if;
  v_therapist:=public.get_private_therapist_financial_actor_v1(); v_offset:=(v_page-1)*v_page_size;
  select * into v_period from public.normalize_private_therapist_finance_period_v1(p_period_start,p_period_end,p_timezone);
  with batch_rows as (
    select batch.id payout_batch_id,batch.reference_period_start period_start,batch.reference_period_end period_end,batch.cutoff_at expected_transfer_at,max(transfer.transferred_at) transferred_at,max(transfer.updated_at) reconciliation_updated_at,max(transfer.stripe_transfer_id) stripe_transfer_id,max(transfer.stripe_source_charge_id) stripe_source_charge_id,
      coalesce(sum(payment.gross_amount_cents),0)::integer gross_amount_cents,coalesce(sum(payment.platform_gross_commission_cents),0)::integer tes_commission_cents,coalesce(sum(public.private_therapist_finance_refunded_cents_v1(payment.id)),0)::integer refunded_amount_cents,coalesce(sum(item.amount_cents),0)::integer therapist_net_amount_cents,count(distinct item.session_payment_id)::integer session_count,
      case when bool_or(transfer.status='reversed' or payment.transfer_status='reversed') then 'reversed' when bool_or(transfer.status='failed' or item.status='failed' or payment.transfer_status='failed') then 'failed' when bool_or(item.status='blocked' or payment.transfer_status='blocked') then 'blocked'
        when bool_and(item.status='transferred' and transfer.status='transferred' and exists(select 1 from public.stripe_payout_transfer_allocations allocation join public.stripe_payouts payout on payout.id=allocation.stripe_payout_id where allocation.stripe_transfer_id=transfer.id and payout.status='paid' and payout.provider_reconciliation_status='completed' and payout.allocation_status='completed' and allocation.amount_cents=transfer.amount_cents)) then 'paid'
        when bool_and(item.status='transferred' and transfer.status='transferred') then 'bank_pending'
        when bool_or(item.status='transfer_pending' or transfer.status='pending') or batch.status='processing' then 'transfer_pending' else 'batched' end transfer_status,
      case when bool_or(transfer.status='failed' or item.status='failed') then 'failed' when bool_or(transfer.status='reversed') then 'reversed'
        when bool_and(exists(select 1 from public.stripe_payout_transfer_allocations allocation join public.stripe_payouts payout on payout.id=allocation.stripe_payout_id where allocation.stripe_transfer_id=transfer.id and payout.status='paid' and payout.provider_reconciliation_status='completed' and payout.allocation_status='completed' and allocation.amount_cents=transfer.amount_cents)) then 'paid'
        when bool_and(transfer.stripe_transfer_id is not null and transfer.stripe_source_charge_id is not null and item.status='transferred') then 'matched' when bool_or(item.status in ('reserved','transfer_pending')) then 'pending' else 'needs_reconciliation' end reconciliation_status,
      max(item.failure_code) filter(where item.status='blocked') blocked_reason,max(item.failure_code) filter(where item.status='failed' or transfer.status='failed') failed_reason
    from public.payout_batch_items item join public.payout_batches batch on batch.id=item.payout_batch_id join public.session_payments payment on payment.id=item.session_payment_id left join public.stripe_transfers transfer on transfer.payout_batch_item_id=item.id
    where item.therapist_profile_id=v_therapist.id and batch.reference_period_start>=v_period.period_start and batch.reference_period_start<=v_period.period_end and item.status<>'removed'
    group by batch.id,batch.reference_period_start,batch.reference_period_end,batch.cutoff_at,batch.status
  ),filtered as(select * from batch_rows where p_status is null or transfer_status=p_status),counted as(select count(*)::integer count from filtered),paged as(select * from filtered order by period_start desc,payout_batch_id desc limit v_page_size offset v_offset)
  select counted.count,coalesce(jsonb_agg(jsonb_build_object('payoutBatchId',paged.payout_batch_id,'periodStart',paged.period_start,'periodEnd',paged.period_end,'grossAmountCents',paged.gross_amount_cents,'tesCommissionCents',paged.tes_commission_cents,'refundedAmountCents',paged.refunded_amount_cents,'therapistNetAmountCents',paged.therapist_net_amount_cents,'transferStatus',paged.transfer_status,'expectedTransferAt',paged.expected_transfer_at,'transferredAt',paged.transferred_at,'blockedReason',paged.blocked_reason,'failedReason',paged.failed_reason,'sessionCount',paged.session_count,'stripeTransferId',paged.stripe_transfer_id,'stripeSourceChargeId',paged.stripe_source_charge_id,'reconciliationStatus',paged.reconciliation_status,'reconciliationUpdatedAt',paged.reconciliation_updated_at) order by paged.period_start desc,paged.payout_batch_id desc) filter(where paged.payout_batch_id is not null),'[]'::jsonb)
  into v_total_count,v_items from counted left join paged on true group by counted.count;
  select jsonb_build_object(
    'eligibleForPayoutCents',coalesce(sum(payment.therapist_amount_cents) filter(where payment.transfer_status='eligible' and payment.stripe_balance_status='available' and payment.stripe_balance_available_on<=now()),0)::integer,
    'waitingConfirmationCents',coalesce(sum(payment.therapist_amount_cents) filter(where payment.transfer_status='waiting_confirmation'),0)::integer,
    'waitingSafetyPeriodCents',coalesce(sum(payment.therapist_amount_cents) filter(where payment.transfer_status='waiting_safety_period'),0)::integer,
    'waitingSettlementCents',coalesce(sum(payment.therapist_amount_cents) filter(where payment.transfer_status='waiting_settlement'),0)::integer,
    'payoutProcessingCents',coalesce(sum(payment.therapist_amount_cents) filter(where public.private_therapist_receipt_status_v2(payment.id) in ('receivable','waiting_confirmation','waiting_safety_period','waiting_settlement','eligible','payout_processing','bank_pending')),0)::integer,
    'blockedCents',coalesce(sum(payment.therapist_amount_cents) filter(where payment.transfer_status='blocked'),0)::integer,
    'blockedReasonCodes',coalesce((select jsonb_agg(distinct case when blocked.transfer_blocked_reason='connect_not_ready' then 'account' when blocked.transfer_blocked_reason in ('refund','manual_refund_review') then 'refund' when blocked.transfer_blocked_reason in ('disputed','blocked_or_contested','participant_reported_not_performed') then 'review' else 'other' end) from public.session_payments blocked where blocked.therapist_profile_id=v_therapist.id and blocked.transfer_status='blocked'),'[]'::jsonb),
    'nextBatchAt',case when exists(select 1 from public.session_payments eligible join public.therapist_connect_accounts account on account.therapist_profile_id=eligible.therapist_profile_id and account.is_current=true and account.stripe_transfers_status='active' and account.payouts_enabled=true and account.payout_status='enabled' and account.payout_schedule_interval='daily' and account.operational_status='ready' where eligible.therapist_profile_id=v_therapist.id and eligible.transfer_status='eligible' and eligible.stripe_balance_status='available' and eligible.stripe_balance_available_on<=now() and eligible.therapist_amount_cents>0) then public.next_weekly_payout_cutoff_v1(now(),now()) else null end
  ) into v_summary from public.session_payments payment where payment.therapist_profile_id=v_therapist.id;
  return jsonb_build_object('contractVersion',2,'therapistProfileId',v_therapist.id,'items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_page_size,'totalCount',v_total_count,'totalPages',case when v_total_count=0 then 0 else ceil(v_total_count::numeric/v_page_size)::integer end,'hasNextPage',v_offset+v_page_size<v_total_count),'filters',jsonb_build_object('status',p_status,'periodStart',v_period.period_start,'periodEnd',v_period.period_end,'timezone',v_period.timezone),'summary',v_summary,'generatedAt',now());
end; $$;


ALTER FUNCTION "public"."private_therapist_payouts_v2_legacy_blocked_card"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_therapist_payouts_v2_legacy_blocked_card"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") IS 'Therapist payout history and current position. Paid requires a fully reconciled automatic Payout allocation.';



CREATE OR REPLACE FUNCTION "public"."private_therapist_payouts_v2_v10_gross_processing_legacy"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_legacy jsonb;
  v_therapist public.therapist_profiles%rowtype;
  v_period record;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := least(greatest(coalesce(p_page_size, 20), 1), 500);
  v_offset integer;
  v_total_count integer := 0;
  v_items jsonb := '[]'::jsonb;
begin
  -- The legacy reader performs the canonical actor authorization and provides
  -- the current-position summary shared by both payment versions.
  v_legacy := public.private_therapist_payouts_v2_v9_history_legacy(
    p_period_start, p_period_end, p_status, 1, 1, p_timezone
  );
  v_therapist := public.get_private_therapist_financial_actor_v1();
  v_offset := (v_page - 1) * v_page_size;
  select * into v_period
  from public.normalize_private_therapist_finance_period_v1(
    p_period_start, p_period_end, p_timezone
  );

  with v9_batch_rows as (
    select
      batch.id as payout_item_id,
      batch.id as payout_batch_id,
      'weekly_batch'::text as source_kind,
      batch.reference_period_start as period_start,
      batch.reference_period_end as period_end,
      batch.cutoff_at as expected_transfer_at,
      max(transfer.transferred_at) as transferred_at,
      max(transfer.updated_at) as reconciliation_updated_at,
      coalesce(sum(payment.gross_amount_cents), 0)::integer as gross_amount_cents,
      coalesce(sum(payment.platform_gross_commission_cents), 0)::integer
        as tes_commission_cents,
      coalesce(sum(public.private_therapist_finance_refunded_cents_v1(payment.id)), 0)::integer
        as refunded_amount_cents,
      coalesce(sum(item.amount_cents), 0)::integer as therapist_net_amount_cents,
      0::integer as debt_offset_amount_cents,
      count(distinct item.session_payment_id)::integer as session_count,
      case
        when bool_or(transfer.status = 'reversed' or payment.transfer_status = 'reversed')
          then 'reversed'
        when bool_or(
          transfer.status = 'failed'
          or item.status = 'failed'
          or payment.transfer_status = 'failed'
        ) then 'failed'
        when bool_or(item.status = 'blocked' or payment.transfer_status = 'blocked')
          then 'blocked'
        when bool_and(
          item.status = 'transferred'
          and transfer.status = 'transferred'
          and exists (
            select 1
            from public.stripe_payout_transfer_allocations allocation
            join public.stripe_payouts payout on payout.id = allocation.stripe_payout_id
            where allocation.stripe_transfer_id = transfer.id
              and payout.status = 'paid'
              and payout.provider_reconciliation_status = 'completed'
              and payout.allocation_status = 'completed'
              and allocation.amount_cents = transfer.amount_cents
          )
        ) then 'paid'
        when bool_and(item.status = 'transferred' and transfer.status = 'transferred')
          then 'bank_pending'
        when bool_or(item.status = 'transfer_pending' or transfer.status = 'pending')
          or batch.status = 'processing'
          then 'transfer_pending'
        else 'batched'
      end as transfer_status,
      case
        when bool_or(transfer.status = 'failed' or item.status = 'failed') then 'failed'
        when bool_or(transfer.status = 'reversed') then 'reversed'
        when bool_and(exists (
          select 1
          from public.stripe_payout_transfer_allocations allocation
          join public.stripe_payouts payout on payout.id = allocation.stripe_payout_id
          where allocation.stripe_transfer_id = transfer.id
            and payout.status = 'paid'
            and payout.provider_reconciliation_status = 'completed'
            and payout.allocation_status = 'completed'
            and allocation.amount_cents = transfer.amount_cents
        )) then 'paid'
        when bool_and(
          transfer.stripe_transfer_id is not null
          and transfer.stripe_source_charge_id is not null
          and item.status = 'transferred'
        ) then 'matched'
        when bool_or(item.status in ('reserved', 'transfer_pending')) then 'pending'
        else 'needs_reconciliation'
      end as reconciliation_status,
      case when bool_or(item.status = 'blocked')
        then 'Repasse em análise.' else null end as blocked_reason,
      case when bool_or(item.status = 'failed' or transfer.status = 'failed')
        then 'Não foi possível concluir. Nossa equipe foi avisada.' else null end
        as failed_reason
    from public.payout_batch_items item
    join public.payout_batches batch on batch.id = item.payout_batch_id
    join public.session_payments payment on payment.id = item.session_payment_id
    left join public.stripe_transfers transfer on transfer.payout_batch_item_id = item.id
    where item.therapist_profile_id = v_therapist.id
      and batch.reference_period_start >= v_period.period_start
      and batch.reference_period_start <= v_period.period_end
      and item.status <> 'removed'
    group by
      batch.id, batch.reference_period_start, batch.reference_period_end,
      batch.cutoff_at, batch.status
  ), v10_direct_rows as (
    select
      job.id as payout_item_id,
      null::uuid as payout_batch_id,
      'session_direct'::text as source_kind,
      (booking.starts_at at time zone v_period.timezone)::date as period_start,
      (booking.starts_at at time zone v_period.timezone)::date as period_end,
      coalesce(payment.paid_at, job.created_at) as expected_transfer_at,
      case when paid_payout.id is not null then paid_payout.paid_at else null end
        as transferred_at,
      greatest(job.updated_at, transfer.updated_at, paid_payout.updated_at)
        as reconciliation_updated_at,
      payment.gross_amount_cents,
      payment.platform_gross_commission_cents as tes_commission_cents,
      public.private_therapist_finance_refunded_cents_v1(payment.id)::integer
        as refunded_amount_cents,
      job.transfer_amount_cents as therapist_net_amount_cents,
      job.debt_offset_amount_cents,
      1::integer as session_count,
      case
        when job.status = 'reversed' or transfer.status = 'reversed' then 'reversed'
        when job.status in ('partially_reversed', 'failed', 'reconciliation_required')
          or transfer.status in ('failed', 'reconciliation_required') then 'failed'
        when paid_payout.id is not null then 'paid'
        when transfer.status = 'transferred'
          or job.status in ('pending_source', 'transferred') then 'bank_pending'
        else 'transfer_pending'
      end as transfer_status,
      case
        when job.status = 'reversed' or transfer.status = 'reversed' then 'reversed'
        when job.status in ('partially_reversed', 'failed') or transfer.status = 'failed'
          then 'failed'
        when job.status = 'reconciliation_required'
          or transfer.status = 'reconciliation_required' then 'needs_reconciliation'
        when paid_payout.id is not null then 'paid'
        when transfer.status = 'transferred' and transfer.stripe_transfer_id is not null
          then 'matched'
        else 'pending'
      end as reconciliation_status,
      null::text as blocked_reason,
      case
        when job.status = 'partially_reversed'
          then 'Este repasse precisa de análise da nossa equipe.'
        when job.status in ('failed', 'reconciliation_required')
          or transfer.status in ('failed', 'reconciliation_required')
          then 'Não foi possível concluir. Nossa equipe foi avisada.'
        else null
      end as failed_reason
    from public.session_transfer_jobs job
    join public.session_payments payment on payment.id = job.session_payment_id
    join public.bookings booking on booking.id = job.booking_id
    left join public.stripe_transfers transfer on transfer.id = job.stripe_transfer_id
    left join lateral (
      select payout.id, payout.paid_at, payout.updated_at
      from public.stripe_payout_transfer_allocations allocation
      join public.stripe_payouts payout on payout.id = allocation.stripe_payout_id
      where allocation.stripe_transfer_id = transfer.id
        and allocation.allocation_origin = 'session_direct'
        and payout.status = 'paid'
        and payout.provider_reconciliation_status = 'completed'
        and payout.allocation_status = 'completed'
        and allocation.amount_cents = transfer.amount_cents
      order by payout.paid_at desc nulls last, payout.id desc
      limit 1
    ) paid_payout on true
    where payment.therapist_profile_id = v_therapist.id
      and payment.payment_flow_version = 'v10'
      and job.status <> 'offset_only'
      and (booking.starts_at at time zone v_period.timezone)::date
        between v_period.period_start and v_period.period_end
  ), all_rows as (
    select * from v9_batch_rows
    union all
    select * from v10_direct_rows
  ), filtered as (
    select * from all_rows
    where p_status is null or transfer_status = p_status
  ), counted as (
    select count(*)::integer as count from filtered
  ), paged as (
    select * from filtered
    order by period_start desc, payout_item_id desc
    limit v_page_size offset v_offset
  )
  select
    counted.count,
    coalesce(jsonb_agg(jsonb_build_object(
      'payoutItemId', paged.payout_item_id,
      'payoutBatchId', paged.payout_batch_id,
      'sourceKind', paged.source_kind,
      'periodStart', paged.period_start,
      'periodEnd', paged.period_end,
      'grossAmountCents', paged.gross_amount_cents,
      'tesCommissionCents', paged.tes_commission_cents,
      'refundedAmountCents', paged.refunded_amount_cents,
      'therapistNetAmountCents', paged.therapist_net_amount_cents,
      'debtOffsetAmountCents', paged.debt_offset_amount_cents,
      'transferStatus', paged.transfer_status,
      'expectedTransferAt', paged.expected_transfer_at,
      'transferredAt', paged.transferred_at,
      'blockedReason', paged.blocked_reason,
      'failedReason', paged.failed_reason,
      'sessionCount', paged.session_count,
      'stripeTransferId', null,
      'stripeSourceChargeId', null,
      'reconciliationStatus', paged.reconciliation_status,
      'reconciliationUpdatedAt', paged.reconciliation_updated_at
    ) order by paged.period_start desc, paged.payout_item_id desc)
      filter (where paged.payout_item_id is not null), '[]'::jsonb)
  into v_total_count, v_items
  from counted
  left join paged on true
  group by counted.count;

  return jsonb_build_object(
    'contractVersion', 2,
    'therapistProfileId', v_therapist.id,
    'items', v_items,
    'pagination', jsonb_build_object(
      'page', v_page,
      'pageSize', v_page_size,
      'totalCount', v_total_count,
      'totalPages', case when v_total_count = 0 then 0
        else ceil(v_total_count::numeric / v_page_size)::integer end,
      'hasNextPage', v_offset + v_page_size < v_total_count
    ),
    'filters', jsonb_build_object(
      'status', p_status,
      'periodStart', v_period.period_start,
      'periodEnd', v_period.period_end,
      'timezone', v_period.timezone
    ),
    'summary', v_legacy -> 'summary',
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."private_therapist_payouts_v2_v10_gross_processing_legacy"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_therapist_payouts_v2_v10_gross_processing_legacy"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") IS 'Therapist payout history unifies V9 weekly batches and V10 direct transfers without duplicate rows. Provider identifiers remain private; paid requires a fully reconciled automatic payout allocation.';



CREATE OR REPLACE FUNCTION "public"."private_therapist_payouts_v2_v9_history_legacy"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payload jsonb;
  v_summary jsonb;
  v_therapist public.therapist_profiles%rowtype;
  v_processing_cents integer := 0;
  v_blocked_cents integer := 0;
  v_blocked_reason_codes jsonb := '[]'::jsonb;
begin
  v_payload := public.private_therapist_payouts_v2_legacy_blocked_card(
    p_period_start,
    p_period_end,
    p_status,
    p_page,
    p_page_size,
    p_timezone
  );
  v_therapist := public.get_private_therapist_financial_actor_v1();

  select coalesce(sum(payment.therapist_amount_cents), 0)::integer
    into v_processing_cents
  from public.session_payments payment
  where payment.therapist_profile_id = v_therapist.id
    and public.private_therapist_receipt_status_v2(payment.id) in (
      'waiting_confirmation',
      'waiting_safety_period',
      'waiting_settlement',
      'eligible',
      'payout_processing',
      'bank_pending'
    );

  select
    coalesce(sum(payment.therapist_amount_cents), 0)::integer,
    coalesce(
      jsonb_agg(distinct case
        when payment.transfer_blocked_reason = 'connect_not_ready' then 'account'
        when payment.transfer_blocked_reason in ('refund', 'manual_refund_review') then 'refund'
        when payment.transfer_blocked_reason in (
          'disputed', 'blocked_or_contested', 'participant_reported_not_performed'
        ) then 'review'
        else 'other'
      end),
      '[]'::jsonb
    )
    into v_blocked_cents, v_blocked_reason_codes
  from public.session_payments payment
  where payment.therapist_profile_id = v_therapist.id
    and public.private_therapist_receipt_status_v2(payment.id) = 'blocked';

  v_summary := coalesce(v_payload->'summary', '{}'::jsonb)
    || jsonb_build_object(
      'blockedCents', v_blocked_cents,
      'blockedReasonCodes', v_blocked_reason_codes,
      'payoutProcessingCents', v_processing_cents
    );

  return jsonb_set(v_payload, '{summary}', v_summary, true);
end;
$$;


ALTER FUNCTION "public"."private_therapist_payouts_v2_v9_history_legacy"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_therapist_payouts_v2_v9_history_legacy"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") IS 'Repasses v2; processamento exclui sessoes futuras no estado A receber e o card bloqueado considera apenas impedimentos operacionais ativos derivados.';



CREATE OR REPLACE FUNCTION "public"."private_therapist_receipt_status_v2"("p_session_payment_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when payment.financial_status = 'disputed' or payment.disputed_at is not null then 'disputed'
    when payment.financial_status = 'refunded' then 'refunded'
    when payment.financial_status = 'canceled' then 'canceled'
    when payment.financial_status = 'failed' then 'failed'
    when payment.transfer_status = 'reversed' then 'reversed'
    when payment.transfer_status = 'failed' then 'failed'
    when payment.transfer_status = 'blocked' then 'blocked'
    when exists (
      select 1
      from public.session_transfer_jobs job
      where job.session_payment_id = payment.id
        and job.status = 'offset_only'
        and job.transfer_amount_cents = 0
        and job.debt_offset_amount_cents = job.therapist_gross_amount_cents
        and job.succeeded_at is not null
    ) then 'compensated'
    when exists (
      select 1
      from public.stripe_transfers transfer
      join public.stripe_payout_transfer_allocations allocation
        on allocation.stripe_transfer_id = transfer.id
      join public.stripe_payouts payout
        on payout.id = allocation.stripe_payout_id
      where transfer.session_payment_id = payment.id
        and transfer.status = 'transferred'
        and payout.status = 'paid'
        and payout.provider_reconciliation_status = 'completed'
        and payout.allocation_status = 'completed'
        and allocation.amount_cents = transfer.amount_cents
    ) then 'paid'
    when payment.transfer_status = 'transferred' then 'bank_pending'
    when payment.transfer_status in ('batched', 'transfer_pending') then 'payout_processing'
    when payment.transfer_status = 'eligible' then 'eligible'
    when payment.transfer_status in ('waiting_settlement', 'waiting_safety_period') then 'waiting_settlement'
    when payment.financial_status in ('paid', 'partially_refunded')
      and booking.starts_at > p_now then 'receivable'
    when payment.transfer_status = 'waiting_confirmation' then 'waiting_confirmation'
    when payment.financial_status in ('paid', 'partially_refunded') then 'waiting_confirmation'
    else 'receivable'
  end
  from public.session_payments payment
  join public.bookings booking on booking.id = payment.booking_id
  where payment.id = p_session_payment_id;
$$;


ALTER FUNCTION "public"."private_therapist_receipt_status_v2"("p_session_payment_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_therapist_receipts_monthly_trend_v2"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_therapy_id" "uuid", "p_search" "text", "p_timezone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_period record;
  v_search text := nullif(trim(coalesce(p_search, '')), '');
  v_trend jsonb := '[]'::jsonb;
begin
  v_therapist := public.get_private_therapist_financial_actor_v1();
  select * into v_period
  from public.normalize_private_therapist_finance_period_v1(
    p_period_start, p_period_end, p_timezone
  );

  with months as (
    select
      local_month at time zone v_period.timezone as month_start,
      (local_month + interval '1 month') at time zone v_period.timezone as month_end,
      to_char(local_month, 'YYYY-MM') as month_key
    from generate_series(
      date_trunc('month', v_period.period_start::timestamp),
      date_trunc('month', v_period.period_end::timestamp),
      interval '1 month'
    ) as local_month
  ), scoped as (
    select
      payment.id,
      booking.starts_at as session_date,
      public.private_therapist_receipt_status_v2(payment.id) as receipt_status,
      greatest(
        0,
        payment.gross_amount_cents
          - payment.platform_gross_commission_cents
          - public.private_therapist_finance_refunded_cents_v1(payment.id)
      ) as net_cents
    from public.session_payments payment
    join public.bookings booking on booking.id = payment.booking_id
    left join public.patient_profiles patient on patient.id = payment.patient_profile_id
    left join public.therapist_services service on service.id = payment.service_id
    left join public.therapies therapy on therapy.id = service.therapy_id
    where payment.therapist_profile_id = v_therapist.id
      and (p_therapy_id is null or therapy.id = p_therapy_id)
      and (
        v_search is null
        or patient.display_name ilike '%' || v_search || '%'
        or therapy.name ilike '%' || v_search || '%'
        or booking.service_title_snapshot ilike '%' || v_search || '%'
      )
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'month', months.month_key,
        'processingCents', (
          select coalesce(sum(item.net_cents), 0)::integer
          from scoped item
          where item.session_date >= months.month_start
            and item.session_date < months.month_end
            and item.receipt_status in (
              'receivable', 'waiting_confirmation', 'waiting_safety_period',
              'waiting_settlement', 'eligible', 'payout_processing', 'bank_pending'
            )
            and (p_status is null or item.receipt_status = p_status)
        ),
        'receivedCents', (
          select coalesce(sum(transfer.amount_cents), 0)::integer
          from public.stripe_transfers transfer
          join public.stripe_payout_transfer_allocations allocation
            on allocation.stripe_transfer_id = transfer.id
          join public.stripe_payouts payout
            on payout.id = allocation.stripe_payout_id
          join scoped item on item.id = transfer.session_payment_id
          where payout.status = 'paid'
            and payout.provider_reconciliation_status = 'completed'
            and payout.allocation_status = 'completed'
            and allocation.amount_cents = transfer.amount_cents
            and coalesce(payout.paid_at, payout.updated_at) >= months.month_start
            and coalesce(payout.paid_at, payout.updated_at) < months.month_end
            and (p_status is null or p_status = 'paid')
        )
      ) order by months.month_start
    ),
    '[]'::jsonb
  ) into v_trend
  from months;

  return v_trend;
end;
$$;


ALTER FUNCTION "public"."private_therapist_receipts_monthly_trend_v2"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_therapy_id" "uuid", "p_search" "text", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_therapist_receipts_v2_legacy_timezone"("p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT NULL::"text", "p_therapy_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_period record;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := least(greatest(coalesce(p_page_size, 20), 1), 500);
  v_offset integer;
  v_total_count integer := 0;
  v_items jsonb := '[]'::jsonb;
  v_therapy_options jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_trend jsonb := '[]'::jsonb;
  v_distribution jsonb := '[]'::jsonb;
  v_search text := nullif(trim(coalesce(p_search, '')), '');
begin
  if p_status is not null and p_status not in (
    'receivable', 'waiting_confirmation', 'waiting_safety_period', 'waiting_settlement',
    'eligible', 'payout_processing', 'bank_pending', 'paid', 'blocked', 'failed',
    'reversed', 'refunded', 'canceled', 'disputed'
  ) then raise exception 'VALIDATION_ERROR' using errcode = '22023'; end if;

  v_therapist := public.get_private_therapist_financial_actor_v1();
  v_offset := (v_page - 1) * v_page_size;
  select * into v_period from public.normalize_private_therapist_finance_period_v1(
    p_period_start, p_period_end, p_timezone
  );

  with raw as (
    select payment.id session_payment_id, payment.booking_id,
      coalesce(patient.display_name, 'Paciente') patient_display_name,
      coalesce(therapy.name, booking.service_title_snapshot, service.title) therapy_name_snapshot,
      therapy.id therapy_id, booking.starts_at session_date,
      payment.gross_amount_cents,
      payment.platform_gross_commission_cents tes_commission_cents,
      public.private_therapist_finance_refunded_cents_v1(payment.id) refunded_amount_cents,
      payment.financial_status::text financial_status,
      public.private_therapist_receipt_status_v2(payment.id) receipt_status,
      coalesce(nullif(payment.metadata ->> 'paymentMethodType',''), nullif(payment.metadata ->> 'payment_method_type',''), nullif(payment.metadata #>> '{payment_method,type}','')) payment_method_type,
      coalesce(nullif(payment.metadata ->> 'paymentOrigin',''), nullif(payment.metadata ->> 'payment_origin',''), case when payment.stripe_checkout_session_id is not null then 'stripe_checkout' else 'unknown' end) payment_origin,
      receipt.receipt_url,
      (select dispute.status from public.session_disputes dispute where dispute.session_payment_id=payment.id order by dispute.opened_at desc limit 1) dispute_status,
      bank.received_at,
      bank.received_amount_cents,
      payment.created_at
    from public.session_payments payment
    join public.bookings booking on booking.id=payment.booking_id
    left join public.patient_profiles patient on patient.id=payment.patient_profile_id
    left join public.therapist_services service on service.id=payment.service_id
    left join public.therapies therapy on therapy.id=service.therapy_id
    left join public.booking_payment_receipts receipt on receipt.booking_id=payment.booking_id
    left join lateral (
      select max(coalesce(payout.paid_at,payout.updated_at)) received_at,
        sum(transfer.amount_cents)::integer received_amount_cents
      from public.stripe_transfers transfer
      join public.stripe_payout_transfer_allocations allocation on allocation.stripe_transfer_id=transfer.id
      join public.stripe_payouts payout on payout.id=allocation.stripe_payout_id
      where transfer.session_payment_id=payment.id and transfer.status='transferred'
        and payout.status='paid' and payout.provider_reconciliation_status='completed'
        and payout.allocation_status='completed'
        and allocation.amount_cents=transfer.amount_cents
    ) bank on true
    where payment.therapist_profile_id=v_therapist.id
      and (p_therapy_id is null or therapy.id=p_therapy_id)
      and (v_search is null or patient.display_name ilike '%'||v_search||'%' or therapy.name ilike '%'||v_search||'%' or booking.service_title_snapshot ilike '%'||v_search||'%')
  ), base as (
    select * from raw
    where (receipt_status='paid' and received_at>=v_period.starts_at and received_at<v_period.ends_at)
       or (receipt_status<>'paid' and session_date>=v_period.starts_at and session_date<v_period.ends_at)
  ), filtered as (select * from base where p_status is null or receipt_status=p_status),
  counted as (select count(*)::integer count from filtered),
  paged as (select * from filtered order by coalesce(received_at,session_date,created_at) desc,session_payment_id desc limit v_page_size offset v_offset)
  select counted.count, coalesce(jsonb_agg(jsonb_build_object(
    'sessionPaymentId',paged.session_payment_id,'bookingId',paged.booking_id,
    'patientDisplayName',paged.patient_display_name,'therapyNameSnapshot',paged.therapy_name_snapshot,
    'sessionDate',paged.session_date,'grossAmountCents',paged.gross_amount_cents,
    'tesCommissionCents',paged.tes_commission_cents,'refundedAmountCents',paged.refunded_amount_cents,
    'therapistNetAmountCents',case when paged.receipt_status='paid' then coalesce(paged.received_amount_cents,0) else greatest(0,paged.gross_amount_cents-paged.tes_commission_cents-paged.refunded_amount_cents) end,
    'financialStatus',paged.financial_status,'receiptStatus',paged.receipt_status,
    'paymentMethodType',paged.payment_method_type,'paymentOrigin',paged.payment_origin,
    'receiptUrl',paged.receipt_url,'disputeStatus',paged.dispute_status,
    'receivedAt',paged.received_at,'createdAt',paged.created_at
  ) order by coalesce(paged.received_at,paged.session_date,paged.created_at) desc,paged.session_payment_id desc) filter(where paged.session_payment_id is not null),'[]'::jsonb)
  into v_total_count,v_items from counted left join paged on true group by counted.count;

  select coalesce(jsonb_agg(jsonb_build_object('therapyId',x.id,'name',x.name) order by x.name),'[]'::jsonb)
  into v_therapy_options from (
    select distinct therapy.id,therapy.name from public.session_payments payment
    join public.therapist_services service on service.id=payment.service_id
    join public.therapies therapy on therapy.id=service.therapy_id
    where payment.therapist_profile_id=v_therapist.id
  ) x;

  with scoped as (
    select payment.*,booking.starts_at session_date,therapy.id therapy_id,therapy.name therapy_name,
      patient.display_name patient_name,booking.service_title_snapshot,
      public.private_therapist_receipt_status_v2(payment.id) receipt_status,
      bank.received_at,
      case when public.private_therapist_receipt_status_v2(payment.id)='paid'
        then coalesce(bank.received_amount_cents,0)
        else greatest(0,payment.gross_amount_cents-payment.platform_gross_commission_cents-public.private_therapist_finance_refunded_cents_v1(payment.id)) end net_cents
    from public.session_payments payment join public.bookings booking on booking.id=payment.booking_id
    left join public.patient_profiles patient on patient.id=payment.patient_profile_id
    left join public.therapist_services service on service.id=payment.service_id
    left join public.therapies therapy on therapy.id=service.therapy_id
    left join lateral (
      select max(coalesce(payout.paid_at,payout.updated_at)) received_at,
        sum(transfer.amount_cents)::integer received_amount_cents
      from public.stripe_transfers transfer
      join public.stripe_payout_transfer_allocations allocation on allocation.stripe_transfer_id=transfer.id
      join public.stripe_payouts payout on payout.id=allocation.stripe_payout_id
      where transfer.session_payment_id=payment.id and transfer.status='transferred'
        and payout.status='paid' and payout.provider_reconciliation_status='completed'
        and payout.allocation_status='completed'
        and allocation.amount_cents=transfer.amount_cents
    ) bank on true
    where payment.therapist_profile_id=v_therapist.id
      and (p_therapy_id is null or therapy.id=p_therapy_id)
      and (v_search is null or patient.display_name ilike '%'||v_search||'%' or therapy.name ilike '%'||v_search||'%' or booking.service_title_snapshot ilike '%'||v_search||'%')
  ), period_scoped as (
    select * from scoped where (
      (receipt_status='paid' and received_at>=v_period.starts_at and received_at<v_period.ends_at)
      or (receipt_status<>'paid' and session_date>=v_period.starts_at and session_date<v_period.ends_at)
    )
      and (p_status is null or receipt_status=p_status)
  ), paid_scoped as (
    select distinct transfer.session_payment_id,transfer.amount_cents,payout.paid_at
    from public.stripe_transfers transfer
    join public.stripe_payout_transfer_allocations allocation on allocation.stripe_transfer_id=transfer.id
    join public.stripe_payouts payout on payout.id=allocation.stripe_payout_id
    join scoped on scoped.id=transfer.session_payment_id
    where payout.status='paid' and payout.provider_reconciliation_status='completed'
      and payout.allocation_status='completed'
      and allocation.amount_cents=transfer.amount_cents
      and coalesce(payout.paid_at,payout.updated_at)>=v_period.starts_at
      and coalesce(payout.paid_at,payout.updated_at)<v_period.ends_at
      and (p_status is null or p_status='paid')
  )
  select jsonb_build_object(
    'receivedCents',(select coalesce(sum(amount_cents),0)::integer from paid_scoped),
    'processingCents',(select coalesce(sum(net_cents),0)::integer from period_scoped where receipt_status in ('receivable','waiting_confirmation','waiting_safety_period','waiting_settlement','eligible','payout_processing','bank_pending')),
    'refundedCents',(select coalesce(sum(public.private_therapist_finance_refunded_cents_v1(id)),0)::integer from period_scoped),
    'disputedCents',(select coalesce(sum(gross_amount_cents),0)::integer from period_scoped where receipt_status='disputed')
  ) into v_summary;

  with months as (
    select month_start,month_start+interval '1 month' month_end
    from generate_series(date_trunc('month',v_period.starts_at),date_trunc('month',v_period.ends_at-interval '1 second'),interval '1 month') month_start
  ), scoped as (
    select payment.id,booking.starts_at session_date,therapy.id therapy_id,therapy.name therapy_name,patient.display_name patient_name,booking.service_title_snapshot,
      public.private_therapist_receipt_status_v2(payment.id) receipt_status,
      greatest(0,payment.gross_amount_cents-payment.platform_gross_commission_cents-public.private_therapist_finance_refunded_cents_v1(payment.id)) net_cents
    from public.session_payments payment join public.bookings booking on booking.id=payment.booking_id
    left join public.patient_profiles patient on patient.id=payment.patient_profile_id left join public.therapist_services service on service.id=payment.service_id left join public.therapies therapy on therapy.id=service.therapy_id
    where payment.therapist_profile_id=v_therapist.id and (p_therapy_id is null or therapy.id=p_therapy_id)
      and (v_search is null or patient.display_name ilike '%'||v_search||'%' or therapy.name ilike '%'||v_search||'%' or booking.service_title_snapshot ilike '%'||v_search||'%')
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'month',to_char(months.month_start at time zone v_period.timezone,'YYYY-MM'),
    'processingCents',(select coalesce(sum(s.net_cents),0)::integer from scoped s where s.session_date>=months.month_start and s.session_date<months.month_end and s.receipt_status in ('receivable','waiting_confirmation','waiting_safety_period','waiting_settlement','eligible','payout_processing','bank_pending') and (p_status is null or s.receipt_status=p_status)),
    'receivedCents',(select coalesce(sum(transfer.amount_cents),0)::integer from public.stripe_transfers transfer join public.stripe_payout_transfer_allocations allocation on allocation.stripe_transfer_id=transfer.id join public.stripe_payouts payout on payout.id=allocation.stripe_payout_id join scoped s on s.id=transfer.session_payment_id where payout.status='paid' and payout.provider_reconciliation_status='completed' and payout.allocation_status='completed' and allocation.amount_cents=transfer.amount_cents and coalesce(payout.paid_at,payout.updated_at)>=months.month_start and coalesce(payout.paid_at,payout.updated_at)<months.month_end and (p_status is null or p_status='paid'))
  ) order by months.month_start),'[]'::jsonb) into v_trend from months;

  with distribution_rows as (
    select public.private_therapist_receipt_status_v2(payment.id) status,
      booking.starts_at session_date,
      bank.received_at,
      case when public.private_therapist_receipt_status_v2(payment.id)='paid'
        then coalesce(bank.received_amount_cents,0)
        else greatest(0,payment.gross_amount_cents-payment.platform_gross_commission_cents-public.private_therapist_finance_refunded_cents_v1(payment.id)) end net_cents
    from public.session_payments payment join public.bookings booking on booking.id=payment.booking_id
    left join public.patient_profiles patient on patient.id=payment.patient_profile_id left join public.therapist_services service on service.id=payment.service_id left join public.therapies therapy on therapy.id=service.therapy_id
    left join lateral (
      select max(coalesce(payout.paid_at,payout.updated_at)) received_at,
        sum(transfer.amount_cents)::integer received_amount_cents
      from public.stripe_transfers transfer
      join public.stripe_payout_transfer_allocations allocation on allocation.stripe_transfer_id=transfer.id
      join public.stripe_payouts payout on payout.id=allocation.stripe_payout_id
      where transfer.session_payment_id=payment.id and transfer.status='transferred'
        and payout.status='paid' and payout.provider_reconciliation_status='completed'
        and payout.allocation_status='completed'
        and allocation.amount_cents=transfer.amount_cents
    ) bank on true
    where payment.therapist_profile_id=v_therapist.id
      and (p_therapy_id is null or therapy.id=p_therapy_id) and (v_search is null or patient.display_name ilike '%'||v_search||'%' or therapy.name ilike '%'||v_search||'%' or booking.service_title_snapshot ilike '%'||v_search||'%')
      and (p_status is null or public.private_therapist_receipt_status_v2(payment.id)=p_status)
  ), distribution as (
    select status,sum(net_cents)::integer amount_cents,count(*)::integer item_count
    from distribution_rows
    where (status='paid' and received_at>=v_period.starts_at and received_at<v_period.ends_at)
       or (status<>'paid' and session_date>=v_period.starts_at and session_date<v_period.ends_at)
    group by 1
  ) select coalesce(jsonb_agg(jsonb_build_object('status',status,'amountCents',amount_cents,'itemCount',item_count) order by status),'[]'::jsonb) into v_distribution from distribution;

  return jsonb_build_object('contractVersion',2,'therapistProfileId',v_therapist.id,
    'items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_page_size,'totalCount',v_total_count,'totalPages',case when v_total_count=0 then 0 else ceil(v_total_count::numeric/v_page_size)::integer end,'hasNextPage',v_offset+v_page_size<v_total_count),
    'filters',jsonb_build_object('status',p_status,'therapyId',p_therapy_id,'search',v_search,'periodStart',v_period.period_start,'periodEnd',v_period.period_end,'timezone',v_period.timezone),
    'therapyOptions',v_therapy_options,'summary',v_summary,'monthlyTrend',v_trend,'statusDistribution',v_distribution,'generatedAt',now());
end;
$$;


ALTER FUNCTION "public"."private_therapist_receipts_v2_legacy_timezone"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_therapy_id" "uuid", "p_search" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."private_therapist_receipts_v2_legacy_timezone"("p_period_start" "date", "p_period_end" "date", "p_status" "text", "p_therapy_id" "uuid", "p_search" "text", "p_page" integer, "p_page_size" integer, "p_timezone" "text") IS 'Therapist receipt lifecycle with full-filter summaries, monthly trend and bank-paid authority independent from pagination.';



CREATE OR REPLACE FUNCTION "public"."protect_booking_session_reference_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.session_reference is distinct from old.session_reference then
    raise exception 'session_reference_immutable' using errcode = '22000';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."protect_booking_session_reference_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_therapist_slug_redirect_rows_v1"() RETURNS TABLE("old_slug" "text", "current_slug" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select h.old_slug, h.current_slug
  from public.therapist_profile_slug_history h
  where public.is_therapist_publication_eligible_v1(h.therapist_profile_id)
$$;


ALTER FUNCTION "public"."public_therapist_slug_redirect_rows_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_therapist_profile_draft_content_base_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_draft public.therapist_profile_content_versions%rowtype;
  v_fields jsonb;
  v_previous_status text;
  v_payload_hash text := encode(extensions.digest(p_expected_version::text, 'sha256'), 'hex');
  v_replay jsonb;
  v_response jsonb;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);
  v_replay := public.therapist_profile_request_replay_m1(v_profile.id, p_request_id, 'publish', v_payload_hash);
  if v_replay is not null then
    return v_replay;
  end if;

  if p_expected_version <> v_profile.profile_version then
    raise exception 'VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  select *
    into v_draft
  from public.therapist_profile_content_versions
  where therapist_profile_id = v_profile.id
    and status = 'draft'
  limit 1;

  if v_draft.id is null then
    raise exception 'VALIDATION_ERROR: draft' using errcode = 'P0001';
  end if;

  v_fields := public.therapist_profile_content_json_m1(v_draft.id) -> 'fields';
  if coalesce(v_fields ->> 'publicName', '') = ''
    or coalesce(v_fields ->> 'shortIntro', v_fields ->> 'headline', '') = ''
    or coalesce(v_fields ->> 'essenceBody', v_fields ->> 'bio', '') = ''
  then
    raise exception 'VALIDATION_ERROR: completeness' using errcode = 'P0001';
  end if;

  v_previous_status := v_profile.public_status;

  update public.therapist_profile_content_versions
  set
    status = 'published',
    published_at = now(),
    updated_at = now()
  where id = v_draft.id;

  update public.therapist_profiles
  set
    public_name = v_fields ->> 'publicName',
    headline = nullif(v_fields ->> 'headline', ''),
    bio = nullif(v_fields ->> 'bio', ''),
    photo_url = nullif(v_fields ->> 'photoUrl', ''),
    city = nullif(v_fields ->> 'city', ''),
    state = nullif(v_fields ->> 'state', ''),
    is_public = true,
    public_status = 'published',
    last_published_at = now(),
    unpublished_at = null,
    profile_version = profile_version + 1,
    updated_at = now()
  where id = v_profile.id
  returning * into v_profile;

  insert into public.therapist_profile_events (
    therapist_profile_id,
    actor_user_id,
    event_type,
    request_id,
    previous_public_status,
    next_public_status,
    previous_version,
    next_version
  )
  values (
    v_profile.id,
    p_actor_user_id,
    'profile_published',
    p_request_id,
    coalesce(v_previous_status, 'draft'),
    'published',
    p_expected_version,
    v_profile.profile_version
  );

  v_response := jsonb_build_object(
    'contractVersion', 1,
    'idempotentReplay', false,
    'editor', public.get_private_therapist_profile_editor_v1(p_actor_user_id)
  );

  return public.therapist_profile_store_request_m1(
    v_profile.id,
    p_request_id,
    'publish',
    v_payload_hash,
    v_response
  );
end;
$$;


ALTER FUNCTION "public"."publish_therapist_profile_draft_content_base_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_therapist_profile_draft_content_base_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) IS 'SERVICE_ROLE_ONLY therapist profile publish command. Browser calls must go through therapist-profile-command.';



CREATE OR REPLACE FUNCTION "public"."publish_therapist_profile_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_theme text;
  v_response jsonb;
  v_requires_initial_review boolean;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);
  if v_profile.status = 'suspended'::public.therapist_status then
    raise exception 'PROFILE_SUSPENDED' using errcode = 'P0001';
  end if;

  select public_profile_theme into v_theme
  from public.therapist_profile_content_versions
  where therapist_profile_id = v_profile.id and status = 'draft'
  order by updated_at desc limit 1;

  if v_profile.plan = 'free' and v_theme in (
    'ancestral',
    'aurora',
    'botanico',
    'celestial',
    'cristalino',
    'energia',
    'essencial_editorial',
    'frequencia',
    'geometria',
    'lunar',
    'oraculo',
    'profundo',
    'sagrado',
    'sereno_horizonte',
    'vinculos'
  ) then
    v_theme := 'serene';
    update public.therapist_profile_content_versions
    set public_profile_theme = v_theme,
        updated_at = now()
    where therapist_profile_id = v_profile.id and status = 'draft';
  end if;

  -- The profile status is the authoritative administrative decision. A
  -- suspended profile never qualifies for this bypass because it is not
  -- approved. Approved professionals keep their public/bookable switches when
  -- publishing subsequent editorial versions.
  v_requires_initial_review := v_profile.status is distinct from 'approved'::public.therapist_status;

  v_response := public.publish_therapist_profile_draft_content_base_v1(
    p_actor_user_id, p_request_id, p_expected_version
  );

  if v_requires_initial_review
    and coalesce(v_response ->> 'idempotentReplay', 'false') <> 'true'
  then
    perform public.queue_therapist_profile_review_v1(v_profile.id);
  end if;

  if v_theme is null then
    select public_profile_theme into v_theme
    from public.therapist_profile_content_versions
    where therapist_profile_id = v_profile.id and status = 'published'
    order by published_at desc nulls last, created_at desc limit 1;
  end if;

  update public.therapist_profiles
  set public_profile_theme = coalesce(v_theme, 'serene')
  where id = v_profile.id;

  v_response := jsonb_set(
    v_response,
    '{editor}',
    public.get_private_therapist_profile_editor_v1(p_actor_user_id),
    true
  );
  update public.therapist_profile_mutation_requests
  set response = v_response
  where therapist_profile_id = v_profile.id and request_id = p_request_id and action = 'publish';
  return v_response;
end;
$$;


