COMMENT ON FUNCTION "public"."purge_temporary_data_v1"("p_now" timestamp with time zone) IS 'Expires booking holds/reschedule requests and purges transient auth/email/Zoom rate-limit data. Intended for a scheduled service-role job.';



CREATE OR REPLACE FUNCTION "public"."queue_therapist_profile_review_v1"("p_therapist_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_verification public.therapist_verifications%rowtype;
begin
  select * into v_profile
  from public.therapist_profiles
  where id = p_therapist_profile_id
  for update;

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0001';
  end if;

  if v_profile.status = 'suspended'::public.therapist_status then
    return;
  end if;

  select * into v_verification
  from public.therapist_verifications
  where therapist_profile_id = v_profile.id
  order by submitted_at desc nulls last, created_at desc, id desc
  limit 1
  for update;

  if v_verification.id is null
    or v_verification.status = 'approved'::public.therapist_status
  then
    insert into public.therapist_verifications (
      therapist_profile_id,
      status,
      submitted_at
    ) values (
      v_profile.id,
      'submitted'::public.therapist_status,
      now()
    );
  else
    update public.therapist_verifications
    set status = 'submitted'::public.therapist_status,
        changes_requested = null,
        rejection_reason = null,
        reviewed_by = null,
        reviewed_at = null,
        submitted_at = now(),
        updated_at = now()
    where id = v_verification.id;
  end if;

  -- A submitted profile must not remain visible or bookable while the new
  -- content is being reviewed.  The content version is retained for the
  -- admin-only review read model and is never exposed by public views.
  update public.therapist_profiles
  set status = 'submitted'::public.therapist_status,
      public_status = 'unpublished',
      is_public = false,
      is_accepting_bookings = false,
      updated_at = now()
  where id = v_profile.id;
end;
$$;


ALTER FUNCTION "public"."queue_therapist_profile_review_v1"("p_therapist_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."queue_therapist_profile_review_v1"("p_therapist_profile_id" "uuid") IS 'Queues every newly published therapist profile version for administrative review and removes public visibility until approval.';



CREATE OR REPLACE FUNCTION "public"."rearm_definitive_payout_transfer_v1"("p_transfer_id" "uuid", "p_expected_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfer public.stripe_transfers%rowtype;
  v_item public.payout_batch_items%rowtype;
begin
  if p_transfer_id is null or p_expected_batch_id is null then
    raise exception 'PAYOUT_TRANSFER_REARM_INVALID';
  end if;

  select * into v_transfer from public.stripe_transfers
  where id = p_transfer_id for update;
  if not found then raise exception 'PAYOUT_TRANSFER_NOT_FOUND'; end if;

  select * into v_item from public.payout_batch_items
  where id = v_transfer.payout_batch_item_id for update;

  if v_item.payout_batch_id <> p_expected_batch_id then
    raise exception 'PAYOUT_TRANSFER_BATCH_MISMATCH';
  end if;
  if v_transfer.status <> 'failed'
    or v_transfer.attempt_count < 4
    or v_transfer.failure_code not in ('balance_insufficient', 'insufficient_funds')
    or v_transfer.stripe_transfer_id is not null
    or exists (
      select 1 from public.financial_ledger_entries ledger
      where ledger.stripe_transfer_id = v_transfer.id
        and ledger.entry_type = 'transfer'
    )
  then
    raise exception 'PAYOUT_TRANSFER_REARM_NOT_SAFE';
  end if;

  update public.stripe_transfers
  set status = 'failed', attempt_count = 0,
      retry_cycle = retry_cycle + 1, next_retry_at = now(),
      lease_owner = null, lease_expires_at = null, updated_at = now()
  where id = v_transfer.id;

  update public.payout_batch_items
  set status = 'failed', updated_at = now()
  where id = v_item.id;

  update public.session_payments
  set transfer_status = 'transfer_pending', updated_at = now()
  where id = v_transfer.session_payment_id;

  return jsonb_build_object('rearmed', true, 'transferId', v_transfer.id,
    'payoutBatchId', v_item.payout_batch_id);
end;
$$;


ALTER FUNCTION "public"."rearm_definitive_payout_transfer_v1"("p_transfer_id" "uuid", "p_expected_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rearm_definitive_payout_transfer_v1"("p_transfer_id" "uuid", "p_expected_batch_id" "uuid") IS 'Explicitly rearms a terminal balance rejection only when no provider Transfer or ledger entry can exist.';



CREATE OR REPLACE FUNCTION "public"."recheck_connect_blocked_payments_v1"("p_therapist_profile_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_count integer := 0; v_payment_id uuid;
begin
  if p_therapist_profile_id is null then raise exception 'THERAPIST_REQUIRED' using errcode = '22023'; end if;
  if not exists (
    select 1 from public.therapist_connect_accounts account
    where account.therapist_profile_id = p_therapist_profile_id and account.is_current = true
      and account.stripe_transfers_status = 'active' and account.payouts_enabled = true
      and account.payout_status = 'enabled' and account.payout_schedule_interval = 'daily'
      and account.operational_status = 'ready'
  ) then return 0; end if;
  for v_payment_id in
    select id from public.session_payments
    where therapist_profile_id = p_therapist_profile_id and transfer_status = 'blocked'
      and transfer_blocked_reason = 'connect_not_ready'
    order by id
    for update
  loop
    perform public.refresh_session_transfer_eligibility(v_payment_id, p_now);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."recheck_connect_blocked_payments_v1"("p_therapist_profile_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_automatic_stripe_payout_v1"("p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_balance_transactions" "jsonb", "p_observed_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_payout public.stripe_payouts%rowtype;
  v_transaction jsonb;
  v_transfer public.stripe_transfers%rowtype;
  v_item public.payout_batch_items%rowtype;
  v_transaction_id text;
  v_source_id text;
  v_currency text;
  v_amount integer;
  v_net integer;
  v_available_on timestamptz;
  v_allocated_count integer := 0;
  v_unmatched_count integer := 0;
  v_total_net integer := 0;
  v_allocation_status text;
begin
  if nullif(trim(p_stripe_payout_id), '') is null
    or nullif(trim(p_stripe_account_id), '') is null
    or p_observed_at is null
    or jsonb_typeof(p_balance_transactions) <> 'array'
    or jsonb_array_length(p_balance_transactions) > 1000
  then
    raise exception 'AUTOMATIC_STRIPE_PAYOUT_RECONCILIATION_INVALID';
  end if;

  select payout.* into v_payout
  from public.stripe_payouts payout
  join public.therapist_connect_accounts account
    on account.id = payout.connect_account_id
  where payout.stripe_payout_id = p_stripe_payout_id
    and account.stripe_account_id = p_stripe_account_id
    and payout.automatic = true
  for update of payout;
  if not found then
    return jsonb_build_object('reconciled', false, 'reason', 'payout_not_found');
  end if;

  -- The provider list is a complete authoritative snapshot once
  -- reconciliation_status is completed. Rebuild atomically so stale local
  -- associations cannot survive a corrected provider response.
  delete from public.stripe_payout_transfer_allocations
  where stripe_payout_id = v_payout.id;

  for v_transaction in
    select value from jsonb_array_elements(p_balance_transactions)
  loop
    v_transaction_id := nullif(trim(v_transaction ->> 'id'), '');
    v_source_id := nullif(trim(v_transaction ->> 'source'), '');
    v_currency := lower(coalesce(v_transaction ->> 'currency', ''));
    begin
      v_amount := (v_transaction ->> 'amount')::integer;
      v_net := coalesce((v_transaction ->> 'net')::integer, v_amount);
    exception when others then
      v_amount := null;
      v_net := null;
    end;
    v_total_net := v_total_net + coalesce(v_net, 0);
    v_available_on := case
      when coalesce(v_transaction ->> 'available_on', '') ~ '^[0-9]+$'
        then to_timestamp((v_transaction ->> 'available_on')::double precision)
      else null
    end;

    v_transfer := null;
    if v_transaction_id is not null and v_source_id is not null
      and v_currency = 'brl' and coalesce(v_amount, 0) > 0
    then
      select transfer.* into v_transfer
      from public.stripe_transfers transfer
      join public.therapist_connect_accounts account
        on account.id = transfer.connect_account_id
      where account.stripe_account_id = p_stripe_account_id
        and transfer.status = 'transferred'
        and transfer.amount_cents = v_amount
        and (
          transfer.stripe_destination_payment_id = v_source_id
          or transfer.stripe_connected_balance_transaction_id = v_transaction_id
        )
      order by transfer.created_at
      limit 1
      for update of transfer;
    end if;

    if v_transfer.id is null then
      v_unmatched_count := v_unmatched_count + 1;
      continue;
    end if;

    select * into v_item
    from public.payout_batch_items
    where id = v_transfer.payout_batch_item_id;

    update public.stripe_transfers
    set stripe_connected_balance_transaction_id = coalesce(
          stripe_connected_balance_transaction_id, v_transaction_id
        ),
        connected_balance_available_on = coalesce(
          connected_balance_available_on, v_available_on
        ),
        updated_at = now()
    where id = v_transfer.id;

    insert into public.stripe_payout_transfer_allocations (
      stripe_payout_id, stripe_transfer_id, payout_batch_id,
      payout_batch_therapist_id, connected_balance_transaction_id,
      source_id, amount_cents, currency, reconciled_at
    ) values (
      v_payout.id, v_transfer.id, v_item.payout_batch_id,
      v_item.payout_batch_therapist_id, v_transaction_id,
      v_source_id, v_transfer.amount_cents, 'BRL', p_observed_at
    )
    on conflict (stripe_payout_id, stripe_transfer_id) do update
    set connected_balance_transaction_id = excluded.connected_balance_transaction_id,
        source_id = excluded.source_id,
        amount_cents = excluded.amount_cents,
        reconciled_at = excluded.reconciled_at,
        updated_at = now();
    v_allocated_count := v_allocated_count + 1;
  end loop;

  v_allocation_status := case
    when v_unmatched_count = 0
      and v_total_net = v_payout.amount_cents
      and v_allocated_count > 0 then 'completed'
    when v_allocated_count > 0 then 'partial'
    else 'pending'
  end;

  update public.stripe_payouts
  set provider_reconciliation_status = 'completed',
      allocation_status = v_allocation_status,
      included_transaction_net_cents = v_total_net,
      unmatched_transaction_count = v_unmatched_count,
      reconciled_at = p_observed_at,
      updated_at = now()
  where id = v_payout.id
  returning * into v_payout;

  if v_allocation_status <> 'completed' then
    perform public.record_payout_operational_incident_v1(
      'automatic-payout:' || v_payout.id::text || ':allocation',
      'automatic_payout_reconciliation_required',
      'critical', 'automatic_payout_allocation_incomplete',
      'O Payout automatico possui movimentacoes sem associacao financeira local.',
      null, null, null, null, v_payout.id, v_payout.therapist_profile_id,
      jsonb_build_object(
        'allocatedCount', v_allocated_count,
        'unmatchedCount', v_unmatched_count,
        'amountMatches', v_total_net = v_payout.amount_cents
      )
    );
  else
    update public.payout_operational_incidents
    set status = 'resolved',
        resolved_at = coalesce(resolved_at, p_observed_at),
        updated_at = now()
    where incident_key = 'automatic-payout:' || v_payout.id::text || ':allocation'
      and status = 'open';
  end if;

  perform public.refresh_automatic_payout_batch_states_v1();

  return jsonb_build_object(
    'reconciled', v_allocation_status = 'completed',
    'allocationStatus', v_allocation_status,
    'allocatedCount', v_allocated_count,
    'unmatchedCount', v_unmatched_count,
    'amountMatches', v_total_net = v_payout.amount_cents
  );
end;
$_$;


ALTER FUNCTION "public"."reconcile_automatic_stripe_payout_v1"("p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_balance_transactions" "jsonb", "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_full_session_refund_debt_v10"("p_session_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_decision public.session_refund_decisions_v10%rowtype;
  v_debt public.therapist_financial_debts%rowtype;
  v_transfer public.stripe_transfers%rowtype;
  v_refunded integer;
  v_reversed integer := 0;
  v_initial_reversed integer;
  v_prior_recovery integer;
  v_due integer;
  v_delta integer;
  v_reduce integer;
  v_ledger_id uuid;
begin
  select * into v_payment from public.session_payments
  where id = p_session_payment_id for update;
  select * into v_decision from public.session_refund_decisions_v10
  where session_payment_id = p_session_payment_id for update;
  if not found then return jsonb_build_object('status', 'no_decision'); end if;
  select coalesce(sum(amount_cents), 0) into v_refunded
  from public.session_refunds
  where session_payment_id = p_session_payment_id and status = 'succeeded';
  if v_refunded <> v_decision.amount_cents then
    return jsonb_build_object('status', 'awaiting_full_refund');
  end if;

  if v_decision.stripe_transfer_id is not null then
    select * into v_transfer from public.stripe_transfers
    where stripe_transfer_id = v_decision.stripe_transfer_id;
    if not found or v_transfer.session_payment_id <> p_session_payment_id then
      raise exception 'FULL_REFUND_TRANSFER_MISMATCH' using errcode = '23514';
    end if;
    select coalesce(sum(amount_cents), 0) into v_reversed
    from public.stripe_transfer_reversals
    where stripe_transfer_id = v_transfer.id and status = 'succeeded';
    if v_reversed < v_transfer.amount_cents
      and v_decision.reversal_state not in ('unavailable','complete') then
      return jsonb_build_object('status', 'recovery_requires_review');
    end if;
  end if;

  v_due := greatest(0, v_decision.therapist_exposure_cents - v_reversed);
  select * into v_debt from public.therapist_financial_debts
  where session_payment_id = p_session_payment_id and origin = 'refund' for update;
  if v_debt.id is null and v_due > 0 then
    insert into public.therapist_financial_debts (
      therapist_profile_id, session_payment_id, stripe_transfer_id,
      origin, reason_code, principal_amount_cents, open_amount_cents,
      metadata
    ) values (
      v_payment.therapist_profile_id, p_session_payment_id, v_transfer.id,
      'refund', 'full_session_refund', v_due, v_due,
      jsonb_build_object('decisionId', v_decision.id, 'initialReversedCents', v_reversed)
    ) returning * into v_debt;
    insert into public.financial_ledger_entries (
      entry_type, direction, currency, amount_cents, therapist_profile_id,
      booking_id, session_payment_id, financial_policy_version_id,
      therapist_financial_debt_id, source_table, source_id, occurred_at
    ) values (
      'therapist_debt', 'debit', 'BRL', v_due, v_payment.therapist_profile_id,
      v_payment.booking_id, p_session_payment_id, v_payment.policy_version_id,
      v_debt.id, 'therapist_financial_debts', v_debt.id, now()
    ) returning id into v_ledger_id;
    insert into public.therapist_financial_debt_events (
      therapist_financial_debt_id, event_type, direction, amount_cents,
      idempotency_key, financial_ledger_entry_id
    ) values (v_debt.id, 'created', 'increase', v_due,
      'tes:v10:refund-debt:' || v_debt.id::text, v_ledger_id);
  elsif v_debt.id is not null then
    v_initial_reversed := coalesce((v_debt.metadata->>'initialReversedCents')::integer, 0);
    select coalesce(sum(amount_cents), 0) into v_prior_recovery
    from public.therapist_financial_debt_events
    where therapist_financial_debt_id = v_debt.id and event_type = 'reversal_recovered';
    v_delta := greatest(0, v_reversed - v_initial_reversed - v_prior_recovery);
    v_reduce := least(v_delta, v_debt.open_amount_cents);
    if v_reduce > 0 then
      update public.therapist_financial_debts
      set open_amount_cents = open_amount_cents - v_reduce,
        recovered_amount_cents = recovered_amount_cents + v_reduce,
        status = case when open_amount_cents = v_reduce then 'settled' else 'open' end,
        closed_at = case when open_amount_cents = v_reduce then now() else null end,
        updated_at = now() where id = v_debt.id;
      insert into public.therapist_financial_debt_events (
        therapist_financial_debt_id, event_type, direction, amount_cents, idempotency_key
      ) values (v_debt.id, 'reversal_recovered', 'decrease', v_reduce,
        'tes:v10:refund-recovery:' || v_debt.id::text || ':' || v_reversed::text);
    end if;
    if v_delta > v_reduce then
      insert into public.session_refund_incidents_v10 (
        session_refund_decision_id, code, expected_amount_cents, observed_amount_cents
      ) values (v_decision.id, 'recovery_exceeds_open_debt', v_debt.open_amount_cents, v_delta)
      on conflict (session_refund_decision_id, code) do update
      set observed_amount_cents = excluded.observed_amount_cents;
    end if;
  end if;
  update public.session_refund_decisions_v10
  set refund_state = 'complete', recovery_reconciled_at = now(), updated_at = now()
  where id = v_decision.id and refund_state <> 'complete';
  return jsonb_build_object('status', 'reconciled', 'debtCents', v_due,
    'reversedCents', v_reversed);
end;
$$;


ALTER FUNCTION "public"."reconcile_full_session_refund_debt_v10"("p_session_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_full_session_refund_debt_v10_v2"("p_session_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_decision public.session_refund_decisions_v10%rowtype;
  v_transfer public.stripe_transfers%rowtype;
  v_reversed integer;
begin
  v_result := public.reconcile_full_session_refund_debt_v10(p_session_payment_id);
  select * into v_decision from public.session_refund_decisions_v10
  where session_payment_id = p_session_payment_id for update;
  if not found then return v_result; end if;
  if exists (select 1 from public.session_refund_incidents_v10
    where session_refund_decision_id = v_decision.id and resolved_at is null) then
    return jsonb_set(v_result, '{status}', '"recovery_requires_review"'::jsonb);
  end if;
  if v_decision.stripe_transfer_id is not null then
    select * into v_transfer from public.stripe_transfers
    where stripe_transfer_id = v_decision.stripe_transfer_id;
    if found then
      select coalesce(sum(amount_cents), 0) into v_reversed
      from public.stripe_transfer_reversals
      where stripe_transfer_id = v_transfer.id and status = 'succeeded';
      if v_reversed = v_transfer.amount_cents
        and v_decision.reversal_state = 'unavailable' then
        update public.session_refund_decisions_v10
        set reversal_state = 'complete', updated_at = now()
        where id = v_decision.id;
      end if;
    end if;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."reconcile_full_session_refund_debt_v10_v2"("p_session_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_legacy_retained_cancellations_v1"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment_id uuid;
  v_reconciled integer := 0;
begin
  for v_payment_id in
    select payment.id
    from public.session_payments payment
    join public.session_cancellation_decisions decision
      on decision.session_payment_id = payment.id
     and decision.booking_id = payment.booking_id
    where payment.financial_status = 'paid'
      and payment.refund_pending = true
      and payment.service_status = 'scheduled'
      and payment.transfer_status = 'blocked'
      and payment.transfer_blocked_reason = 'manual_refund_review'
      and payment.admin_blocked_at is null
      and payment.internal_contested_at is null
      and payment.disputed_at is null
      and decision.processed_at is not null
      and decision.requires_manual_review = false
      and decision.refund_amount_cents = 0
      and decision.retained_amount_cents = payment.gross_amount_cents
      and decision.therapist_retained_cents = payment.therapist_amount_cents
      and decision.platform_retained_cents = payment.platform_gross_commission_cents
    for update of payment
  loop
    update public.session_payments payment
    set canceled_at = coalesce(
          payment.canceled_at,
          (
            select coalesce(decision.processed_at, decision.created_at, p_now)
            from public.session_cancellation_decisions decision
            where decision.session_payment_id = payment.id
              and decision.processed_at is not null
              and decision.requires_manual_review = false
              and decision.refund_amount_cents = 0
            order by decision.created_at desc
            limit 1
          )
        ),
        eligible_at = null,
        refund_pending = false,
        service_confirmation_source = null,
        service_confirmed_at = coalesce(
          payment.service_confirmed_at,
          (
            select coalesce(decision.processed_at, decision.created_at, p_now)
            from public.session_cancellation_decisions decision
            where decision.session_payment_id = payment.id
              and decision.processed_at is not null
              and decision.requires_manual_review = false
              and decision.refund_amount_cents = 0
            order by decision.created_at desc
            limit 1
          )
        ),
        service_status = 'canceled',
        transfer_blocked_reason = 'retained_cancellation_pending_eligibility',
        updated_at = p_now
    where payment.id = v_payment_id;

    perform public.refresh_session_transfer_eligibility(v_payment_id, p_now);
    v_reconciled := v_reconciled + 1;
  end loop;

  return v_reconciled;
end;
$$;


ALTER FUNCTION "public"."reconcile_legacy_retained_cancellations_v1"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_payout_transfer_v1"("p_transfer_id" "uuid", "p_stripe_transfer_id" "text", "p_reversed" boolean DEFAULT false, "p_observed_at" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfer public.stripe_transfers%rowtype;
  v_item public.payout_batch_items%rowtype;
begin
  select * into v_transfer from public.stripe_transfers
  where id = p_transfer_id for update;
  if not found then raise exception 'PAYOUT_TRANSFER_NOT_FOUND'; end if;
  if nullif(trim(p_stripe_transfer_id), '') is null then
    raise exception 'PAYOUT_TRANSFER_PROVIDER_ID_INVALID';
  end if;
  if v_transfer.stripe_transfer_id is not null
    and v_transfer.stripe_transfer_id <> p_stripe_transfer_id
  then raise exception 'PAYOUT_TRANSFER_PROVIDER_ID_MISMATCH'; end if;

  select * into v_item from public.payout_batch_items
  where id = v_transfer.payout_batch_item_id for update;

  if p_reversed then
    update public.stripe_transfers
    set stripe_transfer_id = p_stripe_transfer_id, status = 'reversed',
        lease_owner = null, lease_expires_at = null, next_retry_at = null,
        updated_at = now()
    where id = v_transfer.id;
    update public.payout_batch_items
    set status = 'failed', failure_code = 'stripe_transfer_reversed',
        failure_message = 'Transfer revertido pelo provedor.', updated_at = now()
    where id = v_item.id;
    update public.session_payments
    set transfer_status = 'failed', transfer_blocked_reason = 'stripe_transfer_reversed', updated_at = now()
    where id = v_transfer.session_payment_id;
    perform public.record_payout_operational_incident_v1(
      'transfer:' || v_transfer.id::text || ':reversed', 'transfer_reversed',
      'critical', 'stripe_transfer_reversed', 'Transfer revertido pelo provedor.',
      null, v_item.payout_batch_id, v_item.id, v_transfer.id, null,
      v_transfer.therapist_profile_id
    );
    return 'reversed';
  end if;

  update public.stripe_transfers
  set stripe_transfer_id = p_stripe_transfer_id, status = 'transferred',
      transferred_at = coalesce(transferred_at, p_observed_at),
      lease_owner = null, lease_expires_at = null, next_retry_at = null,
      failure_code = null, failure_message = null, updated_at = now()
  where id = v_transfer.id;
  update public.payout_batch_items
  set status = 'transferred', failure_code = null, failure_message = null, updated_at = now()
  where id = v_item.id;
  update public.session_payments
  set transfer_status = 'transferred', transfer_blocked_reason = null, updated_at = now()
  where id = v_transfer.session_payment_id;
  insert into public.financial_ledger_entries (
    entry_type, direction, currency, amount_cents, therapist_profile_id,
    booking_id, session_payment_id, payout_batch_id, stripe_transfer_id,
    source_table, source_id, occurred_at
  ) values (
    'transfer', 'debit', v_transfer.currency, v_transfer.amount_cents,
    v_transfer.therapist_profile_id, v_item.booking_id,
    v_transfer.session_payment_id, v_item.payout_batch_id, v_transfer.id,
    'stripe_transfers', v_transfer.id, p_observed_at
  ) on conflict do nothing;
  return 'transferred';
end;
$$;


ALTER FUNCTION "public"."reconcile_payout_transfer_v1"("p_transfer_id" "uuid", "p_stripe_transfer_id" "text", "p_reversed" boolean, "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_payout_transfer_v2"("p_transfer_id" "uuid", "p_stripe_transfer_id" "text", "p_stripe_destination_payment_id" "text", "p_stripe_connected_balance_transaction_id" "text" DEFAULT NULL::"text", "p_connected_balance_available_on" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reversed" boolean DEFAULT false, "p_observed_at" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text;
begin
  if nullif(trim(p_stripe_destination_payment_id), '') is null then
    raise exception 'PAYOUT_TRANSFER_DESTINATION_PAYMENT_REQUIRED';
  end if;
  v_status := public.reconcile_payout_transfer_v1(
    p_transfer_id, p_stripe_transfer_id, p_reversed, p_observed_at
  );
  update public.stripe_transfers
  set stripe_destination_payment_id = coalesce(
        stripe_destination_payment_id, p_stripe_destination_payment_id
      ),
      stripe_connected_balance_transaction_id = coalesce(
        stripe_connected_balance_transaction_id,
        nullif(trim(p_stripe_connected_balance_transaction_id), '')
      ),
      connected_balance_available_on = coalesce(
        connected_balance_available_on, p_connected_balance_available_on
      ),
      updated_at = now()
  where id = p_transfer_id
    and (
      stripe_destination_payment_id is null
      or stripe_destination_payment_id = p_stripe_destination_payment_id
    );
  if not found then
    raise exception 'PAYOUT_TRANSFER_DESTINATION_PAYMENT_MISMATCH';
  end if;
  return v_status;
end;
$$;


ALTER FUNCTION "public"."reconcile_payout_transfer_v2"("p_transfer_id" "uuid", "p_stripe_transfer_id" "text", "p_stripe_destination_payment_id" "text", "p_stripe_connected_balance_transaction_id" "text", "p_connected_balance_available_on" timestamp with time zone, "p_reversed" boolean, "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_session_payment_amount_v1"("p_session_payment_id" "uuid", "p_charged_amount_cents" integer, "p_original_amount_cents" integer DEFAULT NULL::integer, "p_discount_amount_cents" integer DEFAULT NULL::integer, "p_stripe_checkout_session_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_snapshot record;
  v_existing_original_amount_cents integer;
  v_original_amount_cents integer;
  v_discount_amount_cents integer;
  v_checkout_metadata jsonb;
begin
  if p_charged_amount_cents is null or p_charged_amount_cents < 0 then
    return jsonb_build_object('applied', false, 'reason', 'invalid_charged_amount');
  end if;

  if p_original_amount_cents is not null and p_original_amount_cents < 0 then
    return jsonb_build_object('applied', false, 'reason', 'invalid_original_amount');
  end if;

  if p_discount_amount_cents is not null and p_discount_amount_cents < 0 then
    return jsonb_build_object('applied', false, 'reason', 'invalid_discount_amount');
  end if;

  select *
    into v_payment
  from public.session_payments
  where id = p_session_payment_id
  for update;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'payment_not_found');
  end if;

  v_existing_original_amount_cents := nullif(
    v_payment.metadata #>> '{stripe_checkout,original_amount_cents}',
    ''
  )::integer;

  if v_existing_original_amount_cents is not null
    and p_original_amount_cents is not null
    and v_existing_original_amount_cents <> p_original_amount_cents then
    return jsonb_build_object(
      'applied', false,
      'reason', 'original_amount_conflict'
    );
  end if;

  if v_payment.financial_status in ('paid', 'partially_refunded', 'refunded')
    and v_payment.gross_amount_cents <> p_charged_amount_cents then
    return jsonb_build_object(
      'applied', false,
      'reason', 'charged_amount_conflict'
    );
  end if;

  v_original_amount_cents := coalesce(
    v_existing_original_amount_cents,
    p_original_amount_cents,
    v_payment.gross_amount_cents
  );
  v_discount_amount_cents := coalesce(
    p_discount_amount_cents,
    greatest(v_original_amount_cents - p_charged_amount_cents, 0)
  );

  if jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object' then
    return jsonb_build_object('applied', false, 'reason', 'invalid_metadata');
  end if;

  select *
    into v_snapshot
  from public.calculate_session_payment_snapshot(
    p_charged_amount_cents,
    v_payment.platform_commission_bps
  );

  v_checkout_metadata := coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
    'original_amount_cents', v_original_amount_cents,
    'charged_amount_cents', p_charged_amount_cents,
    'discount_amount_cents', v_discount_amount_cents,
    'reconciled_at', now()
  );

  update public.session_payments
  set gross_amount_cents = v_snapshot.gross_amount_cents,
      platform_gross_commission_cents = v_snapshot.platform_gross_commission_cents,
      therapist_amount_cents = v_snapshot.therapist_amount_cents,
      stripe_checkout_session_id = coalesce(
        p_stripe_checkout_session_id,
        stripe_checkout_session_id
      ),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'stripe_checkout', v_checkout_metadata
      ),
      updated_at = now()
  where id = v_payment.id
  returning * into v_payment;

  return jsonb_build_object(
    'applied', true,
    'chargedAmountCents', v_payment.gross_amount_cents,
    'originalAmountCents', v_original_amount_cents,
    'discountAmountCents', v_discount_amount_cents,
    'platformGrossCommissionCents', v_payment.platform_gross_commission_cents,
    'therapistAmountCents', v_payment.therapist_amount_cents,
    'sessionPaymentId', v_payment.id
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_session_payment_amount_v1"("p_session_payment_id" "uuid", "p_charged_amount_cents" integer, "p_original_amount_cents" integer, "p_discount_amount_cents" integer, "p_stripe_checkout_session_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reconcile_session_payment_amount_v1"("p_session_payment_id" "uuid", "p_charged_amount_cents" integer, "p_original_amount_cents" integer, "p_discount_amount_cents" integer, "p_stripe_checkout_session_id" "text", "p_metadata" "jsonb") IS 'Reconcilia o valor efetivamente cobrado pela Stripe e recalcula comissao e repasse sem criar logica propria de cupons.';



CREATE OR REPLACE FUNCTION "public"."reconcile_session_refund_event_v10"("p_session_payment_id" "uuid", "p_stripe_refund_id" "text", "p_amount_cents" integer, "p_currency" "text", "p_status" "text", "p_reason" "text", "p_stripe_event_id" "text", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_refund public.session_refunds%rowtype;
  v_succeeded integer;
  v_pending boolean;
  v_status text;
begin
  if p_session_payment_id is null
    or nullif(trim(p_stripe_refund_id), '') is null
    or p_amount_cents is null or p_amount_cents <= 0
    or upper(coalesce(p_currency, '')) <> 'BRL'
    or p_status not in ('pending', 'requires_action', 'succeeded', 'failed', 'canceled')
    or nullif(trim(p_stripe_event_id), '') is null
    or p_occurred_at is null then
    raise exception 'V10_REFUND_EVENT_INVALID' using errcode = '22023';
  end if;

  select * into v_payment from public.session_payments
  where id = p_session_payment_id for update;
  if not found or v_payment.payment_flow_version <> 'v10'
    or v_payment.currency <> 'BRL'
    or v_payment.gross_amount_cents < p_amount_cents
    or v_payment.stripe_charge_id is null then
    raise exception 'V10_REFUND_PAYMENT_MISMATCH' using errcode = '23514';
  end if;

  select * into v_refund from public.session_refunds
  where stripe_refund_id = p_stripe_refund_id for update;
  if found and (v_refund.session_payment_id <> v_payment.id
    or v_refund.amount_cents <> p_amount_cents
    or v_refund.currency <> 'BRL') then
    raise exception 'V10_REFUND_ID_REUSED' using errcode = '23505';
  end if;

  -- A delayed older event cannot undo a provider-confirmed refund.
  v_status := case when v_refund.status = 'succeeded' then 'succeeded'
                   else p_status end;
  if v_refund.id is null then
    insert into public.session_refunds (
      session_payment_id, stripe_refund_id, amount_cents, currency,
      status, reason, processed_at, metadata
    ) values (
      v_payment.id, p_stripe_refund_id, p_amount_cents, 'BRL',
      v_status, p_reason,
      case when v_status = 'succeeded' then p_occurred_at else null end,
      jsonb_build_object('paymentFlowVersion', 'v10')
    ) returning * into v_refund;
  elsif v_refund.status is distinct from v_status then
    update public.session_refunds
    set status = v_status,
        processed_at = case when v_status = 'succeeded' then p_occurred_at
                            else processed_at end,
        updated_at = now()
    where id = v_refund.id returning * into v_refund;
  end if;

  select coalesce(sum(amount_cents) filter (where status = 'succeeded'), 0),
         coalesce(bool_or(status in ('pending', 'requires_action')), false)
  into v_succeeded, v_pending
  from public.session_refunds where session_payment_id = v_payment.id;
  if v_succeeded > v_payment.gross_amount_cents then
    raise exception 'V10_REFUND_EXCEEDS_PAYMENT' using errcode = '23514';
  end if;

  if v_status = 'succeeded' then
    insert into public.financial_ledger_entries (
      entry_type, direction, currency, amount_cents,
      patient_profile_id, therapist_profile_id, booking_id,
      session_payment_id, financial_policy_version_id,
      source_table, source_external_id, stripe_event_id, occurred_at
    ) values (
      'refund', 'debit', 'BRL', p_amount_cents,
      v_payment.patient_profile_id, v_payment.therapist_profile_id,
      v_payment.booking_id, v_payment.id,
      v_payment.policy_version_id, 'stripe_refunds', p_stripe_refund_id,
      p_stripe_event_id, p_occurred_at
    ) on conflict (entry_type, source_table, source_external_id, direction)
      do nothing;
  end if;

  update public.session_payments
  set financial_status = case
        when v_succeeded = gross_amount_cents then 'refunded'::public.session_financial_status
        when v_succeeded > 0 then 'partially_refunded'::public.session_financial_status
        else financial_status end,
      refund_pending = v_pending,
      updated_at = now()
  where id = v_payment.id;

  return jsonb_build_object(
    'sessionPaymentId', v_payment.id, 'refundId', v_refund.id,
    'successfulAmountCents', v_succeeded, 'refundPending', v_pending
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_session_refund_event_v10"("p_session_payment_id" "uuid", "p_stripe_refund_id" "text", "p_amount_cents" integer, "p_currency" "text", "p_status" "text", "p_reason" "text", "p_stripe_event_id" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_session_transfer_reversal_v10"("p_stripe_transfer_id" "text", "p_stripe_reversal_id" "text", "p_amount_cents" integer, "p_currency" "text", "p_stripe_event_id" "text", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfer public.stripe_transfers%rowtype;
  v_payment public.session_payments%rowtype;
  v_reversal public.stripe_transfer_reversals%rowtype;
  v_reversed integer;
begin
  if nullif(trim(p_stripe_transfer_id), '') is null
    or nullif(trim(p_stripe_reversal_id), '') is null
    or p_amount_cents is null or p_amount_cents <= 0
    or upper(coalesce(p_currency, '')) <> 'BRL'
    or nullif(trim(p_stripe_event_id), '') is null
    or p_occurred_at is null then
    raise exception 'V10_REVERSAL_EVENT_INVALID' using errcode = '22023';
  end if;

  select * into v_transfer from public.stripe_transfers
  where stripe_transfer_id = p_stripe_transfer_id for update;
  if not found or v_transfer.transfer_origin <> 'session_direct'
    or v_transfer.amount_cents < p_amount_cents then
    raise exception 'V10_REVERSAL_TRANSFER_MISMATCH' using errcode = '23514';
  end if;
  select * into v_payment from public.session_payments
  where id = v_transfer.session_payment_id for update;
  if not found or v_payment.payment_flow_version <> 'v10'
    or v_payment.stripe_charge_id is distinct from v_transfer.stripe_source_charge_id then
    raise exception 'V10_REVERSAL_PAYMENT_MISMATCH' using errcode = '23514';
  end if;

  select * into v_reversal from public.stripe_transfer_reversals
  where stripe_transfer_reversal_id = p_stripe_reversal_id for update;
  if found and (v_reversal.stripe_transfer_id <> v_transfer.id
    or v_reversal.amount_cents <> p_amount_cents
    or v_reversal.currency <> 'BRL') then
    raise exception 'V10_REVERSAL_ID_REUSED' using errcode = '23505';
  end if;
  if v_reversal.id is null then
    insert into public.stripe_transfer_reversals (
      stripe_transfer_id, stripe_transfer_reversal_id, amount_cents,
      currency, reason, status, metadata
    ) values (
      v_transfer.id, p_stripe_reversal_id, p_amount_cents,
      'BRL', 'refund', 'succeeded',
      jsonb_build_object('paymentFlowVersion', 'v10')
    ) returning * into v_reversal;
  end if;

  select coalesce(sum(amount_cents), 0) into v_reversed
  from public.stripe_transfer_reversals
  where stripe_transfer_id = v_transfer.id and status = 'succeeded';
  if v_reversed > v_transfer.amount_cents then
    raise exception 'V10_REVERSAL_EXCEEDS_TRANSFER' using errcode = '23514';
  end if;

  insert into public.financial_ledger_entries (
    entry_type, direction, currency, amount_cents,
    patient_profile_id, therapist_profile_id, booking_id,
    session_payment_id, stripe_transfer_id, financial_policy_version_id,
    transfer_origin, source_table, source_external_id,
    stripe_event_id, occurred_at
  ) values (
    'transfer_reversal', 'credit', 'BRL', p_amount_cents,
    v_payment.patient_profile_id, v_payment.therapist_profile_id,
    v_payment.booking_id, v_payment.id, v_transfer.id,
    v_payment.policy_version_id, 'session_direct',
    'stripe_transfer_reversals', p_stripe_reversal_id,
    p_stripe_event_id, p_occurred_at
  ) on conflict (entry_type, source_table, source_external_id, direction)
    do nothing;

  update public.stripe_transfers
  set status = case when v_reversed = amount_cents then 'reversed'
                    else 'partially_reversed' end,
      updated_at = now()
  where id = v_transfer.id;
  update public.session_transfer_jobs
  set status = case when v_reversed = v_transfer.amount_cents then 'reversed'
                    else 'partially_reversed' end,
      updated_at = now()
  where stripe_transfer_id = v_transfer.id;
  if v_reversed = v_transfer.amount_cents then
    update public.session_payments
    set transfer_status = 'reversed',
        transfer_blocked_reason = 'transfer_reversed', updated_at = now()
    where id = v_payment.id;
  end if;

  return jsonb_build_object(
    'sessionPaymentId', v_payment.id, 'transferId', v_transfer.id,
    'reversedAmountCents', v_reversed,
    'fullyReversed', v_reversed = v_transfer.amount_cents
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_session_transfer_reversal_v10"("p_stripe_transfer_id" "text", "p_stripe_reversal_id" "text", "p_amount_cents" integer, "p_currency" "text", "p_stripe_event_id" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_admin_audit_event_v1"("p_actor_user_id" "uuid", "p_actor_role" "text", "p_permission" "text", "p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_previous_state" "jsonb", "p_next_state" "jsonb", "p_reason" "text", "p_request_id" "text", "p_correlation_id" "text", "p_source" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event_id uuid;
begin
  if nullif(btrim(coalesce(p_request_id, '')), '') is not null then
    select admin_audit_events.id
    into v_event_id
    from public.admin_audit_events
    where admin_audit_events.source = coalesce(nullif(btrim(coalesce(p_source, '')), ''), 'admin')
      and admin_audit_events.request_id = nullif(btrim(coalesce(p_request_id, '')), '')
      and admin_audit_events.action = nullif(btrim(coalesce(p_action, '')), '')
      and admin_audit_events.entity_type = nullif(btrim(coalesce(p_entity_type, '')), '')
    limit 1;

    if v_event_id is not null then
      return v_event_id;
    end if;
  end if;

  insert into public.admin_audit_events (
    actor_user_id,
    actor_role,
    permission,
    action,
    entity_type,
    entity_id,
    previous_state,
    next_state,
    reason,
    request_id,
    correlation_id,
    source
  )
  values (
    p_actor_user_id,
    nullif(btrim(coalesce(p_actor_role, '')), ''),
    nullif(btrim(coalesce(p_permission, '')), ''),
    nullif(btrim(coalesce(p_action, '')), ''),
    nullif(btrim(coalesce(p_entity_type, '')), ''),
    nullif(btrim(coalesce(p_entity_id, '')), ''),
    coalesce(p_previous_state, '{}'::jsonb),
    coalesce(p_next_state, '{}'::jsonb),
    nullif(btrim(coalesce(p_reason, '')), ''),
    nullif(btrim(coalesce(p_request_id, '')), ''),
    nullif(btrim(coalesce(p_correlation_id, '')), ''),
    coalesce(nullif(btrim(coalesce(p_source, '')), ''), 'admin')
  )
  returning id into v_event_id;

  return v_event_id;
exception
  when unique_violation then
    if nullif(btrim(coalesce(p_request_id, '')), '') is null then
      raise;
    end if;

    select admin_audit_events.id
    into v_event_id
    from public.admin_audit_events
    where admin_audit_events.source = coalesce(nullif(btrim(coalesce(p_source, '')), ''), 'admin')
      and admin_audit_events.request_id = nullif(btrim(coalesce(p_request_id, '')), '')
      and admin_audit_events.action = nullif(btrim(coalesce(p_action, '')), '')
      and admin_audit_events.entity_type = nullif(btrim(coalesce(p_entity_type, '')), '')
    limit 1;

    if v_event_id is null then
      raise;
    end if;

    return v_event_id;
end;
$$;


ALTER FUNCTION "public"."record_admin_audit_event_v1"("p_actor_user_id" "uuid", "p_actor_role" "text", "p_permission" "text", "p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_previous_state" "jsonb", "p_next_state" "jsonb", "p_reason" "text", "p_request_id" "text", "p_correlation_id" "text", "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_admin_audit_event_v1"("p_actor_user_id" "uuid", "p_actor_role" "text", "p_permission" "text", "p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_previous_state" "jsonb", "p_next_state" "jsonb", "p_reason" "text", "p_request_id" "text", "p_correlation_id" "text", "p_source" "text") IS 'Service-role-only writer for sanitized admin audit events. Browser roles must not call it directly.';



CREATE OR REPLACE FUNCTION "public"."record_automatic_stripe_payout_v1"("p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_amount_cents" integer, "p_currency" "text", "p_provider_status" "text", "p_provider_reconciliation_status" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_payout_balance_transaction_id" "text" DEFAULT NULL::"text", "p_source_type" "text" DEFAULT NULL::"text", "p_arrival_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_account public.therapist_connect_accounts%rowtype;
  v_payout public.stripe_payouts%rowtype;
  v_was_paid boolean := false;
begin
  if nullif(trim(p_stripe_payout_id), '') is null
    or nullif(trim(p_stripe_account_id), '') is null
    or p_amount_cents <= 0
    or upper(p_currency) <> 'BRL'
    or p_provider_status not in ('pending', 'in_transit', 'paid', 'failed', 'canceled')
    or p_provider_reconciliation_status not in ('in_progress', 'completed', 'not_applicable')
    or nullif(trim(p_stripe_event_id), '') is null
    or p_stripe_event_created_at is null
  then
    raise exception 'AUTOMATIC_STRIPE_PAYOUT_EVENT_INVALID';
  end if;

  select * into v_account
  from public.therapist_connect_accounts
  where stripe_account_id = p_stripe_account_id
  for update;
  if not found then
    return jsonb_build_object('applied', false, 'reason', 'connect_account_not_found');
  end if;

  select * into v_payout
  from public.stripe_payouts
  where stripe_payout_id = p_stripe_payout_id
  for update;
  if found then
    if v_payout.connect_account_id <> v_account.id then
      raise exception 'AUTOMATIC_STRIPE_PAYOUT_ACCOUNT_MISMATCH';
    end if;
    if v_payout.stripe_event_created_at is not null
      and p_stripe_event_created_at < v_payout.stripe_event_created_at
    then
      return jsonb_build_object('applied', false, 'reason', 'stale_event');
    end if;
    v_was_paid := v_payout.status = 'paid';
  else
    insert into public.stripe_payouts (
      payout_batch_therapist_id, payout_batch_id, therapist_profile_id,
      connect_account_id, stripe_payout_id, idempotency_key,
      request_fingerprint, amount_cents, currency, source_type, status,
      provider_status, stripe_event_id, stripe_event_created_at, arrival_at,
      automatic, payout_balance_transaction_id,
      provider_reconciliation_status, allocation_status
    ) values (
      null, null, v_account.therapist_profile_id, v_account.id,
      p_stripe_payout_id, null, null, p_amount_cents, 'BRL', p_source_type,
      'pending', p_provider_status, p_stripe_event_id,
      p_stripe_event_created_at, p_arrival_at, true,
      nullif(trim(p_payout_balance_transaction_id), ''),
      p_provider_reconciliation_status, 'pending'
    ) returning * into v_payout;
  end if;

  update public.stripe_payouts
  set provider_status = p_provider_status,
      status = case p_provider_status
        when 'paid' then 'paid'::public.stripe_payout_status
        when 'failed' then 'failed'::public.stripe_payout_status
        when 'canceled' then 'canceled'::public.stripe_payout_status
        when 'in_transit' then 'in_transit'::public.stripe_payout_status
        else 'pending'::public.stripe_payout_status
      end,
      provider_reconciliation_status = p_provider_reconciliation_status,
      payout_balance_transaction_id = coalesce(
        payout_balance_transaction_id,
        nullif(trim(p_payout_balance_transaction_id), '')
      ),
      source_type = coalesce(p_source_type, source_type),
      failure_code = left(nullif(regexp_replace(coalesce(p_failure_code, ''), '[\r\n]+', ' ', 'g'), ''), 120),
      failure_message = left(nullif(regexp_replace(coalesce(p_failure_message, ''), '[\r\n]+', ' ', 'g'), ''), 500),
      stripe_event_id = p_stripe_event_id,
      stripe_event_created_at = p_stripe_event_created_at,
      arrival_at = coalesce(p_arrival_at, arrival_at),
      paid_at = case when p_provider_status = 'paid'
        then coalesce(paid_at, p_stripe_event_created_at) else paid_at end,
      failed_at = case when p_provider_status = 'failed'
        then p_stripe_event_created_at else failed_at end,
      updated_at = now()
  where stripe_payout_id = p_stripe_payout_id
  returning * into v_payout;

  if p_provider_status = 'failed' then
    perform public.record_payout_operational_incident_v1(
      'automatic-payout:' || v_payout.id::text || ':failed',
      case when v_was_paid then 'payout_failed_after_paid' else 'payout_failed' end,
      'critical', p_failure_code, p_failure_message, null, null, null, null,
      v_payout.id, v_payout.therapist_profile_id,
      jsonb_build_object('failedAfterPaid', v_was_paid, 'automatic', true)
    );
  end if;

  perform public.refresh_automatic_payout_batch_states_v1();

  return jsonb_build_object(
    'applied', true,
    'payoutId', v_payout.id,
    'status', v_payout.status,
    'automatic', true,
    'failedAfterPaid', v_was_paid and p_provider_status = 'failed'
  );
end;
$$;


ALTER FUNCTION "public"."record_automatic_stripe_payout_v1"("p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_amount_cents" integer, "p_currency" "text", "p_provider_status" "text", "p_provider_reconciliation_status" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_payout_balance_transaction_id" "text", "p_source_type" "text", "p_arrival_at" timestamp with time zone, "p_failure_code" "text", "p_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_favorite_therapist_metric_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_timezone text;
  v_metric_date date;
  v_inserted_id uuid;
begin
  select settings.timezone
    into v_timezone
  from public.therapist_schedule_settings as settings
  where settings.therapist_profile_id = new.therapist_profile_id;

  v_timezone := coalesce(v_timezone, 'America/Sao_Paulo');
  v_metric_date := (new.created_at at time zone v_timezone)::date;

  insert into public.therapist_metric_events (
    event_id,
    event_type,
    event_source,
    therapist_profile_id,
    dedupe_key,
    metric_date,
    definition_version,
    occurred_at
  )
  values (
    new.id,
    'favorite_therapist_added',
    'authoritative',
    new.therapist_profile_id,
    'favorite:' || new.id::text,
    v_metric_date,
    1,
    new.created_at
  )
  on conflict do nothing
  returning id into v_inserted_id;

  if v_inserted_id is not null then
    perform public.increment_therapist_metric_daily_v1(
      new.therapist_profile_id,
      v_metric_date,
      'favorite_therapist_added',
      new.created_at
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."record_favorite_therapist_metric_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_patient_zoom_waiting_room_arrival_v1"("p_booking_id" "uuid", "p_patient_profile_id" "uuid", "p_now" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_booking record;
  v_now timestamptz := coalesce(p_now, clock_timestamp());
  v_arrived_at timestamptz;
  v_request_id text;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_booking_id::text, 0)
  );

  select
    booking.id,
    booking.patient_profile_id,
    booking.starts_at,
    booking.ends_at,
    booking.version,
    booking.status,
    booking.meeting_provider,
    patient.user_id as patient_user_id,
    payment.financial_status
  into v_booking
  from public.bookings booking
  join public.patient_profiles patient
    on patient.id = booking.patient_profile_id
  left join public.session_payments payment
    on payment.booking_id = booking.id
  where booking.id = p_booking_id
  limit 1;

  if not found then
    raise exception 'ZOOM_BOOKING_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_booking.patient_profile_id is distinct from p_patient_profile_id then
    raise exception 'ZOOM_WAITING_ROOM_PARTICIPANT_REQUIRED'
      using errcode = '42501';
  end if;

  if v_booking.status <> 'confirmed'::public.booking_status
    or v_booking.meeting_provider not in ('zoom', 'zoom_video_sdk')
    or v_booking.financial_status is distinct from 'paid'::public.session_financial_status
    or v_now < v_booking.starts_at - interval '15 minutes'
    or v_now >= v_booking.ends_at then
    return jsonb_build_object(
      'arrivedAt', null,
      'entitled', false,
      'recorded', false
    );
  end if;

  select min(event.created_at)
  into v_arrived_at
  from public.booking_events event
  where event.booking_id = v_booking.id
    and event.event_type = 'zoom_waiting_room_entered'
    and event.payload ->> 'bookingVersion' = v_booking.version::text
    and event.payload ->> 'scheduledStartsAt' = v_booking.starts_at::text;

  if v_arrived_at is not null then
    return jsonb_build_object(
      'arrivedAt', v_arrived_at,
      'entitled', true,
      'recorded', false
    );
  end if;

  if v_now > v_booking.starts_at + interval '10 minutes' then
    return jsonb_build_object(
      'arrivedAt', null,
      'entitled', false,
      'recorded', false
    );
  end if;

  v_request_id := left(
    'zoom-waiting-room:' || v_booking.id::text || ':v' || v_booking.version::text ||
      ':' || floor(extract(epoch from v_booking.starts_at) * 1000)::bigint::text,
    160
  );

  insert into public.booking_events (
    booking_id,
    actor_profile_id,
    event_type,
    payload,
    request_id,
    source
  ) values (
    v_booking.id,
    v_booking.patient_user_id,
    'zoom_waiting_room_entered',
    jsonb_build_object(
      'bookingVersion', v_booking.version,
      'scheduledStartsAt', v_booking.starts_at::text,
      'source', 'authenticated_waiting_room'
    ),
    v_request_id,
    'zoom-video-session-access'
  )
  on conflict (booking_id, event_type, request_id)
    where request_id is not null
  do nothing;

  select min(event.created_at)
  into v_arrived_at
  from public.booking_events event
  where event.booking_id = v_booking.id
    and event.event_type = 'zoom_waiting_room_entered'
    and event.payload ->> 'bookingVersion' = v_booking.version::text
    and event.payload ->> 'scheduledStartsAt' = v_booking.starts_at::text;

  return jsonb_build_object(
    'arrivedAt', v_arrived_at,
    'entitled', v_arrived_at is not null,
    'recorded', v_arrived_at is not null
  );
end;
$$;


ALTER FUNCTION "public"."record_patient_zoom_waiting_room_arrival_v1"("p_booking_id" "uuid", "p_patient_profile_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_patient_zoom_waiting_room_arrival_v1"("p_booking_id" "uuid", "p_patient_profile_id" "uuid", "p_now" timestamp with time zone) IS 'Records one authoritative patient waiting-room arrival per booking version between T-15 and T+10, preserving re-entry until the scheduled end.';



CREATE OR REPLACE FUNCTION "public"."record_payout_operational_incident_v1"("p_incident_key" "text", "p_incident_type" "text", "p_severity" "text" DEFAULT 'warning'::"text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text", "p_payout_scheduler_run_id" "uuid" DEFAULT NULL::"uuid", "p_payout_batch_id" "uuid" DEFAULT NULL::"uuid", "p_payout_batch_item_id" "uuid" DEFAULT NULL::"uuid", "p_stripe_transfer_id" "uuid" DEFAULT NULL::"uuid", "p_stripe_payout_id" "uuid" DEFAULT NULL::"uuid", "p_therapist_profile_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
begin
  if nullif(trim(p_incident_key), '') is null
    or nullif(trim(p_incident_type), '') is null
    or p_severity not in ('info', 'warning', 'critical')
    or jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object'
  then
    raise exception 'PAYOUT_INCIDENT_INVALID';
  end if;

  insert into public.payout_operational_incidents (
    incident_key, incident_type, severity, error_code, error_message,
    payout_scheduler_run_id, payout_batch_id, payout_batch_item_id,
    stripe_transfer_id, stripe_payout_id, therapist_profile_id, metadata
  ) values (
    left(trim(p_incident_key), 240), left(trim(p_incident_type), 120), p_severity,
    left(nullif(regexp_replace(coalesce(p_error_code, ''), '[\r\n]+', ' ', 'g'), ''), 120),
    left(nullif(regexp_replace(coalesce(p_error_message, ''), '[\r\n]+', ' ', 'g'), ''), 500),
    p_payout_scheduler_run_id, p_payout_batch_id, p_payout_batch_item_id,
    p_stripe_transfer_id, p_stripe_payout_id, p_therapist_profile_id,
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (incident_key) do update
  set occurrence_count = public.payout_operational_incidents.occurrence_count + 1,
      last_occurred_at = now(),
      severity = excluded.severity,
      error_code = excluded.error_code,
      error_message = excluded.error_message,
      metadata = public.payout_operational_incidents.metadata || excluded.metadata,
      status = 'open',
      resolved_at = null
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_payout_operational_incident_v1"("p_incident_key" "text", "p_incident_type" "text", "p_severity" "text", "p_error_code" "text", "p_error_message" "text", "p_payout_scheduler_run_id" "uuid", "p_payout_batch_id" "uuid", "p_payout_batch_item_id" "uuid", "p_stripe_transfer_id" "uuid", "p_stripe_payout_id" "uuid", "p_therapist_profile_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payout_scheduler_failure_v1"("p_run_id" "uuid", "p_worker_id" "uuid", "p_error_code" "text", "p_error_message" "text", "p_request_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.payout_scheduler_runs%rowtype;
  v_failure_count integer;
  v_retry_at timestamptz;
  v_code text;
  v_message text;
  v_circuit_open boolean;
begin
  if p_run_id is null or p_worker_id is null or p_request_id is null or p_now is null then
    raise exception 'PAYOUT_SCHEDULER_FAILURE_INVALID';
  end if;

  select * into v_run
  from public.payout_scheduler_runs
  where id = p_run_id
  for update;

  if not found then raise exception 'PAYOUT_SCHEDULER_RUN_NOT_FOUND'; end if;
  if v_run.status <> 'running' or v_run.worker_id is distinct from p_worker_id then
    raise exception 'PAYOUT_SCHEDULER_LEASE_LOST';
  end if;

  v_failure_count := least(v_run.consecutive_failures + 1, 4);
  v_code := left(nullif(regexp_replace(coalesce(p_error_code, ''), '[\r\n]+', ' ', 'g'), ''), 120);
  v_message := left(nullif(regexp_replace(coalesce(p_error_message, ''), '[\r\n]+', ' ', 'g'), ''), 500);
  v_circuit_open := v_failure_count >= 4;
  v_retry_at := case v_failure_count
    when 1 then p_now + interval '15 minutes'
    when 2 then p_now + interval '30 minutes'
    when 3 then p_now + interval '60 minutes'
    else null
  end;

  update public.payout_scheduler_runs
  set consecutive_failures = v_failure_count,
      next_retry_at = v_retry_at,
      last_failed_at = p_now,
      last_error_code = coalesce(v_code, 'worker_failure'),
      last_error_message = coalesce(v_message, 'Worker execution failed.'),
      last_request_id = p_request_id,
      status = case when v_circuit_open then 'failed'::public.payout_scheduler_run_status else status end,
      completed_at = case when v_circuit_open then coalesce(completed_at, p_now) else completed_at end,
      worker_id = null,
      lease_expires_at = null,
      updated_at = now()
  where id = v_run.id;

  if v_circuit_open then
    perform public.record_payout_operational_incident_v1(
      'scheduler:' || v_run.id::text || ':worker-circuit-open',
      'weekly_payout_scheduler_failed',
      'critical',
      coalesce(v_code, 'worker_failure'),
      coalesce(v_message, 'Worker execution failed.'),
      v_run.id,
      v_run.payout_batch_id,
      null, null, null, null,
      jsonb_build_object(
        'consecutiveFailures', v_failure_count,
        'requestId', p_request_id
      )
    );
  end if;

  return jsonb_build_object(
    'recorded', true,
    'runId', v_run.id,
    'consecutiveFailures', v_failure_count,
    'retryAt', v_retry_at,
    'circuitOpen', v_circuit_open
  );
end;
$$;


ALTER FUNCTION "public"."record_payout_scheduler_failure_v1"("p_run_id" "uuid", "p_worker_id" "uuid", "p_error_code" "text", "p_error_message" "text", "p_request_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payout_scheduler_progress_v1"("p_run_id" "uuid", "p_worker_id" "uuid", "p_request_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.payout_scheduler_runs%rowtype;
begin
  if p_run_id is null or p_worker_id is null or p_request_id is null or p_now is null then
    raise exception 'PAYOUT_SCHEDULER_PROGRESS_INVALID';
  end if;

  select * into v_run
  from public.payout_scheduler_runs
  where id = p_run_id
  for update;

  if not found then raise exception 'PAYOUT_SCHEDULER_RUN_NOT_FOUND'; end if;
  if v_run.status <> 'running' or v_run.worker_id is distinct from p_worker_id then
    raise exception 'PAYOUT_SCHEDULER_LEASE_LOST';
  end if;

  update public.payout_scheduler_runs
  set consecutive_failures = 0,
      next_retry_at = null,
      last_succeeded_at = p_now,
      last_error_code = null,
      last_error_message = null,
      last_request_id = p_request_id,
      updated_at = now()
  where id = v_run.id;

  update public.payout_operational_incidents
  set status = 'resolved',
      resolved_at = coalesce(resolved_at, p_now),
      updated_at = now()
  where incident_key = 'scheduler:' || v_run.id::text || ':worker-circuit-open'
    and status = 'open';

  return jsonb_build_object('recorded', true, 'runId', v_run.id);
end;
$$;


ALTER FUNCTION "public"."record_payout_scheduler_progress_v1"("p_run_id" "uuid", "p_worker_id" "uuid", "p_request_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_public_therapist_metric_events_v1"("p_session_id" "uuid", "p_events" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_role public.user_role;
  v_event jsonb;
  v_event_id uuid;
  v_event_type text;
  v_slug text;
  v_service_id uuid;
  v_therapy_id uuid;
  v_result_set_id uuid;
  v_result_position integer;
  v_source_surface text;
  v_therapist_profile_id uuid;
  v_timezone text;
  v_metric_date date;
  v_session_hash text;
  v_dedupe_key text;
  v_inserted_id uuid;
  v_accepted integer := 0;
  v_duplicates integer := 0;
  v_ignored integer := 0;
  v_event_count integer;
begin
  if not coalesce(
    (
      select config.public_telemetry_enabled
      from public.therapist_metrics_runtime_config as config
      where config.singleton = true
    ),
    false
  ) then
    return jsonb_build_object(
      'status', 'disabled',
      'accepted', 0,
      'duplicates', 0,
      'ignored', 0
    );
  end if;

  if p_session_id is null
    or jsonb_typeof(p_events) <> 'array'
    or jsonb_array_length(p_events) < 1
    or jsonb_array_length(p_events) > 20 then
    raise exception 'VALIDATION_ERROR' using errcode = '22023';
  end if;

  select profile.role
    into v_actor_role
  from public.profiles as profile
  where profile.id = auth.uid();

  if v_actor_role in ('therapist', 'admin') then
    return jsonb_build_object(
      'status', 'ignored',
      'accepted', 0,
      'duplicates', 0,
      'ignored', jsonb_array_length(p_events)
    );
  end if;

  v_session_hash := encode(
    extensions.digest(p_session_id::text, 'sha256'::text),
    'hex'
  );

  select count(*)
    into v_event_count
  from public.therapist_metric_events as metric_event
  where metric_event.event_source = 'browser'
    and metric_event.session_key_hash = v_session_hash
    and metric_event.occurred_at >= now() - interval '1 day';

  if v_event_count + jsonb_array_length(p_events) > 100 then
    raise exception 'RATE_LIMITED' using errcode = 'P0001';
  end if;

  for v_event in
    select value
    from jsonb_array_elements(p_events)
  loop
    begin
      if jsonb_typeof(v_event) <> 'object'
        or (v_event - array[
          'eventId',
          'eventType',
          'therapistSlug',
          'serviceId',
          'resultSetId',
          'resultPosition',
          'sourceSurface'
        ]::text[]) <> '{}'::jsonb then
        raise exception 'VALIDATION_ERROR' using errcode = '22023';
      end if;

      v_event_id := (v_event ->> 'eventId')::uuid;
      v_event_type := nullif(trim(v_event ->> 'eventType'), '');
      v_slug := nullif(trim(v_event ->> 'therapistSlug'), '');
      v_service_id := nullif(v_event ->> 'serviceId', '')::uuid;
      v_result_set_id := nullif(v_event ->> 'resultSetId', '')::uuid;
      v_result_position := nullif(v_event ->> 'resultPosition', '')::integer;
      v_source_surface := nullif(trim(v_event ->> 'sourceSurface'), '');

      if v_event_type not in (
        'search_impression',
        'profile_view',
        'booking_flow_started'
      )
        or v_slug is null
        or length(v_slug) > 120
        or v_source_surface not in (
          'therapist_search',
          'therapist_profile'
        ) then
        raise exception 'VALIDATION_ERROR' using errcode = '22023';
      end if;

      if v_event_type = 'search_impression' and (
        v_source_surface <> 'therapist_search'
        or v_result_set_id is null
        or v_result_position is null
        or v_result_position not between 1 and 100
        or v_service_id is not null
      ) then
        raise exception 'VALIDATION_ERROR' using errcode = '22023';
      end if;

      if v_event_type = 'profile_view' and (
        v_source_surface <> 'therapist_profile'
        or v_result_set_id is not null
        or v_result_position is not null
        or v_service_id is not null
      ) then
        raise exception 'VALIDATION_ERROR' using errcode = '22023';
      end if;

      if v_event_type = 'booking_flow_started' and (
        v_source_surface not in ('therapist_profile', 'therapist_search')
        or v_service_id is null
        or v_result_set_id is not null
        or v_result_position is not null
      ) then
        raise exception 'VALIDATION_ERROR' using errcode = '22023';
      end if;

      select public_profile.id, schedule_settings.timezone
        into v_therapist_profile_id, v_timezone
      from public.public_therapist_profiles_v as public_profile
      join public.therapist_schedule_settings as schedule_settings
        on schedule_settings.therapist_profile_id = public_profile.id
      where public_profile.slug = v_slug;

      if not found then
        v_ignored := v_ignored + 1;
        continue;
      end if;

      v_therapy_id := null;
      if v_service_id is not null then
        select service.therapy_id
          into v_therapy_id
        from public.therapist_services as service
        join public.therapies as therapy
          on therapy.id = service.therapy_id
        where service.id = v_service_id
          and service.therapist_profile_id = v_therapist_profile_id
          and service.status = 'active'
          and service.is_bookable = true
          and service.online_only = true
          and therapy.status = 'published'
          and therapy.is_public_visible = true;

        if not found then
          v_ignored := v_ignored + 1;
          continue;
        end if;
      end if;

      v_metric_date := (now() at time zone v_timezone)::date;
      v_dedupe_key := encode(
        extensions.digest(
          concat_ws(
            ':',
            v_event_type,
            v_therapist_profile_id::text,
            v_session_hash,
            coalesce(v_service_id::text, ''),
            coalesce(v_result_set_id::text, ''),
            case
              when v_event_type = 'profile_view'
                then v_metric_date::text
              when v_event_type = 'booking_flow_started'
                then v_metric_date::text
              else ''
            end
          ),
          'sha256'::text
        ),
        'hex'
      );

      v_inserted_id := null;
      insert into public.therapist_metric_events (
        event_id,
        event_type,
        event_source,
        therapist_profile_id,
        service_id,
        therapy_id,
        session_key_hash,
        result_set_id,
        result_position,
        source_surface,
        dedupe_key,
        metric_date,
        definition_version,
        occurred_at
      )
      values (
        v_event_id,
        v_event_type,
        'browser',
        v_therapist_profile_id,
        v_service_id,
        v_therapy_id,
        v_session_hash,
        v_result_set_id,
        v_result_position,
        v_source_surface,
        v_dedupe_key,
        v_metric_date,
        1,
        now()
      )
      on conflict do nothing
      returning id into v_inserted_id;

      if v_inserted_id is null then
        if exists (
          select 1
          from public.therapist_metric_events as existing_event
          where existing_event.event_id = v_event_id
            and existing_event.dedupe_key <> v_dedupe_key
        ) then
          raise exception 'REQUEST_CONFLICT' using errcode = '23505';
        end if;

        v_duplicates := v_duplicates + 1;
      else
        perform public.increment_therapist_metric_daily_v1(
          v_therapist_profile_id,
          v_metric_date,
          v_event_type,
          now()
        );
        v_accepted := v_accepted + 1;
      end if;
    exception
      when invalid_text_representation
        or numeric_value_out_of_range
        or check_violation then
        raise exception 'VALIDATION_ERROR' using errcode = '22023';
    end;
  end loop;

  return jsonb_build_object(
    'status', 'accepted',
    'accepted', v_accepted,
    'duplicates', v_duplicates,
    'ignored', v_ignored
  );
end;
$$;


ALTER FUNCTION "public"."record_public_therapist_metric_events_v1"("p_session_id" "uuid", "p_events" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_public_therapist_metric_events_v1"("p_session_id" "uuid", "p_events" "jsonb") IS 'MTR-1 browser ingestion. Validates public entities, deduplicates, rate-limits and stores no raw IP, user agent, query string or free text.';



CREATE OR REPLACE FUNCTION "public"."record_session_participant_confirmation_v1"("p_actor_user_id" "uuid", "p_booking_id" "uuid", "p_outcome" "text", "p_request_id" "uuid", "p_source" "text" DEFAULT 'manual'::"text", "p_confirmed_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_role public.user_role;
  v_ends_at timestamptz;
  v_policy public.financial_policy_versions%rowtype;
  v_existing public.session_participant_confirmations;
  v_hash text;
  v_confirmation public.session_participant_confirmations;
  v_due_at timestamptz;
begin
  if p_actor_user_id is null or p_booking_id is null or p_request_id is null
    or p_outcome not in ('completed', 'not_performed')
    or p_source not in ('manual', 'automatic') then
    raise exception 'SESSION_CONFIRMATION_VALIDATION_ERROR' using errcode = '22023';
  end if;

  select case
      when patient_profiles.user_id = p_actor_user_id then 'patient'::public.user_role
      when therapist_profiles.user_id = p_actor_user_id then 'therapist'::public.user_role
      else null
    end,
    bookings.ends_at
  into v_actor_role, v_ends_at
  from public.bookings
  left join public.patient_profiles on patient_profiles.id = bookings.patient_profile_id
  left join public.therapist_profiles on therapist_profiles.id = bookings.therapist_profile_id
  join public.session_payments payment on payment.booking_id = bookings.id
  where bookings.id = p_booking_id
    and payment.financial_status in ('paid', 'partially_refunded');

  if v_actor_role is null then
    raise exception 'SESSION_CONFIRMATION_PARTICIPANT_REQUIRED' using errcode = '42501';
  end if;

  select policy.* into v_policy
  from public.session_payments payment
  join public.financial_policy_versions policy on policy.id = payment.policy_version_id
  where payment.booking_id = p_booking_id;

  if v_policy.id is null then
    raise exception 'SESSION_CONFIRMATION_POLICY_REQUIRED';
  end if;

  v_due_at := v_ends_at + make_interval(
    days => case v_actor_role
      when 'patient'::public.user_role then v_policy.patient_auto_confirmation_days
      else v_policy.therapist_auto_confirmation_days
    end
  );
  v_hash := encode(
    extensions.digest(
      concat_ws('|', p_booking_id::text, v_actor_role::text, p_outcome, p_source),
      'sha256'
    ),
    'hex'
  );

  select confirmation.* into v_existing
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = v_actor_role
  for update;

  if v_existing.id is not null then
    if v_existing.payload_hash <> v_hash then
      raise exception 'SESSION_CONFIRMATION_REQUEST_CONFLICT' using errcode = '23505';
    end if;
    return jsonb_build_object(
      'confirmation', jsonb_build_object(
        'confirmedAt', v_existing.confirmed_at,
        'dueAt', v_existing.due_at,
        'outcome', v_existing.outcome,
        'source', v_existing.source
      ),
      'idempotentReplay', true
    );
  end if;

  insert into public.session_participant_confirmations (
    booking_id, participant_role, outcome, source, confirmed_by_profile_id,
    request_id, payload_hash, due_at, confirmed_at, policy_version_id
  ) values (
    p_booking_id, v_actor_role, p_outcome, p_source,
    case when p_source = 'manual' then p_actor_user_id else null end,
    p_request_id, v_hash, v_due_at, p_confirmed_at, v_policy.id
  )
  returning * into v_confirmation;

  return jsonb_build_object(
    'confirmation', jsonb_build_object(
      'confirmedAt', v_confirmation.confirmed_at,
      'dueAt', v_confirmation.due_at,
      'outcome', v_confirmation.outcome,
      'source', v_confirmation.source
    ),
    'idempotentReplay', false
  );
exception
  when unique_violation then
    select confirmation.* into v_existing
    from public.session_participant_confirmations confirmation
    where confirmation.booking_id = p_booking_id
      and confirmation.participant_role = v_actor_role
    limit 1;
    if v_existing.id is not null and v_existing.payload_hash = v_hash then
      return jsonb_build_object(
        'confirmation', jsonb_build_object(
          'confirmedAt', v_existing.confirmed_at,
          'dueAt', v_existing.due_at,
          'outcome', v_existing.outcome,
          'source', v_existing.source
        ),
        'idempotentReplay', true
      );
    end if;
    raise exception 'SESSION_CONFIRMATION_REQUEST_CONFLICT' using errcode = '23505';
end;
$$;


ALTER FUNCTION "public"."record_session_participant_confirmation_v1"("p_actor_user_id" "uuid", "p_booking_id" "uuid", "p_outcome" "text", "p_request_id" "uuid", "p_source" "text", "p_confirmed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_session_payment_intent_v10"("p_schedule_id" "uuid", "p_session_payment_id" "uuid", "p_booking_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_payment_intent_id" "text", "p_status" "text", "p_amount_cents" integer, "p_currency" "text", "p_stripe_customer_id" "text", "p_stripe_payment_method_id" "text", "p_stripe_charge_id" "text" DEFAULT NULL::"text", "p_event_id" "text" DEFAULT NULL::"text", "p_event_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
  v_setup public.session_payment_setups%rowtype;
  v_booking public.bookings%rowtype;
  v_patient_user_id uuid;
  v_result jsonb;
begin
  if p_schedule_id is null or p_session_payment_id is null
    or p_booking_id is null or p_booking_version is null
    or p_stripe_environment not in ('test', 'live')
    or nullif(trim(p_payment_intent_id), '') is null
    or p_status not in ('succeeded', 'processing', 'requires_action', 'requires_payment_method', 'canceled')
    or p_amount_cents is null or p_amount_cents <= 0
    or nullif(trim(p_currency), '') is null
    or nullif(trim(p_stripe_customer_id), '') is null
  then
    raise exception 'SESSION_PAYMENT_INTENT_V10_INVALID' using errcode = '22023';
  end if;

  -- Match the lock order used by the paid/outbox RPC.
  select p.* into v_payment
  from public.session_payments p
  join public.session_payment_schedules s on s.session_payment_id = p.id
  where s.id = p_schedule_id
  for update of p;
  if not found or v_payment.payment_flow_version <> 'v10' then
    raise exception 'SESSION_PAYMENT_INTENT_V10_NOT_FOUND' using errcode = 'P0002';
  end if;
  select * into v_schedule from public.session_payment_schedules
  where id = p_schedule_id for update;
  select * into v_setup from public.session_payment_setups
  where id = v_schedule.session_payment_setup_id;
  select * into v_booking from public.bookings where id = v_schedule.booking_id;

  if v_schedule.session_payment_id <> v_payment.id
    or v_schedule.session_payment_id <> p_session_payment_id
    or v_schedule.booking_id <> p_booking_id
    or v_schedule.booking_version <> p_booking_version
    or v_schedule.stripe_environment <> p_stripe_environment
    or v_schedule.booking_id <> v_payment.booking_id
    or v_setup.session_payment_id <> v_payment.id
    or v_setup.booking_version <> v_schedule.booking_version
    or v_setup.status <> 'succeeded'
    or v_setup.superseded_at is not null
    or v_setup.stripe_customer_id <> trim(p_stripe_customer_id)
    or (p_stripe_payment_method_id is not null
      and v_setup.stripe_payment_method_id <> trim(p_stripe_payment_method_id)
      and not exists (
        select 1 from public.session_charge_recoveries_v10 recovery
        where recovery.schedule_id = v_schedule.id
          and recovery.stripe_payment_intent_id = trim(p_payment_intent_id)
          and recovery.patient_profile_id = v_booking.patient_profile_id
          and recovery.status in ('open', 'consumed')
      ))
    or v_payment.gross_amount_cents <> p_amount_cents
    or lower(v_payment.currency::text) <> lower(trim(p_currency))
    or v_booking.version <> v_schedule.expected_booking_version
    or v_booking.status <> 'confirmed'
    or v_schedule.status in ('canceled', 'superseded')
    or (v_schedule.stripe_payment_intent_id is not null
      and v_schedule.stripe_payment_intent_id <> trim(p_payment_intent_id))
  then
    raise exception 'SESSION_PAYMENT_INTENT_V10_BINDING_MISMATCH' using errcode = '23514';
  end if;

  if p_status = 'succeeded' then
    if nullif(trim(p_stripe_charge_id), '') is null
      or nullif(trim(p_event_id), '') is null
      or p_event_created_at is null
    then
      raise exception 'SESSION_PAYMENT_INTENT_V10_SUCCESS_INCOMPLETE' using errcode = '22023';
    end if;
    v_result := public.confirm_session_payment_and_enqueue_transfer_v10(
      v_payment.id, p_stripe_environment, trim(p_payment_intent_id),
      trim(p_stripe_charge_id), p_event_created_at,
      trim(p_event_id), p_event_created_at
    );
    update public.session_charge_incidents_v10
    set status = 'resolved', resolved_at = now(), updated_at = now()
    where schedule_id = v_schedule.id and status = 'open';
    update public.session_charge_recoveries_v10
    set status = 'consumed', consumed_at = coalesce(consumed_at, now())
    where schedule_id = v_schedule.id and status = 'open';
    return v_result || jsonb_build_object('scheduleStatus', 'paid');
  end if;

  if v_payment.financial_status = 'paid' or v_schedule.status = 'paid' then
    return jsonb_build_object('scheduleStatus', 'paid', 'applied', false);
  end if;
  if v_schedule.status = 'failed' then
    return jsonb_build_object('scheduleStatus', 'failed', 'applied', false);
  end if;

  update public.session_payment_schedules
  set status = case p_status
        when 'processing' then 'processing'
        when 'canceled' then 'failed'
        else 'requires_customer_action'
      end,
      stripe_payment_intent_id = trim(p_payment_intent_id),
      last_error_code = case p_status
        when 'requires_action' then 'customer_authentication_required'
        when 'requires_payment_method' then 'payment_method_declined'
        when 'canceled' then 'payment_intent_canceled'
        else null
      end,
      last_failed_at = case when p_status = 'processing' then last_failed_at else now() end,
      lease_owner = null, lease_expires_at = null,
      next_retry_at = null, updated_at = now()
  where id = v_schedule.id;

  if p_status in ('requires_action', 'requires_payment_method') then
    select patient.user_id into v_patient_user_id
    from public.patient_profiles patient
    where patient.id = v_booking.patient_profile_id;
    insert into public.notifications(profile_id, kind, title, body, href, event_key)
    values (
      v_patient_user_id,
      'session_payment_declined',
      'Confirme o pagamento',
      'Seu banco precisa de uma confirmação ou de outro cartão para manter o encontro.',
      '/app/encontros/' || v_booking.id::text,
      'session-charge-recovery:' || v_schedule.id::text
    ) on conflict (profile_id, event_key) where event_key is not null do nothing;
    perform public.enqueue_transactional_email_v1(
      'session_payment_declined',
      v_schedule.id,
      'session_payment',
      v_payment.id,
      v_patient_user_id,
      'profile:' || v_patient_user_id::text,
      '{}'::jsonb
    );
  end if;

  return jsonb_build_object(
    'scheduleStatus', (select status from public.session_payment_schedules where id = v_schedule.id),
    'applied', true
  );
end;
$$;


ALTER FUNCTION "public"."record_session_payment_intent_v10"("p_schedule_id" "uuid", "p_session_payment_id" "uuid", "p_booking_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_payment_intent_id" "text", "p_status" "text", "p_amount_cents" integer, "p_currency" "text", "p_stripe_customer_id" "text", "p_stripe_payment_method_id" "text", "p_stripe_charge_id" "text", "p_event_id" "text", "p_event_created_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_session_payment_stripe_reconciliation_v1"("p_session_payment_id" "uuid", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_charge_id" "text" DEFAULT NULL::"text", "p_stripe_balance_transaction_id" "text" DEFAULT NULL::"text", "p_stripe_fee_amount_cents" integer DEFAULT NULL::integer, "p_stripe_net_amount_cents" integer DEFAULT NULL::integer, "p_payment_method_type" "text" DEFAULT NULL::"text", "p_payment_origin" "text" DEFAULT 'stripe_checkout'::"text", "p_receipt_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
begin
  select *
    into v_payment
  from public.session_payments
  where id = p_session_payment_id
  for update;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'payment_not_found');
  end if;

  if v_payment.stripe_event_created_at is not null
    and p_stripe_event_created_at < v_payment.stripe_event_created_at then
    return jsonb_build_object('applied', false, 'reason', 'stale_event');
  end if;

  update public.session_payments
  set stripe_charge_id = coalesce(p_stripe_charge_id, stripe_charge_id),
      stripe_balance_transaction_id = coalesce(
        p_stripe_balance_transaction_id,
        stripe_balance_transaction_id
      ),
      stripe_fee_amount_cents = coalesce(
        p_stripe_fee_amount_cents,
        stripe_fee_amount_cents
      ),
      stripe_net_amount_cents = coalesce(
        p_stripe_net_amount_cents,
        stripe_net_amount_cents
      ),
      metadata = metadata || jsonb_strip_nulls(jsonb_build_object(
        'paymentMethodType', p_payment_method_type,
        'paymentOrigin', p_payment_origin,
        'receiptUrlAvailable', p_receipt_url is not null
      )),
      updated_at = now()
  where id = v_payment.id
  returning * into v_payment;

  if p_receipt_url is not null
    or v_payment.financial_status in (
      'paid',
      'partially_refunded',
      'refunded',
      'disputed'
    ) then
    insert into public.booking_payment_receipts (
      booking_id,
      amount_cents,
      currency,
      provider,
      receipt_url,
      paid_at
    ) values (
      v_payment.booking_id,
      v_payment.gross_amount_cents,
      v_payment.currency,
      'stripe',
      p_receipt_url,
      v_payment.paid_at
    )
    on conflict (booking_id) do update
    set amount_cents = excluded.amount_cents,
        currency = excluded.currency,
        provider = excluded.provider,
        receipt_url = coalesce(excluded.receipt_url, public.booking_payment_receipts.receipt_url),
        paid_at = coalesce(excluded.paid_at, public.booking_payment_receipts.paid_at),
        updated_at = now();
  end if;

  if p_stripe_balance_transaction_id is not null
    and p_stripe_fee_amount_cents is not null
    and p_stripe_fee_amount_cents > 0 then
    insert into public.financial_ledger_entries (
      entry_type,
      direction,
      amount_cents,
      patient_profile_id,
      therapist_profile_id,
      booking_id,
      session_payment_id,
      stripe_event_id,
      source_table,
      source_external_id,
      occurred_at
    ) values (
      'stripe_fee',
      'debit',
      p_stripe_fee_amount_cents,
      v_payment.patient_profile_id,
      v_payment.therapist_profile_id,
      v_payment.booking_id,
      v_payment.id,
      p_stripe_event_id,
      'stripe_balance_transactions',
      p_stripe_balance_transaction_id,
      p_stripe_event_created_at
    )
    on conflict (entry_type, source_table, source_external_id, direction)
    do nothing;
  end if;

  return jsonb_build_object(
    'applied', true,
    'sessionPaymentId', v_payment.id,
    'receiptRecorded', p_receipt_url is not null
  );
end;
$$;


ALTER FUNCTION "public"."record_session_payment_stripe_reconciliation_v1"("p_session_payment_id" "uuid", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_charge_id" "text", "p_stripe_balance_transaction_id" "text", "p_stripe_fee_amount_cents" integer, "p_stripe_net_amount_cents" integer, "p_payment_method_type" "text", "p_payment_origin" "text", "p_receipt_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_session_payment_stripe_reconciliation_v1"("p_session_payment_id" "uuid", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_charge_id" "text", "p_stripe_balance_transaction_id" "text", "p_stripe_fee_amount_cents" integer, "p_stripe_net_amount_cents" integer, "p_payment_method_type" "text", "p_payment_origin" "text", "p_receipt_url" "text") IS 'Registra comprovante e conciliacao de Charge/Balance Transaction para pagamento de sessao confirmado exclusivamente por webhook Stripe.';



CREATE OR REPLACE FUNCTION "public"."record_session_payment_stripe_reconciliation_v2"("p_session_payment_id" "uuid", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_charge_id" "text" DEFAULT NULL::"text", "p_stripe_balance_transaction_id" "text" DEFAULT NULL::"text", "p_stripe_fee_amount_cents" integer DEFAULT NULL::integer, "p_stripe_net_amount_cents" integer DEFAULT NULL::integer, "p_payment_method_type" "text" DEFAULT NULL::"text", "p_payment_origin" "text" DEFAULT 'stripe_checkout'::"text", "p_receipt_url" "text" DEFAULT NULL::"text", "p_balance_status" "text" DEFAULT NULL::"text", "p_balance_available_on" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_balance_currency" "text" DEFAULT NULL::"text", "p_balance_amount_cents" integer DEFAULT NULL::integer, "p_balance_source_charge_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_base jsonb;
  v_settlement_applied boolean := false;
begin
  select * into v_payment
  from public.session_payments
  where id = p_session_payment_id
  for update;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'payment_not_found');
  end if;

  if p_balance_status is not null then
    if p_balance_status not in ('pending', 'available')
      or nullif(trim(p_stripe_charge_id), '') is null
      or nullif(trim(p_stripe_balance_transaction_id), '') is null
      or p_balance_available_on is null
      or lower(coalesce(p_balance_currency, '')) <> lower(v_payment.currency)
      or p_balance_amount_cents <> v_payment.gross_amount_cents
      or p_balance_source_charge_id <> p_stripe_charge_id
      or (v_payment.stripe_charge_id is not null and v_payment.stripe_charge_id <> p_stripe_charge_id)
      or (v_payment.stripe_balance_transaction_id is not null
        and v_payment.stripe_balance_transaction_id <> p_stripe_balance_transaction_id)
    then
      raise exception 'STRIPE_BALANCE_TRANSACTION_MISMATCH' using errcode = '22023';
    end if;
  end if;

  v_base := public.record_session_payment_stripe_reconciliation_v1(
    p_session_payment_id,
    p_stripe_event_id,
    p_stripe_event_created_at,
    p_stripe_charge_id,
    p_stripe_balance_transaction_id,
    p_stripe_fee_amount_cents,
    p_stripe_net_amount_cents,
    p_payment_method_type,
    p_payment_origin,
    p_receipt_url
  );

  if p_balance_status is not null
    and (v_payment.stripe_balance_checked_at is null
      or p_stripe_event_created_at >= v_payment.stripe_balance_checked_at)
    and not (
      v_payment.stripe_balance_status = 'available'
      and p_balance_status = 'pending'
    ) then
    update public.session_payments
    set stripe_balance_status = p_balance_status,
        stripe_balance_available_on = p_balance_available_on,
        stripe_balance_checked_at = p_stripe_event_created_at,
        updated_at = now()
    where id = p_session_payment_id;
    v_settlement_applied := true;
    perform public.refresh_session_transfer_eligibility(
      p_session_payment_id,
      p_stripe_event_created_at
    );
  end if;

  return v_base || jsonb_build_object(
    'settlementRecorded', v_settlement_applied,
    'settlementStatus', p_balance_status
  );
end;
$$;


ALTER FUNCTION "public"."record_session_payment_stripe_reconciliation_v2"("p_session_payment_id" "uuid", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_stripe_charge_id" "text", "p_stripe_balance_transaction_id" "text", "p_stripe_fee_amount_cents" integer, "p_stripe_net_amount_cents" integer, "p_payment_method_type" "text", "p_payment_origin" "text", "p_receipt_url" "text", "p_balance_status" "text", "p_balance_available_on" timestamp with time zone, "p_balance_currency" "text", "p_balance_amount_cents" integer, "p_balance_source_charge_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_therapist_public_slug_change_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.slug is not distinct from new.slug then
    return new;
  end if;

  delete from public.therapist_profile_slug_history
  where old_slug = new.slug
    and therapist_profile_id = new.id;

  update public.therapist_profile_slug_history
  set current_slug = new.slug
  where therapist_profile_id = new.id;

  insert into public.therapist_profile_slug_history (
    therapist_profile_id,
    old_slug,
    current_slug
  ) values (
    new.id,
    old.slug,
    new.slug
  )
  on conflict (old_slug) do update
  set current_slug = excluded.current_slug
  where public.therapist_profile_slug_history.therapist_profile_id = excluded.therapist_profile_id;

  return new;
end;
$$;


ALTER FUNCTION "public"."record_therapist_public_slug_change_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_automatic_payout_batch_states_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_updated integer := 0;
begin
  with states as (
    select batch.id,
      count(item.id) filter (
        where item.status in ('failed', 'blocked')
          or transfer.status in ('failed', 'reconciliation_required', 'reversed')
      ) as failed_count,
      count(item.id) filter (
        where item.status <> 'transferred' or transfer.status <> 'transferred'
      ) as transfer_pending_count,
      count(item.id) filter (
        where item.status = 'transferred' and transfer.status = 'transferred'
          and not exists (
            select 1
            from public.stripe_payout_transfer_allocations allocation
            join public.stripe_payouts payout
              on payout.id = allocation.stripe_payout_id
            where allocation.stripe_transfer_id = transfer.id
              and payout.status = 'paid'
              and payout.provider_reconciliation_status = 'completed'
              and payout.allocation_status = 'completed'
          )
      ) as bank_pending_count,
      count(item.id) as item_count
    from public.payout_batches batch
    left join public.payout_batch_items item
      on item.payout_batch_id = batch.id and item.status <> 'removed'
    left join public.stripe_transfers transfer
      on transfer.payout_batch_item_id = item.id
    where batch.status in ('open', 'processing', 'partially_failed')
    group by batch.id
  )
  update public.payout_batches batch
  set status = case
        when states.failed_count > 0 then 'partially_failed'::public.payout_batch_status
        when states.item_count = 0 then 'completed'::public.payout_batch_status
        when states.transfer_pending_count = 0 and states.bank_pending_count = 0
          then 'completed'::public.payout_batch_status
        else 'processing'::public.payout_batch_status
      end,
      processed_at = case
        when states.item_count = 0
          or (states.failed_count = 0 and states.transfer_pending_count = 0 and states.bank_pending_count = 0)
          then coalesce(batch.processed_at, now())
        else null
      end,
      updated_at = now()
  from states
  where batch.id = states.id
    and (
      batch.status is distinct from case
        when states.failed_count > 0 then 'partially_failed'::public.payout_batch_status
        when states.item_count = 0 then 'completed'::public.payout_batch_status
        when states.transfer_pending_count = 0 and states.bank_pending_count = 0
          then 'completed'::public.payout_batch_status
        else 'processing'::public.payout_batch_status
      end
      or (
        (states.item_count = 0 or (states.failed_count = 0 and states.transfer_pending_count = 0 and states.bank_pending_count = 0))
        and batch.processed_at is null
      )
    );
  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."refresh_automatic_payout_batch_states_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_session_transfer_eligibility"("p_session_payment_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "public"."session_transfer_status"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
begin
  select payment.* into v_payment
  from public.session_payments payment
  where payment.id = p_session_payment_id
  for update;

  if not found then
    raise exception 'session_payment_not_found';
  end if;

  if v_payment.payment_flow_version = 'v10' then
    return v_payment.transfer_status;
  end if;

  return public.private_refresh_session_transfer_eligibility_v9_legacy(
    p_session_payment_id, p_now
  );
end;
$$;


