CREATE TABLE IF NOT EXISTS "public"."legal_acceptances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "actor_role" "text" NOT NULL,
    "document_version_id" "uuid" NOT NULL,
    "document_key" "text" NOT NULL,
    "document_version" "text" NOT NULL,
    "content_hash" "text" NOT NULL,
    "context" "text" NOT NULL,
    "booking_id" "uuid",
    "request_id" "uuid" NOT NULL,
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "accepted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revoked_at" timestamp with time zone,
    "superseded_at" timestamp with time zone,
    CONSTRAINT "legal_acceptances_actor_role" CHECK (("actor_role" = ANY (ARRAY['patient'::"text", 'therapist'::"text", 'admin'::"text"]))),
    CONSTRAINT "legal_acceptances_context" CHECK (("context" = ANY (ARRAY['patient_signup'::"text", 'therapist_signup'::"text", 'reservation_checkout'::"text", 'new_acceptance'::"text"]))),
    CONSTRAINT "legal_acceptances_document_key_not_blank" CHECK (("length"(TRIM(BOTH FROM "document_key")) > 0)),
    CONSTRAINT "legal_acceptances_hash_not_blank" CHECK (("length"(TRIM(BOTH FROM "content_hash")) > 0)),
    CONSTRAINT "legal_acceptances_version_not_blank" CHECK (("length"(TRIM(BOTH FROM "document_version")) > 0))
);


ALTER TABLE "public"."legal_acceptances" OWNER TO "postgres";


COMMENT ON TABLE "public"."legal_acceptances" IS 'Immutable evidence of user acceptance for a server-selected legal document version.';



CREATE OR REPLACE FUNCTION "public"."register_legal_acceptance_v1"("p_profile_id" "uuid", "p_actor_role" "text", "p_document_key" "text", "p_context" "text", "p_request_id" "uuid", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."legal_acceptances"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_document public.legal_document_versions%rowtype;
  v_acceptance public.legal_acceptances%rowtype;
begin
  if p_profile_id is null
    or p_request_id is null
    or length(trim(coalesce(p_document_key, ''))) = 0
  then
    raise exception 'invalid legal acceptance request'
      using errcode = '22023';
  end if;

  select *
    into v_document
  from public.legal_document_versions
  where document_key = p_document_key
    and status = 'published'
    and effective_at <= now()
  order by effective_at desc, published_at desc
  limit 1;

  if not found then
    raise exception 'published legal document not found: %', p_document_key
      using errcode = 'P0002';
  end if;

  insert into public.legal_acceptances (
    profile_id,
    actor_role,
    document_version_id,
    document_key,
    document_version,
    content_hash,
    context,
    booking_id,
    request_id,
    evidence
  )
  values (
    p_profile_id,
    p_actor_role,
    v_document.id,
    v_document.document_key,
    v_document.version,
    v_document.content_hash,
    p_context,
    p_booking_id,
    p_request_id,
    coalesce(p_evidence, '{}'::jsonb)
  )
  on conflict (profile_id, document_version_id, context, request_id)
  do update set revoked_at = public.legal_acceptances.revoked_at
  returning * into v_acceptance;

  return v_acceptance;
end;
$$;


ALTER FUNCTION "public"."register_legal_acceptance_v1"("p_profile_id" "uuid", "p_actor_role" "text", "p_document_key" "text", "p_context" "text", "p_request_id" "uuid", "p_booking_id" "uuid", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_session_payment_setup_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_stripe_customer_id" "text", "p_stripe_setup_intent_id" "text", "p_stripe_payment_method_id" "text", "p_status" "text", "p_consent_version" "text", "p_consented_at" timestamp with time zone, "p_failure_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_booking public.bookings%rowtype;
  v_setup public.session_payment_setups%rowtype;
begin
  if p_session_payment_id is null
    or p_booking_version is null
    or p_booking_version <= 0
    or p_stripe_environment not in ('test', 'live')
    or nullif(trim(p_stripe_customer_id), '') is null
    or nullif(trim(p_stripe_setup_intent_id), '') is null
    or p_status not in (
      'requires_setup', 'processing', 'requires_action', 'succeeded',
      'failed', 'canceled', 'superseded'
    )
    or nullif(trim(p_consent_version), '') is null
    or p_consented_at is null
    or (p_status = 'succeeded' and nullif(trim(p_stripe_payment_method_id), '') is null)
  then
    raise exception 'SESSION_PAYMENT_SETUP_V10_INVALID'
      using errcode = '22023';
  end if;

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.id = p_session_payment_id
  for update;

  if not found or v_payment.payment_flow_version <> 'v10' then
    raise exception 'SESSION_PAYMENT_V10_NOT_FOUND'
      using errcode = 'P0002';
  end if;

  select booking.*
  into v_booking
  from public.bookings as booking
  where booking.id = v_payment.booking_id;

  if not found or v_booking.version <> p_booking_version then
    raise exception 'SESSION_PAYMENT_BOOKING_VERSION_MISMATCH'
      using errcode = '23514';
  end if;

  select setup.*
  into v_setup
  from public.session_payment_setups as setup
  where setup.booking_id = v_payment.booking_id
    and setup.booking_version = p_booking_version
    and setup.superseded_at is null
    and setup.status not in ('canceled', 'superseded')
  for update;

  if found and (
    v_setup.stripe_environment <> p_stripe_environment
    or v_setup.stripe_setup_intent_id <> p_stripe_setup_intent_id
    or v_setup.stripe_customer_id <> p_stripe_customer_id
  ) then
    raise exception 'SESSION_PAYMENT_SETUP_V10_IDEMPOTENCY_CONFLICT'
      using errcode = '23505';
  end if;

  if found then
    update public.session_payment_setups
    set stripe_payment_method_id = coalesce(
          nullif(trim(p_stripe_payment_method_id), ''),
          stripe_payment_method_id
        ),
        status = p_status,
        failure_code = p_failure_code,
        updated_at = now()
    where id = v_setup.id
    returning * into v_setup;
  else
    insert into public.session_payment_setups (
      booking_id,
      booking_version,
      session_payment_id,
      stripe_environment,
      stripe_customer_id,
      stripe_setup_intent_id,
      stripe_payment_method_id,
      status,
      consent_version,
      consented_at,
      failure_code
    )
    values (
      v_payment.booking_id,
      p_booking_version,
      v_payment.id,
      p_stripe_environment,
      trim(p_stripe_customer_id),
      trim(p_stripe_setup_intent_id),
      nullif(trim(p_stripe_payment_method_id), ''),
      p_status,
      trim(p_consent_version),
      p_consented_at,
      p_failure_code
    )
    returning * into v_setup;
  end if;

  return jsonb_build_object(
    'setupId', v_setup.id,
    'bookingId', v_setup.booking_id,
    'bookingVersion', v_setup.booking_version,
    'status', v_setup.status
  );
end;
$$;


ALTER FUNCTION "public"."register_session_payment_setup_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_stripe_customer_id" "text", "p_stripe_setup_intent_id" "text", "p_stripe_payment_method_id" "text", "p_status" "text", "p_consent_version" "text", "p_consented_at" timestamp with time zone, "p_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_new_duplicate_therapist_cpf_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.document_type <> 'cpf' then
    return new;
  end if;

  -- Existing duplicate holders may still update unrelated private fields.
  if tg_op = 'UPDATE'
    and old.document_type = 'cpf'
    and new.document_number = old.document_number
  then
    return new;
  end if;

  -- Serialize checks for the same normalized CPF to close concurrent writes.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes-therapist-private-cpf:' || new.document_number,
      0
    )
  );

  if exists (
    select 1
    from public.therapist_private_identity as existing
    where existing.document_type = 'cpf'
      and existing.document_number = new.document_number
      and existing.id is distinct from new.id
  ) then
    raise exception 'CPF_ALREADY_IN_USE' using errcode = '23505';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."reject_new_duplicate_therapist_cpf_v1"() OWNER TO "postgres";


