    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_updated integer;
begin
  update public.auth_action_tokens
  set
    claimed_at = null,
    claim_id = null,
    claim_expires_at = null
  where id = p_token_id
    and claim_id = p_claim_id
    and consumed_at is null
