CREATE OR REPLACE FUNCTION "public"."release_booking_after_full_refund_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_request_id text;
begin
  if new.financial_status <> 'refunded' then
    return new;
  end if;

  select *
    into v_booking
  from public.bookings
  where id = new.booking_id
  for update;

  if not found
    or v_booking.status not in (
      'pending_payment',
      'confirmed',
      'completed',
      'cancelled_by_patient',
      'cancelled_by_therapist',
      'no_show_patient',
      'no_show_therapist'
    ) then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_booking.therapist_profile_id::text, 0)
  );

  v_request_id := left(
    coalesce(
      nullif(trim(new.stripe_event_id), ''),
      'payment-refund:' || new.id::text
    ),
    200
  );

  perform pg_catalog.set_config(
    'tes.booking_reason',
    'session_payment_refunded',
    true
  );
  perform pg_catalog.set_config(
    'tes.booking_source',
    'payment_state',
    true
  );
  perform pg_catalog.set_config(
    'tes.booking_request_id',
    v_request_id,
    true
  );

  update public.bookings
  set status = 'refunded',
      updated_at = now()
  where id = v_booking.id;

  perform public.sync_booking_video_session_from_agenda_v1(
    v_booking.id,
    'cancel',
    v_request_id
  );

  perform pg_catalog.set_config('tes.booking_reason', '', true);
  perform pg_catalog.set_config('tes.booking_source', '', true);
  perform pg_catalog.set_config('tes.booking_request_id', '', true);

  return new;
end;
$$;


ALTER FUNCTION "public"."release_booking_after_full_refund_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_booking_after_full_refund_v1"() IS 'Moves a booking to refunded after the canonical session payment is fully refunded, releasing availability while preserving audit history.';



CREATE OR REPLACE FUNCTION "public"."release_booking_after_payment_failure_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_reason text;
begin
  if new.financial_status not in ('failed', 'canceled')
    or old.financial_status is not distinct from new.financial_status then
    return new;
  end if;

  select *
    into v_booking
  from public.bookings
  where id = new.booking_id
  for update;

  if not found
    or v_booking.status not in ('draft', 'pending_payment')
    or v_booking.payment_status = 'paid' then
    return new;
  end if;

  v_reason := case new.financial_status
    when 'canceled' then 'stripe_checkout_not_completed'
    else 'stripe_payment_failed'
  end;

  perform pg_catalog.set_config('tes.booking_reason', v_reason, true);
  perform pg_catalog.set_config('tes.booking_source', 'payment_state', true);
  perform pg_catalog.set_config('tes.booking_request_id', coalesce(new.stripe_event_id, ''), true);

  update public.bookings
  set status = 'cancelled_by_payment',
      cancellation_reason = v_reason,
      cancelled_at = coalesce(cancelled_at, now()),
      updated_at = now()
  where id = v_booking.id;

  perform pg_catalog.set_config('tes.booking_reason', '', true);
  perform pg_catalog.set_config('tes.booking_source', '', true);
  perform pg_catalog.set_config('tes.booking_request_id', '', true);

  return new;
end;
$$;


ALTER FUNCTION "public"."release_booking_after_payment_failure_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_booking_after_payment_failure_v1"() IS 'Atomically closes an unpaid booking after a definitive Stripe failure/cancellation; retries are no-ops.';



CREATE OR REPLACE FUNCTION "public"."release_expired_payout_leases_v1"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfers integer := 0;
begin
  if p_limit < 1 or p_limit > 200 then
    raise exception 'PAYOUT_LEASE_LIMIT_INVALID';
  end if;
  with expired as (
    select id from public.stripe_transfers
    where status = 'pending' and lease_expires_at <= now()
    order by lease_expires_at
    limit p_limit
    for update skip locked
  )
  update public.stripe_transfers transfer
  set status = 'reconciliation_required', next_retry_at = now(),
      lease_owner = null, lease_expires_at = null,
      failure_code = 'provider_response_unknown',
      failure_message = 'Lease expirou antes da confirmacao da operacao.',
      updated_at = now()
  from expired where transfer.id = expired.id;
  get diagnostics v_transfers = row_count;
  return jsonb_build_object('transfers', v_transfers, 'payouts', 0);
end;
$$;


ALTER FUNCTION "public"."release_expired_payout_leases_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_therapist_services_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_service_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_payload_hash text := encode(
    extensions.digest(array_to_string(p_service_ids, ',')::text, 'sha256'),
    'hex'
  );
  v_service_id uuid;
  v_position integer := 0;
  v_response jsonb;
begin
  v_therapist := public.get_therapist_for_service_actor_v1(p_actor_user_id);
  v_response := public.get_therapist_service_request_replay_v1(
    v_therapist.id,
    p_request_id,
    'reorder',
    v_payload_hash
  );

  if v_response is not null then
    return v_response;
  end if;

  if coalesce(array_length(p_service_ids, 1), 0) = 0
    or array_length(p_service_ids, 1) > 100 then
    raise exception 'THERAPIST_SERVICE_INVALID_ORDER' using errcode = 'P0001';
  end if;

  if (
    select count(distinct item)
    from unnest(p_service_ids) as item
  ) <> array_length(p_service_ids, 1) then
    raise exception 'THERAPIST_SERVICE_INVALID_ORDER' using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from unnest(p_service_ids) as item
    left join public.therapist_services as service
      on service.id = item
      and service.therapist_profile_id = v_therapist.id
    where service.id is null
  ) then
    raise exception 'THERAPIST_SERVICE_NOT_FOUND' using errcode = 'P0002';
  end if;

  foreach v_service_id in array p_service_ids loop
    v_position := v_position + 10;

    update public.therapist_services
    set position = v_position,
        updated_at = now()
    where id = v_service_id;
  end loop;

  insert into public.therapist_service_events (
    therapist_profile_id,
    actor_user_id,
    event_type,
    request_id,
    metadata
  )
  values (
    v_therapist.id,
    p_actor_user_id,
    'services_reordered',
    p_request_id,
    jsonb_build_object('serviceIds', to_jsonb(p_service_ids))
  );

  v_response := public.list_private_therapist_services_v1(p_actor_user_id)
    || jsonb_build_object('idempotentReplay', false);

  return public.store_therapist_service_request_v1(
    v_therapist.id,
    p_request_id,
    'reorder',
    v_payload_hash,
    null,
    v_response
  );
end;
$$;


ALTER FUNCTION "public"."reorder_therapist_services_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_service_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_therapist_service_matching_v1"("p_actor_user_id" "uuid", "p_service_id" "uuid", "p_theme_ids" "uuid"[], "p_interest_ids" "uuid"[], "p_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_service public.therapist_services%rowtype;
  v_previous jsonb;
  v_next jsonb;
begin
  v_therapist := public.get_therapist_for_service_actor_v1(p_actor_user_id);

  select *
    into v_service
  from public.therapist_services
  where id = p_service_id
    and therapist_profile_id = v_therapist.id
  for update;

  if not found then
    raise exception 'THERAPIST_SERVICE_NOT_FOUND' using errcode = 'P0002';
  end if;

  select jsonb_build_object(
    'themeIds', coalesce(jsonb_agg(distinct service_theme.theme_id) filter (where service_theme.theme_id is not null), '[]'::jsonb),
    'interestIds', coalesce(jsonb_agg(distinct service_interest.interest_id) filter (where service_interest.interest_id is not null), '[]'::jsonb)
  )
    into v_previous
  from public.therapist_services as service
  left join public.therapist_service_matching_themes as service_theme
    on service_theme.therapist_service_id = service.id
  left join public.therapist_service_matching_interests as service_interest
    on service_interest.therapist_service_id = service.id
  where service.id = p_service_id;

  delete from public.therapist_service_matching_interests
  where therapist_service_id = p_service_id;
  delete from public.therapist_service_matching_themes
  where therapist_service_id = p_service_id;

  insert into public.therapist_service_matching_themes (
    therapist_service_id,
    theme_id
  )
  select p_service_id, theme_id
  from unnest(coalesce(p_theme_ids, '{}'::uuid[])) as theme_id;

  insert into public.therapist_service_matching_interests (
    therapist_service_id,
    interest_id
  )
  select p_service_id, interest_id
  from unnest(coalesce(p_interest_ids, '{}'::uuid[])) as interest_id;

  perform public.ensure_service_matching_rules_v1(p_service_id);

  select jsonb_build_object(
    'themeIds', coalesce(jsonb_agg(distinct service_theme.theme_id) filter (where service_theme.theme_id is not null), '[]'::jsonb),
    'interestIds', coalesce(jsonb_agg(distinct service_interest.interest_id) filter (where service_interest.interest_id is not null), '[]'::jsonb)
  )
    into v_next
  from public.therapist_services as service
  left join public.therapist_service_matching_themes as service_theme
    on service_theme.therapist_service_id = service.id
  left join public.therapist_service_matching_interests as service_interest
    on service_interest.therapist_service_id = service.id
  where service.id = p_service_id;

  insert into public.therapist_service_events (
    therapist_profile_id,
    service_id,
    actor_user_id,
    event_type,
    request_id,
    previous_version,
    resulting_version,
    metadata
  )
  values (
    v_therapist.id,
    p_service_id,
    p_actor_user_id,
    'service_updated',
    p_request_id,
    v_service.version,
    v_service.version,
    jsonb_build_object(
      'matchingPrevious', coalesce(v_previous, '{}'::jsonb),
      'matchingNext', coalesce(v_next, '{}'::jsonb)
    )
  );
end;
$$;


ALTER FUNCTION "public"."replace_therapist_service_matching_v1"("p_actor_user_id" "uuid", "p_service_id" "uuid", "p_theme_ids" "uuid"[], "p_interest_ids" "uuid"[], "p_request_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."booking_reschedule_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "requested_by_profile_id" "uuid",
    "proposed_starts_at" timestamp with time zone NOT NULL,
    "proposed_ends_at" timestamp with time zone NOT NULL,
    "reason" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "resolved_by_profile_id" "uuid",
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "original_starts_at" timestamp with time zone NOT NULL,
    "original_ends_at" timestamp with time zone NOT NULL,
    "original_timezone" "text" NOT NULL,
    "proposed_timezone" "text" NOT NULL,
    "request_id" "text",
    "resolution_request_id" "text",
    "booking_version_at_request" integer NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "applied_at" timestamp with time zone,
    CONSTRAINT "booking_reschedule_requests_original_range" CHECK (("original_starts_at" < "original_ends_at")),
    CONSTRAINT "booking_reschedule_requests_range" CHECK (("proposed_starts_at" < "proposed_ends_at")),
    CONSTRAINT "booking_reschedule_requests_status" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'rejected'::"text", 'cancelled'::"text", 'expired'::"text", 'applied'::"text"]))),
    CONSTRAINT "booking_reschedule_requests_version_positive" CHECK (("booking_version_at_request" > 0))
);


ALTER TABLE "public"."booking_reschedule_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_booking_reschedule_v1"("p_booking_id" "uuid", "p_requested_by_profile_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_proposed_ends_at" timestamp with time zone, "p_proposed_timezone" "text", "p_reason" "text", "p_request_id" "text", "p_expires_in_seconds" integer DEFAULT 172800, "p_expected_booking_version" integer DEFAULT NULL::integer) RETURNS "public"."booking_reschedule_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_existing public.booking_reschedule_requests%rowtype;
  v_request public.booking_reschedule_requests%rowtype;
begin
  if length(trim(coalesce(p_request_id, ''))) not between 8 and 200 then
    raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode = '22023';
  end if;

  if p_expires_in_seconds not between 300 and 604800 then
    raise exception 'INVALID_RESCHEDULE_EXPIRY' using errcode = '22023';
  end if;

  if p_proposed_starts_at is null
    or p_proposed_ends_at is null
    or p_proposed_starts_at >= p_proposed_ends_at
    or p_proposed_starts_at <= now() then
    raise exception 'INVALID_AVAILABILITY_RANGE' using errcode = '22023';
  end if;

  if not public.is_valid_timezone_v1(p_proposed_timezone) then
    raise exception 'INVALID_TIMEZONE' using errcode = '22023';
  end if;

  select *
    into v_existing
  from public.booking_reschedule_requests
  where request_id = trim(p_request_id)
  for update;

  if found then
    if v_existing.booking_id <> p_booking_id
      or v_existing.requested_by_profile_id <> p_requested_by_profile_id
      or v_existing.proposed_starts_at <> p_proposed_starts_at
      or v_existing.proposed_ends_at <> p_proposed_ends_at
      or v_existing.proposed_timezone <> p_proposed_timezone then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;

    return v_existing;
  end if;

  select *
    into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND' using errcode = 'P0002';
  end if;

  if not public.is_booking_participant_profile_v1(
    v_booking.id,
    p_requested_by_profile_id
  ) then
    raise exception 'BOOKING_ACTOR_FORBIDDEN' using errcode = '42501';
  end if;

  if v_booking.status <> 'confirmed' then
    raise exception 'BOOKING_CANNOT_BE_RESCHEDULED' using errcode = 'P0001';
  end if;

  if p_expected_booking_version is not null
    and p_expected_booking_version <> v_booking.version then
    raise exception 'BOOKING_VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  if p_proposed_ends_at <> (
    p_proposed_starts_at
    + v_booking.service_duration_minutes_snapshot * interval '1 minute'
  ) then
    raise exception 'INVALID_AVAILABILITY_RANGE' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_booking.therapist_profile_id::text, 0)
  );
  perform public.expire_booking_holds_v1(
    now(),
    v_booking.therapist_profile_id
  );

  if exists (
    select 1
    from public.bookings as conflict
    where conflict.therapist_profile_id = v_booking.therapist_profile_id
      and conflict.id <> v_booking.id
      and conflict.status in ('draft', 'pending_payment', 'confirmed')
      and conflict.occupied_during && pg_catalog.tstzrange(
        p_proposed_starts_at
          - v_booking.buffer_before_minutes_snapshot * interval '1 minute',
        p_proposed_ends_at
          + v_booking.buffer_after_minutes_snapshot * interval '1 minute',
        '[)'
      )
  ) then
    raise exception 'BOOKING_CONFLICT' using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from public.booking_holds as hold
    where hold.therapist_profile_id = v_booking.therapist_profile_id
      and hold.status = 'active'
      and hold.expires_at > now()
      and hold.occupied_during && pg_catalog.tstzrange(
        p_proposed_starts_at
          - v_booking.buffer_before_minutes_snapshot * interval '1 minute',
        p_proposed_ends_at
          + v_booking.buffer_after_minutes_snapshot * interval '1 minute',
        '[)'
      )
  ) then
    raise exception 'SLOT_HELD_BY_ANOTHER_USER' using errcode = 'P0001';
  end if;

  begin
    insert into public.booking_reschedule_requests (
      booking_id,
      requested_by_profile_id,
      original_starts_at,
      original_ends_at,
      original_timezone,
      proposed_starts_at,
      proposed_ends_at,
      proposed_timezone,
      reason,
      status,
      request_id,
      booking_version_at_request,
      expires_at
    ) values (
      v_booking.id,
      p_requested_by_profile_id,
      v_booking.starts_at,
      v_booking.ends_at,
      v_booking.timezone,
      p_proposed_starts_at,
      p_proposed_ends_at,
      p_proposed_timezone,
      nullif(left(trim(coalesce(p_reason, '')), 500), ''),
      'pending',
      trim(p_request_id),
      v_booking.version,
      now() + pg_catalog.make_interval(secs => p_expires_in_seconds)
    )
    returning * into v_request;
  exception
    when unique_violation then
      raise exception 'BOOKING_RESCHEDULE_ALREADY_PENDING'
        using errcode = 'P0001';
  end;

  insert into public.booking_events (
    booking_id,
    actor_profile_id,
    event_type,
    request_id,
    source,
    previous_status,
    next_status,
    payload
  ) values (
    v_booking.id,
    p_requested_by_profile_id,
    'booking_reschedule_requested',
    trim(p_request_id),
    'agenda_a2',
    v_booking.status,
    v_booking.status,
    pg_catalog.jsonb_strip_nulls(
      pg_catalog.jsonb_build_object(
        'rescheduleRequestId', v_request.id,
        'proposedStartsAt', v_request.proposed_starts_at,
        'proposedEndsAt', v_request.proposed_ends_at,
        'proposedTimezone', v_request.proposed_timezone,
        'reason', v_request.reason,
        'expiresAt', v_request.expires_at
      )
    )
  )
  on conflict do nothing;

  return v_request;
end;
$$;


ALTER FUNCTION "public"."request_booking_reschedule_v1"("p_booking_id" "uuid", "p_requested_by_profile_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_proposed_ends_at" timestamp with time zone, "p_proposed_timezone" "text", "p_reason" "text", "p_request_id" "text", "p_expires_in_seconds" integer, "p_expected_booking_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reschedule_uncharged_session_v10"("p_booking_id" "uuid", "p_patient_user_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_proposed_ends_at" timestamp with time zone, "p_proposed_timezone" "text", "p_reason" "text", "p_request_id" "text", "p_expected_booking_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_existing public.booking_reschedule_requests%rowtype;
  v_payment public.session_payments%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
  v_setup public.session_payment_setups%rowtype;
  v_result jsonb;
  v_due_at timestamptz;
  v_idempotency_key text;
  v_fingerprint text;
  v_new_schedule_id uuid;
begin
  if p_booking_id is null or p_patient_user_id is null
    or p_proposed_starts_at is null or p_proposed_ends_at is null
    or p_proposed_starts_at >= p_proposed_ends_at
    or p_proposed_starts_at <= now()
    or length(trim(coalesce(p_request_id, ''))) not between 8 and 200
  then
    raise exception 'SESSION_PRECHARGE_RESCHEDULE_V10_INVALID'
      using errcode = '22023';
  end if;

  -- Keep the same lock order as payment recording and cancellation.
  select payment.* into v_payment
  from public.session_payments payment
  where payment.booking_id = p_booking_id
  for update;
  select booking.* into v_booking
  from public.bookings booking
  join public.patient_profiles patient on patient.id = booking.patient_profile_id
  where booking.id = p_booking_id and patient.user_id = p_patient_user_id
  for update of booking;
  if not found then
    raise exception 'SESSION_PRECHARGE_RESCHEDULE_V10_FORBIDDEN'
      using errcode = '42501';
  end if;
  if v_payment.id is null or v_payment.payment_flow_version <> 'v10' then
    raise exception 'SESSION_PRECHARGE_RESCHEDULE_V10_NOT_FOUND'
      using errcode = '23514';
  end if;

  select request.* into v_existing
  from public.booking_reschedule_requests request
  where request.request_id = trim(p_request_id)
  for update;
  if found then
    if v_existing.booking_id <> v_booking.id
      or v_existing.requested_by_profile_id <> p_patient_user_id
      or v_existing.proposed_starts_at <> p_proposed_starts_at
      or v_existing.proposed_ends_at <> p_proposed_ends_at
      or v_existing.proposed_timezone <> p_proposed_timezone
      or v_existing.status <> 'applied'
    then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;

    select schedule.* into v_schedule
    from public.session_payment_schedules schedule
    where schedule.session_payment_id = v_payment.id
      and schedule.status = 'scheduled'
      and schedule.idempotency_key = 'tes:v10:session-charge:reschedule:' || trim(p_request_id)
    limit 1;
    if not found then
      raise exception 'SESSION_PRECHARGE_RESCHEDULE_V10_REQUIRES_SUPPORT'
        using errcode = '23514';
    end if;
    return jsonb_build_object(
      'applied', false,
      'bookingId', v_booking.id,
      'bookingVersion', v_booking.version,
      'chargeTiming', case when v_schedule.due_at <= now() then 'immediate' else 'scheduled' end,
      'paymentDueAt', v_schedule.due_at,
      'rescheduleRequestId', v_existing.id,
      'scheduleId', v_schedule.id,
      'status', 'applied'
    );
  end if;

  select schedule.* into v_schedule
  from public.session_payment_schedules schedule
  where schedule.session_payment_id = v_payment.id
    and schedule.status not in ('paid', 'failed', 'canceled', 'superseded')
  order by schedule.created_at desc
  limit 1 for update;
  select setup.* into v_setup
  from public.session_payment_setups setup
  where setup.id = v_schedule.session_payment_setup_id;

  if v_booking.status <> 'confirmed'
    or v_booking.starts_at <= now() + interval '24 hours'
    or (p_expected_booking_version is not null
      and p_expected_booking_version <> v_booking.version)
    or p_proposed_timezone <> v_booking.timezone
    or p_proposed_ends_at <> p_proposed_starts_at
      + v_booking.service_duration_minutes_snapshot * interval '1 minute'
    or v_payment.financial_status <> 'pending'
    or v_payment.stripe_payment_intent_id is not null
    or v_payment.stripe_charge_id is not null
    or v_payment.paid_at is not null
    or v_schedule.id is null
    or v_schedule.status <> 'scheduled'
    or v_schedule.attempt_count <> 0
    or v_schedule.stripe_payment_intent_id is not null
    or v_schedule.stripe_charge_id is not null
    or v_schedule.lease_owner is not null
    or v_schedule.expected_booking_version <> v_booking.version
    or v_setup.id is null
    or v_setup.status <> 'succeeded'
    or v_setup.superseded_at is not null
    or v_setup.booking_version <> v_schedule.booking_version
    or exists (select 1 from public.session_transfer_jobs job
      where job.session_payment_id = v_payment.id)
    or exists (select 1 from public.stripe_transfers transfer
      where transfer.session_payment_id = v_payment.id)
  then
    raise exception 'SESSION_PRECHARGE_RESCHEDULE_V10_REQUIRES_SUPPORT'
      using errcode = '23514';
  end if;

  v_result := public.apply_patient_booking_reschedule_v1(
    v_booking.id,
    p_patient_user_id,
    p_proposed_starts_at,
    p_proposed_ends_at,
    p_proposed_timezone,
    p_reason,
    trim(p_request_id),
    v_booking.version
  );

  select booking.* into v_booking
  from public.bookings booking where booking.id = p_booking_id;
  v_due_at := v_booking.starts_at - interval '24 hours';

  update public.session_payment_schedules
  set status = 'superseded', lease_owner = null, lease_expires_at = null,
      updated_at = now()
  where id = v_schedule.id;

  perform pg_catalog.set_config(
    'tes.v10_reschedule_payment_id', v_payment.id::text, true
  );
  update public.session_payments
  set payment_due_at = v_due_at, updated_at = now()
  where id = v_payment.id;
  perform pg_catalog.set_config('tes.v10_reschedule_payment_id', '', true);

  v_idempotency_key := 'tes:v10:session-charge:reschedule:' || trim(p_request_id);
  v_fingerprint := encode(extensions.digest(concat_ws(':',
    v_schedule.stripe_environment,
    v_payment.id::text,
    v_setup.id::text,
    v_setup.stripe_payment_method_id,
    v_due_at::text,
    v_payment.gross_amount_cents::text,
    v_payment.currency::text,
    v_booking.version::text
  ), 'sha256'), 'hex');

  insert into public.session_payment_schedules (
    booking_id, booking_version, expected_booking_version,
    session_payment_id, session_payment_setup_id, stripe_environment,
    due_at, idempotency_key, request_fingerprint
  ) values (
    v_booking.id, v_setup.booking_version, v_booking.version,
    v_payment.id, v_setup.id, v_schedule.stripe_environment,
    v_due_at, v_idempotency_key, v_fingerprint
  ) returning id into v_new_schedule_id;

  return v_result || jsonb_build_object(
    'applied', true,
    'chargeTiming', case when v_due_at <= now() then 'immediate' else 'scheduled' end,
    'paymentDueAt', v_due_at,
    'scheduleId', v_new_schedule_id
  );
end;
$$;


ALTER FUNCTION "public"."reschedule_uncharged_session_v10"("p_booking_id" "uuid", "p_patient_user_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_proposed_ends_at" timestamp with time zone, "p_proposed_timezone" "text", "p_reason" "text", "p_request_id" "text", "p_expected_booking_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_booking_hold_v1"("p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_idempotency_key" "text", "p_ttl_seconds" integer DEFAULT 600) RETURNS "public"."booking_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.is_public_service_booking_eligible_v1(p_service_id) then
    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;
  return public.reserve_booking_hold_v1_internal(
    p_patient_profile_id, p_service_id, p_starts_at, p_ends_at, p_timezone, p_idempotency_key, p_ttl_seconds
  );
end;
$$;


ALTER FUNCTION "public"."reserve_booking_hold_v1"("p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_idempotency_key" "text", "p_ttl_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reserve_booking_hold_v1"("p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_idempotency_key" "text", "p_ttl_seconds" integer) IS 'Transactional booking hold command. Edge Functions using service_role only; browser clients must use session-booking-checkout.';



CREATE OR REPLACE FUNCTION "public"."reserve_booking_hold_v1_internal"("p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_idempotency_key" "text", "p_ttl_seconds" integer DEFAULT 600) RETURNS "public"."booking_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_buffer_after integer;
  v_buffer_before integer;
  v_hold public.booking_holds%rowtype;
  v_max_days_ahead integer;
  v_min_notice_minutes integer;
  v_service public.therapist_services%rowtype;
  v_therapist public.therapist_profiles%rowtype;
begin
  if p_patient_profile_id is null
    or not exists (
      select 1
      from public.patient_profiles
      where id = p_patient_profile_id
    ) then
    raise exception 'PATIENT_NOT_FOUND' using errcode = 'P0002';
  end if;

  if length(trim(coalesce(p_idempotency_key, ''))) not between 8 and 200 then
    raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode = '22023';
  end if;

  if p_ttl_seconds not between 60 and 900 then
    raise exception 'INVALID_HOLD_TTL' using errcode = '22023';
  end if;

  if p_starts_at is null
    or p_ends_at is null
    or p_starts_at >= p_ends_at then
    raise exception 'INVALID_AVAILABILITY_RANGE' using errcode = '22023';
  end if;

  if not public.is_valid_timezone_v1(p_timezone) then
    raise exception 'INVALID_TIMEZONE' using errcode = '22023';
  end if;

  select *
    into v_hold
  from public.booking_holds
  where idempotency_key = trim(p_idempotency_key)
  for update;

  if found then
    if v_hold.patient_profile_id <> p_patient_profile_id
      or v_hold.service_id <> p_service_id
      or v_hold.starts_at <> p_starts_at
      or v_hold.ends_at <> p_ends_at
      or v_hold.timezone <> p_timezone then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;

    return v_hold;
  end if;

  select *
    into v_service
  from public.therapist_services
  where id = p_service_id;

  if not found then
    raise exception 'SERVICE_NOT_FOUND' using errcode = 'P0002';
  end if;

  select *
    into v_therapist
  from public.therapist_profiles
  where id = v_service.therapist_profile_id;

  if v_service.status <> 'active'
    or v_therapist.status <> 'approved'
    or not v_therapist.is_accepting_bookings then
    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;

  select
    coalesce(settings.buffer_before_minutes, 0),
    coalesce(settings.buffer_after_minutes, 0),
    coalesce(settings.min_notice_minutes, 120),
    coalesce(settings.max_days_ahead, 30)
  into
    v_buffer_before,
    v_buffer_after,
    v_min_notice_minutes,
    v_max_days_ahead
  from (select 1) as anchor
  left join public.therapist_service_booking_settings as settings
    on settings.service_id = v_service.id;

  if p_ends_at <> (
    p_starts_at
    + v_service.duration_minutes * interval '1 minute'
  ) then
    raise exception 'INVALID_AVAILABILITY_RANGE' using errcode = '22023';
  end if;

  if p_starts_at < now() + v_min_notice_minutes * interval '1 minute'
    or p_starts_at > now() + v_max_days_ahead * interval '1 day' then
    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_service.therapist_profile_id::text, 0)
  );
  perform public.expire_booking_holds_v1(
    now(),
    v_service.therapist_profile_id
  );

  begin
    insert into public.booking_holds (
      patient_profile_id,
      therapist_profile_id,
      service_id,
      starts_at,
      ends_at,
      timezone,
      status,
      idempotency_key,
      expires_at,
      service_title_snapshot,
      service_duration_minutes_snapshot,
      service_price_cents_snapshot,
      currency_snapshot,
      buffer_before_minutes_snapshot,
      buffer_after_minutes_snapshot,
      snapshot_captured_at
    ) values (
      p_patient_profile_id,
      v_service.therapist_profile_id,
      v_service.id,
      p_starts_at,
      p_ends_at,
      p_timezone,
      'active',
      trim(p_idempotency_key),
      now() + pg_catalog.make_interval(secs => p_ttl_seconds),
      v_service.title,
      v_service.duration_minutes,
      v_service.price_cents,
      upper(v_service.currency),
      v_buffer_before,
      v_buffer_after,
      now()
    )
    returning * into v_hold;
  exception
    when exclusion_violation then
      raise exception 'SLOT_HELD_BY_ANOTHER_USER' using errcode = 'P0001';
    when unique_violation then
      select *
        into v_hold
      from public.booking_holds
      where idempotency_key = trim(p_idempotency_key);

      if not found
        or v_hold.patient_profile_id <> p_patient_profile_id
        or v_hold.service_id <> p_service_id
        or v_hold.starts_at <> p_starts_at
        or v_hold.ends_at <> p_ends_at
        or v_hold.timezone <> p_timezone then
        raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
      end if;
  end;

  return v_hold;
end;
$$;


ALTER FUNCTION "public"."reserve_booking_hold_v1_internal"("p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_idempotency_key" "text", "p_ttl_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reserve_booking_hold_v1_internal"("p_patient_profile_id" "uuid", "p_service_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_idempotency_key" "text", "p_ttl_seconds" integer) IS 'Atomically reserves a therapist interval with TTL, snapshots, idempotency, and cross-service conflict protection.';



CREATE OR REPLACE FUNCTION "public"."reserve_stripe_webhook_event_v1"("p_stripe_event_id" "text", "p_event_type" "text", "p_account_id" "text", "p_livemode" boolean, "p_api_version" "text", "p_source" "text", "p_payload_sha256" "text", "p_event_created_at" timestamp with time zone, "p_object_id" "text") RETURNS TABLE("processing_status" "public"."stripe_webhook_processing_status", "acquired" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.stripe_webhook_events%rowtype;
begin
  insert into public.stripe_webhook_events (
    stripe_event_id,
    event_type,
    account_id,
    livemode,
    api_version,
    source,
    processing_status,
    attempts,
    payload_sha256,
    stripe_event_created_at,
    object_id,
    processing_started_at,
    updated_at
  ) values (
    p_stripe_event_id,
    p_event_type,
    p_account_id,
    p_livemode,
    p_api_version,
    p_source,
    'processing',
    1,
    p_payload_sha256,
    p_event_created_at,
    p_object_id,
    now(),
    now()
  )
  on conflict (stripe_event_id) do nothing
  returning * into v_event;

  if v_event.id is not null then
    return query select v_event.processing_status, true;
    return;
  end if;

  select *
    into v_event
  from public.stripe_webhook_events
  where stripe_event_id = p_stripe_event_id
  for update;

  if v_event.processing_status in ('processed', 'ignored')
    or (
      v_event.processing_status = 'processing'
      and v_event.processing_started_at > now() - interval '5 minutes'
    ) then
    return query select v_event.processing_status, false;
    return;
  end if;

  update public.stripe_webhook_events
  set processing_status = 'processing',
      processing_started_at = now(),
      processed_at = null,
      attempts = attempts + 1,
      error_code = null,
      error_message = null,
      updated_at = now()
  where id = v_event.id
  returning * into v_event;

  return query select v_event.processing_status, true;
end;
$$;


ALTER FUNCTION "public"."reserve_stripe_webhook_event_v1"("p_stripe_event_id" "text", "p_event_type" "text", "p_account_id" "text", "p_livemode" boolean, "p_api_version" "text", "p_source" "text", "p_payload_sha256" "text", "p_event_created_at" timestamp with time zone, "p_object_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reserve_stripe_webhook_event_v1"("p_stripe_event_id" "text", "p_event_type" "text", "p_account_id" "text", "p_livemode" boolean, "p_api_version" "text", "p_source" "text", "p_payload_sha256" "text", "p_event_created_at" timestamp with time zone, "p_object_id" "text") IS 'Reserva atomica e reprocessavel de evento Stripe, com lease de cinco minutos.';



CREATE OR REPLACE FUNCTION "public"."reserve_video_session_control_jobs_v1"("p_environment" "text", "p_limit" integer DEFAULT 10, "p_lock_seconds" integer DEFAULT 60) RETURNS TABLE("id" "uuid", "video_session_id" "uuid", "booking_id" "uuid", "provider_session_id" "text", "operation" "public"."video_session_control_operation", "attempts" integer, "max_attempts" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with candidates as (
    select job.id
    from public.video_session_control_jobs job
    join public.video_sessions session on session.id = job.video_session_id
    join public.bookings booking on booking.id = job.booking_id
    where job.environment = p_environment
      and job.status in ('queued', 'retry')
      and job.next_run_at <= now()
      and coalesce(job.locked_until_at, '-infinity'::timestamptz) <= now()
      and job.attempts < job.max_attempts
      and session.termination_confirmed_at is null
      and session.status not in ('ended', 'canceled')
      and (
        job.operation <> 'end_patient_no_show'
        or pg_catalog.pg_try_advisory_xact_lock(
          pg_catalog.hashtextextended(booking.id::text, 0)
        )
      )
      and (
        (job.operation = 'end_scheduled' and session.scheduled_ends_at <= now())
        or (
          job.operation = 'end_hard_timeout'
          and session.hard_ends_at is not null
          and session.hard_ends_at <= now()
        )
        or (
          job.operation = 'end_patient_no_show'
          and session.status = 'active'
          and session.scheduled_starts_at = booking.starts_at
          and session.scheduled_ends_at = booking.ends_at
          and booking.status = 'confirmed'::public.booking_status
          and booking.meeting_provider in ('zoom', 'zoom_video_sdk')
          and exists (
            select 1 from public.session_payments payment
            where payment.booking_id = booking.id
              and payment.financial_status = 'paid'::public.session_financial_status
          )
          and booking.starts_at + interval '10 minutes' < now()
          and booking.ends_at > now()
          and job.metadata ->> 'bookingVersion' = booking.version::text
          and job.metadata ->> 'scheduledStartsAt' = booking.starts_at::text
          and not exists (
            select 1 from public.booking_events event
            where event.booking_id = booking.id
              and event.event_type = 'zoom_waiting_room_entered'
              and event.payload ->> 'bookingVersion' = booking.version::text
              and event.payload ->> 'scheduledStartsAt' = booking.starts_at::text
          )
          and not exists (
            select 1 from public.video_session_participations participation
            where participation.video_session_id = session.id
              and participation.participant_role = 'patient'::public.video_session_participant_role
              and participation.event_type = 'session.user_joined'
          )
        )
        or (
          job.operation = 'confirm_end'
          and session.termination_requested_at is not null
          and (
            session.termination_reason = 'manual_end'
            or (session.termination_reason = 'scheduled_end' and session.scheduled_ends_at <= now())
            or (session.termination_reason = 'hard_timeout' and session.hard_ends_at is not null and session.hard_ends_at <= now())
            or (session.termination_reason = 'provider_ended' and session.scheduled_ends_at <= now())
          )
        )
      )
    order by job.next_run_at, job.created_at
    for update of job, session, booking skip locked
    limit greatest(1, least(coalesce(p_limit, 10), 50))
  ),
  updated as (
    update public.video_session_control_jobs job
    set status = 'processing',
        attempts = attempts + 1,
        locked_until_at = now() + make_interval(
          secs => greatest(15, least(coalesce(p_lock_seconds, 60), 300))
        ),
        updated_at = now()
    from candidates
    where job.id = candidates.id
    returning job.id, job.video_session_id, job.booking_id, job.operation,
      job.attempts, job.max_attempts
  ),
  fenced as (
    update public.video_sessions session
    set termination_requested_at = case
          when updated.operation = 'confirm_end' then session.termination_requested_at
          else coalesce(session.termination_requested_at, now())
        end,
        termination_reason = case updated.operation
          when 'end_scheduled' then 'scheduled_end'
          when 'end_hard_timeout' then 'hard_timeout'
          when 'end_patient_no_show' then 'patient_no_show'
          else session.termination_reason
        end,
        last_maintenance_at = now(),
        updated_at = now()
    from updated
    where session.id = updated.video_session_id
    returning session.id, session.provider_session_id
  )
  select updated.id, updated.video_session_id, updated.booking_id,
    fenced.provider_session_id, updated.operation, updated.attempts,
    updated.max_attempts
  from updated
  join fenced on fenced.id = updated.video_session_id;
$$;


ALTER FUNCTION "public"."reserve_video_session_control_jobs_v1"("p_environment" "text", "p_limit" integer, "p_lock_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reserve_video_session_control_jobs_v1"("p_environment" "text", "p_limit" integer, "p_lock_seconds" integer) IS 'Atomically reserves terminal work and revalidates patient no-show evidence under the same booking advisory lock used by waiting-room arrival.';



CREATE OR REPLACE FUNCTION "public"."reserve_zoom_video_access_issue_v1"("p_environment" "text", "p_booking_id" "uuid", "p_profile_id" "uuid", "p_actor_role" "text", "p_window_seconds" integer DEFAULT 60, "p_max_issued" integer DEFAULT 4) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_limit public.zoom_video_access_issue_limits%rowtype;
  v_window_seconds integer := greatest(5, least(coalesce(p_window_seconds, 60), 300));
  v_max_issued integer := greatest(1, least(coalesce(p_max_issued, 4), 20));
begin
  if p_environment not in ('development', 'production') then
    raise exception 'invalid_zoom_environment' using errcode = '22023';
  end if;

  if p_actor_role not in ('patient', 'therapist') then
    raise exception 'invalid_zoom_actor_role' using errcode = '22023';
  end if;

  insert into public.zoom_video_access_issue_limits (
    environment,
    booking_id,
    profile_id,
    actor_role,
    window_started_at,
    issued_count,
    blocked_count,
    last_issued_at
  )
  values (
    p_environment,
    p_booking_id,
    p_profile_id,
    p_actor_role,
    v_now,
    0,
    0,
    null
  )
  on conflict (environment, booking_id, profile_id, actor_role) do nothing;

  select *
    into v_limit
  from public.zoom_video_access_issue_limits
  where environment = p_environment
    and booking_id = p_booking_id
    and profile_id = p_profile_id
    and actor_role = p_actor_role
  for update;

  if not found then
    raise exception 'zoom_video_access_rate_limit_not_found';
  end if;

  if v_limit.window_started_at + make_interval(secs => v_window_seconds) <= v_now then
    update public.zoom_video_access_issue_limits
    set window_started_at = v_now,
        issued_count = 1,
        last_issued_at = v_now,
        updated_at = v_now
    where id = v_limit.id
    returning * into v_limit;

    return jsonb_build_object(
      'allowed', true,
      'issuedCount', v_limit.issued_count,
      'resetAt', v_limit.window_started_at + make_interval(secs => v_window_seconds)
    );
  end if;

  if v_limit.issued_count >= v_max_issued then
    update public.zoom_video_access_issue_limits
    set blocked_count = blocked_count + 1,
        updated_at = v_now
    where id = v_limit.id
    returning * into v_limit;

    return jsonb_build_object(
      'allowed', false,
      'issuedCount', v_limit.issued_count,
      'resetAt', v_limit.window_started_at + make_interval(secs => v_window_seconds)
    );
  end if;

  update public.zoom_video_access_issue_limits
  set issued_count = issued_count + 1,
      last_issued_at = v_now,
      updated_at = v_now
  where id = v_limit.id
  returning * into v_limit;

  return jsonb_build_object(
    'allowed', true,
    'issuedCount', v_limit.issued_count,
    'resetAt', v_limit.window_started_at + make_interval(secs => v_window_seconds)
  );
end;
$$;


ALTER FUNCTION "public"."reserve_zoom_video_access_issue_v1"("p_environment" "text", "p_booking_id" "uuid", "p_profile_id" "uuid", "p_actor_role" "text", "p_window_seconds" integer, "p_max_issued" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_zoom_video_webhook_event_v1"("p_event_key" "text", "p_event_type" "text", "p_account_identifier" "text", "p_provider_session_id" "text", "p_session_name_hash" "text", "p_provider_user_id" "text", "p_provider_user_key" "text", "p_request_id" "text", "p_event_ts" timestamp with time zone, "p_payload_sha256" "text", "p_payload_sanitized" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("processing_status" "public"."zoom_video_webhook_processing_status", "acquired" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.zoom_video_webhook_events%rowtype;
begin
  insert into public.zoom_video_webhook_events (
    event_key,
    event_type,
    account_identifier,
    provider_session_id,
    session_name_hash,
    provider_user_id,
    provider_user_key,
    request_id,
    event_ts,
    payload_sha256,
    payload_sanitized,
    processing_status,
    attempts,
    processing_started_at,
    updated_at
  ) values (
    p_event_key,
    p_event_type,
    p_account_identifier,
    p_provider_session_id,
    p_session_name_hash,
    p_provider_user_id,
    p_provider_user_key,
    p_request_id,
    p_event_ts,
    p_payload_sha256,
    coalesce(p_payload_sanitized, '{}'::jsonb),
    'processing',
    1,
    now(),
    now()
  )
  on conflict (event_key) do nothing
  returning * into v_event;

  if v_event.id is not null then
    return query select v_event.processing_status, true;
    return;
  end if;

  select *
    into v_event
  from public.zoom_video_webhook_events
  where event_key = p_event_key
  for update;

  if v_event.processing_status in ('processed', 'ignored')
    or (
      v_event.processing_status = 'processing'
      and v_event.processing_started_at > now() - interval '5 minutes'
    ) then
    return query select v_event.processing_status, false;
    return;
  end if;

  update public.zoom_video_webhook_events
  set processing_status = 'processing',
      processing_started_at = now(),
      processed_at = null,
      attempts = attempts + 1,
      error_code = null,
      error_message = null,
      updated_at = now()
  where id = v_event.id
  returning * into v_event;

  return query select v_event.processing_status, true;
end;
$$;


ALTER FUNCTION "public"."reserve_zoom_video_webhook_event_v1"("p_event_key" "text", "p_event_type" "text", "p_account_identifier" "text", "p_provider_session_id" "text", "p_session_name_hash" "text", "p_provider_user_id" "text", "p_provider_user_key" "text", "p_request_id" "text", "p_event_ts" timestamp with time zone, "p_payload_sha256" "text", "p_payload_sanitized" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_booking_reschedule_v1"("p_reschedule_request_id" "uuid", "p_resolved_by_profile_id" "uuid", "p_resolution" "text", "p_request_id" "text", "p_expected_booking_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_request public.booking_reschedule_requests%rowtype;
  v_requester_is_patient boolean;
  v_resolver_is_patient boolean;
  v_resolver_is_therapist boolean;
begin
  if p_resolution not in ('accepted', 'rejected', 'cancelled') then
    raise exception 'INVALID_RESCHEDULE_RESOLUTION' using errcode = '22023';
  end if;

  if length(trim(coalesce(p_request_id, ''))) not between 8 and 200 then
    raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode = '22023';
  end if;

  select *
    into v_request
  from public.booking_reschedule_requests
  where id = p_reschedule_request_id
  for update;

  if not found then
    raise exception 'BOOKING_RESCHEDULE_NOT_FOUND' using errcode = 'P0002';
  end if;

  select *
    into v_booking
  from public.bookings
  where id = v_request.booking_id
  for update;

  if v_request.status <> 'pending' then
    if v_request.resolution_request_id = trim(p_request_id) then
      return pg_catalog.jsonb_build_object(
        'applied', v_request.status = 'applied',
        'bookingId', v_booking.id,
        'bookingVersion', v_booking.version,
        'rescheduleRequestId', v_request.id,
        'status', v_request.status
      );
    end if;

    raise exception 'BOOKING_RESCHEDULE_ALREADY_RESOLVED'
      using errcode = 'P0001';
  end if;

  if v_request.expires_at <= now() then
    update public.booking_reschedule_requests
    set status = 'expired',
        resolved_by_profile_id = p_resolved_by_profile_id,
        resolution_request_id = trim(p_request_id),
        resolved_at = now(),
        updated_at = now()
    where id = v_request.id;

    return pg_catalog.jsonb_build_object(
      'applied', false,
      'bookingId', v_booking.id,
      'bookingVersion', v_booking.version,
      'reason', 'expired',
      'rescheduleRequestId', v_request.id,
      'status', 'expired'
    );
  end if;

  select
    patient.user_id = v_request.requested_by_profile_id,
    patient.user_id = p_resolved_by_profile_id,
    therapist.user_id = p_resolved_by_profile_id
  into
    v_requester_is_patient,
    v_resolver_is_patient,
    v_resolver_is_therapist
  from public.patient_profiles as patient
  join public.therapist_profiles as therapist
    on therapist.id = v_booking.therapist_profile_id
  where patient.id = v_booking.patient_profile_id;

  if not coalesce(v_resolver_is_patient, false)
    and not coalesce(v_resolver_is_therapist, false) then
    raise exception 'BOOKING_ACTOR_FORBIDDEN' using errcode = '42501';
  end if;

  if p_resolution = 'cancelled'
    and p_resolved_by_profile_id <> v_request.requested_by_profile_id then
    raise exception 'BOOKING_ACTOR_FORBIDDEN' using errcode = '42501';
  end if;

  if p_resolution in ('accepted', 'rejected') and (
    (v_requester_is_patient and not v_resolver_is_therapist)
    or (not v_requester_is_patient and not v_resolver_is_patient)
  ) then
    raise exception 'BOOKING_ACTOR_FORBIDDEN' using errcode = '42501';
  end if;

  if p_resolution = 'accepted' then
    if v_booking.status <> 'confirmed' then
      raise exception 'BOOKING_CANNOT_BE_RESCHEDULED' using errcode = 'P0001';
    end if;

    if v_booking.version <> v_request.booking_version_at_request
      or (
        p_expected_booking_version is not null
        and p_expected_booking_version <> v_booking.version
      ) then
      raise exception 'BOOKING_VERSION_CONFLICT' using errcode = 'P0001';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_booking.therapist_profile_id::text, 0)
    );
    perform public.expire_booking_holds_v1(
      now(),
      v_booking.therapist_profile_id
    );
    perform pg_catalog.set_config(
      'tes.booking_actor_profile_id',
      p_resolved_by_profile_id::text,
      true
    );
    perform pg_catalog.set_config(
      'tes.booking_reason',
      left(coalesce(v_request.reason, ''), 500),
      true
    );
    perform pg_catalog.set_config(
      'tes.booking_request_id',
      trim(p_request_id),
      true
    );
    perform pg_catalog.set_config(
      'tes.booking_source',
      'reschedule_resolution',
      true
    );

    begin
      update public.bookings
      set starts_at = v_request.proposed_starts_at,
          ends_at = v_request.proposed_ends_at,
          timezone = v_request.proposed_timezone,
          updated_at = now()
      where id = v_booking.id
      returning * into v_booking;
    exception
      when exclusion_violation then
        raise exception 'BOOKING_CONFLICT' using errcode = 'P0001';
    end;

    update public.booking_reschedule_requests
    set status = 'applied',
        resolved_by_profile_id = p_resolved_by_profile_id,
        resolution_request_id = trim(p_request_id),
        resolved_at = now(),
        applied_at = now(),
        updated_at = now()
    where id = v_request.id
    returning * into v_request;

    perform public.sync_booking_video_session_from_agenda_v1(
      v_booking.id,
      'update',
      p_request_id
    );

    perform pg_catalog.set_config('tes.booking_actor_profile_id', '', true);
    perform pg_catalog.set_config('tes.booking_reason', '', true);
    perform pg_catalog.set_config('tes.booking_request_id', '', true);
    perform pg_catalog.set_config('tes.booking_source', '', true);
  else
    update public.booking_reschedule_requests
    set status = p_resolution,
        resolved_by_profile_id = p_resolved_by_profile_id,
        resolution_request_id = trim(p_request_id),
        resolved_at = now(),
        updated_at = now()
    where id = v_request.id
    returning * into v_request;
  end if;

  insert into public.booking_events (
    booking_id,
    actor_profile_id,
    event_type,
    request_id,
    source,
    previous_status,
    next_status,
    payload
  ) values (
    v_booking.id,
    p_resolved_by_profile_id,
    'booking_reschedule_resolved',
    trim(p_request_id),
    'agenda_a2',
    v_booking.status,
    v_booking.status,
    pg_catalog.jsonb_build_object(
      'rescheduleRequestId', v_request.id,
      'resolution', p_resolution,
      'status', v_request.status
    )
  )
  on conflict do nothing;

  return pg_catalog.jsonb_build_object(
    'applied', v_request.status = 'applied',
    'bookingId', v_booking.id,
    'bookingVersion', v_booking.version,
    'rescheduleRequestId', v_request.id,
    'status', v_request.status
  );
end;
$$;


ALTER FUNCTION "public"."resolve_booking_reschedule_v1"("p_reschedule_request_id" "uuid", "p_resolved_by_profile_id" "uuid", "p_resolution" "text", "p_request_id" "text", "p_expected_booking_version" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_booking_reschedule_v1"("p_reschedule_request_id" "uuid", "p_resolved_by_profile_id" "uuid", "p_resolution" "text", "p_request_id" "text", "p_expected_booking_version" integer) IS 'Resolves one reschedule request and atomically updates the booking and local Video SDK session when accepted.';



CREATE OR REPLACE FUNCTION "public"."resolve_current_therapist_for_reviews_v1"() RETURNS "public"."therapist_profiles"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
begin
  select *
  into v_profile
  from public.therapist_profiles
  where user_id = (select auth.uid())
  limit 1;

  if v_profile.id is null then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0001';
  end if;

  return v_profile;
end;
$$;


ALTER FUNCTION "public"."resolve_current_therapist_for_reviews_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_payout_operational_incident_v1"("p_incident_key" "text", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_updated boolean;
begin
  if nullif(trim(p_incident_key), '') is null or p_now is null then
    raise exception 'PAYOUT_INCIDENT_RESOLUTION_INVALID';
  end if;

  with resolved as (
    update public.payout_operational_incidents
    set status = 'resolved',
        resolved_at = coalesce(resolved_at, p_now),
        updated_at = now()
    where incident_key = left(trim(p_incident_key), 240)
      and status = 'open'
    returning true
  )
  select coalesce(bool_or(true), false)
  into v_updated
  from resolved;

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."resolve_payout_operational_incident_v1"("p_incident_key" "text", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_payout_operational_incident_v1"("p_incident_key" "text", "p_now" timestamp with time zone) IS 'Resolves a protected payout operational incident after confirmed worker recovery.';



CREATE OR REPLACE FUNCTION "public"."resolve_structured_participant_message_v2"("p_conversation_id" "uuid", "p_template_key" "text", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_parameters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_expected_context public.message_context;
  v_conversation public.conversations%rowtype;
  v_patient_user_id uuid;
  v_therapist_user_id uuid;
  v_recipient_name text;
  v_template public.message_templates%rowtype;
  v_parameters jsonb := coalesce(p_parameters, '{}'::jsonb);
  v_resolved_parameters jsonb := '{}'::jsonb;
  v_body text;
  v_parameter jsonb;
  v_key text;
  v_value text;
  v_option_label text;
  v_context_booking_id uuid;
  v_cta jsonb := null;
  v_recipient_route text;
  v_recipient_role public.user_role;
begin
  if v_actor_id is null then
    raise exception 'authenticated participant required' using errcode = '42501';
  end if;

  if p_conversation_id is null
    or length(btrim(coalesce(p_template_key, ''))) = 0
    or jsonb_typeof(v_parameters) <> 'object'
  then
    raise exception 'structured message request is invalid' using errcode = '22023';
  end if;

  select *
  into v_conversation
  from public.conversations
  where conversations.id = p_conversation_id;

  if not found then
    raise exception 'conversation participant required' using errcode = '42501';
  end if;

  select patient_profiles.user_id
  into v_patient_user_id
  from public.patient_profiles
  where patient_profiles.id = v_conversation.patient_profile_id;

  select therapist_profiles.user_id
  into v_therapist_user_id
  from public.therapist_profiles
  where therapist_profiles.id = v_conversation.therapist_profile_id;

  if v_patient_user_id = v_actor_id then
    v_expected_context := 'patient_to_therapist'::public.message_context;
    v_recipient_role := 'therapist'::public.user_role;
    select public.therapist_profiles.public_name
    into v_recipient_name
    from public.therapist_profiles
    where public.therapist_profiles.id = v_conversation.therapist_profile_id;
  elsif v_therapist_user_id = v_actor_id then
    v_expected_context := 'therapist_to_patient'::public.message_context;
    v_recipient_role := 'patient'::public.user_role;
    select coalesce(public.patient_profiles.display_name, 'Paciente')
    into v_recipient_name
    from public.patient_profiles
    where public.patient_profiles.id = v_conversation.patient_profile_id;
  else
    raise exception 'conversation participant required' using errcode = '42501';
  end if;

  select *
  into v_template
  from public.message_templates
  where key = btrim(p_template_key)
    and context = v_expected_context
    and is_active = true;

  if not found then
    raise exception 'participant template is unavailable for this direction'
      using errcode = '22023';
  end if;

  v_context_booking_id := coalesce(p_booking_id, v_conversation.booking_id);
  if v_context_booking_id is not null then
    if not exists (
      select 1
      from public.bookings
      where bookings.id = v_context_booking_id
        and bookings.patient_profile_id = v_conversation.patient_profile_id
        and bookings.therapist_profile_id = v_conversation.therapist_profile_id
    ) then
      raise exception 'booking context is not authorized for this conversation'
        using errcode = '42501';
    end if;
  elsif v_template.requires_booking then
    raise exception 'this participant template requires an authorized session context'
      using errcode = '22023';
  end if;

  for v_key in
    select key from jsonb_object_keys(v_parameters) as key
  loop
    if not exists (
      select 1
      from jsonb_array_elements(v_template.parameter_schema) as parameter
      where parameter->>'key' = v_key
    ) then
      raise exception 'structured message parameter is not allowed'
        using errcode = '22023';
    end if;
  end loop;

  for v_parameter in
    select value from jsonb_array_elements(v_template.parameter_schema)
  loop
    v_key := v_parameter->>'key';
    if not (v_parameters ? v_key) then
      raise exception 'required structured message parameter is missing'
        using errcode = '22023';
    end if;

    v_value := v_parameters->>v_key;
    select option->>'label'
    into v_option_label
    from jsonb_array_elements(v_parameter->'options') as option
    where option->>'value' = v_value
    limit 1;

    if v_option_label is null then
      raise exception 'structured message parameter value is not allowed'
        using errcode = '22023';
    end if;

    v_body := coalesce(v_body, v_template.body);
    v_body := replace(v_body, '{{' || v_key || '_label}}', v_option_label);
    v_resolved_parameters := v_resolved_parameters || jsonb_build_object(
      v_key,
      jsonb_build_object('value', v_value, 'label', v_option_label)
    );
  end loop;

  if v_body is null then
    v_body := v_template.body;
  end if;

  if v_template.cta_action is not null then
    if v_context_booking_id is not null then
      if v_recipient_role = 'patient'::public.user_role then
        v_recipient_route := '/app/encontros/' || v_context_booking_id::text;
      else
        v_recipient_route := '/terapeuta/sessoes/' || v_context_booking_id::text;
      end if;

      v_cta := jsonb_build_object(
        'action', v_template.cta_action,
        'href', v_recipient_route,
        'label', case v_template.cta_action
          when 'open_session' then case when v_recipient_role = 'patient'::public.user_role then 'Entrar no encontro' else 'Abrir sessão' end
          when 'reschedule_session' then 'Reagendar'
          when 'cancel_session' then 'Cancelar sessão'
          else case when v_recipient_role = 'patient'::public.user_role then 'Ver encontro' else 'Ver sessão' end
        end
      );
    end if;
  end if;

  return jsonb_build_object(
    'actorId', v_actor_id,
    'body', v_body,
    'category', v_template.category,
    'context', case when v_context_booking_id is null then null else jsonb_build_object('bookingId', v_context_booking_id) end,
    'cta', v_cta,
    'parameters', v_resolved_parameters,
    'recipientName', coalesce(v_recipient_name, case when v_recipient_role = 'patient'::public.user_role then 'Paciente' else 'Terapeuta' end),
    'templateId', v_template.id,
    'templateKey', v_template.key,
    'title', v_template.title,
    'usageDescription', v_template.usage_description
  );
end;
$$;


ALTER FUNCTION "public"."resolve_structured_participant_message_v2"("p_conversation_id" "uuid", "p_template_key" "text", "p_booking_id" "uuid", "p_parameters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_therapist_block_impact_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_impact_id" "uuid", "p_resolution" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_existing public.availability_exception_events%rowtype;
  v_impact public.availability_exception_booking_impacts%rowtype;
  v_result jsonb;
  v_therapist public.therapist_profiles%rowtype;
begin
  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = p_actor_user_id
    and profile.role = 'therapist';

  if not found or v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_therapist.id::text, 0)
  );

  select event.*
    into v_existing
  from public.availability_exception_events as event
  where event.therapist_profile_id = v_therapist.id
    and event.request_id = p_request_id;

  if found then
    return v_existing.result || jsonb_build_object('idempotentReplay', true);
  end if;

  if p_resolution <> 'keep_booking' then
    raise exception 'invalid_block_impact_resolution' using errcode = '22023';
  end if;

  select impact.*
    into v_impact
  from public.availability_exception_booking_impacts as impact
  where impact.id = p_impact_id
    and impact.therapist_profile_id = v_therapist.id
  for update;

  if not found then
    raise exception 'block_impact_not_found' using errcode = 'P0002';
  end if;

  if v_impact.status = 'pending' then
    update public.availability_exception_booking_impacts
    set
      status = 'resolved',
      resolution = p_resolution,
      resolved_by_user_id = p_actor_user_id,
      resolved_at = now()
    where id = v_impact.id
    returning * into v_impact;
  end if;

  v_result := jsonb_build_object(
    'impactId', v_impact.id,
    'status', v_impact.status,
    'resolution', v_impact.resolution,
    'idempotentReplay', false
  );

  insert into public.availability_exception_events (
    therapist_profile_id,
    actor_user_id,
    exception_id,
    booking_id,
    event_type,
    request_id,
    result
  )
  values (
    v_therapist.id,
    p_actor_user_id,
    v_impact.exception_id,
    v_impact.booking_id,
    'block_impact_resolved',
    p_request_id,
    v_result
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."resolve_therapist_block_impact_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_impact_id" "uuid", "p_resolution" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resubmit_therapy_catalog_request_v2"("p_actor_user_id" "uuid", "p_catalog_request_id" "uuid", "p_payload" "jsonb", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_request public.therapy_catalog_requests;
  v_name text := trim(coalesce(p_payload->>'informedName', ''));
  v_submission jsonb := coalesce(p_payload->'submission', '{}'::jsonb);
  v_theme_source jsonb := coalesce(p_payload->'themeIds', v_submission->'themeIds', '[]'::jsonb);
  v_theme_ids uuid[] := '{}'::uuid[];
  v_theme_names text[] := '{}'::text[];
  v_theme_input_count integer := 0;
  v_valid_theme_count integer := 0;
begin
  select * into v_request
  from public.therapy_catalog_requests
  where id = p_catalog_request_id
    and requester_profile_id = p_actor_user_id
  for update;

  if v_request.id is null then
    raise exception 'THERAPY_CATALOG_REQUEST_NOT_FOUND';
  end if;

  if exists (
    select 1
    from public.therapy_catalog_events event
    where event.entity_type = 'therapy_catalog_request'
      and event.entity_id = v_request.id
      and event.event_type = 'therapy_request_resubmitted'
      and event.request_id = p_request_id
  ) then
    return jsonb_build_object(
      'contractVersion', 2,
      'idempotentReplay', true,
      'requestId', v_request.id,
      'status', v_request.status
    );
  end if;

  if v_request.status <> 'needs_information' then
    raise exception 'THERAPY_CATALOG_REQUEST_NOT_EDITABLE';
  end if;

  if jsonb_typeof(v_theme_source) <> 'array' then
    raise exception 'THERAPY_CATALOG_REQUEST_INVALID_PAYLOAD';
  end if;

  with raw as (
    select trim(value) as id_text
    from jsonb_array_elements_text(v_theme_source) value
  ), validated as (
    select distinct id_text::uuid as id
    from raw
    where id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  )
  select
    (select count(*) from raw),
    coalesce(array_agg(theme.id order by theme.sort_order, theme.name), '{}'::uuid[]),
    coalesce(array_agg(theme.name order by theme.sort_order, theme.name), '{}'::text[]),
    count(theme.id)::integer
  into v_theme_input_count, v_theme_ids, v_theme_names, v_valid_theme_count
  from validated
  join public.matching_themes theme on theme.id = validated.id and theme.is_active;

  if p_request_id is null
    or char_length(v_name) not between 2 and 120
    or nullif(trim(coalesce(v_submission->>'description', '')), '') is null
    or nullif(trim(coalesce(v_submission->>'objective', '')), '') is null
    or nullif(trim(coalesce(v_submission->>'useCases', '')), '') is null
    or nullif(trim(coalesce(v_submission->>'sessionProcess', '')), '') is null
    or v_theme_input_count not between 1 and 3
    or v_valid_theme_count <> v_theme_input_count then
    raise exception 'THERAPY_CATALOG_REQUEST_INVALID_PAYLOAD';
  end if;

  v_submission := jsonb_set(v_submission, '{themeIds}', to_jsonb(v_theme_ids), true);
  v_submission := jsonb_set(v_submission, '{themeNames}', to_jsonb(v_theme_names), true);

  update public.therapy_catalog_requests
  set
    informed_name = v_name,
    description = nullif(trim(coalesce(v_submission->>'description', '')), ''),
    justification = nullif(trim(coalesce(v_submission->>'objective', '')), ''),
    submission = v_submission,
    submission_version = 2,
    status = 'submitted',
    decision = null,
    resubmitted_at = now(),
    updated_at = now()
  where id = v_request.id
  returning * into v_request;

  insert into public.therapy_catalog_events (
    actor_profile_id, actor_role, entity_type, entity_id, event_type, previous_state, next_state, request_id
  ) values (
    p_actor_user_id,
    'therapist',
    'therapy_catalog_request',
    v_request.id,
    'therapy_request_resubmitted',
    jsonb_build_object('status', 'needs_information'),
    jsonb_build_object('status', 'submitted'),
    p_request_id
  );

  insert into public.notifications (profile_id, kind, title, body, href)
  values (
    p_actor_user_id,
    'therapy_catalog_request',
    'Solicitação atualizada',
    'Recebemos as informações adicionais da sua sugestão de terapia.',
    '/terapeuta/mensagens/solicitar-terapia?request=' || v_request.id::text
  );

  return jsonb_build_object(
    'contractVersion', 2,
    'idempotentReplay', false,
    'requestId', v_request.id,
    'status', v_request.status
  );
end;
$_$;


ALTER FUNCTION "public"."resubmit_therapy_catalog_request_v2"("p_actor_user_id" "uuid", "p_catalog_request_id" "uuid", "p_payload" "jsonb", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resume_failed_payout_scheduler_run_v1"("p_run_id" "uuid", "p_expected_batch_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.payout_scheduler_runs%rowtype;
begin
  if p_run_id is null or p_expected_batch_id is null or p_now is null then
    raise exception 'PAYOUT_SCHEDULER_RESUME_INVALID';
  end if;

  select * into v_run
  from public.payout_scheduler_runs
  where id = p_run_id
  for update;

  if not found then raise exception 'PAYOUT_SCHEDULER_RUN_NOT_FOUND'; end if;
  if v_run.status <> 'failed' then raise exception 'PAYOUT_SCHEDULER_RUN_NOT_FAILED'; end if;
  if v_run.payout_batch_id is distinct from p_expected_batch_id then
    raise exception 'PAYOUT_SCHEDULER_BATCH_MISMATCH';
  end if;
  if v_run.worker_id is not null or (v_run.lease_expires_at is not null and v_run.lease_expires_at > p_now) then
    raise exception 'PAYOUT_SCHEDULER_LEASE_ACTIVE';
  end if;

  update public.payout_scheduler_runs
  set status = 'running',
      consecutive_failures = 0,
      next_retry_at = null,
      last_error_code = null,
      last_error_message = null,
      completed_at = null,
      worker_id = null,
      lease_expires_at = null,
      updated_at = now()
  where id = v_run.id;

  update public.payout_operational_incidents
  set status = 'resolved',
      resolved_at = coalesce(resolved_at, p_now),
      updated_at = now()
  where incident_key = 'scheduler:' || v_run.id::text || ':worker-circuit-open'
    and status = 'open';

  return jsonb_build_object(
    'resumed', true,
    'runId', v_run.id,
    'batchId', v_run.payout_batch_id
  );
end;
$$;


ALTER FUNCTION "public"."resume_failed_payout_scheduler_run_v1"("p_run_id" "uuid", "p_expected_batch_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resume_session_transfer_job_v10"("p_job_id" "uuid", "p_expected_attempt_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.session_transfer_jobs%rowtype;
begin
  if p_job_id is null
    or p_expected_attempt_count is null
    or p_expected_attempt_count < 1
  then
    raise exception 'SESSION_TRANSFER_RESUME_V10_INVALID'
      using errcode = '22023';
  end if;

  select * into v_job
  from public.session_transfer_jobs
  where id = p_job_id
  for update;

  if not found
    or v_job.status <> 'failed'
    or v_job.attempt_count <> p_expected_attempt_count
    or v_job.prepared_at is not null
    or v_job.stripe_transfer_id is not null
  then
    return jsonb_build_object(
      'resumed', false,
      'reason', 'manual_reconciliation_required'
    );
  end if;

  update public.session_transfer_jobs
  set status = 'creating',
      last_error_code = null,
      next_retry_at = now(),
      lease_owner = null,
      lease_expires_at = null,
      updated_at = now()
  where id = v_job.id;

  update public.session_payments
  set transfer_status = 'transfer_pending',
      updated_at = now()
  where id = v_job.session_payment_id
    and financial_status = 'paid'
    and not refund_pending;

  return jsonb_build_object('resumed', true, 'reason', 'operator_resumed');
end;
$$;


ALTER FUNCTION "public"."resume_session_transfer_job_v10"("p_job_id" "uuid", "p_expected_attempt_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resume_session_transfer_job_v10"("p_job_id" "uuid", "p_expected_attempt_count" integer) IS 'Explicitly resumes an unprepared V10 Transfer job after operations resolves its definitive preflight failure.';



CREATE OR REPLACE FUNCTION "public"."retire_therapist_connect_account_v1"("p_stripe_account_id" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_closed_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_account public.therapist_connect_accounts%rowtype;
  v_requeued_count integer := 0;
begin
  if nullif(trim(p_stripe_account_id), '') is null
    or nullif(trim(p_stripe_event_id), '') is null
    or p_stripe_event_created_at is null
    or p_closed_at is null
  then
    raise exception 'CONNECT_ACCOUNT_CLOSURE_INVALID';
  end if;

  select * into v_account
  from public.therapist_connect_accounts
  where stripe_account_id = p_stripe_account_id
  for update;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'connect_account_not_found');
  end if;

  if not v_account.is_current then
    return jsonb_build_object('applied', false, 'reason', 'already_historical');
  end if;

  update public.therapist_connect_accounts
  set is_current = false,
      closed_at = p_closed_at,
      closed_stripe_event_id = p_stripe_event_id,
      closed_stripe_event_created_at = p_stripe_event_created_at,
      disabled_reason = 'account_closed',
      charges_enabled = false,
      details_submitted = false,
      onboarding_status = 'disabled',
      operational_status = 'disabled',
      payout_schedule_interval = null,
      payout_status = 'disabled',
      payouts_enabled = false,
      stripe_event_created_at = p_stripe_event_created_at,
      stripe_event_id = p_stripe_event_id,
      stripe_transfers_status = 'inactive',
      last_synced_at = now(),
      updated_at = now()
  where id = v_account.id;

  -- Only entries with no Transfer attempt may return to the platform-held
  -- eligible queue. Any created Transfer remains tied to this historical account.
  with released as (
    update public.payout_batch_items item
    set status = 'removed',
        failure_code = 'connect_account_closed_before_transfer',
        failure_message = 'Conta de recebimento encerrada antes da criacao do Transfer.',
        metadata = item.metadata || jsonb_build_object(
          'connectAccountClosureEventId', p_stripe_event_id,
          'connectAccountClosedAt', p_closed_at
        ),
        updated_at = now()
    from public.payout_batch_therapists group_row
    where item.payout_batch_therapist_id = group_row.id
      and group_row.connect_account_id = v_account.id
      and item.status = 'reserved'
      and not exists (
        select 1
        from public.stripe_transfers transfer
        where transfer.payout_batch_item_id = item.id
      )
    returning item.session_payment_id
  ), restored as (
    update public.session_payments payment
    set transfer_status = 'eligible', updated_at = now()
    from released
    where payment.id = released.session_payment_id
      and payment.transfer_status = 'batched'
    returning payment.id
  )
  select count(*)::integer into v_requeued_count from restored;

  update public.payout_batch_therapists group_row
  set item_count = stats.item_count,
      total_amount_cents = stats.total_amount_cents,
      status = case when stats.item_count = 0 then 'removed'::public.payout_batch_item_status else group_row.status end,
      metadata = group_row.metadata || jsonb_build_object(
        'connectAccountClosureEventId', p_stripe_event_id,
        'connectAccountClosedAt', p_closed_at
      ),
      updated_at = now()
  from (
    select group_row_inner.id,
      count(item.id)::integer as item_count,
      coalesce(sum(item.amount_cents), 0)::integer as total_amount_cents
    from public.payout_batch_therapists group_row_inner
    left join public.payout_batch_items item
      on item.payout_batch_therapist_id = group_row_inner.id
      and item.status <> 'removed'
    where group_row_inner.connect_account_id = v_account.id
    group by group_row_inner.id
  ) stats
  where group_row.id = stats.id;

  insert into public.therapist_connect_account_snapshots (
    connect_account_id,
    stripe_event_id,
    snapshot
  ) values (
    v_account.id,
    p_stripe_event_id,
    jsonb_build_object(
      'account_status', 'disabled',
      'closure', jsonb_build_object(
        'closedAt', p_closed_at,
        'eventCreatedAt', p_stripe_event_created_at,
        'reason', 'account_closed'
      )
    )
  ) on conflict do nothing;

  return jsonb_build_object('applied', true, 'requeuedCount', v_requeued_count);
end;
$$;


ALTER FUNCTION "public"."retire_therapist_connect_account_v1"("p_stripe_account_id" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_closed_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."retire_therapist_connect_account_v1"("p_stripe_account_id" "text", "p_stripe_event_id" "text", "p_stripe_event_created_at" timestamp with time zone, "p_closed_at" timestamp with time zone) IS 'Internal, idempotent closure transition. Service role only; requeues only payout items with no Transfer record and preserves all historical Transfers and Payouts.';



CREATE OR REPLACE FUNCTION "public"."run_booking_reminder_scheduler_v1"("p_now" timestamp with time zone DEFAULT "clock_timestamp"(), "p_limit" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.booking_reminder_jobs;
  v_booking_status public.booking_status;
  v_booking_version integer;
  v_starts_at timestamptz;
  v_payment_status public.session_financial_status;
  v_refund_pending boolean;
  v_disputed_at timestamptz;
  v_internal_contested_at timestamptz;
  v_admin_blocked_at timestamptz;
  v_patient_user_id uuid;
  v_expected_scheduled_for timestamptz;
  v_outbox_id uuid;
  v_reason text;
  v_worker_id uuid := gen_random_uuid();
  v_recovered integer := 0;
  v_missed integer := 0;
  v_claimed integer := 0;
  v_enqueued integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
begin
  if p_now is null or p_limit < 1 or p_limit > 100 then
    raise exception 'BOOKING_REMINDER_INVALID_RUN_REQUEST';
  end if;

  update public.booking_reminder_jobs
  set status = case
        when scheduled_for > p_now - interval '1 minute'
          then 'scheduled'::public.booking_reminder_job_status
        else 'missed'::public.booking_reminder_job_status
      end,
      lease_owner = null,
      lease_expires_at = null,
      last_error = case
        when scheduled_for > p_now - interval '1 minute' then last_error
        else 'scheduler_tick_missed'
      end
  where status = 'processing'
    and lease_expires_at is not null
    and lease_expires_at <= p_now;
  get diagnostics v_recovered = row_count;

  update public.booking_reminder_jobs
  set status = 'missed',
      last_error = 'scheduler_tick_missed',
      lease_owner = null,
      lease_expires_at = null
  where status = 'scheduled'
    and scheduled_for < p_now - interval '1 minute';
  get diagnostics v_missed = row_count;

  for v_job in
    select *
    from public.booking_reminder_jobs
    where status = 'scheduled'
      and scheduled_for <= p_now
      and scheduled_for > p_now - interval '1 minute'
    order by scheduled_for, created_at
    limit p_limit
    for update skip locked
  loop
    v_claimed := v_claimed + 1;

    update public.booking_reminder_jobs
    set status = 'processing',
        attempts = attempts + 1,
        lease_owner = v_worker_id,
        lease_expires_at = p_now + interval '2 minutes',
        last_error = null
    where id = v_job.id;

    v_booking_status := null;
    v_booking_version := null;
    v_starts_at := null;
    v_payment_status := null;
    v_refund_pending := null;
    v_disputed_at := null;
    v_internal_contested_at := null;
    v_admin_blocked_at := null;
    v_patient_user_id := null;
    v_expected_scheduled_for := null;
    v_outbox_id := null;
    v_reason := null;

    begin
      select
        booking.status,
        booking.version,
        booking.starts_at,
        payment.financial_status,
        payment.refund_pending,
        payment.disputed_at,
        payment.internal_contested_at,
        payment.admin_blocked_at,
        patient.user_id
      into
        v_booking_status,
        v_booking_version,
        v_starts_at,
        v_payment_status,
        v_refund_pending,
        v_disputed_at,
        v_internal_contested_at,
        v_admin_blocked_at,
        v_patient_user_id
      from public.bookings booking
      left join public.session_payments payment on payment.booking_id = booking.id
      left join public.patient_profiles patient on patient.id = booking.patient_profile_id
      where booking.id = v_job.booking_id
      for update of booking;

      v_expected_scheduled_for := case v_job.action_key
        when 'booking_reminder_24h_patient' then v_starts_at - interval '24 hours'
        when 'booking_reminder_1h_patient' then v_starts_at - interval '1 hour'
        else null
      end;

      if v_booking_status is null then
        v_reason := 'booking_not_found';
      elsif v_booking_status <> 'confirmed' then
        v_reason := 'booking_not_confirmed';
      elsif v_booking_version is distinct from v_job.booking_version then
        v_reason := 'booking_version_changed';
      elsif v_starts_at <= p_now then
        v_reason := 'booking_already_started';
      elsif v_patient_user_id is null or v_patient_user_id <> v_job.recipient_user_id then
        v_reason := 'patient_recipient_changed';
      elsif v_payment_status not in ('paid', 'partially_refunded') then
        v_reason := 'payment_not_eligible';
      elsif coalesce(v_refund_pending, true)
        or v_disputed_at is not null
        or v_internal_contested_at is not null
        or v_admin_blocked_at is not null
      then
        v_reason := 'payment_blocked';
      elsif v_expected_scheduled_for is distinct from v_job.scheduled_for then
        v_reason := 'reminder_schedule_changed';
      end if;

      if v_reason is not null then
        update public.booking_reminder_jobs
        set status = case
              when v_reason in ('booking_not_confirmed', 'booking_version_changed', 'booking_already_started', 'patient_recipient_changed', 'payment_not_eligible', 'payment_blocked', 'reminder_schedule_changed')
                then 'cancelled'::public.booking_reminder_job_status
              else 'failed'::public.booking_reminder_job_status
            end,
            last_error = v_reason,
            lease_owner = null,
            lease_expires_at = null
        where id = v_job.id;
        if v_reason = 'booking_not_found' then
          v_failed := v_failed + 1;
        else
          v_skipped := v_skipped + 1;
        end if;
      else
        v_outbox_id := public.enqueue_transactional_email_v1(
          v_job.action_key,
          v_job.id,
          'booking',
          v_job.booking_id,
          v_job.recipient_user_id,
          'profile:' || v_job.recipient_user_id::text,
          '{}'::jsonb
        );

        if v_outbox_id is null then
          update public.booking_reminder_jobs
          set status = 'skipped',
              last_error = 'automatic_dispatch_disabled',
              lease_owner = null,
              lease_expires_at = null
          where id = v_job.id;
          v_skipped := v_skipped + 1;
        else
          update public.booking_reminder_jobs
          set status = 'enqueued',
              outbox_id = v_outbox_id,
              lease_owner = null,
              lease_expires_at = null
          where id = v_job.id;
          v_enqueued := v_enqueued + 1;
        end if;
      end if;
    exception
      when others then
        update public.booking_reminder_jobs
        set status = 'failed',
            last_error = left(
              pg_catalog.regexp_replace(sqlerrm, '[\r\n]+', ' ', 'g'),
              500
            ),
            lease_owner = null,
            lease_expires_at = null
        where id = v_job.id;
        v_failed := v_failed + 1;
    end;
  end loop;

  return pg_catalog.jsonb_build_object(
    'workerId', v_worker_id,
    'recovered', v_recovered,
    'missed', v_missed,
    'claimed', v_claimed,
    'enqueued', v_enqueued,
    'skipped', v_skipped,
    'failed', v_failed
  );
end;
$$;


ALTER FUNCTION "public"."run_booking_reminder_scheduler_v1"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_booking_reminder_scheduler_v1"("p_now" timestamp with time zone, "p_limit" integer) IS 'Claims due patient reminder jobs once per scheduler tick, revalidates booking/payment/version state and enqueues through the transactional email outbox.';



CREATE OR REPLACE FUNCTION "public"."save_patient_therapist_review_for_actor_v1"("p_actor_user_id" "uuid", "p_therapist_profile_id" "uuid", "p_action" "text", "p_rating" integer, "p_comment" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_patient public.patient_profiles%rowtype;
  v_booking_id uuid;
  v_review public.reviews;
  v_existing_request public.patient_review_mutation_requests%rowtype;
  v_comment text := btrim(coalesce(p_comment, ''));
  v_hash text;
  v_change_source text;
begin
  if p_actor_user_id is null or p_therapist_profile_id is null or p_request_id is null
    or p_action not in ('save', 'hide', 'publish')
    or char_length(v_comment) > 1000 then
    raise exception 'PATIENT_REVIEW_VALIDATION_ERROR' using errcode = '22023';
  end if;
  if p_action in ('save', 'publish') and (p_rating is null or p_rating not between 1 and 5) then
    raise exception 'PATIENT_REVIEW_VALIDATION_ERROR' using errcode = '22023';
  end if;

  select patient.* into v_patient
  from public.patient_profiles patient where patient.user_id = p_actor_user_id;
  if v_patient.id is null then
    raise exception 'PATIENT_REVIEW_PATIENT_REQUIRED' using errcode = '42501';
  end if;

  select booking.id into v_booking_id
  from public.bookings booking
  join public.session_participant_confirmations confirmation
    on confirmation.booking_id = booking.id
    and confirmation.participant_role = 'patient'::public.user_role
    and confirmation.outcome = 'completed'
  where booking.patient_profile_id = v_patient.id
    and booking.therapist_profile_id = p_therapist_profile_id
  order by confirmation.confirmed_at desc, booking.ends_at desc
  limit 1;
  if v_booking_id is null then
    raise exception 'PATIENT_REVIEW_RELATION_NOT_ELIGIBLE' using errcode = '42501';
  end if;

  v_hash := encode(extensions.digest(jsonb_build_object(
    'action', p_action,
    'comment', v_comment,
    'rating', p_rating,
    'therapistProfileId', p_therapist_profile_id
  )::text, 'sha256'), 'hex');

  select request.* into v_existing_request
  from public.patient_review_mutation_requests request
  where request.patient_profile_id = v_patient.id
    and request.request_id = p_request_id
  for update;
  if v_existing_request.id is not null then
    if v_existing_request.payload_hash <> v_hash then
      raise exception 'PATIENT_REVIEW_REQUEST_CONFLICT' using errcode = '23505';
    end if;
    select review.* into v_review from public.reviews review
    where review.id = v_existing_request.review_id;
    return jsonb_build_object(
      'idempotentReplay', true,
      'review', public.patient_review_payload_v1(v_review)
    );
  end if;

  select review.* into v_review
  from public.reviews review
  where review.patient_profile_id = v_patient.id
    and review.therapist_profile_id = p_therapist_profile_id
    and review.superseded_at is null
  for update;

  if p_action = 'hide' then
    if v_review.id is null then raise exception 'PATIENT_REVIEW_NOT_FOUND'; end if;
    perform set_config('tes.review_change_source', 'patient_hide', true);
    perform set_config('tes.review_actor_id', p_actor_user_id::text, true);
    update public.reviews
    set status = 'hidden', published_at = null, updated_at = now()
    where id = v_review.id returning * into v_review;
  elsif v_review.id is null then
    insert into public.reviews (
      booking_id, patient_profile_id, therapist_profile_id,
      rating, comment, status, published_at
    ) values (
      v_booking_id, v_patient.id, p_therapist_profile_id,
      p_rating, nullif(v_comment, ''), 'published', now()
    ) returning * into v_review;
  else
    v_change_source := case when p_action = 'publish'
      then 'patient_republish' else 'patient_edit' end;
    perform set_config('tes.review_change_source', v_change_source, true);
    perform set_config('tes.review_actor_id', p_actor_user_id::text, true);
    update public.reviews
    set booking_id = v_booking_id,
        rating = p_rating,
        comment = nullif(v_comment, ''),
        status = 'published',
        published_at = case when status = 'published' then published_at else now() end,
        updated_at = now()
    where id = v_review.id returning * into v_review;
  end if;

  insert into public.patient_review_mutation_requests (
    patient_profile_id, therapist_profile_id, request_id,
    action, payload_hash, review_id
  ) values (
    v_patient.id, p_therapist_profile_id, p_request_id,
    p_action, v_hash, v_review.id
  );

  return jsonb_build_object(
    'idempotentReplay', false,
    'review', public.patient_review_payload_v1(v_review)
  );
end;
$$;


ALTER FUNCTION "public"."save_patient_therapist_review_for_actor_v1"("p_actor_user_id" "uuid", "p_therapist_profile_id" "uuid", "p_action" "text", "p_rating" integer, "p_comment" "text", "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_patient_therapist_review_for_actor_v1"("p_actor_user_id" "uuid", "p_therapist_profile_id" "uuid", "p_action" "text", "p_rating" integer, "p_comment" "text", "p_request_id" "uuid") IS 'Creates, edits, hides or republishes one public review per patient-therapist relationship after a completed patient confirmation; never changes financial tables.';



CREATE OR REPLACE FUNCTION "public"."save_therapist_private_identity_v1"("p_document_type" "text", "p_document_number" "text", "p_postal_code" "text", "p_street" "text", "p_street_number" "text", "p_complement" "text", "p_neighborhood" "text", "p_city" "text", "p_state" "text", "p_country" "text" DEFAULT 'BR'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_profile_id uuid;
  v_document_type text := lower(btrim(coalesce(p_document_type, '')));
  v_document_number text := upper(regexp_replace(btrim(coalesce(p_document_number, '')), '[^0-9A-Za-z]', '', 'g'));
  v_postal_code text := regexp_replace(btrim(coalesce(p_postal_code, '')), '[^0-9]', '', 'g');
  v_country text := upper(btrim(coalesce(p_country, 'BR')));
  v_cpf_check_1 integer;
  v_cpf_check_2 integer;
begin
  select id into v_profile_id
  from public.therapist_profiles
  where user_id = auth.uid();

  if v_profile_id is null then
    raise exception 'therapist profile required' using errcode = '42501';
  end if;
  if v_document_type not in ('cpf', 'rg', 'passport') then
    raise exception 'invalid document type' using errcode = '22023';
  end if;
  if length(v_document_number) < 6 or length(v_document_number) > 20 then
    raise exception 'invalid document number' using errcode = '22023';
  end if;
  if v_document_type = 'cpf' then
    if v_document_number !~ '^[0-9]{11}$'
      or v_document_number ~ '^([0-9])\1{10}$'
    then
      raise exception 'invalid cpf' using errcode = '22023';
    end if;
    select case
      when mod(sum(substr(v_document_number, position, 1)::integer * (11 - position)), 11) < 2 then 0
      else 11 - mod(sum(substr(v_document_number, position, 1)::integer * (11 - position)), 11)
    end
    into v_cpf_check_1
    from generate_series(1, 9) as series(position);
    select case
      when mod(sum(substr(v_document_number, position, 1)::integer * (12 - position)), 11) < 2 then 0
      else 11 - mod(sum(substr(v_document_number, position, 1)::integer * (12 - position)), 11)
    end
    into v_cpf_check_2
    from generate_series(1, 10) as series(position);
    if v_cpf_check_1 <> substr(v_document_number, 10, 1)::integer
      or v_cpf_check_2 <> substr(v_document_number, 11, 1)::integer
    then
      raise exception 'invalid cpf' using errcode = '22023';
    end if;
  end if;
  if v_document_type = 'passport' and v_document_number !~ '^[A-Z0-9]{6,9}$' then
    raise exception 'invalid passport' using errcode = '22023';
  end if;
  if v_document_type = 'rg' and v_document_number !~ '^[0-9A-Z]{7,14}$' then
    raise exception 'invalid rg' using errcode = '22023';
  end if;
  if v_postal_code !~ '^[0-9]{8}$' then
    raise exception 'invalid postal code' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_street, ''))) not between 2 and 160
    or length(btrim(coalesce(p_street_number, ''))) not between 1 and 20
    or length(btrim(coalesce(p_neighborhood, ''))) not between 2 and 100
    or length(btrim(coalesce(p_city, ''))) not between 2 and 100
    or length(btrim(coalesce(p_state, ''))) not between 2 and 2
    or v_country <> 'BR'
  then
    raise exception 'invalid address' using errcode = '22023';
  end if;

  begin
    insert into public.therapist_private_identity (
      therapist_profile_id, document_type, document_number, postal_code,
      street, street_number, complement, neighborhood, city, state, country
    ) values (
      v_profile_id, v_document_type, v_document_number, v_postal_code,
      btrim(p_street), btrim(p_street_number), nullif(btrim(coalesce(p_complement, '')), ''),
      btrim(p_neighborhood), btrim(p_city), upper(btrim(p_state)), v_country
    )
    on conflict (therapist_profile_id) do update set
      document_type = excluded.document_type,
      document_number = excluded.document_number,
      postal_code = excluded.postal_code,
      street = excluded.street,
      street_number = excluded.street_number,
      complement = excluded.complement,
      neighborhood = excluded.neighborhood,
      city = excluded.city,
      state = excluded.state,
      country = excluded.country,
      updated_at = now();
  exception
    when unique_violation then
      if v_document_type = 'cpf' then
        raise exception 'CPF_ALREADY_IN_USE' using errcode = '23505';
      end if;
      raise;
  end;

  return public.get_therapist_private_identity_v1();
end;
$_$;


ALTER FUNCTION "public"."save_therapist_private_identity_v1"("p_document_type" "text", "p_document_number" "text", "p_postal_code" "text", "p_street" "text", "p_street_number" "text", "p_complement" "text", "p_neighborhood" "text", "p_city" "text", "p_state" "text", "p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_therapist_profile_draft_content_base_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_profile public.therapist_profiles%rowtype;
  v_payload jsonb;
  v_requested_photo_url text := nullif(btrim(coalesce(p_payload ->> 'photoUrl', '')), '');
  v_payload_hash text := encode(extensions.digest(coalesce(p_payload, '{}'::jsonb)::text, 'sha256'), 'hex');
  v_replay jsonb;
  v_content_id uuid;
  v_response jsonb;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);
  v_replay := public.therapist_profile_request_replay_m1(v_profile.id, p_request_id, 'save_draft', v_payload_hash);
  if v_replay is not null then
    return v_replay;
  end if;
  if p_expected_version <> v_profile.profile_version then
    raise exception 'VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  if v_requested_photo_url ~* '^http://[^[:space:]]+$'
    and v_profile.photo_url is distinct from v_requested_photo_url
    and not exists (
      select 1
      from public.therapist_profile_content_versions as content
      where content.therapist_profile_id = v_profile.id
        and content.status in ('draft', 'published')
        and content.profile_payload ->> 'photoUrl' = v_requested_photo_url
    )
  then
    raise exception 'VALIDATION_ERROR: photoUrl' using errcode = 'P0001';
  end if;

  v_payload := public.therapist_profile_validate_payload_m1(p_payload, v_profile.plan);
  insert into public.therapist_profile_content_versions (
    therapist_profile_id, status, short_intro, essence_body, invitation_body,
    video_url, video_provider, video_thumbnail_url, video_title,
    experience_years, profile_payload, base_profile_version
  ) values (
    v_profile.id, 'draft', v_payload ->> 'shortIntro',
    v_payload ->> 'essenceBody', v_payload ->> 'invitationBody',
    v_payload ->> 'videoUrl', v_payload ->> 'videoProvider',
    v_payload ->> 'videoThumbnailUrl', v_payload ->> 'videoTitle',
    nullif(v_payload ->> 'experienceYears', '')::integer,
    jsonb_strip_nulls(jsonb_build_object(
      'publicName', v_payload ->> 'publicName', 'headline', v_payload ->> 'headline',
      'bio', v_payload ->> 'bio', 'photoUrl', v_payload ->> 'photoUrl',
      'city', v_payload ->> 'city', 'state', v_payload ->> 'state'
    )), v_profile.profile_version
  )
  on conflict (therapist_profile_id) where status = 'draft'
  do update set
    short_intro = excluded.short_intro, essence_body = excluded.essence_body,
    invitation_body = excluded.invitation_body, video_url = excluded.video_url,
    video_provider = excluded.video_provider,
    video_thumbnail_url = excluded.video_thumbnail_url,
    video_title = excluded.video_title, experience_years = excluded.experience_years,
    profile_payload = excluded.profile_payload,
    base_profile_version = excluded.base_profile_version, updated_at = now()
  returning id into v_content_id;

  perform public.therapist_profile_replace_children_m1(
    v_content_id, v_payload -> 'guideItems', v_payload -> 'reflections'
  );
  insert into public.therapist_profile_events (
    therapist_profile_id, actor_user_id, event_type, request_id,
    previous_public_status, next_public_status, previous_version, next_version
  ) values (
    v_profile.id, p_actor_user_id, 'profile_draft_saved', p_request_id,
    v_profile.public_status, v_profile.public_status,
    v_profile.profile_version, v_profile.profile_version
  );
  v_response := jsonb_build_object(
    'contractVersion', 1, 'idempotentReplay', false,
    'editor', public.get_private_therapist_profile_editor_v1(p_actor_user_id)
  );
  return public.therapist_profile_store_request_m1(
    v_profile.id, p_request_id, 'save_draft', v_payload_hash, v_response
  );
end;
$_$;


ALTER FUNCTION "public"."save_therapist_profile_draft_content_base_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_therapist_profile_draft_content_base_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") IS 'SERVICE_ROLE_ONLY therapist profile draft command. Browser calls must go through therapist-profile-command.';



CREATE OR REPLACE FUNCTION "public"."save_therapist_profile_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_current_draft_theme text;
  v_theme text := coalesce(nullif(p_payload ->> 'publicProfileTheme', ''), 'serene');
  v_illustration text := nullif(p_payload ->> 'bioIllustrationId', '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_response jsonb;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);

  if v_theme not in (
    'ancestral',
    'aurora',
    'botanico',
    'celestial',
    'cristalino',
    'energia',
    'essencial_editorial',
    'essential',
    'frequencia',
    'geometria',
    'lunar',
    'natural',
    'oraculo',
    'profundo',
    'sagrado',
    'sereno_horizonte',
    'serene',
    'vinculos',
    'warm'
  ) then
    raise exception 'VALIDATION_ERROR: publicProfileTheme' using errcode = 'P0001';
  end if;

  if v_illustration is not null and v_illustration not in (
    'organic_flow',
    'gentle_horizon',
    'warm_layers',
    'essential_lines'
  ) then
    raise exception 'VALIDATION_ERROR: bioIllustrationId' using errcode = 'P0001';
  end if;

  if v_profile.plan = 'free' and v_theme in (
    'ancestral',
    'aurora',
    'botanico',
    'celestial',
    'cristalino',
    'energia',
    'essencial_editorial',
    'frequencia',
    'geometria',
    'lunar',
    'oraculo',
    'profundo',
    'sagrado',
    'sereno_horizonte',
    'vinculos'
  ) then
    select public_profile_theme
      into v_current_draft_theme
    from public.therapist_profile_content_versions
    where therapist_profile_id = v_profile.id
      and status = 'draft'
    order by updated_at desc
    limit 1;

    if v_profile.public_profile_theme in (
      'ancestral',
      'aurora',
      'botanico',
      'celestial',
      'cristalino',
      'energia',
      'essencial_editorial',
      'frequencia',
      'geometria',
      'lunar',
      'oraculo',
      'profundo',
      'sagrado',
      'sereno_horizonte',
      'vinculos'
    ) or v_current_draft_theme in (
      'ancestral',
      'aurora',
      'botanico',
      'celestial',
      'cristalino',
      'energia',
      'essencial_editorial',
      'frequencia',
      'geometria',
      'lunar',
      'oraculo',
      'profundo',
      'sagrado',
      'sereno_horizonte',
      'vinculos'
    ) then
      v_theme := 'serene';
    else
      raise exception 'CAPABILITY_NOT_ALLOWED: premium_profile_themes' using errcode = 'P0001';
    end if;
  end if;

  v_payload := jsonb_set(v_payload, '{publicProfileTheme}', to_jsonb(v_theme), true);

  v_response := public.save_therapist_profile_draft_content_base_v1(
    p_actor_user_id, p_request_id, p_expected_version, v_payload
  );
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);

  update public.therapist_profile_content_versions
  set public_profile_theme = v_theme,
      bio_illustration_id = v_illustration,
      updated_at = now()
  where therapist_profile_id = v_profile.id and status = 'draft';

  v_response := jsonb_set(v_response, '{editor}', public.get_private_therapist_profile_editor_v1(p_actor_user_id), true);
  update public.therapist_profile_mutation_requests
  set response = v_response
  where therapist_profile_id = v_profile.id and request_id = p_request_id and action = 'save_draft';
  return v_response;
end;
$$;


ALTER FUNCTION "public"."save_therapist_profile_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_therapist_profile_media_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_kind" "text", "p_media_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_draft public.therapist_profile_content_versions%rowtype;
  v_published public.therapist_profile_content_versions%rowtype;
  v_payload_hash text := encode(
    extensions.digest(
      p_expected_version::text || ':' || coalesce(p_kind, '') || ':' || coalesce(p_media_url, ''),
      'sha256'
    ),
    'hex'
  );
  v_replay jsonb;
  v_response jsonb;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);
  v_replay := public.therapist_profile_request_replay_m1(
    v_profile.id,
    p_request_id,
    'save_media_draft',
    v_payload_hash
  );
  if v_replay is not null then
    return v_replay;
  end if;

  if p_expected_version <> v_profile.profile_version then
    raise exception 'VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  if p_kind <> 'photo'
    or p_media_url is null
    or position(
      '/storage/v1/object/public/therapist-public-media/' ||
      p_actor_user_id::text || '/profile/photo-'
      in p_media_url
    ) = 0
  then
    raise exception 'VALIDATION_ERROR: photo_url' using errcode = 'P0001';
  end if;

  select *
    into v_draft
  from public.therapist_profile_content_versions
  where therapist_profile_id = v_profile.id
    and status = 'draft'
  order by updated_at desc
  limit 1
  for update;

  if v_draft.id is not null then
    update public.therapist_profile_content_versions
    set profile_payload = jsonb_set(
          coalesce(profile_payload, '{}'::jsonb),
          '{photoUrl}',
          to_jsonb(p_media_url),
          true
        ),
        updated_at = now()
    where id = v_draft.id;
  else
    select *
      into v_published
    from public.therapist_profile_content_versions
    where therapist_profile_id = v_profile.id
      and status = 'published'
    order by published_at desc nulls last, created_at desc
    limit 1;

    insert into public.therapist_profile_content_versions (
      therapist_profile_id,
      status,
      short_intro,
      essence_body,
      invitation_body,
      video_url,
      video_provider,
      video_thumbnail_url,
      video_title,
      experience_years,
      profile_payload,
      base_profile_version,
      public_profile_theme,
      bio_illustration_id
    )
    values (
      v_profile.id,
      'draft',
      v_published.short_intro,
      v_published.essence_body,
      v_published.invitation_body,
      v_published.video_url,
      v_published.video_provider,
      v_published.video_thumbnail_url,
      v_published.video_title,
      v_published.experience_years,
      jsonb_strip_nulls(
        coalesce(v_published.profile_payload, '{}'::jsonb) ||
        jsonb_build_object(
          'publicName', coalesce(v_profile.public_name, v_published.profile_payload ->> 'publicName'),
          'headline', coalesce(v_profile.headline, v_published.profile_payload ->> 'headline'),
          'bio', coalesce(v_profile.bio, v_published.profile_payload ->> 'bio'),
          'photoUrl', p_media_url,
          'city', coalesce(v_profile.city, v_published.profile_payload ->> 'city'),
          'state', coalesce(v_profile.state, v_published.profile_payload ->> 'state')
        )
      ),
      v_profile.profile_version,
      coalesce(v_published.public_profile_theme, v_profile.public_profile_theme, 'serene'),
      v_published.bio_illustration_id
    );
  end if;

  insert into public.therapist_profile_events (
    therapist_profile_id,
    actor_user_id,
    event_type,
    request_id,
    previous_public_status,
    next_public_status,
    previous_version,
    next_version,
    metadata
  )
  values (
    v_profile.id,
    p_actor_user_id,
    'profile_media_draft_saved',
    p_request_id,
    v_profile.public_status,
    v_profile.public_status,
    v_profile.profile_version,
    v_profile.profile_version,
    jsonb_build_object('kind', p_kind)
  );

  v_response := jsonb_build_object(
    'contractVersion', 1,
    'idempotentReplay', false,
    'editor', public.get_private_therapist_profile_editor_v1(p_actor_user_id)
  );

  return public.therapist_profile_store_request_m1(
    v_profile.id,
    p_request_id,
    'save_media_draft',
    v_payload_hash,
    v_response
  );
end;
$$;


ALTER FUNCTION "public"."save_therapist_profile_media_draft_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_kind" "text", "p_media_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_therapist_schedule_v1"("p_actor_user_id" "uuid", "p_expected_version" bigint, "p_timezone" "text", "p_rules" "jsonb", "p_service_settings" "jsonb", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_current_version bigint;
  v_resulting_version bigint;
  v_rule record;
  v_service_setting record;
  v_replayed_version bigint;
  v_replayed_timezone text;
begin
  if jsonb_typeof(p_rules) <> 'array'
    or jsonb_typeof(p_service_settings) <> 'array' then
    raise exception 'invalid_schedule_payload' using errcode = '22023';
  end if;

  if jsonb_array_length(p_rules) > 100
    or jsonb_array_length(p_service_settings) > 50 then
    raise exception 'schedule_payload_too_large' using errcode = '22023';
  end if;

  select therapist.*
    into v_therapist
  from public.profiles as profile
  join public.therapist_profiles as therapist
    on therapist.user_id = profile.id
  where profile.id = p_actor_user_id
    and profile.role = 'therapist';

  if not found then
    raise exception 'therapist_access_required' using errcode = '42501';
  end if;

  if v_therapist.status in ('suspended', 'rejected') then
    raise exception 'therapist_access_blocked' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'therapist-schedule:' || v_therapist.id::text,
      0
    )
  );

  select event.resulting_version, event.timezone
    into v_replayed_version, v_replayed_timezone
  from public.therapist_schedule_events as event
  where event.therapist_profile_id = v_therapist.id
    and event.request_id = p_request_id;

  if found then
    return jsonb_build_object(
      'scheduleVersion', v_replayed_version,
      'timezone', v_replayed_timezone,
      'idempotentReplay', true
    );
  end if;

  if not public.is_valid_timezone_v1(p_timezone) then
    raise exception 'invalid_schedule_timezone' using errcode = '22023';
  end if;

  insert into public.therapist_schedule_settings (
    therapist_profile_id,
    timezone
  )
  values (v_therapist.id, p_timezone)
  on conflict (therapist_profile_id) do nothing;

  select schedule_settings.version
    into v_current_version
  from public.therapist_schedule_settings as schedule_settings
  where schedule_settings.therapist_profile_id = v_therapist.id
  for update;

  if v_current_version <> p_expected_version then
    raise exception 'schedule_version_conflict' using errcode = 'P0001';
  end if;

  if exists (
    with parsed_rules as (
      select
        rule.ordinality,
        nullif(rule.value ->> 'serviceId', '')::uuid as service_id,
        (rule.value ->> 'dayOfWeek')::integer as day_of_week,
        (rule.value ->> 'startTime')::time as start_time,
        (rule.value ->> 'endTime')::time as end_time,
        coalesce((rule.value ->> 'isActive')::boolean, true) as is_active
      from jsonb_array_elements(p_rules) with ordinality
        as rule(value, ordinality)
    )
    select 1
    from parsed_rules as left_rule
    join parsed_rules as right_rule
      on left_rule.ordinality < right_rule.ordinality
      and left_rule.is_active
      and right_rule.is_active
      and left_rule.day_of_week = right_rule.day_of_week
      and left_rule.service_id = right_rule.service_id
      and left_rule.start_time < right_rule.end_time
      and right_rule.start_time < left_rule.end_time
  ) then
    raise exception 'overlapping_availability_rule' using errcode = '23P01';
  end if;

  for v_rule in
    select
      rule."id" as id,
      rule."serviceId" as service_id,
      rule."dayOfWeek" as day_of_week,
      rule."startTime" as start_time,
      rule."endTime" as end_time,
      coalesce(rule."isActive", true) as is_active
    from jsonb_to_recordset(p_rules) as rule(
      "id" uuid,
      "serviceId" uuid,
      "dayOfWeek" integer,
      "startTime" time,
      "endTime" time,
      "isActive" boolean
    )
  loop
    if v_rule.day_of_week is null
      or v_rule.day_of_week < 0
      or v_rule.day_of_week > 6
      or v_rule.start_time is null
      or v_rule.end_time is null
      or v_rule.start_time >= v_rule.end_time then
      raise exception 'invalid_availability_range' using errcode = '22023';
    end if;

    if v_rule.service_id is null
      or not exists (
        select 1
        from public.therapist_services as service
        where service.id = v_rule.service_id
          and service.therapist_profile_id = v_therapist.id
          and service.status <> 'archived'
      ) then
      raise exception 'schedule_service_forbidden' using errcode = '42501';
    end if;

    if v_rule.id is not null
      and exists (
        select 1
        from public.availability_rules as existing_rule
        where existing_rule.id = v_rule.id
          and existing_rule.therapist_profile_id <> v_therapist.id
      ) then
      raise exception 'schedule_rule_forbidden' using errcode = '42501';
    end if;
  end loop;

  for v_service_setting in
    select
      setting."serviceId" as service_id,
      setting."bufferBeforeMinutes" as buffer_before_minutes,
      setting."bufferAfterMinutes" as buffer_after_minutes,
      setting."minimumNoticeMinutes" as minimum_notice_minutes,
      setting."bookingHorizonDays" as booking_horizon_days,
      setting."slotStepMinutes" as slot_step_minutes
    from jsonb_to_recordset(p_service_settings) as setting(
      "serviceId" uuid,
      "bufferBeforeMinutes" integer,
      "bufferAfterMinutes" integer,
      "minimumNoticeMinutes" integer,
      "bookingHorizonDays" integer,
      "slotStepMinutes" integer
    )
  loop
    if v_service_setting.service_id is null
      or v_service_setting.buffer_before_minutes is null
      or v_service_setting.buffer_before_minutes <> 0
      or v_service_setting.buffer_after_minutes is null
      or v_service_setting.buffer_after_minutes < 0
      or v_service_setting.minimum_notice_minutes is null
      or v_service_setting.minimum_notice_minutes < 0
      or v_service_setting.booking_horizon_days is null
      or v_service_setting.booking_horizon_days < 1
      or v_service_setting.slot_step_minutes is null
      or v_service_setting.slot_step_minutes < 1 then
      raise exception 'invalid_service_booking_settings' using errcode = '22023';
    end if;

    if not exists (
      select 1
      from public.therapist_services as service
      where service.id = v_service_setting.service_id
        and service.therapist_profile_id = v_therapist.id
        and service.status <> 'archived'
    ) then
      raise exception 'schedule_service_forbidden' using errcode = '42501';
    end if;
  end loop;

  delete from public.availability_rules as existing_rule
  where existing_rule.therapist_profile_id = v_therapist.id
    and not exists (
      select 1
      from jsonb_to_recordset(p_rules) as incoming_rule("id" uuid)
      where incoming_rule."id" = existing_rule.id
    );

  for v_rule in
    select
      rule."id" as id,
      rule."serviceId" as service_id,
      rule."dayOfWeek" as day_of_week,
      rule."startTime" as start_time,
      rule."endTime" as end_time,
      coalesce(rule."isActive", true) as is_active
    from jsonb_to_recordset(p_rules) as rule(
      "id" uuid,
      "serviceId" uuid,
      "dayOfWeek" integer,
      "startTime" time,
      "endTime" time,
      "isActive" boolean
    )
  loop
    if v_rule.id is null then
      insert into public.availability_rules (
        therapist_profile_id,
        service_id,
        day_of_week,
        start_time,
        end_time,
        timezone,
        is_active
      )
      values (
        v_therapist.id,
        v_rule.service_id,
        v_rule.day_of_week,
        v_rule.start_time,
        v_rule.end_time,
        p_timezone,
        v_rule.is_active
      );
    else
      insert into public.availability_rules (
        id,
        therapist_profile_id,
        service_id,
        day_of_week,
        start_time,
        end_time,
        timezone,
        is_active
      )
      values (
        v_rule.id,
        v_therapist.id,
        v_rule.service_id,
        v_rule.day_of_week,
        v_rule.start_time,
        v_rule.end_time,
        p_timezone,
        v_rule.is_active
      )
      on conflict (id) do update
      set
        service_id = excluded.service_id,
        day_of_week = excluded.day_of_week,
        start_time = excluded.start_time,
        end_time = excluded.end_time,
        timezone = excluded.timezone,
        is_active = excluded.is_active,
        updated_at = now()
      where availability_rules.therapist_profile_id = v_therapist.id;
    end if;
  end loop;

  for v_service_setting in
    select
      setting."serviceId" as service_id,
      setting."bufferBeforeMinutes" as buffer_before_minutes,
      setting."bufferAfterMinutes" as buffer_after_minutes,
      setting."minimumNoticeMinutes" as minimum_notice_minutes,
      setting."bookingHorizonDays" as booking_horizon_days,
      setting."slotStepMinutes" as slot_step_minutes
    from jsonb_to_recordset(p_service_settings) as setting(
      "serviceId" uuid,
      "bufferBeforeMinutes" integer,
      "bufferAfterMinutes" integer,
      "minimumNoticeMinutes" integer,
      "bookingHorizonDays" integer,
      "slotStepMinutes" integer
    )
  loop
    insert into public.therapist_service_booking_settings (
      service_id,
      buffer_before_minutes,
      buffer_after_minutes,
      min_notice_minutes,
      max_days_ahead,
      interval_minutes
    )
    values (
      v_service_setting.service_id,
      v_service_setting.buffer_before_minutes,
      v_service_setting.buffer_after_minutes,
      v_service_setting.minimum_notice_minutes,
      v_service_setting.booking_horizon_days,
      v_service_setting.slot_step_minutes
    )
    on conflict (service_id) do update
    set
      buffer_before_minutes = excluded.buffer_before_minutes,
      buffer_after_minutes = excluded.buffer_after_minutes,
      min_notice_minutes = excluded.min_notice_minutes,
      max_days_ahead = excluded.max_days_ahead,
      interval_minutes = excluded.interval_minutes,
      updated_at = now();
  end loop;

  update public.therapist_schedule_settings as schedule_settings
  set
    timezone = p_timezone,
    version = schedule_settings.version + 1,
    updated_at = now()
  where schedule_settings.therapist_profile_id = v_therapist.id
  returning schedule_settings.version into v_resulting_version;

  -- Temporary compatibility projection for read models predating A3.
  update public.therapist_profiles as therapist
  set metadata = jsonb_set(
    therapist.metadata,
    '{timezone}',
    to_jsonb(p_timezone),
    true
  )
  where therapist.id = v_therapist.id;

  insert into public.therapist_schedule_events (
    therapist_profile_id,
    actor_user_id,
    event_type,
    request_id,
    previous_version,
    resulting_version,
    timezone,
    rule_count,
    service_settings_count
  )
  values (
    v_therapist.id,
    p_actor_user_id,
    'schedule_saved',
    p_request_id,
    v_current_version,
    v_resulting_version,
    p_timezone,
    jsonb_array_length(p_rules),
    jsonb_array_length(p_service_settings)
  );

  return jsonb_build_object(
    'scheduleVersion', v_resulting_version,
    'timezone', p_timezone,
    'idempotentReplay', false
  );
end;
$$;


ALTER FUNCTION "public"."save_therapist_schedule_v1"("p_actor_user_id" "uuid", "p_expected_version" bigint, "p_timezone" "text", "p_rules" "jsonb", "p_service_settings" "jsonb", "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_therapist_schedule_v1"("p_actor_user_id" "uuid", "p_expected_version" bigint, "p_timezone" "text", "p_rules" "jsonb", "p_service_settings" "jsonb", "p_request_id" "uuid") IS 'A3 atomic and idempotent schedule command restricted to trusted Edge Functions.';



CREATE OR REPLACE FUNCTION "public"."save_therapist_session_journey_themes_v1"("p_actor_user_id" "uuid", "p_booking_id" "uuid", "p_theme_keys" "text"[], "p_acknowledged" boolean, "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles;
  v_booking record;
  v_existing public.booking_journey_theme_selections;
  v_selection public.booking_journey_theme_selections;
  v_theme_keys text[];
  v_hash text;
  v_allowed_keys constant text[] := array[
    'self_knowledge',
    'emotional_wellbeing',
    'relationships_and_bonds',
    'communication',
    'personal_boundaries',
    'self_esteem_and_confidence',
    'routine_and_self_care',
    'habits_and_organization',
    'work_and_career',
    'purpose_and_life_projects',
    'family',
    'parenting',
    'partnership',
    'life_transitions',
    'body_and_presence',
    'other_topic'
  ];
begin
  if p_actor_user_id is null
    or p_booking_id is null
    or p_request_id is null
    or p_acknowledged is not true
    or cardinality(p_theme_keys) not between 1 and 3
    or public.is_unique_text_array(p_theme_keys) is not true
    or not (p_theme_keys <@ v_allowed_keys) then
    raise exception 'JOURNEY_THEME_VALIDATION_ERROR' using errcode = '22023';
  end if;

  select therapist.*
  into v_therapist
  from public.therapist_profiles therapist
  where therapist.user_id = p_actor_user_id
    and therapist.plan = 'premium_plus'::public.therapist_plan;

  if not found then
    raise exception 'JOURNEY_THEME_THERAPIST_PREMIUM_PLUS_REQUIRED' using errcode = '42501';
  end if;

  select booking.id, booking.patient_profile_id, booking.therapist_profile_id
  into v_booking
  from public.bookings booking
  join public.session_feedback feedback
    on feedback.booking_id = booking.id
   and feedback.author_role = 'therapist'::public.user_role
   and feedback.author_profile_id = p_actor_user_id
   and feedback.outcome = 'completed'
  join public.session_participant_confirmations confirmation
    on confirmation.booking_id = booking.id
   and confirmation.participant_role = 'therapist'::public.user_role
   and confirmation.outcome = 'completed'
  where booking.id = p_booking_id
    and booking.therapist_profile_id = v_therapist.id;

  if not found then
    raise exception 'JOURNEY_THEME_SESSION_NOT_ELIGIBLE' using errcode = '42501';
  end if;

  select array_agg(theme_key order by theme_key)
  into v_theme_keys
  from unnest(p_theme_keys) as item(theme_key);

  v_hash := encode(
    extensions.digest(
      concat_ws(
        '|',
        p_booking_id::text,
        p_actor_user_id::text,
        'journey_topics_v1',
        array_to_string(v_theme_keys, ','),
        'acknowledged'
      ),
      'sha256'
    ),
    'hex'
  );

  select selection.*
  into v_existing
  from public.booking_journey_theme_selections selection
  where selection.booking_id = p_booking_id
  for update;

  if v_existing.id is not null then
    if v_existing.payload_hash <> v_hash then
      raise exception 'JOURNEY_THEME_SELECTION_IMMUTABLE' using errcode = '23505';
    end if;

    return jsonb_build_object(
      'selection', public.booking_journey_theme_selection_payload(v_existing),
      'idempotentReplay', true
    );
  end if;

  insert into public.booking_journey_theme_selections (
    booking_id,
    therapist_profile_id,
    patient_profile_id,
    selected_by_profile_id,
    theme_keys,
    request_id,
    payload_hash
  ) values (
    p_booking_id,
    v_therapist.id,
    v_booking.patient_profile_id,
    p_actor_user_id,
    v_theme_keys,
    p_request_id,
    v_hash
  )
  returning * into v_selection;

  return jsonb_build_object(
    'selection', public.booking_journey_theme_selection_payload(v_selection),
    'idempotentReplay', false
  );
exception
  when unique_violation then
    select selection.*
    into v_existing
    from public.booking_journey_theme_selections selection
    where selection.booking_id = p_booking_id
    limit 1;

    if v_existing.id is not null and v_existing.payload_hash = v_hash then
      return jsonb_build_object(
        'selection', public.booking_journey_theme_selection_payload(v_existing),
        'idempotentReplay', true
      );
    end if;

    raise exception 'JOURNEY_THEME_SELECTION_IMMUTABLE' using errcode = '23505';
end;
$$;


ALTER FUNCTION "public"."save_therapist_session_journey_themes_v1"("p_actor_user_id" "uuid", "p_booking_id" "uuid", "p_theme_keys" "text"[], "p_acknowledged" boolean, "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_therapist_session_journey_themes_v1"("p_actor_user_id" "uuid", "p_booking_id" "uuid", "p_theme_keys" "text"[], "p_acknowledged" boolean, "p_request_id" "uuid") IS 'Service-role-only idempotent command for Premium Plus therapists after they confirm a completed session.';



CREATE OR REPLACE FUNCTION "public"."schedule_booking_reminder_jobs_v1"("p_booking_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_payment public.session_payments%rowtype;
  v_patient_user_id uuid;
  v_created integer := 0;
begin
  if p_booking_id is null or p_now is null then
    raise exception 'BOOKING_REMINDER_INVALID_SCHEDULE_REQUEST';
  end if;

  select *
    into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found or v_booking.status <> 'confirmed' or v_booking.starts_at <= p_now then
    return 0;
  end if;

  select *
    into v_payment
  from public.session_payments
  where booking_id = p_booking_id;

  if not found
    or v_payment.financial_status not in ('paid', 'partially_refunded')
    or v_payment.refund_pending
    or v_payment.disputed_at is not null
    or v_payment.internal_contested_at is not null
    or v_payment.admin_blocked_at is not null
  then
    return 0;
  end if;

  select patient.user_id
    into v_patient_user_id
  from public.patient_profiles patient
  where patient.id = v_booking.patient_profile_id;

  if v_patient_user_id is null then
    return 0;
  end if;

  insert into public.booking_reminder_jobs (
    booking_id,
    booking_version,
    action_key,
    recipient_user_id,
    scheduled_for
  )
  select
    v_booking.id,
    v_booking.version,
    reminder.action_key,
    v_patient_user_id,
    reminder.scheduled_for
  from (
    values
      (
        'booking_reminder_24h_patient'::text,
        v_booking.starts_at - interval '24 hours'
      ),
      (
        'booking_reminder_1h_patient'::text,
        v_booking.starts_at - interval '1 hour'
      )
  ) as reminder(action_key, scheduled_for)
  where reminder.scheduled_for > p_now
  on conflict (
    booking_id,
    booking_version,
    action_key,
    recipient_user_id
  ) do nothing;

  get diagnostics v_created = row_count;
  return v_created;
end;
$$;


ALTER FUNCTION "public"."schedule_booking_reminder_jobs_v1"("p_booking_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."schedule_booking_reminder_jobs_v1"("p_booking_id" "uuid", "p_now" timestamp with time zone) IS 'Creates strict-window patient reminder jobs atomically from a confirmed, financially eligible booking.';



CREATE OR REPLACE FUNCTION "public"."schedule_session_payment_v10"("p_session_payment_id" "uuid", "p_session_payment_setup_id" "uuid", "p_due_at" timestamp with time zone, "p_idempotency_key" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.session_payments%rowtype;
  v_setup public.session_payment_setups%rowtype;
  v_schedule public.session_payment_schedules%rowtype;
begin
  if p_session_payment_id is null
    or p_session_payment_setup_id is null
    or p_due_at is null
    or nullif(trim(p_idempotency_key), '') is null
    or nullif(trim(p_request_fingerprint), '') is null
  then
    raise exception 'SESSION_PAYMENT_SCHEDULE_V10_INVALID'
      using errcode = '22023';
  end if;

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.id = p_session_payment_id
  for update;

  if not found
    or v_payment.payment_flow_version <> 'v10'
    or v_payment.financial_status not in ('pending', 'processing')
    or v_payment.payment_due_at is distinct from p_due_at
  then
    raise exception 'SESSION_PAYMENT_V10_NOT_SCHEDULABLE'
      using errcode = '23514';
  end if;

  select setup.*
  into v_setup
  from public.session_payment_setups as setup
  where setup.id = p_session_payment_setup_id
    and setup.session_payment_id = v_payment.id
    and setup.booking_id = v_payment.booking_id
    and setup.status = 'succeeded'
    and setup.superseded_at is null;

  if not found then
    raise exception 'SESSION_PAYMENT_SETUP_V10_NOT_READY'
      using errcode = '23514';
  end if;

  select schedule.*
  into v_schedule
  from public.session_payment_schedules as schedule
  where schedule.stripe_environment = v_setup.stripe_environment
    and schedule.idempotency_key = trim(p_idempotency_key)
  for update;

  if found and (
    v_schedule.session_payment_id <> v_payment.id
    or v_schedule.session_payment_setup_id <> v_setup.id
    or v_schedule.request_fingerprint <> trim(p_request_fingerprint)
  ) then
    raise exception 'SESSION_PAYMENT_SCHEDULE_V10_IDEMPOTENCY_CONFLICT'
      using errcode = '23505';
  end if;

  if not found then
    insert into public.session_payment_schedules (
      booking_id,
      booking_version,
      session_payment_id,
      session_payment_setup_id,
      stripe_environment,
      due_at,
      idempotency_key,
      request_fingerprint
    )
    values (
      v_payment.booking_id,
      v_setup.booking_version,
      v_payment.id,
      v_setup.id,
      v_setup.stripe_environment,
      p_due_at,
      trim(p_idempotency_key),
      trim(p_request_fingerprint)
    )
    returning * into v_schedule;
  end if;

  return jsonb_build_object(
    'scheduleId', v_schedule.id,
    'bookingId', v_schedule.booking_id,
    'dueAt', v_schedule.due_at,
    'status', v_schedule.status
  );
end;
$$;


ALTER FUNCTION "public"."schedule_session_payment_v10"("p_session_payment_id" "uuid", "p_session_payment_setup_id" "uuid", "p_due_at" timestamp with time zone, "p_idempotency_key" "text", "p_request_fingerprint" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "sender_profile_id" "uuid",
    "body" "text" NOT NULL,
    "read_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "template_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "messages_body_not_blank" CHECK (("length"(TRIM(BOTH FROM "body")) > 0)),
    CONSTRAINT "messages_metadata_object_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text"))
);


ALTER TABLE "public"."messages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."messages"."template_id" IS 'Template server-resolved for structured participant messages. Legacy rows may remain null.';



COMMENT ON COLUMN "public"."messages"."metadata" IS 'Server-resolved structured metadata, including an optional allowlisted CTA.';



CREATE OR REPLACE FUNCTION "public"."send_structured_participant_message_v1"("p_conversation_id" "uuid", "p_template_key" "text") RETURNS "public"."messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return public.send_structured_participant_message_v2(
    p_conversation_id,
    p_template_key,
    null,
    '{}'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."send_structured_participant_message_v1"("p_conversation_id" "uuid", "p_template_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_structured_participant_message_v1"("p_conversation_id" "uuid", "p_template_key" "text") IS 'Authenticated participant boundary: derives identity and direction, resolves an approved template body, and never accepts a browser-supplied body.';



CREATE OR REPLACE FUNCTION "public"."send_structured_participant_message_v2"("p_conversation_id" "uuid", "p_template_key" "text", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_parameters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_resolved jsonb;
  v_message public.messages%rowtype;
begin
  v_resolved := public.resolve_structured_participant_message_v2(
    p_conversation_id,
    p_template_key,
    p_booking_id,
    p_parameters
  );

  insert into public.messages (
    conversation_id,
    sender_profile_id,
    template_id,
    body,
    metadata
  )
  values (
    p_conversation_id,
    (v_resolved->>'actorId')::uuid,
    (v_resolved->>'templateId')::uuid,
    v_resolved->>'body',
    jsonb_build_object(
      'category', v_resolved->'category',
      'cta', v_resolved->'cta',
      'parameters', v_resolved->'parameters',
      'templateKey', v_resolved->'templateKey'
    )
  )
  returning * into v_message;

  return v_message;
end;
$$;


