    "outcome" "text" NOT NULL,
    "source" "text" NOT NULL,
    "confirmed_by_profile_id" "uuid",
    "request_id" "uuid" NOT NULL,
    "payload_hash" "text" NOT NULL,
    "due_at" timestamp with time zone NOT NULL,
    "confirmed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "policy_version_id" "uuid" NOT NULL,
    CONSTRAINT "session_participant_confirmations_outcome_check" CHECK (("outcome" = ANY (ARRAY['completed'::"text", 'not_performed'::"text"]))),
    CONSTRAINT "session_participant_confirmations_role_check" CHECK (("participant_role" = ANY (ARRAY['patient'::"public"."user_role", 'therapist'::"public"."user_role"]))),
    CONSTRAINT "session_participant_confirmations_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'automatic'::"text"])))
);


