    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "author_profile_id" "uuid" NOT NULL,
    "author_role" "public"."user_role" NOT NULL,
    "outcome" "text" NOT NULL,
