    CONSTRAINT "session_feedback_comment_length_check" CHECK (("char_length"("comment") <= 500)),
    CONSTRAINT "session_feedback_outcome_check" CHECK (("outcome" = ANY (ARRAY['completed'::"text", 'not_performed'::"text"]))),
