    CONSTRAINT "session_feedback_reason_check" CHECK ((("not_performed_reason" IS NULL) OR ("not_performed_reason" = ANY (ARRAY['patient_absent'::"text", 'therapist_absent'::"text", 'internet_problem'::"text", 'audio_video_problem'::"text", 'rescheduled'::"text", 'late_cancellation'::"text", 'other'::"text"])))),
    CONSTRAINT "session_feedback_shape_check" CHECK (((("outcome" = 'completed'::"text") AND ("rating" IS NOT NULL) AND ("not_performed_reason" IS NULL)) OR (("outcome" = 'not_performed'::"text") AND ("rating" IS NULL) AND ("not_performed_reason" IS NOT NULL))))
);


