CREATE OR REPLACE FUNCTION "public"."store_therapist_service_request_v1"("p_therapist_profile_id" "uuid", "p_request_id" "uuid", "p_operation" "text", "p_payload_hash" "text", "p_service_id" "uuid", "p_response" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_existing public.therapist_service_mutation_requests%rowtype;
begin
  select *
    into v_existing
  from public.therapist_service_mutation_requests
  where therapist_profile_id = p_therapist_profile_id
    and request_id = p_request_id
  for update;

  if found then
    if v_existing.operation <> p_operation
      or v_existing.payload_hash <> p_payload_hash then
      raise exception 'THERAPIST_SERVICE_IDEMPOTENCY_CONFLICT'
        using errcode = 'P0001';
    end if;

    return jsonb_set(v_existing.response, '{idempotentReplay}', 'true'::jsonb, true);
  end if;

  insert into public.therapist_service_mutation_requests (
    therapist_profile_id,
    request_id,
    operation,
    payload_hash,
    service_id,
    response
  )
  values (
    p_therapist_profile_id,
    p_request_id,
    p_operation,
    p_payload_hash,
    p_service_id,
    p_response
  );

  return p_response;
end;
$$;


ALTER FUNCTION "public"."store_therapist_service_request_v1"("p_therapist_profile_id" "uuid", "p_request_id" "uuid", "p_operation" "text", "p_payload_hash" "text", "p_service_id" "uuid", "p_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_session_feedback_for_actor_v1"("p_actor_user_id" "uuid", "p_booking_id" "uuid", "p_outcome" "text", "p_rating" smallint, "p_not_performed_reason" "text", "p_comment" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_role public.user_role;
  v_existing public.session_feedback;
  v_feedback public.session_feedback;
  v_comment text := btrim(coalesce(p_comment, ''));
  v_hash text;
  v_confirmation jsonb;
  v_participant_confirmation public.session_participant_confirmations;
  v_ends_at timestamptz;
begin
  if p_actor_user_id is null or p_booking_id is null or p_request_id is null then
    raise exception 'FEEDBACK_VALIDATION_ERROR' using errcode = '22023';
  end if;

  select case
      when patient_profiles.user_id = p_actor_user_id then 'patient'::public.user_role
      when therapist_profiles.user_id = p_actor_user_id then 'therapist'::public.user_role
      else null
    end,
    bookings.ends_at
  into v_actor_role, v_ends_at
  from public.bookings
  left join public.patient_profiles on patient_profiles.id = bookings.patient_profile_id
  left join public.therapist_profiles on therapist_profiles.id = bookings.therapist_profile_id
  where bookings.id = p_booking_id;

  if v_actor_role is null then
    raise exception 'FEEDBACK_PARTICIPANT_REQUIRED' using errcode = '42501';
  end if;
  if now() < v_ends_at then
    raise exception 'FEEDBACK_SESSION_NOT_ENDED' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.session_payments payment
    where payment.booking_id = p_booking_id
      and payment.financial_status in ('paid', 'partially_refunded')
      and payment.refund_pending = false
      and payment.disputed_at is null
      and payment.admin_blocked_at is null
  ) then
    raise exception 'FEEDBACK_SESSION_NOT_ELIGIBLE' using errcode = '42501';
  end if;

  if p_outcome not in ('completed', 'not_performed')
    or char_length(v_comment) > 500 then
    raise exception 'FEEDBACK_VALIDATION_ERROR' using errcode = '22023';
  end if;
  if p_outcome = 'completed' then
    if p_rating is null or p_rating not between 1 and 5
      or p_not_performed_reason is not null then
      raise exception 'FEEDBACK_VALIDATION_ERROR' using errcode = '22023';
    end if;
  elsif p_rating is not null
    or p_not_performed_reason is null
    or p_not_performed_reason not in (
      'patient_absent', 'therapist_absent', 'internet_problem',
      'audio_video_problem', 'rescheduled', 'late_cancellation', 'other'
    ) then
    raise exception 'FEEDBACK_VALIDATION_ERROR' using errcode = '22023';
  end if;

  v_hash := encode(
    extensions.digest(
      concat_ws('|', p_booking_id::text, v_actor_role::text, p_outcome,
        coalesce(p_rating::text, ''), coalesce(p_not_performed_reason, ''), v_comment),
      'sha256'
    ),
    'hex'
  );

  select feedback.* into v_existing
  from public.session_feedback feedback
  where feedback.booking_id = p_booking_id
    and feedback.author_role = v_actor_role
  for update;

  if v_existing.id is not null then
    if v_existing.payload_hash <> v_hash then
      raise exception 'FEEDBACK_REQUEST_CONFLICT' using errcode = '23505';
    end if;
    return jsonb_build_object(
      'confirmation', public.session_feedback_confirmation_payload(p_booking_id, v_actor_role),
      'feedback', public.session_feedback_payload(v_existing),
      'idempotentReplay', true
    );
  end if;

  insert into public.session_feedback (
    author_profile_id, author_role, booking_id, comment,
    not_performed_reason, outcome, payload_hash, rating, request_id
  ) values (
    p_actor_user_id, v_actor_role, p_booking_id, v_comment,
    p_not_performed_reason, p_outcome, v_hash, p_rating, p_request_id
  )
  returning * into v_feedback;

  select confirmation.* into v_participant_confirmation
  from public.session_participant_confirmations confirmation
  where confirmation.booking_id = p_booking_id
    and confirmation.participant_role = v_actor_role
  for update;

  if v_participant_confirmation.id is null then
    v_confirmation := public.record_session_participant_confirmation_v1(
      p_actor_user_id, p_booking_id, p_outcome, p_request_id, 'manual', now()
    );
  else
    v_confirmation := jsonb_build_object(
      'confirmation', jsonb_build_object(
        'confirmedAt', v_participant_confirmation.confirmed_at,
        'dueAt', v_participant_confirmation.due_at,
        'outcome', v_participant_confirmation.outcome,
        'source', v_participant_confirmation.source
      ),
      'idempotentReplay', true
    );
  end if;

  if p_outcome = 'completed' then
    perform public.finalize_bilateral_session_confirmation_v1(p_booking_id, now());
  else
    update public.session_payments
    set service_status = 'not_performed',
        service_confirmed_at = null,
        service_confirmation_source = null,
        eligible_at = null,
        transfer_status = case
          when transfer_status in ('batched', 'transfer_pending', 'transferred') then transfer_status
          else 'blocked'::public.session_transfer_status
        end,
        transfer_blocked_reason = 'participant_reported_not_performed',
        internal_contested_at = coalesce(internal_contested_at, now()),
        updated_at = now()
    where booking_id = p_booking_id
      and transfer_status <> 'transferred';
  end if;

  return jsonb_build_object(
    'confirmation', v_confirmation -> 'confirmation',
    'feedback', public.session_feedback_payload(v_feedback),
    'idempotentReplay', false
  );
exception
  when unique_violation then
    select feedback.* into v_existing
    from public.session_feedback feedback
    where feedback.booking_id = p_booking_id
      and feedback.author_role = v_actor_role
    limit 1;
    if v_existing.id is not null and v_existing.payload_hash = v_hash then
      return jsonb_build_object(
        'confirmation', public.session_feedback_confirmation_payload(p_booking_id, v_actor_role),
        'feedback', public.session_feedback_payload(v_existing),
        'idempotentReplay', true
      );
    end if;
    raise exception 'FEEDBACK_REQUEST_CONFLICT' using errcode = '23505';
end;
$$;


ALTER FUNCTION "public"."submit_session_feedback_for_actor_v1"("p_actor_user_id" "uuid", "p_booking_id" "uuid", "p_outcome" "text", "p_rating" smallint, "p_not_performed_reason" "text", "p_comment" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_therapy_catalog_request_v1"("p_actor_user_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.profiles;
  v_therapist_profile_id uuid;
  v_request_id uuid;
  v_name text := trim(coalesce(p_payload->>'informedName', ''));
begin
  select * into v_profile
  from public.profiles
  where id = p_actor_user_id
    and role = 'therapist';

  if v_profile.id is null then
    raise exception 'THERAPY_CATALOG_REQUEST_THERAPIST_REQUIRED';
  end if;

  if char_length(v_name) < 2 or char_length(v_name) > 120 then
    raise exception 'THERAPY_CATALOG_REQUEST_INVALID_PAYLOAD';
  end if;

  select id into v_therapist_profile_id
  from public.therapist_profiles
  where user_id = p_actor_user_id
  limit 1;

  insert into public.therapy_catalog_requests (
    requester_profile_id,
    requester_therapist_profile_id,
    informed_name,
    description,
    suggested_category_id,
    justification
  )
  values (
    p_actor_user_id,
    v_therapist_profile_id,
    v_name,
    nullif(p_payload->>'description', ''),
    nullif(p_payload->>'suggestedCategoryId', '')::uuid,
    nullif(p_payload->>'justification', '')
  )
  returning id into v_request_id;

  insert into public.therapy_catalog_events (
    actor_profile_id,
    actor_role,
    entity_type,
    entity_id,
    event_type,
    next_state
  )
  values (
    v_profile.id,
    v_profile.role,
    'therapy_catalog_request',
    v_request_id,
    'therapy_request_submitted',
    jsonb_build_object('status', 'submitted', 'informedName', v_name)
  );

  return jsonb_build_object(
    'contractVersion', 1,
    'requestId', v_request_id,
    'status', 'submitted'
  );
end;
$$;


ALTER FUNCTION "public"."submit_therapy_catalog_request_v1"("p_actor_user_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_therapy_catalog_request_v2"("p_actor_user_id" "uuid", "p_payload" "jsonb", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_profile public.profiles;
  v_therapist_profile_id uuid;
  v_existing public.therapy_catalog_requests;
  v_request public.therapy_catalog_requests;
  v_name text := trim(coalesce(p_payload->>'informedName', ''));
  v_submission jsonb := coalesce(p_payload->'submission', '{}'::jsonb);
  v_description text := nullif(trim(coalesce(v_submission->>'description', '')), '');
  v_objective text := nullif(trim(coalesce(v_submission->>'objective', '')), '');
  v_use_cases text := nullif(trim(coalesce(v_submission->>'useCases', '')), '');
  v_process text := nullif(trim(coalesce(v_submission->>'sessionProcess', '')), '');
  v_theme_source jsonb := coalesce(p_payload->'themeIds', v_submission->'themeIds', '[]'::jsonb);
  v_theme_ids uuid[] := '{}'::uuid[];
  v_theme_names text[] := '{}'::text[];
  v_theme_input_count integer := 0;
  v_valid_theme_count integer := 0;
begin
  select * into v_profile
  from public.profiles
  where id = p_actor_user_id and role = 'therapist';

  if v_profile.id is null then
    raise exception 'THERAPY_CATALOG_REQUEST_THERAPIST_REQUIRED';
  end if;

  select * into v_existing
  from public.therapy_catalog_requests
  where requester_profile_id = p_actor_user_id
    and client_request_id = p_request_id;

  if v_existing.id is not null then
    return jsonb_build_object(
      'contractVersion', 2,
      'idempotentReplay', true,
      'requestId', v_existing.id,
      'status', v_existing.status
    );
  end if;

  if jsonb_typeof(v_theme_source) <> 'array' then
    raise exception 'THERAPY_CATALOG_REQUEST_INVALID_PAYLOAD';
  end if;

  with raw as (
    select trim(value) as id_text
    from jsonb_array_elements_text(v_theme_source) value
  ), validated as (
    select distinct id_text::uuid as id
    from raw
    where id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  )
  select
    (select count(*) from raw),
    coalesce(array_agg(theme.id order by theme.sort_order, theme.name), '{}'::uuid[]),
    coalesce(array_agg(theme.name order by theme.sort_order, theme.name), '{}'::text[]),
    count(theme.id)::integer
  into v_theme_input_count, v_theme_ids, v_theme_names, v_valid_theme_count
  from validated
  join public.matching_themes theme on theme.id = validated.id and theme.is_active;

  if p_request_id is null
    or char_length(v_name) not between 2 and 120
    or v_description is null
    or v_objective is null
    or v_use_cases is null
    or v_process is null
    or v_theme_input_count not between 1 and 3
    or v_valid_theme_count <> v_theme_input_count then
    raise exception 'THERAPY_CATALOG_REQUEST_INVALID_PAYLOAD';
  end if;

  v_submission := jsonb_set(v_submission, '{themeIds}', to_jsonb(v_theme_ids), true);
  v_submission := jsonb_set(v_submission, '{themeNames}', to_jsonb(v_theme_names), true);

  select id into v_therapist_profile_id
  from public.therapist_profiles
  where user_id = p_actor_user_id
  limit 1;

  insert into public.therapy_catalog_requests (
    requester_profile_id,
    requester_therapist_profile_id,
    client_request_id,
    informed_name,
    description,
    justification,
    submission,
    submission_version,
    status
  ) values (
    p_actor_user_id,
    v_therapist_profile_id,
    p_request_id,
    v_name,
    v_description,
    v_objective,
    v_submission,
    2,
    'submitted'
  )
  returning * into v_request;

  insert into public.therapy_catalog_events (
    actor_profile_id, actor_role, entity_type, entity_id, event_type, next_state, request_id
  ) values (
    v_profile.id,
    v_profile.role,
    'therapy_catalog_request',
    v_request.id,
    'therapy_request_submitted',
    jsonb_build_object('status', 'submitted', 'informedName', v_name),
    p_request_id
  );

  insert into public.notifications (profile_id, kind, title, body, href)
  values (
    p_actor_user_id,
    'therapy_catalog_request',
    'Solicitação recebida',
    'Recebemos sua sugestão de terapia. Você será avisado quando houver uma atualização.',
    '/terapeuta/mensagens/solicitar-terapia?request=' || v_request.id::text
  );

  return jsonb_build_object(
    'contractVersion', 2,
    'idempotentReplay', false,
    'requestId', v_request.id,
    'status', v_request.status
  );
end;
$_$;


ALTER FUNCTION "public"."submit_therapy_catalog_request_v2"("p_actor_user_id" "uuid", "p_payload" "jsonb", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_current_requester_role_v1"() RETURNS "public"."user_role"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role public.user_role;
begin
  if auth.uid() is null then
    raise exception 'authenticated requester required' using errcode = '42501';
  end if;

  select role
    into v_role
  from public.profiles
  where id = auth.uid()
    and role in ('patient'::public.user_role, 'therapist'::public.user_role);

  if not found then
    raise exception 'authenticated requester required' using errcode = '42501';
  end if;

  return v_role;
end;
$$;


ALTER FUNCTION "public"."support_current_requester_role_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_plain_text_v1"("p_value" "text", "p_min_length" integer, "p_max_length" integer, "p_field_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_value text;
begin
  v_value := btrim(regexp_replace(coalesce(p_value, ''), '[[:cntrl:]]+', ' ', 'g'));
  v_value := regexp_replace(v_value, '[[:space:]]+', ' ', 'g');

  if length(v_value) < p_min_length or length(v_value) > p_max_length then
    raise exception '% length is invalid', p_field_name using errcode = '22023';
  end if;

  if v_value ~ '<[^>]+>' then
    raise exception '% must be plain text', p_field_name using errcode = '22023';
  end if;

  return v_value;
end;
$$;


ALTER FUNCTION "public"."support_plain_text_v1"("p_value" "text", "p_min_length" integer, "p_max_length" integer, "p_field_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_ticket_protocol_suffix_v1"("p_category" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_category
    when 'agenda_sessoes' then 'A'
    when 'zoom_acesso' then 'Z'
    when 'pagamentos' then 'P'
    when 'financeiro_repasses' then 'F'
    when 'plano_assinatura' then 'S'
    when 'perfil_verificacao' then 'V'
    when 'conta_acesso' then 'C'
    else 'O'
  end
$$;


ALTER FUNCTION "public"."support_ticket_protocol_suffix_v1"("p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_ticket_protocol_v1"("p_category" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_protocol text;
begin
  -- Serializa apenas a alocação do identificador curto para eliminar a pequena
  -- janela de colisão entre a checagem e o insert.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('support_ticket_protocol_v1')
  );

  loop
    v_protocol := pg_catalog.lpad(
      pg_catalog.floor(pg_catalog.random() * 1000000000)::bigint::text,
      9,
      '0'
    ) || public.support_ticket_protocol_suffix_v1(p_category);

    exit when not exists (
      select 1
      from public.support_tickets
      where protocol = v_protocol
    );
  end loop;

  return v_protocol;
end;
$$;


ALTER FUNCTION "public"."support_ticket_protocol_v1"("p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_validate_ticket_attachments_v1"("p_ticket_id" "uuid", "p_message_id" "uuid", "p_attachments" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attachment jsonb;
  v_path text;
  v_name text;
  v_mime text;
  v_size integer;
begin
  if p_attachments is null or jsonb_typeof(p_attachments) <> 'array' then
    raise exception 'support attachments are invalid' using errcode = '22023';
  end if;
  if jsonb_array_length(p_attachments) > 5 then
    raise exception 'support attachment limit reached' using errcode = '22023';
  end if;

  for v_attachment in select value from jsonb_array_elements(p_attachments)
  loop
    v_path := nullif(btrim(v_attachment->>'storageObjectPath'), '');
    v_name := nullif(btrim(v_attachment->>'originalName'), '');
    v_mime := nullif(btrim(v_attachment->>'mimeType'), '');
    v_size := nullif(v_attachment->>'sizeBytes', '')::integer;

    if v_path is null or v_name is null or v_mime is null or v_size is null
      or length(v_name) > 160
      or v_size < 1 or v_size > 10485760
      or v_mime not in ('application/pdf', 'image/jpeg', 'image/png', 'image/webp')
      or v_path not like p_ticket_id::text || '/%'
      or v_path like '%..%'
      or not exists (
        select 1 from storage.objects
        where storage.objects.bucket_id = 'support-ticket-attachments'
          and storage.objects.name = v_path
      )
    then
      raise exception 'support attachment metadata is invalid' using errcode = '22023';
    end if;

    insert into public.support_ticket_message_attachments (
      ticket_id,
      message_id,
      storage_object_path,
      original_name,
      mime_type,
      size_bytes
    )
    values (
      p_ticket_id,
      p_message_id,
      v_path,
      v_name,
      v_mime,
      v_size
    )
    on conflict (storage_object_path) do nothing;
  end loop;
end;
$$;


ALTER FUNCTION "public"."support_validate_ticket_attachments_v1"("p_ticket_id" "uuid", "p_message_id" "uuid", "p_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_session_payment_checkout_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_expected_checkout_session_id" "text", "p_new_checkout_session_id" "text", "p_original_amount_cents" integer, "p_discount_amount_cents" integer, "p_total_amount_cents" integer, "p_checkout_timing" "text", "p_promotion_code" "text" DEFAULT NULL::"text", "p_stripe_promotion_code_id" "text" DEFAULT NULL::"text", "p_stripe_coupon_id" "text" DEFAULT NULL::"text", "p_discount_type" "text" DEFAULT NULL::"text", "p_discount_value" integer DEFAULT NULL::integer, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_existing_reservation public.session_promotion_reservations%rowtype;
  v_existing_reservation_found boolean := false;
  v_payment public.session_payments%rowtype;
  v_snapshot record;
  v_has_promotion boolean;
begin
  v_has_promotion := nullif(trim(p_promotion_code), '') is not null;

  if p_session_payment_id is null
    or p_booking_version is null or p_booking_version <= 0
    or p_stripe_environment not in ('test', 'live')
    or nullif(trim(p_new_checkout_session_id), '') is null
    or p_original_amount_cents is null or p_original_amount_cents < 0
    or p_discount_amount_cents is null or p_discount_amount_cents < 0
    or p_total_amount_cents is null or p_total_amount_cents < 0
    or p_original_amount_cents <> p_discount_amount_cents + p_total_amount_cents
    or p_checkout_timing not in ('scheduled', 'immediate')
    or (
      v_has_promotion and (
        nullif(trim(p_stripe_promotion_code_id), '') is null
        or nullif(trim(p_stripe_coupon_id), '') is null
        or p_discount_type not in ('percent', 'fixed_amount')
        or p_discount_value is null or p_discount_value < 0
        or nullif(trim(p_idempotency_key), '') is null
      )
    )
    or (
      not v_has_promotion and (
        p_stripe_promotion_code_id is not null
        or p_stripe_coupon_id is not null
        or p_discount_type is not null
        or p_discount_value is not null
      )
    )
  then
    raise exception 'SESSION_PAYMENT_V10_CHECKOUT_SWAP_INVALID'
      using errcode = '22023';
  end if;

  select payment.*
  into v_payment
  from public.session_payments as payment
  where payment.id = p_session_payment_id
  for update;

  if not found
    or v_payment.payment_flow_version <> 'v10'
    or v_payment.financial_status <> 'pending'
  then
    raise exception 'SESSION_PAYMENT_V10_NOT_REPLACEABLE'
      using errcode = '23514';
  end if;

  select booking.*
  into v_booking
  from public.bookings as booking
  where booking.id = v_payment.booking_id
  for update;

  if not found
    or v_booking.version <> p_booking_version
    or v_booking.service_price_cents_snapshot <> p_original_amount_cents
  then
    raise exception 'SESSION_PAYMENT_BOOKING_VERSION_MISMATCH'
      using errcode = '23514';
  end if;

  if v_payment.stripe_checkout_session_id is distinct from p_new_checkout_session_id
    and v_payment.stripe_checkout_session_id is distinct from p_expected_checkout_session_id
  then
    raise exception 'SESSION_PAYMENT_V10_CHECKOUT_SWAP_CONFLICT'
      using errcode = 'P0001';
  end if;

  if v_has_promotion then
    select reservation.*
    into v_existing_reservation
    from public.session_promotion_reservations as reservation
    where reservation.stripe_environment = p_stripe_environment
      and reservation.idempotency_key = trim(p_idempotency_key)
    for update;
    v_existing_reservation_found := found;

    if v_existing_reservation_found and (
      v_existing_reservation.booking_id <> v_booking.id
      or v_existing_reservation.booking_version <> p_booking_version
      or v_existing_reservation.session_payment_id <> v_payment.id
      or v_existing_reservation.stripe_promotion_code_id <> trim(p_stripe_promotion_code_id)
      or v_existing_reservation.stripe_coupon_id <> trim(p_stripe_coupon_id)
      or v_existing_reservation.subtotal_cents <> p_original_amount_cents
      or v_existing_reservation.discount_cents <> p_discount_amount_cents
      or v_existing_reservation.total_cents <> p_total_amount_cents
    ) then
      raise exception 'SESSION_PROMOTION_RESERVATION_IDEMPOTENCY_CONFLICT'
        using errcode = '23505';
    end if;

    update public.session_promotion_reservations
    set status = 'released',
        released_at = coalesce(released_at, now()),
        updated_at = now()
    where booking_id = v_booking.id
      and booking_version = p_booking_version
      and status in ('reserved', 'consumed')
      and (
        not v_existing_reservation_found
        or id <> v_existing_reservation.id
      );

    if not v_existing_reservation_found then
      insert into public.session_promotion_reservations (
        booking_id,
        booking_version,
        session_payment_id,
        stripe_environment,
        stripe_promotion_code_id,
        stripe_coupon_id,
        promotion_code_snapshot,
        discount_type,
        discount_value,
        subtotal_cents,
        discount_cents,
        total_cents,
        idempotency_key,
        metadata
      )
      values (
        v_booking.id,
        p_booking_version,
        v_payment.id,
        p_stripe_environment,
        trim(p_stripe_promotion_code_id),
        trim(p_stripe_coupon_id),
        upper(trim(p_promotion_code)),
        p_discount_type,
        p_discount_value,
        p_original_amount_cents,
        p_discount_amount_cents,
        p_total_amount_cents,
        trim(p_idempotency_key),
        jsonb_build_object('checkoutTiming', p_checkout_timing)
      )
      returning * into v_existing_reservation;
    else
      update public.session_promotion_reservations
      set status = 'reserved',
          released_at = null,
          updated_at = now()
      where id = v_existing_reservation.id
      returning * into v_existing_reservation;
    end if;
  else
    update public.session_promotion_reservations
    set status = 'released',
        released_at = coalesce(released_at, now()),
        updated_at = now()
    where booking_id = v_booking.id
      and booking_version = p_booking_version
      and status in ('reserved', 'consumed');
  end if;

  select *
  into v_snapshot
  from public.calculate_session_payment_snapshot(
    p_total_amount_cents,
    v_payment.platform_commission_bps
  );

  update public.session_payments
  set gross_amount_cents = v_snapshot.gross_amount_cents,
      platform_gross_commission_cents = v_snapshot.platform_gross_commission_cents,
      therapist_amount_cents = v_snapshot.therapist_amount_cents,
      stripe_checkout_session_id = trim(p_new_checkout_session_id),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'stripe_checkout', jsonb_build_object(
          'original_amount_cents', p_original_amount_cents,
          'charged_amount_cents', p_total_amount_cents,
          'discount_amount_cents', p_discount_amount_cents,
          'checkout_timing', p_checkout_timing,
          'promotion_code_id', case when v_has_promotion then trim(p_stripe_promotion_code_id) else null end,
          'coupon_id', case when v_has_promotion then trim(p_stripe_coupon_id) else null end
        )
      ),
      updated_at = now()
  where id = v_payment.id
  returning * into v_payment;

  return jsonb_build_object(
    'applied', true,
    'promotionReservationId', case when v_has_promotion then v_existing_reservation.id else null end,
    'sessionPaymentId', v_payment.id,
    'stripeCheckoutSessionId', v_payment.stripe_checkout_session_id,
    'therapistAmountCents', v_payment.therapist_amount_cents,
    'totalAmountCents', v_payment.gross_amount_cents
  );
end;
$$;


ALTER FUNCTION "public"."swap_session_payment_checkout_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_expected_checkout_session_id" "text", "p_new_checkout_session_id" "text", "p_original_amount_cents" integer, "p_discount_amount_cents" integer, "p_total_amount_cents" integer, "p_checkout_timing" "text", "p_promotion_code" "text", "p_stripe_promotion_code_id" "text", "p_stripe_coupon_id" "text", "p_discount_type" "text", "p_discount_value" integer, "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."swap_session_payment_checkout_v10"("p_session_payment_id" "uuid", "p_booking_version" bigint, "p_stripe_environment" "text", "p_expected_checkout_session_id" "text", "p_new_checkout_session_id" "text", "p_original_amount_cents" integer, "p_discount_amount_cents" integer, "p_total_amount_cents" integer, "p_checkout_timing" "text", "p_promotion_code" "text", "p_stripe_promotion_code_id" "text", "p_stripe_coupon_id" "text", "p_discount_type" "text", "p_discount_value" integer, "p_idempotency_key" "text") IS 'Atomically swaps an open V10 Checkout and its promotion/money snapshot before setup or charge authority exists.';



CREATE OR REPLACE FUNCTION "public"."sync_booking_video_session_from_agenda_v1"("p_booking_id" "uuid", "p_operation" "text", "p_request_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_session_id uuid;
begin
  if p_operation not in ('update', 'cancel') then
    raise exception 'INVALID_VIDEO_SESSION_SYNC_OPERATION' using errcode = '22023';
  end if;

  select public.sync_booking_video_session_v1(
    p_booking_id,
    p_operation,
    left('agenda:' || trim(p_request_id), 200)
  )
  into v_session_id;

  return v_session_id;
end;
$$;


ALTER FUNCTION "public"."sync_booking_video_session_from_agenda_v1"("p_booking_id" "uuid", "p_operation" "text", "p_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_booking_video_session_v1"("p_booking_id" "uuid", "p_operation" "text", "p_request_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_environment text := coalesce(
    nullif(current_setting('request.jwt.claim.zoom_environment', true), ''),
    'development'
  );
  v_session_id uuid;
begin
  if p_operation not in ('create', 'update', 'cancel') then
    raise exception 'invalid_video_session_sync_operation' using errcode = '22023';
  end if;

  if p_operation = 'cancel' then
    return public.cancel_video_session_for_booking_v1(
      p_booking_id,
      coalesce(p_request_id, 'booking_sync')
    );
  end if;

  select public.ensure_video_session_for_paid_booking_v1(
    p_booking_id,
    v_environment,
    coalesce(p_request_id, 'booking_sync')
  )
  into v_session_id;

  return v_session_id;
exception
  when raise_exception then
    return null;
end;
$$;


ALTER FUNCTION "public"."sync_booking_video_session_v1"("p_booking_id" "uuid", "p_operation" "text", "p_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_session_payment_projections"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_legacy_status public.payment_status;
begin
  v_legacy_status := case new.financial_status
    when 'pending' then 'pending'::public.payment_status
    when 'processing' then 'pending'::public.payment_status
    when 'paid' then 'paid'::public.payment_status
    when 'failed' then 'failed'::public.payment_status
    when 'canceled' then 'cancelled'::public.payment_status
    when 'partially_refunded' then 'partially_refunded'::public.payment_status
    when 'refunded' then 'refunded'::public.payment_status
    when 'disputed' then 'paid'::public.payment_status
  end;

  update public.bookings
  set payment_status = v_legacy_status,
      status = case
        when new.financial_status in ('pending', 'processing')
          and status = 'draft' then 'pending_payment'::public.booking_status
        when new.financial_status = 'paid'
          and status in ('draft', 'pending_payment') then 'confirmed'::public.booking_status
        else status
      end,
      updated_at = now()
  where id = new.booking_id
    and payment_status is distinct from v_legacy_status;

  insert into public.payments (
    booking_id,
    patient_profile_id,
    therapist_profile_id,
    provider,
    stripe_checkout_session_id,
    stripe_payment_intent_id,
    amount_cents,
    platform_fee_cents,
    therapist_amount_cents,
    currency,
    status,
    paid_at,
    refunded_at
  ) values (
    new.booking_id,
    new.patient_profile_id,
    new.therapist_profile_id,
    'stripe',
    new.stripe_checkout_session_id,
    new.stripe_payment_intent_id,
    new.gross_amount_cents,
    new.platform_gross_commission_cents,
    new.therapist_amount_cents,
    new.currency,
    v_legacy_status,
    new.paid_at,
    case
      when new.financial_status in ('refunded', 'partially_refunded') then now()
      else null
    end
  )
  on conflict (booking_id) do update
  set stripe_checkout_session_id = excluded.stripe_checkout_session_id,
      stripe_payment_intent_id = excluded.stripe_payment_intent_id,
      amount_cents = excluded.amount_cents,
      platform_fee_cents = excluded.platform_fee_cents,
      therapist_amount_cents = excluded.therapist_amount_cents,
      currency = excluded.currency,
      status = excluded.status,
      paid_at = excluded.paid_at,
      refunded_at = coalesce(excluded.refunded_at, public.payments.refunded_at),
      updated_at = now();

  if new.financial_status in ('paid', 'partially_refunded', 'refunded', 'disputed') then
    insert into public.booking_payment_receipts (
      booking_id,
      amount_cents,
      currency,
      provider,
      paid_at
    ) values (
      new.booking_id,
      new.gross_amount_cents,
      new.currency,
      'stripe',
      new.paid_at
    )
    on conflict (booking_id) do update
    set amount_cents = excluded.amount_cents,
        currency = excluded.currency,
        provider = excluded.provider,
        paid_at = excluded.paid_at,
        updated_at = now();

    insert into public.financial_ledger_entries (
      entry_type,
      direction,
      amount_cents,
      patient_profile_id,
      therapist_profile_id,
      booking_id,
      session_payment_id,
      source_table,
      source_id,
      occurred_at
    )
    select
      entries.entry_type,
      'credit',
      entries.amount_cents,
      new.patient_profile_id,
      new.therapist_profile_id,
      new.booking_id,
      new.id,
      'session_payments',
      new.id,
      coalesce(new.paid_at, new.created_at)
    from (
      values
        (
          'session_gross_payment'::public.financial_ledger_entry_type,
          new.gross_amount_cents
        ),
        (
          'therapist_payable'::public.financial_ledger_entry_type,
          new.therapist_amount_cents
        ),
        (
          'platform_gross_commission'::public.financial_ledger_entry_type,
          new.platform_gross_commission_cents
        )
    ) as entries(entry_type, amount_cents)
    where entries.amount_cents > 0
    on conflict do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_session_payment_projections"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_therapist_verification_queue_on_publish_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_verification_id uuid;
  v_verification_status public.therapist_status;
  v_target_status public.therapist_status;
begin
  if not new.is_public
    or new.public_status <> 'published'
    or new.status in (
      'approved'::public.therapist_status,
      'suspended'::public.therapist_status
    )
  then
    return new;
  end if;

  select
    therapist_verifications.id,
    therapist_verifications.status
  into
    v_verification_id,
    v_verification_status
  from public.therapist_verifications
  where therapist_verifications.therapist_profile_id = new.id
  order by
    therapist_verifications.submitted_at desc nulls last,
    therapist_verifications.created_at desc,
    therapist_verifications.id desc
  limit 1
  for update;

  if v_verification_id is null then
    v_target_status := case
      when new.status = 'in_review'::public.therapist_status
        then 'in_review'::public.therapist_status
      else 'submitted'::public.therapist_status
    end;

    insert into public.therapist_verifications (
      therapist_profile_id,
      status,
      submitted_at
    )
    values (
      new.id,
      v_target_status,
      now()
    );
  elsif v_verification_status in (
    'draft'::public.therapist_status,
    'changes_requested'::public.therapist_status,
    'rejected'::public.therapist_status
  ) then
    v_target_status := 'submitted'::public.therapist_status;

    update public.therapist_verifications
    set
      status = v_target_status,
      changes_requested = null,
      rejection_reason = null,
      reviewed_by = null,
      reviewed_at = null,
      submitted_at = now(),
      updated_at = now()
    where id = v_verification_id;
  else
    v_target_status := v_verification_status;
  end if;

  if v_target_status in (
    'submitted'::public.therapist_status,
    'in_review'::public.therapist_status
  )
  then
    update public.therapist_profiles
    set
      status = v_target_status,
      updated_at = now()
    where id = new.id
      and status in (
        'draft'::public.therapist_status,
        'submitted'::public.therapist_status,
        'in_review'::public.therapist_status,
        'changes_requested'::public.therapist_status,
        'rejected'::public.therapist_status
      )
      and status is distinct from v_target_status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_therapist_verification_queue_on_publish_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_therapist_verification_queue_on_publish_v1"() IS 'Keeps profile publication and its administrative verification queue entry in the same transaction without auto-approving profiles.';



CREATE OR REPLACE FUNCTION "public"."synchronize_video_session_watchdog_v1"("p_session_name" "text", "p_provider_session_id" "text", "p_environment" "text", "p_max_duration_minutes" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session_id uuid;
  v_match_count integer := 0;
  v_session_name text := nullif(btrim(coalesce(p_session_name, '')), '');
  v_provider_session_id text := nullif(btrim(coalesce(p_provider_session_id, '')), '');
begin
  if p_environment not in ('development', 'production') then
    raise exception 'invalid_zoom_video_environment' using errcode = '22023';
  end if;

  if p_max_duration_minutes is null
     or p_max_duration_minutes < 1
     or p_max_duration_minutes > 240 then
    raise exception 'invalid_zoom_video_session_max_duration_minutes'
      using errcode = '22023';
  end if;

  if v_session_name is null and v_provider_session_id is null then
    return;
  end if;

  select count(*), (array_agg(id order by updated_at desc))[1]
    into v_match_count, v_session_id
  from public.video_sessions
  where environment = p_environment
    and (
      (v_session_name is not null and lower(session_name) = lower(v_session_name))
      or (
        v_provider_session_id is not null
        and provider_session_id = v_provider_session_id
      )
    );

  if v_match_count <> 1 then
    return;
  end if;

  update public.video_sessions
  set hard_ends_at = actual_started_at + make_interval(mins => p_max_duration_minutes),
      updated_at = now()
  where id = v_session_id
    and actual_started_at is not null
    and status not in ('ended', 'canceled');
end;
$$;


ALTER FUNCTION "public"."synchronize_video_session_watchdog_v1"("p_session_name" "text", "p_provider_session_id" "text", "p_environment" "text", "p_max_duration_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."synchronize_video_session_watchdog_v1"("p_session_name" "text", "p_provider_session_id" "text", "p_environment" "text", "p_max_duration_minutes" integer) IS 'Recalculates the internal orphan-session watchdog from actual provider start plus the validated runtime duration. It does not define booking duration or join windows.';



CREATE OR REPLACE FUNCTION "public"."therapist_metric_counter_v1"("p_current" bigint, "p_previous" bigint, "p_copy_key_prefix" "text", "p_unit" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_direction text;
begin
  v_direction := case
    when p_current > p_previous then 'up'
    when p_current < p_previous then 'down'
    else 'stable'
  end;

  return jsonb_build_object(
    'status', case when p_current = 0 then 'empty' else 'ready' end,
    'value', p_current,
    'previousValue', p_previous,
    'direction', v_direction,
    'directionCopyKey', p_copy_key_prefix || '.' || v_direction,
    'unit', p_unit
  );
end;
$$;


ALTER FUNCTION "public"."therapist_metric_counter_v1"("p_current" bigint, "p_previous" bigint, "p_copy_key_prefix" "text", "p_unit" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."therapist_metric_counter_v1"("p_current" bigint, "p_previous" bigint, "p_copy_key_prefix" "text", "p_unit" "text") IS 'Internal MTR-0.1 helper. Every counter includes a direction and a required copy key.';



CREATE OR REPLACE FUNCTION "public"."therapist_metric_rate_v1"("p_current_numerator" bigint, "p_current_denominator" bigint, "p_previous_numerator" bigint, "p_previous_denominator" bigint, "p_copy_key_prefix" "text", "p_minimum_sample" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_current numeric;
  v_previous numeric;
  v_direction text;
begin
  if p_current_denominator < p_minimum_sample then
    return jsonb_build_object(
      'status', 'insufficient_sample',
      'value', null,
      'previousValue', null,
      'direction', null,
      'directionCopyKey', null,
      'unit', 'percent',
      'minimumSample', p_minimum_sample,
      'observedSample', p_current_denominator
    );
  end if;

  v_current := round(
    p_current_numerator::numeric * 100 / nullif(p_current_denominator, 0),
    1
  );
  v_previous := case
    when p_previous_denominator >= p_minimum_sample then round(
      p_previous_numerator::numeric * 100 / p_previous_denominator,
      1
    )
    else null
  end;
  v_direction := case
    when v_previous is null then 'stable'
    when v_current > v_previous then 'up'
    when v_current < v_previous then 'down'
    else 'stable'
  end;

  return jsonb_build_object(
    'status', 'ready',
    'value', v_current,
    'previousValue', v_previous,
    'direction', v_direction,
    'directionCopyKey', p_copy_key_prefix || '.' || v_direction,
    'unit', 'percent',
    'minimumSample', p_minimum_sample,
    'observedSample', p_current_denominator
  );
end;
$$;


ALTER FUNCTION "public"."therapist_metric_rate_v1"("p_current_numerator" bigint, "p_current_denominator" bigint, "p_previous_numerator" bigint, "p_previous_denominator" bigint, "p_copy_key_prefix" "text", "p_minimum_sample" integer) OWNER TO "postgres";


