CREATE OR REPLACE FUNCTION "public"."therapist_reviews_initials_v1"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select upper(
    coalesce(
      nullif(
        left(split_part(trim(coalesce(p_name, 'Paciente TES')), ' ', 1), 1) ||
        left(
          case
            when strpos(trim(coalesce(p_name, '')), ' ') > 0
              then regexp_replace(trim(coalesce(p_name, '')), '^.*\s([^\s]+)$', '\1')
            else ''
          end,
          1
        ),
        ''
      ),
      'PT'
    )
  );
$_$;


