CREATE OR REPLACE FUNCTION "public"."unpublish_therapist_profile_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_previous_status text;
  v_payload_hash text := encode(extensions.digest(p_expected_version::text, 'sha256'), 'hex');
  v_replay jsonb;
  v_response jsonb;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);
  v_replay := public.therapist_profile_request_replay_m1(v_profile.id, p_request_id, 'unpublish', v_payload_hash);
  if v_replay is not null then
    return v_replay;
  end if;

  if p_expected_version <> v_profile.profile_version then
    raise exception 'VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  v_previous_status := v_profile.public_status;

  update public.therapist_profiles
  set
    is_public = false,
    public_status = 'unpublished',
    unpublished_at = now(),
    profile_version = profile_version + 1,
    updated_at = now()
  where id = v_profile.id
  returning * into v_profile;

  insert into public.therapist_profile_events (
    therapist_profile_id,
    actor_user_id,
    event_type,
    request_id,
    previous_public_status,
    next_public_status,
    previous_version,
    next_version
  )
  values (
    v_profile.id,
    p_actor_user_id,
    'profile_unpublished',
    p_request_id,
    v_previous_status,
    'unpublished',
    p_expected_version,
    v_profile.profile_version
  );

  v_response := jsonb_build_object(
    'contractVersion', 1,
    'idempotentReplay', false,
    'editor', public.get_private_therapist_profile_editor_v1(p_actor_user_id)
  );

  return public.therapist_profile_store_request_m1(
    v_profile.id,
    p_request_id,
    'unpublish',
    v_payload_hash,
    v_response
  );
end;
$$;


ALTER FUNCTION "public"."unpublish_therapist_profile_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unpublish_therapist_profile_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint) IS 'SERVICE_ROLE_ONLY therapist profile unpublish command. Browser calls must go through therapist-profile-command.';



CREATE OR REPLACE FUNCTION "public"."update_therapist_public_slug_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_slug text := public.normalize_therapist_public_slug_v1(p_slug);
  v_status jsonb;
  v_payload_hash text := encode(extensions.digest(p_expected_version::text || ':' || v_slug, 'sha256'), 'hex');
  v_replay jsonb;
  v_response jsonb;
begin
  v_profile := public.get_therapist_profile_actor_m1(p_actor_user_id);
  v_replay := public.therapist_profile_request_replay_m1(v_profile.id, p_request_id, 'update_slug', v_payload_hash);
  if v_replay is not null then return v_replay; end if;

  if v_profile.plan = 'free' then
    raise exception 'CAPABILITY_NOT_ALLOWED: custom_profile_slug' using errcode = 'P0001';
  end if;
  if p_expected_version <> v_profile.profile_version then
    raise exception 'VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('therapist-public-slug:' || v_slug, 0));
  select * into v_profile from public.therapist_profiles where id = v_profile.id for update;
  v_status := public.therapist_public_slug_status_v1(v_profile.id, v_slug);

  case v_status ->> 'status'
    when 'invalid' then raise exception 'SLUG_INVALID' using errcode = 'P0001';
    when 'reserved' then raise exception 'SLUG_RESERVED' using errcode = 'P0001';
    when 'taken' then raise exception 'SLUG_TAKEN' using errcode = 'P0001';
    when 'current' then null;
    else
      delete from public.therapist_profile_slug_history
      where therapist_profile_id = v_profile.id and old_slug = v_slug;
      update public.therapist_profiles
      set slug = v_slug,
          profile_version = profile_version + 1,
          updated_at = now()
      where id = v_profile.id
      returning * into v_profile;

      insert into public.therapist_profile_events (
        therapist_profile_id, actor_user_id, event_type, request_id,
        previous_public_status, next_public_status, previous_version, next_version,
        metadata
      ) values (
        v_profile.id, p_actor_user_id, 'profile_slug_updated', p_request_id,
        v_profile.public_status, v_profile.public_status, p_expected_version,
        v_profile.profile_version, jsonb_build_object('publicProfileSlug', v_profile.slug)
      );
  end case;

  v_response := jsonb_build_object(
    'contractVersion', 2,
    'idempotentReplay', false,
    'editor', public.get_private_therapist_profile_editor_v1(p_actor_user_id)
  );
  return public.therapist_profile_store_request_m1(
    v_profile.id, p_request_id, 'update_slug', v_payload_hash, v_response
  );
end;
$$;


ALTER FUNCTION "public"."update_therapist_public_slug_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_therapist_public_slug_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_expected_version" bigint, "p_slug" "text") IS 'Plan-aware, idempotent and concurrency-safe custom public slug command for authenticated Edge Functions.';



CREATE OR REPLACE FUNCTION "public"."update_therapist_service_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_service_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_therapist public.therapist_profiles%rowtype;
  v_service public.therapist_services%rowtype;
  v_next_therapy_id uuid := coalesce(nullif(p_payload ->> 'therapyId', '')::uuid, null);
  v_next_title text := nullif(btrim(coalesce(p_payload ->> 'title', '')), '');
  v_next_description text := case
    when p_payload ? 'description'
      then nullif(btrim(coalesce(p_payload ->> 'description', '')), '')
    else null
  end;
  v_next_duration integer := nullif(p_payload ->> 'durationMinutes', '')::integer;
  v_next_price integer := nullif(p_payload ->> 'priceCents', '')::integer;
  v_next_currency text := case
    when p_payload ? 'currency' then upper(p_payload ->> 'currency')
    else null
  end;
  v_next_format text := p_payload ->> 'deliveryFormat';
  v_next_bookable boolean := case
    when p_payload ? 'isBookable' then (p_payload ->> 'isBookable')::boolean
    else null
  end;
  v_payload_hash text := encode(
    extensions.digest(
      jsonb_build_object(
        'serviceId', p_service_id,
        'expectedVersion', p_expected_version,
        'payload', p_payload
      )::text,
      'sha256'
    ),
    'hex'
  );
  v_response jsonb;
begin
  v_therapist := public.get_therapist_for_service_actor_v1(p_actor_user_id);
  v_response := public.get_therapist_service_request_replay_v1(
    v_therapist.id,
    p_request_id,
    'update',
    v_payload_hash
  );

  if v_response is not null then
    return v_response;
  end if;

  select *
    into v_service
  from public.therapist_services
  where id = p_service_id
    and therapist_profile_id = v_therapist.id
  for update;

  if not found then
    raise exception 'THERAPIST_SERVICE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_service.version <> p_expected_version then
    raise exception 'THERAPIST_SERVICE_VERSION_CONFLICT' using errcode = 'P0001';
  end if;

  if v_next_therapy_id is not null and v_next_therapy_id <> v_service.therapy_id then
    perform public.validate_platform_therapy_for_service_v1(v_next_therapy_id);

    if exists (
      select 1 from public.bookings where service_id = v_service.id
    ) then
      raise exception 'THERAPIST_SERVICE_THERAPY_LOCKED' using errcode = 'P0001';
    end if;

    perform public.ensure_no_duplicate_therapist_service_v1(
      v_therapist.id,
      v_next_therapy_id,
      v_service.id
    );
  end if;

  update public.therapist_services
  set
    therapy_id = coalesce(v_next_therapy_id, therapy_id),
    title = coalesce(v_next_title, title),
    description = case
      when p_payload ? 'description' then v_next_description
      else description
    end,
    duration_minutes = coalesce(v_next_duration, duration_minutes),
    price_cents = coalesce(v_next_price, price_cents),
    currency = coalesce(v_next_currency, currency),
    delivery_format = coalesce(v_next_format, delivery_format),
    online_only = coalesce(v_next_format, delivery_format) = 'online',
    is_bookable = coalesce(v_next_bookable, is_bookable),
    updated_at = now()
  where id = v_service.id
  returning * into v_service;

  insert into public.therapist_service_events (
    therapist_profile_id,
    service_id,
    actor_user_id,
    event_type,
    request_id,
    previous_status,
    next_status,
    previous_version,
    resulting_version
  )
  values (
    v_therapist.id,
    v_service.id,
    p_actor_user_id,
    'service_updated',
    p_request_id,
    v_service.status,
    v_service.status,
    p_expected_version,
    v_service.version
  );

  v_response := jsonb_build_object(
    'contractVersion', 1,
    'idempotentReplay', false,
    'service', public.service_row_to_private_json_v1(v_service.id)
  );

  return public.store_therapist_service_request_v1(
    v_therapist.id,
    p_request_id,
    'update',
    v_payload_hash,
    v_service.id,
    v_response
  );
end;
$$;


ALTER FUNCTION "public"."update_therapist_service_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_service_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_therapist_service_with_matching_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_service_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_theme_ids uuid[];
  v_interest_ids uuid[];
begin
  v_result := public.update_therapist_service_v1(
    p_actor_user_id,
    p_request_id,
    p_service_id,
    p_expected_version,
    p_payload
  );

  if p_payload ? 'themeIds' or p_payload ? 'interestIds' then
    select coalesce(array_agg(value::uuid order by ordinality), '{}'::uuid[])
      into v_theme_ids
    from jsonb_array_elements_text(coalesce(p_payload->'themeIds', '[]'::jsonb))
      with ordinality as items(value, ordinality);

    select coalesce(array_agg(value::uuid order by ordinality), '{}'::uuid[])
      into v_interest_ids
    from jsonb_array_elements_text(coalesce(p_payload->'interestIds', '[]'::jsonb))
      with ordinality as items(value, ordinality);

    perform public.replace_therapist_service_matching_v1(
      p_actor_user_id,
      p_service_id,
      v_theme_ids,
      v_interest_ids,
      p_request_id
    );

    v_result := jsonb_set(
      v_result,
      '{service}',
      public.service_row_to_private_json_v1(p_service_id),
      true
    );
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."update_therapist_service_with_matching_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_service_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_therapist_service_with_matching_v1"("p_actor_user_id" "uuid", "p_request_id" "uuid", "p_service_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") IS 'SERVICE_ROLE_ONLY therapist service update with Match metadata. Browser clients must not call this RPC directly.';



CREATE OR REPLACE FUNCTION "public"."upsert_participant_conversation_for_booking_v1"("p_booking_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
  v_conversation_id uuid;
begin
  select *
    into v_booking
  from public.bookings
  where id = p_booking_id;

  if not found
    or v_booking.status not in (
      'confirmed'::public.booking_status,
      'completed'::public.booking_status
    )
  then
    return null;
  end if;

  insert into public.conversations as conversation (
    patient_profile_id,
    therapist_profile_id,
    booking_id
  )
  values (
    v_booking.patient_profile_id,
    v_booking.therapist_profile_id,
    v_booking.id
  )
  on conflict (patient_profile_id, therapist_profile_id) do update
  set
    booking_id = case
      -- Do not replace a more recent confirmed session context with a
      -- historical completion arriving later in the lifecycle.
      when exists (
        select 1
        from public.bookings as current_booking
        where current_booking.id = conversation.booking_id
          and current_booking.status = 'confirmed'::public.booking_status
          and current_booking.starts_at >= v_booking.starts_at
      ) then conversation.booking_id
      else excluded.booking_id
    end,
    updated_at = now()
  returning id into v_conversation_id;

  return v_conversation_id;
end;
$$;


ALTER FUNCTION "public"."upsert_participant_conversation_for_booking_v1"("p_booking_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_participant_conversation_for_booking_v1"("p_booking_id" "uuid") IS 'Creates or maintains the one structured participant conversation for an eligible confirmed or completed booking relationship.';



CREATE OR REPLACE FUNCTION "public"."upsert_therapist_review_reply_for_actor_v1"("p_actor_user_id" "uuid", "p_review_id" "uuid", "p_body" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_actor_user_id is null then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0001';
  end if;

  perform set_config('request.jwt.claim.sub', p_actor_user_id::text, true);
  perform set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'role',
      'authenticated',
      'sub',
      p_actor_user_id::text
    )::text,
    true
  );

  return public.upsert_therapist_review_reply_v1(
    p_review_id,
    p_body,
    p_request_id
  );
end;
$$;


ALTER FUNCTION "public"."upsert_therapist_review_reply_for_actor_v1"("p_actor_user_id" "uuid", "p_review_id" "uuid", "p_body" "text", "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_therapist_review_reply_for_actor_v1"("p_actor_user_id" "uuid", "p_review_id" "uuid", "p_body" "text", "p_request_id" "uuid") IS 'SERVICE_ROLE_ONLY wrapper for therapist review replies. The actor user id must come from the JWT validated by therapist-reviews-command.';



CREATE OR REPLACE FUNCTION "public"."upsert_therapist_review_reply_v1"("p_review_id" "uuid", "p_body" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.therapist_profiles%rowtype;
  v_body text := trim(coalesce(p_body, ''));
  v_hash text;
  v_existing_request public.therapist_review_reply_mutation_requests%rowtype;
  v_reply public.review_replies%rowtype;
begin
  if p_review_id is null or p_request_id is null
    or length(v_body) < 3 or length(v_body) > 600 then
    raise exception 'VALIDATION_ERROR' using errcode = 'P0001';
  end if;

  v_profile := public.resolve_current_therapist_for_reviews_v1();
  if v_profile.plan not in ('premium', 'premium_plus') then
    raise exception 'CAPABILITY_NOT_ALLOWED' using errcode = 'P0001';
  end if;

  v_hash := encode(extensions.digest(jsonb_build_object(
    'reviewId', p_review_id, 'body', v_body
  )::text, 'sha256'), 'hex');

  select request.* into v_existing_request
  from public.therapist_review_reply_mutation_requests request
  where request.therapist_profile_id = v_profile.id
    and request.request_id = p_request_id
    and request.operation = 'reply'
  for update;
  if v_existing_request.id is not null then
    if v_existing_request.payload_hash <> v_hash then
      raise exception 'REQUEST_CONFLICT' using errcode = 'P0001';
    end if;
    return jsonb_build_object(
      'idempotentReplay', true,
      'page', public.get_therapist_reviews_v1()
    );
  end if;

  perform 1 from public.reviews review
  where review.id = p_review_id
    and review.therapist_profile_id = v_profile.id
    and review.status = 'published'
    and review.superseded_at is null
  for update;
  if not found then raise exception 'REVIEW_NOT_FOUND' using errcode = 'P0001'; end if;

  insert into public.review_replies (
    review_id, therapist_profile_id, body, status, published_at
  ) values (
    p_review_id, v_profile.id, v_body, 'published', now()
  )
  on conflict (review_id) do update
  set body = excluded.body,
      therapist_profile_id = excluded.therapist_profile_id,
      status = 'published',
      published_at = coalesce(public.review_replies.published_at, excluded.published_at),
      updated_at = now()
  returning * into v_reply;

  insert into public.therapist_review_reply_mutation_requests (
    therapist_profile_id, request_id, operation, payload_hash, review_id, reply_id
  ) values (
    v_profile.id, p_request_id, 'reply', v_hash, p_review_id, v_reply.id
  );

  return jsonb_build_object(
    'idempotentReplay', false,
    'page', public.get_therapist_reviews_v1()
  );
end;
$$;


ALTER FUNCTION "public"."upsert_therapist_review_reply_v1"("p_review_id" "uuid", "p_body" "text", "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_therapist_review_reply_v1"("p_review_id" "uuid", "p_body" "text", "p_request_id" "uuid") IS 'Internal therapist review reply mutation. Direct browser execution is revoked; use upsert_therapist_review_reply_for_actor_v1 through therapist-reviews-command.';



CREATE OR REPLACE FUNCTION "public"."validate_applied_booking_reschedule_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.starts_at is not distinct from old.starts_at
    or pg_catalog.current_setting('tes.booking_source', true)
      is distinct from 'reschedule_resolution'
  then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.therapist_profile_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-schedule:' || new.patient_profile_id::text,
      0
    )
  );

  if not exists (
    select 1
    from public.list_booking_reschedule_candidates_v1(
      old.id,
      new.starts_at,
      new.ends_at + interval '1 microsecond',
      now(),
      10
    ) as candidate
    where candidate.starts_at = new.starts_at
      and candidate.ends_at = new.ends_at
      and candidate.timezone = new.timezone
  ) then
    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_applied_booking_reschedule_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_availability_exception_series_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.is_valid_timezone_v1(new.timezone) then
    raise exception 'invalid_block_timezone' using errcode = '22023';
  end if;

  if new.recurrence_ends_on > new.starts_on + 366 then
    raise exception 'block_recurrence_too_long' using errcode = '22023';
  end if;

  if new.service_id is not null
    and not exists (
      select 1
      from public.therapist_services as service
      where service.id = new.service_id
        and service.therapist_profile_id = new.therapist_profile_id
    ) then
    raise exception 'block_service_forbidden' using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_availability_exception_series_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_booking_against_active_holds_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status not in ('draft', 'pending_payment', 'confirmed', 'completed') then
    return new;
  end if;

  -- Stable lock order: therapist first, patient second.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.therapist_profile_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-schedule:' || new.patient_profile_id::text,
      0
    )
  );

  update public.booking_holds
  set status = 'expired', updated_at = now()
  where therapist_profile_id = new.therapist_profile_id
    and status = 'active'
    and expires_at <= now();

  -- Completed bookings are patient history only; therapist occupancy keeps the
  -- established active-status and buffer contract.
  if new.status in ('draft', 'pending_payment', 'confirmed') then
    if exists (
      select 1
      from public.bookings as booking
      where booking.therapist_profile_id = new.therapist_profile_id
        and booking.id is distinct from new.id
        and booking.status in ('draft', 'pending_payment', 'confirmed')
        and booking.occupied_during && new.occupied_during
    ) then
      raise exception 'BOOKING_CONFLICT' using errcode = 'P0001';
    end if;

    if exists (
      select 1
      from public.booking_holds as hold
      where hold.therapist_profile_id = new.therapist_profile_id
        and hold.status = 'active'
        and hold.expires_at > now()
        and hold.occupied_during && new.occupied_during
    ) then
      raise exception 'SLOT_HELD_BY_ANOTHER_USER' using errcode = 'P0001';
    end if;
  end if;

  -- An unchanged, already confirmed historical interval is not a new booking.
  -- Preserve completion/reconciliation of legacy overlaps, but revalidate every
  -- insert, patient change, time change and transition from an unpaid booking.
  if tg_op = 'UPDATE'
    and old.status in ('confirmed', 'completed')
    and new.status in ('confirmed', 'completed')
    and new.patient_profile_id is not distinct from old.patient_profile_id
    and new.starts_at is not distinct from old.starts_at
    and new.ends_at is not distinct from old.ends_at then
    return new;
  end if;

  if public.patient_has_schedule_conflict_v1(
    new.patient_profile_id,
    new.starts_at,
    new.ends_at,
    new.id
  ) then
    raise exception 'PATIENT_SCHEDULE_CONFLICT' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_booking_against_active_holds_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_booking_against_active_holds_v1"() IS 'Trigger helper only. Serializes therapist then patient; therapist occupancy blocks pending checkout, while patient overlap requires another paid confirmed session.';



CREATE OR REPLACE FUNCTION "public"."validate_booking_hold_schedule_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status <> 'active' then
    return new;
  end if;

  -- Preserve the more specific A2 conflict errors. Existing triggers and the
  -- exclusion constraint remain authoritative for these overlapping cases.
  if exists (
    select 1
    from public.booking_holds as hold
    where hold.therapist_profile_id = new.therapist_profile_id
      and hold.status = 'active'
      and hold.expires_at > now()
      and hold.occupied_during && new.occupied_during
  ) or exists (
    select 1
    from public.bookings as booking
    where booking.therapist_profile_id = new.therapist_profile_id
      and booking.status in ('draft', 'pending_payment', 'confirmed')
      and booking.occupied_during && new.occupied_during
  ) then
    return new;
  end if;

  if not public.is_service_schedule_slot_v1(
      new.service_id,
      new.starts_at,
      new.ends_at,
      now()
    )
  then
    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_booking_hold_schedule_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_booking_reschedule_request_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings%rowtype;
begin
  select * into v_booking
  from public.bookings
  where id = new.booking_id
  for update;

  if not found or v_booking.status <> 'confirmed' then
    raise exception 'BOOKING_CANNOT_BE_RESCHEDULED' using errcode = 'P0001';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_booking.therapist_profile_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-schedule:' || v_booking.patient_profile_id::text,
      0
    )
  );
  perform public.expire_booking_holds_v1(now(), v_booking.therapist_profile_id);

  if new.proposed_timezone <> v_booking.timezone
    or new.proposed_ends_at <> new.proposed_starts_at
      + v_booking.service_duration_minutes_snapshot * interval '1 minute'
    or new.proposed_starts_at = v_booking.starts_at
    or not exists (
      select 1
      from public.list_booking_reschedule_candidates_v1(
        v_booking.id,
        new.proposed_starts_at,
        new.proposed_ends_at + interval '1 microsecond',
        now(),
        10
      ) as candidate
      where candidate.starts_at = new.proposed_starts_at
        and candidate.ends_at = new.proposed_ends_at
    )
  then
    raise exception 'SLOT_NOT_AVAILABLE' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.bookings as conflict
    where conflict.therapist_profile_id = v_booking.therapist_profile_id
      and conflict.id <> v_booking.id
      and conflict.status in ('draft', 'pending_payment', 'confirmed')
      and conflict.occupied_during && pg_catalog.tstzrange(
        new.proposed_starts_at
          - v_booking.buffer_before_minutes_snapshot * interval '1 minute',
        new.proposed_ends_at
          + v_booking.buffer_after_minutes_snapshot * interval '1 minute',
        '[)'
      )
  ) then
    raise exception 'BOOKING_CONFLICT' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.booking_holds as hold
    where hold.therapist_profile_id = v_booking.therapist_profile_id
      and hold.status = 'active'
      and hold.expires_at > now()
      and hold.occupied_during && pg_catalog.tstzrange(
        new.proposed_starts_at
          - v_booking.buffer_before_minutes_snapshot * interval '1 minute',
        new.proposed_ends_at
          + v_booking.buffer_after_minutes_snapshot * interval '1 minute',
        '[)'
      )
  ) then
    raise exception 'SLOT_HELD_BY_ANOTHER_USER' using errcode = 'P0001';
  end if;

  if public.patient_has_schedule_conflict_v1(
    v_booking.patient_profile_id,
    new.proposed_starts_at,
    new.proposed_ends_at,
    v_booking.id
  ) then
    raise exception 'PATIENT_SCHEDULE_CONFLICT' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_booking_reschedule_request_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_hold_against_active_bookings_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status <> 'active' then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.therapist_profile_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'tes:patient-schedule:' || new.patient_profile_id::text,
      0
    )
  );

  update public.booking_holds
  set status = 'expired', updated_at = now()
  where therapist_profile_id = new.therapist_profile_id
    and status = 'active'
    and expires_at <= now()
    and id <> new.id;

  if exists (
    select 1
    from public.bookings as booking
    where booking.therapist_profile_id = new.therapist_profile_id
      and booking.status in ('draft', 'pending_payment', 'confirmed')
      and booking.occupied_during && new.occupied_during
  ) then
    raise exception 'BOOKING_CONFLICT' using errcode = 'P0001';
  end if;

  if public.patient_has_schedule_conflict_v1(
    new.patient_profile_id,
    new.starts_at,
    new.ends_at,
    null
  ) then
    raise exception 'PATIENT_SCHEDULE_CONFLICT' using errcode = 'P0001';
  end if;

  -- Another unsubmitted patient hold intentionally does not block this hold.
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_hold_against_active_bookings_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_hold_against_active_bookings_v1"() IS 'Protects therapist occupancy and rejects patient overlaps only after confirmation or payment authorization claim; unsubmitted patient holds remain non-blocking.';



