CREATE TABLE IF NOT EXISTS "public"."admin_audit_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "actor_user_id" "uuid" NOT NULL,
    "actor_role" "text" NOT NULL,
    "permission" "text",
    "action" "text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "text",
    "previous_state" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "next_state" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reason" "text",
    "request_id" "text",
    "correlation_id" "text",
    "source" "text" DEFAULT 'admin'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "admin_audit_events_action_not_blank" CHECK ((("length"("btrim"("action")) >= 3) AND ("length"("btrim"("action")) <= 128))),
    CONSTRAINT "admin_audit_events_actor_role_not_blank" CHECK ((("length"("btrim"("actor_role")) >= 2) AND ("length"("btrim"("actor_role")) <= 64))),
    CONSTRAINT "admin_audit_events_correlation_id_length" CHECK ((("correlation_id" IS NULL) OR (("length"("btrim"("correlation_id")) >= 1) AND ("length"("btrim"("correlation_id")) <= 128)))),
    CONSTRAINT "admin_audit_events_entity_id_not_blank" CHECK ((("entity_id" IS NULL) OR (("length"("btrim"("entity_id")) >= 1) AND ("length"("btrim"("entity_id")) <= 256)))),
    CONSTRAINT "admin_audit_events_entity_type_not_blank" CHECK ((("length"("btrim"("entity_type")) >= 2) AND ("length"("btrim"("entity_type")) <= 128))),
    CONSTRAINT "admin_audit_events_next_state_object" CHECK (("jsonb_typeof"("next_state") = 'object'::"text")),
    CONSTRAINT "admin_audit_events_permission_not_blank" CHECK ((("permission" IS NULL) OR (("length"("btrim"("permission")) >= 3) AND ("length"("btrim"("permission")) <= 128)))),
    CONSTRAINT "admin_audit_events_previous_state_object" CHECK (("jsonb_typeof"("previous_state") = 'object'::"text")),
