    CONSTRAINT "availability_exception_series_reason_length" CHECK ((("reason" IS NULL) OR (("length"(TRIM(BOTH FROM "reason")) >= 1) AND ("length"(TRIM(BOTH FROM "reason")) <= 240)))),
    CONSTRAINT "availability_exception_series_recurrence_valid" CHECK ((("recurrence_frequency" = ANY (ARRAY['none'::"text", 'daily'::"text", 'weekly'::"text"])) AND ("recurrence_ends_on" >= "starts_on") AND (("recurrence_frequency" <> 'none'::"text") OR ("recurrence_ends_on" = "starts_on")))),
    CONSTRAINT "availability_exception_series_status_valid" CHECK (("status" = ANY (ARRAY['active'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "availability_exception_series_time_valid" CHECK ((("all_day" AND ("start_time" IS NULL) AND ("end_time" IS NULL)) OR ((NOT "all_day") AND ("start_time" IS NOT NULL) AND ("end_time" IS NOT NULL) AND ("start_time" < "end_time")))),
    CONSTRAINT "availability_exception_series_timezone_valid" CHECK ((("length"("timezone") >= 1) AND ("length"("timezone") <= 100))),
