CREATE TABLE IF NOT EXISTS "public"."financial_policy_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "version" "text" NOT NULL,
    "is_active" boolean DEFAULT false NOT NULL,
    "currency" character(3) DEFAULT 'BRL'::"bpchar" NOT NULL,
    "platform_commission_bps" integer DEFAULT 1500 NOT NULL,
    "auto_confirmation_days" integer DEFAULT 30 NOT NULL,
    "transfer_safety_period_days" integer DEFAULT 0 NOT NULL,
    "free_cancellation_hours" integer DEFAULT 24 NOT NULL,
    "late_cancellation_retention_bps" integer DEFAULT 5000 NOT NULL,
    "no_show_retention_bps" integer DEFAULT 5000 NOT NULL,
    "refund_processing_business_days" integer DEFAULT 1 NOT NULL,
    "manual_review_response_days" integer DEFAULT 5 NOT NULL,
    "weekly_batch_weekday" integer DEFAULT 2 NOT NULL,
    "weekly_batch_time" time without time zone DEFAULT '10:00:00'::time without time zone NOT NULL,
    "timezone" "text" DEFAULT 'America/Sao_Paulo'::"text" NOT NULL,
    "payout_batch_rule" "text" DEFAULT 'weekly_manual_cutoff'::"text" NOT NULL,
    "cancellation_policy_key" "text" DEFAULT 'free_until_24h_late_50_percent_no_show_50_percent'::"text" NOT NULL,
    "refund_policy_key" "text" DEFAULT 'instant_automatic_or_manual_review_before_transfer'::"text" NOT NULL,
    "proration_policy_key" "text" DEFAULT 'upgrade_immediate_prorated_downgrade_period_end'::"text" NOT NULL,
    "upgrade_proration_behavior" "text" DEFAULT 'always_invoice'::"text" NOT NULL,
    "downgrade_behavior" "text" DEFAULT 'period_end_no_credit'::"text" NOT NULL,
    "subscription_cancellation_behavior" "text" DEFAULT 'cancel_at_period_end'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "effective_from" timestamp with time zone DEFAULT "now"() NOT NULL,
    "effective_until" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "patient_auto_confirmation_days" integer DEFAULT 7 NOT NULL,
    "therapist_auto_confirmation_days" integer DEFAULT 30 NOT NULL,
    "policy_key" "text" NOT NULL,
    CONSTRAINT "financial_policy_auto_confirmation_positive" CHECK (("auto_confirmation_days" > 0)),
    CONSTRAINT "financial_policy_cancellation_window_positive" CHECK (("free_cancellation_hours" >= 0)),
    CONSTRAINT "financial_policy_commission_bps_range" CHECK ((("platform_commission_bps" >= 0) AND ("platform_commission_bps" <= 10000))),
    CONSTRAINT "financial_policy_currency_brl" CHECK (("currency" = 'BRL'::"bpchar")),
    CONSTRAINT "financial_policy_patient_auto_confirmation_positive" CHECK (("patient_auto_confirmation_days" > 0)),
    CONSTRAINT "financial_policy_retention_bps_range" CHECK (((("late_cancellation_retention_bps" >= 0) AND ("late_cancellation_retention_bps" <= 10000)) AND (("no_show_retention_bps" >= 0) AND ("no_show_retention_bps" <= 10000)))),
    CONSTRAINT "financial_policy_review_positive" CHECK ((("refund_processing_business_days" > 0) AND ("manual_review_response_days" > 0))),
    CONSTRAINT "financial_policy_therapist_auto_confirmation_positive" CHECK (("therapist_auto_confirmation_days" > 0)),
    CONSTRAINT "financial_policy_transfer_safety_positive" CHECK (("transfer_safety_period_days" >= 0)),
    CONSTRAINT "financial_policy_weekday_range" CHECK ((("weekly_batch_weekday" >= 0) AND ("weekly_batch_weekday" <= 6)))
);


ALTER TABLE "public"."financial_policy_versions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."financial_policy_versions"."patient_auto_confirmation_days" IS 'Days after the scheduled end before an absent patient confirmation is recorded automatically.';



COMMENT ON COLUMN "public"."financial_policy_versions"."therapist_auto_confirmation_days" IS 'Days after the scheduled end before an absent therapist confirmation is recorded automatically.';



CREATE TABLE IF NOT EXISTS "public"."financial_reconciliation_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "scheduled_for" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
