    "payouts_reconciled" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "financial_reconciliation_runs_counts_check" CHECK ((("attempts" > 0) AND ("source_charges_reconciled" >= 0) AND ("settlements_reconciled" >= 0) AND ("transfers_reconciled" >= 0) AND ("payouts_reconciled" >= 0))),
    CONSTRAINT "financial_reconciliation_runs_status_check" CHECK (("status" = ANY (ARRAY['running'::"text", 'completed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."financial_reconciliation_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."financial_reconciliation_runs" IS 'Auditable hourly Stripe reconciliation runs. A unique hourly lease prevents overlapping scheduled executions.';



