    CONSTRAINT "legal_document_versions_status" CHECK (("status" = ANY (ARRAY['draft'::"text", 'legal_review'::"text", 'approved'::"text", 'scheduled'::"text", 'published'::"text", 'superseded'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "legal_document_versions_title_not_blank" CHECK (("length"(TRIM(BOTH FROM "title")) > 0)),
    CONSTRAINT "legal_document_versions_version_not_blank" CHECK (("length"(TRIM(BOTH FROM "version")) > 0))
);


