    "provider" "text" DEFAULT 'zoom_video_sdk'::"text" NOT NULL,
    "environment" "text" NOT NULL,
    "session_name" "text" NOT NULL,
    "session_key" "text",
    "provider_session_id" "text",
    "status" "public"."video_session_status" DEFAULT 'ready'::"public"."video_session_status" NOT NULL,
    "scheduled_starts_at" timestamp with time zone NOT NULL,
    "scheduled_ends_at" timestamp with time zone NOT NULL,
    "actual_started_at" timestamp with time zone,
    "actual_ended_at" timestamp with time zone,
    "therapist_token_issued_at" timestamp with time zone,
    "last_synced_at" timestamp with time zone,
    "last_error_code" "text",
    "last_error_message" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "hard_ends_at" timestamp with time zone,
    "termination_reason" "text",
    "termination_requested_at" timestamp with time zone,
    "termination_confirmed_at" timestamp with time zone,
    "last_maintenance_at" timestamp with time zone,
    "therapist_first_joined_at" timestamp with time zone,
