    CONSTRAINT "video_sessions_provider_check" CHECK (("provider" = 'zoom_video_sdk'::"text")),
    CONSTRAINT "video_sessions_termination_reason_check" CHECK ((("termination_reason" IS NULL) OR ("termination_reason" = ANY (ARRAY['host_left'::"text", 'scheduled_end'::"text", 'hard_timeout'::"text", 'therapist_absent'::"text", 'provider_ended'::"text", 'manual_end'::"text", 'reconcile_orphan'::"text", 'patient_no_show'::"text"])))),
    CONSTRAINT "video_sessions_valid_range" CHECK (("scheduled_starts_at" < "scheduled_ends_at"))
);


ALTER TABLE "public"."video_sessions" OWNER TO "postgres";


COMMENT ON TABLE "public"."video_sessions" IS 'Sessao logica local de Video SDK por booking. Nao armazena JWT, senha, URL ou conteudo clinico.';



COMMENT ON COLUMN "public"."video_sessions"."therapist_token_issued_at" IS 'Auditoria de JWT emitido para terapeuta. Nao significa presenca confirmada no provedor.';



COMMENT ON COLUMN "public"."video_sessions"."hard_ends_at" IS 'Limite operacional efetivo: min(inicio efetivo + max env, fim agendado + tolerancia existente).';



COMMENT ON COLUMN "public"."video_sessions"."therapist_first_joined_at" IS 'Primeiro session.user_joined confiavel do webhook Zoom para o terapeuta.';



CREATE OR REPLACE VIEW "public"."patient_video_session_summary_v" WITH ("security_invoker"='true') AS
