CREATE TABLE IF NOT EXISTS "public"."payout_scheduler_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "business_date" "date" NOT NULL,
    "reference_period_start" "date" NOT NULL,
    "reference_period_end" "date" NOT NULL,
    "cutoff_at" timestamp with time zone NOT NULL,
    "payout_batch_id" "uuid",
    "status" "public"."payout_scheduler_run_status" DEFAULT 'running'::"public"."payout_scheduler_run_status" NOT NULL,
    "worker_id" "uuid",
    "lease_expires_at" timestamp with time zone,
    "attempts" integer DEFAULT 0 NOT NULL,
    "window_alerted_at" timestamp with time zone,
    "last_error_code" "text",
    "last_error_message" "text",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "consecutive_failures" integer DEFAULT 0 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "last_failed_at" timestamp with time zone,
    "last_succeeded_at" timestamp with time zone,
    "last_request_id" "uuid",
    CONSTRAINT "payout_scheduler_runs_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "payout_scheduler_runs_consecutive_failures_check" CHECK ((("consecutive_failures" >= 0) AND ("consecutive_failures" <= 4))),
    CONSTRAINT "payout_scheduler_runs_period_check" CHECK (("reference_period_start" <= "reference_period_end"))
);


ALTER TABLE "public"."payout_scheduler_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."payout_scheduler_runs" IS 'Auditable weekly Transfer runs with lease, bounded backoff and a failure circuit. Brazilian platform payout settings cannot reserve weekly liabilities, so workers must preflight actual available balance.';



COMMENT ON COLUMN "public"."payout_scheduler_runs"."consecutive_failures" IS 'Consecutive worker failures for the same immutable weekly run and batch. Reset only after acknowledged progress or an explicit service-role resume.';



COMMENT ON COLUMN "public"."payout_scheduler_runs"."next_retry_at" IS 'Earliest instant at which the scheduler may reacquire this run after a worker failure.';



COMMENT ON COLUMN "public"."payout_scheduler_runs"."last_request_id" IS 'Internal correlation identifier only. It must never be exposed as financial authority.';



