CREATE TABLE IF NOT EXISTS "public"."session_payment_schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "booking_version" bigint NOT NULL,
    "session_payment_id" "uuid" NOT NULL,
    "session_payment_setup_id" "uuid" NOT NULL,
    "stripe_environment" "text" NOT NULL,
    "due_at" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "lease_owner" "uuid",
    "lease_expires_at" timestamp with time zone,
    "claimed_at" timestamp with time zone,
    "stripe_payment_intent_id" "text",
    "stripe_charge_id" "text",
    "last_error_code" "text",
    "last_failed_at" timestamp with time zone,
    "succeeded_at" timestamp with time zone,
    "canceled_at" timestamp with time zone,
    "idempotency_key" "text" NOT NULL,
    "request_fingerprint" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expected_booking_version" bigint NOT NULL,
    CONSTRAINT "session_payment_schedules_attempt_count_check" CHECK ((("attempt_count" >= 0) AND ("attempt_count" <= 8))),
    CONSTRAINT "session_payment_schedules_booking_version_positive" CHECK (("booking_version" > 0)),
    CONSTRAINT "session_payment_schedules_environment_check" CHECK (("stripe_environment" = ANY (ARRAY['test'::"text", 'live'::"text"]))),
    CONSTRAINT "session_payment_schedules_expected_booking_version_positive" CHECK (("expected_booking_version" > 0)),
    CONSTRAINT "session_payment_schedules_fingerprint_present" CHECK (("length"(TRIM(BOTH FROM "request_fingerprint")) > 0)),
    CONSTRAINT "session_payment_schedules_idempotency_present" CHECK (("length"(TRIM(BOTH FROM "idempotency_key")) > 0)),
    CONSTRAINT "session_payment_schedules_lease_check" CHECK (((("lease_owner" IS NULL) AND ("lease_expires_at" IS NULL)) OR (("lease_owner" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL)))),
    CONSTRAINT "session_payment_schedules_status_check" CHECK (("status" = ANY (ARRAY['scheduled'::"text", 'claimed'::"text", 'processing'::"text", 'paid'::"text", 'requires_customer_action'::"text", 'retry_scheduled'::"text", 'failed'::"text", 'canceled'::"text", 'superseded'::"text"])))
);


ALTER TABLE "public"."session_payment_schedules" OWNER TO "postgres";


COMMENT ON TABLE "public"."session_payment_schedules" IS 'Private V10 T-24 charge schedule with lease, retry and idempotency state.';



COMMENT ON COLUMN "public"."session_payment_schedules"."expected_booking_version" IS 'Booking version that must still be current when this immutable charge schedule is claimed or reconciled.';



CREATE TABLE IF NOT EXISTS "public"."session_payment_setups" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
