    "session_payment_id" "uuid" NOT NULL,
    "stripe_environment" "text" NOT NULL,
    "stripe_customer_id" "text" NOT NULL,
    "stripe_setup_intent_id" "text" NOT NULL,
    "stripe_payment_method_id" "text",
    "usage" "text" DEFAULT 'off_session'::"text" NOT NULL,
    "status" "text" DEFAULT 'requires_setup'::"text" NOT NULL,
    "consent_version" "text" NOT NULL,
    "consented_at" timestamp with time zone NOT NULL,
    "superseded_at" timestamp with time zone,
    "failure_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "session_payment_setups_booking_version_positive" CHECK (("booking_version" > 0)),
    CONSTRAINT "session_payment_setups_environment_check" CHECK (("stripe_environment" = ANY (ARRAY['test'::"text", 'live'::"text"]))),
    CONSTRAINT "session_payment_setups_payment_method_state_check" CHECK ((("status" <> 'succeeded'::"text") OR ("stripe_payment_method_id" IS NOT NULL))),
    CONSTRAINT "session_payment_setups_status_check" CHECK (("status" = ANY (ARRAY['requires_setup'::"text", 'processing'::"text", 'requires_action'::"text", 'succeeded'::"text", 'failed'::"text", 'canceled'::"text", 'superseded'::"text"]))),
    CONSTRAINT "session_payment_setups_usage_check" CHECK (("usage" = 'off_session'::"text"))
);


ALTER TABLE "public"."session_payment_setups" OWNER TO "postgres";


COMMENT ON TABLE "public"."session_payment_setups" IS 'Private V10 binding between one booking version, SetupIntent and PaymentMethod. Never stores PAN or CVC.';



CREATE TABLE IF NOT EXISTS "public"."session_transfer_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_payment_id" "uuid" NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "policy_version_id" "uuid" NOT NULL,
    "connect_account_id" "uuid" NOT NULL,
    "stripe_environment" "text" NOT NULL,
    "stripe_source_charge_id" "text" NOT NULL,
    "therapist_gross_amount_cents" integer NOT NULL,
    "debt_offset_amount_cents" integer DEFAULT 0 NOT NULL,
    "transfer_amount_cents" integer NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "lease_owner" "uuid",
    "lease_expires_at" timestamp with time zone,
    "stripe_transfer_id" "uuid",
    "idempotency_key" "text" NOT NULL,
    "request_fingerprint" "text" NOT NULL,
    "last_error_code" "text",
    "last_failed_at" timestamp with time zone,
    "succeeded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "prepared_at" timestamp with time zone,
    CONSTRAINT "session_transfer_jobs_amounts_check" CHECK ((("therapist_gross_amount_cents" > 0) AND ("debt_offset_amount_cents" >= 0) AND ("transfer_amount_cents" >= 0) AND ("therapist_gross_amount_cents" = ("debt_offset_amount_cents" + "transfer_amount_cents")))),
    CONSTRAINT "session_transfer_jobs_attempt_count_check" CHECK ((("attempt_count" >= 0) AND ("attempt_count" <= 8))),
    CONSTRAINT "session_transfer_jobs_environment_check" CHECK (("stripe_environment" = ANY (ARRAY['test'::"text", 'live'::"text"]))),
    CONSTRAINT "session_transfer_jobs_keys_present" CHECK ((("length"(TRIM(BOTH FROM "idempotency_key")) > 0) AND ("length"(TRIM(BOTH FROM "request_fingerprint")) > 0) AND ("length"(TRIM(BOTH FROM "stripe_source_charge_id")) > 0))),
    CONSTRAINT "session_transfer_jobs_lease_check" CHECK (((("lease_owner" IS NULL) AND ("lease_expires_at" IS NULL)) OR (("lease_owner" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL)))),
    CONSTRAINT "session_transfer_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'creating'::"text", 'pending_source'::"text", 'transferred'::"text", 'reconciliation_required'::"text", 'failed'::"text", 'offset_only'::"text", 'partially_reversed'::"text", 'reversed'::"text"])))
);


ALTER TABLE "public"."session_transfer_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."session_transfer_jobs" IS 'Private V10 direct Transfer outbox created atomically when a session payment is confirmed.';



CREATE OR REPLACE VIEW "public"."private_session_financial_flow_v10_v1" WITH ("security_invoker"='true') AS
 SELECT "payment"."id" AS "session_payment_id",
    "payment"."booking_id",
    "payment"."financial_status",
    "payment"."transfer_status",
    "payment"."payment_due_at",
    "setup"."id" AS "setup_id",
    "setup"."status" AS "setup_status",
    "schedule"."id" AS "schedule_id",
    "schedule"."status" AS "schedule_status",
    "schedule"."due_at",
    "transfer_job"."id" AS "transfer_job_id",
    "transfer_job"."status" AS "transfer_job_status",
    "transfer_job"."transfer_amount_cents",
    "transfer_job"."debt_offset_amount_cents",
    "payment"."created_at",
    "payment"."updated_at"
   FROM ((("public"."session_payments" "payment"
     LEFT JOIN "public"."session_payment_setups" "setup" ON ((("setup"."session_payment_id" = "payment"."id") AND ("setup"."superseded_at" IS NULL))))
     LEFT JOIN "public"."session_payment_schedules" "schedule" ON ((("schedule"."session_payment_id" = "payment"."id") AND ("schedule"."status" <> 'superseded'::"text"))))
     LEFT JOIN "public"."session_transfer_jobs" "transfer_job" ON (("transfer_job"."session_payment_id" = "payment"."id")))
  WHERE ("payment"."payment_flow_version" = 'v10'::"text");


ALTER VIEW "public"."private_session_financial_flow_v10_v1" OWNER TO "postgres";


