    "duration_minutes" integer NOT NULL,
    "price_cents" integer NOT NULL,
    "currency" character(3) DEFAULT 'BRL'::"bpchar" NOT NULL,
    "status" "public"."service_status" DEFAULT 'draft'::"public"."service_status" NOT NULL,
    "online_only" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "delivery_format" "text" DEFAULT 'online'::"text" NOT NULL,
    "is_bookable" boolean DEFAULT true NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "version" bigint DEFAULT 1 NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "therapist_services_active_price_required" CHECK ((("status" <> 'active'::"public"."service_status") OR ("price_cents" >= 1000))),
    CONSTRAINT "therapist_services_currency_uppercase" CHECK ((("currency")::"text" = "upper"(("currency")::"text"))),
    CONSTRAINT "therapist_services_delivery_format_online_only_check" CHECK (("delivery_format" = 'online'::"text")),
    CONSTRAINT "therapist_services_duration_positive" CHECK (("duration_minutes" > 0)),
    CONSTRAINT "therapist_services_online_only_check" CHECK (("online_only" IS TRUE)),
    CONSTRAINT "therapist_services_position_non_negative" CHECK (("position" >= 0)),
    CONSTRAINT "therapist_services_price_cents_range" CHECK ((("price_cents" >= 0) AND ("price_cents" <= 2000000))),
    CONSTRAINT "therapist_services_price_non_negative" CHECK (("price_cents" >= 0))
);


ALTER TABLE "public"."therapist_services" OWNER TO "postgres";


COMMENT ON COLUMN "public"."therapist_services"."therapy_id" IS 'Canonical relationship to the platform therapy catalog. Therapist services never relate by free-text therapy name.';



COMMENT ON COLUMN "public"."therapist_services"."duration_minutes" IS 'Session duration in minutes; supported range for therapist services is 15 to 240.';



COMMENT ON COLUMN "public"."therapist_services"."price_cents" IS 'Integer amount in cents. No decimal money is accepted by service mutations.';



