);


ALTER TABLE "public"."therapy_matching_themes" OWNER TO "postgres";


COMMENT ON TABLE "public"."therapy_matching_themes" IS 'Canonical admin-managed relationship: themes recommend therapies. Max three themes per therapy.';



CREATE OR REPLACE VIEW "public"."public_therapies_v" WITH ("security_invoker"='true') AS
 WITH "therapist_counts" AS (
         SELECT "service"."therapy_id",
            ("count"(DISTINCT "profile"."id"))::integer AS "therapist_count"
           FROM ("public"."therapist_services" "service"
             JOIN "public"."therapist_profiles" "profile" ON (("profile"."id" = "service"."therapist_profile_id")))
          WHERE (("service"."status" = 'active'::"public"."service_status") AND "service"."is_bookable" AND "service"."online_only" AND ("profile"."status" = 'approved'::"public"."therapist_status") AND "profile"."is_public" AND "profile"."is_accepting_bookings" AND "profile"."accepts_online_sessions")
          GROUP BY "service"."therapy_id"
        )
 SELECT "therapy"."id",
    "therapy"."slug",
    "therapy"."name",
    "therapy"."short_description",
    "therapy"."description",
    "therapy"."image_url",
    "therapy"."status",
    "therapy"."published_at",
    "therapy"."popularity_score",
    "therapy"."created_at",
    "therapy"."updated_at",
    COALESCE("therapist_counts"."therapist_count", 0) AS "therapist_count",
    (("therapy"."popularity_score" >= 80) OR "therapy"."is_featured") AS "is_popular",
    (("therapy"."published_at" IS NOT NULL) AND ("therapy"."published_at" >= ("now"() - '45 days'::interval))) AS "is_new",
    "lower"("public"."unaccent"("concat_ws"(' '::"text", "therapy"."name", "therapy"."short_description", "therapy"."description", "array_to_string"("theme_names"."names", ' '::"text"), "array_to_string"("therapy"."search_aliases", ' '::"text")))) AS "search_text",
    "therapy"."is_featured",
    "theme_names"."names" AS "theme_names",
    "theme_names"."slugs" AS "theme_slugs"
   FROM (("public"."therapies" "therapy"
     LEFT JOIN "therapist_counts" ON (("therapist_counts"."therapy_id" = "therapy"."id")))
     JOIN LATERAL ( SELECT "array_agg"("theme"."name" ORDER BY "link"."sort_order", "theme"."name") AS "names",
            "array_agg"("theme"."slug" ORDER BY "link"."sort_order", "theme"."name") AS "slugs"
           FROM ("public"."therapy_matching_themes" "link"
             JOIN "public"."matching_themes" "theme" ON ((("theme"."id" = "link"."theme_id") AND "theme"."is_active")))
          WHERE ("link"."therapy_id" = "therapy"."id")) "theme_names" ON (true))
  WHERE (("therapy"."status" = 'published'::"public"."therapy_status") AND "therapy"."is_public_visible" AND "public"."therapy_has_active_matching_theme_v1"("therapy"."id"));


ALTER VIEW "public"."public_therapies_v" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_home_therapies" WITH ("security_invoker"='true') AS
 SELECT "id",
    "name",
    "slug",
    "slug" AS "href_slug",
    "short_description",
    "is_featured",
    "theme_names"[1] AS "theme_name",
    "theme_slugs"[1] AS "theme_slug",
    "updated_at"
   FROM "public"."public_therapies_v";


ALTER VIEW "public"."public_home_therapies" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."review_replies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "review_id" "uuid" NOT NULL,
    "therapist_profile_id" "uuid" NOT NULL,
    "body" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "review_replies_body_not_blank" CHECK (("length"(TRIM(BOTH FROM "body")) > 0)),
    CONSTRAINT "review_replies_status" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'hidden'::"text"])))
);


ALTER TABLE "public"."review_replies" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_therapist_profile_reviews_v_internal" AS
 SELECT "therapist"."slug" AS "therapist_slug",
    "review"."id",
    'Paciente TES'::"text" AS "author_label",
    COALESCE("review"."comment", ''::"text") AS "body",
    'Paciente com encontro realizado na plataforma'::"text" AS "patient_context",
        CASE
            WHEN ("review"."published_at" >= ("now"() - '2 days'::interval)) THEN 'Há dois dias'::"text"
            WHEN ("review"."published_at" >= ("now"() - '8 days'::interval)) THEN 'Há uma semana'::"text"
            ELSE 'Experiência compartilhada'::"text"
        END AS "created_label",
    "review"."rating",
    "review"."published_at",
    "reply"."body" AS "reply_body",
    "reply"."published_at" AS "reply_published_at"
   FROM (("public"."reviews" "review"
     JOIN "public"."therapist_profiles" "therapist" ON (("therapist"."id" = "review"."therapist_profile_id")))
     LEFT JOIN "public"."review_replies" "reply" ON ((("reply"."review_id" = "review"."id") AND ("reply"."status" = 'published'::"text"))))
  WHERE (("review"."status" = 'published'::"public"."review_status") AND ("review"."superseded_at" IS NULL));


ALTER VIEW "public"."public_therapist_profile_reviews_v_internal" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_therapist_profile_reviews_v_internal" IS 'Canonical published relationship reviews. Visibility is independent from future booking/payment state.';



CREATE OR REPLACE VIEW "public"."public_home_therapists_internal" AS
 SELECT "therapist"."id",
    "therapist"."slug",
    "therapist"."public_name",
    "therapist"."headline",
    "therapist"."photo_url",
    "therapist"."accepts_online_sessions",
    "summary"."service_title",
    "summary"."service_price_from_cents",
    "reviews"."average_rating",
    "reviews"."review_count",
    "therapist"."updated_at"
   FROM (("public"."therapist_profiles" "therapist"
     JOIN LATERAL ( SELECT "service"."title" AS "service_title",
            "service"."price_cents" AS "service_price_from_cents"
           FROM ("public"."therapist_services" "service"
             JOIN "public"."therapies" "therapy" ON (("therapy"."id" = "service"."therapy_id")))
          WHERE (("service"."therapist_profile_id" = "therapist"."id") AND ("service"."status" = 'active'::"public"."service_status") AND "service"."is_bookable" AND "service"."online_only" AND ("therapy"."status" = 'published'::"public"."therapy_status") AND "therapy"."is_public_visible" AND "public"."therapy_has_active_matching_theme_v1"("therapy"."id"))
          ORDER BY "service"."position", "service"."price_cents", "therapy"."name", "service"."title", "service"."id"
         LIMIT 1) "summary" ON (true))
     LEFT JOIN LATERAL ( SELECT "round"("avg"("review"."rating"), 1) AS "average_rating",
            ("count"(*))::integer AS "review_count"
           FROM "public"."public_therapist_profile_reviews_v_internal" "review"
          WHERE ("review"."therapist_slug" = "therapist"."slug")) "reviews" ON (true))
  WHERE (("therapist"."status" = 'approved'::"public"."therapist_status") AND "therapist"."is_public" AND "therapist"."is_accepting_bookings" AND "therapist"."accepts_online_sessions");


ALTER VIEW "public"."public_home_therapists_internal" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_home_therapists_internal" IS 'Private home therapist DTO. Rating aggregates use canonical published relationship reviews.';



CREATE OR REPLACE VIEW "public"."public_home_therapists" AS
 SELECT "id",
    "slug",
    "public_name",
    "headline",
    "photo_url",
    "accepts_online_sessions",
    "service_title",
    "service_price_from_cents",
    "average_rating",
    "review_count",
    "updated_at"
   FROM "public"."public_home_therapists_internal" "i"
  WHERE "public"."is_therapist_publication_eligible_v1"("id");


ALTER VIEW "public"."public_home_therapists" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_matching_config" WITH ("security_invoker"='true') AS
 SELECT "matching_versions"."id" AS "version_id",
    "matching_versions"."version",
    "matching_themes"."id" AS "theme_id",
    "matching_themes"."name" AS "theme_name",
    "matching_themes"."slug" AS "theme_slug",
    "matching_themes"."description" AS "theme_description",
    "matching_themes"."image_url" AS "theme_image_url",
    "matching_themes"."sort_order" AS "theme_sort_order",
    "matching_interests"."id" AS "interest_id",
    "matching_interests"."name" AS "interest_name",
    "matching_interests"."slug" AS "interest_slug",
    "matching_interests"."sort_order" AS "interest_sort_order"
   FROM (("public"."matching_versions"
     JOIN "public"."matching_themes" ON (("matching_themes"."is_active" = true)))
     LEFT JOIN "public"."matching_interests" ON ((("matching_interests"."theme_id" = "matching_themes"."id") AND ("matching_interests"."is_active" = true))))
  WHERE ("matching_versions"."status" = 'published'::"public"."matching_version_status")
  ORDER BY "matching_themes"."sort_order", "matching_interests"."sort_order";


ALTER VIEW "public"."public_matching_config" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_matching_config" IS 'Public Match configuration DTO. SECURITY INVOKER: relies on public RLS for published matching versions and active themes/interests.';



