CREATE OR REPLACE VIEW "public"."public_therapy_details_v" WITH ("security_invoker"='true') AS
 SELECT "catalog"."id",
    "catalog"."slug",
    "catalog"."name",
    "catalog"."short_description",
    "catalog"."description",
    COALESCE("content"."hero_image_url", "catalog"."image_url") AS "hero_image_url",
    "catalog"."image_url",
    "catalog"."therapist_count",
    "catalog"."theme_slugs",
    "catalog"."theme_names",
    "content"."subtitle",
    "content"."introduction",
    "content"."complementary_description",
    COALESCE("content"."safety_note", "therapy"."safety_note") AS "safety_note",
    "content"."seo_title",
    "content"."seo_description",
    COALESCE("content"."approach_label", "catalog"."theme_names"[1]) AS "approach_label",
    COALESCE("content"."approach_icon_key", 'sparkles'::"text") AS "approach_icon_key",
    COALESCE(("content"."visual_theme_key")::"text", 'energy'::"text") AS "visual_theme_key",
    COALESCE("content"."hero_focal_point", 'center'::"text") AS "hero_focal_point",
    COALESCE("highlights"."items", '[]'::"jsonb") AS "highlights",
    COALESCE("benefits"."items", '[]'::"jsonb") AS "benefits",
    "catalog"."published_at",
    "catalog"."updated_at"
   FROM (((("public"."public_therapies_v" "catalog"
     JOIN "public"."therapies" "therapy" ON (("therapy"."id" = "catalog"."id")))
     LEFT JOIN "public"."therapy_public_content" "content" ON (("content"."therapy_id" = "catalog"."id")))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('title', "h"."title", 'iconKey', "h"."icon_key") ORDER BY "h"."sort_order") AS "items"
           FROM "public"."therapy_highlights" "h"
          WHERE ("h"."therapy_id" = "catalog"."id")) "highlights" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('title', "b"."title", 'description', "b"."description", 'iconKey', "b"."icon_key") ORDER BY "b"."sort_order") AS "items"
           FROM "public"."therapy_benefits" "b"
          WHERE ("b"."therapy_id" = "catalog"."id")) "benefits" ON (true))
  WHERE ("therapy"."archived_at" IS NULL);


ALTER VIEW "public"."public_therapy_details_v" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_matching_therapies_v" WITH ("security_invoker"='true') AS
 SELECT "detail"."id",
    "detail"."name",
    "detail"."slug",
    "detail"."short_description",
    "detail"."description",
    "detail"."image_url",
    "therapy"."status",
    "detail"."therapist_count",
    "settings"."is_visible_in_matching"
   FROM (("public"."public_therapy_details_v" "detail"
     JOIN "public"."therapies" "therapy" ON (("therapy"."id" = "detail"."id")))
     JOIN "public"."matching_therapy_settings" "settings" ON (("settings"."therapy_id" = "detail"."id")))
  WHERE (("therapy"."status" = 'published'::"public"."therapy_status") AND "therapy"."is_public_visible" AND ("therapy"."archived_at" IS NULL) AND "settings"."is_visible_in_matching");


ALTER VIEW "public"."public_matching_therapies_v" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_matching_therapist_counts" WITH ("security_invoker"='true') AS
 SELECT "catalog"."id" AS "therapy_id",
    "catalog"."therapist_count"
   FROM ("public"."public_therapies_v" "catalog"
     JOIN "public"."matching_therapy_settings" "settings" ON ((("settings"."therapy_id" = "catalog"."id") AND "settings"."is_visible_in_matching")))
  WHERE ("catalog"."status" = 'published'::"public"."therapy_status");


ALTER VIEW "public"."public_matching_therapist_counts" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_matching_therapist_counts" IS 'Public Match therapist-count projection. Counts distinct therapists with an active, online, bookable and publication-eligible service for each visible Match therapy.';



CREATE OR REPLACE VIEW "public"."public_matching_therapy_themes_v" WITH ("security_invoker"='true') AS
 SELECT "therapy_matching_themes"."therapy_id",
    "therapy_matching_themes"."theme_id",
    "matching_themes"."name" AS "theme_name",
    "matching_themes"."slug" AS "theme_slug",
    "therapy_matching_themes"."sort_order"
   FROM ((("public"."therapy_matching_themes"
     JOIN "public"."matching_themes" ON (("matching_themes"."id" = "therapy_matching_themes"."theme_id")))
     JOIN "public"."therapies" ON (("therapies"."id" = "therapy_matching_themes"."therapy_id")))
     JOIN "public"."matching_therapy_settings" ON (("matching_therapy_settings"."therapy_id" = "therapy_matching_themes"."therapy_id")))
  WHERE (("matching_themes"."is_active" = true) AND ("therapies"."status" = 'published'::"public"."therapy_status") AND ("therapies"."is_public_visible" = true) AND ("therapies"."archived_at" IS NULL) AND ("matching_therapy_settings"."is_visible_in_matching" = true) AND (EXISTS ( SELECT 1
           FROM ("public"."matching_weights"
             JOIN "public"."matching_versions" ON (("matching_versions"."id" = "matching_weights"."version_id")))
          WHERE (("matching_weights"."therapy_id" = "therapies"."id") AND ("matching_weights"."theme_id" = "therapy_matching_themes"."theme_id") AND ("matching_weights"."is_active" = true) AND ("matching_versions"."status" = 'published'::"public"."matching_version_status")))));


ALTER VIEW "public"."public_matching_therapy_themes_v" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_matching_therapy_themes_v" IS 'Safe public Match therapy-theme projection. SECURITY INVOKER by design; base-table RLS exposes only active themes attached to published, public, Match-visible therapies with active weights in the published Match version.';



CREATE TABLE IF NOT EXISTS "public"."therapist_profile_content_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "therapist_profile_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "short_intro" "text",
    "essence_body" "text",
    "invitation_body" "text",
    "video_url" "text",
    "video_provider" "text",
    "video_thumbnail_url" "text",
    "video_title" "text",
    "experience_years" integer,
    "published_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "profile_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "base_profile_version" bigint,
    "public_profile_theme" "text" DEFAULT 'serene'::"text" NOT NULL,
    "bio_illustration_id" "text",
    CONSTRAINT "therapist_profile_content_bio_illustration_check" CHECK ((("bio_illustration_id" IS NULL) OR ("bio_illustration_id" = ANY (ARRAY['organic_flow'::"text", 'gentle_horizon'::"text", 'warm_layers'::"text", 'essential_lines'::"text"])))),
    CONSTRAINT "therapist_profile_content_theme_check" CHECK (("public_profile_theme" = ANY (ARRAY['ancestral'::"text", 'aurora'::"text", 'botanico'::"text", 'celestial'::"text", 'cristalino'::"text", 'energia'::"text", 'essencial_editorial'::"text", 'essential'::"text", 'frequencia'::"text", 'geometria'::"text", 'lunar'::"text", 'natural'::"text", 'oraculo'::"text", 'profundo'::"text", 'sagrado'::"text", 'sereno_horizonte'::"text", 'serene'::"text", 'vinculos'::"text", 'warm'::"text"]))),
    CONSTRAINT "therapist_profile_content_versions_experience" CHECK ((("experience_years" IS NULL) OR ("experience_years" >= 0))),
    CONSTRAINT "therapist_profile_content_versions_status" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text", 'in_review'::"text"])))
);


ALTER TABLE "public"."therapist_profile_content_versions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."therapist_profile_content_versions"."profile_payload" IS 'Draft/published public identity fields that are applied to therapist_profiles only on therapist publication.';



COMMENT ON COLUMN "public"."therapist_profile_content_versions"."bio_illustration_id" IS 'Optional official TES bio illustration identifier; null means no illustration.';



