ALTER TABLE "public"."therapist_profile_reflections" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_therapist_profile_content_v" WITH ("security_invoker"='true') AS
 SELECT "p"."slug",
    "v"."short_intro",
    "v"."essence_body",
    "v"."invitation_body",
    "v"."experience_years",
    COALESCE("guide_items"."items", '[]'::"jsonb") AS "guide_items",
    COALESCE("reflections"."items", '[]'::"jsonb") AS "reflections",
    "p"."public_profile_theme",
    "v"."bio_illustration_id"
   FROM ((("public"."therapist_profiles" "p"
     JOIN LATERAL ( SELECT "content"."id",
            "content"."therapist_profile_id",
            "content"."short_intro",
            "content"."essence_body",
            "content"."invitation_body",
            "content"."experience_years",
            "content"."public_profile_theme",
            "content"."bio_illustration_id"
           FROM "public"."therapist_profile_content_versions" "content"
          WHERE (("content"."therapist_profile_id" = "p"."id") AND ("content"."status" = 'published'::"text"))
          ORDER BY "content"."published_at" DESC NULLS LAST, "content"."created_at" DESC
         LIMIT 1) "v" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('icon', "i"."icon", 'label', "i"."label") ORDER BY "i"."sort_order") AS "items"
           FROM "public"."therapist_profile_guide_items" "i"
          WHERE (("i"."content_version_id" = "v"."id") AND "i"."is_active")) "guide_items" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('href', "r"."href", 'imageUrl', "r"."image_url", 'minutesToRead', "r"."minutes_to_read", 'title', "r"."title") ORDER BY "r"."sort_order") AS "items"
           FROM "public"."therapist_profile_reflections" "r"
          WHERE (("r"."content_version_id" = "v"."id") AND "r"."is_public")) "reflections" ON (true))
  WHERE "public"."is_therapist_publication_eligible_v1"("p"."id");


ALTER VIEW "public"."public_therapist_profile_content_v" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_therapist_profile_content_v_internal" WITH ("security_invoker"='true') AS
 SELECT "therapist_profiles"."slug",
    "therapist_profile_content_versions"."therapist_profile_id",
    "therapist_profile_content_versions"."short_intro",
    "therapist_profile_content_versions"."essence_body",
    "therapist_profile_content_versions"."invitation_body",
    "therapist_profile_content_versions"."experience_years",
    COALESCE("guide_items"."items", '[]'::"jsonb") AS "guide_items",
    COALESCE("reflections"."items", '[]'::"jsonb") AS "reflections"
   FROM ((("public"."therapist_profiles"
     JOIN "public"."therapist_profile_content_versions" ON (("therapist_profile_content_versions"."therapist_profile_id" = "therapist_profiles"."id")))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('icon', "therapist_profile_guide_items"."icon", 'label', "therapist_profile_guide_items"."label") ORDER BY "therapist_profile_guide_items"."sort_order") AS "items"
           FROM "public"."therapist_profile_guide_items"
          WHERE (("therapist_profile_guide_items"."content_version_id" = "therapist_profile_content_versions"."id") AND ("therapist_profile_guide_items"."is_active" = true))) "guide_items" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('href', "therapist_profile_reflections"."href", 'imageUrl', "therapist_profile_reflections"."image_url", 'minutesToRead', "therapist_profile_reflections"."minutes_to_read", 'title', "therapist_profile_reflections"."title") ORDER BY "therapist_profile_reflections"."sort_order") AS "items"
           FROM "public"."therapist_profile_reflections"
          WHERE (("therapist_profile_reflections"."content_version_id" = "therapist_profile_content_versions"."id") AND ("therapist_profile_reflections"."is_public" = true))) "reflections" ON (true))
  WHERE (("therapist_profiles"."status" = 'approved'::"public"."therapist_status") AND ("therapist_profiles"."is_public" IS TRUE) AND ("therapist_profile_content_versions"."status" = 'published'::"text"));


ALTER VIEW "public"."public_therapist_profile_content_v_internal" OWNER TO "postgres";


