CREATE TABLE IF NOT EXISTS "public"."therapist_service_booking_settings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_id" "uuid" NOT NULL,
    "buffer_before_minutes" integer DEFAULT 0 NOT NULL,
    "buffer_after_minutes" integer DEFAULT 0 NOT NULL,
    "min_notice_minutes" integer DEFAULT 120 NOT NULL,
    "max_days_ahead" integer DEFAULT 90 NOT NULL,
    "interval_minutes" integer DEFAULT 30 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "therapist_service_booking_settings_no_pre_session_buffer" CHECK (("buffer_before_minutes" = 0)),
    CONSTRAINT "therapist_service_booking_settings_positive" CHECK ((("buffer_before_minutes" >= 0) AND ("buffer_after_minutes" >= 0) AND ("min_notice_minutes" >= 0) AND ("max_days_ahead" > 0) AND ("interval_minutes" > 0)))
);


ALTER TABLE "public"."therapist_service_booking_settings" OWNER TO "postgres";


COMMENT ON COLUMN "public"."therapist_service_booking_settings"."buffer_before_minutes" IS 'Compatibility field fixed at zero for current settings; historical booking and hold snapshots are preserved.';



COMMENT ON COLUMN "public"."therapist_service_booking_settings"."buffer_after_minutes" IS 'Therapist-selected free time after a newly reserved session; existing booking and hold snapshots remain immutable.';



COMMENT ON COLUMN "public"."therapist_service_booking_settings"."interval_minutes" IS 'Fixed cadence of candidate session starts, anchored at each availability window start; never post-session rest.';



CREATE OR REPLACE VIEW "public"."public_therapist_profile_services_v_internal" AS
 SELECT "therapist"."slug" AS "therapist_slug",
    "service"."id" AS "service_id",
    "service"."title" AS "service_title",
    "service"."description",
    "service"."duration_minutes",
    "service"."price_cents",
    "service"."currency",
    "therapy"."id" AS "therapy_id",
    "therapy"."name" AS "therapy_name",
    "therapy"."slug" AS "therapy_slug",
    "row_number"() OVER (PARTITION BY "therapist"."id" ORDER BY "service"."position", "service"."price_cents", "therapy"."name", "service"."title", "service"."id") AS "sort_order",
    COALESCE("settings"."buffer_before_minutes", 0) AS "buffer_before_minutes",
    COALESCE("settings"."buffer_after_minutes", 0) AS "buffer_after_minutes",
    COALESCE("settings"."min_notice_minutes", 120) AS "min_notice_minutes",
    COALESCE("settings"."max_days_ahead", 90) AS "max_days_ahead",
    COALESCE("settings"."interval_minutes", 30) AS "interval_minutes",
    COALESCE("rules"."items", '[]'::"jsonb") AS "availability_rules",
    COALESCE("exceptions"."items", '[]'::"jsonb") AS "availability_exceptions",
    COALESCE("conflicts"."items", '[]'::"jsonb") AS "booking_conflicts"
   FROM (((((("public"."therapist_profiles" "therapist"
     JOIN "public"."therapist_services" "service" ON (("service"."therapist_profile_id" = "therapist"."id")))
     JOIN "public"."therapies" "therapy" ON (("therapy"."id" = "service"."therapy_id")))
     LEFT JOIN "public"."therapist_service_booking_settings" "settings" ON (("settings"."service_id" = "service"."id")))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('dayOfWeek', "rule"."day_of_week", 'endTime', ("rule"."end_time")::"text", 'isActive', "rule"."is_active", 'serviceId', "rule"."service_id", 'startTime', ("rule"."start_time")::"text", 'timezone', "rule"."timezone") ORDER BY "rule"."day_of_week", "rule"."start_time") AS "items"
           FROM "public"."availability_rules" "rule"
          WHERE (("rule"."therapist_profile_id" = "therapist"."id") AND (("rule"."service_id" IS NULL) OR ("rule"."service_id" = "service"."id")) AND "rule"."is_active")) "rules" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('endsAt', "exception"."ends_at", 'isAvailable', "exception"."is_available", 'serviceId', "exception"."service_id", 'startsAt', "exception"."starts_at")) AS "items"
           FROM "public"."availability_exceptions" "exception"
          WHERE (("exception"."therapist_profile_id" = "therapist"."id") AND (("exception"."service_id" IS NULL) OR ("exception"."service_id" = "service"."id")) AND ("exception"."ends_at" >= "now"()))) "exceptions" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('endsAt', "booking"."ends_at", 'serviceId', "booking"."service_id", 'startsAt', "booking"."starts_at", 'status', "booking"."status")) AS "items"
           FROM "public"."bookings" "booking"
          WHERE (("booking"."therapist_profile_id" = "therapist"."id") AND ("booking"."service_id" = "service"."id") AND ("booking"."ends_at" >= "now"()) AND ("booking"."status" = ANY (ARRAY['pending_payment'::"public"."booking_status", 'confirmed'::"public"."booking_status", 'completed'::"public"."booking_status"])))) "conflicts" ON (true))
  WHERE (("therapist"."status" = 'approved'::"public"."therapist_status") AND "therapist"."is_public" AND "therapist"."is_accepting_bookings" AND "therapist"."accepts_online_sessions" AND ("service"."status" = 'active'::"public"."service_status") AND "service"."is_bookable" AND "service"."online_only" AND ("therapy"."status" = 'published'::"public"."therapy_status") AND "therapy"."is_public_visible" AND "public"."therapy_has_active_matching_theme_v1"("therapy"."id"));


ALTER VIEW "public"."public_therapist_profile_services_v_internal" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_therapist_profile_services_v_internal" IS 'Safe public projection for public therapist services with canonical therapy identity and derived availability inputs.';



CREATE OR REPLACE VIEW "public"."public_therapist_profile_services_v" AS
 SELECT "i"."therapist_slug",
    "i"."service_id",
    "i"."service_title",
    "i"."description",
    "i"."duration_minutes",
    "i"."price_cents",
    "i"."currency",
    "i"."therapy_id",
    "i"."therapy_name",
    "i"."therapy_slug",
    "i"."sort_order",
    "i"."buffer_before_minutes",
    "i"."buffer_after_minutes",
    "i"."min_notice_minutes",
    "i"."max_days_ahead",
    "i"."interval_minutes",
    "i"."availability_rules",
    "i"."availability_exceptions",
    "i"."booking_conflicts"
   FROM ("public"."public_therapist_profile_services_v_internal" "i"
     JOIN "public"."therapist_profiles" "p" ON (("p"."slug" = "i"."therapist_slug")))
  WHERE ("public"."is_public_service_booking_eligible_v1"("i"."service_id") AND "public"."is_therapist_publication_eligible_v1"("p"."id"));


ALTER VIEW "public"."public_therapist_profile_services_v" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."public_therapist_profiles_v_internal" AS
 SELECT "therapist"."id",
    "therapist"."slug",
    "therapist"."public_name",
    "therapist"."plan",
    "therapist"."bio",
    "therapist"."photo_url",
    "therapist"."city",
    "therapist"."state",
    "therapist"."is_accepting_bookings",
    "therapist"."accepts_online_sessions",
    true AS "is_verified",
    COALESCE("content"."short_intro", "therapist"."headline") AS "short_intro",
    COALESCE("content"."short_intro", "therapist"."headline") AS "published_headline",
    COALESCE("tags"."tags", ARRAY[]::"text"[]) AS "tags",
    COALESCE("content"."video_url", ("therapist"."metadata" ->> 'video_url'::"text")) AS "video_url",
    COALESCE("content"."video_provider", 'external'::"text") AS "video_provider",
    COALESCE("content"."video_thumbnail_url", '/home/tablet-video-session.png'::"text") AS "video_thumbnail_url",
    COALESCE("content"."video_title", 'Um convite para você'::"text") AS "video_title",
        CASE
            WHEN ("therapist"."plan" = 'premium_plus'::"public"."therapist_plan") THEN ARRAY['Perfil verificado'::"text", 'Terapeuta Plus'::"text"]
            ELSE ARRAY['Perfil verificado'::"text"]
        END AS "badges",
    "review_summary"."average_rating",
    "review_summary"."review_count",
    (COALESCE("session_summary"."sessions_completed", (0)::bigint))::integer AS "sessions_completed",
    "therapist"."updated_at"
   FROM (((("public"."therapist_profiles" "therapist"
     LEFT JOIN LATERAL ( SELECT "content_version"."id",
            "content_version"."therapist_profile_id",
            "content_version"."status",
            "content_version"."short_intro",
            "content_version"."essence_body",
            "content_version"."invitation_body",
            "content_version"."video_url",
            "content_version"."video_provider",
            "content_version"."video_thumbnail_url",
            "content_version"."video_title",
            "content_version"."experience_years",
            "content_version"."published_at",
            "content_version"."created_at",
            "content_version"."updated_at",
            "content_version"."profile_payload",
            "content_version"."base_profile_version",
            "content_version"."public_profile_theme",
            "content_version"."bio_illustration_id"
           FROM "public"."therapist_profile_content_versions" "content_version"
          WHERE (("content_version"."therapist_profile_id" = "therapist"."id") AND ("content_version"."status" = 'published'::"text"))
          ORDER BY "content_version"."published_at" DESC NULLS LAST, "content_version"."created_at" DESC
         LIMIT 1) "content" ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE("array_agg"("tag"."value" ORDER BY "tag"."value"), ARRAY[]::"text"[]) AS "tags"
           FROM "jsonb_array_elements_text"(
                CASE
                    WHEN ("jsonb_typeof"(("therapist"."metadata" -> 'care_tags'::"text")) = 'array'::"text") THEN ("therapist"."metadata" -> 'care_tags'::"text")
                    ELSE '[]'::"jsonb"
                END) "tag"("value")) "tags" ON (true))
     LEFT JOIN LATERAL ( SELECT "round"("avg"("review"."rating"), 1) AS "average_rating",
            ("count"(*))::integer AS "review_count"
           FROM "public"."public_therapist_profile_reviews_v_internal" "review"
          WHERE ("review"."therapist_slug" = "therapist"."slug")) "review_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "sessions_completed"
           FROM ("public"."bookings" "booking"
             JOIN "public"."session_payments" "payment" ON (("payment"."booking_id" = "booking"."id")))
          WHERE (("booking"."therapist_profile_id" = "therapist"."id") AND ("booking"."status" = 'completed'::"public"."booking_status") AND ("payment"."financial_status" = 'paid'::"public"."session_financial_status"))) "session_summary" ON (true))
  WHERE (("therapist"."status" = 'approved'::"public"."therapist_status") AND ("therapist"."is_public" = true) AND (EXISTS ( SELECT 1
           FROM ("public"."therapist_services" "service"
             JOIN "public"."therapies" "therapy" ON (("therapy"."id" = "service"."therapy_id")))
          WHERE (("service"."therapist_profile_id" = "therapist"."id") AND ("service"."status" = 'active'::"public"."service_status") AND ("service"."is_bookable" = true) AND ("service"."online_only" = true) AND ("therapy"."status" = 'published'::"public"."therapy_status") AND ("therapy"."is_public_visible" = true)))));


ALTER VIEW "public"."public_therapist_profiles_v_internal" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_therapist_profiles_v_internal" IS 'Private therapist profile DTO. Rating aggregates use canonical published relationship reviews.';



CREATE OR REPLACE VIEW "public"."public_therapist_profiles_v" AS
 SELECT "id",
    "slug",
    "public_name",
    "plan",
    "bio",
    "photo_url",
    "city",
    "state",
    "is_accepting_bookings",
    "accepts_online_sessions",
    "is_verified",
    "short_intro",
    "published_headline",
    "tags",
    "video_url",
    "video_provider",
    "video_thumbnail_url",
    "video_title",
    "badges",
    "average_rating",
    "review_count",
    "sessions_completed",
    "updated_at"
   FROM "public"."public_therapist_profiles_v_internal" "i"
  WHERE "public"."is_therapist_publication_eligible_v1"("id");


ALTER VIEW "public"."public_therapist_profiles_v" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."therapist_schedule_settings" (
    "therapist_profile_id" "uuid" NOT NULL,
    "timezone" "text" DEFAULT 'America/Sao_Paulo'::"text" NOT NULL,
    "version" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "therapist_schedule_settings_brasilia_timezone" CHECK (("timezone" = 'America/Sao_Paulo'::"text")),
    CONSTRAINT "therapist_schedule_settings_version_positive" CHECK (("version" > 0))
);


ALTER TABLE "public"."therapist_schedule_settings" OWNER TO "postgres";


COMMENT ON TABLE "public"."therapist_schedule_settings" IS 'Canonical therapist business timezone and optimistic schedule version.';



CREATE OR REPLACE VIEW "public"."public_therapist_search_internal" AS
 SELECT "therapist"."id" AS "therapist_profile_id",
    "therapist"."slug",
    "therapist"."public_name",
    "therapist"."headline" AS "therapist_headline",
    "therapist"."bio" AS "therapist_bio",
    "therapist"."photo_url",
    "therapist"."city",
    "therapist"."state",
    "service_summary"."service_id",
    "service_summary"."service_title",
    "service_summary"."service_description",
    "service_summary"."service_price_cents",
    "service_summary"."duration_minutes",
    "service_summary"."therapy_id",
    "service_summary"."therapy_name",
    "service_summary"."therapy_slug",
    "theme_summary"."theme_names",
    "theme_summary"."theme_slugs",
    COALESCE("care_tags"."items", "theme_summary"."theme_names", ARRAY["service_summary"."therapy_name"]) AS "tags",
    "next_slot"."next_slot_at",
    COALESCE("review_summary"."average_rating", (0)::numeric) AS "average_rating",
    COALESCE("review_summary"."review_count", 0) AS "review_count",
    (COALESCE("session_summary"."completed_session_count", (0)::bigint))::integer AS "completed_session_count",
    "review_quote"."review_quote",
    COALESCE((("therapist"."metadata" ->> 'has_intro_video'::"text"))::boolean, false) AS "has_video",
    COALESCE(("therapist"."metadata" ->> 'highlight'::"text"),
        CASE
            WHEN ("therapist"."plan" = ANY (ARRAY['premium'::"public"."therapist_plan", 'premium_plus'::"public"."therapist_plan"])) THEN 'Destaque TES'::"text"
            ELSE 'Perfil Verificado'::"text"
        END) AS "highlight",
        CASE
            WHEN (("therapist"."metadata" ->> 'highlight_tone'::"text") = ANY (ARRAY['featured'::"text", 'verified'::"text"])) THEN ("therapist"."metadata" ->> 'highlight_tone'::"text")
            WHEN ("therapist"."plan" = ANY (ARRAY['premium'::"public"."therapist_plan", 'premium_plus'::"public"."therapist_plan"])) THEN 'featured'::"text"
            ELSE 'verified'::"text"
        END AS "highlight_tone",
    "concat_ws"(' '::"text", "therapist"."public_name", "therapist"."headline", "therapist"."bio", "therapist"."city", "therapist"."state", "service_summary"."service_title", "service_summary"."service_description", "service_summary"."therapy_name", "array_to_string"("theme_summary"."theme_names", ' '::"text"), "array_to_string"("care_tags"."items", ' '::"text")) AS "search_text",
    "therapist"."updated_at",
    "schedule_timezone"."timezone" AS "schedule_timezone"
   FROM (((((((("public"."therapist_profiles" "therapist"
     JOIN LATERAL ( SELECT "service"."id" AS "service_id",
            "service"."title" AS "service_title",
            "service"."description" AS "service_description",
            "service"."price_cents" AS "service_price_cents",
            "service"."duration_minutes",
            "therapy"."id" AS "therapy_id",
            "therapy"."name" AS "therapy_name",
            "therapy"."slug" AS "therapy_slug"
           FROM ("public"."therapist_services" "service"
             JOIN "public"."therapies" "therapy" ON (("therapy"."id" = "service"."therapy_id")))
          WHERE (("service"."therapist_profile_id" = "therapist"."id") AND ("service"."status" = 'active'::"public"."service_status") AND "service"."is_bookable" AND "service"."online_only" AND ("service"."archived_at" IS NULL) AND ("therapy"."status" = 'published'::"public"."therapy_status") AND "therapy"."is_public_visible" AND "public"."therapy_has_active_matching_theme_v1"("therapy"."id"))
          ORDER BY "service"."price_cents", "service"."title", "service"."id"
         LIMIT 1) "service_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT "array_agg"("theme_row"."name" ORDER BY "theme_row"."sort_order", "theme_row"."name") AS "theme_names",
            "array_agg"("theme_row"."slug" ORDER BY "theme_row"."sort_order", "theme_row"."name") AS "theme_slugs"
           FROM ( SELECT DISTINCT "theme"."id",
                    "theme"."name",
                    "theme"."slug",
                    "link"."sort_order"
                   FROM ("public"."therapy_matching_themes" "link"
                     JOIN "public"."matching_themes" "theme" ON ((("theme"."id" = "link"."theme_id") AND "theme"."is_active")))
                  WHERE ("link"."therapy_id" = "service_summary"."therapy_id")) "theme_row") "theme_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT "array_agg"("tag"."value" ORDER BY "tag"."value") AS "items"
           FROM "jsonb_array_elements_text"(
                CASE
                    WHEN ("jsonb_typeof"(("therapist"."metadata" -> 'care_tags'::"text")) = 'array'::"text") THEN ("therapist"."metadata" -> 'care_tags'::"text")
                    ELSE '[]'::"jsonb"
                END) "tag"("value")) "care_tags" ON (true))
     LEFT JOIN LATERAL ( SELECT "round"("avg"("review"."rating"), 1) AS "average_rating",
            ("count"(*))::integer AS "review_count"
           FROM "public"."public_therapist_profile_reviews_v_internal" "review"
          WHERE ("review"."therapist_slug" = "therapist"."slug")) "review_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "completed_session_count"
           FROM "public"."bookings" "booking"
          WHERE (("booking"."therapist_profile_id" = "therapist"."id") AND ("booking"."status" = 'completed'::"public"."booking_status") AND ("booking"."payment_status" = 'paid'::"public"."payment_status"))) "session_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT "review"."body" AS "review_quote"
           FROM "public"."public_therapist_profile_reviews_v_internal" "review"
          WHERE (("review"."therapist_slug" = "therapist"."slug") AND ("review"."body" <> ''::"text") AND ("length"(TRIM(BOTH FROM "review"."body")) >= 12))
          ORDER BY "review"."published_at" DESC NULLS LAST, "review"."id" DESC
         LIMIT 1) "review_quote" ON (true))
     LEFT JOIN LATERAL ( SELECT "min"((("slot"."value" ->> 'startsAt'::"text"))::timestamp with time zone) AS "next_slot_at"
           FROM ((("public"."therapist_services" "candidate"
             JOIN "public"."therapies" "candidate_therapy" ON (("candidate_therapy"."id" = "candidate"."therapy_id")))
             CROSS JOIN LATERAL "generate_series"("now"(), ("now"() + '30 days'::interval), '5 days'::interval) "slot_window"("range_start"))
             CROSS JOIN LATERAL "jsonb_array_elements"(COALESCE(("public"."get_service_available_slots_v1"("candidate"."id", "slot_window"."range_start", LEAST(("slot_window"."range_start" + '5 days'::interval), ("now"() + '31 days'::interval)), 500) -> 'slots'::"text"), '[]'::"jsonb")) "slot"("value"))
          WHERE (("candidate"."therapist_profile_id" = "therapist"."id") AND ("candidate"."status" = 'active'::"public"."service_status") AND "candidate"."is_bookable" AND "candidate"."online_only" AND ("candidate"."archived_at" IS NULL) AND ("candidate_therapy"."status" = 'published'::"public"."therapy_status") AND "candidate_therapy"."is_public_visible" AND "public"."therapy_has_active_matching_theme_v1"("candidate_therapy"."id") AND "public"."is_public_service_booking_eligible_v1"("candidate"."id"))) "next_slot" ON (true))
     LEFT JOIN LATERAL ( SELECT "settings"."timezone"
           FROM "public"."therapist_schedule_settings" "settings"
          WHERE ("settings"."therapist_profile_id" = "therapist"."id")
         LIMIT 1) "schedule_timezone" ON (true))
  WHERE (("therapist"."status" = 'approved'::"public"."therapist_status") AND "therapist"."is_public" AND "therapist"."is_accepting_bookings" AND "therapist"."accepts_online_sessions");


ALTER VIEW "public"."public_therapist_search_internal" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_therapist_search_internal" IS 'Private therapist search DTO. Rating aggregates and quote use canonical published relationship reviews; next_slot_at remains derived from the authoritative public slot engine.';



CREATE OR REPLACE VIEW "public"."public_therapist_search" AS
 SELECT "therapist_profile_id",
    "slug",
    "public_name",
    "therapist_headline",
    "therapist_bio",
    "photo_url",
    "city",
    "state",
    "service_id",
    "service_title",
    "service_description",
    "service_price_cents",
    "duration_minutes",
    "therapy_id",
    "therapy_name",
    "therapy_slug",
    "theme_names",
    "theme_slugs",
    "tags",
    "next_slot_at",
    "average_rating",
    "review_count",
    "completed_session_count",
    "review_quote",
    "has_video",
    "highlight",
    "highlight_tone",
    "search_text",
    "updated_at",
    "schedule_timezone"
   FROM "public"."public_therapist_search_internal" "internal"
  WHERE "public"."is_therapist_publication_eligible_v1"("therapist_profile_id");


ALTER VIEW "public"."public_therapist_search" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_therapist_search" IS 'Safe public projection for therapist search. The selected service and next slot use the same eligibility and availability contracts as the public agenda.';



CREATE OR REPLACE VIEW "public"."public_therapist_slug_redirects_v" WITH ("security_invoker"='true') AS
 SELECT "old_slug",
    "current_slug"
   FROM "public"."public_therapist_slug_redirect_rows_v1"() "public_therapist_slug_redirect_rows_v1"("old_slug", "current_slug");


ALTER VIEW "public"."public_therapist_slug_redirects_v" OWNER TO "postgres";


