    "lease_expires_at" timestamp with time zone,
    "request_fingerprint" "text",
    "last_attempt_at" timestamp with time zone,
    "stripe_destination_payment_id" "text",
    "stripe_connected_balance_transaction_id" "text",
    "connected_balance_available_on" timestamp with time zone,
    "retry_cycle" integer DEFAULT 0 NOT NULL,
    "transfer_origin" "text" DEFAULT 'weekly_batch'::"text" NOT NULL,
    "therapist_gross_amount_cents" integer,
    "debt_offset_amount_cents" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "stripe_transfers_amount_positive" CHECK (("amount_cents" > 0)),
    CONSTRAINT "stripe_transfers_amount_split_check" CHECK (((("transfer_origin" = 'weekly_batch'::"text") AND ("therapist_gross_amount_cents" IS NULL)) OR (("therapist_gross_amount_cents" IS NOT NULL) AND ("debt_offset_amount_cents" >= 0) AND ("therapist_gross_amount_cents" = ("debt_offset_amount_cents" + "amount_cents"))))),
    CONSTRAINT "stripe_transfers_attempt_count_check" CHECK ((("attempt_count" >= 0) AND ("attempt_count" <= 4))),
    CONSTRAINT "stripe_transfers_currency_brl" CHECK (("currency" = 'BRL'::"bpchar")),
    CONSTRAINT "stripe_transfers_origin_check" CHECK (((("transfer_origin" = 'weekly_batch'::"text") AND ("payout_batch_item_id" IS NOT NULL)) OR (("transfer_origin" = 'session_direct'::"text") AND ("payout_batch_item_id" IS NULL) AND (NULLIF(TRIM(BOTH FROM "stripe_source_charge_id"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "stripe_transfers_retry_cycle_nonnegative" CHECK (("retry_cycle" >= 0))
);


