    CONSTRAINT "therapist_private_documents_status" CHECK (("status" = ANY (ARRAY['uploaded'::"text", 'accepted'::"text", 'rejected'::"text", 'archived'::"text"]))),
    CONSTRAINT "therapist_private_documents_validation" CHECK (("validation_state" = ANY (ARRAY['not_scanned'::"text", 'pending'::"text", 'passed'::"text", 'failed'::"text"])))
);


