CREATE OR REPLACE VIEW "public"."therapist_service_metrics_v1" WITH ("security_invoker"='true') AS
 SELECT "service"."id" AS "service_id",
    NULL::integer AS "favorite_count",
    ("count"(DISTINCT "booking"."id"))::integer AS "booking_count",
    ("count"(DISTINCT "booking"."id") FILTER (WHERE ("booking"."created_at" >= ("now"() - '30 days'::interval))))::integer AS "bookings_last_30_days",
    NULL::numeric AS "booking_count_delta_percent"
   FROM ("public"."therapist_services" "service"
     LEFT JOIN "public"."bookings" "booking" ON (("booking"."service_id" = "service"."id")))
  GROUP BY "service"."id";


ALTER VIEW "public"."therapist_service_metrics_v1" OWNER TO "postgres";


COMMENT ON COLUMN "public"."therapist_service_metrics_v1"."favorite_count" IS 'Deprecated compatibility column. Favorites are a therapist-profile metric and must never be attributed to an individual service.';



CREATE OR REPLACE VIEW "public"."therapist_private_services_v1" WITH ("security_invoker"='true') AS
 SELECT "service"."id" AS "service_id",
    "service"."therapist_profile_id",
    "service"."therapy_id",
    "therapy"."name" AS "therapy_name",
    "therapy"."slug" AS "therapy_slug",
    "therapy"."status" AS "therapy_status",
    "therapy"."is_public_visible" AS "therapy_is_public_visible",
    "therapy"."is_available_for_services",
    "service"."status",
    "service"."title",
    "service"."description",
    "service"."duration_minutes",
    "service"."price_cents",
    "service"."currency",
    "service"."delivery_format",
    "service"."online_only",
    "service"."is_bookable",
    "service"."position",
    "service"."version",
        CASE
            WHEN (("service"."status" <> 'active'::"public"."service_status") OR (NOT "service"."is_bookable") OR ("therapist"."status" <> 'approved'::"public"."therapist_status") OR (NOT "therapist"."is_public") OR (NOT "therapist"."is_accepting_bookings") OR ("therapy"."status" <> 'published'::"public"."therapy_status") OR (NOT "therapy"."is_public_visible") OR (NOT "public"."therapy_has_active_matching_theme_v1"("therapy"."id"))) THEN false
            ELSE true
        END AS "is_reservable",
        CASE
            WHEN ("service"."status" = 'paused'::"public"."service_status") THEN 'service_paused'::"text"
            WHEN ("service"."status" = 'archived'::"public"."service_status") THEN 'service_archived'::"text"
            WHEN ("service"."status" <> 'active'::"public"."service_status") THEN 'service_not_active'::"text"
            WHEN (NOT "service"."is_bookable") THEN 'service_not_accepting_bookings'::"text"
            WHEN ("therapist"."status" <> 'approved'::"public"."therapist_status") THEN 'therapist_not_approved'::"text"
            WHEN (NOT "therapist"."is_public") THEN 'therapist_profile_private'::"text"
            WHEN (NOT "therapist"."is_accepting_bookings") THEN 'therapist_not_accepting_bookings'::"text"
            WHEN ("therapy"."status" <> 'published'::"public"."therapy_status") THEN 'therapy_not_published'::"text"
            WHEN (NOT "therapy"."is_public_visible") THEN 'therapy_not_public'::"text"
            WHEN (NOT "public"."therapy_has_active_matching_theme_v1"("therapy"."id")) THEN 'therapy_without_active_theme'::"text"
            ELSE NULL::"text"
        END AS "blocking_reason",
    COALESCE("metrics"."favorite_count", 0) AS "favorite_count",
    COALESCE("metrics"."booking_count", 0) AS "booking_count",
    COALESCE("metrics"."bookings_last_30_days", 0) AS "bookings_last_30_days",
    "metrics"."booking_count_delta_percent",
    "service"."created_at",
    "service"."updated_at",
    "service"."archived_at",
    COALESCE("content"."hero_image_url", "therapy"."image_url") AS "therapy_image_url"
   FROM (((("public"."therapist_services" "service"
     JOIN "public"."therapist_profiles" "therapist" ON (("therapist"."id" = "service"."therapist_profile_id")))
     JOIN "public"."therapies" "therapy" ON (("therapy"."id" = "service"."therapy_id")))
     LEFT JOIN "public"."therapy_public_content" "content" ON (("content"."therapy_id" = "therapy"."id")))
     LEFT JOIN "public"."therapist_service_metrics_v1" "metrics" ON (("metrics"."service_id" = "service"."id")));


ALTER VIEW "public"."therapist_private_services_v1" OWNER TO "postgres";


