CREATE OR REPLACE VIEW "public"."therapist_service_allowed_catalog_v1" WITH ("security_invoker"='true') AS
 SELECT "therapy"."id" AS "therapy_id",
    "therapy"."name" AS "therapy_name",
    "therapy"."slug" AS "therapy_slug",
    "therapy"."short_description",
    "therapy"."status" AS "therapy_status",
    "therapy"."is_public_visible",
    "therapy"."is_available_for_services",
    COALESCE("settings"."is_visible_in_matching", false) AS "is_visible_in_matching",
    "therapy"."updated_at",
    COALESCE("themes"."items", '[]'::"jsonb") AS "matching_themes",
    COALESCE("content"."hero_image_url", "therapy"."image_url") AS "therapy_image_url"
   FROM ((("public"."therapies" "therapy"
     LEFT JOIN "public"."therapy_public_content" "content" ON (("content"."therapy_id" = "therapy"."id")))
     LEFT JOIN "public"."matching_therapy_settings" "settings" ON (("settings"."therapy_id" = "therapy"."id")))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('id', "theme"."id", 'name', "theme"."name", 'slug', "theme"."slug", 'sortOrder', "link"."sort_order", 'interests', COALESCE("interests"."items", '[]'::"jsonb")) ORDER BY "link"."sort_order", "theme"."name") AS "items"
           FROM (("public"."therapy_matching_themes" "link"
             JOIN "public"."matching_themes" "theme" ON ((("theme"."id" = "link"."theme_id") AND "theme"."is_active")))
             LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('id', "interest"."id", 'name', "interest"."name", 'slug', "interest"."slug", 'sortOrder', "interest"."sort_order", 'themeId', "interest"."theme_id") ORDER BY "interest"."sort_order", "interest"."name") AS "items"
                   FROM "public"."matching_interests" "interest"
                  WHERE (("interest"."theme_id" = "theme"."id") AND "interest"."is_active")) "interests" ON (true))
          WHERE ("link"."therapy_id" = "therapy"."id")) "themes" ON (true))
  WHERE (("therapy"."status" = 'published'::"public"."therapy_status") AND "therapy"."is_available_for_services" AND "public"."therapy_has_active_matching_theme_v1"("therapy"."id"));


