CREATE OR REPLACE VIEW "public"."therapist_session_read_model_v1" WITH ("security_invoker"='true') AS
 SELECT "booking"."id" AS "bookingId",
    "booking"."therapist_profile_id" AS "_therapistProfileId",
    "booking"."patient_profile_id" AS "patientProfileId",
    "patient"."display_name" AS "patientName",
    "patient"."avatar_url" AS "patientAvatarUrl",
    "booking"."service_id" AS "serviceId",
    "booking"."service_title_snapshot" AS "serviceTitle",
    "booking"."service_duration_minutes_snapshot" AS "durationMinutes",
    "booking"."service_price_cents_snapshot" AS "priceCents",
    "booking"."currency_snapshot" AS "currency",
    "booking"."starts_at" AS "startsAt",
    "booking"."ends_at" AS "endsAt",
    "booking"."timezone",
    "booking"."status" AS "bookingStatus",
    "booking"."version" AS "bookingVersion",
        CASE
            WHEN "service"."online_only" THEN 'online'::"text"
            ELSE 'in_person'::"text"
        END AS "modality",
    "payment"."financial_status" AS "financialStatus",
    "payment"."service_status" AS "fulfillmentStatus",
    "payment"."transfer_status" AS "transferStatus",
    "payment"."gross_amount_cents" AS "grossAmountCents",
    "payment"."therapist_amount_cents" AS "therapistAmountCents",
    "payment"."refund_pending" AS "refundPending",
        CASE "booking"."status"
            WHEN 'no_show_patient'::"public"."booking_status" THEN 'patient_no_show'::"text"
            WHEN 'no_show_therapist'::"public"."booking_status" THEN 'therapist_no_show'::"text"
            ELSE 'pending'::"text"
        END AS "attendanceStatus",
        CASE
            WHEN ("booking"."status" = ANY (ARRAY['no_show_patient'::"public"."booking_status", 'no_show_therapist'::"public"."booking_status"])) THEN 'booking_compatibility'::"text"
            ELSE 'unavailable'::"text"
        END AS "attendanceSource",
    "reschedule"."status" AS "rescheduleStatus",
    "reschedule"."proposed_starts_at" AS "proposedStartsAt",
    "reschedule"."proposed_ends_at" AS "proposedEndsAt",
    "reschedule"."proposed_timezone" AS "proposedTimezone",
    "cancellation"."decision" AS "cancellationDecision",
    "cancellation"."requires_manual_review" AS "cancellationRequiresReview",
    "video_session"."status" AS "videoSessionStatus",
    "video_session"."provider" AS "videoSessionProvider",
    (("video_session"."id" IS NOT NULL) AND ("video_session"."status" = ANY (ARRAY['ready'::"public"."video_session_status", 'active'::"public"."video_session_status"]))) AS "_videoSessionReady",
    "booking"."session_reference" AS "sessionReference"
   FROM (((((("public"."bookings" "booking"
     JOIN "public"."patient_profiles" "patient" ON (("patient"."id" = "booking"."patient_profile_id")))
     JOIN "public"."therapist_services" "service" ON (("service"."id" = "booking"."service_id")))
     LEFT JOIN "public"."session_payments" "payment" ON (("payment"."booking_id" = "booking"."id")))
     LEFT JOIN LATERAL ( SELECT "request"."status",
            "request"."proposed_starts_at",
            "request"."proposed_ends_at",
            "request"."proposed_timezone"
           FROM "public"."booking_reschedule_requests" "request"
          WHERE ("request"."booking_id" = "booking"."id")
          ORDER BY ("request"."status" = 'pending'::"text") DESC, "request"."created_at" DESC
         LIMIT 1) "reschedule" ON (true))
     LEFT JOIN LATERAL ( SELECT "decision"."decision",
            "decision"."requires_manual_review"
           FROM "public"."session_cancellation_decisions" "decision"
          WHERE ("decision"."booking_id" = "booking"."id")
          ORDER BY "decision"."created_at" DESC
         LIMIT 1) "cancellation" ON (true))
     LEFT JOIN "public"."video_sessions" "video_session" ON (("video_session"."booking_id" = "booking"."id")))
  WHERE "public"."is_current_therapist_profile"("booking"."therapist_profile_id");


ALTER VIEW "public"."therapist_session_read_model_v1" OWNER TO "postgres";


COMMENT ON VIEW "public"."therapist_session_read_model_v1" IS 'Versioned, security-invoker therapist session projection. Payment and fulfillment come from session_payments; attendance remains explicitly unavailable except for legacy no-show projections.';



