CREATE OR REPLACE VIEW "public"."therapist_video_session_summary_v" WITH ("security_invoker"='true') AS
 SELECT "vs"."id",
    "vs"."booking_id",
    "vs"."provider",
    "vs"."environment",
    "vs"."status",
    "vs"."scheduled_starts_at",
    "vs"."scheduled_ends_at",
    "vs"."actual_started_at",
    "vs"."actual_ended_at",
    "vs"."therapist_token_issued_at",
    "vs"."hard_ends_at",
    "vs"."therapist_first_joined_at",
    "vs"."therapist_last_joined_at",
    "vs"."therapist_last_left_at",
    "vs"."therapist_present",
    "vs"."last_synced_at"
   FROM ("public"."video_sessions" "vs"
     JOIN "public"."bookings" "b" ON (("b"."id" = "vs"."booking_id")))
  WHERE "public"."is_current_therapist_profile"("b"."therapist_profile_id");


ALTER VIEW "public"."therapist_video_session_summary_v" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."therapy_catalog_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "actor_profile_id" "uuid",
    "actor_role" "public"."user_role" DEFAULT 'admin'::"public"."user_role" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "previous_state" "jsonb",
    "next_state" "jsonb",
    "reason" "text",
    "correlation_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "therapy_catalog_events_entity_check" CHECK (("entity_type" = ANY (ARRAY['therapy'::"text", 'therapy_catalog_request'::"text", 'matching_theme'::"text", 'matching_interest'::"text"])))
);


ALTER TABLE "public"."therapy_catalog_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."therapy_catalog_events" IS 'Sanitized audit trail for administrative catalog and therapy request changes.';



CREATE TABLE IF NOT EXISTS "public"."therapy_catalog_request_materials" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "therapy_catalog_request_id" "uuid" NOT NULL,
    "file_name" "text" NOT NULL,
    "file_size_bytes" integer NOT NULL,
    "mime_type" "text" NOT NULL,
    "storage_object_path" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "therapy_catalog_request_materials_file_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "file_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "file_name")) <= 180))),
    CONSTRAINT "therapy_catalog_request_materials_file_size_check" CHECK ((("file_size_bytes" > 0) AND ("file_size_bytes" <= 10485760))),
    CONSTRAINT "therapy_catalog_request_materials_mime_check" CHECK (("mime_type" = ANY (ARRAY['application/pdf'::"text", 'application/msword'::"text", 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'::"text", 'image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"])))
);


ALTER TABLE "public"."therapy_catalog_request_materials" OWNER TO "postgres";


COMMENT ON TABLE "public"."therapy_catalog_request_materials" IS 'Private supporting materials for therapist-submitted therapy catalog requests.';



CREATE TABLE IF NOT EXISTS "public"."therapy_catalog_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "requester_profile_id" "uuid" NOT NULL,
    "requester_therapist_profile_id" "uuid",
    "informed_name" "text" NOT NULL,
    "description" "text",
    "justification" "text",
    "status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "related_therapy_id" "uuid",
    "decision" "text",
    "decided_by_profile_id" "uuid",
    "decided_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_request_id" "uuid",
    "submission_version" integer DEFAULT 1 NOT NULL,
    "submission" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "resubmitted_at" timestamp with time zone,
    CONSTRAINT "therapy_catalog_requests_name_length" CHECK ((("char_length"(TRIM(BOTH FROM "informed_name")) >= 2) AND ("char_length"(TRIM(BOTH FROM "informed_name")) <= 120))),
    CONSTRAINT "therapy_catalog_requests_status_check" CHECK (("status" = ANY (ARRAY['submitted'::"text", 'under_review'::"text", 'needs_information'::"text", 'approved'::"text", 'merged'::"text", 'rejected'::"text"]))),
    CONSTRAINT "therapy_catalog_requests_submission_version_check" CHECK (("submission_version" >= 1))
);


ALTER TABLE "public"."therapy_catalog_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."therapy_catalog_requests" IS 'Therapist-submitted requests for platform review of missing therapies. Approval does not publish free text automatically.';



