CREATE TABLE IF NOT EXISTS "public"."therapy_theme_weights" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "therapy_id" "uuid" NOT NULL,
    "theme_id" "uuid",
    "subtheme_id" "uuid",
    "weight" numeric(6,2) DEFAULT 1 NOT NULL,
    "reason" "text",
    "source" "public"."match_source" DEFAULT 'journey'::"public"."match_source" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "therapy_theme_weights_has_theme" CHECK ((("theme_id" IS NOT NULL) OR ("subtheme_id" IS NOT NULL))),
    CONSTRAINT "therapy_theme_weights_positive_weight" CHECK (("weight" > (0)::numeric))
);


ALTER TABLE "public"."therapy_theme_weights" OWNER TO "postgres";


COMMENT ON TABLE "public"."therapy_theme_weights" IS 'Deterministic matching weights. Keep RLS closed until Edge Function/view strategy is defined.';



