CREATE TABLE IF NOT EXISTS "public"."video_session_control_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "video_session_id" "uuid" NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "environment" "text" NOT NULL,
    "operation" "public"."video_session_control_operation" NOT NULL,
    "status" "public"."video_session_control_job_status" DEFAULT 'queued'::"public"."video_session_control_job_status" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "next_run_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "locked_until_at" timestamp with time zone,
    "last_error_code" "text",
    "last_error_message" "text",
    "completed_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "video_session_control_jobs_attempts_check" CHECK ((("attempts" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 10)))),
    CONSTRAINT "video_session_control_jobs_environment_check" CHECK (("environment" = ANY (ARRAY['development'::"text", 'production'::"text"]))),
    CONSTRAINT "video_session_control_jobs_idempotency_limited" CHECK ((("char_length"("idempotency_key") >= 12) AND ("char_length"("idempotency_key") <= 160)))
);


ALTER TABLE "public"."video_session_control_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."video_session_control_jobs" IS 'Jobs duraveis idempotentes para encerramento e reconciliacao de sessoes Zoom Video SDK.';



CREATE TABLE IF NOT EXISTS "public"."video_session_participations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
