CREATE POLICY "Active therapy themes are readable" ON "public"."therapy_themes" FOR SELECT USING (("is_active" = true));



CREATE POLICY "Admins can read admin audit events" ON "public"."admin_audit_events" FOR SELECT TO "authenticated" USING ("public"."is_current_admin"());



CREATE POLICY "Admins can read canonical therapies" ON "public"."therapies" FOR SELECT TO "authenticated" USING ("public"."is_current_admin"());



CREATE POLICY "Admins can read email action definitions" ON "public"."email_action_definitions" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("profiles"."role" = 'admin'::"public"."user_role")))));



